const e=[{id:1,name:"Day 1: ROS 2 Foundations & Core Middleware",icon:"Cpu",range:[1,8],lesson_count:8,lessons:[{id:"lesson_01",num_str:"01",title:"Linux Fundamentals for Robotics Engineers"},{id:"lesson_02",num_str:"02",title:"ROS 2 Overview & Environment Setup"},{id:"lesson_03",num_str:"03",title:"Turtlesim Simulation & Essential ROS 2 CLI Tools"},{id:"lesson_04",num_str:"04",title:"ROS 2 Workspace & Package Architecture Deep Dive"},{id:"lesson_05",num_str:"05",title:"Communication Mechanism I: Publishers, Subscribers & Quality of Service (QoS)"},{id:"lesson_06",num_str:"06",title:"Communication Mechanism II: Service Servers & Clients in Python"},{id:"lesson_07",num_str:"07",title:"Runtime Management & Python Launch Files"},{id:"lesson_08",num_str:"08",title:"Communication Mechanism III: Action Servers & Clients in Python"}]},{id:2,name:"Day 2: 3D Robot Modeling & Physics Simulation",icon:"Box",range:[9,12],lesson_count:4,lessons:[{id:"lesson_09",num_str:"09",title:"3D Robot Modeling with URDF & Xacro"},{id:"lesson_10",num_str:"10",title:"RViz2 Visualization & Kinematic TF Inspection"},{id:"lesson_11",num_str:"11",title:"Gazebo Physics Simulation & Sensor Plugins"},{id:"lesson_12",num_str:"12",title:"Building Custom Simulation Worlds in Gazebo"}]},{id:3,name:"Day 3: Autonomous SLAM & Nav2 Navigation",icon:"Compass",range:[13,15],lesson_count:3,lessons:[{id:"lesson_13",num_str:"13",title:"2D LiDAR SLAM Mapping with SLAM Toolbox"},{id:"lesson_14",num_str:"14",title:"Nav2 Stack Architecture, Path Planning & Parameter Tuning"},{id:"lesson_15",num_str:"15",title:"Autonomous Navigation Scripting with Nav2 Simple Commander"}]},{id:4,name:"Bonus: Advanced Masterclasses & Electives",icon:"Sparkles",range:[16,21],lesson_count:6,lessons:[{id:"lesson_16",num_str:"16",title:"Dynamic Parameters & YAML Configuration"},{id:"lesson_17",num_str:"17",title:"VS Code IDE Tooling & ROS 2 Logging Framework"},{id:"lesson_18",num_str:"18",title:"ROS 2 Interfaces & Custom Messages, Services & Actions (.msg, .srv, .action)"},{id:"lesson_19",num_str:"19",title:"Data Recording & Playback with ROS 2 Bags"},{id:"lesson_20",num_str:"20",title:"Complete ROS 2 Command-Line Interface (CLI) Mastery"},{id:"lesson_21",num_str:"21",title:"Behavior Trees, Recovery Behaviors & Lifecycle Management"}]}],n=JSON.parse(`[{"id":"lesson_01","num":1,"num_str":"01","title":"Linux Fundamentals for Robotics Engineers","slug":"linux_fundamentals_for_robotics","filename":"01_linux_fundamentals_for_robotics.md","module":"Day 1: ROS 2 Foundations & Core Middleware","module_id":1,"duration":"45-60 min","focus":"Essential Linux Terminal Commands, Filesystem Hierarchy, File Permissions & Process Management","snapshot":[["Filesystem Hierarchy","Navigate directories with pwd, cd, and create nested trees with mkdir -p."],["Executable Permission","Scripts must have the execute bit set with chmod +x script.sh before execution."],["Process Management","Monitor resource utilization with top and terminate jobs cleanly with kill <PID> or killall."],["Shell Aliases","Automate repetitive command paths by adding productivity aliases to ~/.bashrc."]],"html_content":"<h2 id=\\"1-overview-learning-objectives\\">1. Overview &amp; Learning Objectives</h2>\\n<p>Robotics software runs on Linux (Ubuntu LTS). Before diving into robotics middleware in Lesson 02, you must master the fundamental command-line workflows: navigating directories, inspecting files, granting executable permissions to scripts, and managing background processes.</p>\\n<p><img src=\\"assets/images/robotics_software_stack.svg\\" alt=\\"Robotics Software Stack\\" class=\\"lesson-image\\" loading=\\"lazy\\" /></p>\\n<p><div class=\\"learning-objectives-card\\">\\n  <div class=\\"learning-objectives-header\\">\\n    <div class=\\"objectives-icon-badge\\">\\n      <span style=\\"font-size: 1.15rem; line-height: 1;\\">🎯</span>\\n    </div>\\n    <div class=\\"objectives-title-group\\">\\n      <h3 class=\\"objectives-main-title\\">Learning Objectives &amp; Core Outcomes</h3>\\n      <span class=\\"objectives-subtitle\\">By the end of this lesson, you will be able to:</span>\\n    </div>\\n    <span class=\\"objectives-count-badge\\">6 CORE OUTCOMES</span>\\n  </div>\\n  <ul class=\\"learning-objectives-list\\">\\n    <li class=\\"learning-objective-item\\">\\n      <span class=\\"objective-num-badge\\">1</span>\\n      <span class=\\"objective-text\\"><strong>Navigate the Linux filesystem</strong> and understand where user files, system packages, and logs reside.</span>\\n    </li>\\n    <li class=\\"learning-objective-item\\">\\n      <span class=\\"objective-num-badge\\">2</span>\\n      <span class=\\"objective-text\\"><strong>Master daily command-line utilities</strong> (<code class=\\"inline-code\\">cd</code>, <code class=\\"inline-code\\">ls</code>, <code class=\\"inline-code\\">mkdir -p</code>, <code class=\\"inline-code\\">cp</code>, <code class=\\"inline-code\\">rm</code>, <code class=\\"inline-code\\">grep</code>) in an unbroken hands-on workflow.</span>\\n    </li>\\n    <li class=\\"learning-objective-item\\">\\n      <span class=\\"objective-num-badge\\">3</span>\\n      <span class=\\"objective-text\\"><strong>Understand file permission strings</strong> and use <code class=\\"inline-code\\">chmod +x</code> to make shell scripts directly executable.</span>\\n    </li>\\n    <li class=\\"learning-objective-item\\">\\n      <span class=\\"objective-num-badge\\">4</span>\\n      <span class=\\"objective-text\\"><strong>Inspect and cleanly terminate background processes</strong> (<code class=\\"inline-code\\">top</code>, <code class=\\"inline-code\\">kill</code>, <code class=\\"inline-code\\">killall</code>).</span>\\n    </li>\\n    <li class=\\"learning-objective-item\\">\\n      <span class=\\"objective-num-badge\\">5</span>\\n      <span class=\\"objective-text\\"><strong>Configure <code class=\\"inline-code\\">~/.bashrc</code></strong> with productivity shell shortcuts (<code class=\\"inline-code\\">alias</code>) and automated environment variables.</span>\\n    </li>\\n    <li class=\\"learning-objective-item\\">\\n      <span class=\\"objective-num-badge\\">6</span>\\n      <span class=\\"objective-text\\"><strong>Use Terminator</strong> to split and orchestrate multi-terminal workflows on a single screen.</span>\\n    </li>\\n  </ul>\\n</div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"2-the-linux-filesystem-what-you-need-to-know\\">2. The Linux Filesystem: What You Need to Know</h2>\\n<p>In Linux, all files, hardware devices, and network sockets are organized into a single unified tree originating at root (<code class=\\"inline-code\\">/</code>):</p>\\n<p><img src=\\"assets/images/linux_filesystem_tree.svg\\" alt=\\"Linux Filesystem Hierarchy\\" class=\\"lesson-image\\" loading=\\"lazy\\" /></p>\\n<h3 id=\\"key-directory-guide-for-roboticists\\">Key Directory Guide for Roboticists</h3>\\n<div class=\\"info-grid\\">\\n  <div class=\\"info-card\\">\\n    <h4>📁 <code>~/</code> (/home/student/)</h4>\\n    <p>Your personal user workspace. You have full read, write, and execute permissions here without requiring <code>sudo</code>.</p>\\n  </div>\\n  <div class=\\"info-card\\">\\n    <h4>⚙️ <code>/opt/</code></h4>\\n    <p>Where system-level robotics packages and pre-compiled software stacks reside (e.g. <code>/opt/ros/jazzy/</code>).</p>\\n  </div>\\n  <div class=\\"info-card\\">\\n    <h4>🌐 <code>/etc/</code></h4>\\n    <p>System-wide configuration files (networking, hosts, user groups, and APT package repositories).</p>\\n  </div>\\n  <div class=\\"info-card\\">\\n    <h4>📊 <code>/var/log/</code></h4>\\n    <p>System service logs, boot diagnostics, and runtime error traces.</p>\\n  </div>\\n  <div class=\\"info-card\\">\\n    <h4>🔌 <code>/dev/</code></h4>\\n    <p>Device nodes representing hardware peripherals (USB LiDARs <code>/dev/ttyUSB0</code> and microcontrollers).</p>\\n  </div>\\n</div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"3-hands-on-practical-building-a-robotics-workspace\\">3. Hands-On Practical: Building a Robotics Workspace</h2>\\n<p>Follow this continuous hands-on workflow in your terminal. Every single command builds directly upon the folders and files created in the preceding step, ensuring zero <em>&quot;file not found&quot;</em> errors.</p>\\n<h3 id=\\"30-step-0-how-to-open-the-terminal\\">3.0 Step 0: How to Open the Terminal</h3>\\n<p>Before executing any commands, you need an open terminal window:</p>\\n<ul>\\n<li><strong>In the Browser Desktop (noVNC / TigerVNC):</strong> Click the <strong>Terminal</strong> (or <strong>Terminator</strong>) icon on the desktop application panel, or press the universal shortcut <kbd>Ctrl</kbd> + <kbd>Alt</kbd> + <kbd>T</kbd>.</li>\\n<li><strong>In the Cloud VS Code IDE (Code Server):</strong> Press <kbd>Ctrl</kbd> + <kbd>\`</kbd> (Backtick) or select <strong>Terminal → New Terminal</strong> from the top menu bar.</li>\\n</ul>\\n<hr class=\\"divider\\">\\n<h3 id=\\"31-step-1-navigating-inspecting-your-workspace\\">3.1 Step 1: Navigating &amp; Inspecting Your Workspace</h3>\\n<div class=\\"cmd-card\\">\\n  <div class=\\"cmd-header\\">\\n    <div class=\\"cmd-header-left\\">\\n      <span class=\\"cmd-badge\\">pwd</span>\\n      <span class=\\"cmd-title\\">Print Current Working Directory</span>\\n    </div>\\n    <span class=\\"cmd-syntax\\">Syntax: <code>pwd</code></span>\\n  </div>\\n  <p class=\\"cmd-desc\\">Prints the absolute filesystem path of the directory you are currently working in. Useful to orient yourself before creating or modifying files.</p>\\n<p><div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\">pwd\\n# Output: /home/student\\n</code></pre>\\n</div>\\n</p>\\n</div>\\n<div class=\\"cmd-card\\">\\n  <div class=\\"cmd-header\\">\\n    <div class=\\"cmd-header-left\\">\\n      <span class=\\"cmd-badge\\">ls</span>\\n      <span class=\\"cmd-title\\">List Directory Contents (Simple to Advanced Flags)</span>\\n    </div>\\n    <span class=\\"cmd-syntax\\">Syntax: <code>ls</code> | <code>ls -l</code> | <code>ls -lh</code> | <code>ls -a</code> | <code>ls -lah</code></span>\\n  </div>\\n  <p class=\\"cmd-desc\\">Lists files and folders. Start with simple <code>ls</code>, then progressively unlock flags for deeper system inspection: <code>-l</code> (detailed list with permissions &amp; size), <code>-h</code> (human-readable units like KB/MB), and <code>-a</code> (unmask hidden dotfiles like <code>.bashrc</code>).</p>\\n<p><div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\"># Step 1: Start Simple — List visible files and folders:\\nls\\n# Output shows standard directories:\\n# Desktop  Documents  Downloads  Music  Pictures  Videos\\n\\n# Step 2: Add '-l' (Long Format) — Reveal permissions, owner, byte size, and timestamps:\\nls -l\\n# Output shows detailed table:\\n# drwxr-xr-x 2 student student 4096 Oct 19 12:00 Desktop\\n# drwxr-xr-x 2 student student 4096 Oct 19 12:00 Documents\\n\\n# Step 3: Add '-h' (Human-Readable) — Convert raw byte counts into KB, MB, GB:\\nls -lh\\n# Notice: '4096' is now formatted as '4.0K', making large sensor logs easy to read!\\n\\n# Step 4: Add '-a' (All / Hidden Files) — Reveal hidden configuration files (starting with '.'):\\nls -a\\n# Output unmasks hidden system files:\\n# .  ..  .bash_history  .bash_logout  .bashrc  .profile\\n\\n# Step 5: Master Combo 'ls -lah' — The ultimate robotics inspection command:\\nls -lah\\n# Displays complete details for ALL files including hidden configurations (.bashrc)\\n</code></pre>\\n</div>\\n</p>\\n</div>\\n<div class=\\"cmd-card\\">\\n  <div class=\\"cmd-header\\">\\n    <div class=\\"cmd-header-left\\">\\n      <span class=\\"cmd-badge\\">cd</span>\\n      <span class=\\"cmd-title\\">Change Working Directory (Navigation Mastery)</span>\\n    </div>\\n    <span class=\\"cmd-syntax\\">Syntax: <code>cd [folder]</code> | <code>cd ~</code> | <code>cd ..</code> | <code>cd -</code></span>\\n  </div>\\n  <p class=\\"cmd-desc\\">Changes your active shell directory location. Practice these practical navigation patterns in your VNC terminal relative to your user home directory (<code>/home/student</code>):</p>\\n<p><div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\"># Step 1: Check your starting directory (Terminal opens rooted in your user home):\\npwd\\n# Output: /home/student\\n# Notice your prompt shows '~', which represents /home/student.\\n\\n# Step 2: Navigate to a specific folder using an absolute path:\\ncd /var/log/apt\\n# Notice your prompt updates to: student@robot-vm:/var/log/apt$\\n\\n# Step 3: Move UP one level to the parent directory using '..':\\ncd ..\\n# Notice your prompt updates to: student@robot-vm:/var/log$\\n\\n# Step 4: Teleport straight back home from anywhere using '~':\\ncd ~\\n# Notice your prompt returns to: student@robot-vm:~$\\n\\n# Step 5: Jump back to your previous directory using '-':\\ncd -\\n# Output: /var/log\\n# Notice your prompt returns to: student@robot-vm:/var/log$\\n</code></pre>\\n</div>\\n</p>\\n</div>\\n<hr class=\\"divider\\">\\n<h3 id=\\"32-step-2-creating-a-structured-robotics-workspace-amp-files\\">3.2 Step 2: Creating a Structured Robotics Workspace &amp; Files</h3>\\n\\n<div class=\\"alert-callout alert-tip\\" style=\\"margin: 1.25rem 0;\\">\\n  <div class=\\"alert-icon\\">🏠</div>\\n  <div class=\\"alert-body\\">\\n    <strong>Important: Return to Your Home Directory:</strong><br>\\n    Notice that after the directory navigation exercises in Step 1, your terminal is currently sitting in <code class=\\"inline-code\\">/var/log</code>. System directories like <code class=\\"inline-code\\">/var/log</code> are protected and will deny file creation without root privileges.<br><br>\\n    Always ensure you return to your home directory before creating your project files:\\n    <div class=\\"code-container\\" data-language=\\"bash\\" style=\\"margin: 0.65rem 0 0.35rem 0;\\">\\n      <div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n      <pre><code class=\\"language-bash\\">cd ~\\n# Your prompt now displays '~' (student@robot-vm:~$), confirming you are safely back home!</code></pre>\\n    </div>\\n  </div>\\n</div>\\n\\n<p>Now let's build a clean robotics project folder <code class=\\"inline-code\\">~/robotics_lab</code> with dedicated subdirectories for configurations (<code class=\\"inline-code\\">config</code>), scripts (<code class=\\"inline-code\\">scripts</code>), and runtime logs (<code class=\\"inline-code\\">logs</code>):</p>\\n<div class=\\"cmd-card\\">\\n  <div class=\\"cmd-header\\">\\n    <div class=\\"cmd-header-left\\">\\n      <span class=\\"cmd-badge\\">mkdir / mkdir -p</span>\\n      <span class=\\"cmd-title\\">Create Directories (Single, Multiple &amp; Nested Trees)</span>\\n    </div>\\n    <span class=\\"cmd-syntax\\">Syntax: <code>mkdir &lt;dir&gt;</code> | <code>mkdir &lt;d1&gt; &lt;d2&gt;</code> | <code>mkdir -p &lt;parent/child&gt;</code></span>\\n  </div>\\n  <p class=\\"cmd-desc\\">Creates new directories. You can create a single directory, multiple directories in one command by separating names with spaces, or entire nested directory hierarchies using the <code>-p</code> (parents) flag.</p>\\n<p><div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\"># 1. Create a single practice directory:\\nmkdir my_robot_test\\n\\n# Verify it was created:\\nls\\n# Output shows: my_robot_test\\n\\n# 2. Create multiple directories at once in a single command:\\nmkdir sensors actuators telemetry\\n\\n# Verify all directories now exist:\\nls\\n# Output shows: actuators  my_robot_test  sensors  telemetry\\n\\n# Clean up temporary practice folders:\\nrm -rf my_robot_test sensors actuators telemetry\\n\\n# 3. Create nested directory hierarchies automatically using -p (parents flag):\\n# Without -p, Linux throws \\"No such file or directory\\" if parent folders do not exist.\\n# With -p, missing parents are generated automatically without errors:\\nmkdir -p ~/robotics_lab/config ~/robotics_lab/scripts ~/robotics_lab/logs\\n\\n# Verify the structured robotics lab directories:\\nls ~/robotics_lab\\n# Output:\\n# config  logs  scripts\\n# ✅ All 3 robotics folders are confirmed created!\\n</code></pre>\\n</div>\\n</p>\\n</div>\\n<div class=\\"cmd-card\\">\\n  <div class=\\"cmd-header\\">\\n    <div class=\\"cmd-header-left\\">\\n      <span class=\\"cmd-badge\\">echo &gt; &gt;&gt;</span>\\n      <span class=\\"cmd-title\\">Create &amp; Append Configuration Files</span>\\n    </div>\\n    <span class=\\"cmd-syntax\\">Syntax: <code>echo \\"text\\" &gt; file</code> (create/overwrite) | <code>echo \\"text\\" &gt;&gt; file</code> (append)</span>\\n  </div>\\n  <p class=\\"cmd-desc\\">Emits text strings. The <code>&gt;</code> redirection operator writes output to a file (creating it or overwriting existing content), while <code>&gt;&gt;</code> appends new lines to the end of an existing file.</p>\\n<p><div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\"># Phase 1: Initial file write with '>'\\necho &quot;max_linear_velocity: 0.5&quot; &gt; ~/robotics_lab/config/robot_params.yaml\\ncat ~/robotics_lab/config/robot_params.yaml\\n# Output:\\n# max_linear_velocity: 0.5\\n\\n# Phase 2: THE OVERWRITE TRAP (Watch what happens if you use '>' again on the same file!)\\n# DANGER: Single '>' truncates (wipes out) all existing content before writing:\\necho &quot;robot_model: nexus_amr&quot; &gt; ~/robotics_lab/config/robot_params.yaml\\ncat ~/robotics_lab/config/robot_params.yaml\\n# Output:\\n# robot_model: nexus_amr\\n# Notice: \\"max_linear_velocity: 0.5\\" DISAPPEARED! Single '>' completely erased the previous line!\\n\\n# Phase 3: The Safe Append Solution ('>>')\\n# Safely append subsequent lines with '>>' without deleting what is already in the file:\\necho &quot;max_linear_velocity: 0.5&quot; &gt;&gt; ~/robotics_lab/config/robot_params.yaml\\necho &quot;lidar_topic: /scan&quot; &gt;&gt; ~/robotics_lab/config/robot_params.yaml\\ncat ~/robotics_lab/config/robot_params.yaml\\n# Output:\\n# robot_model: nexus_amr\\n# max_linear_velocity: 0.5\\n# lidar_topic: /scan\\n# Notice: All 3 configuration lines are now safely preserved!\\n</code></pre>\\n</div>\\n</p>\\n</div>\\n<div class=\\"cmd-card\\">\\n  <div class=\\"cmd-header\\">\\n    <div class=\\"cmd-header-left\\">\\n      <span class=\\"cmd-badge\\">touch</span>\\n      <span class=\\"cmd-title\\">Create Files (Create, Populate &amp; Inspect)</span>\\n    </div>\\n    <span class=\\"cmd-syntax\\">Syntax: <code>touch &lt;file_path&gt;</code></span>\\n  </div>\\n  <p class=\\"cmd-desc\\">Creates a new file on disk. Practice a clean verification workflow: create an empty file with <code>touch</code>, populate it with data, and immediately inspect its contents with <code>cat</code>.</p>\\n<p><div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\"># Step 1: Create an empty file with touch:\\ntouch ~/robotics_lab/logs/boot_temp.log\\n\\n# Step 2: Populate the file with data:\\necho &quot;boot_status: ready&quot; &gt; ~/robotics_lab/logs/boot_temp.log\\n\\n# Step 3: See the populated file content using cat:\\ncat ~/robotics_lab/logs/boot_temp.log\\n# Expected Output:\\n# boot_status: ready\\n\\n# Step 4: Also create our diagnostic script placeholder:\\ntouch ~/robotics_lab/scripts/sensor_diagnostics.sh\\n</code></pre>\\n</div>\\n</p>\\n</div>\\n<div class=\\"cmd-card\\">\\n  <div class=\\"cmd-header\\">\\n    <div class=\\"cmd-header-left\\">\\n      <span class=\\"cmd-badge\\">cp / cp -r</span>\\n      <span class=\\"cmd-title\\">Copy Files &amp; Recursive Directories</span>\\n    </div>\\n    <span class=\\"cmd-syntax\\">Syntax: <code>cp [options] &lt;source&gt; &lt;destination&gt;</code></span>\\n  </div>\\n  <p class=\\"cmd-desc\\">Copies files or folders to a target location. Use flag <code>-r</code> (recursive) to copy an entire directory and all nested files within it.</p>\\n<p><div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\"># 1. Create a safety backup copy of the robot config file:\\ncp ~/robotics_lab/config/robot_params.yaml ~/robotics_lab/config/robot_params_backup.yaml\\n\\n# 2. Copy the entire scripts directory recursively (-r):\\ncp -r ~/robotics_lab/scripts ~/robotics_lab/scripts_backup\\n\\n# Verification Check: Verify both backup copies exist on disk:\\nls -l ~/robotics_lab/config/\\n# Expected Output:\\n# -rw-r--r-- 1 student student 72 Oct 19 13:18 robot_params.yaml\\n# -rw-r--r-- 1 student student 72 Oct 19 13:20 robot_params_backup.yaml\\n\\nls -la ~/robotics_lab/scripts_backup/\\n# Expected Output:\\n# -rw-r--r-- 1 student student 0 Oct 19 13:18 sensor_diagnostics.sh\\n# (Both the backup file and recursive directory copy are verified on disk!)\\n</code></pre>\\n</div>\\n</p>\\n</div>\\n<div class=\\"cmd-card\\">\\n  <div class=\\"cmd-header\\">\\n    <div class=\\"cmd-header-left\\">\\n      <span class=\\"cmd-badge\\">mv</span>\\n      <span class=\\"cmd-title\\">Move or Rename Files &amp; Directories</span>\\n    </div>\\n    <span class=\\"cmd-syntax\\">Syntax: <code>mv &lt;source&gt; &lt;destination&gt;</code></span>\\n  </div>\\n  <p class=\\"cmd-desc\\">Moves files or folders to a new directory path, or renames them in place when the source and destination reside within the same parent folder.</p>\\n<p><div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\"># 1. Move a file to another directory:\\nmv ~/robotics_lab/config/robot_params_backup.yaml ~/robotics_lab/logs/\\n\\n# 2. Rename a file in place (within the same directory):\\nmv ~/robotics_lab/logs/robot_params_backup.yaml ~/robotics_lab/logs/archived_params.yaml\\n\\n# 3. Interactive Safe Move (-i) — prompts before overwriting an existing file:\\nmv -i ~/robotics_lab/config/robot_params.yaml ~/robotics_lab/logs/archived_params.yaml\\n\\n# 4. Verification Check: Confirm the file relocated cleanly into logs:\\nls -l ~/robotics_lab/logs/\\n# Expected Output:\\n# -rw-r--r-- 1 student student 72 Oct 19 13:20 archived_params.yaml\\n# (File was relocated cleanly into the logs archive!)\\n</code></pre>\\n</div>\\n</p>\\n</div>\\n<div class=\\"cmd-card\\">\\n  <div class=\\"cmd-header\\">\\n    <div class=\\"cmd-header-left\\">\\n      <span class=\\"cmd-badge\\">rm / rm -rf</span>\\n      <span class=\\"cmd-title\\">Safe File &amp; Directory Cleanup</span>\\n    </div>\\n    <span class=\\"cmd-syntax\\">Syntax: <code>rm [options] &lt;target_path&gt;</code></span>\\n  </div>\\n  <p class=\\"cmd-desc\\">Deletes files or directories permanently. Flag <code>-r</code> enables recursive directory deletion, and <code>-f</code> (force) suppresses confirmation prompts and ignores non-existent files.</p>\\n<p><div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\"># 1. Remove the temporary test log file:\\nrm ~/robotics_lab/logs/boot_temp.log\\n\\n# 2. Recursively force delete the scripts_backup directory:\\nrm -rf ~/robotics_lab/scripts_backup\\n\\n# Verification Check: Confirm clean workspace structure using simple ls:\\nls ~/robotics_lab/\\n# Expected Output:\\n# config  logs  scripts\\n# (Temporary files and backup directories are verified removed from disk!)\\n</code></pre>\\n</div>\\n</p>\\n</div>\\n<hr class=\\"divider\\">\\n<h3 id=\\"33-step-3-inspecting-reading-amp-searching-files\\">3.3 Step 3: Inspecting, Reading &amp; Searching Files</h3>\\n<div class=\\"cmd-card\\">\\n  <div class=\\"cmd-header\\">\\n    <div class=\\"cmd-header-left\\">\\n      <span class=\\"cmd-badge\\">cat</span>\\n      <span class=\\"cmd-title\\">Display Full File Contents</span>\\n    </div>\\n    <span class=\\"cmd-syntax\\">Syntax: <code>cat &lt;file_path&gt;</code></span>\\n  </div>\\n  <p class=\\"cmd-desc\\">Concatenates and streams the entire contents of a file directly to standard output. Best suited for short configuration files and scripts.</p>\\n<p><div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\">cat ~/robotics_lab/config/robot_params.yaml\\n\\n# Output:\\n# robot_model: nexus_amr\\n# max_linear_velocity: 0.5\\n# lidar_topic: /scan\\n</code></pre>\\n</div>\\n</p>\\n</div>\\n<div class=\\"cmd-card\\">\\n  <div class=\\"cmd-header\\">\\n    <div class=\\"cmd-header-left\\">\\n      <span class=\\"cmd-badge\\">head / tail</span>\\n      <span class=\\"cmd-title\\">Inspect Top or Bottom Lines of Files</span>\\n    </div>\\n    <span class=\\"cmd-syntax\\">Syntax: <code>head -n &lt;N&gt; &lt;file&gt;</code> | <code>tail -f &lt;file&gt;</code></span>\\n  </div>\\n  <p class=\\"cmd-desc\\"><code>head</code> prints the first N lines of a file; <code>tail</code> prints the last N lines. Flag <code>-f</code> with <code>tail</code> follows live logs in real-time as background daemons write new data.</p>\\n<p><div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\"># View the first 5 lines of network hosts\\nhead -n 5 /etc/hosts\\n\\n# Output displays: 127.0.0.1 localhost, ::1 ip6-localhost...\\n</code></pre>\\n</div>\\n</p>\\n</div>\\n<div class=\\"cmd-card\\">\\n  <div class=\\"cmd-header\\">\\n    <div class=\\"cmd-header-left\\">\\n      <span class=\\"cmd-badge\\">grep</span>\\n      <span class=\\"cmd-title\\">Search Text Patterns (Simple to Advanced Flags)</span>\\n    </div>\\n    <span class=\\"cmd-syntax\\">Syntax: <code>grep \\"&lt;pattern&gt;\\" &lt;file&gt;</code> | <code>grep -i</code> | <code>grep -n</code> | <code>grep -rn</code></span>\\n  </div>\\n  <p class=\\"cmd-desc\\">Searches text lines matching a query. Start simple on a single file, then progressively unlock flags: <code>-i</code> (ignore case), <code>-n</code> (line numbers), and <code>-rn</code> (recursively search entire directory tree).</p>\\n<p><div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\"># Step 1: Simple search in a single file:\\ngrep &quot;nexus&quot; ~/robotics_lab/config/robot_params.yaml\\n# Output:\\n# robot_model: nexus_amr\\n\\n# Step 2: Case-insensitive search using -i (matches NEXUS, Nexus, nexus):\\ngrep -i &quot;NEXUS&quot; ~/robotics_lab/config/robot_params.yaml\\n# Output:\\n# robot_model: nexus_amr\\n\\n# Step 3: Display matching line number using -n:\\ngrep -n &quot;robot_model&quot; ~/robotics_lab/config/robot_params.yaml\\n# Output:\\n# 1:robot_model: nexus_amr\\n\\n# Step 4: Search recursively across an entire directory tree using -rn:\\ngrep -rn &quot;nexus&quot; ~/robotics_lab/\\n# Output:\\n# /home/student/robotics_lab/config/robot_params.yaml:1:robot_model: nexus_amr\\n# /home/student/robotics_lab/logs/archived_params.yaml:1:robot_model: nexus_amr\\n</code></pre>\\n</div>\\n</p>\\n</div>\\n<div class=\\"cmd-card\\">\\n  <div class=\\"cmd-header\\">\\n    <div class=\\"cmd-header-left\\">\\n      <span class=\\"cmd-badge\\">| (Pipe)</span>\\n      <span class=\\"cmd-title\\">Piping Output: Filter &amp; Chain Commands (cat | grep)</span>\\n    </div>\\n    <span class=\\"cmd-syntax\\">Syntax: <code>command_1 | command_2</code></span>\\n  </div>\\n  <p class=\\"cmd-desc\\">The <strong>Pipe (<code>|</code>)</strong> operator takes the Standard Output (<code>stdout</code>) of the command on the left and redirects it directly into the Standard Input (<code>stdin</code>) of the command on the right. In robotics, combining <code>cat</code> with <code>grep</code> is an indispensable technique for instantly filtering configuration files, system parameters, and diagnostic logs without scrolling through hundreds of lines.</p>\\n<p><div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\"># 1. Pipe file contents from &#x27;cat&#x27; into &#x27;grep&#x27; to filter specific robot parameters:\\ncat ~/robotics_lab/config/robot_params.yaml | grep &quot;velocity&quot;\\n# Output: max_linear_velocity: 0.5\\n\\n# 2. Inspect operating system release information by piping cat into grep:\\ncat /etc/os-release | grep &quot;PRETTY_NAME&quot;\\n# Output: PRETTY_NAME=&quot;Ubuntu 24.04 LTS&quot;\\n\\n# 3. Practical Robotics Real-World Examples:\\n# - Filter live ROS 2 topic streams:  ros2 topic list | grep cmd_vel\\n# - Filter system error logs:         cat /var/log/syslog | grep -i error\\n</code></pre>\\n</div>\\n</p>\\n</div>\\n<div class=\\"cmd-card\\">\\n  <div class=\\"cmd-header\\">\\n    <div class=\\"cmd-header-left\\">\\n      <span class=\\"cmd-badge\\">&amp;&amp; / ; / ||</span>\\n      <span class=\\"cmd-title\\">Executing Multiple Commands in a Single Line</span>\\n    </div>\\n    <span class=\\"cmd-syntax\\">Syntax: <code>cmd1 &amp;&amp; cmd2</code> | <code>cmd1 ; cmd2</code> | <code>cmd1 || cmd2</code></span>\\n  </div>\\n  <p class=\\"cmd-desc\\">In Linux, you can chain multiple commands onto a single command line using three operators depending on whether you want subsequent commands to depend on previous success, run unconditionally, or act as an error fallback.</p>\\n<p><div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\"># 1. The &#x27;&amp;&amp;&#x27; Operator (Logical AND - Run next ONLY IF previous command succeeded):\\n# If the first command fails, execution halts immediately:\\ncd ~/robotics_lab &amp;&amp; ls -la\\n\\n# 2. The &#x27;;&#x27; Semicolon (Sequential Execution - Run regardless of success or failure):\\n# Commands run one after another in order, even if an earlier command threw an error:\\necho &quot;Starting pre-flight check...&quot; ; ls -l ~/robotics_lab ; echo &quot;Pre-flight check complete.&quot;\\n\\n# 3. The &#x27;||&#x27; Operator (Logical OR - Run next ONLY IF previous command failed):\\n# Perfect for error alerts and fallback defaults:\\ngrep &quot;camera_topic&quot; ~/robotics_lab/config/robot_params.yaml || echo &quot;⚠️ Warning: Camera parameter not found in config!&quot;\\n</code></pre>\\n</div>\\n</p>\\n</div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"4-file-permissions-making-shell-scripts-executable\\">4. File Permissions: Making Shell Scripts Executable</h2>\\n<p>When you create a script in Linux, it is created without execution permissions by default. Attempting to run it directly triggers:</p>\\n<p><div class=\\"code-container\\" data-language=\\"text\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">text</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-text\\">bash: ./sensor_diagnostics.sh: Permission denied\\n</code></pre>\\n</div>\\n</p>\\n<h3 id=\\"41-understanding-the-permission-string\\">4.1 Understanding the Permission String</h3>\\n<p>Running <code class=\\"inline-code\\">ls -l</code> outputs a 10-character permission string:</p>\\n<p><div class=\\"code-container\\" data-language=\\"text\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">text</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-text\\">-rwxr-xr-x 1 student student 1420 Oct 13 10:00 sensor_diagnostics.sh\\n │├──┘├──┘└── Others permissions (Read, Execute)\\n ││   └── Group permissions (Read, Execute)\\n │└── User (Owner) permissions: Read (r), Write (w), Execute (x)\\n └── File type: &#x27;-&#x27; = regular file, &#x27;d&#x27; = directory\\n</code></pre>\\n</div>\\n</p>\\n<p>Each triplet represents:</p>\\n<ul>\\n<li><strong><code class=\\"inline-code\\">r</code> (Read = 4):</strong> View file contents.</li>\\n<li><strong><code class=\\"inline-code\\">w</code> (Write = 2):</strong> Modify or delete file.</li>\\n<li><strong><code class=\\"inline-code\\">x</code> (Execute = 1):</strong> Execute the file as a program.</li>\\n</ul>\\n<div id=\\"interactive-permission-calculator-root\\"></div>\\n<h3 id=\\"42-hands-on-exercise-creating-amp-running-an-executable-script\\">4.2 Hands-On Exercise: Creating &amp; Running an Executable Script</h3>\\n<div class=\\"cmd-card\\">\\n  <div class=\\"cmd-header\\">\\n    <div class=\\"cmd-header-left\\">\\n      <span class=\\"cmd-badge\\">chmod +x</span>\\n      <span class=\\"cmd-title\\">Grant Executable Permission to Shell Script</span>\\n    </div>\\n    <span class=\\"cmd-syntax\\">Syntax: <code>chmod +x &lt;script_file&gt;</code> | <code>chmod 755 &lt;script_file&gt;</code></span>\\n  </div>\\n  <p class=\\"cmd-desc\\">Modifies file access permissions. Flag <code>+x</code> grants execution rights so the operating system can run the script directly as an independent program.</p>\\n<p><div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\"># Step 1: Navigate into the scripts folder where sensor_diagnostics.sh resides\\ncd ~/robotics_lab/scripts\\n\\n# Step 2: Add robot sensor diagnostic logic to sensor_diagnostics.sh\\ncat &lt;&lt; &#x27;EOF&#x27; &gt; sensor_diagnostics.sh\\n#!/bin/bash\\necho &quot;==========================================&quot;\\necho &quot;      ROBOT SENSOR PRE-FLIGHT CHECK       &quot;\\necho &quot;==========================================&quot;\\necho &quot;Timestamp:    $(date)&quot;\\necho &quot;Kernel:       $(uname -r)&quot;\\necho &quot;Architecture: $(uname -m)&quot;\\necho &quot;Free Memory:  $(free -h | awk &#x27;/^Mem:/ {print $4}&#x27;)&quot;\\necho &quot;All robot sensor subsystems operating normally!&quot;\\necho &quot;==========================================&quot;\\nEOF\\n\\n# Step 3: Try running the script directly with &#x27;./&#x27; (triggers Permission denied)\\n./sensor_diagnostics.sh\\n# Output: bash: ./sensor_diagnostics.sh: Permission denied\\n\\n# Step 4: Grant executable permission (+x) to the script\\nchmod +x sensor_diagnostics.sh\\n\\n# Step 5: Run the script successfully!\\n./sensor_diagnostics.sh\\n</code></pre>\\n</div>\\n</p>\\n</div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"5-process-management-amp-background-jobs\\">5. Process Management &amp; Background Jobs</h2>\\n<p>Robotics systems run multiple programs simultaneously (LiDAR driver, SLAM, motor controllers). You must know how to inspect resource usage, start background jobs, and terminate stalled processes.</p>\\n<h3 id=\\"51-monitoring-running-processes\\">5.1 Monitoring Running Processes</h3>\\n<div class=\\"cmd-card\\">\\n  <div class=\\"cmd-header\\">\\n    <div class=\\"cmd-header-left\\">\\n      <span class=\\"cmd-badge\\">sleep &amp; / ps aux</span>\\n      <span class=\\"cmd-title\\">Launch Background Jobs &amp; Inspect Processes</span>\\n    </div>\\n    <span class=\\"cmd-syntax\\">Syntax: <code>&lt;cmd&gt; &amp;</code> | <code>ps aux | grep &lt;name&gt;</code></span>\\n  </div>\\n  <p class=\\"cmd-desc\\">Appending <code>&amp;</code> to any command runs it as a background job, freeing your terminal immediately. <code>ps aux</code> lists all running processes with user, PID, CPU, memory, and command path.</p>\\n<p><div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\"># 1. Start a simulated background telemetry logger (sleeps for 300 seconds):\\nsleep 300 &amp;\\n# Expected Output:\\n# [1] 42109\\n# Note: '[1]' is the shell job number, '42109' is the unique OS Process ID (PID).\\n\\n# 2. Filter active processes to verify it is actively running in memory:\\nps aux | grep sleep\\n# Expected Output:\\n# student  42109  0.0  0.0   5480   920 pts/1    S    12:05   0:00 sleep 300\\n</code></pre>\\n</div>\\n</p>\\n</div>\\n<div class=\\"cmd-card\\">\\n  <div class=\\"cmd-header\\">\\n    <div class=\\"cmd-header-left\\">\\n      <span class=\\"cmd-badge\\">top</span>\\n      <span class=\\"cmd-title\\">Interactive System Resource Task Manager</span>\\n    </div>\\n    <span class=\\"cmd-syntax\\">Syntax: <code>top</code> (press 'q' to exit)</span>\\n  </div>\\n  <p class=\\"cmd-desc\\">Interactive real-time process viewer displaying total CPU usage, memory utilization, and active process states sorted by resource consumption.</p>\\n<p><div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\">top\\n# Displays live PID table, memory load, and CPU %. Press &#x27;q&#x27; to exit.\\n</code></pre>\\n</div>\\n</p>\\n</div>\\n<h3 id=\\"52-terminating-processes-cleanly\\">5.2 Terminating Processes Cleanly</h3>\\n<div class=\\"cmd-card\\">\\n  <div class=\\"cmd-header\\">\\n    <div class=\\"cmd-header-left\\">\\n      <span class=\\"cmd-badge\\">kill / killall / pkill</span>\\n      <span class=\\"cmd-title\\">Terminate Background Processes Cleanly</span>\\n    </div>\\n    <span class=\\"cmd-syntax\\">Syntax: <code>killall &lt;name&gt;</code> | <code>pkill &lt;name&gt;</code> | <code>kill &lt;PID&gt;</code> | <code>kill -9 &lt;PID&gt;</code></span>\\n  </div>\\n  <p class=\\"cmd-desc\\">Sends POSIX termination signals. <code>killall</code> and <code>pkill</code> terminate all processes matching a program name; standard <code>kill &lt;PID&gt;</code> sends SIGTERM (graceful shutdown); <code>kill -9 &lt;PID&gt;</code> sends SIGKILL (forced instant halt).</p>\\n<p><div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\"># 1. Terminate all running sleep test processes cleanly by name:\\nkillall sleep\\n# (Alternatively, 'kill 42109' terminates by unique PID)\\n\\n# 2. Verify the process is confirmed terminated (only the grep search command appears):\\nps aux | grep sleep\\n# Expected Output:\\n# [1]+  Terminated              sleep 300\\n# student  42180  0.0  0.0   6432   720 pts/1    S+   12:06   0:00 grep --color=auto sleep\\n# (PID 42109 is confirmed GONE from the operating system!)\\n</code></pre>\\n</div>\\n</p>\\n</div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"6-shell-automation-with-bashrc\\">6. Shell Automation with <code class=\\"inline-code\\">~/.bashrc</code></h2>\\n<p>Every time you launch a new terminal, Linux reads and executes <code class=\\"inline-code\\">~/.bashrc</code>. You can define custom shortcut aliases to streamline daily terminal operations:</p>\\n<div class=\\"cmd-card\\">\\n  <div class=\\"cmd-header\\">\\n    <div class=\\"cmd-header-left\\">\\n      <span class=\\"cmd-badge\\">alias / source</span>\\n      <span class=\\"cmd-title\\">Shell Shortcuts &amp; Automated Sourcing</span>\\n    </div>\\n    <span class=\\"cmd-syntax\\">Syntax: <code>alias &lt;key&gt;='&lt;command&gt;'</code> | <code>source &lt;file&gt;</code></span>\\n  </div>\\n  <p class=\\"cmd-desc\\">Defines persistent shortcuts in <code>~/.bashrc</code>. The <code>source</code> command reloads the configuration in the active terminal immediately without restarting the shell.</p>\\n<p><div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\"># 1. Append productivity shortcuts to ~/.bashrc:\\necho 'alias ll=\\"ls -lah\\"' >> ~/.bashrc\\necho 'alias lab=\\"cd ~/robotics_lab\\"' >> ~/.bashrc\\n\\n# 2. Try running the shortcut BEFORE reloading configuration:\\n# lab\\n# Expected Output: bash: lab: command not found\\n# (Notice: Changes written to ~/.bashrc on disk are NOT active in running terminals until sourced!)\\n\\n# 3. Reload bash configuration in current active terminal:\\nsource ~/.bashrc\\n\\n# 4. Now test your custom shortcut:\\nlab\\n# Notice your prompt updates: student@robot-vm:~/robotics_lab$\\n# ✅ Instantly jumped to your robotics laboratory! This is why ROS 2 requires sourcing setup.bash.\\n</code></pre>\\n</div>\\n</p>\\n</div>\\n<div class=\\"alert-callout alert-note\\"><div class=\\"alert-icon\\"></div><div class=\\"alert-body\\">In <strong>Lesson 02</strong>, we will add your ROS 2 underlay paths (<code class=\\"inline-code\\">/opt/ros/jazzy/setup.bash</code>) to this file so every terminal is automatically primed for robotics programming!</div></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"7-multi-pane-terminal-workflows-terminator\\">7. Multi-Pane Terminal Workflows (Terminator)</h2>\\n<p>Robotics workflows often require 3–4 terminal windows running concurrently (simulation, sensors, visualization, commands). <strong>Terminator</strong> allows splitting your screen into a clean multi-terminal grid:</p>\\n<p><img src=\\"assets/images/terminator_layout.svg\\" alt=\\"Terminator Multi-Pane Layout\\" class=\\"lesson-image\\" loading=\\"lazy\\" /></p>\\n<div class=\\"table-responsive\\"><table>\\n<thead>\\n<tr>\\n<th>Shortcut</th>\\n<th>Function</th>\\n<th>Purpose in Robotics</th>\\n</tr>\\n</thead>\\n<tbody>\\n<tr>\\n<td><code class=\\"inline-code\\">Ctrl + Shift + O</code></td>\\n<td><strong>Split Horizontally</strong></td>\\n<td>Creates top and bottom terminal panes</td>\\n</tr>\\n<tr>\\n<td><code class=\\"inline-code\\">Ctrl + Shift + E</code></td>\\n<td><strong>Split Vertically</strong></td>\\n<td>Creates left and right terminal panes</td>\\n</tr>\\n<tr>\\n<td><code class=\\"inline-code\\">Alt + Arrow Keys</code></td>\\n<td><strong>Navigate Active Panes</strong></td>\\n<td>Switch focus quickly without touching mouse</td>\\n</tr>\\n<tr>\\n<td><code class=\\"inline-code\\">Ctrl + Shift + X</code></td>\\n<td><strong>Maximize / Restore Active Pane</strong></td>\\n<td>Zoom in on a busy node log</td>\\n</tr>\\n<tr>\\n<td><code class=\\"inline-code\\">Ctrl + Shift + W</code></td>\\n<td><strong>Close Current Pane</strong></td>\\n<td>Safely exit an active terminal session</td>\\n</tr>\\n<tr>\\n<td><code class=\\"inline-code\\">Alt + A</code></td>\\n<td><strong>Broadcast Keystrokes to All Panes</strong></td>\\n<td>Send identical commands across multiple panes</td>\\n</tr>\\n<tr>\\n<td><code class=\\"inline-code\\">Alt + O</code></td>\\n<td><strong>Disable Broadcast Mode</strong></td>\\n<td>Return to independent pane control</td>\\n</tr>\\n</tbody>\\n</table></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"8-pro-tips-amp-hardware-reference\\">8. 💡 Pro-Tips &amp; Hardware Reference</h2>\\n<div class=\\"alert-callout alert-tip\\"><div class=\\"alert-icon\\"></div><div class=\\"alert-body\\">If plugging in an external USB microcontroller (ESP32, Arduino) or LiDAR produces <code class=\\"inline-code\\">Permission denied: /dev/ttyUSB0</code>, grant your user serial permissions once:</p><br><p><div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\">sudo usermod -a -G dialout $USER\\n</code></pre>\\n</div>\\n</p><br><p>Then log out and log back in (or run <code class=\\"inline-code\\">newgrp dialout</code>).</div></div>\\n<div class=\\"alert-callout alert-tip\\"><div class=\\"alert-icon\\"></div><div class=\\"alert-body\\">Press <code class=\\"inline-code\\">Ctrl + R</code> in any terminal and start typing a previous command (e.g. <code class=\\"inline-code\\">sensor_diagnostics</code>) to search and auto-complete your command history without retyping.</div></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"8-hands-on-student-challenge\\">8. Hands-on Student Challenge: Autonomous Mobile Robot Workspace Initializer &amp; Diagnostics</h2>\\n<p>Before launching robot software packages or compiling nodes, robotics engineers automate workspace provisioning, directory hierarchy structuring, and hardware sensor configuration manifests using shell scripts.</p>\\n\\n<div class=\\"alert alert-tip\\">\\n  <div class=\\"alert-title\\">🎯 Mission Targets</div>\\n  <ol>\\n    <li><strong>TODO 1 (Workspace Directories):</strong> Create the required robotics workspace directory tree (<code class=\\"inline-code\\">~/nexus_ws/src</code>, <code class=\\"inline-code\\">~/nexus_ws/logs</code>, <code class=\\"inline-code\\">~/nexus_ws/config</code>) using <code class=\\"inline-code\\">mkdir -p</code>.</li>\\n  </ol>\\n</div>\\n\\n<h3 id=\\"81-starter-template\\">8.1 Starter Template: <code class=\\"inline-code\\">m01_l01_task_env_setup.sh</code></h3>\\n<p>Copy the starter template from the reference workspace into your active student workspace:</p>\\n<div class=\\"code-container\\" data-language=\\"bash\\">\\n  <div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n  <pre><code class=\\"language-bash\\">mkdir -p ~/ros2_ws/scripts\\ncp ~/ros2_ws_reference/scripts/m01_l01_task_env_setup.sh ~/ros2_ws/scripts/\\nchmod +x ~/ros2_ws/scripts/m01_l01_task_env_setup.sh</code></pre>\\n</div>\\n<p>Open the copied file in your editor and complete the marked <code class=\\"inline-code\\">TODO</code> targets:</p>\\n\\n<div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\">#!/usr/bin/env bash\\n# ==============================================================================\\n# Nexus AMR Learning Hub - Level 1: Module 1 / Lesson 01 Task\\n# Script:  m01_l01_task_env_setup.sh\\n# Purpose: Autonomous Mobile Robot Workspace Initializer &amp; Diagnostic Check\\n# ==============================================================================\\n#\\n# MISSION TARGETS:\\n# ----------------\\n# 1. TODO 1: Create robotics workspace directory tree (/home/chaitu/nexus_ws/{src,logs,config}).\\n# ==============================================================================\\n\\nset -e\\n\\n# Terminal color codes\\nGREEN=&#x27;\\u001b[0;32m&#x27;\\nRED=&#x27;\\u001b[0;31m&#x27;\\nYELLOW=&#x27;\\u001b[1;33m&#x27;\\nBLUE=&#x27;\\u001b[0;34m&#x27;\\nNC=&#x27;\\u001b[0m&#x27; # No Color\\n\\necho -e \\"======================================================\\"\\necho -e \\"  Nexus AMR Workspace Initializer &amp; Diagnostics      \\"\\necho -e \\"======================================================\\"\\n\\n# Target workspace paths\\nWS_DIR=\\"/home/chaitu/nexus_ws\\"\\n\\n# ==============================================================================\\n# TODO 1: Create the workspace directories:\\n#         - \\"/src\\"\\n#         - \\"/logs\\"\\n#         - \\"/config\\"\\n# - Hint: Use \`mkdir -p\` with directory paths to ensure parent directories are created.\\n# ==============================================================================\\necho -e \\"\\n[Step 1/1: Creating Robotics Workspace Directory Tree]\\"\\n# ---&gt; YOUR CODE HERE &lt;---\\n\\necho -e \\"\\n======================================================\\"\\necho -e \\"  Workspace Setup Complete: READY FOR ROBOTICS!        \\"\\necho -e \\"======================================================\\"\\n</code></pre>\\n</div>\\n\\n<h3 id=\\"82-verification-steps\\">8.2 Verification Steps &amp; Expected Terminal Output</h3>\\n<p>Grant execute permissions and run the script:</p>\\n<div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\">mkdir -p ~/ros2_ws/scripts\\ncp ~/ros2_ws_reference/scripts/m01_l01_task_env_setup.sh ~/ros2_ws/scripts/\\nchmod +x ~/ros2_ws/scripts/m01_l01_task_env_setup.sh\\n~/ros2_ws/scripts/m01_l01_task_env_setup.sh</code></pre>\\n</div>\\n\\n<p><em>Expected Terminal Output:</em></p>\\n<div class=\\"code-container\\" data-language=\\"text\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">text</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-text\\">======================================================\\n  Nexus AMR Workspace Initializer &amp; Diagnostics      \\n======================================================\\n\\n[Step 1/1: Creating Robotics Workspace Directory Tree]\\n[PASS] Workspace directory structure established at: /home/student/nexus_ws\\n\\n======================================================\\n  Workspace Setup Complete: READY FOR ROBOTICS!        \\n======================================================</code></pre>\\n</div>\\n\\n<details class=\\"reference-solution-dropdown\\">\\n  <summary class=\\"solution-summary-btn\\">\\n    <span>🔍 View Reference Solution (<code class=\\"inline-code\\">m01_l01_solution_env_setup.sh</code>)</span>\\n  </summary>\\n  <div class=\\"solution-body\\">\\n    <p>Reference file: <code class=\\"inline-code\\">ros2_ws_reference/scripts/m01_l01_solution_env_setup.sh</code></p>\\n    <div class=\\"code-container\\" data-language=\\"bash\\">\\n      <div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n      <pre><code class=\\"language-bash\\">#!/usr/bin/env bash\\n# ==============================================================================\\n# Nexus AMR Learning Hub - Level 1: Module 1 / Lesson 01 Solution\\n# Script:  m01_l01_solution_env_setup.sh\\n# Purpose: Autonomous Mobile Robot Workspace Initializer &amp; Diagnostic Check (Complete)\\n# ==============================================================================\\n\\nset -e\\n\\n# Terminal color codes\\nGREEN=&#x27;\\u001b[0;32m&#x27;\\nRED=&#x27;\\u001b[0;31m&#x27;\\nYELLOW=&#x27;\\u001b[1;33m&#x27;\\nBLUE=&#x27;\\u001b[0;34m&#x27;\\nNC=&#x27;\\u001b[0m&#x27; # No Color\\n\\necho -e \\"======================================================\\"\\necho -e \\"  Nexus AMR Workspace Initializer &amp; Diagnostics      \\"\\necho -e \\"======================================================\\"\\n\\n# Target workspace paths\\nWS_DIR=\\"/home/chaitu/nexus_ws\\"\\n\\n# Step 1: Workspace Directory Structure\\necho -e \\"\\n[Step 1/1: Creating Robotics Workspace Directory Tree]\\"\\nmkdir -p \\"/src\\" \\"/logs\\" \\"/config\\"\\nif [ -d \\"/src\\" ] &amp;&amp; [ -d \\"/logs\\" ] &amp;&amp; [ -d \\"/config\\" ]; then\\n    echo -e \\"[PASS] Workspace directory structure established at: \\"\\nelse\\n    echo -e \\"[FAIL] Could not create workspace directories!\\"\\n    exit 1\\nfi\\n\\necho -e \\"\\n======================================================\\"\\necho -e \\"  Workspace Setup Complete: READY FOR ROBOTICS!        \\"\\necho -e \\"======================================================\\"\\n</code></pre>\\n    </div>\\n  </div>\\n</details>\\n\\n<hr class=\\"divider\\">\\n<h2 id=\\"9-summary-amp-next-steps\\">9. Summary &amp; Next Steps</h2>\\n<p>You now have a solid command of Linux engineering fundamentals:</p>\\n<ul>\\n<li><strong>Navigated the filesystem hierarchy</strong> and inspected essential system paths.</li>\\n<li><strong>Created and managed files</strong> in an organized robotics project workspace.</li>\\n<li><strong>Created shell scripts and granted execution rights</strong> using <code class=\\"inline-code\\">chmod +x</code>.</li>\\n<li><strong>Managed background processes</strong> and monitored resource consumption with <code class=\\"inline-code\\">top</code> and <code class=\\"inline-code\\">killall</code>.</li>\\n<li><strong>Configured productivity aliases</strong> in <code class=\\"inline-code\\">~/.bashrc</code>.</li>\\n</ul>\\n<p>In <strong><a href=\\"02_ros2_overview_and_environment_setup.md\\">Lesson 02</a></strong>, we build on these Linux foundations to install our robotics stack: exploring ROS 2 Jazzy architecture, the peer-to-peer DDS middleware, and containerized Docker setup!</p>\\n\\n<div class=\\"asset-handoff-card\\" style=\\"margin: 1.75rem 0 1rem 0; padding: 1.15rem 1.4rem; border-radius: 10px; background: rgba(16, 185, 129, 0.06); border: 1px solid rgba(16, 185, 129, 0.25); border-left: 4px solid #10b981;\\">\\n  <div style=\\"display: flex; align-items: center; gap: 0.5rem; margin-bottom: 0.5rem;\\">\\n    <span style=\\"font-size: 1.1rem;\\">📦</span>\\n    <strong style=\\"font-size: 0.95rem; color: #10b981; text-transform: uppercase; letter-spacing: 0.04em;\\">Asset Handoff &amp; Next Lesson Pipeline Bridge</strong>\\n  </div>\\n  <p style=\\"margin: 0 0 0.65rem 0; font-size: 0.88rem; color: var(--text-primary); line-height: 1.6;\\">\\n    You have mastered core Linux CLI navigation, POSIX file permissions, filesystem hierarchy, and process lifecycle management. Your workspace directory structure and bash environment are primed for ROS 2 package compilation and execution.\\n  </p>\\n  <div style=\\"display: flex; flex-wrap: wrap; gap: 0.75rem; font-size: 0.82rem; font-family: var(--font-mono);\\">\\n    <span style=\\"background: var(--bg-surface); border: 1px solid var(--border-color); padding: 0.25rem 0.6rem; border-radius: 5px; color: var(--text-primary);\\">\\n      📁 <strong>Produced Artifact:</strong> <code>~/ros2_ws/</code> workspace directory &amp; verified Linux execution permissions (<code>chmod +x</code>)\\n    </span>\\n    <span style=\\"background: var(--bg-surface); border: 1px solid var(--border-color); padding: 0.25rem 0.6rem; border-radius: 5px; color: var(--text-primary);\\">\\n      ➡️ <strong>Ingested By:</strong> Lesson 02 (ROS 2 Overview &amp; Environment Setup)\\n    </span>\\n  </div>\\n</div>\\n","quizzes":[{"id":"q_l1_01_1","prompt":"Which Linux command is required to make a newly created Python node script executable by the ROS 2 runtime?","options":["chmod -R 777 script.py","chmod +x script.py","chown student:student script.py","source script.py"],"correct":1,"explanation":"chmod +x grants execution permissions to the script. While 777 also grants execution, it is an insecure antipattern in production robotics. chmod +x is the targeted industry standard."},{"id":"q_l1_01_2","prompt":"What does running 'source ~/.bashrc' achieve in an active terminal session?","options":["It restarts the Linux kernel and graphics drivers","It reloads environment variables, ROS 2 underlay paths, and aliases without closing the shell","It permanently writes current bash history to NVMe disk","It kills all running ROS 2 nodes"],"correct":1,"explanation":"source ~/.bashrc re-executes the user profile in the active shell context, updating paths like $ROS_DISTRO and custom aliases without requiring the engineer to spawn a new terminal window."}],"has_quiz":true,"next_id":"lesson_02","prev_id":null,"subtopics":[{"id":"1-overview-learning-objectives","title":"1. Overview &amp; Learning Objectives"},{"id":"2-the-linux-filesystem-what-you-need-to-know","title":"2. The Linux Filesystem: What You Need to Know"},{"id":"3-hands-on-practical-building-a-robotics-workspace","title":"3. Hands-On Practical: Building a Robotics Workspace"},{"id":"4-file-permissions-making-shell-scripts-executable","title":"4. File Permissions: Making Shell Scripts Executable"},{"id":"5-process-management-amp-background-jobs","title":"5. Process Management &amp; Background Jobs"},{"id":"6-shell-automation-with-bashrc","title":"6. Shell Automation with ~/.bashrc"},{"id":"7-multi-pane-terminal-workflows-terminator","title":"7. Multi-Pane Terminal Workflows (Terminator)"},{"id":"8-pro-tips-amp-hardware-reference","title":"8. 💡 Pro-Tips &amp; Hardware Reference"},{"id":"8-hands-on-student-challenge","title":"8. Hands-on Student Challenge: Autonomous Mobile Robot Workspace Initializer &amp; Diagnostics"},{"id":"9-summary-amp-next-steps","title":"9. Summary &amp; Next Steps"}]},{"id":"lesson_02","num":2,"num_str":"02","title":"ROS 2 Overview & Environment Setup","slug":"ros2_overview_and_environment_setup","filename":"02_ros2_overview_and_environment_setup.md","module":"Day 1: ROS 2 Foundations & Core Middleware","module_id":1,"duration":"45-60 min","focus":"Python-Only Robotics Engineering Workflow","snapshot":[["Peer-to-Peer DDS","Zero master bottleneck (roscore eliminated); nodes discover each other dynamically via DDS RTPS multicast."],["ROS 2 Jazzy LTS","Standardized on Ubuntu 24.04 Noble Numbat and Python 3.12 with enhanced DDS performance and real-time support."],["Multi-Terminal Layout","Manage bringup, teleoperation, RViz, and telemetry in an organized split-window terminal workflow."],["Hardware Abstraction","Encapsulates physical robot actuators, sensors, and kinematics behind standardized middleware interfaces."]],"html_content":"<h2 id=\\"1-overview-learning-objectives\\">1. Overview &amp; Learning Objectives</h2>\\n<p>Welcome to the foundation of modern robotics software engineering. This tutorial introduces <strong>Robot Operating System 2 (ROS 2)</strong>, the global standard for building commercial autonomous robots.</p>\\n<p><div class=\\"learning-objectives-card\\">\\n  <div class=\\"learning-objectives-header\\">\\n    <div class=\\"objectives-icon-badge\\">\\n      <span style=\\"font-size: 1.15rem; line-height: 1;\\">🎯</span>\\n    </div>\\n    <div class=\\"objectives-title-group\\">\\n      <h3 class=\\"objectives-main-title\\">Learning Objectives &amp; Core Outcomes</h3>\\n      <span class=\\"objectives-subtitle\\">By the end of this lesson, you will be able to:</span>\\n    </div>\\n    <span class=\\"objectives-count-badge\\">5 CORE OUTCOMES</span>\\n  </div>\\n  <ul class=\\"learning-objectives-list\\">\\n    <li class=\\"learning-objective-item\\">\\n      <span class=\\"objective-num-badge\\">1</span>\\n      <span class=\\"objective-text\\">Understand the core architectural differences between ROS 1 and ROS 2 (DDS middleware vs. Master node).</span>\\n    </li>\\n    <li class=\\"learning-objective-item\\">\\n      <span class=\\"objective-num-badge\\">2</span>\\n      <span class=\\"objective-text\\">Learn the release lifecycle and why <strong>ROS 2 Jazzy Jalisco</strong> on Ubuntu 24.04 is the industry benchmark.</span>\\n    </li>\\n    <li class=\\"learning-objective-item\\">\\n      <span class=\\"objective-num-badge\\">3</span>\\n      <span class=\\"objective-text\\">Install and configure a complete ROS 2 development workstation (Native Ubuntu or Containerized Docker).</span>\\n    </li>\\n    <li class=\\"learning-objective-item\\">\\n      <span class=\\"objective-num-badge\\">4</span>\\n      <span class=\\"objective-text\\">Configure multi-terminal development tooling with <strong>Terminator</strong> and <strong>VS Code</strong>.</span>\\n    </li>\\n    <li class=\\"learning-objective-item\\">\\n      <span class=\\"objective-num-badge\\">5</span>\\n      <span class=\\"objective-text\\">Set up automatic shell environment sourcing and productivity aliases.</span>\\n    </li>\\n  </ul>\\n</div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"2-hardware-and-software-prerequisites\\">2. Hardware and Software Prerequisites</h2>\\n<div class=\\"table-responsive\\"><table>\\n<thead>\\n<tr>\\n<th>Component</th>\\n<th>Specification</th>\\n<th>Purpose</th>\\n</tr>\\n</thead>\\n<tbody>\\n<tr>\\n<td><strong>Operating System</strong></td>\\n<td>Ubuntu 24.04 LTS (Noble Numbat) or Docker</td>\\n<td>Base OS supporting ROS 2 Jazzy</td>\\n</tr>\\n<tr>\\n<td><strong>Processor</strong></td>\\n<td>x86_64 or ARM64 (e.g. Jetson Orin, Raspberry Pi 5)</td>\\n<td>Host compute</td>\\n</tr>\\n<tr>\\n<td><strong>RAM</strong></td>\\n<td>Minimum 8 GB (16 GB recommended for Gazebo sim)</td>\\n<td>Colcon builds and simulation</td>\\n</tr>\\n<tr>\\n<td><strong>ROS 2 Distro</strong></td>\\n<td><strong>ROS 2 Jazzy Jalisco</strong> (LTS until May 2027)</td>\\n<td>Robotics middleware</td>\\n</tr>\\n<tr>\\n<td><strong>Python</strong></td>\\n<td>Python 3.12+</td>\\n<td>Primary programming language</td>\\n</tr>\\n<tr>\\n<td><strong>Editor</strong></td>\\n<td>Visual Studio Code (or Web code-server)</td>\\n<td>Code development &amp; debugging</td>\\n</tr>\\n<tr>\\n<td><strong>Terminal</strong></td>\\n<td>Terminator or tmux</td>\\n<td>Multi-pane ROS 2 CLI monitoring</td>\\n</tr>\\n</tbody>\\n</table></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"3-robotics-fundamentals-ros-2-architecture\\">3. Robotics Fundamentals &amp; ROS 2 Architecture</h2>\\n<h3 id=\\"31-what-is-a-robot-the-three-core-ingredients\\">3.1 What is a Robot? &amp; The Three Core Ingredients</h3>\\n<blockquote>\\n<p><strong>Definition:</strong> A <strong>robot</strong> is a machine capable of carrying out a complex series of actions automatically, especially one programmable by a computer.</p>\\n</blockquote>\\n<p><img src=\\"assets/images/robot_anatomy_ingredients.png\\" alt=\\"AMR Anatomy Cutaway\\" class=\\"lesson-image\\" loading=\\"lazy\\" /></p>\\n<p>Every autonomous robot—from an industrial mobile robot moving warehouse boxes to an interstellar rover—relies on <strong>three fundamental ingredients</strong>:</p>\\n<ol>\\n<li>\\n<p><strong>Perception (The Robot's Eyes &amp; Ears):</strong> How the robot senses the world around it.</p>\\n<ul>\\n<li><em>Simple Role:</em> It uses cameras to see, laser scanners to measure distances to walls, and GPS to know its position.</li>\\n<li>📷 <strong>Cameras (seeing):</strong> Capturing video frames, obstacle features, and visual objects.</li>\\n<li>🔴 <strong>LiDAR (measuring distances):</strong> 360-degree laser beams measuring precise distances to obstacles and walls.</li>\\n<li>🧭 <strong>GPS &amp; Compass (positioning):</strong> Tracking robot heading direction and global coordinates.</li>\\n</ul>\\n</li>\\n<li>\\n<p><strong>Decision Making (The Robot's Brain):</strong> How the robot thinks and plans what to do next.</p>\\n<ul>\\n<li><em>Simple Role:</em> It takes the sensor information and decides what to do next—stopping before hitting obstacles or finding the best path to its goal.</li>\\n<li>🛑 <strong>Obstacle Avoidance:</strong> Stop or brake immediately if an unexpected obstacle or person is close.</li>\\n<li>🗺️ <strong>Map Processing:</strong> Read the building layout and compute 2D costmaps with danger inflation zones.</li>\\n<li>📍 <strong>Path Planning:</strong> Generate smooth, collision-free trajectories from current pose to the destination.</li>\\n</ul>\\n</li>\\n<li>\\n<p><strong>Action (The Robot's Muscles):</strong> How the robot physically moves and acts.</p>\\n<ul>\\n<li><em>Simple Role:</em> It turns the brain's decisions into real movement—spinning the drive wheels, moving an arm, or speaking alerts.</li>\\n<li>⚙️ <strong>Spin Drive Wheels:</strong> Send linear &amp; angular velocity commands to wheel motor controllers.</li>\\n<li>🦾 <strong>Actuate Joints:</strong> Move robotic arm joints, grippers, or sensor tilt mechanisms.</li>\\n<li>🔊 <strong>Audio &amp; Voice Alerts:</strong> Speak notifications or sound chimes to warn pedestrians.</li>\\n</ul>\\n</li>\\n</ol>\\n<hr class=\\"divider\\">\\n<h3 id=\\"32-the-story-of-a-robotics-developer-why-we-need-a-standard\\">3.2 The Story of a Robotics Developer: Why We Need a Standard</h3>\\n<p>One pretty common story in robotics development is this:</p>\\n<h4 id=\\"-step-1-the-dream-autonomous-medicine-delivery-robot\\">🎬 Step 1: The Dream: Autonomous Medicine Delivery Robot</h4>\\n<p><img src=\\"assets/images/story_step1_dream.jpg\\" alt=\\"Step 1: The Dream: Autonomous Medicine Delivery Robot\\" class=\\"lesson-image\\" loading=\\"lazy\\" /></p>\\n<blockquote>\\n<p><strong>Someday, a student/engineer starts a new cool robotics project: She wants to build an Autonomous Medicine Delivery Robot</strong> to transport medicine across hospital corridors and deliver supplies safely to patient beds.<br>\\nSoon, she discovers that it’s not that simple: robotics is hard to learn, and developing good software takes immense time.</p>\\n</blockquote>\\n<hr class=\\"divider\\">\\n<h4 id=\\"-step-2-the-plumbing-trap-lidar-cameras-motors-sockets\\">🎬 Step 2: The Plumbing Trap: LiDAR, Cameras, Motors &amp; Sockets</h4>\\n<p><img src=\\"assets/images/story_step2_plumbing.jpg\\" alt=\\"Step 2: The Plumbing Trap: LiDAR, Cameras, Motors &amp; Sockets\\" class=\\"lesson-image\\" loading=\\"lazy\\" /></p>\\n<blockquote>\\n<p><strong>All her time is consumed by low-level plumbing:</strong></p>\\n<ul>\\n<li>How to get raw distance data from the LiDAR?</li>\\n<li>How to read images from the camera?</li>\\n<li>How to control the electric drive motors?</li>\\n<li>And how to make all these separate programs communicate and synchronize with each other?</li>\\n</ul>\\n<p><em>Without realizing it, all her time is killed writing device drivers and IPC sockets instead of autonomous medicine delivery.</em></p>\\n</blockquote>\\n<hr class=\\"divider\\">\\n<h4 id=\\"-step-3-goal-abandoned-just-an-rc-car\\">🎬 Step 3: Goal Abandoned: Just an RC Car</h4>\\n<p><img src=\\"assets/images/story_step3_burnout.jpg\\" alt=\\"Step 3: Goal Abandoned: Just an RC Car\\" class=\\"lesson-image\\" loading=\\"lazy\\" /></p>\\n<blockquote>\\n<p><strong>The project deadline arrives (often a 2–3 year PhD timeframe). No real progress was made on autonomous navigation.</strong><br>\\nSo much time was killed trying to write communication plumbing that the main project goal—an autonomous medicine delivery robot—was completely abandoned. All she managed to make in the end was get the motors to move using a hacked remote control (a glorified RC car). Soon the project is abandoned, and the prototype sits dormant in the lab.</p>\\n</blockquote>\\n<hr class=\\"divider\\">\\n<h4 id=\\"-step-4-another-guy-starts-the-food-delivery-robot-loop\\">🎬 Step 4: Another Guy Starts: The Food Delivery Robot Loop</h4>\\n<p><img src=\\"assets/images/story_step4_cycle.jpg\\" alt=\\"Step 4: Another Guy Starts: The Food Delivery Robot Loop\\" class=\\"lesson-image\\" loading=\\"lazy\\" /></p>\\n<blockquote>\\n<p><strong>A few weeks later, another guy wants to develop a Food Delivery Robot.</strong><br>\\nHe thinks: <em>What if I find some existing code I can directly use?</em> He finds her project on the Internet where she worked on controlling motors and getting LiDAR data.<br>\\nBut because her code was written without any standard framework, it is completely hardcoded, undocumented, and non-reusable for his robot.<br>\\n<strong>So, he has to start writing everything from scratch all over again!</strong></p>\\n</blockquote>\\n<hr class=\\"divider\\">\\n<div class=\\"alert-callout alert-warning\\"><div class=\\"alert-icon\\"></div><div class=\\"alert-body\\"><strong>The Core Problem in Robotics Development:</strong><br><br><em>&quot;And so on, and so forth. Many people who work in robot software development don’t actually develop robotics applications (such as medicine delivery or food delivery). They spend years building custom motor drivers and low-level frameworks that end up non-reusable, unsupported, not known, and quickly forgotten.</em></p><br><p><em>This situation often happens for people doing a PhD, with a 2–3 years time frame for the project.</em></p><br><p><em><strong>This is one of the main factors slowing down robotics research and development — and ROS was created specifically to solve this problem!</strong></em>&quot;</div></div>\\n<hr class=\\"divider\\">\\n<h3 id=\\"33-stop-reinventing-the-wheel-standardize-communication-for-community-sharing\\">3.3 Stop Reinventing the Wheel &amp; Standardize Communication for Community Sharing</h3>\\n<p>How universal message standards and global community sharing solve the developer crisis and enable plug-and-play robotics.</p>\\n<p><img src=\\"assets/images/reinvent_the_wheel.jpg\\" alt=\\"Reinventing the Wheel\\" class=\\"lesson-image\\" loading=\\"lazy\\" />\\n<em>“If you are busy making everything from scratch and rebuilding parts that someone has already worked on, you cannot make every part of your robot perfect.”</em></p>\\n<div class=\\"alert-callout alert-important\\"><div class=\\"alert-icon\\"></div><div class=\\"alert-body\\"><strong>The Paradigm Shift: From Custom Square Wheels to a Universal ROS 2 Bus</strong></p><br><ul><br><li><strong>1. Stop Reinventing the Wheel:</strong> Before ROS, developers spent 80% of project time writing custom motor drivers and serial protocols from scratch, only to abandon them when the project ended.</li><br><li><strong>2. Standardize Communication:</strong> ROS 2 defines universal message interfaces (<code class=\\"inline-code\\">/scan</code>, <code class=\\"inline-code\\">/cmd_vel</code>, <code class=\\"inline-code\\">/odom</code>) across Topics, Services, and Actions—completely decoupling high-level software from hardware.</li><br><li><strong>3. Global Community Sharing:</strong> Because all robots speak the same standard, you instantly reuse community packages (<code class=\\"inline-code\\">Nav2</code>, <code class=\\"inline-code\\">SLAM Toolbox</code>, <code class=\\"inline-code\\">MoveIt 2</code>) and focus 90% of your time on real autonomy.</div></div></li>\\n</ul>\\n<hr class=\\"divider\\">\\n<h3 id=\\"34-what-is-ros-the-windows-os-metaphor\\">3.4 What is ROS? The Windows OS Metaphor</h3>\\n<p><img src=\\"assets/images/ros_metaphor_pc_vs_robot.jpg\\" alt=\\"The Operating System Metaphor: Windows vs ROS\\" class=\\"lesson-image\\" loading=\\"lazy\\" /></p>\\n<blockquote>\\n<p><strong>The Operating System Metaphor: Windows for PC ➔ ROS for Robots</strong></p>\\n<p>Think about how your personal computer works: When you open <strong>Chrome</strong>, <strong>Microsoft Word</strong>, or <strong>Blender</strong>, you never have to write custom device drivers to talk to your mouse, keyboard, or printer. The operating system handles all the hardware communication behind the scenes through standardized interfaces.</p>\\n<p><strong>ROS does the exact same thing for robots:</strong> Instead of writing low-level code for every motor and camera, your high-level navigation, computer vision, and AI programs talk directly to ROS. If you switch from an expensive industrial laser scanner to a budget sensor, you don't rewrite your navigation software—ROS takes care of the hardware translation!</p>\\n</blockquote>\\n<hr class=\\"divider\\">\\n<h3 id=\\"341-the-core-reality-a-framework-not-a-bare-metal-os\\">3.4.1 The Core Reality: A Framework, Not a Bare-Metal OS</h3>\\n<p><img src=\\"assets/images/ros_framework_os_layers.jpg\\" alt=\\"ROS 2 Framework on Top of Host Operating Systems\\" class=\\"lesson-image\\" loading=\\"lazy\\" /></p>\\n<p><div class=\\"alert-callout alert-important\\"><div class=\\"alert-icon\\"></div><div class=\\"alert-body\\"><strong>&quot;Robot Operating System, despite its name, is not an operating system; rather, it’s a framework that works on top of an existing operating system.&quot;</strong><br><br>⭐ <strong>Ubuntu Linux</strong> is the official Tier-1, best-supported, and industry-standard operating system for robotics engineering.</div></div>\\n<hr class=\\"divider\\">\\n<h3 id=\\"35-the-4-foundational-pillars-of-ros\\">3.5 The 4 Foundational Pillars of ROS</h3>\\n<div class=\\"table-responsive\\"><table>\\n<thead>\\n<tr>\\n<th style=\\"text-align:left\\">Pillar</th>\\n<th style=\\"text-align:left\\">What It Provides</th>\\n<th style=\\"text-align:left\\">Real-World Robotics Impact</th>\\n</tr>\\n</thead>\\n<tbody>\\n<tr>\\n<td style=\\"text-align:left\\"><strong>1. The Plumbing (Communication / Middleware)</strong></td>\\n<td style=\\"text-align:left\\">Anonymous, distributed message-passing (Topics, Services, Actions) running over industrial DDS (Data Distribution Service).</td>\\n<td style=\\"text-align:left\\">Decouples software processes completely. A camera node doesn't care who is watching; it simply publishes <code class=\\"inline-code\\">/camera/image_raw</code>. You can add an obstacle detector or a web dashboard without modifying a single line of camera code.</td>\\n</tr>\\n<tr>\\n<td style=\\"text-align:left\\"><strong>2. The Tools</strong></td>\\n<td style=\\"text-align:left\\">Developer introspection &amp; simulation: <strong>RViz2</strong> (3D sensor visualization), <strong>Gazebo</strong> (physics simulation), <strong>ros2 bag</strong> (record &amp; replay flight telemetry), and <strong>rqt_graph</strong>.</td>\\n<td style=\\"text-align:left\\">Inspect the robot's brain in real time without guessing. Test navigation algorithms in simulated physics worlds before risking collisions on thousand-dollar physical hardware.</td>\\n</tr>\\n<tr>\\n<td style=\\"text-align:left\\"><strong>3. The Capabilities</strong></td>\\n<td style=\\"text-align:left\\">Production-ready algorithms for 2D/3D SLAM mapping (<code class=\\"inline-code\\">slam_toolbox</code>), path planning (<code class=\\"inline-code\\">Nav2</code>), kinematics (<code class=\\"inline-code\\">TF2</code>), and computer vision (<code class=\\"inline-code\\">cv_bridge</code>).</td>\\n<td style=\\"text-align:left\\">You don't need a PhD in computational geometry to make a robot navigate from Point A to Point B. You wire Nav2 into your sensors and focus on your business mission.</td>\\n</tr>\\n<tr>\\n<td style=\\"text-align:left\\"><strong>4. The Ecosystem</strong></td>\\n<td style=\\"text-align:left\\">Massive global community backed by Open Robotics and industry consortiums (ROS-Industrial).</td>\\n<td style=\\"text-align:left\\">Hardware vendors (SICK, Velodyne, Intel RealSense, ODrive) publish verified ROS 2 drivers out of the box under permissive Apache 2.0 open-source licenses.</td>\\n</tr>\\n</tbody>\\n</table></div>\\n<hr class=\\"divider\\">\\n<h3 id=\\"36-the-motion-flow-explanation-the-robot-as-a-living-organism\\">3.6 The Motion Flow Explanation: The Robot as a Living Organism</h3>\\n<p>To intuitively understand how ROS 2 operates at runtime, visualize the AMR not as a collection of scripts, but as a <strong>living biological organism</strong> where information flows through four dynamic stages:</p>\\n<p><img src=\\"assets/images/ros2_motion_architecture.svg\\" alt=\\"ROS 2 Motion Architecture &amp; Data Flow\\" class=\\"lesson-image\\" loading=\\"lazy\\" /></p>\\n<h4 id=\\"-motion-flow-stage-breakdown\\">🎬 Motion Flow Stage Breakdown:</h4>\\n<p><div class=\\"code-container\\" data-language=\\"text\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">text</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-text\\">[ 1. SENSES (Perception) ] --------&gt; ( /scan, /image_raw ) --------&gt; [ 2. DDS HIGHWAY ]\\n                                                                             |\\n[ 3. BRAIN (SLAM &amp; Nav2) ] &lt;------- ( /scan, /odom ) &lt;-----------------------+\\n        |\\n        +-------------------------&gt; ( /cmd_vel ) -------------------------&gt; [ 2. DDS HIGHWAY ]\\n                                                                             |\\n[ 4. MUSCLES (Motors/Encoders) ] &lt;-- ( /cmd_vel ) &lt;--------------------------+\\n        |\\n        +-------------------------&gt; ( /odom Feedback ) -------------------&gt; [ 2. DDS HIGHWAY ]\\n</code></pre>\\n</div>\\n</p>\\n<ol>\\n<li>\\n<p><strong>Stage 1: Senses (Sensory Perception / Telemetry Input)</strong></p>\\n<ul>\\n<li>The robot's eyes and ears: The <strong>LiDAR Node</strong> continuously spins at 10 Hz, emitting 360 laser distance measurements bundled into a <code class=\\"inline-code\\">sensor_msgs/msg/LaserScan</code> packet.</li>\\n<li>The <strong>Camera Node</strong> captures 30 FPS video frames as <code class=\\"inline-code\\">sensor_msgs/msg/Image</code>.</li>\\n<li>The <strong>IMU Node</strong> streams high-frequency angular velocity and linear acceleration (100 Hz).</li>\\n<li><em>In Motion:</em> Data packets pulse outward from the hardware sensors directly onto the local data bus.</li>\\n</ul>\\n</li>\\n<li>\\n<p><strong>Stage 2: Nerves (The DDS Communication Highway)</strong></p>\\n<ul>\\n<li>The central nervous system: Instead of routing messages through a centralized master bottleneck (as ROS 1 did), ROS 2 utilizes <strong>DDS (Data Distribution Service)</strong>.</li>\\n<li>Nodes discover each other automatically via peer-to-peer UDP multicast.</li>\\n<li><em>In Motion:</em> Messages travel along high-speed virtual conduits. On a single robot computer, data moves through <strong>zero-copy shared memory</strong> (nanoseconds); across wireless fleet networks, DDS handles packet serialization and retransmission deterministically.</li>\\n</ul>\\n</li>\\n<li>\\n<p><strong>Stage 3: Brain (Cognitive Planning &amp; State Estimation)</strong></p>\\n<ul>\\n<li>The cognitive cortex: The <strong>SLAM Node (<code class=\\"inline-code\\">slam_toolbox</code>)</strong> consumes <code class=\\"inline-code\\">/scan</code> and wheel odometry, performing scan-matching against the global map to calculate the robot's exact coordinates <code class=\\"inline-code\\">(x, y, θ)</code>.</li>\\n<li>The <strong>Nav2 Controller (<code class=\\"inline-code\\">controller_server</code>)</strong> projects global obstacles onto a rolling costmap, evaluates dozens of candidate velocity trajectories with DWB critics, and chooses the optimal speed curve.</li>\\n<li><em>In Motion:</em> The brain synthesizes incoming sensory pulses and outputs forward/angular velocity setpoints as <code class=\\"inline-code\\">geometry_msgs/msg/Twist</code> on topic <code class=\\"inline-code\\">/cmd_vel</code>.</li>\\n</ul>\\n</li>\\n<li>\\n<p><strong>Stage 4: Muscles (Actuation &amp; Motor Control)</strong></p>\\n<ul>\\n<li>The physical limbs: The <strong>Differential Drive Controller Node</strong> subscribes to <code class=\\"inline-code\\">/cmd_vel</code>. It solves differential kinematics:\\n<code class=\\"inline-code\\">v_left = (v_x - ω_z · (L / 2)) / R</code> and <code class=\\"inline-code\\">v_right = (v_x + ω_z · (L / 2)) / R</code></li>\\n<li>Sends target RPM setpoints to the motor controller boards over CAN or USB.</li>\\n<li><em>In Motion:</em> The wheels rotate, the AMR advances forward across the warehouse floor, and new wheel encoder ticks flow back to the nervous system, completing the closed-loop perception-action cycle!</li>\\n</ul>\\n</li>\\n</ol>\\n<hr class=\\"divider\\">\\n<h3 id=\\"37-ros-1-vs-ros-2-the-architectural-paradigm-shift-unified-rcl-c-core\\">3.7 ROS 1 vs. ROS 2: The Architectural Paradigm Shift &amp; Unified RCL C Core</h3>\\n<h4 id=\\"the-3-architectural-layers-side-by-side-comparison\\">The 3 Architectural Layers (Side-by-Side Comparison):</h4>\\n<h5 id=\\"1-ros-1-architecture-legacy-centralized-design\\">1. ROS 1 Architecture (Legacy Centralized Design)</h5>\\n<ul>\\n<li><strong>Master (<code class=\\"inline-code\\">roscore</code>):</strong> Centralized XML-RPC naming and lookup service that all nodes must query to discover peers and establish topic connections.</li>\\n<li><strong>Application Nodes:</strong> User robotics algorithms that depend entirely on the Master for connection lookup and freeze if it fails.</li>\\n<li><strong>Client Library (<code class=\\"inline-code\\">roscpp</code> / <code class=\\"inline-code\\">rospy</code>):</strong> Two independently written language codebases that suffered from feature disparities and differing threading behaviors.</li>\\n<li><strong>TCPROS / UDPROS:</strong> Custom socket transport lacking native QoS policies, data encryption, and lossy wireless support.</li>\\n<li><strong>Nodelet API (C++):</strong> Specialized C++ mechanism sharing memory inside one process to bypass network serialization.</li>\\n<li><strong>OS Layer (Linux Only):</strong> Strictly bound to Linux distributions with no native support for Windows, macOS, or microcontrollers.</li>\\n</ul>\\n<h5 id=\\"2-ros-2-architecture-modern-decentralized-standard\\">2. ROS 2 Architecture (Modern Decentralized Standard)</h5>\\n<ul>\\n<li><strong>Application Nodes (Masterless):</strong> Autonomous nodes that dynamically discover peers via DDS UDP multicast with zero single point of failure.</li>\\n<li><strong>Client Library (<code class=\\"inline-code\\">rclcpp</code> / <code class=\\"inline-code\\">rclpy</code> / <code class=\\"inline-code\\">rcl</code>):</strong> Thin language wrappers built upon a shared C core (<code class=\\"inline-code\\">rcl</code>), ensuring 100% behavioral and threading parity.</li>\\n<li><strong>Abstract DDS Layer (<code class=\\"inline-code\\">rmw</code>):</strong> Standard middleware interface that decouples ROS 2 from specific DDS vendors, enabling zero-code vendor switching.</li>\\n<li><strong>DDS (<code class=\\"inline-code\\">FastDDS</code> / <code class=\\"inline-code\\">CycloneDDS</code>):</strong> OMG industrial standard handling peer discovery, data encryption, and configurable Quality of Service (QoS).</li>\\n<li><strong>Intra-process API:</strong> Passes direct memory pointers between co-located nodes to achieve ultra-low microsecond latency.</li>\\n<li><strong>OS Layer (Multi-Platform &amp; RTOS):</strong> Universal multi-platform support spanning developer workstations, cloud servers, and real-time embedded microcontrollers (FreeRTOS, Zephyr, QNX).</li>\\n</ul>\\n<hr class=\\"divider\\">\\n<h4 id=\\"eliminating-language-inconsistencies-the-unified-c-core-rcl\\">Eliminating Language Inconsistencies: The Unified C Core (<code class=\\"inline-code\\">rcl</code>)</h4>\\n<p>In <strong>ROS 1</strong>, <code class=\\"inline-code\\">roscpp</code> and <code class=\\"inline-code\\">rospy</code> were two completely independent codebases written from scratch. Features added to C++ were often missing in Python, multithreading worked differently, and bugs fixed in one language lingered in the other for years.</p>\\n<p>In <strong>ROS 2</strong>, Open Robotics solved this by building a unified C core: <code class=\\"inline-code\\">rcl</code> (ROS Client Library) and <code class=\\"inline-code\\">rcutils</code>. Both <code class=\\"inline-code\\">rclcpp</code> (C++) and <code class=\\"inline-code\\">rclpy</code> (Python) are thin, lightweight wrappers on top of the exact same C codebase.</p>\\n<p><div class=\\"code-container\\" data-language=\\"text\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">text</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-text\\">       [ rclcpp (C++ API) ]        [ rclpy (Python 3 API) ]\\n                 \\\\                          /\\n                  ▼  thin wrapper bindings ▼\\n             [ rcl (Unified Common ROS Client C Core) + rcutils ]\\n                                    │\\n                         ▼ standard abstraction ▼\\n             [ rmw (ROS MiddleWare Interface) ---&gt; FastDDS / CycloneDDS ]\\n</code></pre>\\n</div>\\n</p>\\n<blockquote>\\n<p><strong>Result:</strong> 100% behavioral parity, identical threading models, and synchronized updates across Python and C++!</p>\\n</blockquote>\\n<hr class=\\"divider\\">\\n<h2 id=\\"4-ros-2-release-timeline\\">4. ROS 2 Release Timeline</h2>\\n<p>ROS 2 releases are named alphabetically after adjectives and marine/amphibian species:</p>\\n<div class=\\"table-responsive\\"><table>\\n<thead>\\n<tr>\\n<th>Release Name</th>\\n<th>Target Ubuntu</th>\\n<th>Release Date</th>\\n<th>End of Life (EOL)</th>\\n<th>Industry Status</th>\\n</tr>\\n</thead>\\n<tbody>\\n<tr>\\n<td>Foxy Fitzroy</td>\\n<td>Ubuntu 20.04 LTS</td>\\n<td>June 2020</td>\\n<td>May 2023</td>\\n<td>End of Life</td>\\n</tr>\\n<tr>\\n<td>Galactic Geochelone</td>\\n<td>Ubuntu 20.04 LTS</td>\\n<td>May 2021</td>\\n<td>Nov 2022</td>\\n<td>End of Life</td>\\n</tr>\\n<tr>\\n<td>Humble Hawksbill</td>\\n<td>Ubuntu 22.04 LTS</td>\\n<td>May 2022</td>\\n<td>May 2027</td>\\n<td>Mature LTS</td>\\n</tr>\\n<tr>\\n<td>Iron Irwini</td>\\n<td>Ubuntu 22.04 LTS</td>\\n<td>May 2023</td>\\n<td>Nov 2024</td>\\n<td>End of Life</td>\\n</tr>\\n<tr>\\n<td><strong>Jazzy Jalisco</strong></td>\\n<td><strong>Ubuntu 24.04 LTS</strong></td>\\n<td><strong>May 2024</strong></td>\\n<td><strong>May 2029</strong></td>\\n<td><strong>Primary Recommended LTS (Workshop Standard)</strong></td>\\n</tr>\\n</tbody>\\n</table></div>\\n<div class=\\"alert-callout alert-important\\"><div class=\\"alert-icon\\"></div><div class=\\"alert-body\\"><strong>ROS 2 Jazzy Jalisco</strong> on <strong>Ubuntu 24.04 LTS (Noble Numbat)</strong> represents the state-of-the-art long-term support release, featuring Python 3.12, native MCAP bag storage, enhanced FastDDS / CycloneDDS middleware, and the latest Nav2 autonomous navigation framework.</div></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"5-step-by-step-installation-on-ubuntu-2404-lts\\">5. Step-by-Step Installation on Ubuntu 24.04 LTS</h2>\\n<p>If installing natively on Ubuntu 24.04, follow these exact verified steps:</p>\\n<h3 id=\\"step-51-configure-locale-utf-8-verification\\">Step 5.1: Configure Locale (UTF-8 Verification)</h3>\\n<blockquote>\\n<p>[!SYNTAX]\\n<strong>Command Syntax:</strong> <code class=\\"inline-code\\">locale</code>  |  <code class=\\"inline-code\\">sudo locale-gen &lt;locale&gt;</code>  |  <code class=\\"inline-code\\">sudo update-locale &lt;vars&gt;</code><br>\\n<strong>Description:</strong> ROS 2 requires an explicit UTF-8 locale environment to process character encoding in ROS message strings, logs, and telemetry packets.</p>\\n</blockquote>\\n<p><strong>Hands-On Practical Command:</strong></p>\\n<p><div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\">locale  # Verify output contains UTF-8\\n\\nsudo apt update &amp;&amp; sudo apt install -y locales\\nsudo locale-gen en_US en_US.UTF-8\\nsudo update-locale LC_ALL=en_US.UTF-8 LANG=en_US.UTF-8\\nexport LANG=en_US.UTF-8\\n</code></pre>\\n</div>\\n</p>\\n<hr class=\\"divider\\">\\n<h3 id=\\"step-52-enable-ubuntu-universe-repository\\">Step 5.2: Enable Ubuntu Universe Repository</h3>\\n<blockquote>\\n<p>[!SYNTAX]\\n<strong>Command Syntax:</strong> <code class=\\"inline-code\\">sudo add-apt-repository &lt;repo_name&gt;</code><br>\\n<strong>Description:</strong> Enables the Ubuntu Universe repository, which provides community-maintained open-source packages and build tools.</p>\\n</blockquote>\\n<p><strong>Hands-On Practical Command:</strong></p>\\n<p><div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\">sudo apt install -y software-properties-common\\nsudo add-apt-repository universe\\n</code></pre>\\n</div>\\n</p>\\n<hr class=\\"divider\\">\\n<h3 id=\\"step-53-add-ros-2-gpg-key-apt-source\\">Step 5.3: Add ROS 2 GPG Key &amp; APT Source</h3>\\n<blockquote>\\n<p>[!SYNTAX]\\n<strong>Command Syntax:</strong> <code class=\\"inline-code\\">curl -sSL &lt;key_url&gt; -o &lt;keyring_path&gt;</code>  |  <code class=\\"inline-code\\">tee /etc/apt/sources.list.d/&lt;list&gt;</code><br>\\n<strong>Description:</strong> Downloads OpenPGP archive keys into <code class=\\"inline-code\\">/usr/share/keyrings</code> and adds the Open Robotics package repository to your APT sources list for cryptographically verified package installations.</p>\\n</blockquote>\\n<p><strong>Hands-On Practical Command:</strong></p>\\n<p><div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\">sudo apt update &amp;&amp; sudo apt install -y curl gnupg lsb-release\\n\\n# Download ROS archive key\\nsudo curl -sSL https://raw.githubusercontent.com/ros/rosdistro/master/ros.key -o /usr/share/keyrings/ros-archive-keyring.gpg\\n\\n# Add ROS 2 repository to sources list\\necho &quot;deb [arch=$(dpkg --print-architecture) signed-by=/usr/share/keyrings/ros-archive-keyring.gpg] http://packages.ros.org/ros2/ubuntu $(. /etc/os-release &amp;&amp; echo $UBUNTU_CODENAME) main&quot; | sudo tee /etc/apt/sources.list.d/ros2.list &gt; /dev/null\\n</code></pre>\\n</div>\\n</p>\\n<hr class=\\"divider\\">\\n<h3 id=\\"step-54-install-ros-2-jazzy-desktop-build-tools\\">Step 5.4: Install ROS 2 Jazzy Desktop &amp; Build Tools</h3>\\n<blockquote>\\n<p>[!SYNTAX]\\n<strong>Command Syntax:</strong> <code class=\\"inline-code\\">sudo apt install -y ros-jazzy-desktop python3-colcon-common-extensions</code><br>\\n<strong>Description:</strong> Installs the core ROS 2 libraries, RViz2 visualization, Gazebo integration packages, Python 3 bindings, and the Colcon build tool.</p>\\n</blockquote>\\n<p><strong>Hands-On Practical Command:</strong></p>\\n<p><div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\">sudo apt update\\nsudo apt install -y ros-jazzy-desktop\\n\\n# Install Colcon build system, rosdep, and python dependencies\\nsudo apt install -y python3-colcon-common-extensions python3-rosdep python3-pip python3-argcomplete\\n</code></pre>\\n</div>\\n</p>\\n<hr class=\\"divider\\">\\n<h3 id=\\"step-55-initialize-rosdep\\">Step 5.5: Initialize Rosdep</h3>\\n<blockquote>\\n<p>[!SYNTAX]\\n<strong>Command Syntax:</strong> <code class=\\"inline-code\\">sudo rosdep init</code>  |  <code class=\\"inline-code\\">rosdep update</code><br>\\n<strong>Description:</strong> Initializes the package dependency index. <code class=\\"inline-code\\">rosdep</code> queries the global ROS package index to resolve and install OS system dependencies (apt libraries, C++ headers, Python packages) required by ROS 2 nodes.</p>\\n</blockquote>\\n<p><strong>Hands-On Practical Command:</strong></p>\\n<p><div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\">sudo rosdep init\\nrosdep update\\n</code></pre>\\n</div>\\n</p>\\n<hr class=\\"divider\\">\\n<h2 id=\\"6-how-to-open-amp-use-the-desktop-gui-novnc-bull-port-6080\\">6. How to Open &amp; Use the Desktop GUI (noVNC • Port 6080)</h2>\\n<p>Because your Nexus AMR Learning Hub container is already running, a full Ubuntu 24.04 XFCE desktop environment is available directly inside your web browser. This desktop is where you run graphical robotics software like Gazebo Harmonic 3D simulations, RViz2 sensor visualizers, and multi-pane terminals.</p>\\n<h3 id=\\"61-accessing-the-desktop-gui\\">6.1 Accessing the Desktop GUI</h3>\\n<p>You can open the Ubuntu desktop at any time using either method:</p>\\n<ul>\\n<li><strong>One-Click Navbar Link:</strong> Click the <strong><code class=\\"inline-code\\">🖥️ Desktop GUI</code></strong> button in the top navigation bar of this platform.</li>\\n<li><strong>Direct Browser URL:</strong> Navigate to:<br>\\n<a href=\\"http://localhost:6080/vnc.html?autoconnect=true&amp;resize=remote\\"><code class=\\"inline-code\\">http://localhost:6080/vnc.html?autoconnect=true&amp;resize=remote</code></a></li>\\n</ul>\\n<div class=\\"alert-callout alert-note\\"><div class=\\"alert-icon\\"></div><div class=\\"alert-body\\"><strong>Passwordless Instant Connect:</strong><br><br>The VNC server is pre-configured with passwordless authentication. The browser tab connects immediately without prompting for a password.</div></div>\\n<h3 id=\\"62-pre-configured-robotics-desktop-launchers\\">6.2 Pre-Configured Robotics Desktop Launchers</h3>\\n<p>On your desktop screen, you will find clean, dedicated application launchers tailored specifically for your coursework:</p>\\n<ul>\\n<li><strong>Terminal:</strong> Launches the pre-configured ROS 2 command terminal directly inside <code class=\\"inline-code\\">/home/student</code>.</li>\\n<li><strong>RViz2 Visualizer:</strong> Opens the 3D robot visualization tool with the ROS 2 Jazzy environment loaded.</li>\\n<li><strong>Gazebo Simulator:</strong> Launches the Gazebo Harmonic physics engine ready to simulate your AMRs.</li>\\n<li><strong>ROS 2 Workspace:</strong> Instant shortcut opening your active <code class=\\"inline-code\\">~/ros2_ws</code> project folder.</li>\\n</ul>\\n<h3 id=\\"63-novnc-controls-amp-productivity-tips\\">6.3 noVNC Controls &amp; Productivity Tips</h3>\\n<ul>\\n<li><strong>Remote Auto-Resize:</strong> The desktop automatically matches your browser window dimensions (<code class=\\"inline-code\\">resize=remote</code>).</li>\\n<li><strong>Clipboard Sync:</strong> Click the small slide-out chevron menu on the left edge of the noVNC screen to open the noVNC Control Bar → select the <strong>Clipboard</strong> tool to copy-paste text between your host OS and the container.</li>\\n<li><strong>Fullscreen Mode:</strong> Click the Fullscreen icon in the noVNC slide-out menu or press <kbd>F11</kbd> in your browser for a distraction-free native desktop experience.</li>\\n</ul>\\n<hr class=\\"divider\\">\\n<h2 id=\\"7-how-to-open-amp-use-in-browser-vs-code-ide-port-8443\\">7. How to Open &amp; Use In-Browser VS Code IDE (Port 8443)</h2>\\n<p>You do not need to install local IDEs or extensions. A full Visual Studio Code IDE (code-server) is running inside your container, accessible from any browser tab.</p>\\n<h3 id=\\"71-accessing-the-vs-code-editor\\">7.1 Accessing the VS Code Editor</h3>\\n<ul>\\n<li><strong>One-Click Navbar Link:</strong> Click the <strong><code class=\\"inline-code\\">💻 VS Code</code></strong> button in the top navigation bar.</li>\\n<li><strong>Direct Browser URL:</strong> Navigate to:<br>\\n<a href=\\"http://localhost:8443/?folder=/home/student\\"><code class=\\"inline-code\\">http://localhost:8443/?folder=/home/student</code></a></li>\\n</ul>\\n<div class=\\"alert-callout alert-note\\"><div class=\\"alert-icon\\"></div><div class=\\"alert-body\\"><strong>Pre-Authenticated User Home Workspace:</strong><br><br>No password or sign-in is required. The editor opens directly rooted inside <code class=\\"inline-code\\">/home/student</code> so you can manage your files, view your terminal, and immediately see your <code class=\\"inline-code\\">~/ros2_ws</code> directory as soon as you create it in <strong>Lesson 03</strong>!</div></div>\\n<h3 id=\\"72-key-in-browser-vs-code-features\\">7.2 Key In-Browser VS Code Features</h3>\\n<ol>\\n<li><strong>Pre-Installed Robotics Extensions:</strong> Python IntelliSense, ROS tooling, XML (for URDF/Xacro), and YAML highlighting are pre-configured.</li>\\n<li><strong>Integrated Terminal:</strong> Press <kbd>Ctrl</kbd> + <kbd><code class=\\"inline-code\\">&lt;/kbd&gt; (Backtick) or select **Terminal &amp;rarr; New Terminal** to open a bash shell in </code>/home/student\`.</li>\\n<li><strong>Real-Time Code Persistence:</strong> Any code files you edit or save in this browser window are stored directly on disk and preserved across container restarts.</li>\\n</ol>\\n<hr class=\\"divider\\">\\n<h2 id=\\"8-how-to-open-amp-use-the-terminal-desktop-hotkeys-terminator-amp-host-cli\\">8. How to Open &amp; Use the Terminal (Desktop, Hotkeys, Terminator &amp; Host CLI)</h2>\\n<p>Robotics engineers spend most of their time in the Linux terminal: compiling packages, echoing topics, and monitoring nodes. You have four convenient ways to open and use the terminal in your environment:</p>\\n<h3 id=\\"method-1-desktop-terminal-icon-amp-universal-hotkey-inside-vnc\\">Method 1: Desktop Terminal Icon &amp; Universal Hotkey (Inside VNC)</h3>\\n<ul>\\n<li><strong>Desktop Launcher:</strong> Double-click the <strong>Terminal</strong> icon on the desktop.</li>\\n<li><strong>Universal Hotkey:</strong> In the noVNC desktop window, press <kbd>Ctrl</kbd> + <kbd>Alt</kbd> + <kbd>T</kbd>.</li>\\n<li><strong>Prompt Location:</strong> Launches directly in your home directory <code class=\\"inline-code\\">/home/student</code>.</li>\\n</ul>\\n<h3 id=\\"method-2-multi-pane-workflow-with-terminator\\">Method 2: Multi-Pane Workflow with Terminator</h3>\\n<p>Robotics workflows require monitoring 3 to 4 nodes at once (e.g. simulation, teleop control, sensor topics, and node logs). <strong>Terminator</strong> lets you split your screen into multiple independent terminal tiles:</p>\\n<ul>\\n<li><strong>Launch Terminator:</strong> Open the terminal and run <code class=\\"inline-code\\">terminator &amp;</code> (or find it in the XFCE Applications menu).</li>\\n<li><strong>Split Horizontally:</strong> Press <kbd>Ctrl</kbd> + <kbd>Shift</kbd> + <kbd>O</kbd> to split the current pane top and bottom.</li>\\n<li><strong>Split Vertically:</strong> Press <kbd>Ctrl</kbd> + <kbd>Shift</kbd> + <kbd>E</kbd> to split the current pane left and right.</li>\\n<li><strong>Navigate Panes:</strong> Press <kbd>Alt</kbd> + <kbd>Arrow Keys</kbd> to jump between tiles without touching the mouse.</li>\\n<li><strong>Close Pane:</strong> Press <kbd>Ctrl</kbd> + <kbd>Shift</kbd> + <kbd>W</kbd>.</li>\\n</ul>\\n<h3 id=\\"method-3-integrated-terminal-inside-vs-code\\">Method 3: Integrated Terminal inside VS Code</h3>\\n<ul>\\n<li>Press <kbd>Ctrl</kbd> + <kbd><code class=\\"inline-code\\">&lt;/kbd&gt; (Backtick) inside the in-browser VS Code tab (</code>:8443\`).</li>\\n<li>Perfect for quick <code class=\\"inline-code\\">colcon build</code> commands while editing Python node files.</li>\\n</ul>\\n<h3 id=\\"method-4-terminal-access-directly-from-host-shell\\">Method 4: Terminal Access Directly from Host Shell</h3>\\n<p>You can also enter the container directly from your local computer's native shell (Ubuntu terminal, macOS terminal, or Windows PowerShell):</p>\\n<p><div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\">docker exec -it navpro_level1_container bash\\n</code></pre>\\n</div>\\n</p>\\n<hr class=\\"divider\\">\\n<h3 id=\\"85-sourcing-the-ros-2-installation-underlay-amp-shell-automation\\">8.5 Sourcing the ROS 2 Installation (Underlay) &amp; Shell Automation</h3>\\n<p>When you open a brand new terminal, the system does not load ROS 2 into your shell environment by default. If you try running <code class=\\"inline-code\\">ros2</code> immediately:</p>\\n<p><div class=\\"code-container\\" data-language=\\"text\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">text</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-text\\">bash: ros2: command not found\\n</code></pre>\\n</div>\\n</p>\\n<p>To tell Linux where the ROS 2 binaries, libraries, and Python packages reside, you must <strong>source the ROS 2 system setup file</strong>:</p>\\n<div class=\\"cmd-card\\">\\n  <div class=\\"cmd-header\\">\\n    <div class=\\"cmd-header-left\\">\\n      <span class=\\"cmd-badge\\">source /opt/ros/...</span>\\n      <span class=\\"cmd-title\\">Source ROS 2 Jazzy Underlay &amp; Automate with ~/.bashrc</span>\\n    </div>\\n    <span class=\\"cmd-syntax\\">Syntax: <code>source /opt/ros/jazzy/setup.bash</code></span>\\n  </div>\\n  <p class=\\"cmd-desc\\">Populates your shell's <code>PATH</code>, <code>AMENT_PREFIX_PATH</code>, and <code>PYTHONPATH</code> with the ROS 2 Jazzy distribution.</p>\\n<p><div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\"># Step 1: Source the ROS 2 installation manually in your current terminal:\\nsource /opt/ros/jazzy/setup.bash\\n\\n# Step 2: Verify that ROS 2 CLI commands are now active:\\nros2 --help\\n# Expected Output: usage: ros2 [-h] Call \`ros2 <command> -h\` for more detailed usage. ...\\n\\n# Step 3: Verify the active ROS 2 distribution environment variable:\\nprintenv ROS_DISTRO\\n# Expected Output:\\n# jazzy\\n\\n# Step 4: Add sourcing permanently to your ~/.bashrc so every future terminal is automated:\\necho \\"source /opt/ros/jazzy/setup.bash\\" >> ~/.bashrc\\n</code></pre>\\n</div>\\n</p>\\n</div>\\n<div class=\\"alert-callout alert-note\\"><div class=\\"alert-icon\\"></div><div class=\\"alert-body\\"><strong>What about custom workspace sourcing?</strong><br><br>Sourcing custom project packages (<code class=\\"inline-code\\">source ~/ros2_ws/install/setup.bash</code>) is called the <strong>workspace overlay</strong>. In <strong>Lesson 03</strong>, you will create, build, and source your own custom robotics workspace from scratch!</div></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"9-verification-hello-world-smoke-test\\">9. Verification &amp; &quot;Hello World&quot; Smoke Test</h2>\\n<p>Run the built-in ROS 2 talker and listener demo nodes to verify that DDS peer discovery is operational.</p>\\n<div class=\\"alert-callout alert-tip\\"><div class=\\"alert-icon\\"></div><div class=\\"alert-body\\">Ensure ROS 2 is sourced in your active terminal before running these commands:<br><br><code class=\\"inline-code\\">source /opt/ros/jazzy/setup.bash</code> (or open a new terminal if you already added it to <code class=\\"inline-code\\">~/.bashrc</code> in Section 8.5).</div></div>\\n<h3 id=\\"step-91-launch-talker-node\\">Step 9.1: Launch Talker Node</h3>\\n<blockquote>\\n<p>[!SYNTAX]\\n<strong>Command Syntax:</strong> <code class=\\"inline-code\\">ros2 run &lt;package_name&gt; &lt;executable_name&gt;</code><br>\\n<strong>Description:</strong> Executes a compiled ROS 2 executable from an installed package. Starts the node process and begins publishing on DDS topics.</p>\\n</blockquote>\\n<p><strong>Hands-On Practical Command (Terminal 1):</strong></p>\\n<p><div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\"># 1. Ensure ROS 2 is sourced in this terminal:\\nsource /opt/ros/jazzy/setup.bash\\n\\n# 2. Start the talker publisher node:\\nros2 run demo_nodes_py talker\\n</code></pre>\\n</div>\\n</p>\\n<p><em>Expected Terminal Output:</em></p>\\n<p><div class=\\"code-container\\" data-language=\\"text\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">text</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-text\\">[INFO] [talker]: Publishing: &quot;Hello World: 1&quot;\\n[INFO] [talker]: Publishing: &quot;Hello World: 2&quot;\\n[INFO] [talker]: Publishing: &quot;Hello World: 3&quot;\\n</code></pre>\\n</div>\\n</p>\\n<hr class=\\"divider\\">\\n<h3 id=\\"step-92-launch-listener-node\\">Step 9.2: Launch Listener Node</h3>\\n<blockquote>\\n<p>[!SYNTAX]\\n<strong>Command Syntax:</strong> <code class=\\"inline-code\\">ros2 run &lt;package_name&gt; &lt;executable_name&gt;</code><br>\\n<strong>Description:</strong> Runs the subscriber node which dynamically discovers <code class=\\"inline-code\\">/talker</code> over local DDS multicast and prints received messages.</p>\\n</blockquote>\\n<p><strong>Hands-On Practical Command (Terminal 2):</strong></p>\\n<p><div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\"># 1. In a second terminal pane (e.g. Terminator Ctrl+Shift+O), ensure ROS 2 is sourced:\\nsource /opt/ros/jazzy/setup.bash\\n\\n# 2. Start the listener subscriber node:\\nros2 run demo_nodes_py listener\\n</code></pre>\\n</div>\\n</p>\\n<p><em>Expected Terminal Output:</em></p>\\n<p><div class=\\"code-container\\" data-language=\\"text\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">text</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-text\\">[INFO] [listener]: I heard: [Hello World: 1]\\n[INFO] [listener]: I heard: [Hello World: 2]\\n[INFO] [listener]: I heard: [Hello World: 3]\\n</code></pre>\\n</div>\\n</p>\\n<hr class=\\"divider\\">\\n<h3 id=\\"step-93-inspect-active-nodes-echo-topics\\">Step 9.3: Inspect Active Nodes &amp; Echo Topics</h3>\\n<blockquote>\\n<p>[!SYNTAX]\\n<strong>Command Syntax:</strong> <code class=\\"inline-code\\">ros2 node list</code>  |  <code class=\\"inline-code\\">ros2 topic list</code>  |  <code class=\\"inline-code\\">ros2 topic echo &lt;topic_name&gt;</code><br>\\n<strong>Description:</strong> Queries the DDS peer discovery bus to inspect live running nodes, active message topics, and echo real-time data packets in the terminal.</p>\\n</blockquote>\\n<p><strong>Hands-On Practical Command:</strong></p>\\n<p><div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\">ros2 node list\\n# Displays: /talker, /listener\\n\\nros2 topic list\\n# Displays: /chatter, /parameter_events, /rosout\\n\\nros2 topic echo /chatter\\n</code></pre>\\n</div>\\n</p>\\n<p><em>Expected Terminal Output:</em></p>\\n<p><div class=\\"code-container\\" data-language=\\"text\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">text</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-text\\">data: &#x27;Hello World: 4&#x27;\\n---\\ndata: &#x27;Hello World: 5&#x27;\\n---\\n</code></pre>\\n</div>\\n</p>\\n<hr class=\\"divider\\">\\n<h2 id=\\"10-summary-next-steps\\">10. Summary &amp; Next Steps</h2>\\n<p>You now have a fully operational, industry-grade ROS 2 Jazzy workstation. In <strong>Lesson 03</strong>, we will build our first custom ROS 2 workspace from scratch and write an object-oriented Python node with timers and logging!</p>\\n\\n<div class=\\"asset-handoff-card\\" style=\\"margin: 1.75rem 0 1rem 0; padding: 1.15rem 1.4rem; border-radius: 10px; background: rgba(16, 185, 129, 0.06); border: 1px solid rgba(16, 185, 129, 0.25); border-left: 4px solid #10b981;\\">\\n  <div style=\\"display: flex; align-items: center; gap: 0.5rem; margin-bottom: 0.5rem;\\">\\n    <span style=\\"font-size: 1.1rem;\\">📦</span>\\n    <strong style=\\"font-size: 0.95rem; color: #10b981; text-transform: uppercase; letter-spacing: 0.04em;\\">Asset Handoff &amp; Next Lesson Pipeline Bridge</strong>\\n  </div>\\n  <p style=\\"margin: 0 0 0.65rem 0; font-size: 0.88rem; color: var(--text-primary); line-height: 1.6;\\">\\n    You have verified your ROS 2 Jazzy installation, configured your bash environment underlays (/opt/ros/jazzy/setup.bash), and understood the DDS middleware communication architecture that replaces the legacy ROS 1 roscore.\\n  </p>\\n  <div style=\\"display: flex; flex-wrap: wrap; gap: 0.75rem; font-size: 0.82rem; font-family: var(--font-mono);\\">\\n    <span style=\\"background: var(--bg-surface); border: 1px solid var(--border-color); padding: 0.25rem 0.6rem; border-radius: 5px; color: var(--text-primary);\\">\\n      📁 <strong>Produced Artifact:</strong> <code>~/.bashrc</code> underlay sourcing &amp; verified ROS 2 Jazzy environment\\n    </span>\\n    <span style=\\"background: var(--bg-surface); border: 1px solid var(--border-color); padding: 0.25rem 0.6rem; border-radius: 5px; color: var(--text-primary);\\">\\n      ➡️ <strong>Ingested By:</strong> Lesson 03 (Turtlesim &amp; Core Architecture)\\n    </span>\\n  </div>\\n</div>\\n","quizzes":[{"id":"q_l1_02_1","prompt":"What primary architectural component replaces the centralized 'roscore' master from ROS 1 in ROS 2 Jazzy?","options":["A central Redis server running in Docker","The decentralized Data Distribution Service (DDS) discovery protocol","systemd service manager","The Linux D-Bus messaging broker"],"correct":1,"explanation":"ROS 2 is built on top of the OMG DDS standard. Discovery is fully decentralized using peer-to-peer multicast participant announcements, eliminating the single point of failure (roscore) present in ROS 1."},{"id":"q_l1_02_2","prompt":"Based on the 3-tier architectural comparison (Application, Middleware, OS), what is a fundamental difference in how ROS 2 handles the Middleware and OS layers compared to ROS 1?","options":["ROS 2 replaces Linux with its own proprietary bare-metal operating system kernel","ROS 2 introduces an Abstract DDS Layer (RMW) over standard DDS vendors (with an Intra-process API) and expands OS support to Linux, Windows, macOS, and RTOS","ROS 2 removes client libraries completely and forces all nodes to communicate strictly over raw TCPROS sockets","ROS 2 embeds the roscore Master process directly into the physical hardware microcontroller"],"correct":1,"explanation":"As illustrated in the ROS 1 vs. ROS 2 architecture layers, ROS 1 used custom TCPROS/UDPROS tied to a centralized Master and was strictly confined to Linux. In contrast, ROS 2 eliminates the Master, introduces an Abstract DDS Layer (RMW) over industry-standard DDS with an Intra-process zero-copy API, and natively runs across Linux, Windows, macOS, and real-time RTOS."}],"has_quiz":true,"next_id":"lesson_03","prev_id":"lesson_01","subtopics":[{"id":"1-overview-learning-objectives","title":"1. Overview &amp; Learning Objectives"},{"id":"2-hardware-and-software-prerequisites","title":"2. Hardware and Software Prerequisites"},{"id":"3-robotics-fundamentals-ros-2-architecture","title":"3. Robotics Fundamentals &amp; ROS 2 Architecture"},{"id":"4-ros-2-release-timeline","title":"4. ROS 2 Release Timeline"},{"id":"5-step-by-step-installation-on-ubuntu-2404-lts","title":"5. Step-by-Step Installation on Ubuntu 24.04 LTS"},{"id":"6-how-to-open-amp-use-the-desktop-gui-novnc-bull-port-6080","title":"6. How to Open &amp; Use the Desktop GUI (noVNC • Port 6080)"},{"id":"7-how-to-open-amp-use-in-browser-vs-code-ide-port-8443","title":"7. How to Open &amp; Use In-Browser VS Code IDE (Port 8443)"},{"id":"8-how-to-open-amp-use-the-terminal-desktop-hotkeys-terminator-amp-host-cli","title":"8. How to Open &amp; Use the Terminal (Desktop, Hotkeys, Terminator &amp; Host CLI)"},{"id":"9-verification-hello-world-smoke-test","title":"9. Verification &amp; &quot;Hello World&quot; Smoke Test"},{"id":"10-hands-on-student-challenge","title":"10. Hands-on Student Challenge: Multi-Robot Domain Isolation & RMW Environment Configuration"},{"id":"11-summary-next-steps","title":"11. Summary &amp; Next Steps"}]},{"id":"lesson_03","num":3,"num_str":"03","title":"Turtlesim Simulation & Essential ROS 2 CLI Tools","slug":"03_turtlesim_and_cli_mastery","filename":"03_turtlesim_and_cli_mastery.md","module":"Day 1: ROS 2 Foundations & Core Middleware","module_id":1,"duration":"45-60 min","focus":"Hands-On CLI Introspection, Graph Inspection & Moving Simulated Robots","snapshot":["Spin up a dual-node computational graph using turtlesim_node and turtle_teleop_key.","Inspect the live computational graph topology with rqt_graph.","Introspect active nodes, published topics, and dynamic message schemas.","Inject command velocity payloads using CLI ros2 topic pub."],"html_content":"<section class=\\"lesson-section\\">\\n<div class=\\"learning-objectives-card\\">\\n  <div class=\\"learning-objectives-header\\">\\n    <div class=\\"objectives-icon-badge\\">\\n      <span style=\\"font-size: 1.15rem; line-height: 1;\\">🎯</span>\\n    </div>\\n    <div class=\\"objectives-title-group\\">\\n      <h3 class=\\"objectives-main-title\\">Learning Objectives &amp; Core Outcomes</h3>\\n      <span class=\\"objectives-subtitle\\">By the end of this lesson, you will be able to:</span>\\n    </div>\\n    <span class=\\"objectives-count-badge\\">7 CORE OUTCOMES</span>\\n  </div>\\n  <ul class=\\"learning-objectives-list\\">\\n    <li class=\\"learning-objective-item\\">\\n      <span class=\\"objective-num-badge\\">1</span>\\n      <span class=\\"objective-text\\">Launch and interact with simulated robotic nodes using <code class=\\"inline-code\\">ros2 run</code>.</span>\\n    </li>\\n    <li class=\\"learning-objective-item\\">\\n      <span class=\\"objective-num-badge\\">2</span>\\n      <span class=\\"objective-text\\">Visualize the live peer-to-peer DDS computational graph with <code class=\\"inline-code\\">rqt_graph</code>.</span>\\n    </li>\\n    <li class=\\"learning-objective-item\\">\\n      <span class=\\"objective-num-badge\\">3</span>\\n      <span class=\\"objective-text\\">Inspect active nodes in the computation graph using <code class=\\"inline-code\\">ros2 node list</code> and <code class=\\"inline-code\\">ros2 node info</code>.</span>\\n    </li>\\n    <li class=\\"learning-objective-item\\">\\n      <span class=\\"objective-num-badge\\">4</span>\\n      <span class=\\"objective-text\\">Monitor data streams using <code class=\\"inline-code\\">ros2 topic list</code>, <code class=\\"inline-code\\">ros2 topic echo</code>, and <code class=\\"inline-code\\">ros2 topic hz</code>.</span>\\n    </li>\\n    <li class=\\"learning-objective-item\\">\\n      <span class=\\"objective-num-badge\\">5</span>\\n      <span class=\\"objective-text\\">Deconstruct interface definitions with <code class=\\"inline-code\\">ros2 topic type</code> and <code class=\\"inline-code\\">ros2 interface show</code>.</span>\\n    </li>\\n    <li class=\\"learning-objective-item\\">\\n      <span class=\\"objective-num-badge\\">6</span>\\n      <span class=\\"objective-text\\">Manually steer the robot by injecting velocity commands with <code class=\\"inline-code\\">ros2 topic pub</code>.</span>\\n    </li>\\n    <li class=\\"learning-objective-item\\">\\n      <span class=\\"objective-num-badge\\">7</span>\\n      <span class=\\"objective-text\\">Perform runtime parameter tuning, dynamic pen configuration, and emergency braking.</span>\\n    </li>\\n  </ul>\\n</div>\\n</section>\\n\\n<section class=\\"lesson-section\\">\\n<h2 id=\\"1-overview-learning-objectives\\">1. Overview &amp; Learning Objectives</h2>\\n<p>Before writing code from scratch, professional robotics engineers first master live runtime introspection tools. In this lesson, you will interact with <strong>Turtlesim</strong>—the canonical robotics simulation sandbox built into ROS 2—and drive a simulated robot purely from the terminal while introspecting its underlying computational graph.</p>\\n</section>\\n\\n<section class=\\"lesson-section\\">\\n<h2 id=\\"2-launching-turtlesim-the-simulation-playground\\">2. Launching Turtlesim: The Simulation Playground</h2>\\n<p>Turtlesim provides a visual 2D simulation canvas representing a differential-drive robot (<code class=\\"inline-code\\">/turtle1</code>). It exposes topics for velocity control, pose telemetry, color sensor feeds, and services for resets and pen drawing.</p>\\n<p><strong>Terminal 1: Launch Turtlesim Simulation Canvas Node</strong></p>\\n<div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\">ros2 run turtlesim turtlesim_node</code></pre>\\n</div>\\n<p>A blue graphic window will appear displaying a small turtle sitting at the center of a coordinate grid (x = 5.54, y = 5.54, &theta; = 0.0 rad).</p>\\n<p class=\\"lesson-image-wrapper\\"><img src=\\"assets/images/turtlesim_simulation_canvas.png\\" alt=\\"Turtlesim 2D Graphic Simulation Canvas\\" title=\\"Turtlesim Simulation Window with live turtle graphic (/turtle1)\\" class=\\"lesson-image\\" loading=\\"lazy\\" style=\\"max-height: 380px; object-fit: contain;\\" /></p>\\n<p><strong>Terminal 2: Launch Keyboard Teleoperation Node</strong></p>\\n<div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\">ros2 run turtlesim turtle_teleop_key</code></pre>\\n</div>\\n<p>With the second terminal focused, press the arrow keys. You will see the turtle drive, turn, and draw an ink trail across the canvas.</p>\\n<p class=\\"lesson-image-wrapper\\"><img src=\\"assets/images/turtle_teleop_key_running.png\\" alt=\\"Turtle Teleop Key Running in Terminal\\" title=\\"Keyboard Teleoperation Node (turtle_teleop_key) reading arrow keys\\" class=\\"lesson-image\\" loading=\\"lazy\\" style=\\"max-height: 320px; object-fit: contain;\\" /></p>\\n\\n<div id=\\"turtlesim-teleop-flow-root\\"></div>\\n</section>\\n\\n<section class=\\"lesson-section\\">\\n<h2 id=\\"3-visualizing-the-computational-graph-rqt_graph\\">3. Visualizing the Computational Graph (<code class=\\"inline-code\\">rqt_graph</code>)</h2>\\n<p>Now that you have seen the conceptual peer-to-peer data flow in the simulation above, let's verify it in real time! ROS 2 provides an interactive GUI tool called <code class=\\"inline-code\\">rqt_graph</code> that introspects the active DDS middleware network and renders the live computational graph.</p>\\n<p>In a new terminal window, launch <code class=\\"inline-code\\">rqt_graph</code> (you can run either command):</p>\\n<p><strong>Terminal 3: Launch Computational Graph Visualizer</strong></p>\\n<div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\">rqt_graph</code></pre>\\n</div>\\n<div class=\\"alert-callout alert-note\\">\\n<div class=\\"alert-icon\\"></div>\\n<div class=\\"alert-body\\"><strong>ROS 2 Command Tip:</strong> In ROS 2, you can launch GUI tools either directly by executable name (<code class=\\"inline-code\\">rqt_graph</code>) or through the ROS 2 package runner (<code class=\\"inline-code\\">ros2 run rqt_graph rqt_graph</code>). If a terminal ever reports command not found, ensure ROS 2 is sourced with <code class=\\"inline-code\\">source /opt/ros/jazzy/setup.bash</code>.</div>\\n</div>\\n<p class=\\"lesson-image-wrapper\\"><img src=\\"assets/images/turtlesim_rqt_graph.png\\" alt=\\"rqt_graph Computational Graph Visualization\\" title=\\"rqt_graph live visualization showing node /teleop_turtle publishing /turtle1/cmd_vel to /turtlesim node\\" class=\\"lesson-image\\" loading=\\"lazy\\" style=\\"max-height: 420px; object-fit: contain;\\" /></p>\\n<p>The GUI visualizer will display the exact communication topology between your two active processes:</p>\\n<div class=\\"code-container\\" data-language=\\"text\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">text</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-text\\">   [ /teleop_turtle ] --------(/turtle1/cmd_vel)--------&gt; [ /turtlesim ]</code></pre>\\n</div>\\n<ul>\\n<li><strong>Ovals</strong> represent active <strong>Nodes</strong> (executable processes like <code class=\\"inline-code\\">/teleop_turtle</code> and <code class=\\"inline-code\\">/turtlesim</code>).</li>\\n<li><strong>Rectangles / Arrows</strong> represent active <strong>Topics</strong> routing data packets (<code class=\\"inline-code\\">/turtle1/cmd_vel</code>) between publishers and subscribers.</li>\\n<li>If a node is not connected to a topic arrow, it indicates an interface mismatch or a topic name typo.</li>\\n</ul>\\n<p>Keep this mental model in mind as we now explore the command-line introspection tools to inspect each node, topic, and message interface individually.</p>\\n</section>\\n\\n<section class=\\"lesson-section\\">\\n<h2 id=\\"4-core-concept-1-node-introspection-ros2-node\\">4. Core Concept 1: Node Introspection (<code class=\\"inline-code\\">ros2 node</code>)</h2>\\n<p>In ROS 2, every distinct robotic software function (perception, planning, motor control) runs as an isolated process called a <strong>Node</strong>.</p>\\n<p>Open a third terminal and query all currently active nodes:</p>\\n<div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\">ros2 node list</code></pre>\\n</div>\\n<p><strong>Output:</strong></p>\\n<div class=\\"code-container\\" data-language=\\"text\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">text</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-text\\">/teleop_turtle\\n/turtlesim</code></pre>\\n</div>\\n<p>To inspect everything a node produces, consumes, or exposes, use <code class=\\"inline-code\\">ros2 node info</code>:</p>\\n<div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\">ros2 node info /turtlesim</code></pre>\\n</div>\\n<p><strong>Output Breakdown:</strong></p>\\n<div class=\\"code-container\\" data-language=\\"yaml\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">yaml</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-yaml\\">/turtlesim\\n  Subscribers:\\n    /turtle1/cmd_vel: geometry_msgs/msg/Twist    &lt;-- Receives velocity commands\\n  Publishers:\\n    /parameter_events: rcl_interfaces/msg/ParameterEvent\\n    /rosout: rcl_interfaces/msg/Log\\n    /turtle1/color_sensor: turtlesim/msg/Color  &lt;-- Emits background color under turtle\\n    /turtle1/pose: turtlesim/msg/Pose          &lt;-- Emits (x, y, theta, linear_velocity)\\n  Service Servers:\\n    /clear: std_srvs/srv/Empty                  &lt;-- Clears screen ink trails\\n    /reset: std_srvs/srv/Empty                  &lt;-- Resets turtle to origin\\n    /spawn: turtlesim/srv/Spawn                &lt;-- Spawns a second turtle\\n    /turtle1/set_pen: turtlesim/srv/SetPen      &lt;-- Changes ink color &amp; thickness</code></pre>\\n</div>\\n\\n<div class=\\"alert-callout alert-tip\\">\\n<div class=\\"alert-icon\\"></div>\\n<div class=\\"alert-body\\"><strong>Production Takeaway:</strong> Whenever an autonomous robot fails to respond to movement commands, your first diagnostic step in production is running <code class=\\"inline-code\\">ros2 node list</code> and <code class=\\"inline-code\\">ros2 node info &lt;node&gt;</code> to confirm the motor driver node is alive and subscribing to the correct topic.</div>\\n</div>\\n</section>\\n\\n<section class=\\"lesson-section\\">\\n<h2 id=\\"5-core-concept-2-topic-introspection-ros2-topic\\">5. Core Concept 2: Topic Introspection (<code class=\\"inline-code\\">ros2 topic</code>)</h2>\\n<p>Nodes do not talk directly to one another. Instead, they publish and subscribe to named message buses called <strong>Topics</strong>.</p>\\n\\n<h3 id=\\"51-listing-topics\\">5.1 Listing Topics</h3>\\n<div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\">ros2 topic list</code></pre>\\n</div>\\n<p>To see both the topic names and their message data types simultaneously, add the <code class=\\"inline-code\\">-t</code> flag:</p>\\n<div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\">ros2 topic list -t</code></pre>\\n</div>\\n<p><strong>Output:</strong></p>\\n<div class=\\"code-container\\" data-language=\\"text\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">text</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-text\\">/parameter_events [rcl_interfaces/msg/ParameterEvent]\\n/rosout [rcl_interfaces/msg/Log]\\n/turtle1/cmd_vel [geometry_msgs/msg/Twist]\\n/turtle1/color_sensor [turtlesim/msg/Color]\\n/turtle1/pose [turtlesim/msg/Pose]</code></pre>\\n</div>\\n\\n<h3 id=\\"52-echoing-live-data-ros2-topic-echo\\">5.2 Echoing Live Data (<code class=\\"inline-code\\">ros2 topic echo</code>)</h3>\\n<p>To listen in real-time to the pose updates emitted by the simulated robot, run:</p>\\n<div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\">ros2 topic echo /turtle1/pose</code></pre>\\n</div>\\n<p>Now drive the turtle using the teleop keys. You will see coordinates stream in real time:</p>\\n<div class=\\"code-container\\" data-language=\\"yaml\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">yaml</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-yaml\\">x: 5.820444583892822\\ny: 5.544444561004639\\ntheta: 0.0\\nlinear_velocity: 0.0\\nangular_velocity: 0.0\\n---</code></pre>\\n</div>\\n\\n<h3 id=\\"53-measuring-topic-publishing-frequency-ros2-topic-hz\\">5.3 Measuring Topic Publishing Frequency (<code class=\\"inline-code\\">ros2 topic hz</code>)</h3>\\n<p>Robotics control loops require deterministic frequencies. You can audit how frequently a sensor is publishing:</p>\\n<div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\">ros2 topic hz /turtle1/pose</code></pre>\\n</div>\\n<p><strong>Output:</strong></p>\\n<div class=\\"code-container\\" data-language=\\"text\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">text</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-text\\">average rate: 62.503\\n\\tmin: 0.015s max: 0.017s std dev: 0.00049s window: 64</code></pre>\\n</div>\\n<p><em>Turtlesim publishes pose updates at ~62.5 Hz.</em></p>\\n</section>\\n\\n<section class=\\"lesson-section\\">\\n<h2 id=\\"6-core-concept-3-topic-interface-types-ros2-interface\\">6. Core Concept 3: Topic Interface Types (<code class=\\"inline-code\\">ros2 interface</code>)</h2>\\n<p>Every topic requires a strictly typed contract defined in ROS 2 IDL (Interface Definition Language).</p>\\n<p>Notice that <code class=\\"inline-code\\">/turtle1/cmd_vel</code> uses the type <code class=\\"inline-code\\">geometry_msgs/msg/Twist</code>. What fields does that message actually contain?</p>\\n<p>Query the interface definition directly:</p>\\n<div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\">ros2 interface show geometry_msgs/msg/Twist</code></pre>\\n</div>\\n<p><strong>Output:</strong></p>\\n<div class=\\"code-container\\" data-language=\\"text\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">text</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-text\\"># This expresses velocity in free space broken into its linear and angular parts.\\n\\nVector3  linear\\n\\tfloat64 x\\n\\tfloat64 y\\n\\tfloat64 z\\nVector3  angular\\n\\tfloat64 x\\n\\tfloat64 y\\n\\tfloat64 z</code></pre>\\n</div>\\n<p>For a ground robot (differential drive AMR or Turtle), <code class=\\"inline-code\\">linear.x</code> moves forward/backward, and <code class=\\"inline-code\\">angular.z</code> steers left/right.</p>\\n</section>\\n\\n<section class=\\"lesson-section\\">\\n<h2 id=\\"7-moving-the-robot-hands-on-via-cli-ros2-topic-pub\\">7. Moving the Robot Hands-On via CLI (<code class=\\"inline-code\\">ros2 topic pub</code>)</h2>\\n<p>You do not need a teleop node or a Python script to command a robot. You can inject messages directly onto any topic using <code class=\\"inline-code\\">ros2 topic pub</code>.</p>\\n\\n<h3 id=\\"71-move-forward-once-once\\">7.1 Move Forward Once (<code class=\\"inline-code\\">--once</code>)</h3>\\n<p>Command the robot to move forward at 2.0 m/s for one single timestep:</p>\\n<div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\">ros2 topic pub --once /turtle1/cmd_vel geometry_msgs/msg/Twist \\"{linear: {x: 2.0, y: 0.0, z: 0.0}, angular: {x: 0.0, y: 0.0, z: 0.0}}\\"</code></pre>\\n</div>\\n<p>Notice the turtle surges forward and then comes to a stop.</p>\\n\\n<h3 id=\\"72-drive-in-a-continuous-circle-r-10\\">7.2 Drive in a Continuous Circle (<code class=\\"inline-code\\">-r 10</code>)</h3>\\n<p>To command the robot to drive in a continuous circle, publish velocity commands at a steady rate of 10 Hz (<code class=\\"inline-code\\">-r 10</code>):</p>\\n<div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\">ros2 topic pub -r 10 /turtle1/cmd_vel geometry_msgs/msg/Twist \\"{linear: {x: 2.0, y: 0.0, z: 0.0}, angular: {x: 0.0, y: 0.0, z: 1.8}}\\"</code></pre>\\n</div>\\n<p>The turtle will drive in a circular loop, drawing an ink circle. Press <kbd>Ctrl + C</kbd> in the terminal to stop publishing.</p>\\n</section>\\n\\n<section class=\\"lesson-section\\">\\n<h2 id=\\"8-summary-comparison-table-of-essential-cli-tools\\">8. Summary Comparison Table of Essential CLI Tools</h2>\\n<div class=\\"table-responsive\\"><table>\\n<thead>\\n<tr>\\n<th>Command</th>\\n<th>Purpose</th>\\n<th>Production Use Case</th>\\n</tr>\\n</thead>\\n<tbody>\\n<tr>\\n<td><code class=\\"inline-code\\">rqt_graph</code></td>\\n<td>Visualizes computational graph nodes and topic wiring</td>\\n<td>Auditing network communication topology and detecting disconnected nodes</td>\\n</tr>\\n<tr>\\n<td><code class=\\"inline-code\\">ros2 run &lt;pkg&gt; &lt;executable&gt;</code></td>\\n<td>Launches a specific executable node from a package</td>\\n<td>Starting drivers, simulators, or single test scripts</td>\\n</tr>\\n<tr>\\n<td><code class=\\"inline-code\\">ros2 node list</code></td>\\n<td>Lists all active nodes across the network</td>\\n<td>Auditing if all expected subsystem nodes are alive</td>\\n</tr>\\n<tr>\\n<td><code class=\\"inline-code\\">ros2 node info &lt;node&gt;</code></td>\\n<td>Details subscribers, publishers, services, and actions</td>\\n<td>Verifying interface names and endpoint wiring</td>\\n</tr>\\n<tr>\\n<td><code class=\\"inline-code\\">ros2 topic list -t</code></td>\\n<td>Lists all active topics with their message types</td>\\n<td>Discovering sensor and telemetry buses</td>\\n</tr>\\n<tr>\\n<td><code class=\\"inline-code\\">ros2 topic echo &lt;topic&gt;</code></td>\\n<td>Prints incoming message payloads to the console</td>\\n<td>Live debugging of sensor values or trajectory points</td>\\n</tr>\\n<tr>\\n<td><code class=\\"inline-code\\">ros2 topic hz &lt;topic&gt;</code></td>\\n<td>Measures publish rate in Hertz</td>\\n<td>Verifying camera / LiDAR sensor update rates</td>\\n</tr>\\n<tr>\\n<td><code class=\\"inline-code\\">ros2 interface show &lt;type&gt;</code></td>\\n<td>Shows message fields and structural types</td>\\n<td>Inspecting data format before writing Python code</td>\\n</tr>\\n<tr>\\n<td><code class=\\"inline-code\\">ros2 topic pub &lt;topic&gt; &lt;type&gt; &lt;yaml&gt;</code></td>\\n<td>Injects messages onto a topic from the CLI</td>\\n<td>Testing actuators or emergency stop commands</td>\\n</tr>\\n</tbody>\\n</table></div>\\n</section>\\n\\n<section class=\\"lesson-section\\">\\n<h2 id=\\"9-hands-on-student-challenge-turtlesim-operations\\">9. Hands-On Student Lab: The Turtlesim Operations Mission</h2>\\n\\n<div class=\\"alert alert-info\\">\\n  <div class=\\"alert-icon\\">🎯</div>\\n  <div class=\\"alert-content\\">\\n    <div class=\\"alert-title\\">Robotics Flight Operations Mission Briefing</div>\\n    <div class=\\"alert-body\\">\\n      As an autonomous robotics software engineer, you rarely touch physical buttons on a robot. Instead, you orchestrate sensors, motors, and runtime graphs entirely through the command-line interface.\\n      <br><br>\\n      In this comprehensive student lab, you will apply the complete suite of ROS 2 CLI tools (<strong>ros2 run</strong>, <strong>ros2 node</strong>, <strong>ros2 topic</strong>, <strong>ros2 service</strong>, and <strong>ros2 param</strong>) to dynamically reconfigure the simulation environment, inspect parameter servers, and customize robot properties at runtime!\\n    </div>\\n  </div>\\n</div>\\n\\n<h3 id=\\"environment-calibration-dynamic-reconfiguration\\">Environment Calibration &amp; Dynamic Reconfiguration</h3>\\n<p>Professional robotics testbeds allow engineers to adjust simulation parameters on the fly without recompiling or restarting nodes. First, calibrate your simulation canvas and robot pen:</p>\\n\\n<ol>\\n<li>Launch Turtlesim in your desktop simulation window (if not already running):</li>\\n</ol>\\n<div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\">ros2 run turtlesim turtlesim_node</code></pre>\\n</div>\\n\\n<ol start=\\"2\\">\\n<li>In your terminal, list all parameters exposed by the <code class=\\"inline-code\\">/turtlesim</code> node:</li>\\n</ol>\\n<div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\">ros2 param list /turtlesim</code></pre>\\n</div>\\n\\n<ol start=\\"3\\">\\n<li>Switch the canvas from default blue to a professional <strong>Night-Ops Dark Navy</strong> theme (<code class=\\"inline-code\\">#0f172a</code> &rarr; RGB: 15, 23, 42):</li>\\n</ol>\\n<div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\">ros2 param set /turtlesim background_r 15\\nros2 param set /turtlesim background_g 23\\nros2 param set /turtlesim background_b 42</code></pre>\\n</div>\\n\\n<ol start=\\"4\\">\\n<li>Parameters update internal state, but Turtlesim requires a background clear request to re-render. Invoke the <code class=\\"inline-code\\">/clear</code> service:</li>\\n</ol>\\n<div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\">ros2 service call /clear std_srvs/srv/Empty</code></pre>\\n</div>\\n<p>Observe the simulation canvas instantly transform into a sleek dark background!</p>\\n\\n<ol start=\\"5\\">\\n<li>Reconfigure <code class=\\"inline-code\\">turtle1</code>'s pen to draw high-visibility neon electric cyan ink with a crisp <strong>4 px</strong> line width:</li>\\n</ol>\\n<div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\">ros2 service call /turtle1/set_pen turtlesim/srv/SetPen \\"{r: 56, g: 189, b: 248, width: 4, 'off': 0}\\"</code></pre>\\n</div>\\n\\n<div class=\\"alert alert-tip\\" style=\\"margin-top: 1.5rem;\\">\\n  <div class=\\"alert-icon\\">🏆</div>\\n  <div class=\\"alert-content\\">\\n    <div class=\\"alert-title\\">Mission Complete: Key Competencies Mastered</div>\\n    <div class=\\"alert-body\\">\\n      Congratulations! You have verified the essential CLI command families that make up daily ROS 2 engineering practice:\\n      <ul>\\n        <li><strong>Node Control:</strong> Inspected active graph participants (<code class=\\"inline-code\\">ros2 node list/info</code>).</li>\\n        <li><strong>Topic Telemetry:</strong> Listened to sensor streams and validated frequency clocks (<code class=\\"inline-code\\">ros2 topic echo/hz</code>).</li>\\n        <li><strong>Actuator Commands:</strong> Broadcast streaming velocity vectors (<code class=\\"inline-code\\">ros2 topic pub -r 10</code>) and executed emergency braking (<code class=\\"inline-code\\">Twist \\"{}\\"</code>).</li>\\n        <li><strong>Service Invocations:</strong> Called discrete request-response triggers (<code class=\\"inline-code\\">/set_pen</code>, <code class=\\"inline-code\\">/clear</code>).</li>\\n        <li><strong>Dynamic Parameters:</strong> Reconfigured node parameters on the fly without restarting (<code class=\\"inline-code\\">ros2 param set</code>).</li>\\n      </ul>\\n      You are now prepared to progress to Lesson 04 to architect your first <strong>ROS 2 Workspace</strong> and build production packages!\\n    </div>\\n  </div>\\n</div>\\n\\n\\n<div class=\\"asset-handoff-card\\" style=\\"margin: 1.75rem 0 1rem 0; padding: 1.15rem 1.4rem; border-radius: 10px; background: rgba(16, 185, 129, 0.06); border: 1px solid rgba(16, 185, 129, 0.25); border-left: 4px solid #10b981;\\">\\n  <div style=\\"display: flex; align-items: center; gap: 0.5rem; margin-bottom: 0.5rem;\\">\\n    <span style=\\"font-size: 1.1rem;\\">📦</span>\\n    <strong style=\\"font-size: 0.95rem; color: #10b981; text-transform: uppercase; letter-spacing: 0.04em;\\">Asset Handoff &amp; Next Lesson Pipeline Bridge</strong>\\n  </div>\\n  <p style=\\"margin: 0 0 0.65rem 0; font-size: 0.88rem; color: var(--text-primary); line-height: 1.6;\\">\\n    You have interacted with live ROS 2 computational graphs, mapped node-to-topic data flows, and inspected velocity command streams (/turtle1/cmd_vel) driving the Turtlesim graphics simulator.\\n  </p>\\n  <div style=\\"display: flex; flex-wrap: wrap; gap: 0.75rem; font-size: 0.82rem; font-family: var(--font-mono);\\">\\n    <span style=\\"background: var(--bg-surface); border: 1px solid var(--border-color); padding: 0.25rem 0.6rem; border-radius: 5px; color: var(--text-primary);\\">\\n      📁 <strong>Produced Artifact:</strong> Introspected computational graph flow (<code>ros2 node list</code>, <code>ros2 topic echo /turtle1/cmd_vel</code>)\\n    </span>\\n    <span style=\\"background: var(--bg-surface); border: 1px solid var(--border-color); padding: 0.25rem 0.6rem; border-radius: 5px; color: var(--text-primary);\\">\\n      ➡️ <strong>Ingested By:</strong> Lesson 04 (Package Creation &amp; Anatomy)\\n    </span>\\n  </div>\\n</div>\\n\\n</section>\\n","quizzes":[{"id":"q_l1_03_1","prompt":"Which ROS 2 CLI command is used to inspect all publishers, subscribers, services, and actions associated with a running node?","options":["ros2 topic list","ros2 node info <node_name>","ros2 doctor --report","ros2 pkg xml"],"correct":1,"explanation":"ros2 node info <node_name> provides complete introspection into a node's active subscriptions, publishers, service servers, and action clients/servers."},{"id":"q_l1_03_2","prompt":"In the geometry_msgs/msg/Twist interface, which field controls the forward and backward linear velocity of a ground robot?","options":["linear.y","linear.z","linear.x","angular.x"],"correct":2,"explanation":"In ROS 2 spatial conventions, linear.x represents forward/reverse surge velocity along the robot's longitudinal axis."}],"has_quiz":true,"next_id":"lesson_04","prev_id":"lesson_02","subtopics":[{"id":"1-overview-learning-objectives","title":"1. Overview &amp; Learning Objectives"},{"id":"2-launching-turtlesim-the-simulation-playground","title":"2. Launching Turtlesim: The Simulation Playground"},{"id":"3-visualizing-the-computational-graph-rqt_graph","title":"3. Visualizing the Computational Graph (rqt_graph)"},{"id":"4-core-concept-1-node-introspection-ros2-node","title":"4. Core Concept 1: Node Introspection (ros2 node)"},{"id":"5-core-concept-2-topic-introspection-ros2-topic","title":"5. Core Concept 2: Topic Introspection (ros2 topic)"},{"id":"6-core-concept-3-topic-interface-types-ros2-interface","title":"6. Core Concept 3: Topic Interface Types (ros2 interface)"},{"id":"7-moving-the-robot-hands-on-via-cli-ros2-topic-pub","title":"7. Moving the Robot Hands-On via CLI (ros2 topic pub)"},{"id":"8-summary-comparison-table-of-essential-cli-tools","title":"8. Summary Comparison Table of Essential CLI Tools"},{"id":"9-hands-on-student-challenge-turtlesim-operations","title":"9. Hands-On Student Lab: The Turtlesim Operations Mission"}]},{"id":"lesson_04","num":4,"num_str":"04","title":"ROS 2 Workspace & Package Architecture Deep Dive","slug":"04_ros2_workspace_and_package_architecture","filename":"04_ros2_workspace_and_package_architecture.md","module":"Day 1: ROS 2 Foundations & Core Middleware","module_id":1,"duration":"45-60 min","focus":"Workspace Anatomy, Overlay Sourcing & ament_python Package Creation","snapshot":[["4 Workspace Directories","src/ contains editable source code; build/, install/, and log/ are generated by colcon."],["Underlay vs Overlay","System binaries reside in /opt/ros/jazzy; your overlay in ~/ros2_ws extends them without OS risk."],["Ament Package Anatomy","Packages require package.xml for dependencies, setup.py for entry points, and resource/ marker."],["Dependency Resolution","rosdep install automatically scans package.xml manifests and resolves system-level APT dependencies."]],"html_content":"<section class=\\"lesson-section\\">\\n<div class=\\"learning-objectives-card\\">\\n  <div class=\\"learning-objectives-header\\">\\n    <div class=\\"objectives-icon-badge\\">\\n      <span style=\\"font-size: 1.15rem; line-height: 1;\\">🎯</span>\\n    </div>\\n    <div class=\\"objectives-title-group\\">\\n      <h3 class=\\"objectives-main-title\\">Learning Objectives &amp; Core Outcomes</h3>\\n      <span class=\\"objectives-subtitle\\">By the end of this lesson, you will be able to:</span>\\n    </div>\\n    <span class=\\"objectives-count-badge\\">7 CORE OUTCOMES</span>\\n  </div>\\n  <ul class=\\"learning-objectives-list\\">\\n    <li class=\\"learning-objective-item\\">\\n      <span class=\\"objective-num-badge\\">1</span>\\n      <span class=\\"objective-text\\">Understand the four core workspace directories: <code class=\\"inline-code\\">src/</code>, <code class=\\"inline-code\\">build/</code>, <code class=\\"inline-code\\">install/</code>, and <code class=\\"inline-code\\">log/</code>.</span>\\n    </li>\\n    <li class=\\"learning-objective-item\\">\\n      <span class=\\"objective-num-badge\\">2</span>\\n      <span class=\\"objective-text\\">Master the difference between the <strong>Underlay</strong> (<code class=\\"inline-code\\">/opt/ros/jazzy</code>) and your development <strong>Overlay</strong> (<code class=\\"inline-code\\">~/ros2_ws</code>).</span>\\n    </li>\\n    <li class=\\"learning-objective-item\\">\\n      <span class=\\"objective-num-badge\\">3</span>\\n      <span class=\\"objective-text\\">Build workspaces using <code class=\\"inline-code\\">colcon build</code> and source them correctly.</span>\\n    </li>\\n    <li class=\\"learning-objective-item\\">\\n      <span class=\\"objective-num-badge\\">4</span>\\n      <span class=\\"objective-text\\">Understand package anatomy (<code class=\\"inline-code\\">package.xml</code>, <code class=\\"inline-code\\">setup.py</code>, <code class=\\"inline-code\\">setup.cfg</code>, <code class=\\"inline-code\\">resource/</code>).</span>\\n    </li>\\n    <li class=\\"learning-objective-item\\">\\n      <span class=\\"objective-num-badge\\">5</span>\\n      <span class=\\"objective-text\\">Use package introspection CLI commands (<code class=\\"inline-code\\">ros2 pkg list</code>, <code class=\\"inline-code\\">ros2 pkg prefix</code>, <code class=\\"inline-code\\">ros2 pkg xml</code>).</span>\\n    </li>\\n    <li class=\\"learning-objective-item\\">\\n      <span class=\\"objective-num-badge\\">6</span>\\n      <span class=\\"objective-text\\">Resolve workspace dependencies automatically using <code class=\\"inline-code\\">rosdep install --from-paths src --ignore-src -y</code>.</span>\\n    </li>\\n    <li class=\\"learning-objective-item\\">\\n      <span class=\\"objective-num-badge\\">7</span>\\n      <span class=\\"objective-text\\">Scaffold, build, and verify a ROS 2 Python package using <code class=\\"inline-code\\">ros2 pkg create</code>.</span>\\n    </li>\\n  </ul>\\n</div>\\n</section>\\n\\n<section class=\\"lesson-section\\">\\n<h2 id=\\"1-overview-learning-objectives\\">1. Overview &amp; Learning Objectives</h2>\\n<p>Now that you have seen active nodes, topics, and simulation in action, you are ready to build software. In ROS 2, code cannot exist as loose, standalone Python scripts. All production robotics nodes, launch files, parameter configurations, and URDF models must be developed inside a <strong>Workspace</strong> and organized within <strong>Packages</strong>.</p>\\n</section>\\n\\n<section class=\\"lesson-section\\">\\n<h2 id=\\"2-the-ros-2-workspace-architecture\\">2. The ROS 2 Workspace Architecture</h2>\\n<p>A <strong>Workspace</strong> is a dedicated directory on your filesystem where you write, compile, and install custom ROS 2 software. All ROS 2 workspaces follow a strict four-directory hierarchy:</p>\\n\\n<p><img src=\\"assets/images/ros2_workspace_tree.svg\\" alt=\\"ROS 2 Workspace Hierarchy\\" class=\\"lesson-image\\" loading=\\"lazy\\" /></p>\\n\\n<h3 id=\\"key-directory-guide-for-ros2-workspaces\\">Key Directory Guide for ROS 2 Workspaces</h3>\\n<div class=\\"info-grid\\">\\n  <div class=\\"info-card\\">\\n    <div class=\\"card-icon\\">📁</div>\\n    <h4><code>src/</code> (Source Code)</h4>\\n    <p>This is the <strong>only directory you write code in</strong>. You clone git repositories, scaffold packages, and edit Python and C++ source files here.</p>\\n  </div>\\n  <div class=\\"info-card\\">\\n    <div class=\\"card-icon\\">⚙️</div>\\n    <h4><code>build/</code> (Build Artifacts)</h4>\\n    <p>Created automatically by <code>colcon</code>. Stores intermediate build caches, object files, and build configuration files. Never edit files in this folder manually.</p>\\n  </div>\\n  <div class=\\"info-card\\">\\n    <div class=\\"card-icon\\">🚀</div>\\n    <h4><code>install/</code> (Installed Runtime)</h4>\\n    <p>Where <code>colcon</code> places executable scripts, shared libraries, installed launch files, and the critical <code>setup.bash</code> sourcing script. ROS 2 executes programs directly from here.</p>\\n  </div>\\n  <div class=\\"info-card\\">\\n    <div class=\\"card-icon\\">📊</div>\\n    <h4><code>log/</code> (Logging &amp; Diagnostics)</h4>\\n    <p>Contains timestamped execution logs of every <code>colcon build</code> run, invaluable for diagnosing failed builds and missing dependencies.</p>\\n  </div>\\n</div>\\n</section>\\n\\n<section class=\\"lesson-section\\">\\n<h2 id=\\"3-underlays-vs-overlays-the-environment-chaining-model\\">3. Underlays vs. Overlays: The Environment Chaining Model</h2>\\n<p>ROS 2 uses an <strong>overlay</strong> mechanism to protect operating system software from custom project changes:</p>\\n\\n<p><img src=\\"assets/images/ros2_overlay_underlay.svg\\" alt=\\"ROS 2 Overlay vs Underlay Architecture\\" class=\\"lesson-image\\" loading=\\"lazy\\" /></p>\\n\\n<ul>\\n<li><strong>The Underlay (<code class=\\"inline-code\\">/opt/ros/jazzy</code>):</strong> The system-level ROS 2 installation. Contains core tools (<code class=\\"inline-code\\">ros2</code>, <code class=\\"inline-code\\">rclpy</code>), standard message definitions (<code class=\\"inline-code\\">geometry_msgs</code>), and pre-compiled robotics stacks (Nav2).</li>\\n<li><strong>The Overlay (<code class=\\"inline-code\\">~/ros2_ws</code>):</strong> Your private development workspace. When you source <code class=\\"inline-code\\">~/ros2_ws/install/setup.bash</code>, your workspace <em>overlays</em> on top of the underlay. If you create a custom package with the same name as a system package, your overlay version takes precedence without modifying or breaking <code class=\\"inline-code\\">/opt/ros/jazzy</code>.</li>\\n</ul>\\n</section>\\n\\n<section class=\\"lesson-section\\">\\n<h2 id=\\"4-initializing-building-a-workspace\\">4. Initializing &amp; Building a Workspace</h2>\\n<p>Follow these steps directly in your terminal to create and build your first workspace:</p>\\n\\n<h3 id=\\"step-41-create-the-workspace-directory\\">Step 4.1: Create the Workspace Directory</h3>\\n<p>Create the source directory where your ROS 2 packages will live, and immediately verify it:</p>\\n<div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\"># 1. Create workspace source directory:\\nmkdir -p ~/ros2_ws/src\\n\\n# 2. Immediate verification:\\nls ~/ros2_ws\\n# Expected Output:\\n# src</code></pre>\\n</div>\\n\\n<h3 id=\\"step-42-build-the-empty-workspace-with-colcon\\">Step 4.2: Build the Empty Workspace with <code class=\\"inline-code\\">colcon</code></h3>\\n\\n<div class=\\"alert-callout alert-info\\" style=\\"margin-bottom: 1.25rem;\\">\\n<div class=\\"alert-icon\\">🛠️</div>\\n<div class=\\"alert-body\\">\\n  <strong>What is <code>colcon</code>?</strong><br>\\n  <code>colcon</code> stands for <strong>col</strong>lective <strong>con</strong>struction. It is the official command-line meta-build tool for ROS 2 (replacing ROS 1's <code>catkin_make</code> and <code>catkin build</code>). A robotics workspace is heterogeneous: it mixes pure Python packages (<code>ament_python</code>), C++ packages (<code>ament_cmake</code>), and custom message interface definitions. <code>colcon</code> inspects the <code>package.xml</code> of every package in <code>src/</code>, calculates the exact dependency build order, and orchestrates the underlying native build engines (<code>setuptools</code> for Python, <code>cmake</code>/<code>ninja</code> for C++) automatically.\\n</div>\\n</div>\\n\\n<p>Navigate to the workspace root. <em>Remember: <code>colcon</code> must always be executed from the workspace root (<code>~/ros2_ws</code>), never inside <code>src/</code>!</em></p>\\n<div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\">cd ~/ros2_ws\\ncolcon build\\n\\n# Expected Output:\\n# Summary: 0 packages finished [0.25s]</code></pre>\\n</div>\\n\\n<div class=\\"code-breakdown-card\\" style=\\"margin: 1.25rem 0;\\">\\n  <h4 class=\\"code-breakdown-title\\">⚙️ What Happens Under the Hood During <code>colcon build</code>?</h4>\\n  <p class=\\"code-breakdown-intro\\">When you execute <code>colcon build</code> from your workspace root, it performs five sequential lifecycle phases:</p>\\n  <ul class=\\"code-breakdown-list\\">\\n    <li class=\\"code-breakdown-item\\"><strong>1. Discovery:</strong> Recursively scans <code>~/ros2_ws/src/</code> for any folder containing a valid <code>package.xml</code> manifest. Because <code>src/</code> is currently empty, it detects 0 packages.</li>\\n    <li class=\\"code-breakdown-item\\"><strong>2. Dependency Graph Resolution:</strong> Builds a topological graph ensuring foundational libraries and message interfaces compile before higher-level autonomy nodes.</li>\\n    <li class=\\"code-breakdown-item\\"><strong>3. Directory Generation:</strong> Automatically scaffolds the workspace directory quartet: generates <code>build/</code> (intermediate compilation caches), <code>install/</code> (runtime binaries, scripts, and environment hooks), and <code>log/</code> (detailed build diagnostic logs).</li>\\n    <li class=\\"code-breakdown-item\\"><strong>4. Multi-Core Parallel Compilation:</strong> Assigns isolated worker threads to build independent packages concurrently.</li>\\n    <li class=\\"code-breakdown-item\\"><strong>5. Environment Staging:</strong> Generates the critical <code>install/setup.bash</code> script, which injects your workspace packages into the global ROS 2 discovery paths.</li>\\n  </ul>\\n</div>\\n\\n<p>Verify the generated workspace folders using simple <code>ls</code>:</p>\\n<div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\">ls ~/ros2_ws\\n# Expected Output:\\n# build  install  log  src</code></pre>\\n</div>\\n\\n<h3 id=\\"step-43-sourcing-the-overlay-environment\\">Step 4.3: Sourcing the Overlay Environment</h3>\\n<p>To make any package built inside <code class=\\"inline-code\\">~/ros2_ws</code> visible to your current terminal session:</p>\\n<div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\">source ~/ros2_ws/install/setup.bash</code></pre>\\n</div>\\n\\n<div class=\\"alert-callout alert-tip\\">\\n<div class=\\"alert-icon\\"></div>\\n<div class=\\"alert-body\\"><strong>Automatic Sourcing:</strong> To ensure every new terminal automatically has access to your workspace overlay, append the source command to your <code class=\\"inline-code\\">~/.bashrc</code>:<br><code class=\\"inline-code\\">echo \\"source ~/ros2_ws/install/setup.bash\\" &gt;&gt; ~/.bashrc</code></div>\\n</div>\\n</section>\\n\\n<section class=\\"lesson-section\\">\\n<h2 id=\\"5-what-makes-a-folder-a-ros-2-package\\">5. What Makes a Folder a ROS 2 Package?</h2>\\n<p>A <strong>Package</strong> is the fundamental atomic unit of software distribution and compilation in ROS 2. A package contains nodes, libraries, configuration files, and launch scripts.</p>\\n<p>There are two primary build types for ROS 2 packages:</p>\\n<ol>\\n<li><strong><code class=\\"inline-code\\">ament_python</code>:</strong> For pure Python nodes, scripts, and launch files.</li>\\n<li><strong><code class=\\"inline-code\\">ament_cmake</code>:</strong> For C++ nodes, hardware drivers, and custom interface definitions (<code class=\\"inline-code\\">.msg</code>, <code class=\\"inline-code\\">.srv</code>, <code class=\\"inline-code\\">.action</code>).</li>\\n</ol>\\n\\n<h3 id=\\"anatomy-of-an-ament_python-package\\">Anatomy of an <code class=\\"inline-code\\">ament_python</code> Package</h3>\\n<p><img src=\\"assets/images/ros2_package_tree.svg\\" alt=\\"ROS 2 Python Package Anatomy\\" class=\\"lesson-image\\" loading=\\"lazy\\" /></p>\\n\\n<h3 id=\\"key-package-components-guide\\">Key Package File Anatomy Guide</h3>\\n<div class=\\"info-grid\\">\\n  <div class=\\"info-card\\">\\n    <div class=\\"card-icon\\">📋</div>\\n    <h4><code>package.xml</code></h4>\\n    <p>The package manifest schema (Format 3). Declares package metadata, licensing, and build/runtime dependencies (<code class=\\"inline-code\\">&lt;depend&gt;</code>) parsed by colcon and rosdep.</p>\\n  </div>\\n  <div class=\\"info-card\\">\\n    <div class=\\"card-icon\\">⚙️</div>\\n    <h4><code>setup.py</code> &amp; <code>setup.cfg</code></h4>\\n    <p>Python install rules. Maps executable CLI commands to python functions in <code class=\\"inline-code\\">entry_points={'console_scripts'}</code> for <code class=\\"inline-code\\">ros2 run</code>.</p>\\n  </div>\\n  <div class=\\"info-card\\">\\n    <div class=\\"card-icon\\">🔍</div>\\n    <h4><code>resource/</code></h4>\\n    <p>Contains an empty marker file named after the package. Registers with the Ament Index so tools like <code class=\\"inline-code\\">ros2 pkg list</code> can discover it.</p>\\n  </div>\\n  <div class=\\"info-card\\">\\n    <div class=\\"card-icon\\">🐍</div>\\n    <h4><code>&lt;pkg_name&gt;/</code></h4>\\n    <p>The inner Python module directory containing <code class=\\"inline-code\\">__init__.py</code> and your actual node classes inheriting from <code class=\\"inline-code\\">rclpy.node.Node</code>.</p>\\n  </div>\\n  <div class=\\"info-card\\">\\n    <div class=\\"card-icon\\">🚀</div>\\n    <h4><code>launch/</code> &amp; <code>config/</code></h4>\\n    <p>Orchestration folders for Python launch scripts (<code class=\\"inline-code\\">.launch.py</code>) and YAML parameter files, installed via <code class=\\"inline-code\\">data_files</code> in <code class=\\"inline-code\\">setup.py</code>.</p>\\n  </div>\\n</div>\\n\\n<div id=\\"package-structure-flow-root\\"></div>\\n</section>\\n\\n<section class=\\"lesson-section\\">\\n<h2 id=\\"6-package-introspection-cli-commands\\">6. Package Introspection CLI Commands</h2>\\n<p>ROS 2 provides dedicated tools to query installed packages:</p>\\n<div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\"># List all discovered ROS 2 packages in the environment\\nros2 pkg list\\n\\n# Find the exact install directory of a package\\nros2 pkg prefix turtlesim\\n\\n# Display the package.xml metadata of any package\\nros2 pkg xml turtlesim</code></pre>\\n</div>\\n</section>\\n\\n<section class=\\"lesson-section\\">\\n<h2 id=\\"7-resolving-package-dependencies-with-rosdep\\">7. Resolving Package Dependencies with <code>rosdep</code></h2>\\n<p>Robotics systems often depend on dozens of system libraries (like OpenCV, SDL, or mathematical solvers). ROS 2 includes <strong><code class=\\"inline-code\\">rosdep</code></strong>, an automated dependency resolver that parses <code class=\\"inline-code\\">&lt;depend&gt;</code> tags across all packages in <code class=\\"inline-code\\">src/</code> and installs missing Ubuntu apt packages.</p>\\n\\n<h3 id=\\"the-standard-workspace-rosdep-command\\">The Standard Workspace rosdep Command</h3>\\n<div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\">cd ~/ros2_ws\\nrosdep update\\nrosdep install --from-paths src --ignore-src -y</code></pre>\\n</div>\\n\\n<h3 id=\\"flag-by-flag-command-breakdown\\">Flag-by-Flag Command Breakdown:</h3>\\n<ul>\\n<li><code class=\\"inline-code\\">--from-paths src</code>: Recursively inspects every <code class=\\"inline-code\\">package.xml</code> inside the <code class=\\"inline-code\\">src/</code> tree.</li>\\n<li><code class=\\"inline-code\\">--ignore-src</code>: Do not attempt to install dependencies from Ubuntu apt if they already exist as source packages inside <code class=\\"inline-code\\">src/</code>.</li>\\n<li><code class=\\"inline-code\\">-y</code>: Automatically answers \\"Yes\\" to all system package installation prompts.</li>\\n</ul>\\n</section>\\n\\n<section class=\\"lesson-section\\">\\n<h2 id=\\"8-create-ros-package-python\\">8. Create ROS 2 Package (Python)</h2>\\n<p>In this guided walkthrough, you will practice creating our core <code class=\\"inline-code\\">nexus_amr_basics</code> package using <code class=\\"inline-code\\">ros2 pkg create</code>, verify its generated file structure, check dependencies with <code class=\\"inline-code\\">rosdep</code>, and compile it into the overlay workspace.</p>\\n\\n<ol>\\n<li>Navigate to your workspace source directory:</li>\\n</ol>\\n<div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\">cd ~/ros2_ws/src</code></pre>\\n</div>\\n\\n<ol start=\\"2\\">\\n<li>Create the <code class=\\"inline-code\\">nexus_amr_basics</code> package with required dependencies:</li>\\n</ol>\\n<div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\">ros2 pkg create --build-type ament_python nexus_amr_basics --dependencies rclpy geometry_msgs std_msgs --description \\"Nexus AMR Robotics Core Basics Package\\"\\n\\n# Expected Output:\\n# going to create a new package\\n# package name: nexus_amr_basics\\n# destination directory: /home/student/ros2_ws/src\\n# package format: 3\\n# version: 0.0.0\\n# description: Nexus AMR Robotics Core Basics Package\\n# maintainer: ['student <student@todo.todo>']\\n# licenses: ['TODO: License declaration']\\n# build type: ament_python\\n# dependencies: ['rclpy', 'geometry_msgs', 'std_msgs']\\n# creating folder ./nexus_amr_basics\\n# creating ./nexus_amr_basics/package.xml\\n# creating setup.py\\n# creating setup.cfg\\n# creating ./nexus_amr_basics/nexus_amr_basics/__init__.py</code></pre>\\n</div>\\n\\n<ol start=\\"3\\">\\n<li>Immediate verification: Inspect the generated package directory structure using simple <code>ls</code>:</li>\\n</ol>\\n<div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\">ls nexus_amr_basics/\\n# Expected Output:\\n# nexus_amr_basics  package.xml  resource  setup.cfg  setup.py  test</code></pre>\\n</div>\\n\\n<ol start=\\"4\\">\\n<li>Run <code class=\\"inline-code\\">rosdep</code> from workspace root to verify all dependencies are satisfied:</li>\\n</ol>\\n<div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\">cd ~/ros2_ws\\nrosdep update\\nrosdep install --from-paths src --ignore-src -y</code></pre>\\n</div>\\n\\n<ol start=\\"5\\">\\n<li>Build only our target package with <code class=\\"inline-code\\">colcon build --packages-select</code>:</li>\\n</ol>\\n\\n<div class=\\"alert-callout alert-tip\\" style=\\"margin-bottom: 1.25rem;\\">\\n<div class=\\"alert-icon\\">⚡</div>\\n<div class=\\"alert-body\\">\\n  <strong>Why use <code>--packages-select</code> instead of a bare <code>colcon build</code>?</strong><br>\\n  In a real-world autonomous mobile robot project, your <code>src/</code> directory will eventually house dozens of packages (navigation planners, 2D/3D SLAM, motor controllers, camera vision pipelines, and custom message interfaces).\\n  <br><br>\\n  If you run a bare <code>colcon build</code>, <code>colcon</code> evaluates and re-compiles <em>every single package in the entire workspace</em>—which can take 5 to 15 minutes! The <code>--packages-select &lt;package_name&gt;</code> flag instructs <code>colcon</code>: <em>\\"Ignore all other packages in <code>src/</code>. Build and install only this specific package!\\"</em> This isolates your build and drops compilation time to <strong>1–2 seconds</strong> for fast developer velocity.\\n</div>\\n</div>\\n\\n<div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\">cd ~/ros2_ws\\ncolcon build --packages-select nexus_amr_basics\\n\\n# Expected Output:\\n# Starting >>> nexus_amr_basics\\n# Finished <<< nexus_amr_basics [1.15s]\\n# Summary: 1 package finished [1.32s]</code></pre>\\n</div>\\n\\n<div class=\\"alert-callout alert-info\\" style=\\"margin: 1.25rem 0;\\">\\n  <div class=\\"alert-icon\\">💡</div>\\n  <div class=\\"alert-body\\">\\n    <strong>Workspace Golden Rule &amp; Reference Directory Note:</strong><br>\\n    Always ensure you navigate into your active workspace root (<code class=\\"inline-code\\">cd ~/ros2_ws</code>) before executing <code class=\\"inline-code\\">colcon build</code>.<br>\\n    The <code class=\\"inline-code\\">~/ros2_ws_reference/</code> directory in your environment is provided strictly as an educational reference codebase for students to inspect and compare working code solutions. It contains a <code class=\\"inline-code\\">COLCON_IGNORE</code> marker file so colcon never compiles it and it is never sourced, keeping your active workspace clean and conflict-free.\\n  </div>\\n</div>\\n\\n<div class=\\"code-breakdown-card\\" style=\\"margin: 1.25rem 0;\\">\\n  <h4 class=\\"code-breakdown-title\\">🔬 Command Anatomy &amp; Build Flag Breakdown</h4>\\n  <p class=\\"code-breakdown-intro\\">Understanding each component of the build command and production flags:</p>\\n  <ul class=\\"code-breakdown-list\\">\\n    <li class=\\"code-breakdown-item\\"><strong><code>colcon</code>:</strong> The collective construction meta-build CLI tool.</li>\\n    <li class=\\"code-breakdown-item\\"><strong><code>build</code>:</strong> The primary verb directing <code>colcon</code> to invoke underlying compilers (setuptools for Python, CMake for C++) and stage outputs into <code>install/</code>.</li>\\n    <li class=\\"code-breakdown-item\\"><strong><code>--packages-select &lt;pkg&gt;</code>:</strong> Limits the build scope strictly to the named package (or space-separated list: <code>--packages-select pkg_a pkg_b</code>).</li>\\n    <li class=\\"code-breakdown-item\\"><strong><code>--symlink-install</code> (Pro Developer Superpower):</strong> When building Python packages, pass <code>--symlink-install</code>. Instead of copying <code>.py</code> files into <code>install/</code>, <code>colcon</code> creates symbolic links pointing back to your source code in <code>src/</code>. This means edits to Python scripts take effect <em>immediately without needing to re-run <code>colcon build</code>!</em></li>\\n    <li class=\\"code-breakdown-item\\"><strong><code>--packages-up-to &lt;pkg&gt;</code> (Companion Flag):</strong> Builds the target package <em>plus all internal workspace packages it depends on</em> (vital when your Python node depends on custom message interfaces in the same workspace).</li>\\n  </ul>\\n</div>\\n\\n<div class=\\"info-grid\\" style=\\"margin: 1.25rem 0;\\">\\n  <div class=\\"info-card\\">\\n    <div class=\\"card-icon\\">🚀</div>\\n    <h4>Starting &gt;&gt;&gt; &lt;pkg&gt;</h4>\\n    <p><code>colcon</code> has spawned a dedicated build thread, confirmed the package type (<code>ament_python</code>), and initialized the build worker.</p>\\n  </div>\\n  <div class=\\"info-card\\">\\n    <div class=\\"card-icon\\">✅</div>\\n    <h4>Finished &lt;&lt;&lt; &lt;pkg&gt; [time]</h4>\\n    <p>Execution completed successfully with return code 0. Bytecode was compiled, entry points registered, and artifacts installed.</p>\\n  </div>\\n  <div class=\\"info-card\\">\\n    <div class=\\"card-icon\\">📊</div>\\n    <h4>Summary: N finished</h4>\\n    <p>Displays total packages compiled and cumulative wall-clock duration. If any package fails, <code>colcon</code> highlights the failing package in red.</p>\\n  </div>\\n</div>\\n\\n<ol start=\\"6\\">\\n<li>Sourcing the workspace and verifying package discovery:</li>\\n</ol>\\n<div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\"># ----------------------------------------------------------------------\\n# The Overlay Sourcing Contrast Drill:\\n# ----------------------------------------------------------------------\\n# Test 1: BEFORE sourcing install/setup.bash, test if ROS 2 knows the package prefix:\\nros2 pkg prefix nexus_amr_basics\\n# Expected Output: Package 'nexus_amr_basics' not found\\n\\n# Test 2: Source the workspace overlay:\\nsource ~/ros2_ws/install/setup.bash\\n\\n# Test 3: Re-query package prefix:\\nros2 pkg prefix nexus_amr_basics\\n# Expected Output:\\n# /home/student/ros2_ws/install/nexus_amr_basics\\n# ✅ Found! Sourcing overlays your local package onto the global ROS 2 graph.</code></pre>\\n</div>\\n<p><em>Verify that the prefix matches <code class=\\"inline-code\\">~/ros2_ws/install/nexus_amr_basics</code>.</em></p>\\n</section>\\n\\n<h2 id=\\"9-verification-steps-amp-expected-terminal-output\\">9. Verification Steps &amp; Expected Terminal Output</h2>\\n<p>Audit your compiled workspace architecture to verify build artifacts and package metadata:</p>\\n\\n<div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash (Workspace Health Audit)</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\"># 1. Verify workspace directory quartet:\\nls -la ~/ros2_ws/\\n\\n# 2. Check installed package prefix:\\nros2 pkg prefix nexus_amr_basics\\n\\n# 3. Query declared package dependencies:\\nros2 pkg xml nexus_amr_basics --tag depend</code></pre>\\n</div>\\n\\n<p><em>Expected Terminal Output:</em></p>\\n<div class=\\"code-container\\" data-language=\\"text\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">text (Expected Verification Output)</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-text\\">drwxr-xr-x 6 student student 4096 Oct 19 12:10 .\\ndrwxr-xr-x 8 student student 4096 Oct 19 12:00 ..\\ndrwxr-xr-x 4 student student 4096 Oct 19 12:08 build\\ndrwxr-xr-x 4 student student 4096 Oct 19 12:08 install\\ndrwxr-xr-x 3 student student 4096 Oct 19 12:08 log\\ndrwxr-xr-x 3 student student 4096 Oct 19 12:05 src\\n\\n/home/student/ros2_ws/install/nexus_amr_basics\\n\\n<depend>rclpy</depend>\\n<depend>geometry_msgs</depend>\\n<depend>std_msgs</depend></code></pre>\\n</div>\\n\\n<div class=\\"asset-handoff-card\\" style=\\"margin: 1.75rem 0 1rem 0; padding: 1.15rem 1.4rem; border-radius: 10px; background: rgba(16, 185, 129, 0.06); border: 1px solid rgba(16, 185, 129, 0.25); border-left: 4px solid #10b981;\\">\\n  <div style=\\"display: flex; align-items: center; gap: 0.5rem; margin-bottom: 0.5rem;\\">\\n    <span style=\\"font-size: 1.1rem;\\">📦</span>\\n    <strong style=\\"font-size: 0.95rem; color: #10b981; text-transform: uppercase; letter-spacing: 0.04em;\\">Asset Handoff &amp; Next Lesson Pipeline Bridge</strong>\\n  </div>\\n  <p style=\\"margin: 0 0 0.65rem 0; font-size: 0.88rem; color: var(--text-primary); line-height: 1.6;\\">\\n    You have generated and structured the core nexus_amr_basics Python package, declaring dependencies in package.xml and configuring package discovery via setup.py and setuptools.\\n  </p>\\n  <div style=\\"display: flex; flex-wrap: wrap; gap: 0.75rem; font-size: 0.82rem; font-family: var(--font-mono);\\">\\n    <span style=\\"background: var(--bg-surface); border: 1px solid var(--border-color); padding: 0.25rem 0.6rem; border-radius: 5px; color: var(--text-primary);\\">\\n      📁 <strong>Produced Artifact:</strong> <code>ros2_ws/src/nexus_amr_basics/</code> package skeleton (<code>package.xml</code>, <code>setup.py</code>, <code>setup.cfg</code>)\\n    </span>\\n    <span style=\\"background: var(--bg-surface); border: 1px solid var(--border-color); padding: 0.25rem 0.6rem; border-radius: 5px; color: var(--text-primary);\\">\\n      ➡️ <strong>Ingested By:</strong> Lesson 05 (Publisher &amp; Subscriber Nodes in Python)\\n    </span>\\n  </div>\\n</div>\\n","quizzes":[{"id":"q_l1_04_1","prompt":"Why must you source install/setup.bash after building a workspace with colcon?","options":["It formats the hard drive cache","It overlays your custom workspace packages onto the system environment so ROS 2 can find your nodes","It downloads Debian dependencies from Ubuntu repositories","It shuts down the background roscore daemon"],"correct":1,"explanation":"Sourcing install/setup.bash updates your shell's environment variables (AMENT_PREFIX_PATH, PATH, PYTHONPATH) to discover the newly built packages in your overlay."},{"id":"q_l1_04_2","prompt":"Which section of setup.py maps an executable CLI command to a Python module entry function?","options":["data_files","packages","console_scripts inside entry_points","install_requires"],"correct":2,"explanation":"entry_points={'console_scripts': ['node_name = pkg.module:main']} registers the binary name that ros2 run executes."}],"has_quiz":true,"next_id":"lesson_05","prev_id":"lesson_03","subtopics":[{"id":"1-overview-learning-objectives","title":"1. Overview &amp; Learning Objectives"},{"id":"2-the-ros-2-workspace-architecture","title":"2. The ROS 2 Workspace Architecture"},{"id":"3-underlays-vs-overlays-the-environment-chaining-model","title":"3. Underlays vs. Overlays: The Environment Chaining Model"},{"id":"4-initializing-building-a-workspace","title":"4. Initializing &amp; Building a Workspace"},{"id":"5-what-makes-a-folder-a-ros-2-package","title":"5. What Makes a Folder a ROS 2 Package?"},{"id":"6-package-introspection-cli-commands","title":"6. Package Introspection CLI Commands"},{"id":"7-resolving-package-dependencies-with-rosdep","title":"7. Resolving Package Dependencies with rosdep"},{"id":"8-create-ros-package-python","title":"8. Create ROS 2 Package (Python)"},{"id":"9-verification-steps-amp-expected-terminal-output","title":"9. Verification Steps &amp; Expected Terminal Output"}]},{"id":"lesson_05","num":5,"num_str":"05","title":"Communication Mechanism I: Publishers, Subscribers & Quality of Service (QoS)","slug":"publishers_subscribers_and_qos","filename":"05_publishers_subscribers_and_qos.md","module":"Day 1: ROS 2 Foundations & Core Middleware","module_id":1,"duration":"45-60 min","focus":"AMR Distance Sensor Simulation, Event-Driven Safety Callbacks, QoS Reliability vs Best Effort","snapshot":[["Pub/Sub Decoupling","Publishers and subscribers communicate anonymously over strongly-typed DDS topics without direct IP address pairing."],["Live Introspection","CLI tools (ros2 topic list, info, echo, hz) allow instant inspection and performance measurement of running data streams."],["Symlink Superpower","--symlink-install links source files directly to install/, enabling instant Python code updates without rebuilding."],["QoS Compatibility Rule","Rx <= Tx: A subscriber's QoS requirements must be less restrictive than or equal to the publisher's offering."]],"html_content":"<section class=\\"lesson-section\\">\\n<h2 id=\\"1-overview-learning-objectives\\">1. Overview &amp; Learning Objectives</h2>\\n<p>In <a href=\\"#\\" class=\\"internal-lesson-link\\" data-lesson=\\"04\\">Lesson 04</a>, you scaffolded your core ROS 2 Python package: <code class=\\"inline-code\\">nexus_amr_basics</code>. Now, you are ready to write production robotics software within it.</p>\\n<p>The foundational paradigm of ROS 2 communication is the <strong>Publish-Subscribe (Pub/Sub)</strong> model. Sensors produce data streams (LiDAR scans, camera images, wheel odometry), and decision-making nodes consume those streams asynchronously without direct hardware or network address coupling.</p>\\n\\n<div class=\\"learning-objectives-card\\">\\n  <div class=\\"learning-objectives-header\\">\\n    <div class=\\"objectives-icon-badge\\">\\n      <span style=\\"font-size: 1.15rem; line-height: 1;\\">🎯</span>\\n    </div>\\n    <div class=\\"objectives-title-group\\">\\n      <h3 class=\\"objectives-main-title\\">Learning Objectives &amp; Core Outcomes</h3>\\n      <span class=\\"objectives-subtitle\\">By the end of this lesson, you will be able to:</span>\\n    </div>\\n    <span class=\\"objectives-count-badge\\">7 CORE OUTCOMES</span>\\n  </div>\\n  <ul class=\\"learning-objectives-list\\">\\n    <li class=\\"learning-objective-item\\">\\n      <span class=\\"objective-num-badge\\">1</span>\\n      <span class=\\"objective-text\\">Understand the asynchronous Publish-Subscribe architecture and the underlying Data Distribution Service (DDS) message bus.</span>\\n    </li>\\n    <li class=\\"learning-objective-item\\">\\n      <span class=\\"objective-num-badge\\">2</span>\\n      <span class=\\"objective-text\\">Write an Object-Oriented ROS 2 Publisher node (<code class=\\"inline-code\\">ultrasonic_sensor_node.py</code>) using standard <code class=\\"inline-code\\">rclpy</code> lifecycle patterns and non-blocking timers.</span>\\n    </li>\\n    <li class=\\"learning-objective-item\\">\\n      <span class=\\"objective-num-badge\\">3</span>\\n      <span class=\\"objective-text\\">Configure <code class=\\"inline-code\\">setup.py</code> entry points and introspect live topics using <code class=\\"inline-code\\">ros2 topic list</code>, <code class=\\"inline-code\\">echo</code>, and <code class=\\"inline-code\\">hz</code>.</span>\\n    </li>\\n    <li class=\\"learning-objective-item\\">\\n      <span class=\\"objective-num-badge\\">4</span>\\n      <span class=\\"objective-text\\">Write an Object-Oriented ROS 2 Subscriber node (<code class=\\"inline-code\\">collision_monitor_node.py</code>) and establish concurrent multi-node communications.</span>\\n    </li>\\n    <li class=\\"learning-objective-item\\">\\n      <span class=\\"objective-num-badge\\">5</span>\\n      <span class=\\"objective-text\\">Master the developer superpower: <code class=\\"inline-code\\">colcon build --symlink-install</code> for rapid Python prototyping.</span>\\n    </li>\\n    <li class=\\"learning-objective-item\\">\\n      <span class=\\"objective-num-badge\\">6</span>\\n      <span class=\\"objective-text\\">Configure Quality of Service (QoS) profiles for reliable command delivery vs. loss-tolerant sensor streaming.</span>\\n    </li>\\n    <li class=\\"learning-objective-item\\">\\n      <span class=\\"objective-num-badge\\">7</span>\\n      <span class=\\"objective-text\\">Complete the hands-on mission: program an autonomous velocity controller node that commands Turtlesim to execute a continuous square patrol.</span>\\n    </li>\\n  </ul>\\n</div>\\n</section>\\n\\n<section class=\\"lesson-section\\">\\n<h2 id=\\"2-topic-communication-architecture\\">2. Topic Communication Architecture &amp; DDS</h2>\\n<p>A <strong>Topic</strong> is a unidirectional, strongly-typed data bus over which nodes exchange messages. ROS 2's Pub/Sub architecture provides three levels of architectural decoupling:</p>\\n\\n<div class=\\"info-grid\\">\\n  <div class=\\"info-card\\">\\n    <div class=\\"card-icon\\">⏳</div>\\n    <h4>Temporal Decoupling</h4>\\n    <p>Publishers and subscribers do not need to be active at the same time. A subscriber can join minutes after a publisher starts without causing errors.</p>\\n  </div>\\n  <div class=\\"info-card\\">\\n    <div class=\\"card-icon\\">🌐</div>\\n    <h4>Spatial Decoupling</h4>\\n    <p>Nodes do not know each other's IP addresses or process IDs. They address messages exclusively by topic name (e.g., <code class=\\"inline-code\\">/chatter</code> or <code class=\\"inline-code\\">/cmd_vel</code>).</p>\\n  </div>\\n  <div class=\\"info-card\\">\\n    <div class=\\"card-icon\\">⚡</div>\\n    <h4>Synchronization Decoupling</h4>\\n    <p>Publishing is non-blocking. A publisher does not wait for subscribers to receive or process data, preventing sensor loops from stalling.</p>\\n  </div>\\n</div>\\n\\n<p>Use the interactive architecture canvas below to explore how data packets serialize, travel across DDS middleware, and trigger event callbacks in real time.</p>\\n\\n<!-- Interactive PubSubFlow Component Mount Point -->\\n<div id=\\"pubsub-flow-root\\"></div>\\n\\n<div class=\\"alert alert-tip\\">\\n  <div class=\\"alert-title\\">💡 DDS (Data Distribution Service) Under the Hood</div>\\n  <p>ROS 2 completely eliminates the centralized ROS 1 master (<code class=\\"inline-code\\">roscore</code>). Instead, it relies on industrial <strong>OMG DDS / RTPS</strong> middleware (such as CycloneDDS or Fast-DDS). Nodes use peer-to-peer multicast discovery to detect compatible publishers and subscribers automatically.</p>\\n</div>\\n</section>\\n\\n<hr class=\\"divider\\">\\n<h2 id=\\"3-writing-the-ultrasonic-sensor-publisher-node\\">3. Writing the Ultrasonic Sensor Rangefinder Publisher Node</h2>\\n<p>In autonomous mobile robotics, distance sensors (ultrasonic transducers, LiDAR, infrared bumpers) continuously stream proximity telemetry over ROS 2 topics so collision supervisors can prevent accidents.</p>\\n\\n\\n<div class=\\"alert alert-info alert-briefing\\">\\n  <div class=\\"alert-icon\\">📡</div>\\n  <div class=\\"alert-content\\">\\n    <div class=\\"alert-title\\">Robotics Flight Operations Mission Briefing: AMR Proximity Rangefinder Sensor Publisher</div>\\n    <div class=\\"alert-body\\">\\n      <strong>Physical AMR Context &amp; Operational Challenge:</strong><br>\\n      In autonomous warehouse robotics, floor hazards like discarded wooden pallet corners, dropped totes, or low-profile forklift tines frequently lie below the horizontal scanning plane of a 2D LiDAR (typically mounted at 20-30 cm). Ultrasonic sonar transducers mounted low on the AMR chassis emit high-frequency acoustic pings to detect obstacles directly in the wheel path.\\n      <br><br>\\n      <strong>Architectural Role &amp; Why This Mechanism:</strong><br>\\n      Sensor telemetry must stream continuously into the computational graph at a predictable rate without waiting for downstream nodes to request data. A <strong>ROS 2 Publisher</strong> over a DDS Topic provides this decoupled, high-frequency, asynchronous streaming paradigm. Downstream nodes (safety monitors, costmaps, emergency brakes) can subscribe to <code>/sensor/ultrasonic_front</code> without the sensor node needing to know who is listening.\\n      <br><br>\\n      <strong>Flight Objective &amp; Behavioral Outcome:</strong><br>\\n      Construct a Python ROS 2 Publisher node that initializes a 10 Hz non-blocking software timer, computes simulated distance telemetry using a sinusoidal proximity profile (0.3m to 2.7m), serializes the measurements into <code>sensor_msgs/msg/Range</code>, and broadcasts them over DDS.\\n    </div>\\n  </div>\\n</div>\\n\\n\\n<div class=\\"alert-callout alert-info\\" style=\\"margin: 1.5rem 0;\\">\\n  <div class=\\"alert-icon\\">🔍</div>\\n  <div class=\\"alert-body\\">\\n    <strong>Best Practice: Discovering &amp; Inspecting Message Interfaces Before Writing Code</strong><br>\\n    In production robotics, you should never write publisher or subscriber nodes blindly. Always inspect the exact data schema of the message to understand what fields and data types exist:\\n    <br><br>\\n    <strong>1. Discover the message interface using <code class=\\"inline-code\\">ros2 interface list</code> or <code class=\\"inline-code\\">package</code>:</strong>\\n    <div class=\\"code-container\\" data-language=\\"bash\\" style=\\"margin: 0.6rem 0;\\">\\n      <div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n      <pre><code class=\\"language-bash\\"># Search across all available ROS 2 interfaces for range/sonar messages:\\nros2 interface list | grep -i range\\n\\n# Or list all standard sensor message interfaces:\\nros2 interface package sensor_msgs</code></pre>\\n    </div>\\n    <strong>2. Inspect the fields and datatypes using <code class=\\"inline-code\\">ros2 interface show</code>:</strong>\\n    <div class=\\"code-container\\" data-language=\\"bash\\" style=\\"margin: 0.6rem 0;\\">\\n      <div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n      <pre><code class=\\"language-bash\\">ros2 interface show sensor_msgs/msg/Range</code></pre>\\n    </div>\\n    <strong>Expected Output &amp; Schema Breakdown:</strong>\\n    <div class=\\"code-container terminal-window\\" data-language=\\"plaintext\\" style=\\"margin: 0.6rem 0;\\">\\n      <div class=\\"terminal-header\\">\\n        <div class=\\"terminal-dots\\"><span class=\\"dot red\\"></span><span class=\\"dot yellow\\"></span><span class=\\"dot green\\"></span></div>\\n        <span class=\\"terminal-title\\">Terminal &mdash; ros2 interface show sensor_msgs/msg/Range</span>\\n      </div>\\n      <pre><code class=\\"language-plaintext\\">std_msgs/Header header\\n    builtin_interfaces/Time stamp\\n        int32 sec\\n        uint32 nanosec\\n    string frame_id\\nuint8 ULTRASOUND=0\\nuint8 INFRARED=1\\nuint8 radiation_type\\nfloat32 field_of_view\\nfloat32 min_range\\nfloat32 max_range\\nfloat32 range\\nfloat32 variance</code></pre>\\n    </div>\\n    <ul style=\\"margin: 0.5rem 0 0 1.25rem; line-height: 1.6;\\">\\n      <li><code class=\\"inline-code\\">header.frame_id</code>: Coordinate frame where the sensor is mounted (e.g., <code class=\\"inline-code\\">'ultrasound_front_link'</code>).</li>\\n      <li><code class=\\"inline-code\\">radiation_type</code>: Transducer technology constant (<code class=\\"inline-code\\">Range.ULTRASOUND = 0</code>).</li>\\n      <li><code class=\\"inline-code\\">field_of_view</code>: Detection cone spread in radians (e.g. <code class=\\"inline-code\\">0.5236</code> rad &approx; 30&deg;).</li>\\n      <li><code class=\\"inline-code\\">min_range</code> / <code class=\\"inline-code\\">max_range</code>: Sensor detection envelope in meters (<code class=\\"inline-code\\">0.02</code> m to <code class=\\"inline-code\\">3.0</code> m).</li>\\n      <li><code class=\\"inline-code\\">range</code>: The actual measured obstacle distance in meters &mdash; this is the primary telemetry value you populate in the publisher and read in the subscriber.</li>\\n    </ul>\\n  </div>\\n</div>\\n\\n<p>Create your ultrasonic rangefinder node script in your package source directory: <code class=\\"inline-code\\">~/ros2_ws/src/nexus_amr_basics/nexus_amr_basics/ultrasonic_sensor_node.py</code>:</p>\\n\\n<div class=\\"code-container ide-code-window\\" data-language=\\"python\\">\\n  <div class=\\"code-header\\">\\n    <div class=\\"code-dots\\"><span class=\\"dot red\\"></span><span class=\\"dot yellow\\"></span><span class=\\"dot green\\"></span></div>\\n    <span class=\\"code-filename\\">ultrasonic_sensor_node.py &mdash; AMR Proximity Rangefinder Publisher</span>\\n  </div>\\n  <pre><code class=\\"language-python\\">import math\\nimport rclpy\\nfrom rclpy.node import Node\\nfrom sensor_msgs.msg import Range\\n\\n\\nclass UltrasonicSensorPublisher(Node):\\n    &quot;&quot;&quot;\\n    Ultrasonic Rangefinder Sensor Publisher Node.\\n    Broadcasts Range measurements periodically over the DDS middleware.\\n    &quot;&quot;&quot;\\n\\n    def __init__(self):\\n        # Step 1: Initialize base Node with unique name &#x27;ultrasonic_sensor_node&#x27;\\n        # This identifier registers the node in the ROS 2 computational graph.\\n        super().__init__(&#x27;ultrasonic_sensor_node&#x27;)\\n\\n        # Step 2: Create a Publisher endpoint with Quality of Service (QoS)\\n        # Parameters:\\n        #   - Range: The ROS 2 sensor message schema (sensor_msgs/msg/Range)\\n        #   - &#x27;/sensor/ultrasonic_front&#x27;: The DDS topic name\\n        #   - 10: QoS Profile configuration.\\n        #     Passing an integer (10) tells ROS 2 to use the DEFAULT QoS Profile:\\n        #       * Reliability: RELIABLE (guarantees packet delivery via ACKs)\\n        #       * Durability:  VOLATILE (messages are not saved for late joiners)\\n        #       * History:     KEEP_LAST with Depth=10 (buffers up to 10 samples)\\n        #     (Shorthand for: QoSProfile(depth=10, reliability=RELIABLE, durability=VOLATILE))\\n        self.publisher_ = self.create_publisher(Range, &#x27;/sensor/ultrasonic_front&#x27;, 10)\\n\\n        # Step 3: Configure a non-blocking software timer running at 10 Hz\\n        # 10 Hz = 0.100s period. Non-blocking timers allow rclpy to execute\\n        # other callbacks concurrently without freezing the thread.\\n        self.timer_period = 0.1  # seconds\\n        self.timer = self.create_timer(self.timer_period, self.timer_callback)\\n\\n        # Step 4: Internal telemetry state tracking\\n        self.step_count = 0\\n        self.get_logger().info(\\n            &#x27;UltrasonicSensorPublisher initialized. Broadcasting Range telemetry to &quot;/sensor/ultrasonic_front&quot; at 10 Hz...&#x27;\\n        )\\n\\n    def timer_callback(self):\\n        &quot;&quot;&quot;\\n        Invoked periodically at 10 Hz by the ROS 2 SingleThreadedExecutor.\\n        Computes the current sensor reading, encapsulates it into Range, and publishes.\\n        &quot;&quot;&quot;\\n        # Calculate simulation time elapsed\\n        time_elapsed = self.step_count * self.timer_period\\n\\n        # Compute smooth sinusoidal distance profile between 0.30 m and 2.70 m\\n        distance = 1.5 + 1.2 * math.sin(0.5 * time_elapsed)\\n\\n        # Instantiate strongly-typed ROS 2 sensor message\\n        msg = Range()\\n        msg.header.stamp = self.get_clock().now().to_msg()\\n        msg.header.frame_id = &#x27;ultrasound_front_link&#x27;\\n        msg.radiation_type = Range.ULTRASOUND\\n        msg.field_of_view = 0.5236  # ~30 degrees beam spread in radians\\n        msg.min_range = 0.02        # 2 cm minimum range\\n        msg.max_range = 3.0         # 3.0 m maximum range\\n        msg.range = round(distance, 2)\\n\\n        # Serialize and broadcast over DDS transport\\n        self.publisher_.publish(msg)\\n\\n        # Log operational warnings if obstacle enters critical safety buffer (&lt; 0.50 m)\\n        if distance &lt; 0.50:\\n            self.get_logger().warn(\\n                f&#x27;Ultrasonic range: {msg.range:.2f} m -&gt; [OBSTACLE WITHIN SAFETY BUFFER!]&#x27;\\n            )\\n        else:\\n            self.get_logger().info(\\n                f&#x27;Ultrasonic range: {msg.range:.2f} m -&gt; [PATH CLEAR]&#x27;\\n            )\\n\\n        self.step_count += 1\\n\\n\\ndef main(args=None):\\n    # Initialize the rclpy client library and underlying DDS transport layer\\n    rclpy.init(args=args)\\n\\n    # Instantiate the node\\n    node = UltrasonicSensorPublisher()\\n\\n    try:\\n        # Enter the event loop; blocks here dispatching timer callbacks\\n        rclpy.spin(node)\\n    except KeyboardInterrupt:\\n        # Graceful exit on Ctrl+C from terminal\\n        pass\\n    finally:\\n        # Destroy the node and unregister publisher from the DDS domain\\n        node.destroy_node()\\n        rclpy.shutdown()\\n\\n\\nif __name__ == &#x27;__main__&#x27;:\\n    main()\\n</code></pre>\\n</div>\\n\\n<div class=\\"code-breakdown-card\\" style=\\"margin: 1.75rem 0; border-left: 4px solid var(--accent-cyan, #06b6d4);\\">\\n  <h4 class=\\"code-breakdown-title\\" style=\\"display: flex; align-items: center; gap: 0.5rem;\\">\\n    <span>⚡</span> Deep Dive: The 3rd Argument in <code>create_publisher</code> &amp; The Default QoS Profile\\n  </h4>\\n  <p class=\\"code-breakdown-intro\\">\\n    When you write <code class=\\"inline-code\\">self.create_publisher(Range, &#x27;/sensor/ultrasonic_front&#x27;, 10)</code>, what does that number <code class=\\"inline-code\\">10</code> actually do?\\n  </p>\\n  <p style=\\"color: var(--text-secondary); line-height: 1.6; margin-bottom: 1rem;\\">\\n    In ROS 2, every publisher and subscriber must specify a <strong>Quality of Service (QoS)</strong> configuration. Unlike ROS 1 (which forced fixed TCP/UDP sockets), ROS 2 runs on top of DDS (Data Distribution Service) middleware, allowing you to configure reliability, message history, and persistence per topic.\\n  </p>\\n  <p style=\\"color: var(--text-secondary); line-height: 1.6;\\">\\n    Passing an integer (e.g. <code class=\\"inline-code\\">10</code>) is a convenient <strong>shorthand</strong> provided by <code class=\\"inline-code\\">rclpy</code>. Under the hood, ROS 2 sets this number as the queue history depth and automatically applies the <strong>ROS 2 Default QoS Profile</strong>:\\n  </p>\\n\\n  <div class=\\"table-responsive\\" style=\\"margin: 1.25rem 0;\\">\\n    <table>\\n      <thead>\\n        <tr>\\n          <th>Default QoS Policy</th>\\n          <th>Configured Value</th>\\n          <th>Operational Meaning &amp; Robotics Impact</th>\\n        </tr>\\n      </thead>\\n      <tbody>\\n        <tr>\\n          <td><strong>History &amp; Depth</strong></td>\\n          <td><code class=\\"inline-code\\">HistoryPolicy.KEEP_LAST</code><br><strong>Depth = 10</strong></td>\\n          <td>Allocates an in-memory ring buffer of 10 messages. If the publisher generates messages faster than DDS can serialize and transmit them, the oldest unread message is discarded once the 10-slot buffer fills.</td>\\n        </tr>\\n        <tr>\\n          <td><strong>Reliability</strong></td>\\n          <td><code class=\\"inline-code\\">ReliabilityPolicy.RELIABLE</code></td>\\n          <td>Guarantees packet delivery. The publisher tracks acknowledgments (ACKs) from subscribers and re-transmits any dropped packets over the network. Essential for safety alerts, state machines, and goal dispatch.</td>\\n        </tr>\\n        <tr>\\n          <td><strong>Durability</strong></td>\\n          <td><code class=\\"inline-code\\">DurabilityPolicy.VOLATILE</code></td>\\n          <td>Messages are volatile and not saved in memory for future nodes. Only subscribers that are currently online when a message is published will receive it. Late-joining nodes only receive data published <em>after</em> they connect.</td>\\n        </tr>\\n      </tbody>\\n    </table>\\n  </div>\\n\\n  <p style=\\"margin-top: 1rem; color: var(--text-secondary); line-height: 1.6;\\">\\n    <strong>Shorthand vs. Explicit Python Code:</strong> In ROS 2 Python, passing an integer is 100% equivalent to instantiating a full <code class=\\"inline-code\\">QoSProfile</code> object:\\n  </p>\\n\\n  <div class=\\"code-container ide-code-window\\" data-language=\\"python\\" style=\\"margin: 0.75rem 0;\\">\\n    <div class=\\"code-header\\">\\n      <div class=\\"code-dots\\"><span class=\\"dot red\\"></span><span class=\\"dot yellow\\"></span><span class=\\"dot green\\"></span></div>\\n      <span class=\\"code-filename\\">qos_comparison.py &mdash; Shorthand vs Explicit QoSProfile</span>\\n    </div>\\n    <pre><code class=\\"language-python\\"># 1. Shorthand (Standard across everyday ROS 2 development):\\nself.publisher_ = self.create_publisher(Range, &#x27;/sensor/ultrasonic_front&#x27;, 10)\\n\\n# 2. Fully Explicit Equivalent (What ROS 2 constructs under the hood):\\nfrom rclpy.qos import QoSProfile, HistoryPolicy, ReliabilityPolicy, DurabilityPolicy\\n\\ndefault_qos = QoSProfile(\\n    history=HistoryPolicy.KEEP_LAST,\\n    depth=10,\\n    reliability=ReliabilityPolicy.RELIABLE,\\n    durability=DurabilityPolicy.VOLATILE\\n)\\nself.publisher_ = self.create_publisher(Range, &#x27;/sensor/ultrasonic_front&#x27;, default_qos)\\n</code></pre>\\n  </div>\\n</div>\\n\\n\\n<div class=\\"alert-callout alert-warning\\" style=\\"margin: 1.75rem 0;\\">\\n  <div class=\\"alert-icon\\">⚠️</div>\\n  <div class=\\"alert-body\\">\\n    <strong>Diagnostic Note: The QoS Incompatibility \\"Silence\\" Trap:</strong><br>\\n    One of the most frequent bugs in production robotics occurs when a subscriber uses <code>Reliability.RELIABLE</code> while a sensor publisher uses <code>Reliability.BEST_EFFORT</code>.<br><br>\\n    <strong>The Consequence:</strong> Both nodes run without crashing, but <strong>ZERO messages are received</strong>! ROS 2 DDS rules mandate that a subscriber demanding guaranteed delivery cannot connect to a best-effort publisher.<br>\\n    <strong>The Fix:</strong> Always align your subscriber's QoS profile with the publisher's QoS (e.g. using <code class=\\"inline-code\\">QoSProfile(reliability=Reliability.BEST_EFFORT)</code> for high-frequency LiDAR and sensor streams).\\n  </div>\\n</div>\\n\\n<div class=\\"code-breakdown-card\\">\\n  <h4 class=\\"code-breakdown-title\\">🔬 Core Code Deep Dive &amp; Operational Breakdown: UltrasonicSensorPublisher Mechanics</h4>\\n  <p class=\\"code-breakdown-intro\\">Let's dissect how this Sensor Publisher node functions within the ROS 2 DDS runtime:</p>\\n  <ul class=\\"code-breakdown-list\\">\\n    <li class=\\"code-breakdown-item\\"><strong>Node Heritage & Superclass Call:</strong> <code>class UltrasonicSensorPublisher(Node):</code> subclasses <code>rclpy.node.Node</code>. Inside <code>__init__</code>, <code>super().__init__('ultrasonic_sensor_node')</code> registers this node's unique identifier into the ROS 2 computational graph.</li>\\n    <li class=\\"code-breakdown-item\\"><strong>DDS Publisher &amp; Default QoS:</strong> <code>self.publisher_ = self.create_publisher(Range, '/sensor/ultrasonic_front', 10)</code> registers an advertising DDS DataWriter. The 3rd parameter <code>10</code> is shorthand for ROS 2's <strong>Default QoS Profile</strong> (History: <code>KEEP_LAST</code> depth 10, Reliability: <code>RELIABLE</code>, Durability: <code>VOLATILE</code>).</li>\\n    <li class=\\"code-breakdown-item\\"><strong>Non-Blocking Software Timer:</strong> <code>self.create_timer(self.timer_period, self.timer_callback)</code> registers a periodic timer with the rclpy event loop. Unlike a blocking <code>time.sleep()</code> loop, this allows the node's executor to process incoming callbacks concurrently.</li>\\n    <li class=\\"code-breakdown-item\\"><strong>Message Instantiation & Serialization:</strong> <code>msg = Range(); msg.header.frame_id = 'ultrasound_front_link'; msg.radiation_type = Range.ULTRASOUND; msg.range = round(distance, 2)</code> populates the standard robotics sensor message. Calling <code>self.publisher_.publish(msg)</code> hands the struct to DDS for CDR byte-serialization and UDP broadcast.</li>\\n    <li class=\\"code-breakdown-item\\"><strong>Executor Spin Loop:</strong> In <code>main()</code>, <code>rclpy.spin(node)</code> executes the single-threaded event loop, firing <code>timer_callback</code> every 100 milliseconds until interrupted.</li>\\n  </ul>\\n</div>\\n\\n<h2 id=\\"4-configuring-setuppy-building-testing-publisher\\">4. Configuring setup.py, Building &amp; Testing the Publisher</h2>\\n<p>Before ROS 2 can execute your Python script via <code class=\\"inline-code\\">ros2 run</code>, you must expose an entry point executable in <code class=\\"inline-code\\">setup.py</code>.</p>\\n\\n<div class=\\"file-edit-instruction-card\\">\\n  <div class=\\"file-edit-header\\">\\n    <div class=\\"file-edit-header-left\\">\\n      <span>📝 Step-by-Step File Modification Guide</span>\\n    </div>\\n    <span class=\\"file-edit-badge\\">~/ros2_ws/src/nexus_amr_basics/setup.py</span>\\n  </div>\\n  <div class=\\"file-edit-body\\">\\n    <div class=\\"file-edit-step\\">\\n      <div class=\\"file-edit-step-title\\">\\n        <span class=\\"step-num-pill\\">Step 1</span>\\n        <span>Open the Target File</span>\\n      </div>\\n      <p class=\\"step-description\\">Open <code class=\\"inline-code\\">~/ros2_ws/src/nexus_amr_basics/setup.py</code> in your editor or IDE.</p>\\n    </div>\\n\\n    <div class=\\"file-edit-step\\">\\n      <div class=\\"file-edit-step-title\\">\\n        <span class=\\"step-num-pill\\">Step 2</span>\\n        <span>Locate Insertion Point &amp; Add Lines</span>\\n      </div>\\n      <p class=\\"step-description\\">Locate the <code class=\\"inline-code\\">entry_points</code> dictionary and register the ultrasonic publisher executable inside <code class=\\"inline-code\\">'console_scripts'</code>:</p>\\n      <div class=\\"code-container\\" data-language=\\"python\\">\\n        <div class=\\"code-header\\"><span class=\\"code-lang-tag\\">python</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n        <pre><code class=\\"language-python\\">    entry_points={\\n        'console_scripts': [\\n            # &gt;&gt;&gt; REGISTER ULTRASONIC SENSOR PUBLISHER &lt;&lt;&lt;\\n            'ultrasonic_publisher = nexus_amr_basics.ultrasonic_sensor_node:main',\\n        ],\\n    },</code></pre>\\n      </div>\\n      <div class=\\"code-breakdown-card\\" style=\\"margin: 1.25rem 0; border-left: 4px solid var(--accent-cyan, #06b6d4);\\">\\n        <h4 class=\\"code-breakdown-title\\" style=\\"display: flex; align-items: center; gap: 0.5rem;\\">\\n          <span>🔍</span> Syntax Breakdown: Anatomy of a Console Script Entry Point\\n        </h4>\\n        <p class=\\"code-breakdown-intro\\">\\n          Understanding the structure of <code class=\\"inline-code\\">'ultrasonic_publisher = nexus_amr_basics.ultrasonic_sensor_node:main'</code>:\\n        </p>\\n        <ul class=\\"code-breakdown-list\\">\\n          <li class=\\"code-breakdown-item\\">\\n            <strong><code>ultrasonic_publisher</code> (Executable Alias):</strong> The command name you type in the terminal when executing <code class=\\"inline-code\\">ros2 run nexus_amr_basics ultrasonic_publisher</code>. This can be any friendly name you choose; it does not have to match the Python filename.\\n          </li>\\n          <li class=\\"code-breakdown-item\\">\\n            <strong><code>=</code> (Assignment Operator):</strong> Maps the terminal CLI command on the left to the Python target module and function on the right.\\n          </li>\\n          <li class=\\"code-breakdown-item\\">\\n            <strong><code>nexus_amr_basics</code> (Package Directory):</strong> The Python subpackage directory containing your scripts, located inside <code class=\\"inline-code\\">~/ros2_ws/src/nexus_amr_basics/</code>.\\n          </li>\\n          <li class=\\"code-breakdown-item\\">\\n            <strong><code>.ultrasonic_sensor_node</code> (Module File):</strong> The Python file itself (<code class=\\"inline-code\\">ultrasonic_sensor_node.py</code>), written <em>without</em> the <code class=\\"inline-code\\">.py</code> extension.\\n          </li>\\n          <li class=\\"code-breakdown-item\\">\\n            <strong><code>:main</code> (Entrypoint Function):</strong> The colon <code class=\\"inline-code\\">:</code> points directly to the function inside the script (<code class=\\"inline-code\\">def main(args=None):</code>) that Python executes when the node is launched.\\n          </li>\\n        </ul>\\n      </div>\\n    </div>\\n\\n    <div class=\\"file-edit-step\\">\\n      <div class=\\"file-edit-step-title\\">\\n        <span class=\\"step-num-pill\\">Step 3</span>\\n        <span>Verify the Full File After Editing</span>\\n      </div>\\n      <p class=\\"step-description\\">Self-check your file against the complete reference below to confirm indentation, closing brackets, and commas:</p>\\n      <details class=\\"file-edit-dropdown\\">\\n        <summary class=\\"file-edit-summary\\">\\n          <span>📄 View Complete setup.py After Editing</span>\\n          <span class=\\"file-edit-toggle-icon\\">▶</span>\\n        </summary>\\n        <div class=\\"file-edit-dropdown-content\\">\\n          <div class=\\"code-container\\" data-language=\\"python\\">\\n            <div class=\\"code-header\\"><span class=\\"code-lang-tag\\">python</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n            <pre><code class=\\"language-python\\">from setuptools import find_packages, setup\\n\\npackage_name = &#x27;nexus_amr_basics&#x27;\\n\\nsetup(\\n    name=package_name,\\n    version=&#x27;1.0.0&#x27;,\\n    packages=find_packages(exclude=[&#x27;test&#x27;]),\\n    data_files=[\\n        (&#x27;share/ament_index/resource_index/packages&#x27;, [&#x27;resource/&#x27; + package_name]),\\n        (&#x27;share/&#x27; + package_name, [&#x27;package.xml&#x27;]),\\n    ],\\n    install_requires=[&#x27;setuptools&#x27;],\\n    zip_safe=True,\\n    maintainer=&#x27;Nexus AMR Academy&#x27;,\\n    maintainer_email=&#x27;instructor@botforge.io&#x27;,\\n    description=&#x27;ROS 2 Sensor &amp; Telemetry Fundamentals&#x27;,\\n    license=&#x27;Apache-2.0&#x27;,\\n    tests_require=[&#x27;pytest&#x27;],\\n    entry_points={\\n        &#x27;console_scripts&#x27;: [\\n            &#x27;ultrasonic_publisher = nexus_amr_basics.ultrasonic_sensor_node:main&#x27;,\\n        ],\\n    },\\n)</code></pre>\\n          </div>\\n        </div>\\n      </details>\\n    </div>\\n  </div>\\n</div>\\n\\n<h3 id=\\"42-build-and-run-with-ros2-cli\\">4.2 Build and Run with the ROS 2 CLI</h3>\\n<p>Compile your workspace and start the publisher in <strong>Terminal 1</strong>:</p>\\n\\n<div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash (Terminal 1 - Publisher)</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\">cd ~/ros2_ws\\ncolcon build\\nsource install/setup.bash\\nros2 run nexus_amr_basics ultrasonic_publisher\\n\\n# Expected Output:\\n# [INFO] [ultrasonic_sensor_node]: Ultrasonic Publisher initialized @ 10 Hz\\n# [INFO] [ultrasonic_sensor_node]: Publishing ultrasonic distance: 1.50 m\\n# [INFO] [ultrasonic_sensor_node]: Publishing ultrasonic distance: 1.62 m</code></pre></div>\\n\\n<div class=\\"alert-callout alert-info\\" style=\\"margin: 1.25rem 0;\\">\\n  <div class=\\"alert-icon\\">💡</div>\\n  <div class=\\"alert-body\\">\\n    <strong>Sourcing Note:</strong> You only need to run <code class=\\"inline-code\\">source install/setup.bash</code> in your terminal if you have <strong>not</strong> already added this line to your <code class=\\"inline-code\\">~/.bashrc</code> file (or if you are in the current session where you built the package for the very first time). If <code class=\\"inline-code\\">source ~/ros2_ws/install/setup.bash</code> is already present in your <code class=\\"inline-code\\">~/.bashrc</code>, every new terminal tab automatically sources the workspace on launch!\\n  </div>\\n</div>\\n\\n<div class=\\"code-breakdown-card\\" style=\\"margin: 1.75rem 0; border-left: 4px solid var(--accent-cyan, #06b6d4);\\">\\n  <h4 class=\\"code-breakdown-title\\" style=\\"display: flex; align-items: center; gap: 0.5rem;\\">\\n    <span>⚡</span> Developer Superpower: Accelerating Python Development with <code>--symlink-install</code>\\n  </h4>\\n  <p class=\\"code-breakdown-intro\\">\\n    Notice that we ran a simple <code class=\\"inline-code\\">colcon build</code> above. By default, <code class=\\"inline-code\\">colcon build</code> copies your Python scripts from <code class=\\"inline-code\\">src/</code> into the <code class=\\"inline-code\\">install/</code> directory. If you change a line of code in <code class=\\"inline-code\\">ultrasonic_sensor_node.py</code>, your edits <strong>will not take effect</strong> until you re-execute <code class=\\"inline-code\\">colcon build</code>!\\n  </p>\\n  <p style=\\"color: var(--text-secondary); line-height: 1.6;\\">\\n    To eliminate this repetitive re-building cycle, ROS 2 provides the <code class=\\"inline-code\\">--symlink-install</code> flag:\\n  </p>\\n\\n  <div class=\\"code-container\\" data-language=\\"bash\\" style=\\"margin: 0.75rem 0;\\">\\n    <div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n    <pre><code class=\\"language-bash\\">cd ~/ros2_ws\\ncolcon build --symlink-install --packages-select nexus_amr_basics\\nsource install/setup.bash</code></pre>\\n  </div>\\n\\n  <div class=\\"info-grid\\" style=\\"margin: 1rem 0;\\">\\n    <div class=\\"info-card\\">\\n      <h4>Standard Build (<code class=\\"inline-code\\">colcon build</code>)</h4>\\n      <p>Copies Python files from <code class=\\"inline-code\\">src/</code> into <code class=\\"inline-code\\">install/</code>. Requires running <code class=\\"inline-code\\">colcon build</code> after <em>every single code edit</em>.</p>\\n    </div>\\n    <div class=\\"info-card\\" style=\\"border-color: #38bdf8;\\">\\n      <h4 style=\\"color: #38bdf8;\\">Symlink Install (<code class=\\"inline-code\\">--symlink-install</code>)</h4>\\n      <p>Creates Linux symbolic links from <code class=\\"inline-code\\">install/</code> pointing directly back to your source files in <code class=\\"inline-code\\">src/</code>. Edit your Python code in VS Code, save, and rerun immediately without rebuilding!</p>\\n    </div>\\n  </div>\\n\\n  <div class=\\"alert alert-important\\" style=\\"margin-top: 1rem;\\">\\n    <div class=\\"alert-title\\">⚠️ The Golden Rule of --symlink-install</div>\\n    <p>While Python source changes are reflected instantly, you <strong>MUST still re-run colcon build</strong> whenever you:</p>\\n    <ol>\\n      <li>Add or modify an entry point in <code class=\\"inline-code\\">setup.py</code>.</li>\\n      <li>Add a new dependency to <code class=\\"inline-code\\">package.xml</code>.</li>\\n      <li>Add new launch files or YAML config files.</li>\\n    </ol>\\n  </div>\\n</div>\\n\\n<p>In a <strong>second terminal</strong>, inspect the live ultrasonic telemetry using progressive verification steps:</p>\\n\\n<p><strong>Step 1: Verify the topic appears on the active DDS network:</strong></p>\\n<div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash (Terminal 2 - Topic Discovery)</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\">source /opt/ros/jazzy/setup.bash\\nros2 topic list\\n\\n# Expected Output:\\n# /parameter_events\\n# /rosout\\n# /sensor/ultrasonic_front</code></pre></div>\\n\\n<p><strong>Step 2: Echo live sensor telemetry (Press Ctrl+C when done):</strong></p>\\n<div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash (Terminal 2 - Telemetry Echo)</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\">ros2 topic echo /sensor/ultrasonic_front\\n\\n# Expected Output:\\n# data: 1.5034\\n# ---\\n# data: 1.6219\\n# ---\\n# (Press Ctrl+C to stop echoing)</code></pre></div>\\n\\n<p><strong>Step 3: Measure actual streaming frequency:</strong></p>\\n<div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash (Terminal 2 - Frequency Measurement)</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\">ros2 topic hz /sensor/ultrasonic_front\\n\\n# Expected Output:\\n# average rate: 10.012\\n# min: 0.098s max: 0.102s std dev: 0.0012s window: 10\\n# (Press Ctrl+C to stop)</code></pre></div>\\n<h2 id=\\"5-writing-the-subscriber-node\\">5. Writing the Collision Safety Monitor Subscriber Node</h2>\\n\\n<div class=\\"alert alert-info alert-briefing\\">\\n  <div class=\\"alert-icon\\">🛑</div>\\n  <div class=\\"alert-content\\">\\n    <div class=\\"alert-title\\">Robotics Flight Operations Mission Briefing: AMR Collision Safety Supervisor Subscriber</div>\\n    <div class=\\"alert-body\\">\\n      <strong>Physical AMR Context &amp; Operational Challenge:</strong><br>\\n      A sensor publisher merely reports raw physical measurements; it possesses no operational authority over the robot's motion. To comply with industrial safety standards, AMRs deploy dedicated supervisory monitor nodes that audit incoming telemetry in real-time and trigger protective stops whenever safety margins are violated.\\n      <br><br>\\n      <strong>Architectural Role &amp; Why This Mechanism:</strong><br>\\n      Rather than polling the network or busy-waiting, a <strong>ROS 2 Subscriber</strong> registers a callback function that is triggered event-driven whenever a new packet arrives at the DDS DataReader. This ensures zero CPU waste during idle conditions and microsecond response times upon packet arrival.\\n      <br><br>\\n      <strong>Flight Objective &amp; Behavioral Outcome:</strong><br>\\n      Construct a Python ROS 2 Subscriber node that connects to <code>/sensor/ultrasonic_front</code>, unpacks incoming <code>Range</code> messages, evaluates distance against a 0.50 m safety threshold, and logs critical emergency braking alerts when an obstacle breaches the buffer.\\n    </div>\\n  </div>\\n</div>\\n\\n\\n<div class=\\"alert-callout alert-info\\" style=\\"margin: 1.5rem 0;\\">\\n  <div class=\\"alert-icon\\">🔍</div>\\n  <div class=\\"alert-body\\">\\n    <strong>Best Practice: Inspecting Topic &amp; Interface Schema Before Subscribing</strong><br>\\n    When implementing a subscriber, discover the active topic's message type and inspect its schema before writing your callback logic:\\n    <br><br>\\n    <strong>1. Query the message type advertised on the topic:</strong>\\n    <div class=\\"code-container\\" data-language=\\"bash\\" style=\\"margin: 0.6rem 0;\\">\\n      <div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n      <pre><code class=\\"language-bash\\">ros2 topic type /sensor/ultrasonic_front\\n# Output: sensor_msgs/msg/Range</code></pre>\\n    </div>\\n    <strong>2. Inspect the fields to determine what attributes your callback must extract:</strong>\\n    <div class=\\"code-container\\" data-language=\\"bash\\" style=\\"margin: 0.6rem 0;\\">\\n      <div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n      <pre><code class=\\"language-bash\\">ros2 interface show sensor_msgs/msg/Range</code></pre>\\n    </div>\\n    <p style=\\"margin: 0.5rem 0 0 0; line-height: 1.6;\\">\\n      By checking <code class=\\"inline-code\\">ros2 interface show</code>, you immediately know that the distance reading is stored in <code class=\\"inline-code\\">msg.range</code> (not <code class=\\"inline-code\\">msg.data</code>). Inside your subscriber callback, you simply read <code class=\\"inline-code\\">distance = msg.range</code>.\\n    </p>\\n  </div>\\n</div>\\n\\n<p>Now create the receiving node: <code class=\\"inline-code\\">~/ros2_ws/src/nexus_amr_basics/nexus_amr_basics/collision_monitor_node.py</code>. This node subscribes to <code class=\\"inline-code\\">/sensor/ultrasonic_front</code> and enforces an emergency stop buffer:</p>\\n\\n<div class=\\"code-container ide-code-window\\" data-language=\\"python\\">\\n  <div class=\\"code-header\\">\\n    <div class=\\"code-dots\\"><span class=\\"dot red\\"></span><span class=\\"dot yellow\\"></span><span class=\\"dot green\\"></span></div>\\n    <span class=\\"code-filename\\">collision_monitor_node.py &mdash; AMR Collision Supervisor</span>\\n  </div>\\n  <pre><code class=\\"language-python\\">import rclpy\\nfrom rclpy.node import Node\\nfrom sensor_msgs.msg import Range\\n\\n\\nclass CollisionSafetySubscriber(Node):\\n    &quot;&quot;&quot;\\n    AMR Collision Safety Supervisor Node.\\n    Monitors ultrasonic proximity telemetry and enforces safety buffer.\\n    &quot;&quot;&quot;\\n\\n    def __init__(self):\\n        # Step 1: Initialize base Node with unique name &#x27;collision_monitor_node&#x27;\\n        super().__init__(&#x27;collision_monitor_node&#x27;)\\n\\n        # Step 2: Establish the physical safety threshold in meters\\n        # Obstacles closer than 50 cm trigger protective safety measures.\\n        self.safety_threshold_m = 0.50\\n\\n        # Step 3: Create DDS Subscription with compatible Default QoS\\n        # - Range: Expected message schema (sensor_msgs/msg/Range)\\n        # - &#x27;/sensor/ultrasonic_front&#x27;: Target topic\\n        # - self.distance_callback: Bound method called when new packet arrives\\n        # - 10: QoS queue depth (Uses Default QoS: RELIABLE + VOLATILE, matching the publisher)\\n        self.subscription = self.create_subscription(\\n            Range,\\n            &#x27;/sensor/ultrasonic_front&#x27;,\\n            self.distance_callback,\\n            10\\n        )\\n\\n        self.get_logger().info(\\n            f&#x27;CollisionSafetySubscriber initialized. Monitoring &quot;/sensor/ultrasonic_front&quot; (Threshold: {self.safety_threshold_m} m)...&#x27;\\n        )\\n\\n    def distance_callback(self, msg: Range):\\n        &quot;&quot;&quot;\\n        Invoked asynchronously by the ROS 2 executor whenever a distance measurement\\n        packet arrives at the DDS DataReader socket.\\n        &quot;&quot;&quot;\\n        distance = msg.range\\n\\n        # Evaluate physical safety invariant\\n        if distance &lt; self.safety_threshold_m:\\n            # Critical hazard: obstacle within safety envelope!\\n            self.get_logger().error(\\n                f&#x27;ALERT: Obstacle detected at {distance:.2f} m! Distance &lt; {self.safety_threshold_m} m -&gt; TRIGGERING EMERGENCY BRAKE!&#x27;\\n            )\\n        else:\\n            # Nominal path clearance: safe for autonomous locomotion\\n            self.get_logger().info(\\n                f&#x27;STATUS: Distance {distance:.2f} m &gt;= {self.safety_threshold_m} m -&gt; Nominal path clearance confirmed.&#x27;\\n            )\\n\\n\\ndef main(args=None):\\n    # Initialize ROS 2 communications\\n    rclpy.init(args=args)\\n\\n    # Instantiate the subscriber node\\n    node = CollisionSafetySubscriber()\\n\\n    try:\\n        # Blocks in single-threaded event loop waiting for incoming DDS messages\\n        rclpy.spin(node)\\n    except KeyboardInterrupt:\\n        pass\\n    finally:\\n        # Clean teardown: unregister subscription endpoint from network graph\\n        node.destroy_node()\\n        rclpy.shutdown()\\n\\n\\nif __name__ == &#x27;__main__&#x27;:\\n    main()\\n</code></pre>\\n</div>\\n\\n<div class=\\"code-breakdown-card\\">\\n  <h4 class=\\"code-breakdown-title\\">🔬 Core Code Deep Dive &amp; Operational Breakdown: CollisionSafetySubscriber Mechanics</h4>\\n  <p class=\\"code-breakdown-intro\\">Let's dissect how this Collision Safety Monitor Subscriber receives and audits sensor data:</p>\\n  <ul class=\\"code-breakdown-list\\">\\n    <li class=\\"code-breakdown-item\\"><strong>DDS Subscription &amp; QoS Match:</strong> <code>self.create_subscription(Range, '/sensor/ultrasonic_front', self.distance_callback, 10)</code> binds this node to DDS DataReader notifications. Using queue depth <code>10</code> matches the publisher's Default QoS Profile (<code>RELIABLE</code>, <code>VOLATILE</code>), guaranteeing seamless packet reception.</li>\\n    <li class=\\"code-breakdown-item\\"><strong>Event-Driven Callback Dispatch:</strong> <code>def distance_callback(self, msg: Range):</code> receives the deserialized message directly. The callback executes synchronously on the executor thread; heavy computation should be avoided here to keep the queue clear.</li>\\n    <li class=\\"code-breakdown-item\\"><strong>Threshold Evaluation & Safety Invariant:</strong> <code>if distance < self.safety_threshold_m:</code> evaluates whether an obstacle has breached the safety buffer. In a complete AMR stack, this branch dispatches zero-velocity commands to the motor controller.</li>\\n    <li class=\\"code-breakdown-item\\"><strong>Clean Node Teardown:</strong> The <code>finally:</code> block calls <code>node.destroy_node()</code> and <code>rclpy.shutdown()</code>, ensuring DDS unregisters the subscriber from the network graph cleanly.</li>\\n  </ul>\\n</div>\\n\\n\\n<div class=\\"file-edit-instruction-card\\">\\n  <div class=\\"file-edit-header\\">\\n    <div class=\\"file-edit-header-left\\">\\n      <span>📝 Step-by-Step File Modification Guide</span>\\n    </div>\\n    <span class=\\"file-edit-badge\\">~/ros2_ws/src/nexus_amr_basics/setup.py</span>\\n  </div>\\n  <div class=\\"file-edit-body\\">\\n    <div class=\\"file-edit-step\\">\\n      <div class=\\"file-edit-step-title\\">\\n        <span class=\\"step-num-pill\\">Step 1</span>\\n        <span>Open the Target File</span>\\n      </div>\\n      <p class=\\"step-description\\">Open <code class=\\"inline-code\\">~/ros2_ws/src/nexus_amr_basics/setup.py</code> in your editor or IDE.</p>\\n    </div>\\n\\n    <div class=\\"file-edit-step\\">\\n      <div class=\\"file-edit-step-title\\">\\n        <span class=\\"step-num-pill\\">Step 2</span>\\n        <span>Locate Insertion Point &amp; Add Lines</span>\\n      </div>\\n      <p class=\\"step-description\\">Locate the <code class=\\"inline-code\\">entry_points</code> dictionary and append the collision safety monitor subscriber to <code class=\\"inline-code\\">'console_scripts'</code>:</p>\\n      <div class=\\"code-container\\" data-language=\\"python\\">\\n        <div class=\\"code-header\\"><span class=\\"code-lang-tag\\">python</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n        <pre><code class=\\"language-python\\">    entry_points={\\n        'console_scripts': [\\n            'ultrasonic_publisher = nexus_amr_basics.ultrasonic_sensor_node:main',\\n            # &gt;&gt;&gt; REGISTER COLLISION SAFETY MONITOR SUBSCRIBER &lt;&lt;&lt;\\n            'collision_monitor = nexus_amr_basics.collision_monitor_node:main',\\n        ],\\n    },</code></pre>\\n      </div>\\n    </div>\\n\\n    <div class=\\"file-edit-step\\">\\n      <div class=\\"file-edit-step-title\\">\\n        <span class=\\"step-num-pill\\">Step 3</span>\\n        <span>Verify the Full File After Editing</span>\\n      </div>\\n      <p class=\\"step-description\\">Self-check your file against the complete reference below to confirm indentation, closing brackets, and commas:</p>\\n      <details class=\\"file-edit-dropdown\\">\\n        <summary class=\\"file-edit-summary\\">\\n          <span>📄 View Complete setup.py with Publisher &amp; Subscriber</span>\\n          <span class=\\"file-edit-toggle-icon\\">▶</span>\\n        </summary>\\n        <div class=\\"file-edit-dropdown-content\\">\\n          <div class=\\"code-container\\" data-language=\\"python\\">\\n            <div class=\\"code-header\\"><span class=\\"code-lang-tag\\">python</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n            <pre><code class=\\"language-python\\">from setuptools import find_packages, setup\\n\\npackage_name = &#x27;nexus_amr_basics&#x27;\\n\\nsetup(\\n    name=package_name,\\n    version=&#x27;1.0.0&#x27;,\\n    packages=find_packages(exclude=[&#x27;test&#x27;]),\\n    data_files=[\\n        (&#x27;share/ament_index/resource_index/packages&#x27;, [&#x27;resource/&#x27; + package_name]),\\n        (&#x27;share/&#x27; + package_name, [&#x27;package.xml&#x27;]),\\n    ],\\n    install_requires=[&#x27;setuptools&#x27;],\\n    zip_safe=True,\\n    maintainer=&#x27;Nexus AMR Academy&#x27;,\\n    maintainer_email=&#x27;instructor@botforge.io&#x27;,\\n    description=&#x27;ROS 2 Sensor &amp; Telemetry Fundamentals&#x27;,\\n    license=&#x27;Apache-2.0&#x27;,\\n    tests_require=[&#x27;pytest&#x27;],\\n    entry_points={\\n        &#x27;console_scripts&#x27;: [\\n            &#x27;ultrasonic_publisher = nexus_amr_basics.ultrasonic_sensor_node:main&#x27;,\\n            &#x27;collision_monitor = nexus_amr_basics.collision_monitor_node:main&#x27;,\\n        ],\\n    },\\n)</code></pre>\\n          </div>\\n        </div>\\n      </details>\\n    </div>\\n  </div>\\n</div>\\n<h2 id=\\"6-dual-node-communication-drill\\">6. Dual-Node Communication &amp; Verification Drill</h2>\\n<p>Now that both the Publisher (<code class=\\"inline-code\\">ultrasonic_publisher</code>) and Subscriber (<code class=\\"inline-code\\">collision_monitor</code>) are registered in <code class=\\"inline-code\\">setup.py</code>, rebuild your workspace using <code class=\\"inline-code\\">--symlink-install</code> and verify the complete communication pipeline in real-time:</p>\\n\\n<div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash (Rebuild Workspace)</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\">cd ~/ros2_ws\\ncolcon build --symlink-install --packages-select nexus_amr_basics\\nsource install/setup.bash  # (Only if not already in ~/.bashrc)</code></pre>\\n</div>\\n\\n<p>Open three terminals (or split Terminator panes) to execute the end-to-end telemetry and safety supervisor system:</p>\\n\\n<div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash (Terminal 1 - Sensor Publisher)</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\">cd ~/ros2_ws\\nsource install/setup.bash  # (Only if not already in ~/.bashrc)\\nros2 run nexus_amr_basics ultrasonic_publisher</code></pre>\\n</div>\\n\\n<div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash (Terminal 2 - Safety Supervisor Subscriber)</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\">cd ~/ros2_ws\\nsource install/setup.bash  # (Only if not already in ~/.bashrc)\\nros2 run nexus_amr_basics collision_monitor\\n\\n# Expected Output (Live Communication Pipeline Verified):\\n# [INFO] [collision_safety_monitor]: Initialized. Monitoring /sensor/ultrasonic_front (Threshold: 0.50 m)\\n# [INFO] [collision_safety_monitor]: Ultrasonic Distance: 1.52 m -> PATH CLEAR\\n# [INFO] [collision_safety_monitor]: Ultrasonic Distance: 1.10 m -> PATH CLEAR\\n# [WARN] [collision_safety_monitor]: ⚠️ EMERGENCY BRAKE ACTIVATED! Distance: 0.38 m &lt; 0.50 m!</code></pre>\\n</div>\\n\\n<div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash (Terminal 3 - Graph Introspection)</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\"># Verify both nodes are connected to the /sensor/ultrasonic_front topic:\\nros2 topic info /sensor/ultrasonic_front\\n# Expected Output:\\n# Type: sensor_msgs/msg/Range\\n# Publisher count: 1\\n# Subscription count: 1</code></pre>\\n</div>\\n</section>\\n\\n<section class=\\"lesson-section\\">\\n<h2 id=\\"7-quality-of-service-qos-deep-dive\\">7. Quality of Service (QoS) Deep Dive</h2>\\n<p>Unlike ROS 1 (which used raw TCP sockets with default settings), ROS 2 allows developers to fine-tune transport behavior per topic using DDS <strong>QoS Profiles</strong>. Real robots operate in environments where network bandwidth, latency, and reliability vary dramatically.</p>\\n\\n<div class=\\"table-responsive\\">\\n  <table>\\n    <thead>\\n      <tr>\\n        <th>QoS Policy</th>\\n        <th>Settings</th>\\n        <th>Behavior &amp; Robotics Use Case</th>\\n      </tr>\\n    </thead>\\n    <tbody>\\n      <tr>\\n        <td><strong>Reliability</strong></td>\\n        <td><code class=\\"inline-code\\">RELIABLE</code><br><code class=\\"inline-code\\">BEST_EFFORT</code></td>\\n        <td>\\n          <strong>RELIABLE:</strong> Guarantees delivery via packet acknowledgments and retransmission (like TCP). Used for state machines, e-stop, and navigation goals.<br>\\n          <strong>BEST_EFFORT:</strong> Drops packets if delayed, minimal latency (like UDP). Essential for high-rate sensor streams (30 Hz cameras, 10 Hz LiDAR).\\n        </td>\\n      </tr>\\n      <tr>\\n        <td><strong>Durability</strong></td>\\n        <td><code class=\\"inline-code\\">VOLATILE</code><br><code class=\\"inline-code\\">TRANSIENT_LOCAL</code></td>\\n        <td>\\n          <strong>VOLATILE:</strong> Messages are not retained. Late-joining subscribers only receive messages published after they connect.<br>\\n          <strong>TRANSIENT_LOCAL:</strong> \\"Latched\\" topic. The publisher keeps the last N messages in memory so late-joining nodes immediately receive critical data (e.g., <code class=\\"inline-code\\">/map</code> or robot footprint).\\n        </td>\\n      </tr>\\n      <tr>\\n        <td><strong>History &amp; Depth</strong></td>\\n        <td><code class=\\"inline-code\\">KEEP_LAST (N)</code><br><code class=\\"inline-code\\">KEEP_ALL</code></td>\\n        <td>\\n          <strong>KEEP_LAST:</strong> Maintains a ring buffer of size <code class=\\"inline-code\\">N</code> in memory. Older messages are discarded when the buffer is full.<br>\\n          <strong>KEEP_ALL:</strong> Buffers all messages until delivered (can cause unbounded memory consumption if subscriber hangs).\\n        </td>\\n      </tr>\\n    </tbody>\\n  </table>\\n</div>\\n\\n<h3 id=\\"71-the-qos-compatibility-rule\\">7.1 The QoS Compatibility Rule (Rx &le; Tx)</h3>\\n<p>In ROS 2, a publisher and subscriber will only connect if their QoS profiles are compatible. The general rule is <strong>\\"Requested &le; Offered\\" (Rx &le; Tx)</strong>: a subscriber cannot demand a higher guarantee of service than the publisher is offering.</p>\\n\\n<div class=\\"table-responsive\\">\\n  <table>\\n    <thead>\\n      <tr>\\n        <th>Publisher Offers (Tx)</th>\\n        <th>Subscriber Requests (Rx)</th>\\n        <th>Connection Compatible?</th>\\n      </tr>\\n    </thead>\\n    <tbody>\\n      <tr>\\n        <td><span class=\\"badge badge-success\\">RELIABLE</span></td>\\n        <td><span class=\\"badge badge-success\\">RELIABLE</span></td>\\n        <td><strong>Compatible ✅</strong> (Data delivered reliably)</td>\\n      </tr>\\n      <tr>\\n        <td><span class=\\"badge badge-success\\">RELIABLE</span></td>\\n        <td><span class=\\"badge badge-warning\\">BEST_EFFORT</span></td>\\n        <td><strong>Compatible ✅</strong> (Subscriber accepts best-effort delivery)</td>\\n      </tr>\\n      <tr>\\n        <td><span class=\\"badge badge-warning\\">BEST_EFFORT</span></td>\\n        <td><span class=\\"badge badge-danger\\">RELIABLE</span></td>\\n        <td><strong>INCOMPATIBLE ❌ (Silent Failure)</strong> &mdash; No data will ever be delivered!</td>\\n      </tr>\\n      <tr>\\n        <td><span class=\\"badge badge-warning\\">BEST_EFFORT</span></td>\\n        <td><span class=\\"badge badge-warning\\">BEST_EFFORT</span></td>\\n        <td><strong>Compatible ✅</strong> (Low-latency stream)</td>\\n      </tr>\\n    </tbody>\\n  </table>\\n</div>\\n\\n<h3 id=\\"72-implementing-custom-qos-in-python\\">7.2 Implementing Custom QoS in Python</h3>\\n<p>ROS 2 provides convenient pre-built profiles in <code class=\\"inline-code\\">rclpy.qos</code>:</p>\\n\\n<div class=\\"code-container\\" data-language=\\"python\\">\\n  <div class=\\"code-header\\"><span class=\\"code-lang-tag\\">python</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n  <pre><code class=\\"language-python\\">from rclpy.qos import QoSProfile, ReliabilityPolicy, DurabilityPolicy, qos_profile_sensor_data\\n\\n# Option A: Use standard sensor profile (Best-effort, Volatile, Depth 5)\\nself.lidar_sub = self.create_subscription(\\n    LaserScan,\\n    '/scan',\\n    self.scan_callback,\\n    qos_profile=qos_profile_sensor_data\\n)\\n\\n# Option B: Author a custom mission-critical profile\\ncustom_qos = QoSProfile(\\n    reliability=ReliabilityPolicy.RELIABLE,\\n    durability=DurabilityPolicy.TRANSIENT_LOCAL,\\n    depth=1\\n)\\nself.map_sub = self.create_subscription(\\n    OccupancyGrid,\\n    '/map',\\n    self.map_callback,\\n    qos_profile=custom_qos\\n)\\n</code></pre>\\n</div>\\n</section>\\n\\n<section class=\\"lesson-section\\">\\n<hr class=\\"divider\\">\\n<h3 id=\\"73-multi-pubsub-architecture\\">7.3 Multi-Topic Architecture: Single Node with Multiple Publishers &amp; Subscribers</h3>\\n<p>A common misconception among beginner robotics engineers is that a ROS 2 node can only be <em>either</em> a publisher <em>or</em> a subscriber, or that a node is restricted to a single topic. In reality, a ROS 2 node is an object-oriented Python or C++ process that can instantiate <strong>arbitrarily many publishers and subscribers</strong> across different topics simultaneously.</p>\\n\\n<p>Autonomous Mobile Robots (AMRs) routinely use single supervisory nodes to act as <strong>Sensor Fusion Hubs</strong>, <strong>Safety Arbitrators</strong>, and <strong>Command Multiplexers</strong>:</p>\\n\\n<div class=\\"multi-pubsub-infographic\\">\\n  <div class=\\"infographic-title-row\\">\\n    <div class=\\"infographic-pill\\">\\n      <span>📐 M:N GRAPH TOPOLOGY · RQT GRAPH ARCHITECTURE</span>\\n    </div>\\n    <span class=\\"ros-version-tag\\">Production ROS 2 Node Architecture</span>\\n  </div>\\n\\n  <div class=\\"svg-graph-container\\">\\n    <svg viewBox=\\"0 0 1200 610\\" class=\\"multi-topic-svg\\" xmlns=\\"http://www.w3.org/2000/svg\\">\\n      <defs>\\n        <!-- Gradients -->\\n        <linearGradient id=\\"centralNodeGrad\\" x1=\\"0%\\" y1=\\"0%\\" x2=\\"100%\\" y2=\\"100%\\">\\n          <stop offset=\\"0%\\" stop-color=\\"#faf5ff\\" stop-opacity=\\"1\\" />\\n          <stop offset=\\"50%\\" stop-color=\\"#fdf4ff\\" stop-opacity=\\"1\\" />\\n          <stop offset=\\"100%\\" stop-color=\\"#ffffff\\" stop-opacity=\\"1\\" />\\n        </linearGradient>\\n\\n        <linearGradient id=\\"nodePillGrad\\" x1=\\"0%\\" y1=\\"0%\\" x2=\\"100%\\" y2=\\"100%\\">\\n          <stop offset=\\"0%\\" stop-color=\\"#ffffff\\" stop-opacity=\\"1\\" />\\n          <stop offset=\\"100%\\" stop-color=\\"#f8fafc\\" stop-opacity=\\"1\\" />\\n        </linearGradient>\\n\\n        <linearGradient id=\\"cyanLineGrad\\" x1=\\"0%\\" y1=\\"0%\\" x2=\\"100%\\" y2=\\"0%\\">\\n          <stop offset=\\"0%\\" stop-color=\\"#06b6d4\\" />\\n          <stop offset=\\"100%\\" stop-color=\\"#38bdf8\\" />\\n        </linearGradient>\\n\\n        <linearGradient id=\\"skyLineGrad\\" x1=\\"0%\\" y1=\\"0%\\" x2=\\"100%\\" y2=\\"0%\\">\\n          <stop offset=\\"0%\\" stop-color=\\"#38bdf8\\" />\\n          <stop offset=\\"100%\\" stop-color=\\"#818cf8\\" />\\n        </linearGradient>\\n\\n        <linearGradient id=\\"violetLineGrad\\" x1=\\"0%\\" y1=\\"0%\\" x2=\\"100%\\" y2=\\"0%\\">\\n          <stop offset=\\"0%\\" stop-color=\\"#818cf8\\" />\\n          <stop offset=\\"100%\\" stop-color=\\"#c084fc\\" />\\n        </linearGradient>\\n\\n        <linearGradient id=\\"greenLineGrad\\" x1=\\"0%\\" y1=\\"0%\\" x2=\\"100%\\" y2=\\"0%\\">\\n          <stop offset=\\"0%\\" stop-color=\\"#10b981\\" />\\n          <stop offset=\\"100%\\" stop-color=\\"#34d399\\" />\\n        </linearGradient>\\n\\n        <linearGradient id=\\"amberLineGrad\\" x1=\\"0%\\" y1=\\"0%\\" x2=\\"100%\\" y2=\\"0%\\">\\n          <stop offset=\\"0%\\" stop-color=\\"#f59e0b\\" />\\n          <stop offset=\\"100%\\" stop-color=\\"#fbbf24\\" />\\n        </linearGradient>\\n\\n        <!-- Arrow Markers -->\\n        <marker id=\\"arrow-cyan\\" viewBox=\\"0 0 10 10\\" refX=\\"7\\" refY=\\"5\\" markerWidth=\\"6\\" markerHeight=\\"6\\" orient=\\"auto-start-reverse\\">\\n          <path d=\\"M 0 1.5 L 8 5 L 0 8.5 z\\" fill=\\"#38bdf8\\" />\\n        </marker>\\n        <marker id=\\"arrow-sky\\" viewBox=\\"0 0 10 10\\" refX=\\"7\\" refY=\\"5\\" markerWidth=\\"6\\" markerHeight=\\"6\\" orient=\\"auto-start-reverse\\">\\n          <path d=\\"M 0 1.5 L 8 5 L 0 8.5 z\\" fill=\\"#38bdf8\\" />\\n        </marker>\\n        <marker id=\\"arrow-violet\\" viewBox=\\"0 0 10 10\\" refX=\\"7\\" refY=\\"5\\" markerWidth=\\"6\\" markerHeight=\\"6\\" orient=\\"auto-start-reverse\\">\\n          <path d=\\"M 0 1.5 L 8 5 L 0 8.5 z\\" fill=\\"#c084fc\\" />\\n        </marker>\\n        <marker id=\\"arrow-green\\" viewBox=\\"0 0 10 10\\" refX=\\"7\\" refY=\\"5\\" markerWidth=\\"6\\" markerHeight=\\"6\\" orient=\\"auto-start-reverse\\">\\n          <path d=\\"M 0 1.5 L 8 5 L 0 8.5 z\\" fill=\\"#34d399\\" />\\n        </marker>\\n        <marker id=\\"arrow-amber\\" viewBox=\\"0 0 10 10\\" refX=\\"7\\" refY=\\"5\\" markerWidth=\\"6\\" markerHeight=\\"6\\" orient=\\"auto-start-reverse\\">\\n          <path d=\\"M 0 1.5 L 8 5 L 0 8.5 z\\" fill=\\"#fbbf24\\" />\\n        </marker>\\n\\n        <!-- Glow Filters -->\\n        <filter id=\\"glow-purple\\" x=\\"-20%\\" y=\\"-20%\\" width=\\"140%\\" height=\\"140%\\">\\n          <feDropShadow dx=\\"0\\" dy=\\"0\\" stdDeviation=\\"6\\" flood-color=\\"#a855f7\\" flood-opacity=\\"0.4\\" />\\n        </filter>\\n        <filter id=\\"text-backdrop\\" x=\\"-15%\\" y=\\"-15%\\" width=\\"130%\\" height=\\"130%\\">\\n          <feDropShadow dx=\\"0\\" dy=\\"0\\" stdDeviation=\\"3\\" flood-color=\\"#ffffff\\" flood-opacity=\\"0.95\\" />\\n        </filter>\\n      </defs>\\n\\n      <!-- Solid Dark Background Canvas -->\\n      <rect x=\\"0\\" y=\\"0\\" width=\\"1200\\" height=\\"610\\" fill=\\"#ffffff\\" stroke=\\"#e2e8f0\\" stroke-width=\\"1.5\\" rx=\\"14\\" />\\n      <pattern id=\\"dotPattern\\" x=\\"0\\" y=\\"0\\" width=\\"24\\" height=\\"24\\" patternUnits=\\"userSpaceOnUse\\">\\n        <circle cx=\\"12\\" cy=\\"12\\" r=\\"1\\" fill=\\"#94a3b8\\" fill-opacity=\\"0.2\\" />\\n      </pattern>\\n      <rect x=\\"0\\" y=\\"0\\" width=\\"1200\\" height=\\"610\\" fill=\\"url(#dotPattern)\\" rx=\\"14\\" />\\n\\n      <!-- ================= CURVED WIRING (DDS TOPIC HIGHWAYS) ================= -->\\n\\n      <!-- Wire 1: Ultrasonic -> Supervisor (Curved Bézier) -->\\n      <path d=\\"M 215,95 C 310,95 365,175 445,175\\" \\n            fill=\\"none\\" stroke=\\"url(#cyanLineGrad)\\" stroke-width=\\"2.5\\" marker-end=\\"url(#arrow-cyan)\\" class=\\"curved-wire-anim\\" />\\n\\n      <!-- Wire 3: Teleop -> Supervisor (Curved Bézier) -->\\n      <path d=\\"M 215,425 C 310,425 365,345 445,345\\" \\n            fill=\\"none\\" stroke=\\"url(#violetLineGrad)\\" stroke-width=\\"2.5\\" marker-end=\\"url(#arrow-violet)\\" class=\\"curved-wire-anim\\" />\\n\\n      <!-- Wire 4: Supervisor -> Motor Controller (Curved Bézier) -->\\n      <path d=\\"M 705,205 C 785,205 870,155 955,155\\" \\n            fill=\\"none\\" stroke=\\"url(#greenLineGrad)\\" stroke-width=\\"2.5\\" marker-end=\\"url(#arrow-green)\\" class=\\"curved-wire-anim\\" />\\n\\n      <!-- Wire 5: Supervisor -> RViz Dashboard (Curved Bézier) -->\\n      <path d=\\"M 705,315 C 785,315 870,355 955,355\\" \\n            fill=\\"none\\" stroke=\\"url(#amberLineGrad)\\" stroke-width=\\"2.5\\" marker-end=\\"url(#arrow-amber)\\" class=\\"curved-wire-anim\\" />\\n\\n\\n      <!-- ================= /odom TOPIC: 1 PUBLISHER -> 2 EXPLICIT SUBSCRIBER BRANCHES ================= -->\\n\\n      <!-- Trunk: /wheel_odom_node to Split Junction (Solid blue) -->\\n      <path d=\\"M 215,260 L 310,260\\" \\n            fill=\\"none\\" stroke=\\"#38bdf8\\" stroke-width=\\"3\\" />\\n\\n      <!-- /odom Branch 1 -> amr_safety_supervisor_node (Subscriber 1) -->\\n      <path d=\\"M 310,260 L 415,260\\" \\n            fill=\\"none\\" stroke=\\"#38bdf8\\" stroke-width=\\"2.5\\" marker-end=\\"url(#arrow-sky)\\" class=\\"curved-wire-anim\\" />\\n\\n      <!-- /odom Branch 2 -> rviz2_dashboard (Subscriber 2, Smooth Curved Path) -->\\n      <path d=\\"M 310,260 C 340,320 370,535 610,535 C 830,535 885,445 955,395\\" \\n            fill=\\"none\\" stroke=\\"#38bdf8\\" stroke-width=\\"2.5\\" marker-end=\\"url(#arrow-sky)\\" class=\\"curved-wire-anim\\" />\\n\\n      <!-- Junction Split Node Indicator (Glowing Cyan Dot) -->\\n      <circle cx=\\"310\\" cy=\\"260\\" r=\\"7\\" fill=\\"#0284c7\\" stroke=\\"#38bdf8\\" stroke-width=\\"2\\" />\\n      <circle cx=\\"310\\" cy=\\"260\\" r=\\"3\\" fill=\\"#ffffff\\" />\\n\\n\\n      <!-- ================= TOPIC NAMES (CLEAN TEXT PLACED WITH CLEAR GAPS - NO OVALS) ================= -->\\n\\n      <!-- Topic 1: /sensor/ultrasonic_front (Placed 28px ABOVE curve) -->\\n      <g transform=\\"translate(325, 68)\\" filter=\\"url(#text-backdrop)\\">\\n        <text x=\\"0\\" y=\\"0\\" fill=\\"#0284c7\\" font-family=\\"'JetBrains Mono', monospace\\" font-size=\\"12\\" font-weight=\\"800\\" text-anchor=\\"middle\\">/sensor/ultrasonic_front</text>\\n        <text x=\\"0\\" y=\\"15\\" fill=\\"#94a3b8\\" font-family=\\"'Plus Jakarta Sans', sans-serif\\" font-size=\\"9.5\\" text-anchor=\\"middle\\">sensor_msgs/Range · 10 Hz</text>\\n      </g>\\n\\n      <!-- Topic 2: /odom Shared Trunk Label (Placed ABOVE the junction) -->\\n      <g transform=\\"translate(285, 226)\\" filter=\\"url(#text-backdrop)\\">\\n        <text x=\\"0\\" y=\\"0\\" fill=\\"#0284c7\\" font-family=\\"'JetBrains Mono', monospace\\" font-size=\\"12.5\\" font-weight=\\"800\\" text-anchor=\\"middle\\">/odom</text>\\n        <text x=\\"0\\" y=\\"14\\" fill=\\"#94a3b8\\" font-family=\\"'Plus Jakarta Sans', sans-serif\\" font-size=\\"9.5\\" text-anchor=\\"middle\\">nav_msgs/Odometry · 50 Hz</text>\\n      </g>\\n\\n      <!-- Junction Callout Tag -->\\n      <g transform=\\"translate(310, 282)\\" filter=\\"url(#text-backdrop)\\">\\n        <rect x=\\"-85\\" y=\\"-10\\" width=\\"170\\" height=\\"20\\" rx=\\"6\\" fill=\\"#ffffff\\" stroke=\\"#0284c7\\" stroke-width=\\"1.2\\" />\\n        <text x=\\"0\\" y=\\"4\\" fill=\\"#0284c7\\" font-family=\\"'JetBrains Mono', monospace\\" font-size=\\"8.5\\" font-weight=\\"800\\" text-anchor=\\"middle\\">⚡ 1 TOPIC ➔ 2 SUBSCRIBERS</text>\\n      </g>\\n\\n      <!-- Sub 1 Branch Label -->\\n      <g transform=\\"translate(365, 250)\\" filter=\\"url(#text-backdrop)\\">\\n        <text x=\\"0\\" y=\\"0\\" fill=\\"#38bdf8\\" font-family=\\"'JetBrains Mono', monospace\\" font-size=\\"9.5\\" font-weight=\\"700\\" text-anchor=\\"middle\\">➔ sub_odom</text>\\n      </g>\\n\\n      <!-- Sub 2 Branch Curve Label (Positioned 35px ABOVE the curve at y=500, with curve at y=535) -->\\n      <g transform=\\"translate(610, 492)\\" filter=\\"url(#text-backdrop)\\">\\n        <text x=\\"0\\" y=\\"0\\" fill=\\"#0284c7\\" font-family=\\"'JetBrains Mono', monospace\\" font-size=\\"11.5\\" font-weight=\\"800\\" text-anchor=\\"middle\\">/odom Branch ➔ Subscribed by /rviz2_dashboard (Sub 2)</text>\\n        <text x=\\"0\\" y=\\"15\\" fill=\\"#94a3b8\\" font-family=\\"'Plus Jakarta Sans', sans-serif\\" font-size=\\"9.5\\" text-anchor=\\"middle\\">DDS Multicast: 1 published message received by both nodes simultaneously</text>\\n      </g>\\n\\n      <!-- Topic 3: /teleop_cmd (Placed 28px BELOW curve) -->\\n      <g transform=\\"translate(325, 450)\\" filter=\\"url(#text-backdrop)\\">\\n        <text x=\\"0\\" y=\\"0\\" fill=\\"#7c3aed\\" font-family=\\"'JetBrains Mono', monospace\\" font-size=\\"12\\" font-weight=\\"800\\" text-anchor=\\"middle\\">/teleop_cmd</text>\\n        <text x=\\"0\\" y=\\"15\\" fill=\\"#94a3b8\\" font-family=\\"'Plus Jakarta Sans', sans-serif\\" font-size=\\"9.5\\" text-anchor=\\"middle\\">geometry_msgs/Twist · 20 Hz</text>\\n      </g>\\n\\n      <!-- Topic 4: /cmd_vel (Placed 28px ABOVE curve) -->\\n      <g transform=\\"translate(830, 135)\\" filter=\\"url(#text-backdrop)\\">\\n        <text x=\\"0\\" y=\\"0\\" fill=\\"#059669\\" font-family=\\"'JetBrains Mono', monospace\\" font-size=\\"12\\" font-weight=\\"800\\" text-anchor=\\"middle\\">/cmd_vel</text>\\n        <text x=\\"0\\" y=\\"15\\" fill=\\"#065f46\\" font-family=\\"'Plus Jakarta Sans', sans-serif\\" font-size=\\"9.5\\" text-anchor=\\"middle\\">geometry_msgs/Twist · Safe Vel (20 Hz)</text>\\n      </g>\\n\\n      <!-- Topic 5: /diagnostics/safety_status (Placed 30px BELOW curve) -->\\n      <g transform=\\"translate(830, 395)\\" filter=\\"url(#text-backdrop)\\">\\n        <text x=\\"0\\" y=\\"0\\" fill=\\"#b45309\\" font-family=\\"'JetBrains Mono', monospace\\" font-size=\\"12\\" font-weight=\\"800\\" text-anchor=\\"middle\\">/diagnostics/safety_status</text>\\n        <text x=\\"0\\" y=\\"15\\" fill=\\"#92400e\\" font-family=\\"'Plus Jakarta Sans', sans-serif\\" font-size=\\"9.5\\" text-anchor=\\"middle\\">std_msgs/String · Health Telemetry (1 Hz)</text>\\n      </g>\\n\\n\\n      <!-- ================= NODES AS OVALS ================= -->\\n\\n      <!-- --- LEFT COLUMN OVAL NODES (UPSTREAM PUBLISHERS) --- -->\\n\\n      <!-- Node 1: ultrasonic_node (Oval) -->\\n      <g transform=\\"translate(120, 95)\\" class=\\"node-oval-group\\">\\n        <rect x=\\"-95\\" y=\\"-26\\" width=\\"190\\" height=\\"52\\" rx=\\"26\\" fill=\\"url(#nodePillGrad)\\" stroke=\\"#06b6d4\\" stroke-width=\\"2\\" />\\n        <circle cx=\\"-70\\" cy=\\"-5\\" r=\\"4\\" fill=\\"#06b6d4\\" />\\n        <text x=\\"-58\\" y=\\"-2\\" fill=\\"#22d3ee\\" font-family=\\"'JetBrains Mono', monospace\\" font-size=\\"8.5\\" font-weight=\\"700\\">NODE</text>\\n        <text x=\\"16\\" y=\\"-2\\" fill=\\"#0f172a\\" font-family=\\"'JetBrains Mono', monospace\\" font-size=\\"10.5\\" font-weight=\\"800\\" text-anchor=\\"middle\\">/ultrasonic_node</text>\\n        <text x=\\"0\\" y=\\"13\\" fill=\\"#06b6d4\\" font-family=\\"'Plus Jakarta Sans', sans-serif\\" font-size=\\"9\\" font-weight=\\"600\\" text-anchor=\\"middle\\">Publisher (1 Topic)</text>\\n        <!-- Out Port Dot -->\\n        <circle cx=\\"95\\" cy=\\"0\\" r=\\"4.5\\" fill=\\"#38bdf8\\" stroke=\\"#ffffff\\" stroke-width=\\"1.5\\" />\\n      </g>\\n\\n      <!-- Node 2: wheel_odom_node (Oval) -->\\n      <g transform=\\"translate(120, 260)\\" class=\\"node-oval-group\\">\\n        <rect x=\\"-95\\" y=\\"-26\\" width=\\"190\\" height=\\"52\\" rx=\\"26\\" fill=\\"url(#nodePillGrad)\\" stroke=\\"#38bdf8\\" stroke-width=\\"2\\" />\\n        <circle cx=\\"-70\\" cy=\\"-5\\" r=\\"4\\" fill=\\"#38bdf8\\" />\\n        <text x=\\"-58\\" y=\\"-2\\" fill=\\"#38bdf8\\" font-family=\\"'JetBrains Mono', monospace\\" font-size=\\"8.5\\" font-weight=\\"700\\">NODE</text>\\n        <text x=\\"16\\" y=\\"-2\\" fill=\\"#0f172a\\" font-family=\\"'JetBrains Mono', monospace\\" font-size=\\"10.5\\" font-weight=\\"800\\" text-anchor=\\"middle\\">/wheel_odom_node</text>\\n        <text x=\\"0\\" y=\\"13\\" fill=\\"#38bdf8\\" font-family=\\"'Plus Jakarta Sans', sans-serif\\" font-size=\\"9\\" font-weight=\\"600\\" text-anchor=\\"middle\\">Publishes /odom (50Hz)</text>\\n        <!-- Out Port Dot -->\\n        <circle cx=\\"95\\" cy=\\"0\\" r=\\"4.5\\" fill=\\"#38bdf8\\" stroke=\\"#ffffff\\" stroke-width=\\"1.5\\" />\\n      </g>\\n\\n      <!-- Node 3: teleop_key_node (Oval) -->\\n      <g transform=\\"translate(120, 425)\\" class=\\"node-oval-group\\">\\n        <rect x=\\"-95\\" y=\\"-26\\" width=\\"190\\" height=\\"52\\" rx=\\"26\\" fill=\\"url(#nodePillGrad)\\" stroke=\\"#818cf8\\" stroke-width=\\"2\\" />\\n        <circle cx=\\"-70\\" cy=\\"-5\\" r=\\"4\\" fill=\\"#818cf8\\" />\\n        <text x=\\"-58\\" y=\\"-2\\" fill=\\"#818cf8\\" font-family=\\"'JetBrains Mono', monospace\\" font-size=\\"8.5\\" font-weight=\\"700\\">NODE</text>\\n        <text x=\\"16\\" y=\\"-2\\" fill=\\"#0f172a\\" font-family=\\"'JetBrains Mono', monospace\\" font-size=\\"10.5\\" font-weight=\\"800\\" text-anchor=\\"middle\\">/teleop_key_node</text>\\n        <text x=\\"0\\" y=\\"13\\" fill=\\"#818cf8\\" font-family=\\"'Plus Jakarta Sans', sans-serif\\" font-size=\\"9\\" font-weight=\\"600\\" text-anchor=\\"middle\\">Publisher (1 Topic)</text>\\n        <!-- Out Port Dot -->\\n        <circle cx=\\"95\\" cy=\\"0\\" r=\\"4.5\\" fill=\\"#c084fc\\" stroke=\\"#ffffff\\" stroke-width=\\"1.5\\" />\\n      </g>\\n\\n\\n      <!-- --- CENTRAL OVAL NODE (THE MULTI PUB & SUB HUB) --- -->\\n\\n      <g transform=\\"translate(575, 260)\\" class=\\"central-node-group\\">\\n        <!-- Outer Glowing Oval Capsule (Horizontal Elliptical Oval) -->\\n        <rect x=\\"-160\\" y=\\"-130\\" width=\\"320\\" height=\\"260\\" rx=\\"130\\" fill=\\"url(#centralNodeGrad)\\" stroke=\\"#a855f7\\" stroke-width=\\"3\\" filter=\\"url(#glow-purple)\\" />\\n        \\n        <!-- Header Pill Badge -->\\n        <rect x=\\"-90\\" y=\\"-115\\" width=\\"180\\" height=\\"20\\" rx=\\"10\\" fill=\\"#f3e8ff\\" stroke=\\"#d8b4fe\\" stroke-width=\\"1\\" />\\n        <text x=\\"0\\" y=\\"-101\\" fill=\\"#7e22ce\\" font-family=\\"'JetBrains Mono', monospace\\" font-size=\\"8.5\\" font-weight=\\"800\\" text-anchor=\\"middle\\">★ CENTRAL NODE (OVAL)</text>\\n\\n        <!-- Node Name -->\\n        <text x=\\"0\\" y=\\"-76\\" fill=\\"#0f172a\\" font-family=\\"'JetBrains Mono', monospace\\" font-size=\\"13.5\\" font-weight=\\"800\\" text-anchor=\\"middle\\">/amr_safety_supervisor_node</text>\\n        <text x=\\"0\\" y=\\"-58\\" fill=\\"#7c3aed\\" font-family=\\"'Plus Jakarta Sans', sans-serif\\" font-size=\\"9.5\\" font-weight=\\"700\\" text-anchor=\\"middle\\">Single Python Process (1 Node · Multiple Pubs &amp; Subs)</text>\\n\\n        <!-- Internal Subscriptions Card -->\\n        <g transform=\\"translate(-70, -10)\\">\\n          <rect x=\\"-60\\" y=\\"-34\\" width=\\"120\\" height=\\"68\\" rx=\\"8\\" fill=\\"#ffffff\\" stroke=\\"#bae6fd\\" stroke-width=\\"1.2\\" stroke-width=\\"1\\" />\\n          <text x=\\"0\\" y=\\"-18\\" fill=\\"#0284c7\\" font-family=\\"'Plus Jakarta Sans', sans-serif\\" font-size=\\"9\\" font-weight=\\"800\\" text-anchor=\\"middle\\">⚡ 3 SUBSCRIBERS</text>\\n          <text x=\\"-50\\" y=\\"-1\\" fill=\\"#334155\\" font-family=\\"'JetBrains Mono', monospace\\" font-size=\\"8\\">• sub_range (10Hz)</text>\\n          <text x=\\"-50\\" y=\\"13\\" fill=\\"#0284c7\\" font-family=\\"'JetBrains Mono', monospace\\" font-size=\\"8\\" font-weight=\\"800\\">• sub_odom (50Hz)</text>\\n          <text x=\\"-50\\" y=\\"27\\" fill=\\"#334155\\" font-family=\\"'JetBrains Mono', monospace\\" font-size=\\"8\\">• sub_teleop (20Hz)</text>\\n        </g>\\n\\n        <!-- Internal Publishers Card -->\\n        <g transform=\\"translate(70, -10)\\">\\n          <rect x=\\"-60\\" y=\\"-34\\" width=\\"120\\" height=\\"68\\" rx=\\"8\\" fill=\\"#ffffff\\" stroke=\\"#bbf7d0\\" stroke-width=\\"1.2\\" stroke-width=\\"1\\" />\\n          <text x=\\"0\\" y=\\"-18\\" fill=\\"#059669\\" font-family=\\"'Plus Jakarta Sans', sans-serif\\" font-size=\\"9\\" font-weight=\\"800\\" text-anchor=\\"middle\\">📡 2 PUBLISHERS</text>\\n          <text x=\\"-50\\" y=\\"-1\\" fill=\\"#334155\\" font-family=\\"'JetBrains Mono', monospace\\" font-size=\\"8\\">• pub_cmd_vel (20Hz)</text>\\n          <text x=\\"-50\\" y=\\"13\\" fill=\\"#334155\\" font-family=\\"'JetBrains Mono', monospace\\" font-size=\\"8\\">• pub_status (1Hz)</text>\\n          <text x=\\"-50\\" y=\\"27\\" fill=\\"#64748b\\" font-family=\\"'JetBrains Mono', monospace\\" font-size=\\"7.5\\">DDS QoS: RELIABLE</text>\\n        </g>\\n\\n        <!-- Logic Arbitration Banner -->\\n        <g transform=\\"translate(0, 76)\\">\\n          <rect x=\\"-135\\" y=\\"-24\\" width=\\"270\\" height=\\"46\\" rx=\\"10\\" fill=\\"#ffffff\\" stroke=\\"#e9d5ff\\" stroke-width=\\"1.2\\" stroke-width=\\"1\\" />\\n          <text x=\\"0\\" y=\\"-10\\" fill=\\"#7e22ce\\" font-family=\\"'Plus Jakarta Sans', sans-serif\\" font-size=\\"9\\" font-weight=\\"800\\" text-anchor=\\"middle\\">🧠 Sensor Fusion &amp; Arbitration</text>\\n          <text x=\\"0\\" y=\\"6\\" fill=\\"#1e293b\\" font-family=\\"'JetBrains Mono', monospace\\" font-size=\\"8\\" font-weight=\\"700\\" text-anchor=\\"middle\\">if clearance &lt; 0.50m: E-STOP else FORWARD</text>\\n        </g>\\n\\n        <!-- Central Oval Ports -->\\n        <!-- Inbound Port Dots (Left Rim) -->\\n        <circle cx=\\"-130\\" cy=\\"-85\\" r=\\"4.5\\" fill=\\"#38bdf8\\" stroke=\\"#ffffff\\" stroke-width=\\"2\\" />\\n        <circle cx=\\"-160\\" cy=\\"0\\" r=\\"4.5\\" fill=\\"#38bdf8\\" stroke=\\"#ffffff\\" stroke-width=\\"2\\" />\\n        <circle cx=\\"-130\\" cy=\\"85\\" r=\\"4.5\\" fill=\\"#c084fc\\" stroke=\\"#ffffff\\" stroke-width=\\"2\\" />\\n\\n        <!-- Outbound Port Dots (Right Rim) -->\\n        <circle cx=\\"130\\" cy=\\"-55\\" r=\\"4.5\\" fill=\\"#34d399\\" stroke=\\"#ffffff\\" stroke-width=\\"2\\" />\\n        <circle cx=\\"130\\" cy=\\"55\\" r=\\"4.5\\" fill=\\"#fbbf24\\" stroke=\\"#ffffff\\" stroke-width=\\"2\\" />\\n      </g>\\n\\n\\n      <!-- --- RIGHT COLUMN OVAL NODES (DOWNSTREAM SUBSCRIBERS) --- -->\\n\\n      <!-- Node 4: motor_controller (Oval) -->\\n      <g transform=\\"translate(1050, 155)\\" class=\\"node-oval-group\\">\\n        <rect x=\\"-95\\" y=\\"-26\\" width=\\"190\\" height=\\"52\\" rx=\\"26\\" fill=\\"url(#nodePillGrad)\\" stroke=\\"#10b981\\" stroke-width=\\"2\\" />\\n        <!-- In Port Dot -->\\n        <circle cx=\\"-95\\" cy=\\"0\\" r=\\"4.5\\" fill=\\"#34d399\\" stroke=\\"#ffffff\\" stroke-width=\\"1.5\\" />\\n        <circle cx=\\"-70\\" cy=\\"-5\\" r=\\"4\\" fill=\\"#10b981\\" />\\n        <text x=\\"-58\\" y=\\"-2\\" fill=\\"#34d399\\" font-family=\\"'JetBrains Mono', monospace\\" font-size=\\"8.5\\" font-weight=\\"700\\">NODE</text>\\n        <text x=\\"16\\" y=\\"-2\\" fill=\\"#0f172a\\" font-family=\\"'JetBrains Mono', monospace\\" font-size=\\"10.5\\" font-weight=\\"800\\" text-anchor=\\"middle\\">/motor_controller</text>\\n        <text x=\\"0\\" y=\\"13\\" fill=\\"#10b981\\" font-family=\\"'Plus Jakarta Sans', sans-serif\\" font-size=\\"9\\" font-weight=\\"600\\" text-anchor=\\"middle\\">Subscriber (Hardware)</text>\\n      </g>\\n\\n      <!-- Node 5: rviz2_dashboard (Oval) -->\\n      <g transform=\\"translate(1050, 375)\\" class=\\"node-oval-group\\">\\n        <rect x=\\"-95\\" y=\\"-34\\" width=\\"190\\" height=\\"68\\" rx=\\"34\\" fill=\\"url(#nodePillGrad)\\" stroke=\\"#f59e0b\\" stroke-width=\\"2\\" />\\n        <!-- In Port Dots (2 subscribers clearly displayed!) -->\\n        <circle cx=\\"-95\\" cy=\\"-20\\" r=\\"4.5\\" fill=\\"#fbbf24\\" stroke=\\"#ffffff\\" stroke-width=\\"1.5\\" />\\n        <circle cx=\\"-95\\" cy=\\"20\\" r=\\"4.5\\" fill=\\"#38bdf8\\" stroke=\\"#ffffff\\" stroke-width=\\"1.5\\" />\\n        \\n        <circle cx=\\"-70\\" cy=\\"-14\\" r=\\"4\\" fill=\\"#f59e0b\\" />\\n        <text x=\\"-58\\" y=\\"-11\\" fill=\\"#fbbf24\\" font-family=\\"'JetBrains Mono', monospace\\" font-size=\\"8.5\\" font-weight=\\"700\\">NODE</text>\\n        <text x=\\"16\\" y=\\"-11\\" fill=\\"#0f172a\\" font-family=\\"'JetBrains Mono', monospace\\" font-size=\\"10.5\\" font-weight=\\"800\\" text-anchor=\\"middle\\">/rviz2_dashboard</text>\\n        \\n        <!-- Two distinct subscriptions inside RViz2 -->\\n        <text x=\\"0\\" y=\\"7\\" fill=\\"#fde68a\\" font-family=\\"'JetBrains Mono', monospace\\" font-size=\\"8.5\\" text-anchor=\\"middle\\">• sub /diagnostics</text>\\n        <text x=\\"0\\" y=\\"21\\" fill=\\"#7dd3fc\\" font-family=\\"'JetBrains Mono', monospace\\" font-size=\\"8.5\\" font-weight=\\"700\\" text-anchor=\\"middle\\">• sub /odom (Branch 2)</text>\\n      </g>\\n\\n      <!-- Bottom Legend -->\\n      <g transform=\\"translate(600, 585)\\">\\n        <rect x=\\"-380\\" y=\\"-12\\" width=\\"760\\" height=\\"24\\" rx=\\"12\\" fill=\\"#ffffff\\" stroke=\\"#cbd5e1\\" stroke-width=\\"1.2\\" />\\n        <text x=\\"0\\" y=\\"3.5\\" fill=\\"#475569\\" font-family=\\"'Plus Jakarta Sans', sans-serif\\" font-size=\\"10\\" font-weight=\\"600\\" text-anchor=\\"middle\\">\\n          <tspan fill=\\"#a855f7\\" font-weight=\\"700\\">⬭ Oval</tspan> = Node  ·  \\n          <tspan fill=\\"#38bdf8\\" font-weight=\\"700\\">⚡ Split Dot</tspan> = 1-to-Many Topic Fork (/odom ➔ 2 Subscribers)  ·  \\n          <tspan fill=\\"#0284c7\\" font-weight=\\"700\\">Text</tspan> = Named Topic  ·  \\n          <tspan fill=\\"#c084fc\\" font-weight=\\"700\\">Center</tspan> = Node with 3 Subs + 2 Pubs\\n        </text>\\n      </g>\\n    </svg>\\n  </div>\\n\\n  <!-- 3 Architectural Patterns Grid -->\\n  <div class=\\"infographic-patterns-grid\\">\\n    <div class=\\"infographic-pattern-card\\">\\n      <div class=\\"pattern-card-header\\">\\n        <span>🔀 Sensor Fusion (M ➔ 1)</span>\\n      </div>\\n      <p class=\\"pattern-card-desc\\">\\n        A single oval node consumes multiple raw sensor topics (LiDAR, ultrasonic, odometry) simultaneously to compute unified state estimations or obstacle costmaps.\\n      </p>\\n    </div>\\n\\n    <div class=\\"infographic-pattern-card\\">\\n      <div class=\\"pattern-card-header\\">\\n        <span>🛡️ Command Relay &amp; Safety Filter</span>\\n      </div>\\n      <p class=\\"pattern-card-desc\\">\\n        Acts as an active supervisor: receives high-level commands, verifies proximity clearances against safety margins, and outputs hardware-safe wheel velocities.\\n      </p>\\n    </div>\\n\\n    <div class=\\"infographic-pattern-card\\">\\n      <div class=\\"pattern-card-header\\">\\n        <span>🌐 Decoupled M:N Topology</span>\\n      </div>\\n      <p class=\\"pattern-card-desc\\">\\n        Notice <code>/odom</code>: published once by <code>/wheel_odom_node</code>, but splits via DDS Multicast into <strong>two distinct subscriber paths</strong> to feed <strong>both</strong> <code>/amr_safety_supervisor_node</code> and <code>/rviz2_dashboard</code> simultaneously!\\n      </p>\\n    </div>\\n  </div>\\n</div>\\n\\n\\n<div class=\\"alert alert-info alert-briefing\\">\\n  <div class=\\"alert-icon\\">🔀</div>\\n  <div class=\\"alert-content\\">\\n    <div class=\\"alert-title\\">Robotics Flight Operations Mission Briefing: Central Safety Supervisor (Multi-Topic Architecture)</div>\\n    <div class=\\"alert-body\\">\\n      <strong>Physical AMR Context &amp; Operational Challenge:</strong><br>\\n      In commercial AMRs, a single master safety node acts as the central brain. It does not exist in isolation: it must fuse sensor streams from ultrasonic rangers, wheel odometry encoders, and manual operator joystick commands, and concurrently broadcast safe velocity commands to motors and status diagnostics to fleet dashboards.\\n      <br><br>\\n      <strong>Architectural Role &amp; Why This Mechanism:</strong><br>\\n      Rather than launching separate processes for every communication pipe, a single ROS 2 Node can host multiple publishers and subscribers simultaneously. The <code>rclpy.node.Node</code> base class manages internal subscription queues and publisher endpoints concurrently within a single event loop.\\n      <br><br>\\n      <strong>Flight Objective &amp; Behavioral Outcome:</strong><br>\\n      Examine how a production-grade safety node subscribes to 3 distinct inputs (<code>/sensor/ultrasonic_front</code>, <code>/odom</code>, <code>/teleop_cmd</code>) and drives 2 outputs (<code>/cmd_vel</code>, <code>/diagnostics/safety_status</code>) at 20 Hz.\\n    </div>\\n  </div>\\n</div>\\n\\n<p>Here is how a production multi-publisher, multi-subscriber node is authored cleanly in Python:</p>\\n\\n<div class=\\"code-container\\" data-language=\\"python\\">\\n  <div class=\\"code-header\\"><span class=\\"code-lang-tag\\">python</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n  <pre><code class=\\"language-python\\">import rclpy\\nfrom rclpy.node import Node\\nfrom sensor_msgs.msg import Range\\nfrom std_msgs.msg import String\\nfrom geometry_msgs.msg import Twist\\nfrom nav_msgs.msg import Odometry\\n\\nclass MultiTopicSafetySupervisor(Node):\\n    \\"\\"\\"Single node orchestrating 3 subscribers and 2 publishers.\\"\\"\\"\\n\\n    def __init__(self):\\n        super().__init__('amr_safety_supervisor_node')\\n\\n        # -------------------------------------------------------------\\n        # 1. Multiple Subscribers (Inputs to this node)\\n        # -------------------------------------------------------------\\n        self.sub_range = self.create_subscription(\\n            Range, '/sensor/ultrasonic_front', self.range_callback, 10\\n        )\\n        self.sub_odom = self.create_subscription(\\n            Odometry, '/odom', self.odom_callback, 10\\n        )\\n        self.sub_teleop = self.create_subscription(\\n            Twist, '/teleop_cmd', self.teleop_callback, 10\\n        )\\n\\n        # -------------------------------------------------------------\\n        # 2. Multiple Publishers (Outputs from this node)\\n        # -------------------------------------------------------------\\n        self.pub_cmd_vel = self.create_publisher(\\n            Twist, '/cmd_vel', 10\\n        )\\n        self.pub_status = self.create_publisher(\\n            String, '/diagnostics/safety_status', 10\\n        )\\n\\n        # Internal state & control loop timer\\n        self.front_clearance = 2.0  # meters\\n        self.latest_teleop = Twist()\\n        self.timer = self.create_timer(0.05, self.control_loop)  # 20 Hz (50 ms)\\n        self.get_logger().info('Multi-PubSub Supervisor active: 3 subs, 2 pubs.')\\n\\n    def range_callback(self, msg: Range):\\n        self.front_clearance = msg.range\\n\\n    def odom_callback(self, msg: Odometry):\\n        # Read current linear speed from wheel odometry\\n        current_linear_v = msg.twist.twist.linear.x\\n\\n    def teleop_callback(self, msg: Twist):\\n        self.latest_teleop = msg\\n\\n    def control_loop(self):\\n        cmd = Twist()\\n        status = String()\\n\\n        if self.front_clearance < 0.50:\\n            # Obstacle within 0.50m! Enforce emergency braking\\n            cmd.linear.x = 0.0\\n            cmd.angular.z = 0.0\\n            status.data = f'EMERGENCY_STOP: Obstacle detected at {self.front_clearance:.2f}m!'\\n        else:\\n            # Safe distance: forward operator commands\\n            cmd = self.latest_teleop\\n            status.data = f'CRUISING_SAFE: Front clearance {self.front_clearance:.2f}m.'\\n\\n        self.pub_cmd_vel.publish(cmd)\\n        self.pub_status.publish(status)\\n</code></pre>\\n</div>\\n\\n<div class=\\"code-breakdown-card\\">\\n  <h4 class=\\"code-breakdown-title\\">🔬 Core Code Deep Dive &amp; Operational Breakdown: MultiTopicSafetySupervisor Architecture</h4>\\n  <p class=\\"code-breakdown-intro\\">Key mechanics of single-node multi-topic orchestration:</p>\\n  <ul class=\\"code-breakdown-list\\">\\n    <li class=\\"code-breakdown-item\\"><strong>Multi-Channel Registration:</strong> The node instantiates 3 subscriptions and 2 publishers within a single <code>__init__</code> constructor, all tied to the same DDS participant entity.</li>\\n    <li class=\\"code-breakdown-item\\"><strong>Asynchronous State Aggregation:</strong> Callbacks update shared internal member variables (<code>self.front_clearance</code>, <code>self.latest_teleop</code>). The separate <code>control_loop</code> timer periodically reads these variables at 20 Hz, decoupling input arrival rates from actuation frequency.</li>\\n    <li class=\\"code-breakdown-item\\"><strong>Deterministic Sensor Fusion & Actuation:</strong> The 20 Hz control loop prioritizes safety over user commands: if <code>front_clearance < 0.50m</code>, it zeros out velocity regardless of what teleoperation requests, enforcing hardware-level protection.</li>\\n  </ul>\\n</div>\\n\\n\\n<div class=\\"alert alert-tip\\">\\n  <div class=\\"alert-icon\\">💡</div>\\n  <div class=\\"alert-content\\">\\n    <strong>CLI Introspection Pro-Tip:</strong>\\n    To inspect all publishers, subscribers, service servers, and action servers running on any active node at runtime, execute:\\n    <div style=\\"margin-top: 6px;\\"><code class=\\"inline-code\\">ros2 node info /amr_safety_supervisor_node</code></div>\\n    The ROS 2 runtime will print the complete communication manifest for that node.\\n  </div>\\n</div>\\n</section>\\n\\n<section class=\\"lesson-section\\">\\n<hr class=\\"divider\\">\\n<h2 id=\\"8-hands-on-student-challenge\\">8. Hands-on Student Challenge: Autonomous Mobile Robot Square Patrol Controller</h2>\\n<p>Write an object-oriented Python publisher node (<code class=\\"inline-code\\">square_turtle</code>) that commands a mobile robot to drive in a continuous 2x2 meter square patrol path via <code class=\\"inline-code\\">/cmd_vel</code>.</p>\\n\\n<div class=\\"alert alert-tip\\">\\n  <div class=\\"alert-title\\">🎯 Mission Requirements</div>\\n  <ol>\\n    <li><strong>TODO 1:</strong> Create a velocity publisher for <code class=\\"inline-code\\">geometry_msgs/msg/Twist</code> on topic <code class=\\"inline-code\\">/turtle1/cmd_vel</code>.</li>\\n    <li><strong>TODO 2:</strong> Implement a state machine with two modes: <code class=\\"inline-code\\">STATE_FORWARD</code> (drive straight at 2.0 m/s for 2.0s) and <code class=\\"inline-code\\">STATE_TURN</code> (rotate 90° CCW at 1.57 rad/s for 1.0s).</li>\\n    <li><strong>TODO 3:</strong> Transition smoothly between forward and turn states, logging each corner.</li>\\n    <li><strong>TODO 4:</strong> Publish zero velocity emergency stop in <code class=\\"inline-code\\">finally</code> block upon <code class=\\"inline-code\\">KeyboardInterrupt</code>.</li>\\n  </ol>\\n</div>\\n\\n\\n<div class=\\"alert alert-info alert-briefing\\">\\n  <div class=\\"alert-icon\\">🔄</div>\\n  <div class=\\"alert-content\\">\\n    <div class=\\"alert-title\\">Robotics Flight Operations Mission Briefing: Autonomous Mobile Robot Square Patrol Controller</div>\\n    <div class=\\"alert-body\\">\\n      <strong>Physical AMR Context &amp; Operational Challenge:</strong><br>\\n      Warehouse inspection AMRs must traverse repeatable geometric patrol paths around inventory storage stacks to scan barcode labels or conduct RFID inventory audits. When GPS is unavailable indoors, dead-reckoning velocity commands drive the vehicle along straight legs and corner turns.\\n      <br><br>\\n      <strong>Architectural Role &amp; Why This Mechanism:</strong><br>\\n      To drive a mobile robot, software must publish <code>geometry_msgs/msg/Twist</code> packets over the standard <code>/cmd_vel</code> (or <code>/turtle1/cmd_vel</code>) topic at a steady control rate (10 Hz). A state machine coordinates linear translation (forward motion) and angular yaw rotation (corner pivot).\\n      <br><br>\\n      <strong>Flight Objective &amp; Behavioral Outcome:</strong><br>\\n      Implement a finite state machine in Python with two distinct flight phases: <code>STATE_FORWARD</code> (2.0 m/s for 2.0s) and <code>STATE_TURN</code> (1.57 rad/s for 1.0s). Transition between states to complete a square trajectory, and ensure a zero-velocity halt is published upon node termination.\\n    </div>\\n  </div>\\n</div>\\n\\n<h3 id=\\"81-starter-template\\">8.1 Starter Template: <code class=\\"inline-code\\">m01_l05_06_task_turtle_square.py</code></h3>\\n<p>Copy the starter template from the reference workspace into your active student workspace:</p>\\n<div class=\\"code-container\\" data-language=\\"bash\\">\\n  <div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n  <pre><code class=\\"language-bash\\">cp ~/ros2_ws_reference/src/nexus_amr_basics/nexus_amr_basics/m01_l05_06_task_turtle_square.py ~/ros2_ws/src/nexus_amr_basics/nexus_amr_basics/</code></pre>\\n</div>\\n<p>Open the copied file in your editor and complete the marked <code class=\\"inline-code\\">TODO</code> targets:</p>\\n\\n<div class=\\"code-container\\" data-language=\\"python\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">python</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-python\\">#!/usr/bin/env python3\\n&quot;&quot;&quot;\\n================================================================================\\nNexus AMR Learning Hub - Level 1: Module 1 / Lesson 05 Student Task\\nPackage: nexus_amr_basics\\nNode:    m01_l05_06_task_turtle_square.py (alias: task_turtle_square)\\n================================================================================\\n\\nMISSION OVERVIEW:\\n-----------------\\nIn this hands-on challenge, you will implement an autonomous motion controller\\nfor Turtlesim that commands the turtle to drive in a continuous, repeatable SQUARE!\\n\\nBecause you already understand ROS 2 interface types (specifically \`geometry_msgs/msg/Twist\`),\\nyou will publish velocity setpoints to \`/turtle1/cmd_vel\` at 10 Hz.\\n\\nGEOMETRY &amp; KINEMATICS FOR A SQUARE:\\n-----------------------------------\\nA square consists of 4 straight edges and 4 ninety-degree turns:\\n1. DRIVE STRAIGHT:\\n   - linear.x = 2.0 m/s\\n   - angular.z = 0.0 rad/s\\n   - Duration = 2.0 seconds (distance traveled = 4.0 meters)\\n2. TURN 90 DEGREES LEFT:\\n   - linear.x = 0.0 m/s\\n   - angular.z = 1.5708 rad/s (π / 2 radians ≈ 90° per second)\\n   - Duration = 1.0 second (angle turned = 90°)\\n3. Repeat continuously across all 4 sides!\\n\\nYOUR TASKS (LOOK FOR THE TODO TAGS):\\n------------------------------------\\n- TODO 1: Initialize the publisher on topic \`/turtle1/cmd_vel\` with type \`Twist\`.\\n- TODO 2: Create a periodic 10 Hz timer (period = 0.1s) calling \`self.timer_callback\`.\\n- TODO 3: Implement the two-state motion logic in \`timer_callback\`.\\n- TODO 4: Publish the constructed \`Twist\` message to \`/turtle1/cmd_vel\`.\\n================================================================================\\n&quot;&quot;&quot;\\n\\nimport rclpy\\nfrom rclpy.node import Node\\nfrom geometry_msgs.msg import Twist\\n\\n\\nclass TurtleSquareController(Node):\\n    &quot;&quot;&quot;\\n    Student Task Node: Commands Turtlesim in an autonomous square path.\\n    &quot;&quot;&quot;\\n\\n    # State Machine Constants\\n    STATE_FORWARD = 0\\n    STATE_TURN = 1\\n\\n    def __init__(self):\\n        super().__init__(&#x27;turtle_square_controller&#x27;)\\n        self.get_logger().info(&#x27;Initializing TurtleSquareController...&#x27;)\\n\\n        # ----------------------------------------------------------------------\\n        # TODO 1: Initialize the Velocity Command Publisher\\n        #\\n        # Algorithmic Goal:\\n        #   Register a publisher endpoint on the robot motion topic so this node\\n        #   can stream velocity setpoints to Turtlesim.\\n        #\\n        # Specifications &amp; Hints:\\n        #   - Message Type: Twist (from geometry_msgs.msg)\\n        #   - Topic Name: &#x27;/turtle1/cmd_vel&#x27;\\n        #   - QoS Queue Depth: 10 (ROS 2 Default QoS Profile)\\n        # ----------------------------------------------------------------------\\n        # &gt;&gt;&gt; TODO: Assign self.cmd_vel_pub using create_publisher &lt;&lt;&lt;\\n        self.cmd_vel_pub = None\\n\\n        # Controller Timing &amp; State tracking\\n        self.state = self.STATE_FORWARD\\n        self.state_elapsed_time = 0.0\\n\\n        # Duration parameters (in seconds)\\n        self.forward_duration = 2.0  # seconds to drive forward\\n        self.turn_duration = 1.0     # seconds to turn 90 degrees\\n\\n        # Velocities\\n        self.linear_speed = 2.0      # m/s forward speed\\n        self.angular_speed = 1.5708  # rad/s (pi / 2 = 90 deg/sec)\\n\\n        # ----------------------------------------------------------------------\\n        # TODO 2: Create a periodic 10 Hz timer (dt = 0.1s)\\n        #\\n        # Algorithmic Goal:\\n        #   Periodic execution is essential for real-time robotic state machines.\\n        #   Register an asynchronous timer that invokes the control loop callback\\n        #   every 100 milliseconds without blocking the executor thread.\\n        #\\n        # Specifications &amp; Hints:\\n        #   - Period: self.timer_period (0.100 seconds)\\n        #   - Callback: self.timer_callback\\n        # ----------------------------------------------------------------------\\n        self.timer_period = 0.1  # seconds (10 Hz)\\n        # &gt;&gt;&gt; TODO: Assign self.timer using create_timer &lt;&lt;&lt;\\n        self.timer = None\\n\\n        self.get_logger().info(&#x27;TurtleSquareController initialized. Waiting for student implementation...&#x27;)\\n\\n    def timer_callback(self):\\n        &quot;&quot;&quot;\\n        Executed every 0.1 seconds (10 Hz).\\n        Updates state elapsed time, transitions state when duration is met,\\n        and publishes the corresponding velocity command to /turtle1/cmd_vel.\\n        &quot;&quot;&quot;\\n        # Increment elapsed time in current state\\n        self.state_elapsed_time += self.timer_period\\n\\n        # Instantiate a new empty Twist velocity message\\n        cmd = Twist()\\n\\n        # ----------------------------------------------------------------------\\n        # TODO 3: Implement Two-State Finite State Machine (FSM) Logic\\n        #\\n        # ALGORITHMIC PSEUDOCODE:\\n        #   IF robot is currently in FORWARD state:\\n        #       1. Set forward linear velocity to the configured forward speed setpoint.\\n        #       2. Ensure angular steering velocity is set to zero (straight path).\\n        #       3. Check if accumulated state time has reached the forward duration:\\n        #          - Log that straight edge traversal is complete.\\n        #          - Switch state to the TURN state.\\n        #          - Reset state elapsed time accumulator back to 0.0.\\n        #\\n        #   ELSE IF robot is currently in TURN state:\\n        #       1. Ensure linear velocity is zero (in-place pivot).\\n        #       2. Set angular steering velocity to the configured turning speed setpoint.\\n        #       3. Check if accumulated state time has reached the turn duration:\\n        #          - Log that 90-degree turn is complete.\\n        #          - Switch state back to the FORWARD state.\\n        #          - Reset state elapsed time accumulator back to 0.0.\\n        #\\n        # CONCEPTUAL HINTS:\\n        #   - Compare state with: self.STATE_FORWARD and self.STATE_TURN\\n        #   - Update fields on the cmd object: linear.x and angular.z\\n        #   - Check elapsed time against: self.forward_duration and self.turn_duration\\n        #   - Use velocity constants: self.linear_speed and self.angular_speed\\n        #   - Log progress with: self.get_logger().info(...)\\n        # ----------------------------------------------------------------------\\n        # &gt;&gt;&gt; TODO: WRITE YOUR STATE MACHINE CODE HERE &lt;&lt;&lt;\\n\\n\\n        # ----------------------------------------------------------------------\\n        # TODO 4: Publish the velocity command\\n        #\\n        # ALGORITHMIC PSEUDOCODE:\\n        #   Verify that the publisher endpoint is initialized.\\n        #   If valid, publish the configured cmd message over DDS.\\n        #\\n        # HINT:\\n        #   Invoke the publish method on your publisher endpoint passing cmd.\\n        # ----------------------------------------------------------------------\\n        # &gt;&gt;&gt; TODO: PUBLISH cmd HERE &lt;&lt;&lt;\\n\\n\\ndef main(args=None):\\n    rclpy.init(args=args)\\n    node = TurtleSquareController()\\n\\n    try:\\n        rclpy.spin(node)\\n    except KeyboardInterrupt:\\n        node.get_logger().info(&#x27;KeyboardInterrupt received. Stopping turtle safely...&#x27;)\\n    finally:\\n        # Publish a zero-velocity emergency stop so turtle doesn&#x27;t keep moving\\n        if node.cmd_vel_pub is not None:\\n            stop_msg = Twist()\\n            stop_msg.linear.x = 0.0\\n            stop_msg.angular.z = 0.0\\n            node.cmd_vel_pub.publish(stop_msg)\\n        node.destroy_node()\\n        rclpy.shutdown()\\n\\n\\nif __name__ == &#x27;__main__&#x27;:\\n    main()\\n</code></pre>\\n</div>\\n\\n<h3 id=\\"82-verification-steps--expected-terminal-output\\">8.2 Verification Steps &amp; Expected Terminal Output</h3>\\n<p>Follow these steps to copy the starter template, register the executable in your package, compile, and execute:</p>\\n\\n<ol class=\\"step-guide-list\\">\\n  <li><strong>Step 1: Copy Starter Template to Your Package:</strong>\\n    <div class=\\"code-container\\" data-language=\\"bash\\">\\n      <div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n      <pre><code class=\\"language-bash\\">cp ~/ros2_ws_reference/src/nexus_amr_basics/nexus_amr_basics/m01_l05_06_task_turtle_square.py ~/ros2_ws/src/nexus_amr_basics/nexus_amr_basics/</code></pre>\\n    </div>\\n  </li>\\n  <li><strong>Step 2: Register in setup.py:</strong>\\n    <p>Open <code class=\\"inline-code\\">~/ros2_ws/src/nexus_amr_basics/setup.py</code> and add the entrypoint inside <code class=\\"inline-code\\">'console_scripts'</code>:</p>\\n    <div class=\\"code-container\\" data-language=\\"python\\">\\n      <div class=\\"code-header\\"><span class=\\"code-lang-tag\\">python</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n      <pre><code class=\\"language-python\\">            'square_turtle = nexus_amr_basics.m01_l05_06_task_turtle_square:main',</code></pre>\\n    </div>\\n  </li>\\n  <li><strong>Step 3: Compile with Symlink Install &amp; Source:</strong>\\n    <div class=\\"code-container\\" data-language=\\"bash\\">\\n      <div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n      <pre><code class=\\"language-bash\\">cd ~/ros2_ws\\ncolcon build --symlink-install --packages-select nexus_amr_basics\\nsource install/setup.bash</code></pre>\\n    </div>\\n  </li>\\n  <li><strong>Step 4: Launch Simulation &amp; Test Square Patrol in Dedicated Terminals:</strong>\\n    <p>Launch each process in its own dedicated terminal tab:</p>\\n    \\n    <div class=\\"code-container\\" data-language=\\"bash\\">\\n      <div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash (Terminal 1 - Simulator)</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n      <pre><code class=\\"language-bash\\">ros2 run turtlesim turtlesim_node</code></pre>\\n    </div>\\n\\n    <div class=\\"code-container\\" data-language=\\"bash\\">\\n      <div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash (Terminal 2 - Square Patrol Controller)</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n      <pre><code class=\\"language-bash\\">source ~/ros2_ws/install/setup.bash\\nros2 run nexus_amr_basics square_turtle</code></pre>\\n    </div>\\n\\n    <div class=\\"code-container\\" data-language=\\"bash\\">\\n      <div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash (Terminal 3 - Velocity Introspection)</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n      <pre><code class=\\"language-bash\\"># Monitor velocity telemetry streaming from controller (Press Ctrl+C to stop):\\nros2 topic echo /turtle1/cmd_vel</code></pre>\\n    </div>\\n  </li>\\n</ol>\\n  </li>\\n</ol>\\n\\n<p><em>Expected Terminal Output:</em></p>\\n<div class=\\"code-container\\" data-language=\\"text\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">text</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-text\\">[INFO] [turtle_square_controller]: Initializing TurtleSquareController...\\n[INFO] [turtle_square_controller]: State FORWARD: driving edge #1...\\n[INFO] [turtle_square_controller]: State TURN: rotating 90 degrees left...\\n[INFO] [turtle_square_controller]: State FORWARD: driving edge #2...</code></pre>\\n</div>\\n\\n<details class=\\"reference-solution-dropdown\\">\\n  <summary class=\\"solution-summary-btn\\">\\n    <span>🔍 View Reference Solution (<code class=\\"inline-code\\">m01_l05_07_solution_turtle_square.py</code>)</span>\\n  </summary>\\n  <div class=\\"solution-body\\">\\n    <p>Reference file: <code class=\\"inline-code\\">ros2_ws_reference/src/nexus_amr_basics/nexus_amr_basics/m01_l05_07_solution_turtle_square.py</code></p>\\n    <div class=\\"code-container\\" data-language=\\"python\\">\\n      <div class=\\"code-header\\"><span class=\\"code-lang-tag\\">python</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n      <pre><code class=\\"language-python\\">#!/usr/bin/env python3\\n&quot;&quot;&quot;\\n================================================================================\\nNexus AMR Learning Hub - Level 1: Module 1 / Lesson 05 Reference Solution\\nPackage: nexus_amr_basics\\nNode:    m01_l05_07_solution_turtle_square.py (alias: square_turtle, solution_turtle_square)\\n================================================================================\\n\\nMISSION OVERVIEW:\\n-----------------\\nReference solution for the Lesson 05 hands-on student challenge:\\nCommands Turtlesim to drive in a continuous, autonomous square patrol path.\\n\\nTopics Used:\\n- Output: \`/turtle1/cmd_vel\` (\`geometry_msgs/msg/Twist\`) at 10 Hz\\n\\nKinematic Sequence:\\n- Leg 1: Drive Straight (linear.x = 2.0 m/s) for 2.0s\\n- Turn 1: 90° CCW Turn (angular.z = 1.5708 rad/s) for 1.0s\\n- Leg 2, Turn 2, Leg 3, Turn 3, Leg 4, Turn 4 -&gt; Loops indefinitely\\n================================================================================\\n&quot;&quot;&quot;\\n\\nimport rclpy\\nfrom rclpy.node import Node\\nfrom geometry_msgs.msg import Twist\\n\\n\\nclass TurtleSquareController(Node):\\n    &quot;&quot;&quot;\\n    Autonomous Square Motion Controller for Turtlesim.\\n    &quot;&quot;&quot;\\n\\n    STATE_FORWARD = 0\\n    STATE_TURN = 1\\n\\n    def __init__(self):\\n        super().__init__(&#x27;turtle_square_controller&#x27;)\\n        self.get_logger().info(&#x27;Initializing TurtleSquareController...&#x27;)\\n\\n        # 1. Create Publisher for velocity commands\\n        self.cmd_vel_pub = self.create_publisher(Twist, &#x27;/turtle1/cmd_vel&#x27;, 10)\\n\\n        # 2. Controller State &amp; Timing Parameters\\n        self.state = self.STATE_FORWARD\\n        self.state_elapsed_time = 0.0\\n\\n        # Motion Durations (seconds)\\n        self.forward_duration = 2.0  # Drive forward for 2.0s\\n        self.turn_duration = 1.0     # Turn 90° for 1.0s\\n\\n        # Velocities\\n        self.linear_speed = 2.0      # 2.0 m/s\\n        self.angular_speed = 1.5708  # pi / 2 rad/s = 90 deg/sec\\n\\n        # 3. Create 10 Hz Control Loop Timer\\n        self.timer_period = 0.1      # 100 ms (10 Hz)\\n        self.timer = self.create_timer(self.timer_period, self.timer_callback)\\n\\n        self.side_count = 0\\n        self.get_logger().info(&#x27;TurtleSquareController running! Driving side 1 of square...&#x27;)\\n\\n    def timer_callback(self):\\n        &quot;&quot;&quot;\\n        10 Hz control loop: updates timer, executes state machine transitions,\\n        and publishes Twist velocity commands.\\n        &quot;&quot;&quot;\\n        self.state_elapsed_time += self.timer_period\\n        cmd = Twist()\\n\\n        if self.state == self.STATE_FORWARD:\\n            # Drive straight\\n            cmd.linear.x = self.linear_speed\\n            cmd.angular.z = 0.0\\n\\n            if self.state_elapsed_time &gt;= self.forward_duration:\\n                self.side_count += 1\\n                self.get_logger().info(f&#x27;Side {self.side_count} complete. Initiating 90° left turn...&#x27;)\\n                self.state = self.STATE_TURN\\n                self.state_elapsed_time = 0.0\\n\\n        elif self.state == self.STATE_TURN:\\n            # Turn 90 degrees CCW\\n            cmd.linear.x = 0.0\\n            cmd.angular.z = self.angular_speed\\n\\n            if self.state_elapsed_time &gt;= self.turn_duration:\\n                self.get_logger().info(&#x27;Turn complete. Resuming straight drive...&#x27;)\\n                self.state = self.STATE_FORWARD\\n                self.state_elapsed_time = 0.0\\n\\n        # Publish the computed velocity to Turtlesim\\n        self.cmd_vel_pub.publish(cmd)\\n\\n\\ndef main(args=None):\\n    rclpy.init(args=args)\\n    node = TurtleSquareController()\\n\\n    try:\\n        rclpy.spin(node)\\n    except KeyboardInterrupt:\\n        node.get_logger().info(&#x27;Stopping turtle controller (Ctrl+C received)...&#x27;)\\n    finally:\\n        # Emergency stop: publish zero velocity command so the turtle halts\\n        stop_cmd = Twist()\\n        stop_cmd.linear.x = 0.0\\n        stop_cmd.angular.z = 0.0\\n        node.cmd_vel_pub.publish(stop_cmd)\\n        node.get_logger().info(&#x27;Zero-velocity halt published. Shutting down node.&#x27;)\\n        node.destroy_node()\\n        rclpy.shutdown()\\n\\n\\nif __name__ == &#x27;__main__&#x27;:\\n    main()</code></pre>\\n    </div>\\n  </div>\\n</details>\\n\\n<div class=\\"code-breakdown-card\\">\\n  <h4 class=\\"code-breakdown-title\\">🔬 Core Code Deep Dive &amp; Operational Breakdown: TurtleSquareController Solution Breakdown</h4>\\n  <p class=\\"code-breakdown-intro\\">Key kinematic and state machine mechanics of the Square Patrol Controller:</p>\\n  <ul class=\\"code-breakdown-list\\">\\n    <li class=\\"code-breakdown-item\\"><strong>Explicit State Machine:</strong> <code>STATE_FORWARD = 0</code> and <code>STATE_TURN = 1</code> cleanly partition the robot's kinematics. The control loop increments <code>state_elapsed_time</code> on each 100ms tick to govern phase transitions.</li>\\n    <li class=\\"code-breakdown-item\\"><strong>Twist Kinematic Velocity Synthesis:</strong> During forward flight, <code>cmd.linear.x = 2.0</code> drives the robot straight. During corner pivots, <code>cmd.linear.x = 0.0; cmd.angular.z = 1.5708</code> rotates the robot 90 degrees CCW over exactly 1.0 second.</li>\\n    <li class=\\"code-breakdown-item\\"><strong>Fail-Safe Shutdown Invariant:</strong> In <code>finally:</code>, the node constructs and publishes a zero-velocity <code>Twist()</code> command before destroying the node. In physical robotics, this prevents residual actuator inertia from driving the robot into walls.</li>\\n  </ul>\\n</div>\\n\\n<div class=\\"asset-handoff-card\\" style=\\"margin: 1.75rem 0 1rem 0; padding: 1.15rem 1.4rem; border-radius: 10px; background: rgba(16, 185, 129, 0.06); border: 1px solid rgba(16, 185, 129, 0.25); border-left: 4px solid #10b981;\\">\\n  <div style=\\"display: flex; align-items: center; gap: 0.5rem; margin-bottom: 0.5rem;\\">\\n    <span style=\\"font-size: 1.1rem;\\">📦</span>\\n    <strong style=\\"font-size: 0.95rem; color: #10b981; text-transform: uppercase; letter-spacing: 0.04em;\\">Asset Handoff &amp; Next Lesson Pipeline Bridge</strong>\\n  </div>\\n  <p style=\\"margin: 0 0 0.65rem 0; font-size: 0.88rem; color: var(--text-primary); line-height: 1.6;\\">\\n    You have developed and verified asynchronous publisher and subscriber nodes, streaming synthetic ultrasonic range telemetry and driving interactive robotic teleoperation in Turtlesim.\\n  </p>\\n  <div style=\\"display: flex; flex-wrap: wrap; gap: 0.75rem; font-size: 0.82rem; font-family: var(--font-mono);\\">\\n    <span style=\\"background: var(--bg-surface); border: 1px solid var(--border-color); padding: 0.25rem 0.6rem; border-radius: 5px; color: var(--text-primary);\\">\\n      📁 <strong>Produced Artifact:</strong> <code>nexus_amr_basics/ultrasonic_publisher.py</code> &amp; <code>nexus_amr_basics/square_turtle.py</code>\\n    </span>\\n    <span style=\\"background: var(--bg-surface); border: 1px solid var(--border-color); padding: 0.25rem 0.6rem; border-radius: 5px; color: var(--text-primary);\\">\\n      ➡️ <strong>Ingested By:</strong> Lesson 06 (Communication Mechanism II: Service Servers &amp; Clients in Python)\\n    </span>\\n  </div>\\n</div>\\n","quizzes":[{"id":"q_l1_05_1","prompt":"What happens if a publisher offers BEST_EFFORT reliability on a topic, but a subscriber requests RELIABLE?","options":["DDS automatically converts BEST_EFFORT packets into reliable packets","DDS rejects the connection and NO data is delivered (silent failure)","The subscriber crashes with a segmentation fault","The ROS 2 executor forces the publisher to restart"],"correct":1,"explanation":"Under DDS QoS compatibility rules, a subscriber cannot request stricter QoS guarantees than a publisher provides (Rx <= Tx). A RELIABLE subscriber connecting to a BEST_EFFORT publisher results in a silent connection rejection."},{"id":"q_l1_05_2","prompt":"Why is the --symlink-install flag critical when developing Python ROS 2 packages with colcon?","options":["It compiles Python byte-code into binary machine code","It symlinks source files from src/ to install/, allowing instant Python code editing without rebuilding","It reduces RAM consumption of DDS participants","It automatically formats Python scripts with Black and Flake8"],"correct":1,"explanation":"--symlink-install creates direct symbolic links to your Python source scripts in src/, enabling rapid prototyping without running colcon build after every edit."},{"id":"q_l1_05_3","prompt":"Which ROS 2 CLI command allows you to monitor the live publishing rate and frequency statistics of a topic?","options":["ros2 topic hz <topic_name>","ros2 topic count <topic_name>","ros2 topic rate <topic_name>","ros2 node ping <topic_name>"],"correct":0,"explanation":"'ros2 topic hz <topic_name>' subscribes to the topic and calculates rolling average frequency, min/max intervals, and standard deviation."},{"id":"q_l1_05_4","prompt":"When commanding mobile robot locomotion (including Turtlesim), which standard ROS 2 message interface is published to /cmd_vel?","options":["sensor_msgs/msg/LaserScan","std_msgs/msg/String","geometry_msgs/msg/Twist","nav_msgs/msg/Odometry"],"correct":2,"explanation":"geometry_msgs/msg/Twist is the universal ROS 2 interface for linear velocity (m/s) and angular velocity (rad/s) ground vehicle control."}],"has_quiz":true,"next_id":"lesson_06","prev_id":"lesson_04","subtopics":[{"id":"1-overview-learning-objectives","title":"1. Overview &amp; Learning Objectives"},{"id":"2-topic-communication-architecture","title":"2. Topic Communication Architecture &amp; DDS"},{"id":"3-writing-the-ultrasonic-sensor-publisher-node","title":"3. Writing the Ultrasonic Sensor Rangefinder Publisher Node"},{"id":"4-configuring-setuppy-building-testing-publisher","title":"4. Configuring setup.py, Building &amp; Testing the Publisher"},{"id":"5-writing-the-subscriber-node","title":"5. Writing the Collision Safety Monitor Subscriber Node"},{"id":"6-dual-node-communication-drill","title":"6. Dual-Node Communication &amp; Verification Drill"},{"id":"7-quality-of-service-qos-deep-dive","title":"7. Quality of Service (QoS) Deep Dive"},{"id":"8-hands-on-student-challenge","title":"8. Hands-on Student Challenge: Autonomous Mobile Robot Square Patrol Controller"}]},{"id":"lesson_06","num":6,"num_str":"06","title":"Communication Mechanism II: Service Servers & Clients in Python","slug":"services-server-client-python","filename":"07_services_server_client_python.md","module":"Day 1: ROS 2 Foundations & Core Middleware","module_id":1,"duration":"45-60 min","focus":"AMR Emergency Stop RPC Service, Asynchronous Safety Clients, and Speed Mode Governor","snapshot":[["Synchronous RPC Pattern","Client sends a request and suspends execution until the server returns a paired response (Request -> Response)."],["When to Use Services","Ideal for discrete operations: mode changes, resetting encoders, or triggering calibrations—never for high-rate data streaming."],["Two-Tier Concurrency","rclpy.spin_until_future_complete() or asynchronous callbacks prevent client deadlocks when waiting for server responses."],["Service Introspection","CLI tools (ros2 service list, type, find, call) allow manual invocation and diagnostic testing of active services."]],"html_content":"<h2 id=\\"1-overview-learning-objectives\\">1. Overview &amp; Learning Objectives</h2>\\n<div class=\\"alert alert-info\\">\\n  <div class=\\"alert-title\\">🔌 Authoritative Hardware Interface Layer</div>\\n  <p>The AMR emergency safety brake and zone speed governor services utilize our robot's dedicated interface definitions (<code class=\\"inline-code\\">TriggerEmergencyStop.srv</code> and <code class=\\"inline-code\\">SetSpeedMode.srv</code>) provided by <code class=\\"inline-code\\">nexus_amr_interfaces</code>. This package is pre-installed in the robot's system underlay (<code class=\\"inline-code\\">/opt/ros/jazzy</code>). In Bonus Lesson 19, you will learn how to design, write, and compile custom IDL packages with CMake from scratch!</p>\\n</div>\\n<p>While Topics handle continuous high-frequency data streams (e.g. sensor feeds), <strong>Services</strong> implement the synchronous or asynchronous <strong>Request-Response</strong> pattern. A client node sends a request to a service server and waits for a response.</p>\\n<p><div class=\\"learning-objectives-card\\">\\n  <div class=\\"learning-objectives-header\\">\\n    <div class=\\"objectives-icon-badge\\">\\n      <span style=\\"font-size: 1.15rem; line-height: 1;\\">🎯</span>\\n    </div>\\n    <div class=\\"objectives-title-group\\">\\n      <h3 class=\\"objectives-main-title\\">Learning Objectives &amp; Core Outcomes</h3>\\n      <span class=\\"objectives-subtitle\\">By the end of this lesson, you will be able to:</span>\\n    </div>\\n    <span class=\\"objectives-count-badge\\">5 CORE OUTCOMES</span>\\n  </div>\\n  <ul class=\\"learning-objectives-list\\">\\n    <li class=\\"learning-objective-item\\">\\n      <span class=\\"objective-num-badge\\">1</span>\\n      <span class=\\"objective-text\\">Understand the Request-Response communication model and when to use Services vs Topics vs Actions.</span>\\n    </li>\\n    <li class=\\"learning-objective-item\\">\\n      <span class=\\"objective-num-badge\\">2</span>\\n      <span class=\\"objective-text\\">Build an object-oriented Python <strong>Service Server</strong> that processes requests and returns structured responses.</span>\\n    </li>\\n    <li class=\\"learning-objective-item\\">\\n      <span class=\\"objective-num-badge\\">3</span>\\n      <span class=\\"objective-text\\">Build an asynchronous Python <strong>Service Client</strong> using <code class=\\"inline-code\\">call_async()</code> and <code class=\\"inline-code\\">Future</code> objects.</span>\\n    </li>\\n    <li class=\\"learning-objective-item\\">\\n      <span class=\\"objective-num-badge\\">4</span>\\n      <span class=\\"objective-text\\">Trigger and test service endpoints directly from the command line using <code class=\\"inline-code\\">ros2 service call</code>.</span>\\n    </li>\\n    <li class=\\"learning-objective-item\\">\\n      <span class=\\"objective-num-badge\\">5</span>\\n      <span class=\\"objective-text\\">Register executable entry points in <code class=\\"inline-code\\">setup.py</code>, build with <code class=\\"inline-code\\">colcon</code>, and execute the verified server-client pair.</span>\\n    </li>\\n  </ul>\\n</div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"2-decision-matrix-topics-vs-services-vs-actions\\">2. Decision Matrix: Topics vs Services vs Actions</h2>\\n<p>Use the interactive service architecture canvas below to explore how two-way Remote Procedure Calls (RPC) function in ROS 2. Trigger an Emergency Stop request, step through the 4-phase transaction lifecycle, and inspect asynchronous <code class=\\"inline-code\\">Future</code> resolution in real time:</p>\\n<div id=\\"service-flow-root\\" style=\\"margin: 1.75rem 0;\\"></div>\\n<div class=\\"table-responsive\\"><table>\\n<thead>\\n<tr>\\n<th>Communication Pattern</th>\\n<th>Data Flow</th>\\n<th>Blocking?</th>\\n<th>Feedback During Execution?</th>\\n<th>Example Robotics Use Case</th>\\n</tr>\\n</thead>\\n<tbody>\\n<tr>\\n<td><strong>Topic</strong></td>\\n<td>Publisher -&gt; Subscriber (Unidirectional, Continuous)</td>\\n<td>No (Asynchronous)</td>\\n<td>No</td>\\n<td>Continuous LiDAR scans (<code class=\\"inline-code\\">/scan</code>), Wheel velocities (<code class=\\"inline-code\\">/cmd_vel</code>)</td>\\n</tr>\\n<tr>\\n<td><strong>Service</strong></td>\\n<td>Client &lt;-&gt; Server (Bidirectional, Request/Response)</td>\\n<td>Optional (Sync or Async)</td>\\n<td>No (Returns only once at completion)</td>\\n<td>Motor calibration, Camera trigger, Mode toggle (<code class=\\"inline-code\\">/set_speed_mode</code>)</td>\\n</tr>\\n<tr>\\n<td><strong>Action</strong></td>\\n<td>Action Client &lt;-&gt; Action Server (Goal -&gt; Feedback -&gt; Result)</td>\\n<td>No (Asynchronous)</td>\\n<td><strong>Yes</strong> (Continuous progress updates)</td>\\n<td>Navigate 10 meters to waypoint, Execute 30-second precision alignment maneuver</td>\\n</tr>\\n</tbody>\\n</table></div>\\n<p><img src=\\"assets/images/ros2_comm_patterns_decision.svg\\" alt=\\"ROS 2 Communication Patterns Decision Architecture (Topics vs Services vs Actions)\\" class=\\"lesson-image\\" loading=\\"lazy\\" /></p>\\n\\n<hr class=\\"divider\\">\\n<h2 id=\\"3-building-the-emergency-stop-safety-service-server\\">3. Building the Emergency Stop Safety Service Server in Python</h2>\\n<p>Unlike continuous topic streaming, critical safety interventions require bidirectional acknowledgment. An Autonomous Mobile Robot must provide a reliable Service that locks drive actuators and responds with an authoritative confirmation receipt.</p>\\n\\n\\n<div class=\\"alert alert-info alert-briefing\\">\\n  <div class=\\"alert-icon\\">🛡️</div>\\n  <div class=\\"alert-content\\">\\n    <div class=\\"alert-title\\">Robotics Flight Operations Mission Briefing: AMR Emergency Safety Brake Service Server</div>\\n    <div class=\\"alert-body\\">\\n      <strong>Physical AMR Context &amp; Operational Challenge:</strong><br>\\n      Imagine an Autonomous Mobile Robot (AMR) transporting a 250 kg pallet down a dynamic warehouse corridor. A worker suddenly steps out from behind a racking pillar into the robot's immediate safety zone. The robot cannot rely on lossy, fire-and-forget UDP telemetry streams over congested industrial Wi-Fi; a mission-critical safety intervention demands deterministic, guaranteed bidirectional acknowledgment.\\n      <br><br>\\n      <strong>Architectural Role &amp; Why This Mechanism:</strong><br>\\n      In industrial robotics standards (such as ISO 3691-4 and ANSI/RIA R15.08), an emergency stop must be verifiable: the requesting supervisor must receive formal cryptographic proof and timestamped confirmation that motor power is cut and electromagnetic brakes are clamped. A <strong>ROS 2 Service</strong> implements this exact synchronous or asynchronous Request-Response RPC pattern. The server acts as the authoritative hardware gatekeeper.\\n      <br><br>\\n      <strong>Flight Objective &amp; Behavioral Outcome:</strong><br>\\n      Construct a Python ROS 2 Service Server that advertises <code>/robot/emergency_stop</code> using <code>nexus_amr_interfaces/srv/TriggerEmergencyStop</code>. When summoned, it latches the e-stop state, commands motor drivers to zero velocity, captures a microsecond audit timestamp, and returns a verified safety receipt.\\n    </div>\\n  </div>\\n</div>\\n\\n\\n<div class=\\"alert-callout alert-info\\" style=\\"margin: 1.5rem 0;\\">\\n  <div class=\\"alert-icon\\">🔍</div>\\n  <div class=\\"alert-body\\">\\n    <strong>Best Practice: Discovering &amp; Inspecting Service Interfaces Before Writing Code</strong><br>\\n    Before implementing a ROS 2 Service Server or Client, always inspect the service definition (<code class=\\"inline-code\\">.srv</code>) to understand both the <strong>Request</strong> and <strong>Response</strong> contracts:\\n    <br><br>\\n    <strong>1. Discover available service interfaces using <code class=\\"inline-code\\">ros2 interface list</code> or <code class=\\"inline-code\\">package</code>:</strong>\\n    <div class=\\"code-container\\" data-language=\\"bash\\" style=\\"margin: 0.6rem 0;\\">\\n      <div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n      <pre><code class=\\"language-bash\\"># Search for emergency or stop service types:\\nros2 interface list | grep srv | grep -i emergency\\n\\n# Or list all service interfaces defined in our AMR workspace package:\\nros2 interface package nexus_amr_interfaces</code></pre>\\n    </div>\\n    <strong>2. Inspect the exact Request and Response fields using <code class=\\"inline-code\\">ros2 interface show</code>:</strong>\\n    <div class=\\"code-container\\" data-language=\\"bash\\" style=\\"margin: 0.6rem 0;\\">\\n      <div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n      <pre><code class=\\"language-bash\\">ros2 interface show nexus_amr_interfaces/srv/TriggerEmergencyStop</code></pre>\\n    </div>\\n    <strong>Expected Output &amp; The Three Hyphens (<code class=\\"inline-code\\">---</code>) Delimiter:</strong>\\n    <div class=\\"code-container terminal-window\\" data-language=\\"plaintext\\" style=\\"margin: 0.6rem 0;\\">\\n      <div class=\\"terminal-header\\">\\n        <div class=\\"terminal-dots\\"><span class=\\"dot red\\"></span><span class=\\"dot yellow\\"></span><span class=\\"dot green\\"></span></div>\\n        <span class=\\"terminal-title\\">Terminal &mdash; ros2 interface show nexus_amr_interfaces/srv/TriggerEmergencyStop</span>\\n      </div>\\n      <pre><code class=\\"language-plaintext\\"># Request (Input payload sent by the Client)\\nbool emergency_stop_requested\\nstring reason\\n---\\n# Response (Output payload populated and returned by the Server)\\nbool success\\nstring status_message\\nfloat32 stop_timestamp</code></pre>\\n    </div>\\n    <ul style=\\"margin: 0.5rem 0 0 1.25rem; line-height: 1.6;\\">\\n      <li><strong>Top Half (Request):</strong> Accessed on the <code class=\\"inline-code\\">request</code> argument in your callback (<code class=\\"inline-code\\">request.emergency_stop_requested</code>, <code class=\\"inline-code\\">request.reason</code>).</li>\\n      <li><strong>Bottom Half (Response):</strong> Assigned on the <code class=\\"inline-code\\">response</code> object that your callback returns (<code class=\\"inline-code\\">response.success</code>, <code class=\\"inline-code\\">response.status_message</code>, <code class=\\"inline-code\\">response.stop_timestamp</code>).</li>\\n      <li><strong>Essential CLI Verification Tools:</strong> Check active services with <code class=\\"inline-code\\">ros2 service list</code>, verify interface types with <code class=\\"inline-code\\">ros2 service type &lt;service&gt;</code>, and test your server directly from terminal using <code class=\\"inline-code\\">ros2 service call</code> without writing a client first!</li>\\n    </ul>\\n  </div>\\n</div>\\n\\n<p>Create your safety service server script at <code class=\\"inline-code\\">~/ros2_ws/src/nexus_amr_basics/nexus_amr_basics/emergency_stop_server.py</code>:</p>\\n\\n<div class=\\"code-container ide-code-window\\" data-language=\\"python\\">\\n  <div class=\\"code-header\\">\\n    <div class=\\"code-dots\\"><span class=\\"dot red\\"></span><span class=\\"dot yellow\\"></span><span class=\\"dot green\\"></span></div>\\n    <span class=\\"code-filename\\">emergency_stop_server.py &mdash; AMR Emergency Stop Service Server</span>\\n  </div>\\n  <pre><code class=\\"language-python\\">import rclpy\\nfrom rclpy.node import Node\\nfrom nexus_amr_interfaces.srv import TriggerEmergencyStop\\n\\n\\nclass EmergencyStopServer(Node):\\n    &quot;&quot;&quot;\\n    AMR Emergency Safety Brake Service Server Node.\\n    &quot;&quot;&quot;\\n\\n    def __init__(self):\\n        # Step 1: Initialize node identity\\n        super().__init__(&#x27;emergency_stop_server&#x27;)\\n\\n        # Step 2: Internal hardware safety state machine\\n        # Latching ensures that once engaged, motion cannot resume without an explicit reset.\\n        self.emergency_stop_active = False\\n\\n        # Step 3: Create ROS 2 Service Server\\n        # - TriggerEmergencyStop: Custom interface (.srv)\\n        # - &#x27;/robot/emergency_stop&#x27;: Service name advertised over DDS\\n        # - self.handle_emergency_stop: Member callback handling client requests\\n        self.srv = self.create_service(\\n            TriggerEmergencyStop,\\n            &#x27;/robot/emergency_stop&#x27;,\\n            self.handle_emergency_stop\\n        )\\n\\n        self.get_logger().info(\\n            &#x27;EmergencyStopServer initialized. Ready to receive safety commands on &quot;/robot/emergency_stop&quot;...&#x27;\\n        )\\n\\n    def handle_emergency_stop(self, request, response):\\n        &quot;&quot;&quot;\\n        Executed synchronously by the ROS 2 executor whenever a client invokes this service.\\n        Arguments:\\n        - request: Input payload (contains request.emergency_stop_requested, request.reason)\\n        - response: Output payload to populate and return\\n        &quot;&quot;&quot;\\n        # Capture precise epoch timestamp in seconds\\n        timestamp_sec = self.get_clock().now().nanoseconds * 1e-9\\n\\n        if request.emergency_stop_requested:\\n            # ENGAGE EMERGENCY BRAKES\\n            self.emergency_stop_active = True\\n            response.success = True\\n            response.status_message = (\\n                f&#x27;EMERGENCY BRAKE ENGAGED: Actuators halted. Reason: &quot;{request.reason}&quot;&#x27;\\n            )\\n            response.stop_timestamp = float(round(timestamp_sec, 3))\\n\\n            self.get_logger().error(\\n                f&#x27;[CRITICAL SAFETY EVENT] Emergency Stop ACTIVATED! Reason: {request.reason}&#x27;\\n            )\\n        else:\\n            # RESET SAFETY SYSTEM\\n            self.emergency_stop_active = False\\n            response.success = True\\n            response.status_message = &#x27;SAFETY RESET: Actuator power restored. Drive authorized.&#x27;\\n            response.stop_timestamp = float(round(timestamp_sec, 3))\\n\\n            self.get_logger().info(\\n                &#x27;[SAFETY STATUS] Emergency Stop CLEARED. Drive systems ready.&#x27;\\n            )\\n\\n        # In ROS 2 service callbacks, ALWAYS return the populated response object\\n        return response\\n\\n\\ndef main(args=None):\\n    rclpy.init(args=args)\\n    node = EmergencyStopServer()\\n\\n    try:\\n        # Blocks in event loop, awaiting RPC service calls over DDS\\n        rclpy.spin(node)\\n    except KeyboardInterrupt:\\n        pass\\n    finally:\\n        node.destroy_node()\\n        rclpy.shutdown()\\n\\n\\nif __name__ == &#x27;__main__&#x27;:\\n    main()\\n</code></pre>\\n</div>\\n\\n<div class=\\"code-breakdown-card\\">\\n  <h4 class=\\"code-breakdown-title\\">🔬 Core Code Deep Dive &amp; Operational Breakdown: EmergencyStopServer Mechanics</h4>\\n  <p class=\\"code-breakdown-intro\\">Let's dissect how this Emergency Stop Service Server operates under the hood within the ROS 2 DDS middleware and rclpy execution runtime:</p>\\n  <ul class=\\"code-breakdown-list\\">\\n    <li class=\\"code-breakdown-item\\"><strong>Node Identity & Graph Registration:</strong> <code>class EmergencyStopServer(Node):</code> subclasses <code>rclpy.node.Node</code>, and <code>super().__init__('emergency_stop_server')</code> registers this node's unique identifier into the ROS 2 computational graph. This name is what appears in <code>ros2 node list</code>.</li>\\n    <li class=\\"code-breakdown-item\\"><strong>State Latching Invariant:</strong> <code>self.emergency_stop_active = False</code> maintains the node's internal state machine. In physical robotics, latching ensures that once an emergency stop is tripped, the robot cannot accidentally resume driving until an explicit reset request is validated.</li>\\n    <li class=\\"code-breakdown-item\\"><strong>Service Server Allocation:</strong> <code>self.srv = self.create_service(TriggerEmergencyStop, '/robot/emergency_stop', self.handle_emergency_stop)</code> allocates a DDS RPC server on <code>/robot/emergency_stop</code>. Notice the 3 arguments: interface type, service name, and bound member callback.</li>\\n    <li class=\\"code-breakdown-item\\"><strong>Callback Signature & Mutability:</strong> <code>def handle_emergency_stop(self, request, response):</code> is invoked when a client sends a request. ROS 2 automatically instantiates and passes two arguments: <code>request</code> (containing client fields, e.g. <code>request.reason</code>) and <code>response</code> (an empty response object which the callback mutates and must return).</li>\\n    <li class=\\"code-breakdown-item\\"><strong>Hardware Response Contract:</strong> The server checks <code>request.emergency_stop_requested</code>, latches <code>self.emergency_stop_active</code>, populates <code>response.success = True</code>, sets <code>response.status_message</code>, records <code>response.stop_timestamp</code>, and returns <code>response</code>. The DDS layer serializes this response directly back to the client.</li>\\n    <li class=\\"code-breakdown-item\\"><strong>Execution Loop (rclpy.spin):</strong> In <code>main()</code>, <code>rclpy.spin(node)</code> blocks the main thread in a <code>SingleThreadedExecutor</code> event loop. Whenever an incoming DDS service request arrives, the executor dispatches <code>handle_emergency_stop</code>, sends the response, and returns to waiting.</li>\\n  </ul>\\n</div>\\n\\n<h2 id=\\"4-configuring-setuppy-building-testing-server-with-cli\\">4. Configuring setup.py, Building &amp; Testing the Service Server with ROS 2 CLI</h2>\\n<p>Before writing the client node, you must configure your package entry points, compile with symlink installation, and <strong>verify the service server directly using the ROS 2 CLI</strong>.</p>\\n\\n<div class=\\"file-edit-instruction-card\\">\\n  <div class=\\"file-edit-header\\">\\n    <div class=\\"file-edit-header-left\\">\\n      <span>📝 Step-by-Step File Modification Guide</span>\\n    </div>\\n    <span class=\\"file-edit-badge\\">~/ros2_ws/src/nexus_amr_basics/setup.py</span>\\n  </div>\\n  <div class=\\"file-edit-body\\">\\n    <div class=\\"file-edit-step\\">\\n      <div class=\\"file-edit-step-title\\">\\n        <span class=\\"step-num-pill\\">Step 1</span>\\n        <span>Open the Target File</span>\\n      </div>\\n      <p class=\\"step-description\\">Open <code class=\\"inline-code\\">~/ros2_ws/src/nexus_amr_basics/setup.py</code> in your editor.</p>\\n    </div>\\n\\n    <div class=\\"file-edit-step\\">\\n      <div class=\\"file-edit-step-title\\">\\n        <span class=\\"step-num-pill\\">Step 2</span>\\n        <span>Locate Insertion Point &amp; Add Lines</span>\\n      </div>\\n      <p class=\\"step-description\\">Register the emergency stop service server executable in <code class=\\"inline-code\\">'console_scripts'</code>:</p>\\n      <div class=\\"code-container\\" data-language=\\"python\\">\\n        <div class=\\"code-header\\"><span class=\\"code-lang-tag\\">python</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n        <pre><code class=\\"language-python\\">    entry_points={\\n        'console_scripts': [\\n            'ultrasonic_publisher = nexus_amr_basics.ultrasonic_sensor_node:main',\\n            'collision_monitor = nexus_amr_basics.collision_monitor_node:main',\\n            # >>> REGISTER EMERGENCY STOP SAFETY SERVICE SERVER <<<\\n            'emergency_stop_server = nexus_amr_basics.emergency_stop_server:main',\\n        ],\\n    },</code></pre>\\n      </div>\\n    </div>\\n\\n    <div class=\\"file-edit-step\\">\\n      <div class=\\"file-edit-step-title\\">\\n        <span class=\\"step-num-pill\\">Step 3</span>\\n        <span>Verify the Full File After Editing</span>\\n      </div>\\n      <p class=\\"step-description\\">Self-check your file against the complete reference below to confirm indentation and closing brackets:</p>\\n      <details class=\\"file-edit-dropdown\\">\\n        <summary class=\\"file-edit-summary\\">\\n          <span>📄 View Complete setup.py with Service Server Entry Point</span>\\n          <span class=\\"file-edit-toggle-icon\\">▶</span>\\n        </summary>\\n        <div class=\\"file-edit-dropdown-content\\">\\n          <div class=\\"code-container\\" data-language=\\"python\\">\\n            <div class=\\"code-header\\"><span class=\\"code-lang-tag\\">python</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n            <pre><code class=\\"language-python\\">from setuptools import find_packages, setup\\n\\npackage_name = &#x27;nexus_amr_basics&#x27;\\n\\nsetup(\\n    name=package_name,\\n    version=&#x27;1.0.0&#x27;,\\n    packages=find_packages(exclude=[&#x27;test&#x27;]),\\n    data_files=[\\n        (&#x27;share/ament_index/resource_index/packages&#x27;, [&#x27;resource/&#x27; + package_name]),\\n        (&#x27;share/&#x27; + package_name, [&#x27;package.xml&#x27;]),\\n    ],\\n    install_requires=[&#x27;setuptools&#x27;],\\n    zip_safe=True,\\n    maintainer=&#x27;Nexus AMR Academy&#x27;,\\n    maintainer_email=&#x27;instructor@botforge.io&#x27;,\\n    description=&#x27;ROS 2 Sensor &amp; Telemetry Fundamentals&#x27;,\\n    license=&#x27;Apache-2.0&#x27;,\\n    tests_require=[&#x27;pytest&#x27;],\\n    entry_points={\\n        &#x27;console_scripts&#x27;: [\\n            &#x27;ultrasonic_publisher = nexus_amr_basics.ultrasonic_sensor_node:main&#x27;,\\n            &#x27;collision_monitor = nexus_amr_basics.collision_monitor_node:main&#x27;,\\n            &#x27;emergency_stop_server = nexus_amr_basics.emergency_stop_server:main&#x27;,\\n        ],\\n    },\\n)</code></pre>\\n          </div>\\n        </div>\\n      </details>\\n    </div>\\n  </div>\\n</div>\\n\\n<h3 id=\\"42-build-and-test-server-with-cli\\">4.2 Build and Introspect the Service Server with ROS 2 CLI</h3>\\n<p>Compile the workspace and start the service server in Terminal 1:</p>\\n<div class=\\"code-container\\" data-language=\\"bash\\">\\n  <div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n  <pre><code class=\\"language-bash\\">cd ~/ros2_ws\\ncolcon build --symlink-install --packages-select nexus_amr_basics\\nsource install/setup.bash\\nros2 run nexus_amr_basics emergency_stop_server</code></pre>\\n</div>\\n\\n<p>In <strong>Terminal 2</strong>, test and verify the service endpoint using the command-line interface:</p>\\n<div class=\\"code-container\\" data-language=\\"bash\\">\\n  <div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n  <pre><code class=\\"language-bash\\">source /opt/ros/jazzy/setup.bash\\n\\n# 1. First, list active services to verify the service appears on the network graph:\\nros2 service list\\n# (Notice /robot/emergency_stop alongside default parameter services)\\n\\n# 2. Check the service interface definition type:\\nros2 service type /robot/emergency_stop\\n# Expected Output:\\n# nexus_amr_interfaces/srv/TriggerEmergencyStop\\n\\n# 3. Call the service directly from the command line:\\nros2 service call /robot/emergency_stop nexus_amr_interfaces/srv/TriggerEmergencyStop \\"{emergency_stop_requested: true, reason: 'Benchtop safety sensor trip'}\\"</code></pre>\\n</div>\\n<p>You will see the server respond with <code class=\\"inline-code\\">response: nexus_amr_interfaces.srv.TriggerEmergencyStop_Response(success=True, status_message='Emergency stop ENGAGED: Power to motor drivers cut.', stop_timestamp=1729017234.120)</code>. <strong>The server is now verified functional!</strong> Next, write the client node to call this programmatically from Python.</p>\\n\\n<h2 id=\\"5-building-an-asynchronous-emergency-stop-client\\">5. Building an Asynchronous Emergency Stop Client in Python</h2>\\n\\n<div class=\\"alert alert-info alert-briefing\\">\\n  <div class=\\"alert-icon\\">⚡</div>\\n  <div class=\\"alert-content\\">\\n    <div class=\\"alert-title\\">Robotics Flight Operations Mission Briefing: Asynchronous Emergency Stop Safety Client</div>\\n    <div class=\\"alert-body\\">\\n      <strong>Physical AMR Context &amp; Operational Challenge:</strong><br>\\n      On an industrial AMR, obstacle detection sensors (3D depth cameras, safety LiDARs, ultrasonic rangefinders) run high-frequency polling loops (20 Hz - 50 Hz). When a sensor algorithm flags an obstacle within the critical safety envelope, it must command the safety server to engage emergency brakes immediately without interrupting other real-time processes.\\n      <br><br>\\n      <strong>Architectural Role &amp; Why This Mechanism:</strong><br>\\n      If a client node makes a synchronous, blocking service call (<code>client.call(request)</code>) inside an active timer callback or subscriber callback, the single-threaded executor freezes entirely! The node cannot process incoming sensor packets, cannot calculate odometry, and deadlocks permanently. In production robotics, service clients must <strong>always</strong> invoke <code>call_async()</code>, which returns a Python <code>Future</code> without stalling the executor thread.\\n      <br><br>\\n      <strong>Flight Objective &amp; Behavioral Outcome:</strong><br>\\n      Build an asynchronous ROS 2 Service Client that checks DDS network availability, formats an emergency stop request with operational reason telemetry, dispatches it asynchronously via <code>call_async()</code>, and uses <code>rclpy.spin_until_future_complete()</code> to confirm brake actuation safely.\\n    </div>\\n  </div>\\n</div>\\n\\n<p>When an AMR detects an imminent hazard, it must invoke the emergency stop service <strong>without deadlocking</strong> the calling node. In ROS 2, always use <code class=\\"inline-code\\">call_async()</code>.</p>\\n\\n<p>Create your safety service client script at <code class=\\"inline-code\\">~/ros2_ws/src/nexus_amr_basics/nexus_amr_basics/emergency_stop_client.py</code>:</p>\\n\\n<div class=\\"code-container ide-code-window\\" data-language=\\"python\\">\\n  <div class=\\"code-header\\">\\n    <div class=\\"code-dots\\"><span class=\\"dot red\\"></span><span class=\\"dot yellow\\"></span><span class=\\"dot green\\"></span></div>\\n    <span class=\\"code-filename\\">emergency_stop_client.py &mdash; AMR Emergency Stop Client</span>\\n  </div>\\n  <pre><code class=\\"language-python\\">import sys\\nimport rclpy\\nfrom rclpy.node import Node\\nfrom nexus_amr_interfaces.srv import TriggerEmergencyStop\\n\\n\\nclass EmergencyStopClient(Node):\\n    &quot;&quot;&quot;\\n    AMR Emergency Safety Brake Service Client Node.\\n    &quot;&quot;&quot;\\n\\n    def __init__(self):\\n        super().__init__(&#x27;emergency_stop_client&#x27;)\\n\\n        # Step 1: Create Service Client for &#x27;/robot/emergency_stop&#x27;\\n        self.client = self.create_client(\\n            TriggerEmergencyStop,\\n            &#x27;/robot/emergency_stop&#x27;\\n        )\\n\\n        # Step 2: Liveness verification with timeout\\n        # Polls DDS discovery every 1.0s to confirm server node is alive\\n        while not self.client.wait_for_service(timeout_sec=1.0):\\n            self.get_logger().info(&#x27;Service &quot;/robot/emergency_stop&quot; not available, waiting...&#x27;)\\n\\n        self.get_logger().info(&#x27;EmergencyStopClient connected to safety service.&#x27;)\\n\\n    def send_emergency_stop_request(self, stop_requested: bool, reason: str):\\n        &quot;&quot;&quot;\\n        Dispatches a non-blocking asynchronous service request.\\n        Returns a rclpy.task.Future object.\\n        &quot;&quot;&quot;\\n        # Step 3: Instantiate and populate strongly-typed request struct\\n        request = TriggerEmergencyStop.Request()\\n        request.emergency_stop_requested = stop_requested\\n        request.reason = reason\\n\\n        self.get_logger().info(\\n            f&#x27;Dispatching Emergency Stop Request: stop={stop_requested}, reason=&quot;{reason}&quot;&#x27;\\n        )\\n\\n        # Step 4: Asynchronous dispatch over DDS (returns immediately)\\n        self.future = self.client.call_async(request)\\n        return self.future\\n\\n\\ndef main(args=None):\\n    rclpy.init(args=args)\\n    client_node = EmergencyStopClient()\\n\\n    # Determine reason from CLI arguments or use standard default\\n    stop_reason = &quot;Obstacle detected within 0.35m critical safety envelope&quot;\\n    if len(sys.argv) &gt; 1:\\n        stop_reason = &quot; &quot;.join(sys.argv[1:])\\n\\n    # Dispatch asynchronous request\\n    future = client_node.send_emergency_stop_request(True, stop_reason)\\n\\n    # Step 5: Spin the executor until the response future completes\\n    rclpy.spin_until_future_complete(client_node, future)\\n\\n    # Step 6: Validate result\\n    if future.result() is not None:\\n        response = future.result()\\n        client_node.get_logger().info(\\n            f&#x27;SAFETY RESPONSE RECEIVED: &#x27;\\n            f&#x27;Success: {response.success} | &#x27;\\n            f&#x27;Status: {response.status_message} | &#x27;\\n            f&#x27;Time: {response.stop_timestamp:.3f} s&#x27;\\n        )\\n    else:\\n        client_node.get_logger().error(f&#x27;Service call failed: {future.exception()}&#x27;)\\n\\n    client_node.destroy_node()\\n    rclpy.shutdown()\\n\\n\\nif __name__ == &#x27;__main__&#x27;:\\n    main()\\n</code></pre>\\n</div>\\n\\n</div>\\n\\n<div class=\\"code-breakdown-card\\">\\n  <h4 class=\\"code-breakdown-title\\">🔬 Core Code Deep Dive &amp; Operational Breakdown: EmergencyStopClient Non-Blocking Architecture</h4>\\n  <p class=\\"code-breakdown-intro\\">Let's dissect how this Asynchronous Service Client safely interfaces with the AMR's safety server without deadlocking the executor:</p>\\n  <ul class=\\"code-breakdown-list\\">\\n    <li class=\\"code-breakdown-item\\"><strong>Client Channel Creation:</strong> <code>self.client = self.create_client(TriggerEmergencyStop, '/robot/emergency_stop')</code> registers a DDS service client endpoint. Both server and client must match the interface type and the exact topic name.</li>\\n    <li class=\\"code-breakdown-item\\"><strong>Liveness Check & Timeout Handling:</strong> <code>while not self.client.wait_for_service(timeout_sec=1.0):</code> polls DDS discovery to verify that an active server is advertising the service. This prevents transmitting safety commands into an unpopulated network graph.</li>\\n    <li class=\\"code-breakdown-item\\"><strong>Asynchronous Dispatch via Futures:</strong> <code>self.future = self.client.call_async(request)</code> is the golden rule of ROS 2 service communication. It sends the serialized request over DDS and returns a <code>rclpy.task.Future</code> object immediately without blocking the thread.</li>\\n    <li class=\\"code-breakdown-item\\"><strong>Executor Spin Until Future Completes:</strong> In <code>main()</code>, <code>rclpy.spin_until_future_complete(client_node, future)</code> executes the node's event loop only until the service response packet is received and decoded. Once <code>future.done()</code> is true, execution resumes cleanly.</li>\\n    <li class=\\"code-breakdown-item\\"><strong>Response Extraction & Verification:</strong> <code>response = future.result()</code> extracts the populated response from the server, allowing the supervisor node to verify <code>response.success == True</code> and inspect the confirmation timestamp before declaring the robot safely stopped.</li>\\n  </ul>\\n</div>\\n\\n<h2 id=\\"6-configuring-setuppy-verifying-client-server-pair\\">6. Configuring setup.py &amp; Verifying the Client-Server Pair</h2>\\n<p>With both nodes coded, register the client executable in <code class=\\"inline-code\\">setup.py</code>, recompile your package with <code class=\\"inline-code\\">colcon</code>, and test the paired safety communication.</p>\\n\\n<div class=\\"file-edit-instruction-card\\">\\n  <div class=\\"file-edit-header\\">\\n    <div class=\\"file-edit-header-left\\">\\n      <span>📝 Step-by-Step File Modification Guide</span>\\n    </div>\\n    <span class=\\"file-edit-badge\\">~/ros2_ws/src/nexus_amr_basics/setup.py</span>\\n  </div>\\n  <div class=\\"file-edit-body\\">\\n    <div class=\\"file-edit-step\\">\\n      <div class=\\"file-edit-step-title\\">\\n        <span class=\\"step-num-pill\\">Step 1</span>\\n        <span>Open the Target File</span>\\n      </div>\\n      <p class=\\"step-description\\">Open <code class=\\"inline-code\\">~/ros2_ws/src/nexus_amr_basics/setup.py</code> in your editor.</p>\\n    </div>\\n\\n    <div class=\\"file-edit-step\\">\\n      <div class=\\"file-edit-step-title\\">\\n        <span class=\\"step-num-pill\\">Step 2</span>\\n        <span>Locate Insertion Point &amp; Add Client Executable</span>\\n      </div>\\n      <p class=\\"step-description\\">Append the emergency stop client entry point right below the server in <code class=\\"inline-code\\">'console_scripts'</code>:</p>\\n      <div class=\\"code-container\\" data-language=\\"python\\">\\n        <div class=\\"code-header\\"><span class=\\"code-lang-tag\\">python</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n        <pre><code class=\\"language-python\\">    entry_points={\\n        'console_scripts': [\\n            'ultrasonic_publisher = nexus_amr_basics.ultrasonic_sensor_node:main',\\n            'collision_monitor = nexus_amr_basics.collision_monitor_node:main',\\n            'emergency_stop_server = nexus_amr_basics.emergency_stop_server:main',\\n            # >>> REGISTER EMERGENCY STOP SAFETY CLIENT <<<\\n            'emergency_stop_client = nexus_amr_basics.emergency_stop_client:main',\\n        ],\\n    },</code></pre>\\n      </div>\\n    </div>\\n\\n    <div class=\\"file-edit-step\\">\\n      <div class=\\"file-edit-step-title\\">\\n        <span class=\\"step-num-pill\\">Step 3</span>\\n        <span>Verify the Full File After Editing</span>\\n      </div>\\n      <p class=\\"step-description\\">Self-check your file against the complete reference below to confirm indentation and closing brackets:</p>\\n      <details class=\\"file-edit-dropdown\\">\\n        <summary class=\\"file-edit-summary\\">\\n          <span>📄 View Complete setup.py with Server and Client Entry Points</span>\\n          <span class=\\"file-edit-toggle-icon\\">▶</span>\\n        </summary>\\n        <div class=\\"file-edit-dropdown-content\\">\\n          <div class=\\"code-container\\" data-language=\\"python\\">\\n            <div class=\\"code-header\\"><span class=\\"code-lang-tag\\">python</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n            <pre><code class=\\"language-python\\">from setuptools import find_packages, setup\\n\\npackage_name = 'nexus_amr_basics'\\n\\nsetup(\\n    name=package_name,\\n    version='1.0.0',\\n    packages=find_packages(exclude=['test']),\\n    data_files=[\\n        ('share/ament_index/resource_index/packages', ['resource/' + package_name]),\\n        ('share/' + package_name, ['package.xml']),\\n    ],\\n    install_requires=['setuptools'],\\n    zip_safe=True,\\n    maintainer='Nexus AMR Academy',\\n    maintainer_email='instructor@botforge.io',\\n    description='ROS 2 Sensor &amp; Telemetry Fundamentals',\\n    license='Apache-2.0',\\n    tests_require=['pytest'],\\n    entry_points={\\n        'console_scripts': [\\n            'ultrasonic_publisher = nexus_amr_basics.ultrasonic_sensor_node:main',\\n            'collision_monitor = nexus_amr_basics.collision_monitor_node:main',\\n            'emergency_stop_server = nexus_amr_basics.emergency_stop_server:main',\\n            'emergency_stop_client = nexus_amr_basics.emergency_stop_client:main',\\n        ],\\n    },\\n)</code></pre>\\n          </div>\\n        </div>\\n      </details>\\n    </div>\\n  </div>\\n</div>\\n\\n<h3 id=\\"62-build-and-run-paired-safety-nodes\\">6.2 Build and Run the Paired Safety Nodes</h3>\\n<p>Recompile your package with <code class=\\"inline-code\\">colcon</code> so the new client executable is indexed:</p>\\n<div class=\\"code-container\\" data-language=\\"bash\\">\\n  <div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n  <pre><code class=\\"language-bash\\">cd ~/ros2_ws\\ncolcon build --symlink-install --packages-select nexus_amr_basics\\nsource install/setup.bash</code></pre>\\n</div>\\n\\n<p>Deploy and test the paired safety communication across two terminal windows:</p>\\n\\n<p><strong>Terminal 1: Start the Emergency Stop Safety Service Server</strong></p>\\n<div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\">source /opt/ros/jazzy/setup.bash\\nsource ~/ros2_ws/install/setup.bash\\nros2 run nexus_amr_basics emergency_stop_server\\n# Expected Output:\\n# [INFO] [emergency_stop_server]: EmergencyStopServer initialized. Ready to receive safety commands on \\"/robot/emergency_stop\\"...</code></pre>\\n</div>\\n\\n<p><strong>Terminal 2: Run the Asynchronous Emergency Stop Client</strong></p>\\n<div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\">source /opt/ros/jazzy/setup.bash\\nsource ~/ros2_ws/install/setup.bash\\nros2 run nexus_amr_basics emergency_stop_client \\"Obstacle detected within 0.35m critical safety envelope\\"\\n# Expected Output:\\n# [INFO] [emergency_stop_client]: EmergencyStopClient connected to safety service.\\n# [INFO] [emergency_stop_client]: Dispatching Emergency Stop Request: stop=True, reason=\\"Obstacle detected within 0.35m critical safety envelope\\"\\n# [INFO] [emergency_stop_client]: SAFETY RESPONSE RECEIVED: Success: True | Status: EMERGENCY BRAKE ENGAGED: Actuators halted. Reason: \\"Obstacle detected within 0.35m critical safety envelope\\" | Time: 1729017234.120 s</code></pre>\\n</div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"7-hands-on-student-challenge\\">7. Hands-on Student Challenge: Autonomous Mobile Robot Operational Speed Mode &amp; Zone Governor Service Server</h2>\\n<p>In automated warehouse fulfillment centers, Autonomous Mobile Robots (AMRs) operate across distinct speed zones to balance high-throughput cargo transfer with worker safety. Your mission is to implement a robust, defensive ROS 2 Service Server that receives zone dispatch commands from the Fleet Management System (FMS), validates speed envelopes, updates motor speed limits, and returns verified receipts using the custom <code class=\\"inline-code\\">nexus_amr_interfaces/srv/SetSpeedMode</code> interface.</p>\\n\\n<div class=\\"alert alert-info alert-briefing\\">\\n  <div class=\\"alert-icon\\">🚀</div>\\n  <div class=\\"alert-content\\">\\n    <div class=\\"alert-title\\">Robotics Flight Operations Mission Briefing: AMR Operational Speed Mode &amp; Zone Dispatch Server</div>\\n    <div class=\\"alert-body\\">\\n      <strong>Physical AMR Context &amp; Operational Challenge:</strong><br>\\n      Autonomous Mobile Robots operating in dynamic logistics centers must adapt their kinetic parameters across different facility sectors. Driving at full speed (<strong>TURBO: 1.00 scale / 1.5 m/s</strong>) down an active pallet transfer corridor maximizes warehouse throughput. However, entering congested warehouse aisle intersections or shared human picking aisles mandates strict deceleration to <strong>ECO: 0.35 scale / 0.5 m/s</strong> to comply with industrial safety guidelines (ISO 3691-4).\\n      <br><br>\\n      <strong>Architectural Role &amp; Why This Mechanism:</strong><br>\\n      Instead of hardcoding fixed speeds in path planners, a centralized Fleet Management System (FMS) commands speed mode updates as the AMR crosses geo-fenced RFID tags or optical floor codes. A <strong>ROS 2 Service</strong> implements this exact deterministic Request-Response RPC transaction. The server acts as an authoritative governor: it defensively checks incoming mode codes, verifies custom scale bounds against physical motor curves, updates internal velocity limits, and returns a verified receipt.\\n      <br><br>\\n      <strong>Flight Objective &amp; Behavioral Outcome:</strong><br>\\n      You will construct the <code>SpeedModeServerTask</code> node (node identity: <code>'speed_mode_server'</code>). When a fleet manager calls <code>/amr/set_speed_mode</code> with <code>nexus_amr_interfaces/srv/SetSpeedMode</code>, your server validates the command against vehicle dynamics limits, updates the active drive scale, and replies with confirmed execution parameters.\\n    </div>\\n  </div>\\n</div>\\n\\n<div class=\\"alert alert-tip\\">\\n  <div class=\\"alert-title\\">🎯 Mission Requirements</div>\\n  <ol>\\n    <li><strong>TODO 1:</strong> Initialize a Service Server on endpoint <code class=\\"inline-code\\">/amr/set_speed_mode</code> using interface <code class=\\"inline-code\\">nexus_amr_interfaces/srv/SetSpeedMode</code> with callback <code class=\\"inline-code\\">self.handle_speed_mode</code>.</li>\\n    <li><strong>TODO 2:</strong> In <code class=\\"inline-code\\">handle_speed_mode(self, request, response)</code>, sanitize the incoming string with <code class=\\"inline-code\\">mode = request.mode_name.upper().strip()</code> and evaluate standard modes:\\n      <ul>\\n        <li><code class=\\"inline-code\\">'TURBO'</code> &rarr; set <code class=\\"inline-code\\">scale = 1.00</code> (100% velocity: 1.5 m/s, high-speed arterial corridor)</li>\\n        <li><code class=\\"inline-code\\">'NORMAL'</code> &rarr; set <code class=\\"inline-code\\">scale = 0.70</code> (70% velocity: 1.0 m/s, standard production inventory aisles)</li>\\n        <li><code class=\\"inline-code\\">'ECO'</code> &rarr; set <code class=\\"inline-code\\">scale = 0.35</code> (35% velocity: 0.5 m/s, high-pedestrian picking zones)</li>\\n      </ul>\\n    </li>\\n    <li><strong>TODO 3:</strong> For <code class=\\"inline-code\\">'CUSTOM'</code> mode, clamp <code class=\\"inline-code\\">request.custom_scale</code> safely within <code class=\\"inline-code\\">[0.10, 1.00]</code> using <code class=\\"inline-code\\">max(0.10, min(1.00, float(request.custom_scale)))</code>.</li>\\n    <li><strong>TODO 4:</strong> If an unrecognized mode is received (e.g. <code class=\\"inline-code\\">'HYPERSPEED'</code>), reject defensively: set <code class=\\"inline-code\\">response.success = False</code>, keep <code class=\\"inline-code\\">response.effective_scale = self.current_scale</code>, populate an informative error message, log a warning, and return early.</li>\\n    <li><strong>TODO 5:</strong> When valid, latch <code class=\\"inline-code\\">self.current_scale = scale</code> and <code class=\\"inline-code\\">self.active_mode = mode</code>, set <code class=\\"inline-code\\">response.success = True</code>, <code class=\\"inline-code\\">response.effective_scale = float(scale)</code>, populate confirmation status, log execution, and return the response.</li>\\n  </ol>\\n</div>\\n\\n<h3 id=\\"71-starter-template\\">7.1 Starter Template: <code class=\\"inline-code\\">m01_l06_task_speed_mode_server.py</code></h3>\\n<p>Copy the starter template from the reference workspace into your active student workspace:</p>\\n<div class=\\"code-container\\" data-language=\\"bash\\">\\n  <div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n  <pre><code class=\\"language-bash\\">cp ~/ros2_ws_reference/src/nexus_amr_basics/nexus_amr_basics/m01_l06_task_speed_mode_server.py ~/ros2_ws/src/nexus_amr_basics/nexus_amr_basics/</code></pre>\\n</div>\\n<p>Open the copied file in your editor and complete the marked <code class=\\"inline-code\\">TODO</code> targets:</p>\\n\\n<div class=\\"code-container\\" data-language=\\"python\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">python</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-python\\">#!/usr/bin/env python3\\n&quot;&quot;&quot;\\n================================================================================\\nNexus AMR Learning Hub - Level 1: Module 1 / Lesson 06 Student Challenge\\nPackage: nexus_amr_basics\\nTask:    m01_l06_task_speed_mode_server.py (alias: task_speed_mode_server)\\n================================================================================\\n\\nROBOTICS OPERATIONAL MISSION:\\n-----------------------------\\nAutonomous Mobile Robots (AMRs) in smart warehouses operate across distinct zones:\\n- &#x27;TURBO&#x27;  -&gt; 1.00 (100% velocity: 1.5 m/s, high-clearance express transit corridors)\\n- &#x27;NORMAL&#x27; -&gt; 0.70 (70% velocity: 1.0 m/s, standard production inventory aisles)\\n- &#x27;ECO&#x27;    -&gt; 0.35 (35% velocity: 0.5 m/s, high-density human picking areas)\\n- &#x27;CUSTOM&#x27; -&gt; User-defined scale clamped safely between [0.10, 1.00]\\n\\nYour mission is to construct an authoritative ROS 2 Service Server that receives\\nzone speed configuration requests from the Fleet Management System (FMS),\\nvalidates the requested mode against robot motor capabilities, updates internal\\nspeed limits, and returns a verified confirmation receipt.\\n\\nINTERFACE SPECIFICATION (\`nexus_amr_interfaces/srv/SetSpeedMode.srv\`):\\n-------------------------------------------------------------------\\nRequest:\\n    string mode_name          # &quot;TURBO&quot;, &quot;NORMAL&quot;, &quot;ECO&quot;, or &quot;CUSTOM&quot;\\n    float32 custom_scale      # Used if mode_name == &quot;CUSTOM&quot; (0.10 to 1.00)\\n---\\nResponse:\\n    bool success              # True if mode accepted; False if invalid\\n    string message            # Diagnostic execution status\\n    float32 effective_scale   # Active velocity scale applied to actuators\\n================================================================================\\n&quot;&quot;&quot;\\n\\nimport rclpy\\nfrom rclpy.node import Node\\nfrom nexus_amr_interfaces.srv import SetSpeedMode\\n\\n\\nclass SpeedModeServerTask(Node):\\n    &quot;&quot;&quot;\\n    Student Starter Template: AMR Operational Speed Mode Service Server\\n    &quot;&quot;&quot;\\n\\n    def __init__(self):\\n        # Step 1: Initialize the node name\\n        super().__init__(&#x27;speed_mode_server&#x27;)\\n\\n        # Internal speed state machine: defaults to 70% NORMAL operation\\n        self.current_scale = 0.70\\n        self.active_mode = &#x27;NORMAL&#x27;\\n\\n        # ======================================================================\\n        # TODO 1: Create the ROS 2 Service Server\\n        # - Interface Type:    SetSpeedMode (from nexus_amr_interfaces.srv)\\n        # - Service Endpoint:  &#x27;/amr/set_speed_mode&#x27;\\n        # - Callback Method:   self.handle_speed_mode\\n        #\\n        # Hint: Use self.create_service(InterfaceType, &#x27;service_name&#x27;, callback)\\n        # ======================================================================\\n        self.srv = None  # ---&gt; REPLACE WITH YOUR CODE HERE &lt;---\\n\\n        self.get_logger().info(\\n            f&#x27;SpeedModeServerTask initialized in {self.active_mode} mode ({self.current_scale * 100:.0f}%). &#x27;\\n            &#x27;Awaiting /amr/set_speed_mode requests...&#x27;\\n        )\\n\\n    def handle_speed_mode(self, request, response):\\n        &quot;&quot;&quot;\\n        Callback executed whenever a client calls &#x27;/amr/set_speed_mode&#x27;.\\n        Arguments:\\n        - request: Contains request.mode_name and request.custom_scale\\n        - response: The SetSpeedMode.Response object to populate and return\\n        &quot;&quot;&quot;\\n        # Step 2: Sanitize the incoming mode string (strip whitespace, uppercase)\\n        mode = request.mode_name.upper().strip()\\n\\n        # ======================================================================\\n        # TODO 2: Validate Mode &amp; Calculate Operational Velocity Scale\\n        #\\n        # Requirements:\\n        # 1. If mode == &#x27;TURBO&#x27;:  set scale = 1.00\\n        # 2. If mode == &#x27;NORMAL&#x27;: set scale = 0.70\\n        # 3. If mode == &#x27;ECO&#x27;:    set scale = 0.35\\n        # 4. If mode == &#x27;CUSTOM&#x27;:\\n        #    Clamp request.custom_scale safely between 0.10 (min) and 1.00 (max)\\n        #    Hint: max(0.10, min(1.00, float(request.custom_scale)))\\n        # 5. If mode is unrecognized (e.g. &#x27;HYPERSPEED&#x27;):\\n        #    - Set response.success = False\\n        #    - Set response.effective_scale = self.current_scale (unchanged)\\n        #    - Set response.message = f&quot;Invalid mode &#x27;{mode}&#x27;. Permitted: TURBO, NORMAL, ECO, CUSTOM&quot;\\n        #    - Log a warning via self.get_logger().warn(...)\\n        #    - Return response immediately!\\n        # ======================================================================\\n        scale = None  # ---&gt; YOUR MODE EVALUATION LOGIC HERE &lt;---\\n\\n        # ======================================================================\\n        # TODO 3: Update Internal Node State\\n        # - Save the validated scale to self.current_scale\\n        # - Save the validated mode to self.active_mode\\n        # ======================================================================\\n        # ---&gt; YOUR CODE HERE &lt;---\\n\\n        # ======================================================================\\n        # TODO 4: Populate Response Fields &amp; Log Operational Confirmation\\n        # - Set response.success = True\\n        # - Set response.effective_scale = float(scale)\\n        # - Set response.message = f&quot;Speed mode &#x27;{mode}&#x27; applied successfully (scale: {scale * 100:.0f}%).&quot;\\n        # - Log an info message via self.get_logger().info(...)\\n        # ======================================================================\\n        # ---&gt; YOUR CODE HERE &lt;---\\n\\n        # In ROS 2 service callbacks, ALWAYS return the response object!\\n        return response\\n\\n\\ndef main(args=None):\\n    rclpy.init(args=args)\\n    node = SpeedModeServerTask()\\n\\n    try:\\n        # Spin keeps the node alive to service client requests\\n        rclpy.spin(node)\\n    except KeyboardInterrupt:\\n        pass\\n    finally:\\n        # Clean teardown\\n        node.destroy_node()\\n        rclpy.shutdown()\\n\\n\\nif __name__ == &#x27;__main__&#x27;:\\n    main()\\n</code></pre>\\n</div>\\n\\n<h3 id=\\"72-verification-steps\\">7.2 Verification Steps &amp; Expected Terminal Output</h3>\\n<p>Register the task executable in <code class=\\"inline-code\\">setup.py</code>, build with <code class=\\"inline-code\\">colcon</code>, launch your server node in Terminal 1, and test zone dispatch service calls from Terminal 2:</p>\\n<div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash (Terminal 1 - Build &amp; Run Service Server)</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\"># Register entrypoint in ~/ros2_ws/src/nexus_amr_basics/setup.py under console_scripts:\\n# 'task_speed_mode_server = nexus_amr_basics.m01_l06_task_speed_mode_server:main',\\n\\n# Rebuild package:\\ncd ~/ros2_ws\\ncolcon build --symlink-install --packages-select nexus_amr_basics\\nsource install/setup.bash\\n\\n# Run Server:\\nros2 run nexus_amr_basics task_speed_mode_server</code></pre>\\n</div>\\n\\n<div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash (Terminal 2 - Service Client Calls)</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\">source /opt/ros/jazzy/setup.bash\\n\\n# Call 1: Request TURBO mode (express corridor):\\nros2 service call /amr/set_speed_mode nexus_amr_interfaces/srv/SetSpeedMode \\"{mode_name: 'TURBO'}\\"\\n\\n# Call 2: Request ECO mode (high-pedestrian picking aisle):\\nros2 service call /amr/set_speed_mode nexus_amr_interfaces/srv/SetSpeedMode \\"{mode_name: 'ECO'}\\"\\n\\n# Terminal 2: Request CUSTOM scale (55% speed)\\nros2 service call /amr/set_speed_mode nexus_amr_interfaces/srv/SetSpeedMode \\"{mode_name: 'CUSTOM', custom_scale: 0.55}\\"\\n\\n# Terminal 2: Test defensive error handling with invalid mode\\nros2 service call /amr/set_speed_mode nexus_amr_interfaces/srv/SetSpeedMode \\"{mode_name: 'HYPERSPEED'}\\"</code></pre>\\n</div>\\n\\n<p><em>Expected Terminal Output (Server - Terminal 1):</em></p>\\n<div class=\\"code-container\\" data-language=\\"text\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">text</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-text\\">[INFO] [speed_mode_server]: SpeedModeServerTask initialized in NORMAL mode (70%). Awaiting /amr/set_speed_mode requests...\\n[INFO] [speed_mode_server]: [SPEED MODE] Speed mode 'TURBO' applied successfully (scale: 100%).\\n[INFO] [speed_mode_server]: [SPEED MODE] Speed mode 'ECO' applied successfully (scale: 35%).\\n[INFO] [speed_mode_server]: [SPEED MODE] Speed mode 'CUSTOM' applied successfully (scale: 55%).\\n[WARN] [speed_mode_server]: [REJECTED] Invalid mode 'HYPERSPEED'. Permitted: TURBO, NORMAL, ECO, CUSTOM</code></pre>\\n</div>\\n\\n<p><em>Expected Terminal Output (Client - Terminal 2 Response Receipt):</em></p>\\n<div class=\\"code-container\\" data-language=\\"text\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">text</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-text\\">requester: making request: nexus_amr_interfaces.srv.SetSpeedMode_Request(mode_name='TURBO', custom_scale=0.0)\\n\\nresponse:\\nnexus_amr_interfaces.srv.SetSpeedMode_Response(success=True, message=\\"Speed mode 'TURBO' applied successfully (scale: 100%).\\", effective_scale=1.0)</code></pre>\\n</div>\\n\\n<details class=\\"reference-solution-dropdown\\">\\n  <summary class=\\"solution-summary-btn\\">\\n    <span>🔍 View Reference Solution (<code class=\\"inline-code\\">m01_l06_solution_speed_mode_server.py</code>)</span>\\n  </summary>\\n  <div class=\\"solution-body\\">\\n    <p>Reference file: <code class=\\"inline-code\\">ros2_ws_reference/src/nexus_amr_basics/nexus_amr_basics/m01_l06_solution_speed_mode_server.py</code></p>\\n    <div class=\\"code-container\\" data-language=\\"python\\">\\n      <div class=\\"code-header\\"><span class=\\"code-lang-tag\\">python</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n      <pre><code class=\\"language-python\\">#!/usr/bin/env python3\\n&quot;&quot;&quot;\\n================================================================================\\nNexus AMR Learning Hub - Level 1: Module 1 / Lesson 06 Reference Solution\\nPackage: nexus_amr_basics\\nTask:    m01_l06_solution_speed_mode_server.py (alias: solution_speed_mode_server)\\n================================================================================\\n\\nROBOTICS OPERATIONAL MISSION:\\n-----------------------------\\nReference Solution: AMR Operational Speed Mode &amp; Zone Dispatch Service Server.\\nAutonomous Mobile Robots (AMRs) in smart warehouses operate across distinct zones:\\n- &#x27;TURBO&#x27;  -&gt; 1.00 (100% velocity: 1.5 m/s, high-clearance express transit corridors)\\n- &#x27;NORMAL&#x27; -&gt; 0.70 (70% velocity: 1.0 m/s, standard production inventory aisles)\\n- &#x27;ECO&#x27;    -&gt; 0.35 (35% velocity: 0.5 m/s, high-density human picking areas)\\n- &#x27;CUSTOM&#x27; -&gt; User-defined scale clamped safely between [0.10, 1.00]\\n\\nThis server validates incoming requests defensively and replies with confirmed scale.\\n================================================================================\\n&quot;&quot;&quot;\\n\\nimport rclpy\\nfrom rclpy.node import Node\\nfrom nexus_amr_interfaces.srv import SetSpeedMode\\n\\n\\nclass SpeedModeSolutionServer(Node):\\n    &quot;&quot;&quot;\\n    Reference Solution: AMR Speed Mode Configuration Server\\n    &quot;&quot;&quot;\\n\\n    def __init__(self):\\n        # Step 1: Initialize node identity in computational graph\\n        super().__init__(&#x27;speed_mode_server&#x27;)\\n\\n        # Internal state machine: defaults to 70% normal operation\\n        self.current_scale = 0.70\\n        self.active_mode = &#x27;NORMAL&#x27;\\n\\n        # Step 2: Create Service Server on &#x27;/amr/set_speed_mode&#x27;\\n        # - Interface: SetSpeedMode (custom .srv with request and response fields)\\n        # - Service Endpoint: &#x27;/amr/set_speed_mode&#x27;\\n        # - Callback: self.handle_speed_mode\\n        self.srv = self.create_service(\\n            SetSpeedMode,\\n            &#x27;/amr/set_speed_mode&#x27;,\\n            self.handle_speed_mode\\n        )\\n\\n        self.get_logger().info(\\n            f&#x27;SpeedModeSolutionServer active on /amr/set_speed_mode. Default: {self.active_mode} ({self.current_scale * 100:.0f}%).&#x27;\\n        )\\n\\n    def handle_speed_mode(self, request, response):\\n        &quot;&quot;&quot;\\n        Processes zone dispatch requests and adjusts vehicle speed governors.\\n        &quot;&quot;&quot;\\n        # Step 3: Sanitize incoming mode string\\n        mode = request.mode_name.upper().strip()\\n\\n        # Step 4: Evaluate requested mode against permitted envelopes\\n        if mode == &#x27;TURBO&#x27;:\\n            scale = 1.00\\n        elif mode == &#x27;NORMAL&#x27;:\\n            scale = 0.70\\n        elif mode == &#x27;ECO&#x27;:\\n            scale = 0.35\\n        elif mode == &#x27;CUSTOM&#x27;:\\n            # Defensively clamp custom scale between 10% and 100%\\n            scale = max(0.10, min(1.00, float(request.custom_scale)))\\n        else:\\n            # Reject invalid mode without crashing the node\\n            response.success = False\\n            response.effective_scale = self.current_scale\\n            response.message = f&quot;Invalid mode &#x27;{mode}&#x27;. Permitted: TURBO, NORMAL, ECO, CUSTOM&quot;\\n            self.get_logger().warn(f&#x27;[REJECTED] {response.message}&#x27;)\\n            return response\\n\\n        # Step 5: Latch validated speed state\\n        self.current_scale = scale\\n        self.active_mode = mode\\n\\n        # Step 6: Formulate confirmed response\\n        response.success = True\\n        response.effective_scale = float(scale)\\n        response.message = f&quot;Speed mode &#x27;{mode}&#x27; applied successfully (scale: {scale * 100:.0f}%).&quot;\\n\\n        self.get_logger().info(f&#x27;[SPEED MODE] {response.message}&#x27;)\\n        return response\\n\\n\\ndef main(args=None):\\n    rclpy.init(args=args)\\n    node = SpeedModeSolutionServer()\\n    try:\\n        # Blocks in SingleThreadedExecutor event loop, servicing RPC calls\\n        rclpy.spin(node)\\n    except KeyboardInterrupt:\\n        pass\\n    finally:\\n        # Clean teardown\\n        node.destroy_node()\\n        rclpy.shutdown()\\n\\n\\nif __name__ == &#x27;__main__&#x27;:\\n    main()\\n</code></pre>\\n    </div>\\n\\n    <div class=\\"code-breakdown-card\\">\\n      <h4 class=\\"code-breakdown-title\\">🔬 Core Code Deep Dive &amp; Operational Breakdown: SpeedModeSolutionServer Architecture</h4>\\n      <p class=\\"code-breakdown-intro\\">Key architectural takeaways from the Speed Mode &amp; Service Governor Solution:</p>\\n      <ul class=\\"code-breakdown-list\\">\\n        <li class=\\"code-breakdown-item\\"><strong>Defensive Parameter Sanitization:</strong> Physical actuators must never receive unvalidated parameters. The callback normalizes the string with <code>mode = request.mode_name.upper().strip()</code> and checks against permitted modes, gracefully rejecting unknown strings with <code>response.success = False</code> without crashing the node.</li>\\n        <li class=\\"code-breakdown-item\\"><strong>State Persistence across Service Invocations:</strong> The active speed factor is saved into <code>self.current_scale</code> and <code>self.active_mode</code>. Subsequent trajectory planner nodes or velocity limiter subscribers can query this state to cap <code>/cmd_vel</code> outputs.</li>\\n        <li class=\\"code-breakdown-item\\"><strong>Deterministic Response Contract:</strong> Every code path in the service callback returns the <code>response</code> object. Omitting the return statement causes a runtime DDS timeout exception in the requesting client.</li>\\n      </ul>\\n    </div>\\n  </div>\\n</details>\\n\\n<div class=\\"asset-handoff-card\\" style=\\"margin: 1.75rem 0 1rem 0; padding: 1.15rem 1.4rem; border-radius: 10px; background: rgba(16, 185, 129, 0.06); border: 1px solid rgba(16, 185, 129, 0.25); border-left: 4px solid #10b981;\\">\\n  <div style=\\"display: flex; align-items: center; gap: 0.5rem; margin-bottom: 0.5rem;\\">\\n    <span style=\\"font-size: 1.1rem;\\">📦</span>\\n    <strong style=\\"font-size: 0.95rem; color: #10b981; text-transform: uppercase; letter-spacing: 0.04em;\\">Asset Handoff &amp; Next Lesson Pipeline Bridge</strong>\\n  </div>\\n  <p style=\\"margin: 0 0 0.65rem 0; font-size: 0.88rem; color: var(--text-primary); line-height: 1.6;\\">\\n    You have implemented and tested the synchronous and asynchronous RPC service communication pattern with deadlock prevention, deploying an authoritative emergency stop service server and client.\\n  </p>\\n  <div style=\\"display: flex; flex-wrap: wrap; gap: 0.75rem; font-size: 0.82rem; font-family: var(--font-mono);\\">\\n    <span style=\\"background: var(--bg-surface); border: 1px solid var(--border-color); padding: 0.25rem 0.6rem; border-radius: 5px; color: var(--text-primary);\\">\\n      📁 <strong>Produced Artifact:</strong> <code>nexus_amr_basics/emergency_stop_server.py</code> &amp; <code>emergency_stop_client.py</code>\\n    </span>\\n    <span style=\\"background: var(--bg-surface); border: 1px solid var(--border-color); padding: 0.25rem 0.6rem; border-radius: 5px; color: var(--text-primary);\\">\\n      ➡️ <strong>Ingested By:</strong> Lesson 07 (Runtime Management &amp; Python Launch Files)\\n    </span>\\n  </div>\\n</div>\\n","quizzes":[{"id":"q_l1_07_1","prompt":"When should you choose a ROS 2 Service over a Topic in an Autonomous Mobile Robot (AMR) architecture?","options":["When transmitting continuous high-frequency sensor streams (e.g., LiDAR scans or IMU telemetry)","When a critical operation requires guaranteed bidirectional Request-Response acknowledgment (e.g., engaging emergency brakes or toggling speed modes)","When you need continuous progress feedback during a long-running navigation trajectory","When communicating between different physical machines without DDS middleware"],"correct":1,"explanation":"Topics use a unidirectional publish-subscribe pattern ideal for continuous streaming data. Services implement a bidirectional Request-Response pattern, making them the correct choice for operations that require guaranteed confirmation and status receipts from the server."},{"id":"q_l1_07_2","prompt":"In a ROS 2 Service definition file (.srv), what is the function of the three hyphens ('---') separator?","options":["It separates package build dependencies from node configuration parameters","It divides the service definition into the Request payload (top) and the Response payload (bottom)","It marks the boundary between synchronous and asynchronous execution threads","It indicates a comment section ignored by the ROS 2 IDL compiler"],"correct":1,"explanation":"A ROS 2 service definition (.srv) consists of two halves separated by '---': the top half specifies the Request structure sent by the client, and the bottom half specifies the Response structure returned by the server."}],"has_quiz":true,"next_id":"lesson_07","prev_id":"lesson_05","subtopics":[{"id":"1-overview-learning-objectives","title":"1. Overview &amp; Learning Objectives"},{"id":"2-decision-matrix-topics-vs-services-vs-actions","title":"2. Decision Matrix: Topics vs Services vs Actions"},{"id":"3-building-the-emergency-stop-safety-service-server","title":"3. Building the Emergency Stop Safety Service Server in Python"},{"id":"4-configuring-setuppy-building-testing-server-with-cli","title":"4. Configuring setup.py, Building &amp; Testing the Service Server with ROS 2 CLI"},{"id":"5-building-an-asynchronous-emergency-stop-client","title":"5. Building an Asynchronous Emergency Stop Client in Python"},{"id":"6-configuring-setuppy-verifying-client-server-pair","title":"6. Configuring setup.py &amp; Verifying the Client-Server Pair"},{"id":"7-hands-on-student-challenge","title":"7. Hands-on Student Challenge: Autonomous Mobile Robot Operational Speed Mode &amp; Zone Governor Service Server"}]},{"id":"lesson_07","num":7,"num_str":"07","title":"Runtime Management & Python Launch Files","slug":"lesson-09-runtime-management-python-launch-files","filename":"lesson_09.html","module":"Day 1: ROS 2 Foundations & Core Middleware","module_id":1,"duration":"45-60 min","focus":"ROS 2 Python Launch System, Multi-Node Subsystem Orchestration, Launch Arguments, Namespaces, Remappings, and Full-Stack AMR Launch","snapshot":[["Multi-Process Orchestration","Launch dozens of cooperating robot nodes simultaneously in a single deterministic execution pipeline."],["Launch Arguments & Overrides","Declare reconfigurable CLI flags with DeclareLaunchArgument and evaluate them lazily with LaunchConfiguration."],["Namespace Isolation","Enforce clean multi-robot fleet boundaries (e.g. /amr_01/) to prevent topic collisions across vehicles."],["Graph Remappings","Dynamically reconnect topic and service endpoints without editing underlying Python source code."]],"html_content":"<h2 id=\\"1-overview-learning-objectives\\">1. Overview &amp; Learning Objectives</h2>\\n<p>An autonomous robot rarely runs a single node. A standard AMR simultaneously executes hardware drivers, odometry estimators, SLAM filters, costmap generators, and safety watchdogs. Starting each node manually across 15 separate terminals is error-prone.</p>\\n<p>ROS 2 provides a programmatic <strong>Python Launch System</strong> to orchestrate multi-node lifecycles, inject YAML parameters, pass CLI arguments, and resolve topic name collisions.</p>\\n<p><div class=\\"learning-objectives-card\\">\\n  <div class=\\"learning-objectives-header\\">\\n    <div class=\\"objectives-icon-badge\\">\\n      <span style=\\"font-size: 1.15rem; line-height: 1;\\">🎯</span>\\n    </div>\\n    <div class=\\"objectives-title-group\\">\\n      <h3 class=\\"objectives-main-title\\">Learning Objectives &amp; Core Outcomes</h3>\\n      <span class=\\"objectives-subtitle\\">By the end of this lesson, you will be able to:</span>\\n    </div>\\n    <span class=\\"objectives-count-badge\\">5 CORE OUTCOMES</span>\\n  </div>\\n  <ul class=\\"learning-objectives-list\\">\\n    <li class=\\"learning-objective-item\\">\\n      <span class=\\"objective-num-badge\\">1</span>\\n      <span class=\\"objective-text\\">Understand the Python launch API: <code class=\\"inline-code\\">LaunchDescription</code>, <code class=\\"inline-code\\">Node</code>, <code class=\\"inline-code\\">DeclareLaunchArgument</code>, and <code class=\\"inline-code\\">LaunchConfiguration</code>.</span>\\n    </li>\\n    <li class=\\"learning-objective-item\\">\\n      <span class=\\"objective-num-badge\\">2</span>\\n      <span class=\\"objective-text\\">Master <strong>Topic Remappings</strong> to rewire node inputs and outputs without modifying source code.</span>\\n    </li>\\n    <li class=\\"learning-objective-item\\">\\n      <span class=\\"objective-num-badge\\">3</span>\\n      <span class=\\"objective-text\\">Use <strong>Namespaces</strong> to prevent topic collisions when deploying multiple robots.</span>\\n    </li>\\n    <li class=\\"learning-objective-item\\">\\n      <span class=\\"objective-num-badge\\">4</span>\\n      <span class=\\"objective-text\\">Compose nested launch systems using <code class=\\"inline-code\\">IncludeLaunchDescription</code>.</span>\\n    </li>\\n    <li class=\\"learning-objective-item\\">\\n      <span class=\\"objective-num-badge\\">5</span>\\n      <span class=\\"objective-text\\">Complete <strong>Project 2.2</strong>: Build a unified multi-node robotics supervisor launch script.</span>\\n    </li>\\n  </ul>\\n</div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"2-the-python-launch-architecture\\">2. The Python Launch Architecture</h2>\\n<p>In ROS 1, launch files were written in XML (<code class=\\"inline-code\\">.launch</code>). ROS 2 introduces pure <strong>Python Launch Files</strong> (<code class=\\"inline-code\\">.launch.py</code>), allowing dynamic conditionals, loop constructs, and Python logic.</p>\\n<p><img src=\\"assets/images/ros2_launch_architecture.svg\\" alt=\\"ROS 2 Python Launch System Architecture\\" class=\\"lesson-image\\" loading=\\"lazy\\" /></p>\\n<hr class=\\"divider\\">\\n<h2 id=\\"3-step-by-step-writing-an-amr-subsystem-launch-file\\">3. Step-by-Step: Writing an AMR Subsystem Launch File</h2>\\n<p>In previous lessons, we built modular robotic building blocks across topics, services, and parameters:\\n<ul>\\n  <li><strong>Lesson 05:</strong> Ultrasonic Range Publisher (<code class=\\"inline-code\\">ultrasonic_publisher</code>) and Collision Proximity Monitor (<code class=\\"inline-code\\">collision_monitor</code>).</li>\\n  <li><strong>Lesson 06:</strong> Emergency Stop Safety Service Server (<code class=\\"inline-code\\">emergency_stop_server</code>) and Client (<code class=\\"inline-code\\">emergency_stop_client</code>).</li>\\n  <li><strong>Bonus Lesson 17:</strong> Parameterized Controller Node (<code class=\\"inline-code\\">param_node_explained</code>) and declarative YAML parameter file (<code class=\\"inline-code\\">config/teleop_params.yaml</code>).</li>\\n</ul>\\nStarting each of these across separate terminal tabs is impossible during real-world robot deployment. A <strong>ROS 2 Python Launch File</strong> programmatically starts, configures, and monitors all cooperating nodes in a single execution pipeline.</p>\\n\\n<div class=\\"alert alert-info alert-briefing\\">\\n  <div class=\\"alert-icon\\">🚀</div>\\n  <div class=\\"alert-content\\">\\n    <div class=\\"alert-title\\">Robotics Flight Operations Mission Briefing: Multi-Node Subsystem Orchestration Launch File</div>\\n    <div class=\\"alert-body\\">\\n      <strong>Physical AMR Context &amp; Operational Challenge:</strong><br>\\n      A production Autonomous Mobile Robot never runs as an uncoordinated cluster of ad-hoc terminal processes. A functional robot requires multiple cooperating subsystems: sensor drivers, safety servers, and parameterized controllers. Launching them manually across separate terminal windows is error-prone and unscalable.\\n      <br><br>\\n      <strong>Architectural Role &amp; Why This Mechanism:</strong><br>\\n      <strong>ROS 2 Python Launch Files</strong> provide deterministic programmatic orchestration. They resolve install paths with <code class=\\"inline-code\\">get_package_share_directory</code>, inject external YAML configuration parameters, declare command-line arguments for operators, and enforce namespace boundaries.\\n      <br><br>\\n      <strong>Flight Objective &amp; Behavioral Outcome:</strong><br>\\n      Author a production-grade Python launch file that brings together the nodes built in Lessons 07 and 08: launching the Parameterized Controller with external YAML parameter injection and the Emergency Stop Service Server under a configurable robot namespace.\\n    </div>\\n  </div>\\n</div>\\n\\n<p>Create your launch file at <code class=\\"inline-code\\">~/ros2_ws/src/nexus_amr_basics/launch/amr_subsystem.launch.py</code> (or copy from reference <code class=\\"inline-code\\">~/ros2_ws_reference/src/nexus_amr_basics/launch/m01_l07_01_amr_subsystem.launch.py</code>):</p>\\n<div class=\\"code-container\\" data-language=\\"bash\\" style=\\"margin-bottom: 1.25rem;\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\">mkdir -p ~/ros2_ws/src/nexus_amr_basics/launch\\ncp ~/ros2_ws_reference/src/nexus_amr_basics/launch/m01_l07_01_amr_subsystem.launch.py ~/ros2_ws/src/nexus_amr_basics/launch/amr_subsystem.launch.py</code></pre>\\n</div>\\n\\n<p>Add the following implementation inside <code class=\\"inline-code\\">amr_subsystem.launch.py</code>:</p>\\n\\n<div class=\\"code-container ide-code-window\\" data-language=\\"python\\">\\n  <div class=\\"code-header\\">\\n    <div class=\\"code-dots\\"><span class=\\"dot red\\"></span><span class=\\"dot yellow\\"></span><span class=\\"dot green\\"></span></div>\\n    <span class=\\"code-filename\\">amr_subsystem.launch.py &mdash; AMR Subsystem Launch File</span>\\n    <button class=\\"copy-code-btn\\">📋 Copy</button>\\n  </div>\\n  <pre><code class=\\"language-python\\">#!/usr/bin/env python3\\n&quot;&quot;&quot;\\n================================================================================\\nNexus AMR Learning Hub - Level 1: Module 1 / Lesson 07\\nPackage: nexus_amr_basics\\nLaunch:  m01_l07_01_amr_subsystem.launch.py (alias: teleop_supervisor.launch.py)\\n================================================================================\\n\\nWHAT THIS LAUNCH FILE DOES:\\n---------------------------\\nOrchestrates the core AMR subsystem by launching:\\n1. The Parameterized Controller node (\`param_node_explained\`) created in Bonus Lesson 17,\\n   injecting YAML configuration parameters from \`teleop_params.yaml\`.\\n2. The Emergency Stop Service Server (\`emergency_stop_server\`) created in Lesson 06.\\n3. Exposes configurable runtime arguments for \`robot_namespace\` and \`config_file\`.\\n================================================================================\\n&quot;&quot;&quot;\\n\\nimport os\\nfrom ament_index_python.packages import get_package_share_directory\\nfrom launch import LaunchDescription\\nfrom launch.actions import DeclareLaunchArgument, LogInfo\\nfrom launch.substitutions import LaunchConfiguration\\nfrom launch_ros.actions import Node\\n\\n\\ndef generate_launch_description():\\n    &quot;&quot;&quot;\\n    Mandatory entry point for ROS 2 Python launch files.\\n    Returns a LaunchDescription defining the execution pipeline.\\n    &quot;&quot;&quot;\\n    # --------------------------------------------------------------------------\\n    # 1. RESOLVE CONFIGURATION PATHS VIA AMENT INDEX\\n    # --------------------------------------------------------------------------\\n    pkg_share = get_package_share_directory(&#x27;nexus_amr_basics&#x27;)\\n    default_config_path = os.path.join(pkg_share, &#x27;config&#x27;, &#x27;teleop_params.yaml&#x27;)\\n    if not os.path.exists(default_config_path):\\n        source_config = os.path.expanduser(&#x27;~/ros2_ws/src/nexus_amr_basics/config/teleop_params.yaml&#x27;)\\n        if os.path.exists(source_config):\\n            default_config_path = source_config\\n\\n    # --------------------------------------------------------------------------\\n    # 2. DECLARE RECONFIGURABLE LAUNCH ARGUMENTS\\n    # --------------------------------------------------------------------------\\n    config_file_arg = DeclareLaunchArgument(\\n        &#x27;config_file&#x27;,\\n        default_value=default_config_path,\\n        description=&#x27;Absolute path to the YAML parameters file (from Bonus Lesson 17)&#x27;\\n    )\\n\\n    namespace_arg = DeclareLaunchArgument(\\n        &#x27;robot_namespace&#x27;,\\n        default_value=&#x27;nexus_amr&#x27;,\\n        description=&#x27;Top-level namespace for multi-robot isolation&#x27;\\n    )\\n\\n    use_sim_time_arg = DeclareLaunchArgument(\\n        &#x27;use_sim_time&#x27;,\\n        default_value=&#x27;false&#x27;,\\n        description=&#x27;Synchronize clock with Gazebo simulator /clock&#x27;\\n    )\\n\\n    # --------------------------------------------------------------------------\\n    # 3. LAUNCH ACTION 1: PARAMETERIZED CONTROLLER NODE (From Bonus Lesson 17)\\n    # --------------------------------------------------------------------------\\n    param_controller_node = Node(\\n        package=&#x27;nexus_amr_basics&#x27;,\\n        executable=&#x27;param_node_explained&#x27;,\\n        name=&#x27;parameterized_controller&#x27;,\\n        namespace=LaunchConfiguration(&#x27;robot_namespace&#x27;),\\n        output=&#x27;screen&#x27;,\\n        emulate_tty=True,\\n        parameters=[\\n            LaunchConfiguration(&#x27;config_file&#x27;),\\n            {&#x27;use_sim_time&#x27;: LaunchConfiguration(&#x27;use_sim_time&#x27;)}\\n        ],\\n        remappings=[\\n            (&#x27;/cmd_vel&#x27;, &#x27;cmd_vel_filtered&#x27;),\\n        ]\\n    )\\n\\n    # --------------------------------------------------------------------------\\n    # 4. LAUNCH ACTION 2: EMERGENCY STOP SAFETY SERVICE SERVER (From Lesson 06)\\n    # --------------------------------------------------------------------------\\n    estop_server_node = Node(\\n        package=&#x27;nexus_amr_basics&#x27;,\\n        executable=&#x27;emergency_stop_server&#x27;,\\n        name=&#x27;emergency_stop_server&#x27;,\\n        namespace=LaunchConfiguration(&#x27;robot_namespace&#x27;),\\n        output=&#x27;screen&#x27;,\\n        emulate_tty=True,\\n        parameters=[\\n            {&#x27;use_sim_time&#x27;: LaunchConfiguration(&#x27;use_sim_time&#x27;)}\\n        ]\\n    )\\n\\n    # --------------------------------------------------------------------------\\n    # 5. ASSEMBLE LAUNCH DESCRIPTION PIPELINE\\n    # --------------------------------------------------------------------------\\n    return LaunchDescription([\\n        config_file_arg,\\n        namespace_arg,\\n        use_sim_time_arg,\\n        LogInfo(msg=[&#x27;[Launch] Starting AMR Subsystem under namespace: &#x27;, LaunchConfiguration(&#x27;robot_namespace&#x27;)]),\\n        LogInfo(msg=[&#x27;[Launch] Injecting parameters from: &#x27;, LaunchConfiguration(&#x27;config_file&#x27;)]),\\n        param_controller_node,\\n        estop_server_node\\n    ])\\n</code></pre>\\n</div>\\n\\n<h3 id=\\"core-logic-breakdown-what-we-are-trying-to-achieve-why\\">Core Logic Breakdown: 4 Architectural Phases</h3>\\n<p>The <code class=\\"inline-code\\">amr_subsystem.launch.py</code> script is structured into four deterministic stages:</p>\\n\\n<div class=\\"info-grid\\" style=\\"grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 1.25rem; margin: 1.5rem 0;\\">\\n  <div class=\\"info-card\\">\\n    <div style=\\"display: flex; align-items: center; gap: 0.6rem; margin-bottom: 0.6rem;\\">\\n      <span style=\\"font-size: 1.25rem;\\">📁</span>\\n      <h4 style=\\"margin: 0; font-size: 0.98rem; font-weight: 700;\\">Phase 1: Dynamic Path Resolution</h4>\\n    </div>\\n    <p style=\\"font-size: 0.88rem; line-height: 1.55; margin: 0; color: var(--text-secondary);\\">\\n      Uses <code class=\\"inline-code\\">get_package_share_directory('nexus_amr_basics')</code> via the Ament Index. Eliminates hardcoded paths, ensuring config files (<code class=\\"inline-code\\">teleop_params.yaml</code>) resolve portably across local machines, Docker containers, and physical AMR fleets.\\n    </p>\\n  </div>\\n\\n  <div class=\\"info-card\\">\\n    <div style=\\"display: flex; align-items: center; gap: 0.6rem; margin-bottom: 0.6rem;\\">\\n      <span style=\\"font-size: 1.25rem;\\">⚙️</span>\\n      <h4 style=\\"margin: 0; font-size: 0.98rem; font-weight: 700;\\">Phase 2: Reconfigurable Arguments</h4>\\n    </div>\\n    <p style=\\"font-size: 0.88rem; line-height: 1.55; margin: 0; color: var(--text-secondary);\\">\\n      Declares CLI parameters (<code class=\\"inline-code\\">DeclareLaunchArgument</code>) for <code class=\\"inline-code\\">robot_namespace</code>, <code class=\\"inline-code\\">config_file</code>, and <code class=\\"inline-code\\">use_sim_time</code>. Operators can dynamically override configurations without editing Python code.\\n    </p>\\n  </div>\\n\\n  <div class=\\"info-card\\">\\n    <div style=\\"display: flex; align-items: center; gap: 0.6rem; margin-bottom: 0.6rem;\\">\\n      <span style=\\"font-size: 1.25rem;\\">🤖</span>\\n      <h4 style=\\"margin: 0; font-size: 0.98rem; font-weight: 700;\\">Phase 3: Managed Subsystem Nodes</h4>\\n    </div>\\n    <p style=\\"font-size: 0.88rem; line-height: 1.55; margin: 0; color: var(--text-secondary);\\">\\n      Instantiates the Parameterized Controller (<code class=\\"inline-code\\">param_node_explained</code>) with YAML parameter injection &amp; <code class=\\"inline-code\\">cmd_vel</code> remapping, alongside the Emergency Stop Safety Server (<code class=\\"inline-code\\">emergency_stop_server</code>) under the declared namespace.\\n    </p>\\n  </div>\\n\\n  <div class=\\"info-card\\">\\n    <div style=\\"display: flex; align-items: center; gap: 0.6rem; margin-bottom: 0.6rem;\\">\\n      <span style=\\"font-size: 1.25rem;\\">🚀</span>\\n      <h4 style=\\"margin: 0; font-size: 0.98rem; font-weight: 700;\\">Phase 4: Launch Pipeline Assembly</h4>\\n    </div>\\n    <p style=\\"font-size: 0.88rem; line-height: 1.55; margin: 0; color: var(--text-secondary);\\">\\n      Packages arguments, diagnostic <code class=\\"inline-code\\">LogInfo</code> status banners, and node processes into a deterministic <code class=\\"inline-code\\">LaunchDescription</code> object returned to the ROS 2 launch runner.\\n    </p>\\n  </div>\\n</div>\\n\\n<div class=\\"alert alert-warning\\" style=\\"margin-top: 1.5rem;\\">\\n  <div class=\\"alert-icon\\">💡</div>\\n  <div class=\\"alert-content\\">\\n    <div class=\\"alert-title\\">Robotics Architecture Insight: Service Servers vs. Service Clients in Launch Files</div>\\n    <div class=\\"alert-body\\">\\n      <strong>Why does our launch file start the Service Server (<code class=\\"inline-code\\">emergency_stop_server</code>) but NOT the Client (<code class=\\"inline-code\\">emergency_stop_client</code>)?</strong>\\n      <ul style=\\"margin: 0.75rem 0 0 0; padding-left: 1.2rem; line-height: 1.6;\\">\\n        <li><strong>Service Servers are Long-Lived Daemons:</strong> A service server must be running continuously in the background from boot. It advertises an RPC endpoint on DDS (<code class=\\"inline-code\\">/nexus_amr/robot/emergency_stop</code>) and stands on standby to execute safety stops whenever an emergency occurs.</li>\\n        <li><strong>Service Clients are Event-Driven &amp; Ephemeral:</strong> A client performs a targeted, request-response call. If launched concurrently with the server inside a flat launch file, it would fire before DDS discovery completes, find no active service, fail, and terminate.</li>\\n        <li><strong>How Clients are Used in Production Fleets:</strong>\\n          <ol style=\\"margin-top: 0.4rem; padding-left: 1.2rem; line-height: 1.6;\\">\\n            <li><strong>Manual / Supervisory Trigger:</strong> Human operators or fleet dashboards trigger the client on demand from the CLI (<code class=\\"inline-code\\">ros2 service call</code>) to perform safety stop drills.</li>\\n            <li><strong>Autonomous Event Integration:</strong> Higher-level supervisor nodes (like the Collision Monitor or Nav2 Behavior Trees) instantiate service clients internally and call them when safety hazards occur.</li>\\n            <li><strong>Launch Event Handlers:</strong> If a launch file <em>must</em> execute a test client during commissioning, ROS 2 provides <code class=\\"inline-code\\">RegisterEventHandler(OnProcessStart(...))</code> or <code class=\\"inline-code\\">TimerAction</code> to delay client execution until the server is spinning.</li>\\n          </ol>\\n        </li>\\n      </ul>\\n    </div>\\n  </div>\\n</div>\\n<hr class=\\"divider\\">\\n\\n<h2 id=\\"4-key-launch-actions-syntax-breakdown\\">4. Key Launch Actions &amp; Syntax Breakdown</h2>\\n<p>ROS 2 Python launch files construct declarative execution graphs using specialized action and substitution classes. The matrix below serves as your core syntax reference for production AMR launch scripting:</p>\\n\\n<div class=\\"table-responsive\\"><table>\\n<thead>\\n<tr>\\n  <th style=\\"width: 26%;\\">Launch Action / API</th>\\n  <th style=\\"width: 28%;\\">Module Import</th>\\n  <th style=\\"width: 46%;\\">Core Role &amp; Concrete Syntax</th>\\n</tr>\\n</thead>\\n<tbody>\\n<tr>\\n  <td><code class=\\"inline-code\\">Node</code></td>\\n  <td><code class=\\"inline-code\\">launch_ros.actions</code></td>\\n  <td>\\n    <strong>Process Spawner:</strong> Launches an executable with isolation &amp; configuration.<br>\\n    <code class=\\"inline-code\\">Node(package='pkg', executable='exe', name='node', namespace=ns, parameters=[...], remappings=[...], output='screen', emulate_tty=True)</code>\\n  </td>\\n</tr>\\n<tr>\\n  <td><code class=\\"inline-code\\">DeclareLaunchArgument</code></td>\\n  <td><code class=\\"inline-code\\">launch.actions</code></td>\\n  <td>\\n    <strong>CLI Interface:</strong> Exposes configurable runtime flags to operators.<br>\\n    <code class=\\"inline-code\\">DeclareLaunchArgument('arg_name', default_value='val', description='Help text')</code>\\n  </td>\\n</tr>\\n<tr>\\n  <td><code class=\\"inline-code\\">LaunchConfiguration</code></td>\\n  <td><code class=\\"inline-code\\">launch.substitutions</code></td>\\n  <td>\\n    <strong>Runtime Value Substitution:</strong> Retrieves operator argument values at launch time.<br>\\n    <code class=\\"inline-code\\">namespace=LaunchConfiguration('robot_namespace')</code>\\n  </td>\\n</tr>\\n<tr>\\n  <td><code class=\\"inline-code\\">get_package_share_directory</code></td>\\n  <td><code class=\\"inline-code\\">ament_index_python.packages</code></td>\\n  <td>\\n    <strong>Portable Asset Lookup:</strong> Dynamically resolves install path for configs &amp; URDFs.<br>\\n    <code class=\\"inline-code\\">os.path.join(get_package_share_directory('pkg'), 'config', 'params.yaml')</code>\\n  </td>\\n</tr>\\n<tr>\\n  <td><code class=\\"inline-code\\">LogInfo</code></td>\\n  <td><code class=\\"inline-code\\">launch.actions</code></td>\\n  <td>\\n    <strong>Diagnostic Banners:</strong> Emits formatted status messages to stdout during launch.<br>\\n    <code class=\\"inline-code\\">LogInfo(msg=['[Launch] Starting subsystem: ', LaunchConfiguration('arg')])</code>\\n  </td>\\n</tr>\\n<tr>\\n  <td><code class=\\"inline-code\\">IncludeLaunchDescription</code></td>\\n  <td><code class=\\"inline-code\\">launch.actions</code></td>\\n  <td>\\n    <strong>Launch Composition:</strong> Imports and executes modular sub-launch files.<br>\\n    <code class=\\"inline-code\\">IncludeLaunchDescription(PythonLaunchDescriptionSource(path), launch_arguments={...}.items())</code>\\n  </td>\\n</tr>\\n</tbody>\\n</table></div>\\n\\n<div class=\\"alert alert-info\\" style=\\"margin-top: 1.5rem;\\">\\n  <div class=\\"alert-icon\\">💡</div>\\n  <div class=\\"alert-content\\">\\n    <div class=\\"alert-title\\">Critical Concept: Launch-Time Evaluation vs. Runtime Execution</div>\\n    <div class=\\"alert-body\\">\\n      A common beginner pitfall in ROS 2 is treating <code class=\\"inline-code\\">LaunchConfiguration('arg')</code> as a standard Python string. In ROS 2, Python launch scripts are executed once to construct the declarative <code class=\\"inline-code\\">LaunchDescription</code> object. The actual values inside <code class=\\"inline-code\\">LaunchConfiguration</code> are deferred substitutions evaluated later by the ROS 2 launch runner. If you need dynamic string concatenation or conditional branching based on an argument, use <code class=\\"inline-code\\">PythonExpression</code> or wrap your logic in an <code class=\\"inline-code\\">OpaqueFunction</code>.\\n    </div>\\n  </div>\\n</div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"5-composition-including-other-launch-files\\">5. Composition: Including Other Launch Files</h2>\\n<p>In advanced systems, top-level launch files include sub-launch files using <code class=\\"inline-code\\">IncludeLaunchDescription</code>:</p>\\n<p><div class=\\"code-container\\" data-language=\\"python\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">python</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-python\\">from launch.actions import IncludeLaunchDescription\\nfrom launch.launch_description_sources import PythonLaunchDescriptionSource\\n\\n# Include robot state publisher from nexus_amr_description\\nrsp_launch = IncludeLaunchDescription(\\n    PythonLaunchDescriptionSource(\\n        os.path.join(get_package_share_directory(&#x27;nexus_amr_description&#x27;), &#x27;launch&#x27;, &#x27;rsp.launch.py&#x27;)\\n    ),\\n    launch_arguments={&#x27;use_sim_time&#x27;: &#x27;true&#x27;}.items()\\n)\\n</code></pre>\\n</div>\\n</p>\\n<hr class=\\"divider\\">\\n<h3 id=\\"51-registering-launch-files-in-setuppy\\">5.1 Registering Launch Files in <code class=\\"inline-code\\">setup.py</code></h3>\\n<p>In ROS 2 Python packages, launch files stored in <code class=\\"inline-code\\">launch/</code> will <strong>not</strong> be found by <code class=\\"inline-code\\">ros2 launch &lt;pkg&gt; &lt;file&gt;</code> unless they are registered in the <code class=\\"inline-code\\">data_files</code> manifest of <code class=\\"inline-code\\">setup.py</code>:</p>\\n<div class=\\"file-edit-instruction-card\\">\\n  <div class=\\"file-edit-header\\">\\n    <div class=\\"file-edit-header-left\\">\\n      <span>📝 Step-by-Step File Modification Guide</span>\\n    </div>\\n    <span class=\\"file-edit-badge\\">~/ros2_ws/src/nexus_amr_basics/setup.py</span>\\n  </div>\\n  <div class=\\"file-edit-body\\">\\n    <div class=\\"file-edit-step\\">\\n      <div class=\\"file-edit-step-title\\">\\n        <span class=\\"step-num-pill\\">Step 1</span>\\n        <span>Open the Target File</span>\\n      </div>\\n      <p class=\\"step-description\\">Open <code class=\\"inline-code\\">~/ros2_ws/src/nexus_amr_basics/setup.py</code> in your editor.</p>\\n    </div>\\n\\n    <div class=\\"file-edit-step\\">\\n      <div class=\\"file-edit-step-title\\">\\n        <span class=\\"step-num-pill\\">Step 2</span>\\n        <span>Locate Insertion Point &amp; Add Lines</span>\\n      </div>\\n      <p class=\\"step-description\\">Add <code class=\\"inline-code\\">import os</code> and <code class=\\"inline-code\\">from glob import glob</code> at the top, then install the <code class=\\"inline-code\\">launch/</code> and <code class=\\"inline-code\\">config/</code> directories inside <code class=\\"inline-code\\">data_files</code>:</p>\\n      <div class=\\"code-container\\" data-language=\\"python\\">\\n        <div class=\\"code-header\\"><span class=\\"code-lang-tag\\">python</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n        <pre><code class=\\"language-python\\"># 1. Ensure required path and glob imports are present at the top of setup.py:\\nimport os\\nfrom glob import glob\\n\\n# 2. Update the data_files list inside setup(...) to install launch and config files:\\n    data_files=[\\n        ('share/ament_index/resource_index/packages', ['resource/' + package_name]),\\n        ('share/' + package_name, ['package.xml']),\\n        # Install all launch files to share/nexus_amr_basics/launch:\\n        (os.path.join('share', package_name, 'launch'), glob('launch/*.launch.py')),\\n        # Install all config YAML files to share/nexus_amr_basics/config:\\n        (os.path.join('share', package_name, 'config'), glob('config/*.yaml')),\\n    ],</code></pre>\\n      </div>\\n    </div>\\n\\n    <div class=\\"file-edit-step\\">\\n      <div class=\\"file-edit-step-title\\">\\n        <span class=\\"step-num-pill\\">Step 3</span>\\n        <span>Verify the Full File After Editing</span>\\n      </div>\\n      <p class=\\"step-description\\">Self-check your file against the complete reference below to confirm indentation, closing brackets, and commas:</p>\\n      <details class=\\"file-edit-dropdown\\">\\n        <summary class=\\"file-edit-summary\\">\\n          <span>📄 View Complete setup.py with Launch Files Configured</span>\\n          <span class=\\"file-edit-toggle-icon\\">▶</span>\\n        </summary>\\n        <div class=\\"file-edit-dropdown-content\\">\\n          <div class=\\"code-container\\" data-language=\\"python\\">\\n            <div class=\\"code-header\\"><span class=\\"code-lang-tag\\">python</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n            <pre><code class=\\"language-python\\">from setuptools import find_packages, setup\\nimport os\\nfrom glob import glob\\n\\npackage_name = &#x27;nexus_amr_basics&#x27;\\n\\nsetup(\\n    name=package_name,\\n    version=&#x27;1.0.0&#x27;,\\n    packages=find_packages(exclude=[&#x27;test&#x27;]),\\n    data_files=[\\n        (&#x27;share/ament_index/resource_index/packages&#x27;, [&#x27;resource/&#x27; + package_name]),\\n        (&#x27;share/&#x27; + package_name, [&#x27;package.xml&#x27;]),\\n        (os.path.join(&#x27;share&#x27;, package_name, &#x27;launch&#x27;), glob(&#x27;launch/*.launch.py&#x27;)),\\n        (os.path.join(&#x27;share&#x27;, package_name, &#x27;config&#x27;), glob(&#x27;config/*.yaml&#x27;)),\\n    ],\\n    install_requires=[&#x27;setuptools&#x27;],\\n    zip_safe=True,\\n    maintainer=&#x27;Nexus AMR Academy&#x27;,\\n    maintainer_email=&#x27;instructor@botforge.io&#x27;,\\n    description=&#x27;ROS 2 Day 1: Topics, Services, Parameters, and Launch Files&#x27;,\\n    license=&#x27;Apache-2.0&#x27;,\\n    entry_points={\\n        &#x27;console_scripts&#x27;: [\\n            &#x27;talker = nexus_amr_basics.talker:main&#x27;,\\n            &#x27;listener = nexus_amr_basics.listener:main&#x27;,\\n        ],\\n    },\\n)</code></pre>\\n          </div>\\n        </div>\\n      </details>\\n    </div>\\n  </div>\\n</div>\\n\\n<h2 id=\\"6-execution-cli-overrides\\">6. Execution &amp; CLI Overrides</h2>\\n<p>Run your launch file:</p>\\n<div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\">ros2 launch nexus_amr_basics amr_subsystem.launch.py robot_namespace:=nexus_amr\\n</code></pre>\\n</div>\\n<p>In a separate terminal, verify the running nodes, services, and parameters under the isolated namespace:</p>\\n<div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\"># 1. Inspect running nodes in the active graph:\\nros2 node list\\n# Expected Output:\\n# /nexus_amr/emergency_stop_server\\n# /nexus_amr/parameterized_controller\\n\\n# 2. Verify namespaced service interface:\\nros2 service list | grep emergency\\n# /nexus_amr/robot/emergency_stop\\n\\n# 3. Verify YAML parameter loading into the controller node:\\nros2 param get /nexus_amr/parameterized_controller max_linear_speed\\n# Double value is: 0.75\\n\\n# 4. Trigger the Emergency Stop using the Service Client Script from Lesson 06:\\nros2 run nexus_amr_basics emergency_stop_client --ros-args -r __ns:=/nexus_amr\\n# [INFO] [emergency_stop_client]: Service available. Sending E-STOP request: True...\\n# [INFO] [emergency_stop_client]: E-STOP confirmed! Response: AMR EMERGENCY STOP ENGAGED! Motors killed.\\n\\n# 5. Alternatively, trigger directly via the ROS 2 Service CLI:\\nros2 service call /nexus_amr/robot/emergency_stop std_srvs/srv/SetBool \\"{data: true}\\"\\n</code></pre>\\n</div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"7-hands-on-student-challenge-full-stack-amr-subsystem-launch\\">7. Hands-on Student Challenge: Full-Stack AMR Subsystem Launch Orchestrator</h2>\\n<p>In Section 3, you orchestrated the Service Server (<code class=\\"inline-code\\">emergency_stop_server</code>) and Parameterized Controller (<code class=\\"inline-code\\">param_node_explained</code>) with YAML parameter injection.</p>\\n<p>Now, your mission is to construct the <strong>COMPLETE Full-Stack AMR Launch File</strong> by integrating the Pub/Sub nodes from Lesson 05!</p>\\n\\n<div class=\\"alert alert-tip\\">\\n  <div class=\\"alert-title\\">🎯 Mission Requirements &amp; Checklist</div>\\n  <ol>\\n    <li><strong>TODO 1:</strong> Declare launch argument <code class=\\"inline-code\\">robot_namespace</code> (default: <code class=\\"inline-code\\">'amr_alpha'</code>).</li>\\n    <li><strong>TODO 2:</strong> Declare launch argument <code class=\\"inline-code\\">config_file</code> (default: path to <code class=\\"inline-code\\">config/teleop_params.yaml</code>).</li>\\n    <li><strong>TODO 3:</strong> Add Node action for <code class=\\"inline-code\\">ultrasonic_publisher</code> (Lesson 05 - Range Publisher) under the robot namespace.</li>\\n    <li><strong>TODO 4:</strong> Add Node action for <code class=\\"inline-code\\">collision_monitor</code> (Lesson 05 - Collision Proximity Monitor) under the robot namespace.</li>\\n    <li><strong>TODO 5:</strong> Add Node action for <code class=\\"inline-code\\">emergency_stop_server</code> (Lesson 06 - Emergency Stop Service Server) under the robot namespace.</li>\\n    <li><strong>TODO 6:</strong> Add Node action for <code class=\\"inline-code\\">parameterized_controller</code> (<code class=\\"inline-code\\">param_node_explained</code> from Bonus Lesson 17) loading parameters from <code class=\\"inline-code\\">config_file</code> under the robot namespace.</li>\\n    <li><strong>TODO 7:</strong> Assemble and return the complete <code class=\\"inline-code\\">LaunchDescription</code> object containing all arguments and the 4 nodes.</li>\\n  </ol>\\n</div>\\n\\n<h3 id=\\"71-starter-template\\">7.1 Starter Template: <code class=\\"inline-code\\">task_fleet_launch.py</code></h3>\\n<p>Copy the starter template from the reference workspace into your active student workspace:</p>\\n<div class=\\"code-container\\" data-language=\\"bash\\" style=\\"margin-bottom: 1.25rem;\\">\\n  <div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n  <pre><code class=\\"language-bash\\">mkdir -p ~/ros2_ws/src/nexus_amr_basics/launch\\ncp ~/ros2_ws_reference/src/nexus_amr_basics/launch/m01_l07_02_task_fleet_launch.py ~/ros2_ws/src/nexus_amr_basics/launch/task_fleet_launch.py</code></pre>\\n</div>\\n\\n<p>Open <code class=\\"inline-code\\">task_fleet_launch.py</code> and complete the marked <code class=\\"inline-code\\">TODO</code> targets:</p>\\n\\n<div class=\\"code-container ide-code-window\\" data-language=\\"python\\">\\n  <div class=\\"code-header\\">\\n    <div class=\\"code-dots\\"><span class=\\"dot red\\"></span><span class=\\"dot yellow\\"></span><span class=\\"dot green\\"></span></div>\\n    <span class=\\"code-filename\\">task_fleet_launch.py &mdash; Full-Stack AMR Launch Starter</span>\\n    <button class=\\"copy-code-btn\\">📋 Copy</button>\\n  </div>\\n  <pre><code class=\\"language-python\\">#!/usr/bin/env python3\\n&quot;&quot;&quot;\\n================================================================================\\nNexus AMR Learning Hub - Level 1: Module 1 / Lesson 07 Task\\nPackage: nexus_amr_basics\\nLaunch:  m01_l07_02_task_fleet_launch.py\\n================================================================================\\n\\nEXERCISE OVERVIEW:\\n------------------\\nYour mission is to construct a production-ready Python Launch file that brings up\\nthe COMPLETE Autonomous Mobile Robot (AMR) core subsystem.\\n\\nYou will integrate everything you have built across Modules 1 &amp; 2:\\n1. Ultrasonic Sensor Publisher (Lesson 05 - Topics / Pub)\\n2. Collision Proximity Monitor (Lesson 05 - Topics / Sub)\\n3. Emergency Stop Service Server (Lesson 06 - Services)\\n4. Parameterized Controller Node (Bonus Lesson 17 - Parameters &amp; YAML)\\n\\nOBJECTIVES:\\n-----------\\nTODO 1: Declare a launch argument &#x27;robot_namespace&#x27; (default: &#x27;amr_alpha&#x27;).\\nTODO 2: Declare a launch argument &#x27;config_file&#x27; pointing to &#x27;config/teleop_params.yaml&#x27;.\\nTODO 3: Instantiate Node &#x27;ultrasonic_publisher&#x27; under the robot namespace.\\nTODO 4: Instantiate Node &#x27;collision_monitor&#x27; under the robot namespace.\\nTODO 5: Instantiate Node &#x27;emergency_stop_server&#x27; under the robot namespace.\\nTODO 6: Instantiate Node &#x27;parameterized_controller&#x27; using executable &#x27;param_node_explained&#x27;,\\n        injecting YAML parameters from &#x27;config_file&#x27; under the robot namespace.\\nTODO 7: Assemble and return a LaunchDescription object containing all arguments and nodes.\\n================================================================================\\n&quot;&quot;&quot;\\n\\nimport os\\nfrom ament_index_python.packages import get_package_share_directory\\nfrom launch import LaunchDescription\\nfrom launch.actions import DeclareLaunchArgument, LogInfo\\nfrom launch.substitutions import LaunchConfiguration\\nfrom launch_ros.actions import Node\\n\\n\\ndef generate_launch_description():\\n    pkg_share = get_package_share_directory(&#x27;nexus_amr_basics&#x27;)\\n    default_config = os.path.join(pkg_share, &#x27;config&#x27;, &#x27;teleop_params.yaml&#x27;)\\n    if not os.path.exists(default_config):\\n        source_config = os.path.expanduser(&#x27;~/ros2_ws/src/nexus_amr_basics/config/teleop_params.yaml&#x27;)\\n        if os.path.exists(source_config):\\n            default_config = source_config\\n\\n    # ==========================================================================\\n    # TODO 1: Declare Launch Argument &#x27;robot_namespace&#x27; (default: &#x27;amr_alpha&#x27;)\\n    # ==========================================================================\\n    # ---&gt; YOUR CODE HERE &lt;---\\n    namespace_arg = DeclareLaunchArgument(\\n        &#x27;robot_namespace&#x27;,\\n        default_value=&#x27;amr_alpha&#x27;,\\n        description=&#x27;Robot top-level namespace&#x27;\\n    )\\n\\n    # ==========================================================================\\n    # TODO 2: Declare Launch Argument &#x27;config_file&#x27; (default: default_config)\\n    # ==========================================================================\\n    # ---&gt; YOUR CODE HERE &lt;---\\n    config_arg = DeclareLaunchArgument(\\n        &#x27;config_file&#x27;,\\n        default_value=default_config,\\n        description=&#x27;Path to YAML parameters configuration&#x27;\\n    )\\n\\n    robot_ns = LaunchConfiguration(&#x27;robot_namespace&#x27;)\\n    config_file = LaunchConfiguration(&#x27;config_file&#x27;)\\n\\n    # ==========================================================================\\n    # TODO 3: Add Ultrasonic Sensor Publisher Node (From Lesson 05)\\n    # - package: &#x27;nexus_amr_basics&#x27;\\n    # - executable: &#x27;ultrasonic_publisher&#x27;\\n    # - name: &#x27;ultrasonic_publisher&#x27;\\n    # - namespace: robot_ns\\n    # - output: &#x27;screen&#x27;\\n    # ==========================================================================\\n    # ---&gt; YOUR CODE HERE &lt;---\\n\\n    # ==========================================================================\\n    # TODO 4: Add Collision Monitor Subscriber Node (From Lesson 05)\\n    # - package: &#x27;nexus_amr_basics&#x27;\\n    # - executable: &#x27;collision_monitor&#x27;\\n    # - name: &#x27;collision_monitor&#x27;\\n    # - namespace: robot_ns\\n    # - output: &#x27;screen&#x27;\\n    # ==========================================================================\\n    # ---&gt; YOUR CODE HERE &lt;---\\n\\n    # ==========================================================================\\n    # TODO 5: Add Emergency Stop Service Server Node (From Lesson 06)\\n    # - package: &#x27;nexus_amr_basics&#x27;\\n    # - executable: &#x27;emergency_stop_server&#x27;\\n    # - name: &#x27;emergency_stop_server&#x27;\\n    # - namespace: robot_ns\\n    # - output: &#x27;screen&#x27;\\n    # ==========================================================================\\n    # ---&gt; YOUR CODE HERE &lt;---\\n\\n    # ==========================================================================\\n    # TODO 6: Add Parameterized Controller Node (From Bonus Lesson 17)\\n    # - package: &#x27;nexus_amr_basics&#x27;\\n    # - executable: &#x27;param_node_explained&#x27;\\n    # - name: &#x27;parameterized_controller&#x27;\\n    # - namespace: robot_ns\\n    # - parameters: [config_file]\\n    # - output: &#x27;screen&#x27;\\n    # ==========================================================================\\n    # ---&gt; YOUR CODE HERE &lt;---\\n\\n    # ==========================================================================\\n    # TODO 7: Assemble and Return LaunchDescription\\n    # ==========================================================================\\n    # ---&gt; YOUR CODE HERE &lt;---\\n    return LaunchDescription([\\n        namespace_arg,\\n        config_arg,\\n        LogInfo(msg=[&#x27;Launching Full AMR Stack for robot: &#x27;, robot_ns]),\\n        # Add your 4 nodes here!\\n    ])\\n</code></pre>\\n</div>\\n\\n<h3 id=\\"72-verification--execution\\">7.2 Build, Launch &amp; Verify</h3>\\n<p>Build your workspace and launch your completed full-stack AMR launch file:</p>\\n\\n<div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\">cd ~/ros2_ws\\ncolcon build --symlink-install --packages-select nexus_amr_basics\\nsource install/setup.bash\\n\\n# Launch the entire robot subsystem with custom namespace:\\nros2 launch nexus_amr_basics task_fleet_launch.py robot_namespace:=amr_alpha\\n</code></pre>\\n</div>\\n\\n<div class=\\"alert-callout alert-tip\\">\\n  <div class=\\"alert-icon\\">⚡</div>\\n  <div class=\\"alert-body\\">\\n    <strong>Expected Multi-Node Terminal Output:</strong><br>\\n    Notice how all four subsystem nodes start up simultaneously under the namespace <code class=\\"inline-code\\">amr_alpha</code>:<br>\\n    <pre style=\\"background: var(--bg-surface); padding: 0.75rem; border-radius: 6px; margin-top: 0.5rem; font-family: var(--font-mono); font-size: 0.85rem; color: #10b981;\\">[INFO] [launch]: Starting Full AMR Stack for robot: amr_alpha\\n[INFO] [ultrasonic_publisher-1]: process started with pid [133531]\\n[INFO] [collision_monitor-2]: process started with pid [133532]\\n[INFO] [emergency_stop_server-3]: process started with pid [133533]\\n[INFO] [param_node_explained-4]: process started with pid [133534]\\n[emergency_stop_server-3] [INFO] [amr_alpha.emergency_stop_server]: EmergencyStopServer initialized. Ready to receive safety commands on \\"/robot/emergency_stop\\"...\\n[param_node_explained-4] [INFO] [amr_alpha.parameterized_controller]: Param Node Initialized | ID: 'nexus-wh-01' | Max Speed: 0.75 m/s | Brake: True | Rate: 20 Hz\\n[collision_monitor-2] [INFO] [amr_alpha.collision_monitor]: CollisionSafetySubscriber initialized. Monitoring \\"/sensor/ultrasonic_front\\"...\\n[ultrasonic_publisher-1] [INFO] [amr_alpha.ultrasonic_publisher]: UltrasonicSensorPublisher initialized. Broadcasting Range telemetry at 10 Hz...</pre>\\n  </div>\\n</div>\\n\\n<details class=\\"solution-details\\">\\n  <summary class=\\"solution-summary\\">\\n    <span>💡 View Complete Solution (<code class=\\"inline-code\\">m01_l07_03_solution_fleet_launch.py</code>)</span>\\n    <span class=\\"solution-toggle-icon\\">▶</span>\\n  </summary>\\n  <div class=\\"solution-body\\">\\n    <p>Reference file: <code class=\\"inline-code\\">ros2_ws_reference/src/nexus_amr_basics/launch/m01_l07_03_solution_fleet_launch.py</code></p>\\n    <div class=\\"code-container ide-code-window\\" data-language=\\"python\\">\\n      <div class=\\"code-header\\">\\n        <div class=\\"code-dots\\"><span class=\\"dot red\\"></span><span class=\\"dot yellow\\"></span><span class=\\"dot green\\"></span></div>\\n        <span class=\\"code-filename\\">solution_fleet_launch.py &mdash; Complete Full-Stack AMR Launch Solution</span>\\n        <button class=\\"copy-code-btn\\">📋 Copy</button>\\n      </div>\\n      <pre><code class=\\"language-python\\">#!/usr/bin/env python3\\n&quot;&quot;&quot;\\n================================================================================\\nNexus AMR Learning Hub - Level 1: Module 1 / Lesson 07 Solution\\nPackage: nexus_amr_basics\\nLaunch:  m01_l07_03_solution_fleet_launch.py\\n================================================================================\\n\\nCOMPLETE SOLUTION:\\n------------------\\nLaunches the full AMR core subsystem:\\n1. Ultrasonic Sensor Publisher (Lesson 05 - Pub)\\n2. Collision Monitor (Lesson 05 - Sub)\\n3. Emergency Stop Service Server (Lesson 06 - Service)\\n4. Parameterized Controller Node with YAML Parameter Loading (Bonus Lesson 17 - Params)\\nAll running under an isolated robot namespace.\\n================================================================================\\n&quot;&quot;&quot;\\n\\nimport os\\nfrom ament_index_python.packages import get_package_share_directory\\nfrom launch import LaunchDescription\\nfrom launch.actions import DeclareLaunchArgument, LogInfo\\nfrom launch.substitutions import LaunchConfiguration\\nfrom launch_ros.actions import Node\\n\\n\\ndef generate_launch_description():\\n    pkg_share = get_package_share_directory(&#x27;nexus_amr_basics&#x27;)\\n    default_config = os.path.join(pkg_share, &#x27;config&#x27;, &#x27;teleop_params.yaml&#x27;)\\n    if not os.path.exists(default_config):\\n        source_config = os.path.expanduser(&#x27;~/ros2_ws/src/nexus_amr_basics/config/teleop_params.yaml&#x27;)\\n        if os.path.exists(source_config):\\n            default_config = source_config\\n\\n    namespace_arg = DeclareLaunchArgument(\\n        &#x27;robot_namespace&#x27;,\\n        default_value=&#x27;amr_alpha&#x27;,\\n        description=&#x27;Robot top-level namespace&#x27;\\n    )\\n\\n    config_arg = DeclareLaunchArgument(\\n        &#x27;config_file&#x27;,\\n        default_value=default_config,\\n        description=&#x27;Path to YAML parameters configuration&#x27;\\n    )\\n\\n    robot_ns = LaunchConfiguration(&#x27;robot_namespace&#x27;)\\n    config_file = LaunchConfiguration(&#x27;config_file&#x27;)\\n\\n    # Node 1: Ultrasonic Sensor Publisher (Lesson 05)\\n    ultrasonic_node = Node(\\n        package=&#x27;nexus_amr_basics&#x27;,\\n        executable=&#x27;ultrasonic_publisher&#x27;,\\n        name=&#x27;ultrasonic_publisher&#x27;,\\n        namespace=robot_ns,\\n        output=&#x27;screen&#x27;\\n    )\\n\\n    # Node 2: Collision Monitor Subscriber (Lesson 05)\\n    collision_node = Node(\\n        package=&#x27;nexus_amr_basics&#x27;,\\n        executable=&#x27;collision_monitor&#x27;,\\n        name=&#x27;collision_monitor&#x27;,\\n        namespace=robot_ns,\\n        output=&#x27;screen&#x27;\\n    )\\n\\n    # Node 3: Emergency Stop Service Server (Lesson 06)\\n    estop_node = Node(\\n        package=&#x27;nexus_amr_basics&#x27;,\\n        executable=&#x27;emergency_stop_server&#x27;,\\n        name=&#x27;emergency_stop_server&#x27;,\\n        namespace=robot_ns,\\n        output=&#x27;screen&#x27;\\n    )\\n\\n    # Node 4: Parameterized Controller Node with YAML Parameters (Bonus Lesson 17)\\n    param_node = Node(\\n        package=&#x27;nexus_amr_basics&#x27;,\\n        executable=&#x27;param_node_explained&#x27;,\\n        name=&#x27;parameterized_controller&#x27;,\\n        namespace=robot_ns,\\n        parameters=[config_file],\\n        output=&#x27;screen&#x27;\\n    )\\n\\n    return LaunchDescription([\\n        namespace_arg,\\n        config_arg,\\n        LogInfo(msg=[&#x27;[Launch] Starting Full AMR Stack for robot: &#x27;, robot_ns]),\\n        ultrasonic_node,\\n        collision_node,\\n        estop_node,\\n        param_node\\n    ])\\n</code></pre>\\n    </div>\\n  </div>\\n</details>\\n\\n<div class=\\"asset-handoff-card\\" style=\\"margin: 1.75rem 0 1rem 0; padding: 1.15rem 1.4rem; border-radius: 10px; background: rgba(16, 185, 129, 0.06); border: 1px solid rgba(16, 185, 129, 0.25); border-left: 4px solid #10b981;\\">\\n  <div style=\\"display: flex; align-items: center; gap: 0.5rem; margin-bottom: 0.5rem;\\">\\n    <span style=\\"font-size: 1.1rem;\\">📦</span>\\n    <strong style=\\"font-size: 0.95rem; color: #10b981; text-transform: uppercase; letter-spacing: 0.04em;\\">Asset Handoff &amp; Next Lesson Pipeline Bridge</strong>\\n  </div>\\n  <p style=\\"margin: 0 0 0.65rem 0; font-size: 0.88rem; color: var(--text-primary); line-height: 1.6;\\">\\n    You have engineered production-grade Python launch files that orchestrate multi-node lifecycles across topics, services, and parameters, configure namespaces and topic remappings, and load YAML parameter trees automatically.\\n  </p>\\n  <div style=\\"display: flex; flex-wrap: wrap; gap: 0.75rem; font-size: 0.82rem; font-family: var(--font-mono);\\">\\n    <span style=\\"background: var(--bg-surface); border: 1px solid var(--border-color); padding: 0.25rem 0.6rem; border-radius: 5px; color: var(--text-primary);\\">\\n      📁 <strong>Produced Artifact:</strong> <code>nexus_amr_basics/launch/amr_subsystem.launch.py</code> &amp; <code>task_fleet_launch.py</code>\\n    </span>\\n    <span style=\\"background: var(--bg-surface); border: 1px solid var(--border-color); padding: 0.25rem 0.6rem; border-radius: 5px; color: var(--text-primary);\\">\\n      ➡️ <strong>Ingested By:</strong> Lesson 08 (Communication Mechanism III: Action Servers &amp; Clients in Python)\\n    </span>\\n  </div>\\n</div>\\n","quizzes":[{"id":"q_l1_10_1","prompt":"In a ROS 2 Python launch file, what does the 'remappings' parameter on launch_ros.actions.Node allow you to do?","options":["Rename physical USB ports for motor controllers","Redirect topic or service names without modifying the underlying Python source code","Swap the ROS 2 DDS distribution at runtime","Change keyboard shortcuts in RViz2"],"correct":1,"explanation":"Remappings allow routing topics (e.g. from /cmd_vel to /diff_drive_controller/cmd_vel_unstamped) dynamically in launch files, decoupling node code from specific robot topologies."},{"id":"q_l1_10_2","prompt":"When orchestrating a robot subsystem via a launch file, why is a Service Server launched as a persistent node while a Service Client is usually triggered on-demand or via event handlers?","options":["Because service clients cannot execute on Linux operating systems","Because Service Servers must run continuously as daemons to listen for requests, whereas Clients send short-lived RPC transactions when triggered","Because launch files only support topic publishers and subscribers, not services","Because DDS only permits one service server to exist in an entire ROS domain"],"correct":1,"explanation":"Service servers are persistent background processes awaiting requests at any time. Clients represent transient request-response transactions, invoked when an event or human operator commands an action."}],"has_quiz":true,"next_id":"lesson_08","prev_id":"lesson_06","subtopics":[{"id":"1-overview-learning-objectives","title":"1. Overview &amp; Learning Objectives"},{"id":"2-the-python-launch-architecture","title":"2. The Python Launch Architecture"},{"id":"3-step-by-step-writing-an-amr-subsystem-launch-file","title":"3. Step-by-Step: Writing an AMR Subsystem Launch File"},{"id":"4-key-launch-actions-syntax-breakdown","title":"4. Key Launch Actions &amp; Syntax Breakdown"},{"id":"5-composition-including-other-launch-files","title":"5. Composition: Including Other Launch Files"},{"id":"6-execution-cli-overrides","title":"6. Execution &amp; CLI Overrides"},{"id":"7-hands-on-student-challenge-full-stack-amr-subsystem-launch","title":"7. Hands-on Student Challenge: Full-Stack AMR Subsystem Launch Orchestrator"}]},{"id":"lesson_08","num":8,"num_str":"08","title":"Communication Mechanism III: Action Servers & Clients in Python","slug":"ros2-actions-server-and-client","filename":"10_ros2_actions_server_and_client.md","module":"Day 1: ROS 2 Foundations & Core Middleware","module_id":1,"duration":"45-60 min","focus":"Linear Distance Traversal Action Server, Asynchronous Goal Handlers, Real-Time Progress Feedback","snapshot":[["3-Tier Action Pipeline","Goal Service (Accept/Reject), Feedback Topic (Real-time progress streaming), and Result Service (Terminal success/failure)."],["Preemptible Execution","Actions can be aborted, preempted by higher-priority goals, or canceled mid-flight by supervisory nodes."],["When to Use Actions","Mandatory for long-running physical tasks: driving 10 meters, precise target positioning, laser mapping, or arm trajectory execution."],["Action CLI Inspection","ros2 action list, info, and send_goal --feedback test long-running mission goals with live progress streaming."]],"html_content":"<h2 id=\\"1-overview-learning-objectives\\">1. Overview &amp; Learning Objectives</h2>\\n<p>Services are ideal for instant requests (e.g. &quot;turn on light&quot; or &quot;reset encoder&quot;). However, for long-running robotic tasks that take seconds or minutes to complete (e.g., navigating across a warehouse or executing a 360-degree LiDAR calibration sweep), Services fail because they provide no progress feedback and cannot be canceled midway.</p>\\n<p>ROS 2 <strong>Actions</strong> solve this by implementing the <strong>Goal - Feedback - Result</strong> protocol with native preemption and cancellation support.</p>\\n<p><div class=\\"learning-objectives-card\\">\\n  <div class=\\"learning-objectives-header\\">\\n    <div class=\\"objectives-icon-badge\\">\\n      <span style=\\"font-size: 1.15rem; line-height: 1;\\">🎯</span>\\n    </div>\\n    <div class=\\"objectives-title-group\\">\\n      <h3 class=\\"objectives-main-title\\">Learning Objectives &amp; Core Outcomes</h3>\\n      <span class=\\"objectives-subtitle\\">By the end of this lesson, you will be able to:</span>\\n    </div>\\n    <span class=\\"objectives-count-badge\\">5 CORE OUTCOMES</span>\\n  </div>\\n  <ul class=\\"learning-objectives-list\\">\\n    <li class=\\"learning-objective-item\\">\\n      <span class=\\"objective-num-badge\\">1</span>\\n      <span class=\\"objective-text\\">Master the 3-part Action lifecycle: Goal submission, Real-time Feedback streaming, and Final Result delivery.</span>\\n    </li>\\n    <li class=\\"learning-objective-item\\">\\n      <span class=\\"objective-num-badge\\">2</span>\\n      <span class=\\"objective-text\\">Build an object-oriented Python <strong>Action Server</strong> using <code class=\\"inline-code\\">rclpy.action.ActionServer</code>.</span>\\n    </li>\\n    <li class=\\"learning-objective-item\\">\\n      <span class=\\"objective-num-badge\\">3</span>\\n      <span class=\\"objective-text\\">Handle goal acceptance, goal rejection, feedback broadcasting, and client cancellation requests.</span>\\n    </li>\\n    <li class=\\"learning-objective-item\\">\\n      <span class=\\"objective-num-badge\\">4</span>\\n      <span class=\\"objective-text\\">Build an asynchronous Python <strong>Action Client</strong> using <code class=\\"inline-code\\">rclpy.action.ActionClient</code>.</span>\\n    </li>\\n    <li class=\\"learning-objective-item\\">\\n      <span class=\\"objective-num-badge\\">5</span>\\n      <span class=\\"objective-text\\">Interact with, trigger, and cancel active actions via the CLI using <code class=\\"inline-code\\">ros2 action send_goal --feedback</code>.</span>\\n    </li>\\n  </ul>\\n</div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"2-action-communication-architecture\\">2. Action Communication Architecture</h2>\\n<p>Use the interactive action architecture canvas below to explore the 3-tier long-running action protocol. Dispatch goal requests, observe real-time feedback telemetry streaming over DDS, test mid-flight cancellation/preemption, and verify terminal result resolution:</p>\\n<div id=\\"action-flow-root\\" style=\\"margin: 1.75rem 0;\\"></div>\\n<p>Under the hood, every ROS 2 Action is implemented as a coordinated set of DDS topics and services:</p>\\n<div class=\\"infographic-container\\" style=\\"margin: 1.75rem 0; text-align: center;\\">\\n  <img src=\\"/assets/images/ros2_action_lifecycle.svg\\" alt=\\"ROS 2 Action Protocol and Goal Lifecycle Architecture\\" style=\\"max-width: 100%; height: auto; border-radius: 12px; box-shadow: 0 4px 20px rgba(0,0,0,0.3); border: 1px solid var(--border-color, #1e293b);\\" />\\n  <p class=\\"image-caption\\" style=\\"margin-top: 0.6rem; font-size: 0.82rem; color: var(--text-muted); font-style: italic;\\">\\n    Figure 10.1: ROS 2 Action Protocol Decomposition — 5 underlying DDS streams (Goal Service, Feedback Topic, Status Topic, Cancel Service, Result Service) and the Goal State Machine.\\n  </p>\\n</div>\\n<ul>\\n<li><strong>Goal:</strong> Initiated by the client (e.g. target pose coordinates).</li>\\n<li><strong>Feedback:</strong> Periodic updates published by the server while executing the goal (e.g. current progress, distance remaining).</li>\\n<li><strong>Result:</strong> Final response sent when the task completes, fails, or is canceled.</li>\\n</ul>\\n<hr class=\\"divider\\">\\n<h2 id=\\"3-building-the-linear-traversal-action-server\\">3. Building the Linear Traversal Action Server in Python</h2>\\n<p>Long-running robotic actions require continuous telemetry feedback and preemption handling. Let's build an action server that executes linear distance movements using <code class=\\"inline-code\\">nexus_amr_interfaces/action/NavigateDistance.action</code>.</p>\\n\\n\\n<div class=\\"alert alert-info alert-briefing\\">\\n  <div class=\\"alert-icon\\">🧭</div>\\n  <div class=\\"alert-content\\">\\n    <div class=\\"alert-title\\">Robotics Flight Operations Mission Briefing: AMR Linear Traversal Navigation Action Server</div>\\n    <div class=\\"alert-body\\">\\n      <strong>Physical AMR Context &amp; Operational Challenge:</strong><br>\\n      In autonomous warehouse robotics, a mobile robot frequently receives high-level travel directives: 'Traverse 12.5 meters down Corridor B at 0.8 m/s'. This operation requires 15 to 30 seconds to complete. The supervisor cannot use a blocking Service (which would freeze client execution) nor an uncoordinated Topic (which provides no goal state machine, no preemption, and no delivery confirmation).\\n      <br><br>\\n      <strong>Architectural Role &amp; Why This Mechanism:</strong><br>\\n      <strong>ROS 2 Actions</strong> are designed specifically for long-running, non-instantaneous robotic tasks. Built over 5 underlying DDS topics and services, an Action provides a 3-part lifecycle: asynchronous Goal Submission (with accept/reject policy), real-time continuous Feedback streaming (distance remaining, velocity, percentage), and preemption/Cancelation support.\\n      <br><br>\\n      <strong>Flight Objective &amp; Behavioral Outcome:</strong><br>\\n      Construct an Action Server in Python using <code>nexus_amr_interfaces/action/NavigateDistance</code>. Implement goal validation, cancel callbacks, an incremental execution loop publishing feedback at 10 Hz, and successful goal completion with a final result payload.\\n    </div>\\n  </div>\\n</div>\\n\\n\\n<div class=\\"alert-callout alert-info\\" style=\\"margin: 1.5rem 0;\\">\\n  <div class=\\"alert-icon\\">🔍</div>\\n  <div class=\\"alert-body\\">\\n    <strong>Best Practice: Discovering &amp; Inspecting Action Interfaces Before Writing Code</strong><br>\\n    Actions represent complex, long-running behaviors. An action definition (<code class=\\"inline-code\\">.action</code>) has three distinct sections separated by two sets of three hyphens (<code class=\\"inline-code\\">---</code>). Always inspect this contract before writing server or client code:\\n    <br><br>\\n    <strong>1. Discover available action interfaces using <code class=\\"inline-code\\">ros2 interface list</code> or <code class=\\"inline-code\\">package</code>:</strong>\\n    <div class=\\"code-container\\" data-language=\\"bash\\" style=\\"margin: 0.6rem 0;\\">\\n      <div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n      <pre><code class=\\"language-bash\\"># Search for distance or navigation action types:\\nros2 interface list | grep action | grep -i distance\\n\\n# Or list all actions defined in our AMR workspace package:\\nros2 interface package nexus_amr_interfaces</code></pre>\\n    </div>\\n    <strong>2. Inspect the Goal, Result, and Feedback schemas using <code class=\\"inline-code\\">ros2 interface show</code>:</strong>\\n    <div class=\\"code-container\\" data-language=\\"bash\\" style=\\"margin: 0.6rem 0;\\">\\n      <div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n      <pre><code class=\\"language-bash\\">ros2 interface show nexus_amr_interfaces/action/NavigateDistance</code></pre>\\n    </div>\\n    <strong>Expected Output &amp; Tri-Partite Action Contract:</strong>\\n    <div class=\\"code-container terminal-window\\" data-language=\\"plaintext\\" style=\\"margin: 0.6rem 0;\\">\\n      <div class=\\"terminal-header\\">\\n        <div class=\\"terminal-dots\\"><span class=\\"dot red\\"></span><span class=\\"dot yellow\\"></span><span class=\\"dot green\\"></span></div>\\n        <span class=\\"terminal-title\\">Terminal &mdash; ros2 interface show nexus_amr_interfaces/action/NavigateDistance</span>\\n      </div>\\n      <pre><code class=\\"language-plaintext\\"># Section 1: Goal (Client target parameters)\\nfloat32 target_distance_m\\nfloat32 max_speed_mps\\n---\\n# Section 2: Result (Final outcome upon completion or cancellation)\\nbool reached_target\\nfloat32 actual_distance_travelled_m\\nstring status_message\\n---\\n# Section 3: Feedback (Periodic progress updates streamed during execution)\\nfloat32 distance_remaining_m\\nfloat32 current_speed_mps\\nfloat32 percent_complete</code></pre>\\n    </div>\\n    <ul style=\\"margin: 0.5rem 0 0 1.25rem; line-height: 1.6;\\">\\n      <li><strong>Goal:</strong> Read via <code class=\\"inline-code\\">goal_handle.request.target_distance_m</code> and <code class=\\"inline-code\\">goal_handle.request.max_speed_mps</code>.</li>\\n      <li><strong>Feedback:</strong> Streamed back to client using <code class=\\"inline-code\\">feedback_msg = NavigateDistance.Feedback()</code> and <code class=\\"inline-code\\">goal_handle.publish_feedback(feedback_msg)</code>.</li>\\n      <li><strong>Result:</strong> Returned upon goal completion via <code class=\\"inline-code\\">result = NavigateDistance.Result()</code>, marked via <code class=\\"inline-code\\">goal_handle.succeed()</code>, and returned.</li>\\n      <li><strong>Essential CLI Verification Tools:</strong> Check active action servers with <code class=\\"inline-code\\">ros2 action list</code>, inspect client/server endpoints with <code class=\\"inline-code\\">ros2 action info &lt;action&gt;</code>, and test server execution directly using <code class=\\"inline-code\\">ros2 action send_goal &lt;name&gt; &lt;type&gt; \\"&lt;yaml&gt;\\" --feedback</code>!</li>\\n    </ul>\\n  </div>\\n</div>\\n\\n<p>Create your action server at <code class=\\"inline-code\\">~/ros2_ws/src/nexus_amr_basics/nexus_amr_basics/navigate_distance_server.py</code>:</p>\\n\\n<div class=\\"code-container ide-code-window\\" data-language=\\"python\\">\\n  <div class=\\"code-header\\">\\n    <div class=\\"code-dots\\"><span class=\\"dot red\\"></span><span class=\\"dot yellow\\"></span><span class=\\"dot green\\"></span></div>\\n    <span class=\\"code-filename\\">navigate_distance_server.py &mdash; AMR Distance Navigation Action Server</span>\\n  </div>\\n  <pre><code class=\\"language-python\\">import time\\nimport rclpy\\nfrom rclpy.node import Node\\nfrom rclpy.action import ActionServer, CancelResponse, GoalResponse\\nfrom nexus_amr_interfaces.action import NavigateDistance\\n\\n\\nclass NavigateDistanceActionServer(Node):\\n    \\"\\"\\"\\n    AMR Linear Navigation Action Server Node.\\n    \\"\\"\\"\\n\\n    def __init__(self):\\n        super().__init__('navigate_distance_server')\\n\\n        self._action_server = ActionServer(\\n            self,\\n            NavigateDistance,\\n            '/navigate_distance',\\n            execute_callback=self.execute_callback,\\n            goal_callback=self.goal_callback,\\n            cancel_callback=self.cancel_callback\\n        )\\n        self.get_logger().info('NavigateDistanceActionServer initialized on \\"/navigate_distance\\"...')\\n\\n    def goal_callback(self, goal_request):\\n        if goal_request.target_distance_m <= 0.0 or goal_request.max_speed_mps <= 0.0:\\n            return GoalResponse.REJECT\\n        return GoalResponse.ACCEPT\\n\\n    def cancel_callback(self, goal_handle):\\n        self.get_logger().warn('Received cancel request for navigation traversal!')\\n        return CancelResponse.ACCEPT\\n\\n    def execute_callback(self, goal_handle):\\n        target = goal_handle.request.target_distance_m\\n        speed = min(2.0, max(0.1, goal_handle.request.max_speed_mps))\\n\\n        feedback_msg = NavigateDistance.Feedback()\\n        distance_travelled = 0.0\\n        dt = 0.1\\n\\n        while distance_travelled < target:\\n            if goal_handle.is_cancel_requested:\\n                goal_handle.canceled()\\n                result = NavigateDistance.Result()\\n                result.reached_target = False\\n                result.actual_distance_travelled_m = float(round(distance_travelled, 3))\\n                result.status_message = 'Navigation preempted by cancel request.'\\n                return result\\n\\n            step = speed * dt\\n            distance_travelled = min(target, distance_travelled + step)\\n\\n            feedback_msg.distance_remaining_m = float(round(target - distance_travelled, 3))\\n            feedback_msg.current_speed_mps = float(round(speed, 2))\\n            feedback_msg.percent_complete = float(round((distance_travelled / target) * 100.0, 1))\\n\\n            goal_handle.publish_feedback(feedback_msg)\\n            self.get_logger().info(\\n                f'[TRAVERSAL FEEDBACK] Progress: {feedback_msg.percent_complete:5.1f}% | Rem: {feedback_msg.distance_remaining_m:5.2f} m'\\n            )\\n            time.sleep(dt)\\n\\n        goal_handle.succeed()\\n        result = NavigateDistance.Result()\\n        result.reached_target = True\\n        result.actual_distance_travelled_m = float(round(distance_travelled, 3))\\n        result.status_message = f'Target distance of {target:.2f} m reached.'\\n        return result\\n\\n\\ndef main(args=None):\\n    rclpy.init(args=args)\\n    node = NavigateDistanceActionServer()\\n    try:\\n        rclpy.spin(node)\\n    except KeyboardInterrupt:\\n        pass\\n    finally:\\n        node.destroy_node()\\n        rclpy.shutdown()\\n\\n\\nif __name__ == '__main__':\\n    main()\\n</code></pre>\\n</div>\\n\\n<div class=\\"alert-callout alert-tip\\" style=\\"margin: 1.75rem 0;\\">\\n  <div class=\\"alert-icon\\">🎯</div>\\n  <div class=\\"alert-body\\">\\n    <strong>Observation Note: Action Feedback &amp; Preemption Drill:</strong><br>\\n    Unlike quick services, actions provide streaming progress and can be cancelled when safety hazards arise:<br>\\n    <div class=\\"code-container\\" data-language=\\"bash\\" style=\\"margin: 0.5rem 0 0.3rem 0;\\">\\n      <div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n      <pre><code class=\\"language-bash\\"># Send navigation distance goal with live feedback stream:\\nros2 action send_goal /navigate_distance nexus_amr_interfaces/action/NavigateDistance \\"{target_distance: 5.0}\\" --feedback\\n# Expected Output:\\n# Feedback: current_distance = 1.25 m, remaining_distance = 3.75 m (25.0% complete)\\n# Feedback: current_distance = 2.50 m, remaining_distance = 2.50 m (50.0% complete)\\n# Feedback: current_distance = 3.75 m, remaining_distance = 1.25 m (75.0% complete)\\n# Result: success = True, final_distance = 5.00 m</code></pre>\\n    </div>\\n  </div>\\n</div>\\n\\n<div class=\\"code-breakdown-card\\">\\n  <h4 class=\\"code-breakdown-title\\">🔬 Core Code Deep Dive &amp; Operational Breakdown: NavigateDistanceActionServer Mechanics</h4>\\n  <p class=\\"code-breakdown-intro\\">Key mechanics of long-running Action Servers in rclpy:</p>\\n  <ul class=\\"code-breakdown-list\\">\\n    <li class=\\"code-breakdown-item\\"><strong>ActionServer Initialization:</strong> <code>self._action_server = ActionServer(self, NavigateDistance, '/navigate_distance', execute_callback=..., goal_callback=..., cancel_callback=...)</code> binds the 3 core lifecycle callbacks.</li>\\n    <li class=\\"code-breakdown-item\\"><strong>Goal Acceptance Policy:</strong> <code>goal_callback(self, goal_request)</code> audits incoming goals before execution starts. Rejecting non-positive distances with <code>GoalResponse.REJECT</code> protects actuators from invalid states.</li>\\n    <li class=\\"code-breakdown-item\\"><strong>Cancelation & Preemption Handling:</strong> Inside the execution loop, <code>if goal_handle.is_cancel_requested:</code> checks whether the client requested an abort. If true, calling <code>goal_handle.canceled()</code> stops motors and returns early.</li>\\n    <li class=\\"code-breakdown-item\\"><strong>Real-Time Telemetry Feedback:</strong> <code>feedback_msg = NavigateDistance.Feedback(); goal_handle.publish_feedback(feedback_msg)</code> streams progress (percent complete, distance remaining) continuously without blocking execution.</li>\\n    <li class=\\"code-breakdown-item\\"><strong>Goal Success State Transition:</strong> Calling <code>goal_handle.succeed()</code> marks the goal as successfully achieved and transitions the goal state machine to <code>STATUS_SUCCEEDED</code> before returning the result struct.</li>\\n  </ul>\\n</div>\\n\\n<h2 id=\\"4-building-the-asynchronous-navigation-action-client\\">4. Building the Asynchronous Navigation Action Client in Python</h2>\\n\\n<div class=\\"alert alert-info alert-briefing\\">\\n  <div class=\\"alert-icon\\">📡</div>\\n  <div class=\\"alert-content\\">\\n    <div class=\\"alert-title\\">Robotics Flight Operations Mission Briefing: Asynchronous Navigation Action Client &amp; Feedback Auditor</div>\\n    <div class=\\"alert-body\\">\\n      <strong>Physical AMR Context &amp; Operational Challenge:</strong><br>\\n      A supervisory fleet controller or high-level mission manager dispatches navigation objectives to mobile robots. While the robot traverses the aisle, the supervisor needs continuous live updates to visualize robot position on the facility digital twin, track estimated arrival times, and cancel the mission if an aisle blockage occurs.\\n      <br><br>\\n      <strong>Architectural Role &amp; Why This Mechanism:</strong><br>\\n      A <strong>ROS 2 Action Client</strong> connects to the action server asynchronously. It registers dedicated callbacks for goal acceptance confirmation, feedback telemetry streaming, and asynchronous final result resolution, ensuring the supervisor remains responsive throughout 30-minute navigation missions.\\n      <br><br>\\n      <strong>Flight Objective &amp; Behavioral Outcome:</strong><br>\\n      Implement an asynchronous Action Client that submits a distance navigation goal, listens to continuous feedback telemetry, prints progress meters, and processes the terminal result without freezing the client application.\\n    </div>\\n  </div>\\n</div>\\n\\n<p>Create the client node at <code class=\\"inline-code\\">~/ros2_ws/src/nexus_amr_basics/nexus_amr_basics/navigate_distance_client.py</code>:</p>\\n\\n<div class=\\"code-container ide-code-window\\" data-language=\\"python\\">\\n  <div class=\\"code-header\\">\\n    <div class=\\"code-dots\\"><span class=\\"dot red\\"></span><span class=\\"dot yellow\\"></span><span class=\\"dot green\\"></span></div>\\n    <span class=\\"code-filename\\">navigate_distance_client.py &mdash; AMR Distance Navigation Action Client</span>\\n  </div>\\n  <pre><code class=\\"language-python\\">import sys\\nimport rclpy\\nfrom rclpy.node import Node\\nfrom rclpy.action import ActionClient\\nfrom nexus_amr_interfaces.action import NavigateDistance\\n\\n\\nclass NavigateDistanceActionClient(Node):\\n\\n    def __init__(self):\\n        super().__init__('navigate_distance_client')\\n        self._action_client = ActionClient(self, NavigateDistance, '/navigate_distance')\\n\\n    def send_goal(self, distance: float, speed: float):\\n        goal_msg = NavigateDistance.Goal()\\n        goal_msg.target_distance_m = float(distance)\\n        goal_msg.max_speed_mps = float(speed)\\n\\n        self._action_client.wait_for_server()\\n        self.get_logger().info(f'Sending goal: {distance:.2f} m @ {speed:.2f} m/s')\\n\\n        self._send_goal_future = self._action_client.send_goal_async(\\n            goal_msg,\\n            feedback_callback=self.feedback_callback\\n        )\\n        self._send_goal_future.add_done_callback(self.goal_response_callback)\\n\\n    def goal_response_callback(self, future):\\n        goal_handle = future.result()\\n        if not goal_handle.accepted:\\n            self.get_logger().error('Goal REJECTED!')\\n            return\\n        self.get_logger().info('Goal ACCEPTED. Running...')\\n        self._get_result_future = goal_handle.get_result_async()\\n        self._get_result_future.add_done_callback(self.get_result_callback)\\n\\n    def feedback_callback(self, feedback_msg):\\n        fb = feedback_msg.feedback\\n        self.get_logger().info(\\n            f'[FEEDBACK] {fb.percent_complete:5.1f}% | Remaining: {fb.distance_remaining_m:5.2f} m'\\n        )\\n\\n    def get_result_callback(self, future):\\n        res = future.result().result\\n        self.get_logger().info(f'[RESULT] Succeeded: {res.reached_target} | Message: {res.status_message}')\\n        rclpy.shutdown()\\n\\n\\ndef main(args=None):\\n    rclpy.init(args=args)\\n    client = NavigateDistanceActionClient()\\n    dist = float(sys.argv[1]) if len(sys.argv) > 1 else 2.5\\n    speed = float(sys.argv[2]) if len(sys.argv) > 2 else 0.5\\n    client.send_goal(dist, speed)\\n    try:\\n        rclpy.spin(client)\\n    except (KeyboardInterrupt, SystemExit):\\n        pass\\n\\n\\nif __name__ == '__main__':\\n    main()\\n</code></pre>\\n</div>\\n\\n<div class=\\"code-breakdown-card\\">\\n  <h4 class=\\"code-breakdown-title\\">🔬 Core Code Deep Dive &amp; Operational Breakdown: NavigateDistanceActionClient Non-Blocking Architecture</h4>\\n  <p class=\\"code-breakdown-intro\\">Dissecting the asynchronous Action Client callback chain:</p>\\n  <ul class=\\"code-breakdown-list\\">\\n    <li class=\\"code-breakdown-item\\"><strong>ActionClient Allocation:</strong> <code>self._action_client = ActionClient(self, NavigateDistance, '/navigate_distance')</code> creates client DDS endpoints for goal, cancel, result services and feedback topic.</li>\\n    <li class=\\"code-breakdown-item\\"><strong>Asynchronous Goal Dispatch:</strong> <code>self._action_client.send_goal_async(goal_msg, feedback_callback=self.feedback_callback)</code> submits the goal and wires real-time feedback packets directly to a member callback.</li>\\n    <li class=\\"code-breakdown-item\\"><strong>Goal Acceptance Future Chain:</strong> Attaching <code>add_done_callback(self.goal_response_callback)</code> handles server acceptance asynchronously. Once accepted, <code>goal_handle.get_result_async()</code> queues the result future.</li>\\n    <li class=\\"code-breakdown-item\\"><strong>Feedback Telemetry Processing:</strong> <code>feedback_callback(self, feedback_msg)</code> executes whenever the robot makes progress, allowing user interfaces or monitors to render live progress bars without polling.</li>\\n  </ul>\\n</div>\\n\\n<h2 id=\\"5-verification-with-the-ros-2-action-cli\\">5. Verification with the ROS 2 Action CLI</h2>\\n<p><strong>Terminal 1: Start Action Server</strong></p>\\n<p><div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\">ros2 run nexus_amr_basics navigate_distance_server\\n</code></pre>\\n</div>\\n</p>\\n<p><strong>Terminal 2: Run Asynchronous Action Client</strong></p>\\n<p><div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\">ros2 run nexus_amr_basics navigate_distance_client 8\\n# Output:\\n# [INFO] [navigate_distance_client]: Sending goal request for NavigateDistance order 8...\\n# [INFO] [navigate_distance_client]: Goal accepted! Awaiting result...\\n# [INFO] [navigate_distance_client]: Received feedback sequence: array(&#x27;i&#x27;, [0, 1, 1])\\n# [INFO] [navigate_distance_client]: Received feedback sequence: array(&#x27;i&#x27;, [0, 1, 1, 2])\\n# ...\\n# [INFO] [navigate_distance_client]: Final Result: array(&#x27;i&#x27;, [0, 1, 1, 2, 3, 5, 8, 13, 21])\\n</code></pre>\\n</div>\\n</p>\\n<p><strong>Terminal 3: Action CLI Introspection &amp; Manual Goal Dispatch</strong></p>\\n<p><div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\"># 1. List active action servers:\\nros2 action list\\n# Output:\\n# /navigate_distance\\n\\n# 2. Inspect action interface type and server count:\\nros2 action info /navigate_distance\\n# Output:\\n# Action: /navigate_distance\\n# Action clients: 0\\n# Action servers: 1\\n\\n# 3. Send a goal without feedback first (Simple before Advanced):\\nros2 action send_goal /navigate_distance nexus_amr_interfaces/action/NavigateDistance &quot;{target_distance: 2.0}&quot;\\n# Output:\\n# Waiting for an action server to become available...\\n# Sending goal:\\n#    target_distance: 2.0\\n# Goal accepted with ID: e56b12a...\\n# Result:\\n#    success: true\\n#    final_distance: 2.00\\n# Goal finished with status: SUCCEEDED\\n\\n# 4. Now send with --feedback to observe continuous real-time progress updates:\\nros2 action send_goal /navigate_distance nexus_amr_interfaces/action/NavigateDistance &quot;{target_distance: 5.0}&quot; --feedback\\n# Output:\\n# Feedback: current_distance = 1.25 m, remaining_distance = 3.75 m (25.0% complete)\\n# Feedback: current_distance = 2.50 m, remaining_distance = 2.50 m (50.0% complete)\\n# Feedback: current_distance = 3.75 m, remaining_distance = 1.25 m (75.0% complete)\\n# Result: success = True, final_distance = 5.00 m\\n# Goal finished with status: SUCCEEDED\\n</code></pre>\\n</div>\\n</p>\\n<hr class=\\"divider\\">\\n<h2 id=\\"6-from-navigatedistance-to-robotics-patrol\\">6. From NavigateDistance to Robotics: Waypoint Patrol &amp; Navigation</h2>\\n<p>The exact same Action protocol is what powers autonomous navigation in Nav2!</p>\\n<ul>\\n<li>Instead of computing numbers, the server navigates the robot through waypoints.</li>\\n<li>Instead of <code class=\\"inline-code\\">partial_sequence</code>, feedback streams <code class=\\"inline-code\\">distance_remaining</code> and <code class=\\"inline-code\\">current_speed</code>.</li>\\n<li>When an obstacle blocks the path, the client can cancel or preempt the goal cleanly!</li>\\n</ul>\\n\\n<hr class=\\"divider\\">\\n<h2 id=\\"7-hands-on-student-challenge\\">7. Hands-on Student Challenge: Long-Running NavigateDistance Action Server with Feedback</h2>\\n<p>Implement an Action Server utilizing the <code class=\\"inline-code\\">NavigateDistance</code> action interface, streaming feedback at progressive steps and returning the final result.</p>\\n\\n<div class=\\"alert alert-tip\\">\\n  <div class=\\"alert-title\\">🎯 Mission Requirements: NavigateDistance Action Server</div>\\n  <ol>\\n    <li><strong>TODO 1:</strong> Initialize <code class=\\"inline-code\\">ActionServer</code> for <code class=\\"inline-code\\">NavigateDistance</code> on topic <code class=\\"inline-code\\">/navigate_distance</code> with <code class=\\"inline-code\\">execute_callback</code>, <code class=\\"inline-code\\">goal_callback</code>, and <code class=\\"inline-code\\">cancel_callback</code>.</li>\\n    <li><strong>TODO 2:</strong> In <code class=\\"inline-code\\">goal_callback</code>, validate that <code class=\\"inline-code\\">target_distance_m &gt; 0.0</code> and accept the goal handle via <code class=\\"inline-code\\">GoalResponse.ACCEPT</code>.</li>\\n    <li><strong>TODO 3:</strong> In <code class=\\"inline-code\\">execute_callback</code>, loop incrementally at 10 Hz, monitor <code class=\\"inline-code\\">goal_handle.is_cancel_requested</code> for preemption, update <code class=\\"inline-code\\">distance_remaining_m</code>, and publish real-time feedback via <code class=\\"inline-code\\">goal_handle.publish_feedback(feedback_msg)</code>.</li>\\n    <li><strong>TODO 4:</strong> When distance remaining reaches 0.0m, mark <code class=\\"inline-code\\">goal_handle.succeed()</code>, return final <code class=\\"inline-code\\">NavigateDistance.Result(reached_target=True)</code>, and verify using <code class=\\"inline-code\\">ros2 action send_goal /navigate_distance nexus_amr_interfaces/action/NavigateDistance \\"{target_distance_m: 5.0, max_speed_mps: 1.0}\\" --feedback</code>.</li>\\n  </ol>\\n</div>\\n\\n\\n<div class=\\"alert alert-info alert-briefing\\">\\n  <div class=\\"alert-icon\\">🎯</div>\\n  <div class=\\"alert-content\\">\\n    <div class=\\"alert-title\\">Robotics Flight Operations Mission Briefing: Long-Running NavigateDistance Action Server Challenge</div>\\n    <div class=\\"alert-body\\">\\n      <strong>Physical AMR Context &amp; Operational Challenge:</strong><br>\\n      In physical AMR operations, straight-line traversals between warehouse stations require executing motion with centimeter precision. The robot must continuously calculate remaining distance, stream telemetry feedback to the fleet manager, and allow immediate preemption if safety scanners detect a blocked passage.\\n      <br><br>\\n      <strong>Architectural Role &amp; Why This Mechanism:</strong><br>\\n      Implementing an Action Server requires strict compliance with the ROS 2 Action lifecycle state machine. You must handle the 3-phase flow: goal request evaluation, iterative feedback publishing in an interruptible execution loop, and clean terminal state transitions (succeeded vs canceled).\\n      <br><br>\\n      <strong>Flight Objective &amp; Behavioral Outcome:</strong><br>\\n      Complete the <code>NavigateDistanceTaskServer</code>. In <code>execute_callback</code>, step distance iteratively by <code>speed * dt</code>, publish feedback with remaining distance and percent complete, honor cancelation requests, and return the final distance travelled upon arrival.\\n    </div>\\n  </div>\\n</div>\\n\\n<h3 id=\\"71-starter-template\\">7.1 Starter Template: <code class=\\"inline-code\\">m01_l08_task_navigate_distance_server.py</code></h3>\\n<p>Copy the starter template from the reference workspace into your active student workspace:</p>\\n<div class=\\"code-container\\" data-language=\\"bash\\">\\n  <div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n  <pre><code class=\\"language-bash\\">cp ~/ros2_ws_reference/src/nexus_amr_basics/nexus_amr_basics/m01_l08_task_navigate_distance_server.py ~/ros2_ws/src/nexus_amr_basics/nexus_amr_basics/</code></pre>\\n</div>\\n<p>Open the copied file in your editor and complete the marked <code class=\\"inline-code\\">TODO</code> targets:</p>\\n\\n<div class=\\"code-container\\" data-language=\\"python\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">python</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-python\\">#!/usr/bin/env python3\\n&quot;&quot;&quot;\\n================================================================================\\nNexus AMR Learning Hub - Level 1: Module 1 / Lesson 08 Task\\nPackage: nexus_amr_basics\\nTask:    m01_l08_task_navigate_distance_server.py (alias: task_navigate_action)\\n================================================================================\\n\\nEXERCISE OVERVIEW:\\n------------------\\nYour mission is to construct an Autonomous Mobile Robot (AMR) Linear Traversal\\nAction Server utilizing the custom interface \`nexus_amr_interfaces/action/NavigateDistance\`.\\n\\nOBJECTIVES:\\n-----------\\n1. Import \`NavigateDistance\` from \`nexus_amr_interfaces.action\`.\\n2. TODO 1: Initialize ActionServer on &#x27;/navigate_distance&#x27; with \`self.execute_callback\`.\\n3. TODO 2: In \`execute_callback(self, goal_handle)\`:\\n   - Extract \`target = goal_handle.request.target_distance_m\` and \`speed = goal_handle.request.max_speed_mps\`.\\n   - Instantiate feedback object: \`feedback_msg = NavigateDistance.Feedback()\`.\\n4. TODO 3: In a while loop advancing distance by \`speed * dt\`:\\n   - Check if \`goal_handle.is_cancel_requested\`. If so, call \`goal_handle.canceled()\` and return early.\\n   - Calculate \`feedback_msg.distance_remaining_m = target - distance_travelled\`.\\n   - Calculate \`feedback_msg.percent_complete = (distance_travelled / target) * 100.0\`.\\n   - Publish feedback: \`goal_handle.publish_feedback(feedback_msg)\`.\\n   - Sleep for \`dt = 0.1\` seconds.\\n5. TODO 4: Once target is achieved:\\n   - Call \`goal_handle.succeed()\`.\\n   - Populate \`result = NavigateDistance.Result()\` with \`reached_target = True\`,\\n     \`actual_distance_travelled_m = distance_travelled\`, \`status_message = &quot;Target reached.&quot;\`.\\n   - Return result.\\n================================================================================\\n&quot;&quot;&quot;\\n\\nimport time\\nimport rclpy\\nfrom rclpy.node import Node\\nfrom rclpy.action import ActionServer, CancelResponse, GoalResponse\\nfrom nexus_amr_interfaces.action import NavigateDistance\\n\\n\\nclass NavigateDistanceTaskServer(Node):\\n    &quot;&quot;&quot;\\n    Student Starter Template: AMR Linear Navigation Action Server\\n    &quot;&quot;&quot;\\n\\n    def __init__(self):\\n        super().__init__(&#x27;navigate_distance_server&#x27;)\\n\\n        # ======================================================================\\n        # TODO 1: Create ActionServer on &#x27;/navigate_distance&#x27;\\n        # - Action Type: NavigateDistance\\n        # - Action Name: &#x27;/navigate_distance&#x27;\\n        # - Callback: self.execute_callback\\n        # ======================================================================\\n        # Hint: Call ActionServer(self, NavigateDistance, &#x27;/navigate_distance&#x27;, self.execute_callback).\\n        self._action_server = None\\n\\n        self.get_logger().info(&#x27;NavigateDistanceTaskServer initialized and awaiting goals...&#x27;)\\n\\n    def execute_callback(self, goal_handle):\\n        target = goal_handle.request.target_distance_m\\n        speed = goal_handle.request.max_speed_mps\\n        self.get_logger().info(f&#x27;Executing traversal: Target={target:.2f} m, Speed={speed:.2f} m/s&#x27;)\\n\\n        # ======================================================================\\n        # TODO 2: Instantiate feedback message and initialize state\\n        # - Hint: Instantiate NavigateDistance.Feedback() and initialize distance_travelled and time step variables.\\n        # ======================================================================\\n        # TODO: Initialize feedback and motion tracking variables\\n\\n        # ======================================================================\\n        # TODO 3: Control loop while distance_travelled &lt; target:\\n        # - Hint: Check for cancellation via goal_handle.is_cancel_requested.\\n        # - Advance distance_travelled by speed * dt, update feedback fields, stream via goal_handle.publish_feedback(), and sleep dt.\\n        # ======================================================================\\n        # TODO: Implement traversal loop\\n\\n        # ======================================================================\\n        # TODO 4: Complete goal, mark succeeded, and return result:\\n        # - Hint: Call goal_handle.succeed() and return a populated NavigateDistance.Result instance.\\n        # ======================================================================\\n        # TODO: Return result object\\n\\n        return NavigateDistance.Result()\\n\\n\\ndef main(args=None):\\n    rclpy.init(args=args)\\n    node = NavigateDistanceTaskServer()\\n    try:\\n        rclpy.spin(node)\\n    except KeyboardInterrupt:\\n        pass\\n    finally:\\n        node.destroy_node()\\n        rclpy.shutdown()\\n\\n\\nif __name__ == &#x27;__main__&#x27;:\\n    main()\\n</code></pre>\\n</div>\\n\\n<h3 id=\\"72-verification-steps\\">7.2 Verification Steps &amp; Expected Terminal Output</h3>\\n<p>Run your node or test command and observe the output:</p>\\n<div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\"># Step 1: Copy Action Server to Package and Build\\ncd ~/ros2_ws\\ncolcon build --symlink-install --packages-select nexus_amr_basics\\nsource install/setup.bash\\n\\n</code></pre>\\n</div>\\n\\n<div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash (Terminal 1 - Action Server)</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\">source ~/ros2_ws/install/setup.bash\\nros2 run nexus_amr_basics navigate_distance_server</code></pre>\\n</div>\\n\\n<div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash (Terminal 2 - Action Goal Client)</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\">source /opt/ros/jazzy/setup.bash\\nros2 action send_goal --feedback /navigate_distance nexus_amr_interfaces/action/NavigateDistance \\"{target_distance_m: 2.0, max_speed_mps: 1.0}\\"</code></pre>\\n</div>\\n\\n<p><em>Expected Terminal Output:</em></p>\\n<div class=\\"code-container\\" data-language=\\"text\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">text</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-text\\">Sending goal:\\n     target_distance_m: 2.0\\n     max_speed_mps: 1.0\\n\\nFeedback:\\n    distance_remaining_m: 1.90\\n    current_speed_mps: 1.00\\n    percent_complete: 5.0\\nFeedback:\\n    distance_remaining_m: 1.00\\n    current_speed_mps: 1.00\\n    percent_complete: 50.0\\nFeedback:\\n    distance_remaining_m: 0.00\\n    current_speed_mps: 1.00\\n    percent_complete: 100.0\\n\\nResult:\\n    reached_target: true\\n    actual_distance_travelled_m: 2.0\\n    status_message: Target distance of 2.00 m reached successfully.</code></pre>\\n</div>\\n\\n<details class=\\"reference-solution-dropdown\\">\\n  <summary class=\\"solution-summary-btn\\">\\n    <span>🔍 View Reference Solution (<code class=\\"inline-code\\">m01_l08_solution_navigate_distance_server.py</code>)</span>\\n  </summary>\\n  <div class=\\"solution-body\\">\\n    <p>Reference file: <code class=\\"inline-code\\">ros2_ws_reference/src/nexus_amr_basics/nexus_amr_basics/m01_l08_solution_navigate_distance_server.py</code></p>\\n    <div class=\\"code-container\\" data-language=\\"python\\">\\n      <div class=\\"code-header\\"><span class=\\"code-lang-tag\\">python</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n      <pre><code class=\\"language-python\\">#!/usr/bin/env python3\\n&quot;&quot;&quot;\\n================================================================================\\nNexus AMR Learning Hub - Level 1: Module 1 / Lesson 08 Solution\\nPackage: nexus_amr_basics\\nTask:    m01_l08_solution_navigate_distance_server.py (alias: solution_navigate_action)\\n================================================================================\\n\\nROBOTICS OPERATIONAL MISSION:\\n-----------------------------\\nReference Solution: AMR Linear Traversal Navigation Action Server.\\nHandles long-running distance navigation goals with continuous feedback streaming\\nand preemption/cancelation support using \`nexus_amr_interfaces/action/NavigateDistance\`.\\n\\n3-Part Action Lifecycle Implemented:\\n1. Goal Validation: Rejects non-positive distances or speeds.\\n2. Cancelation Audit: Honors client abort commands instantly during execution.\\n3. Iterative Feedback: Streams progress percentage and distance remaining at 10 Hz.\\n================================================================================\\n&quot;&quot;&quot;\\n\\nimport time\\nimport rclpy\\nfrom rclpy.node import Node\\nfrom rclpy.action import ActionServer, CancelResponse, GoalResponse\\nfrom nexus_amr_interfaces.action import NavigateDistance\\n\\n\\nclass NavigateDistanceSolutionServer(Node):\\n    &quot;&quot;&quot;\\n    Reference Solution: AMR Linear Navigation Action Server\\n    &quot;&quot;&quot;\\n\\n    def __init__(self):\\n        super().__init__(&#x27;navigate_distance_server&#x27;)\\n\\n        # Initialize the Action Server with 3 lifecycle callbacks\\n        self._action_server = ActionServer(\\n            self,\\n            NavigateDistance,\\n            &#x27;/navigate_distance&#x27;,\\n            execute_callback=self.execute_callback,\\n            goal_callback=self.goal_callback,\\n            cancel_callback=self.cancel_callback\\n        )\\n\\n        self.get_logger().info(&#x27;NavigateDistanceSolutionServer active on /navigate_distance.&#x27;)\\n\\n    def goal_callback(self, goal_request):\\n        &quot;&quot;&quot;\\n        Step 1: Goal Acceptance Policy.\\n        Validates target parameters before allocating execution resources.\\n        &quot;&quot;&quot;\\n        if goal_request.target_distance_m &lt;= 0.0 or goal_request.max_speed_mps &lt;= 0.0:\\n            self.get_logger().warn(\\n                f&#x27;Rejecting goal: target_distance={goal_request.target_distance_m}, speed={goal_request.max_speed_mps}&#x27;\\n            )\\n            return GoalResponse.REJECT\\n        return GoalResponse.ACCEPT\\n\\n    def cancel_callback(self, goal_handle):\\n        &quot;&quot;&quot;\\n        Step 2: Preemption &amp; Cancelation Policy.\\n        Allows clients or fleet supervisors to abort the navigation traversal midway.\\n        &quot;&quot;&quot;\\n        self.get_logger().warn(&#x27;Received client request to CANCEL active navigation traversal.&#x27;)\\n        return CancelResponse.ACCEPT\\n\\n    def execute_callback(self, goal_handle):\\n        &quot;&quot;&quot;\\n        Step 3: Execution Loop.\\n        Iteratively simulates motion, streams feedback, audits cancelation, and returns result.\\n        &quot;&quot;&quot;\\n        target = goal_handle.request.target_distance_m\\n        speed = min(2.0, max(0.1, goal_handle.request.max_speed_mps))\\n\\n        feedback_msg = NavigateDistance.Feedback()\\n        distance_travelled = 0.0\\n        dt = 0.1  # 10 Hz feedback loop\\n\\n        while distance_travelled &lt; target:\\n            # Check for client cancelation request\\n            if goal_handle.is_cancel_requested:\\n                goal_handle.canceled()\\n                result = NavigateDistance.Result()\\n                result.reached_target = False\\n                result.actual_distance_travelled_m = float(round(distance_travelled, 3))\\n                result.status_message = &#x27;Navigation preempted by cancel request.&#x27;\\n                self.get_logger().warn(f&#x27;[ABORTED] {result.status_message}&#x27;)\\n                return result\\n\\n            # Simulate incremental linear travel step\\n            step = speed * dt\\n            distance_travelled = min(target, distance_travelled + step)\\n\\n            # Populate feedback telemetry\\n            feedback_msg.distance_remaining_m = float(round(target - distance_travelled, 3))\\n            feedback_msg.current_speed_mps = float(round(speed, 2))\\n            feedback_msg.percent_complete = float(round((distance_travelled / target) * 100.0, 1))\\n\\n            # Stream feedback packet over DDS\\n            goal_handle.publish_feedback(feedback_msg)\\n            self.get_logger().info(\\n                f&#x27;[TRAVERSAL FEEDBACK] Progress: {feedback_msg.percent_complete:5.1f}% | Rem: {feedback_msg.distance_remaining_m:5.2f} m&#x27;\\n            )\\n\\n            time.sleep(dt)\\n\\n        # Transition goal state machine to STATUS_SUCCEEDED\\n        goal_handle.succeed()\\n\\n        # Return terminal result payload\\n        result = NavigateDistance.Result()\\n        result.reached_target = True\\n        result.actual_distance_travelled_m = float(round(distance_travelled, 3))\\n        result.status_message = f&#x27;Target distance of {target:.2f} m reached successfully.&#x27;\\n        self.get_logger().info(f&#x27;[SUCCEEDED] {result.status_message}&#x27;)\\n        return result\\n\\n\\ndef main(args=None):\\n    rclpy.init(args=args)\\n    node = NavigateDistanceSolutionServer()\\n    try:\\n        rclpy.spin(node)\\n    except KeyboardInterrupt:\\n        pass\\n    finally:\\n        node.destroy_node()\\n        rclpy.shutdown()\\n\\n\\nif __name__ == &#x27;__main__&#x27;:\\n    main()\\n</code></pre>\\n    </div>\\n  </div>\\n</details>\\n\\n<div class=\\"code-breakdown-card\\">\\n  <h4 class=\\"code-breakdown-title\\">🔬 Core Code Deep Dive &amp; Operational Breakdown: NavigateDistance Solution Server Breakdown</h4>\\n  <p class=\\"code-breakdown-intro\\">Key takeaways from the Navigate Distance Action Server solution:</p>\\n  <ul class=\\"code-breakdown-list\\">\\n    <li class=\\"code-breakdown-item\\"><strong>Preemption Loop Invariant:</strong> Checking <code>if goal_handle.is_cancel_requested:</code> on every iteration ensures responsiveness. Calling <code>goal_handle.canceled()</code> transitions the state machine cleanly before exiting.</li>\\n    <li class=\\"code-breakdown-item\\"><strong>Incremental Distance Simulation:</strong> <code>distance_travelled = min(target, distance_travelled + speed * dt)</code> simulates realistic physical motion kinematics without overshoot.</li>\\n    <li class=\\"code-breakdown-item\\"><strong>Terminal State Finality:</strong> Calling <code>goal_handle.succeed()</code> marks the action execution as successfully completed, after which the result struct is transmitted to waiting clients.</li>\\n  </ul>\\n</div>\\n\\n<div class=\\"asset-handoff-card\\" style=\\"margin: 1.75rem 0 1rem 0; padding: 1.15rem 1.4rem; border-radius: 10px; background: rgba(16, 185, 129, 0.06); border: 1px solid rgba(16, 185, 129, 0.25); border-left: 4px solid #10b981;\\">\\n  <div style=\\"display: flex; align-items: center; gap: 0.5rem; margin-bottom: 0.5rem;\\">\\n    <span style=\\"font-size: 1.1rem;\\">📦</span>\\n    <strong style=\\"font-size: 0.95rem; color: #10b981; text-transform: uppercase; letter-spacing: 0.04em;\\">Asset Handoff &amp; Next Lesson Pipeline Bridge</strong>\\n  </div>\\n  <p style=\\"margin: 0 0 0.65rem 0; font-size: 0.88rem; color: var(--text-primary); line-height: 1.6;\\">\\n    You have mastered the complete 3-tier Action protocol (Goal Service, Feedback Stream, Result Service) with goal preemption and asynchronous non-blocking tracking for long-running robot navigation tasks.\\n  </p>\\n  <div style=\\"display: flex; flex-wrap: wrap; gap: 0.75rem; font-size: 0.82rem; font-family: var(--font-mono);\\">\\n    <span style=\\"background: var(--bg-surface); border: 1px solid var(--border-color); padding: 0.25rem 0.6rem; border-radius: 5px; color: var(--text-primary);\\">\\n      📁 <strong>Produced Artifact:</strong> <code>nexus_amr_basics/navigate_distance_server.py</code> &amp; <code>navigate_distance_client.py</code>\\n    </span>\\n    <span style=\\"background: var(--bg-surface); border: 1px solid var(--border-color); padding: 0.25rem 0.6rem; border-radius: 5px; color: var(--text-primary);\\">\\n      ➡️ <strong>Ingested By:</strong> Lesson 09 (Day 2: 3D Robot Modeling with URDF &amp; Xacro)\\n    </span>\\n  </div>\\n</div>\\n","quizzes":[{"id":"q_l1_11_1","prompt":"What are the three communication phases of a ROS 2 Action?","options":["Subscribe, Filter, Publish","Goal Request/Acceptance, Continuous Feedback Streaming, and Final Result","Ping, Handshake, Disconnect","Compile, Launch, Terminate"],"correct":1,"explanation":"ROS 2 Actions are designed for long-running preemptible tasks. They communicate via: (1) Goal Request & Acceptance, (2) Periodic Feedback, and (3) Final Result."}],"has_quiz":true,"next_id":"lesson_09","prev_id":"lesson_07","subtopics":[{"id":"1-overview-learning-objectives","title":"1. Overview &amp; Learning Objectives"},{"id":"2-action-communication-architecture","title":"2. Action Communication Architecture"},{"id":"3-building-the-linear-traversal-action-server","title":"3. Building the Linear Traversal Action Server in Python"},{"id":"4-building-the-asynchronous-navigation-action-client","title":"4. Building the Asynchronous Navigation Action Client in Python"},{"id":"5-verification-with-the-ros-2-action-cli","title":"5. Verification with the ROS 2 Action CLI"},{"id":"6-from-navigatedistance-to-robotics-patrol","title":"6. From NavigateDistance to Robotics: Waypoint Patrol &amp; Navigation"},{"id":"7-hands-on-student-challenge","title":"7. Hands-on Student Challenge: Long-Running NavigateDistance Action Server with Feedback"}]},{"id":"lesson_09","num":9,"num_str":"09","title":"3D Robot Modeling with URDF & Xacro","slug":"14_3d_modeling_urdf_xacro","filename":"14_3d_modeling_urdf_xacro.md","module":"Day 2: 3D Robot Modeling & Physics Simulation","module_id":2,"duration":"45-60 min","focus":"Kinematic Tree Modeling, RGB Camera & LiDAR Xacro Integration, Interactive Inertia Calculator & Fusion 360 CAD Export","snapshot":[["URDF/Xacro Digital Twin","Defines the kinematic tree of physical Links and revolute/continuous/fixed Joints for Nexus AMR in clean XML."],["Visual, Collision & Inertial","Partitions realistic 3D appearance, bounding-box collision meshes, and accurate 3D mass inertia tensors ({xx}, I_{yy}, I_{zz}$)."],["Modular Xacro Macros","xacro:macro and xacro:property parameterize wheels, casters, and sensors to eliminate redundant code repetition."],["REP 103 TF Coordinate Tree","Establishes spatial coordinate conventions (+X Forward, +Y Left, +Z Up) linking base_footprint -> base_link -> sensors."]],"html_content":"<h2 id=\\"1-overview-learning-objectives\\">1. Overview &amp; Learning Objectives</h2>\\n<p>Before a robot can navigate, plan paths, or simulate physics in Gazebo, ROS 2 must understand its physical structure: chassis dimensions, wheel locations, center of mass, sensor mount positions, and joint limits.</p>\\n<p>This kinematic and physical representation is defined using <strong>URDF (Unified Robot Description Format)</strong> and <strong>Xacro (XML Macros)</strong>.</p>\\n\\n<div class=\\"learning-objectives-card\\">\\n  <div class=\\"learning-objectives-header\\">\\n    <div class=\\"objectives-icon-badge\\">\\n      <span style=\\"font-size: 1.15rem; line-height: 1;\\">🎯</span>\\n    </div>\\n    <div class=\\"objectives-title-group\\">\\n      <h3 class=\\"objectives-main-title\\">Learning Objectives &amp; Core Outcomes</h3>\\n      <span class=\\"objectives-subtitle\\">By the end of this lesson, you will be able to:</span>\\n    </div>\\n    <span class=\\"objectives-count-badge\\">5 CORE OUTCOMES</span>\\n  </div>\\n  <ul class=\\"learning-objectives-list\\">\\n    <li class=\\"learning-objective-item\\">\\n      <span class=\\"objective-num-badge\\">1</span>\\n      <span class=\\"objective-text\\">Understand the hierarchy of Links and Joints in a differential drive robot.</span>\\n    </li>\\n    <li class=\\"learning-objective-item\\">\\n      <span class=\\"objective-num-badge\\">2</span>\\n      <span class=\\"objective-text\\">Differentiate between Visual, Collision, and Inertial geometry tags.</span>\\n    </li>\\n    <li class=\\"learning-objective-item\\">\\n      <span class=\\"objective-num-badge\\">3</span>\\n      <span class=\\"objective-text\\">Calculate physical 3D Inertia Tensors (I<sub>xx</sub>, I<sub>yy</sub>, I<sub>zz</sub>) for boxes, cylinders, and spheres.</span>\\n    </li>\\n    <li class=\\"learning-objective-item\\">\\n      <span class=\\"objective-num-badge\\">4</span>\\n      <span class=\\"objective-text\\">Use Xacro macros (<code class=\\"inline-code\\">&lt;xacro:macro&gt;</code>) and properties (<code class=\\"inline-code\\">&lt;xacro:property&gt;</code>) to eliminate code duplication.</span>\\n    </li>\\n    <li class=\\"learning-objective-item\\">\\n      <span class=\\"objective-num-badge\\">5</span>\\n      <span class=\\"objective-text\\">Convert Xacro files to clean URDF strings at launch time using the <code class=\\"inline-code\\">xacro</code> command substitution.</span>\\n    </li>\\n  </ul>\\n</div>\\n<div id=\\"interactive-urdf-viewer-root\\"></div>\\n\\n<div class=\\"architecture-specs-card\\" style=\\"margin: 1.5rem 0 2rem 0; border: 1px solid var(--border-color); border-radius: 14px; background: var(--bg-card); overflow: hidden; box-shadow: var(--shadow-sm);\\">\\n  <div style=\\"padding: 1rem 1.6rem 1.5rem 1.6rem;\\">\\n    <h4 style=\\"font-size: 1.05rem; font-weight: 700; color: var(--text-primary); margin: 0.5rem 0 0.85rem 0; display: flex; align-items: center; gap: 0.5rem;\\">\\n      <span>📐</span> Nexus AMR Physical Kinematic Structure &amp; Coordinate Hierarchy\\n    </h4>\\n    <div style=\\"display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 1rem; margin-bottom: 1.25rem;\\">\\n      <div style=\\"background: var(--bg-surface); border: 1px solid var(--border-color); border-radius: 8px; padding: 0.85rem 1rem;\\">\\n        <div style=\\"display: flex; align-items: center; justify-content: space-between; margin-bottom: 0.4rem;\\">\\n          <code style=\\"font-size: 0.88rem; font-weight: 700; color: #06b6d4;\\">base_footprint</code>\\n          <span style=\\"font-size: 0.75rem; color: var(--text-secondary); font-family: var(--font-mono);\\">Ground Datum (Z = 0.0 m)</span>\\n        </div>\\n        <p style=\\"margin: 0; font-size: 0.82rem; color: var(--text-secondary); line-height: 1.5;\\">\\n          Zero-thickness reference plane at the floor contact patch directly beneath the axle center. Used by Nav2 for 2D footprint projection and obstacle costmap inflation.\\n        </p>\\n      </div>\\n\\n      <div style=\\"background: var(--bg-surface); border: 1px solid var(--border-color); border-radius: 8px; padding: 0.85rem 1rem;\\">\\n        <div style=\\"display: flex; align-items: center; justify-content: space-between; margin-bottom: 0.4rem;\\">\\n          <code style=\\"font-size: 0.88rem; font-weight: 700; color: #06b6d4;\\">base_link</code>\\n          <span style=\\"font-size: 0.75rem; color: var(--text-secondary); font-family: var(--font-mono);\\">Chassis Center (Z = +0.06 m)</span>\\n        </div>\\n        <p style=\\"margin: 0; font-size: 0.82rem; color: var(--text-secondary); line-height: 1.5;\\">\\n          The primary 3D structural body (40 × 30 × 14 cm, 8.0 kg). Elevated 0.06m above floor. Root parent for drive wheel continuous joints and perception sensor mounts.\\n        </p>\\n      </div>\\n\\n      <div style=\\"background: var(--bg-surface); border: 1px solid var(--border-color); border-radius: 8px; padding: 0.85rem 1rem;\\">\\n        <div style=\\"display: flex; align-items: center; justify-content: space-between; margin-bottom: 0.4rem;\\">\\n          <code style=\\"font-size: 0.88rem; font-weight: 700; color: #10b981;\\">left / right_wheel_link</code>\\n          <span style=\\"font-size: 0.75rem; color: var(--text-secondary); font-family: var(--font-mono);\\">Actuated Drive (r = 0.06 m)</span>\\n        </div>\\n        <p style=\\"margin: 0; font-size: 0.82rem; color: var(--text-secondary); line-height: 1.5;\\">\\n          Dual independent drive wheels (32 cm track gauge separation, Y = ±0.16m, mass 0.8kg). Continuous revolute joints driven by motor velocity controllers for differential drive steering.\\n        </p>\\n      </div>\\n\\n      <div style=\\"background: var(--bg-surface); border: 1px solid var(--border-color); border-radius: 8px; padding: 0.85rem 1rem;\\">\\n        <div style=\\"display: flex; align-items: center; justify-content: space-between; margin-bottom: 0.4rem;\\">\\n          <code style=\\"font-size: 0.88rem; font-weight: 700; color: #94a3b8;\\">front / rear_caster_link</code>\\n          <span style=\\"font-size: 0.75rem; color: var(--text-secondary); font-family: var(--font-mono);\\">Passive Support (r = 0.03 m)</span>\\n        </div>\\n        <p style=\\"margin: 0; font-size: 0.82rem; color: var(--text-secondary); line-height: 1.5;\\">\\n          Dual spherical low-friction support casters (offset at X = ±0.14m, Z = +0.03m relative to base_footprint, mass 0.3kg) maintaining 3-point static balance and preventing chassis pitching.\\n        </p>\\n      </div>\\n\\n      <div style=\\"background: var(--bg-surface); border: 1px solid var(--border-color); border-radius: 8px; padding: 0.85rem 1rem;\\">\\n        <div style=\\"display: flex; align-items: center; justify-content: space-between; margin-bottom: 0.4rem;\\">\\n          <code style=\\"font-size: 0.88rem; font-weight: 700; color: #f59e0b;\\">laser_frame</code>\\n          <span style=\\"font-size: 0.75rem; color: var(--text-secondary); font-family: var(--font-mono);\\">2D Planar LiDAR (X = +0.08 m, Z = +0.22 m)</span>\\n        </div>\\n        <p style=\\"margin: 0; font-size: 0.82rem; color: var(--text-secondary); line-height: 1.5;\\">\\n          Top-mounted planar LiDAR scanning 360° laser range beams on <code class=\\"inline-code\\">/scan</code> at 10Hz. Crucial for SLAM Toolbox mapping (L18) and Nav2 local costmaps (L19).\\n        </p>\\n      </div>\\n\\n      <div style=\\"background: var(--bg-surface); border: 1px solid var(--border-color); border-radius: 8px; padding: 0.85rem 1rem;\\">\\n        <div style=\\"display: flex; align-items: center; justify-content: space-between; margin-bottom: 0.4rem;\\">\\n          <code style=\\"font-size: 0.88rem; font-weight: 700; color: #8b5cf6;\\">camera_link</code>\\n          <span style=\\"font-size: 0.75rem; color: var(--text-secondary); font-family: var(--font-mono);\\">Student Challenge Sensor</span>\\n        </div>\\n        <p style=\\"margin: 0; font-size: 0.82rem; color: var(--text-secondary); line-height: 1.5;\\">\\n          Forward-facing RGB camera mounted on front bumper (X = +0.20 m, Z = +0.08 m) via camera_joint. Authored by the student in Section 6!\\n        </p>\\n      </div>\\n    </div>\\n\\n    <div style=\\"background: rgba(6, 182, 212, 0.08); border-left: 4px solid #06b6d4; border-radius: 8px; padding: 0.9rem 1.25rem;\\">\\n      <h5 style=\\"margin: 0 0 0.4rem 0; font-size: 0.92rem; font-weight: 700; color: #06b6d4; display: flex; align-items: center; gap: 0.4rem;\\">\\n        <span>🔄</span> End-to-End Curriculum Flow: How This URDF Drives the Rest of Your Course\\n      </h5>\\n      <p style=\\"margin: 0; font-size: 0.85rem; color: var(--text-primary); line-height: 1.6;\\">\\n        The robot model you build in this lesson is <strong>not a temporary exercise</strong>&mdash;it is the foundational physical digital twin that carries across the entire robotics pipeline:\\n      </p>\\n      <ul style=\\"margin: 0.5rem 0 0 1.25rem; padding: 0; font-size: 0.84rem; color: var(--text-secondary); line-height: 1.6;\\">\\n        <li><strong>Lesson 10 (RViz2)</strong> loads this URDF, tests <code class=\\"inline-code\\">robot_state_publisher</code>, and verifies all kinematic coordinate frames.</li>\\n        <li><strong>Lesson 11 (Gazebo)</strong> adds physics inertia, wheel friction, and simulation plugins to this model so it drives and casts laser rays.</li>\\n        <li><strong>Lesson 12 &amp; 13 (Simulation &amp; SLAM)</strong> spawns this AMR into a custom warehouse world to map the building with <code class=\\"inline-code\\">slam_toolbox</code>.</li>\\n        <li><strong>Lessons 19&ndash;21 (Nav2 Stack)</strong> uses this robot's footprint to configure safety costmaps, trajectory planners, and recovery behaviors.</li>\\n        <li><strong>Lesson 16 (Autonomous Mission)</strong> commands this robot to patrol the warehouse autonomously using Python Nav2 Simple Commander!</li>\\n      </ul>\\n    </div>\\n  </div>\\n</div>\\n\\n<hr class=\\"divider\\">\\n<h2 id=\\"2-urdf-anatomy-links-vs-joints\\">2. URDF Anatomy: Links vs. Joints</h2>\\n<p>A robot model in ROS 2 is structured as a <strong>directed acyclic graph (tree)</strong> consisting of rigid physical bodies called <strong>Links</strong> connected by kinematic constraints called <strong>Joints</strong>.</p>\\n\\n<p><img src=\\"assets/images/urdf_kinematic_tree.svg\\" alt=\\"URDF Kinematic Tree and Joint Hierarchy\\" class=\\"lesson-image\\" loading=\\"lazy\\" /></p>\\n\\n<div class=\\"alert alert-info\\">\\n  <div class=\\"alert-title\\">🌳 The Golden Rule of Kinematic Trees</div>\\n  <p>In URDF, every robot must have <strong>exactly one root link</strong> with no parent joint (in mobile robotics, this is <code class=\\"inline-code\\">base_footprint</code>). Every other link must have <strong>exactly one parent link</strong> and one connecting joint. Closed kinematic loops (like parallel four-bar linkages) are strictly forbidden in standard URDF and must be handled via Gazebo SDF plugins or transmission controllers.</p>\\n</div>\\n\\n<div class=\\"code-breakdown-card\\" style=\\"margin: 1.75rem 0; border: 1px solid rgba(14, 165, 233, 0.3); background: rgba(14, 165, 233, 0.03); border-radius: 12px; padding: 1.25rem;\\">\\n  <h4 class=\\"code-breakdown-title\\" style=\\"display: flex; align-items: center; gap: 0.5rem; color: #0284c7; margin-top: 0; font-size: 1.05rem;\\">\\n    <span>📄</span> Canonical URDF File Excerpt: Anatomy of Links, Joints &amp; Physical Tags\\n  </h4>\\n  <p class=\\"code-breakdown-intro\\" style=\\"font-size: 0.9rem; line-height: 1.6; color: var(--text-secondary); margin-bottom: 1.25rem;\\">\\n    In industrial robotics engineering (from articulated robotic arms like the <strong>Universal Robots UR10e</strong> to differential-drive AMRs like our <strong>Nexus AMR</strong>), every robot description file follows a universal tripartite XML hierarchy. Below is an authentic excerpt illustrating how a parent link, connecting joint, and child link are defined:\\n  </p>\\n\\n  <div class=\\"code-container\\" data-language=\\"xml\\" style=\\"margin-bottom: 1.25rem;\\">\\n    <div class=\\"code-header\\"><span class=\\"code-lang-tag\\">xml</span><span style=\\"font-size: 0.8rem; font-family: var(--font-mono); color: #94a3b8;\\">nexus_amr.urdf (URDF File Excerpt)</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n    <pre><code class=\\"language-xml\\">&lt;robot name=\\"nexus_amr\\"&gt;\\n\\n  &lt;!-- ======================================================= --&gt;\\n  &lt;!-- 1. PARENT LINK: Main Chassis Body (base_link)           --&gt;\\n  &lt;!-- ======================================================= --&gt;\\n  &lt;link name=\\"base_link\\"&gt;\\n    &lt;!-- Mass &amp; 3D Moment of Inertia for Physics Engine (Gazebo ODE) --&gt;\\n    &lt;inertial&gt;\\n      &lt;origin xyz=\\"0.00147 0.00038 0.03507\\" rpy=\\"0 0 0\\"/&gt;\\n      &lt;mass value=\\"0.6558\\"/&gt;\\n      &lt;inertia ixx=\\"0.000584\\" iyy=\\"0.002255\\" izz=\\"0.002722\\"\\n               ixy=\\"0.0\\"      iyz=\\"0.0\\"      ixz=\\"-3.3e-05\\"/&gt;\\n    &lt;/inertial&gt;\\n\\n    &lt;!-- 3D Visual Rendering Geometry in RViz2 --&gt;\\n    &lt;visual&gt;\\n      &lt;origin xyz=\\"0 0 0\\" rpy=\\"0 0 0\\"/&gt;\\n      &lt;geometry&gt;\\n        &lt;mesh filename=\\"package://nexus_amr_description/meshes/base_link.stl\\" scale=\\"0.001 0.001 0.001\\"/&gt;\\n      &lt;/geometry&gt;\\n      &lt;material name=\\"silver\\"&gt;\\n        &lt;color rgba=\\"0.700 0.700 0.700 1.000\\"/&gt;\\n      &lt;/material&gt;\\n    &lt;/visual&gt;\\n\\n    &lt;!-- Decoupled Simplified Collision Hull for Fast Physics Contact --&gt;\\n    &lt;collision&gt;\\n      &lt;origin xyz=\\"0 0 0\\" rpy=\\"0 0 0\\"/&gt;\\n      &lt;geometry&gt;\\n        &lt;mesh filename=\\"package://nexus_amr_description/meshes/base_link.stl\\" scale=\\"0.001 0.001 0.001\\"/&gt;\\n      &lt;/geometry&gt;\\n    &lt;/collision&gt;\\n  &lt;/link&gt;\\n\\n  &lt;!-- ======================================================= --&gt;\\n  &lt;!-- 2. KINEMATIC JOINT: Right Traction Motor (Continuous)   --&gt;\\n  &lt;!-- ======================================================= --&gt;\\n  &lt;joint name=\\"right_motor\\" type=\\"continuous\\"&gt;\\n    &lt;parent link=\\"base_link\\"/&gt;\\n    &lt;child link=\\"right_wheel_1\\"/&gt;\\n    &lt;origin xyz=\\"0.05612 -0.05162 0.03500\\" rpy=\\"0 0 0\\"/&gt;\\n    &lt;axis xyz=\\"0.0 1.0 0.0\\"/&gt;\\n    &lt;limit effort=\\"10.0\\" velocity=\\"12.5\\"/&gt;\\n    &lt;dynamics damping=\\"0.05\\" friction=\\"0.01\\"/&gt;\\n  &lt;/joint&gt;\\n\\n  &lt;!-- ======================================================= --&gt;\\n  &lt;!-- 3. CHILD LINK: Driven Right Wheel Subassembly           --&gt;\\n  &lt;!-- ======================================================= --&gt;\\n  &lt;link name=\\"right_wheel_1\\"&gt;\\n    &lt;inertial&gt;\\n      &lt;origin xyz=\\"0.0 -0.005 0.0\\" rpy=\\"0 0 0\\"/&gt;\\n      &lt;mass value=\\"0.0358\\"/&gt;\\n      &lt;inertia ixx=\\"1.1e-05\\" iyy=\\"2.2e-05\\" izz=\\"1.1e-05\\"\\n               ixy=\\"0.0\\"     iyz=\\"0.0\\"     ixz=\\"0.0\\"/&gt;\\n    &lt;/inertial&gt;\\n    &lt;visual&gt;\\n      &lt;origin xyz=\\"-0.05612 0.05162 -0.03500\\" rpy=\\"0 0 0\\"/&gt;\\n      &lt;geometry&gt;\\n        &lt;mesh filename=\\"package://nexus_amr_description/meshes/right_wheel_1.stl\\" scale=\\"0.001 0.001 0.001\\"/&gt;\\n      &lt;/geometry&gt;\\n      &lt;material name=\\"black\\"&gt;\\n        &lt;color rgba=\\"0.05 0.05 0.05 1.000\\"/&gt;\\n      &lt;/material&gt;\\n    &lt;/visual&gt;\\n    &lt;collision&gt;\\n      &lt;origin xyz=\\"-0.05612 0.05162 -0.03500\\" rpy=\\"0 0 0\\"/&gt;\\n      &lt;geometry&gt;\\n        &lt;mesh filename=\\"package://nexus_amr_description/meshes/right_wheel_1.stl\\" scale=\\"0.001 0.001 0.001\\"/&gt;\\n      &lt;/geometry&gt;\\n    &lt;/collision&gt;\\n  &lt;/link&gt;\\n\\n&lt;/robot&gt;</code></pre>\\n  </div>\\n\\n  <div style=\\"display: grid; grid-template-columns: repeat(auto-fit, minmax(240px, 1fr)); gap: 0.85rem;\\">\\n    <div style=\\"background: var(--bg-surface); border: 1px solid rgba(2, 132, 199, 0.3); border-left: 4px solid #0284c7; border-radius: 8px; padding: 0.85rem;\\">\\n      <h5 style=\\"margin: 0 0 0.35rem 0; font-size: 0.88rem; color: #0284c7;\\">🔵 Visual Geometry (&lt;visual&gt;)</h5>\\n      <p style=\\"margin: 0; font-size: 0.82rem; line-height: 1.45; color: var(--text-secondary);\\">\\n        Directs RViz2 rendering. Defines 3D mesh files (STL/DAE) or geometric primitives (<code>&lt;box&gt;</code>, <code>&lt;cylinder&gt;</code>, <code>&lt;sphere&gt;</code>) along with RGBA surface coloring and material shaders.\\n      </p>\\n    </div>\\n    <div style=\\"background: var(--bg-surface); border: 1px solid rgba(245, 158, 11, 0.3); border-left: 4px solid #f59e0b; border-radius: 8px; padding: 0.85rem;\\">\\n      <h5 style=\\"margin: 0 0 0.35rem 0; font-size: 0.88rem; color: #f59e0b;\\">🟠 Collision Boundary (&lt;collision&gt;)</h5>\\n      <p style=\\"margin: 0; font-size: 0.82rem; line-height: 1.45; color: var(--text-secondary);\\">\\n        Decoupled physical bounding surface evaluated by Gazebo contact solvers and Nav2 obstacle detectors. Simplified geometry prevents massive simulation FPS drops.\\n      </p>\\n    </div>\\n    <div style=\\"background: var(--bg-surface); border: 1px solid rgba(16, 185, 129, 0.3); border-left: 4px solid #10b981; border-radius: 8px; padding: 0.85rem;\\">\\n      <h5 style=\\"margin: 0 0 0.35rem 0; font-size: 0.88rem; color: #10b981;\\">🟢 Inertial Dynamics (&lt;inertial&gt;)</h5>\\n      <p style=\\"margin: 0; font-size: 0.82rem; line-height: 1.45; color: var(--text-secondary);\\">\\n        Mandatory for physics simulation. Encapsulates physical mass (kg), Center of Mass offset (CoM), and the 3&times;3 symmetric rotational inertia matrix tensor (<code>ixx, iyy, izz, ixy, ixz, iyz</code>).\\n      </p>\\n    </div>\\n    <div style=\\"background: var(--bg-surface); border: 1px solid rgba(139, 92, 246, 0.3); border-left: 4px solid #8b5cf6; border-radius: 8px; padding: 0.85rem;\\">\\n      <h5 style=\\"margin: 0 0 0.35rem 0; font-size: 0.88rem; color: #8b5cf6;\\">🟣 Kinematic Joint (&lt;joint&gt;)</h5>\\n      <p style=\\"margin: 0; font-size: 0.82rem; line-height: 1.45; color: var(--text-secondary);\\">\\n        Binds <code>&lt;parent&gt;</code> to <code>&lt;child&gt;</code>. Enforces 3D transform origin (<code>xyz/rpy</code>), degree-of-freedom actuation axis (<code>&lt;axis&gt;</code>), motion/effort limits (<code>&lt;limit&gt;</code>), and friction (<code>&lt;dynamics&gt;</code>).\\n      </p>\\n    </div>\\n  </div>\\n</div>\\n\\n<h3 id=\\"21-nexus-amr-kinematic-anatomy-table\\">2.1 Nexus AMR Kinematic Hierarchy &amp; Specification Table</h3>\\n<p>The following table details the complete mechanical anatomy of our Nexus AMR as defined in <code class=\\"inline-code\\">nexus_amr.urdf.xacro</code>, incorporating high-fidelity CAD meshes exported from Autodesk Fusion 360:</p>\\n\\n<div class=\\"table-responsive\\">\\n  <table>\\n    <thead>\\n      <tr>\\n        <th>Child Link Name</th>\\n        <th>Parent Joint</th>\\n        <th>Joint Type</th>\\n        <th>Relative Origin (<code class=\\"inline-code\\">xyz</code>, <code class=\\"inline-code\\">rpy</code>)</th>\\n        <th>Physical Properties &amp; CAD Mesh</th>\\n        <th>Functional Role in Pipeline</th>\\n      </tr>\\n    </thead>\\n    <tbody>\\n      <tr>\\n        <td><strong style=\\"color: #06b6d4;\\">base_footprint</strong></td>\\n        <td><em>None (Root)</em></td>\\n        <td><span class=\\"badge\\" style=\\"background: rgba(148, 163, 184, 0.2); color: var(--text-primary); border: 1px solid rgba(148, 163, 184, 0.4); padding: 0.15rem 0.5rem; border-radius: 4px; font-size: 0.75rem; font-weight: 700;\\">ROOT</span></td>\\n        <td><code class=\\"inline-code\\">0 0 0</code> (Z=0 datum)</td>\\n        <td>Zero-mass virtual ground projection plane</td>\\n        <td>Ground reference on floor for Nav2 costmaps &amp; 2D footprints</td>\\n      </tr>\\n      <tr>\\n        <td><strong style=\\"color: #06b6d4;\\">base_link</strong></td>\\n        <td><code class=\\"inline-code\\">base_footprint_joint</code></td>\\n        <td><span class=\\"badge\\" style=\\"background: rgba(148, 163, 184, 0.15); color: #64748b; border: 1px solid rgba(148, 163, 184, 0.3); padding: 0.15rem 0.5rem; border-radius: 4px; font-size: 0.75rem; font-weight: 700;\\">fixed</span></td>\\n        <td><code class=\\"inline-code\\">0 0 0.005</code></td>\\n        <td>CAD Mesh (<code class=\\"inline-code\\">base_link.stl</code>, scale: 0.001), mass: 0.656 kg</td>\\n        <td>Main robot structural chassis &amp; vehicle body center of mass</td>\\n      </tr>\\n      <tr>\\n        <td><strong style=\\"color: #10b981;\\">left_wheel_1</strong></td>\\n        <td><code class=\\"inline-code\\">left_motor</code></td>\\n        <td><span class=\\"badge\\" style=\\"background: rgba(16, 185, 129, 0.15); color: #10b981; border: 1px solid rgba(16, 185, 129, 0.3); padding: 0.15rem 0.5rem; border-radius: 4px; font-size: 0.75rem; font-weight: 700;\\">continuous</span></td>\\n        <td><code class=\\"inline-code\\">0.0561 0.0524 0.035</code>, axis: <code class=\\"inline-code\\">[0 1 0]</code></td>\\n        <td>CAD Mesh (<code class=\\"inline-code\\">left_wheel_1.stl</code>, diameter: 0.06m), mass: 0.036 kg</td>\\n        <td>Actuated port-side drive wheel powered by diff-drive controller</td>\\n      </tr>\\n      <tr>\\n        <td><strong style=\\"color: #10b981;\\">right_wheel_1</strong></td>\\n        <td><code class=\\"inline-code\\">right_motor</code></td>\\n        <td><span class=\\"badge\\" style=\\"background: rgba(16, 185, 129, 0.15); color: #10b981; border: 1px solid rgba(16, 185, 129, 0.3); padding: 0.15rem 0.5rem; border-radius: 4px; font-size: 0.75rem; font-weight: 700;\\">continuous</span></td>\\n        <td><code class=\\"inline-code\\">0.0561 -0.0516 0.035</code>, axis: <code class=\\"inline-code\\">[0 1 0]</code></td>\\n        <td>CAD Mesh (<code class=\\"inline-code\\">right_wheel_1.stl</code>, diameter: 0.06m), mass: 0.036 kg</td>\\n        <td>Actuated starboard drive wheel powered by diff-drive controller</td>\\n      </tr>\\n      <tr>\\n        <td><strong style=\\"color: #f59e0b;\\">caster_wheel</strong></td>\\n        <td><code class=\\"inline-code\\">caster_joint</code></td>\\n        <td><span class=\\"badge\\" style=\\"background: rgba(148, 163, 184, 0.15); color: #64748b; border: 1px solid rgba(148, 163, 184, 0.3); padding: 0.15rem 0.5rem; border-radius: 4px; font-size: 0.75rem; font-weight: 700;\\">fixed</span></td>\\n        <td><code class=\\"inline-code\\">-0.08 0 0.01</code></td>\\n        <td>Sphere (radius: 0.015m, low friction <code class=\\"inline-code\\">mu=0.001</code>), mass: 0.05 kg</td>\\n        <td>Passive rear contact point balancing chassis and preventing pitch</td>\\n      </tr>\\n      <tr>\\n        <td><strong style=\\"color: #3b82f6;\\">lidar_1</strong></td>\\n        <td><code class=\\"inline-code\\">lidar_joint</code></td>\\n        <td><span class=\\"badge\\" style=\\"background: rgba(148, 163, 184, 0.15); color: #64748b; border: 1px solid rgba(148, 163, 184, 0.3); padding: 0.15rem 0.5rem; border-radius: 4px; font-size: 0.75rem; font-weight: 700;\\">fixed</span></td>\\n        <td><code class=\\"inline-code\\">0.0661 0.0004 0.06</code></td>\\n        <td>CAD Mesh (<code class=\\"inline-code\\">lidar_1.stl</code>), mass: 0.015 kg</td>\\n        <td>360-degree 2D planar LiDAR scanner for SLAM &amp; Nav2 obstacle avoidance</td>\\n      </tr>\\n      <tr>\\n        <td><strong style=\\"color: #8b5cf6;\\">camera_1</strong></td>\\n        <td><code class=\\"inline-code\\">cam_joint</code></td>\\n        <td><span class=\\"badge\\" style=\\"background: rgba(148, 163, 184, 0.15); color: #64748b; border: 1px solid rgba(148, 163, 184, 0.3); padding: 0.15rem 0.5rem; border-radius: 4px; font-size: 0.75rem; font-weight: 700;\\">fixed</span></td>\\n        <td><code class=\\"inline-code\\">0.1011 0.0004 0.035</code></td>\\n        <td>CAD Mesh (<code class=\\"inline-code\\">camera_1.stl</code>), mass: 0.00034 kg</td>\\n        <td>Front-facing RGB optical camera for visual perception and object detection</td>\\n      </tr>\\n    </tbody>\\n  </table>\\n</div>\\n\\n<h3 id=\\"22-urdf-joint-types-animated-comparison\\">2.2 URDF Joint Types &amp; Degrees of Freedom (DOF)</h3>\\n<p>URDF provides standard joint types to define kinematic constraints between links. Each joint specifies degrees of freedom, parent/child relationships, coordinate transform origins, rotation/translation axes, and physical limits:</p>\\n\\n<div style=\\"display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 1.25rem; margin: 1.5rem 0;\\">\\n  <!-- Card 1: Continuous Joint -->\\n  <div style=\\"background: var(--bg-surface); border: 1px solid var(--border-color); border-radius: 12px; padding: 1.25rem; border-top: 4px solid #10b981; display: flex; flex-direction: column; justify-content: space-between;\\">\\n    <div>\\n      <div style=\\"display: flex; align-items: center; justify-content: space-between; margin-bottom: 0.65rem;\\">\\n        <h4 style=\\"margin: 0; font-size: 1rem; font-weight: 700; color: #10b981;\\">1. Continuous Joint</h4>\\n        <span style=\\"font-size: 0.75rem; font-family: var(--font-mono); background: rgba(16, 185, 129, 0.1); color: #10b981; padding: 0.15rem 0.5rem; border-radius: 4px; font-weight: 700;\\">1 DOF (&infin; Rotation)</span>\\n      </div>\\n\\n      <!-- Animation -->\\n      <div style=\\"background: rgba(16, 185, 129, 0.04); border: 1px solid rgba(16, 185, 129, 0.2); border-radius: 8px; padding: 0.5rem; margin-bottom: 0.85rem; display: flex; justify-content: center; align-items: center; height: 110px; overflow: hidden;\\">\\n        <svg viewBox=\\"0 0 200 110\\" width=\\"100%\\" height=\\"110\\" style=\\"max-width: 200px;\\">\\n          <defs>\\n            <style>\\n              @keyframes spinC1 { from { transform: rotate(0deg); } to { transform: rotate(360deg); } }\\n              @keyframes dashC1 { from { stroke-dashoffset: 0; } to { stroke-dashoffset: -32; } }\\n              .spin-c1 { transform-origin: 100px 55px; animation: spinC1 2.5s linear infinite; }\\n              .orbit-c1 { stroke-dasharray: 5 4; animation: dashC1 1.5s linear infinite; }\\n            </style>\\n          </defs>\\n          <circle cx=\\"100\\" cy=\\"55\\" r=\\"42\\" fill=\\"none\\" stroke=\\"rgba(16, 185, 129, 0.25)\\" stroke-width=\\"1.5\\" />\\n          <circle cx=\\"100\\" cy=\\"55\\" r=\\"42\\" fill=\\"none\\" stroke=\\"#10b981\\" stroke-width=\\"1.8\\" class=\\"orbit-c1\\" />\\n          <line x1=\\"45\\" y1=\\"55\\" x2=\\"155\\" y2=\\"55\\" stroke=\\"#64748b\\" stroke-width=\\"3\\" stroke-linecap=\\"round\\" />\\n          <g class=\\"spin-c1\\">\\n            <circle cx=\\"100\\" cy=\\"55\\" r=\\"32\\" fill=\\"#1e293b\\" stroke=\\"#059669\\" stroke-width=\\"2\\" />\\n            <circle cx=\\"100\\" cy=\\"55\\" r=\\"22\\" fill=\\"#334155\\" />\\n            <circle cx=\\"100\\" cy=\\"55\\" r=\\"8\\" fill=\\"#10b981\\" />\\n            <line x1=\\"100\\" y1=\\"23\\" x2=\\"100\\" y2=\\"87\\" stroke=\\"#e2e8f0\\" stroke-width=\\"1.5\\" />\\n            <line x1=\\"68\\" y1=\\"55\\" x2=\\"132\\" y2=\\"55\\" stroke=\\"#e2e8f0\\" stroke-width=\\"1.5\\" />\\n            <line x1=\\"77\\" y1=\\"32\\" x2=\\"123\\" y2=\\"78\\" stroke=\\"#e2e8f0\\" stroke-width=\\"1.5\\" />\\n            <line x1=\\"77\\" y1=\\"78\\" x2=\\"123\\" y2=\\"32\\" stroke=\\"#e2e8f0\\" stroke-width=\\"1.5\\" />\\n            <circle cx=\\"100\\" cy=\\"25\\" r=\\"3\\" fill=\\"#facc15\\" />\\n          </g>\\n          <circle cx=\\"100\\" cy=\\"55\\" r=\\"3.5\\" fill=\\"#ffffff\\" stroke=\\"#0f172a\\" stroke-width=\\"1.5\\" />\\n        </svg>\\n      </div>\\n\\n      <!-- Description -->\\n      <p style=\\"font-size: 0.84rem; color: var(--text-secondary); line-height: 1.5; margin: 0 0 0.85rem 0;\\">\\n        Continuous rotation with <strong>no upper or lower angular limits</strong>. Ideal for driving wheels, continuous casters, or rotating LiDAR scanning turrets.\\n      </p>\\n    </div>\\n\\n    <!-- URDF Syntax -->\\n    <div class=\\"code-container\\" data-language=\\"xml\\" style=\\"margin: 0;\\">\\n      <pre style=\\"margin: 0; font-size: 0.76rem;\\"><code class=\\"language-xml\\">&lt;joint name=\\"left_wheel_joint\\" type=\\"continuous\\"&gt;\\n  &lt;parent link=\\"base_link\\"/&gt;\\n  &lt;child link=\\"left_wheel_link\\"/&gt;\\n  &lt;origin xyz=\\"0 0.16 0\\" rpy=\\"0 0 0\\"/&gt;\\n  &lt;axis xyz=\\"0 1 0\\"/&gt;\\n&lt;/joint&gt;</code></pre>\\n    </div>\\n  </div>\\n\\n  <!-- Card 2: Revolute Joint -->\\n  <div style=\\"background: var(--bg-surface); border: 1px solid var(--border-color); border-radius: 12px; padding: 1.25rem; border-top: 4px solid #06b6d4; display: flex; flex-direction: column; justify-content: space-between;\\">\\n    <div>\\n      <div style=\\"display: flex; align-items: center; justify-content: space-between; margin-bottom: 0.65rem;\\">\\n        <h4 style=\\"margin: 0; font-size: 1rem; font-weight: 700; color: #06b6d4;\\">2. Revolute Joint</h4>\\n        <span style=\\"font-size: 0.75rem; font-family: var(--font-mono); background: rgba(6, 182, 212, 0.1); color: #06b6d4; padding: 0.15rem 0.5rem; border-radius: 4px; font-weight: 700;\\">1 DOF (Bounded &theta;)</span>\\n      </div>\\n\\n      <!-- Animation -->\\n      <div style=\\"background: rgba(6, 182, 212, 0.04); border: 1px solid rgba(6, 182, 212, 0.2); border-radius: 8px; padding: 0.5rem; margin-bottom: 0.85rem; display: flex; justify-content: center; align-items: center; height: 110px; overflow: hidden;\\">\\n        <svg viewBox=\\"0 0 200 110\\" width=\\"100%\\" height=\\"110\\" style=\\"max-width: 200px;\\">\\n          <defs>\\n            <style>\\n              @keyframes swingC2 { 0% { transform: rotate(-55deg); } 50% { transform: rotate(55deg); } 100% { transform: rotate(-55deg); } }\\n              .arm-c2 { transform-origin: 100px 85px; animation: swingC2 3s ease-in-out infinite; }\\n            </style>\\n          </defs>\\n          <rect x=\\"84\\" y=\\"80\\" width=\\"32\\" height=\\"20\\" rx=\\"3\\" fill=\\"#334155\\" stroke=\\"#64748b\\" stroke-width=\\"1.2\\" />\\n          <path d=\\"M 64 35 A 50 50 0 0 1 136 35 L 100 85 Z\\" fill=\\"rgba(6, 182, 212, 0.12)\\" />\\n          <path d=\\"M 58 35 A 50 50 0 0 1 142 35\\" fill=\\"none\\" stroke=\\"#06b6d4\\" stroke-width=\\"1.2\\" stroke-dasharray=\\"3 3\\" />\\n          <circle cx=\\"58\\" cy=\\"35\\" r=\\"3.5\\" fill=\\"#ef4444\\" stroke=\\"#991b1b\\" stroke-width=\\"1\\" />\\n          <circle cx=\\"142\\" cy=\\"35\\" r=\\"3.5\\" fill=\\"#ef4444\\" stroke=\\"#991b1b\\" stroke-width=\\"1\\" />\\n          <text x=\\"44\\" y=\\"30\\" font-family=\\"monospace\\" font-size=\\"7.5\\" font-weight=\\"700\\" fill=\\"#ef4444\\">-55°</text>\\n          <text x=\\"144\\" y=\\"30\\" font-family=\\"monospace\\" font-size=\\"7.5\\" font-weight=\\"700\\" fill=\\"#ef4444\\">+55°</text>\\n          <line x1=\\"100\\" y1=\\"30\\" x2=\\"100\\" y2=\\"40\\" stroke=\\"#0891b2\\" stroke-width=\\"1.2\\" />\\n          <g class=\\"arm-c2\\">\\n            <line x1=\\"100\\" y1=\\"85\\" x2=\\"100\\" y2=\\"35\\" stroke=\\"#0891b2\\" stroke-width=\\"5\\" stroke-linecap=\\"round\\" />\\n            <line x1=\\"100\\" y1=\\"85\\" x2=\\"100\\" y2=\\"35\\" stroke=\\"#38bdf8\\" stroke-width=\\"2\\" stroke-linecap=\\"round\\" />\\n            <circle cx=\\"100\\" cy=\\"35\\" r=\\"5\\" fill=\\"#06b6d4\\" stroke=\\"#ffffff\\" stroke-width=\\"1.2\\" />\\n          </g>\\n          <circle cx=\\"100\\" cy=\\"85\\" r=\\"5\\" fill=\\"#ffffff\\" stroke=\\"#0e7490\\" stroke-width=\\"2\\" />\\n          <circle cx=\\"100\\" cy=\\"85\\" r=\\"2\\" fill=\\"#0e7490\\" />\\n        </svg>\\n      </div>\\n\\n      <!-- Description -->\\n      <p style=\\"font-size: 0.84rem; color: var(--text-secondary); line-height: 1.5; margin: 0 0 0.85rem 0;\\">\\n        Rotation <strong>bounded by hard mechanical limits</strong>. Requires <code class=\\"inline-code\\">&lt;limit lower upper effort velocity&gt;</code>. Used for robotic arm elbows, Ackermann steering, and pan-tilt gimbals.\\n      </p>\\n    </div>\\n\\n    <!-- URDF Syntax -->\\n    <div class=\\"code-container\\" data-language=\\"xml\\" style=\\"margin: 0;\\">\\n      <pre style=\\"margin: 0; font-size: 0.76rem;\\"><code class=\\"language-xml\\">&lt;joint name=\\"steer_joint\\" type=\\"revolute\\"&gt;\\n  &lt;parent link=\\"base_link\\"/&gt;\\n  &lt;child link=\\"steer_knuckle\\"/&gt;\\n  &lt;origin xyz=\\"0.2 0 0\\"/&gt;\\n  &lt;axis xyz=\\"0 0 1\\"/&gt;\\n  &lt;limit lower=\\"-0.785\\" upper=\\"0.785\\"\\n         effort=\\"15.0\\" velocity=\\"2.0\\"/&gt;\\n&lt;/joint&gt;</code></pre>\\n    </div>\\n  </div>\\n\\n  <!-- Card 3: Prismatic Joint -->\\n  <div style=\\"background: var(--bg-surface); border: 1px solid var(--border-color); border-radius: 12px; padding: 1.25rem; border-top: 4px solid #f59e0b; display: flex; flex-direction: column; justify-content: space-between;\\">\\n    <div>\\n      <div style=\\"display: flex; align-items: center; justify-content: space-between; margin-bottom: 0.65rem;\\">\\n        <h4 style=\\"margin: 0; font-size: 1rem; font-weight: 700; color: #f59e0b;\\">3. Prismatic Joint</h4>\\n        <span style=\\"font-size: 0.75rem; font-family: var(--font-mono); background: rgba(245, 158, 11, 0.1); color: #f59e0b; padding: 0.15rem 0.5rem; border-radius: 4px; font-weight: 700;\\">1 DOF (Linear Stroke)</span>\\n      </div>\\n\\n      <!-- Animation -->\\n      <div style=\\"background: rgba(245, 158, 11, 0.04); border: 1px solid rgba(245, 158, 11, 0.2); border-radius: 8px; padding: 0.5rem; margin-bottom: 0.85rem; display: flex; justify-content: center; align-items: center; height: 110px; overflow: hidden;\\">\\n        <svg viewBox=\\"0 0 200 110\\" width=\\"100%\\" height=\\"110\\" style=\\"max-width: 200px;\\">\\n          <defs>\\n            <style>\\n              @keyframes slideC3 { 0% { transform: translateY(0px); } 50% { transform: translateY(-50px); } 100% { transform: translateY(0px); } }\\n              .carriage-c3 { animation: slideC3 2.8s ease-in-out infinite; }\\n            </style>\\n          </defs>\\n          <rect x=\\"64\\" y=\\"20\\" width=\\"6\\" height=\\"75\\" rx=\\"1.5\\" fill=\\"#94a3b8\\" stroke=\\"#64748b\\" stroke-width=\\"1\\" />\\n          <rect x=\\"130\\" y=\\"20\\" width=\\"6\\" height=\\"75\\" rx=\\"1.5\\" fill=\\"#94a3b8\\" stroke=\\"#64748b\\" stroke-width=\\"1\\" />\\n          <line x1=\\"58\\" y1=\\"26\\" x2=\\"142\\" y2=\\"26\\" stroke=\\"#ef4444\\" stroke-width=\\"2\\" />\\n          <text x=\\"146\\" y=\\"29\\" font-family=\\"monospace\\" font-size=\\"7.5\\" font-weight=\\"700\\" fill=\\"#ef4444\\">Upper</text>\\n          <line x1=\\"58\\" y1=\\"90\\" x2=\\"142\\" y2=\\"90\\" stroke=\\"#ef4444\\" stroke-width=\\"2\\" />\\n          <text x=\\"146\\" y=\\"93\\" font-family=\\"monospace\\" font-size=\\"7.5\\" font-weight=\\"700\\" fill=\\"#ef4444\\">Lower</text>\\n          <line x1=\\"100\\" y1=\\"80\\" x2=\\"100\\" y2=\\"35\\" stroke=\\"#f59e0b\\" stroke-width=\\"1.5\\" stroke-dasharray=\\"3 2\\" />\\n          <polygon points=\\"100,30 97,36 103,36\\" fill=\\"#f59e0b\\" />\\n          <g transform=\\"translate(0, 83)\\">\\n            <g class=\\"carriage-c3\\">\\n              <rect x=\\"68\\" y=\\"-7\\" width=\\"64\\" height=\\"14\\" rx=\\"2.5\\" fill=\\"#f59e0b\\" stroke=\\"#b45309\\" stroke-width=\\"1.2\\" />\\n              <rect x=\\"74\\" y=\\"-5\\" width=\\"52\\" height=\\"10\\" rx=\\"1.5\\" fill=\\"#fbbf24\\" />\\n              <circle cx=\\"67\\" cy=\\"0\\" r=\\"3.5\\" fill=\\"#1e293b\\" stroke=\\"#64748b\\" stroke-width=\\"1\\" />\\n              <circle cx=\\"133\\" cy=\\"0\\" r=\\"3.5\\" fill=\\"#1e293b\\" stroke=\\"#64748b\\" stroke-width=\\"1\\" />\\n              <rect x=\\"56\\" y=\\"5\\" width=\\"88\\" height=\\"3\\" rx=\\"1\\" fill=\\"#334155\\" />\\n            </g>\\n          </g>\\n        </svg>\\n      </div>\\n\\n      <!-- Description -->\\n      <p style=\\"font-size: 0.84rem; color: var(--text-secondary); line-height: 1.5; margin: 0 0 0.85rem 0;\\">\\n        Pure <strong>linear translation</strong> along a single axis vector with displacement limits (in meters). Used for forklift pallet lifters, linear slides, and parallel grippers.\\n      </p>\\n    </div>\\n\\n    <!-- URDF Syntax -->\\n    <div class=\\"code-container\\" data-language=\\"xml\\" style=\\"margin: 0;\\">\\n      <pre style=\\"margin: 0; font-size: 0.76rem;\\"><code class=\\"language-xml\\">&lt;joint name=\\"lift_joint\\" type=\\"prismatic\\"&gt;\\n  &lt;parent link=\\"base_link\\"/&gt;\\n  &lt;child link=\\"fork_carriage\\"/&gt;\\n  &lt;origin xyz=\\"0.15 0 0.1\\"/&gt;\\n  &lt;axis xyz=\\"0 0 1\\"/&gt;\\n  &lt;limit lower=\\"0.0\\" upper=\\"0.85\\"\\n         effort=\\"200.0\\" velocity=\\"0.2\\"/&gt;\\n&lt;/joint&gt;</code></pre>\\n    </div>\\n  </div>\\n\\n  <!-- Card 4: Fixed Joint -->\\n  <div style=\\"background: var(--bg-surface); border: 1px solid var(--border-color); border-radius: 12px; padding: 1.25rem; border-top: 4px solid #6366f1; display: flex; flex-direction: column; justify-content: space-between;\\">\\n    <div>\\n      <div style=\\"display: flex; align-items: center; justify-content: space-between; margin-bottom: 0.65rem;\\">\\n        <h4 style=\\"margin: 0; font-size: 1rem; font-weight: 700; color: #6366f1;\\">4. Fixed Joint</h4>\\n        <span style=\\"font-size: 0.75rem; font-family: var(--font-mono); background: rgba(99, 102, 241, 0.1); color: #6366f1; padding: 0.15rem 0.5rem; border-radius: 4px; font-weight: 700;\\">0 DOF (Rigid Welded)</span>\\n      </div>\\n\\n      <!-- Animation -->\\n      <div style=\\"background: rgba(99, 102, 241, 0.04); border: 1px solid rgba(99, 102, 241, 0.2); border-radius: 8px; padding: 0.5rem; margin-bottom: 0.85rem; display: flex; justify-content: center; align-items: center; height: 110px; overflow: hidden;\\">\\n        <svg viewBox=\\"0 0 200 110\\" width=\\"100%\\" height=\\"110\\" style=\\"max-width: 200px;\\">\\n          <defs>\\n            <style>\\n              @keyframes pulseC4 { 0%, 100% { transform: scale(1); opacity: 0.9; } 50% { transform: scale(1.1); opacity: 1; } }\\n              .lock-c4 { transform-origin: 0px 0px; animation: pulseC4 2.2s ease-in-out infinite; }\\n              @keyframes boltC4 { 0%, 100% { stroke: #6366f1; } 50% { stroke: #a5b4fc; } }\\n              .bolt-c4 { animation: boltC4 2s ease-in-out infinite; }\\n            </style>\\n          </defs>\\n          <rect x=\\"35\\" y=\\"75\\" width=\\"130\\" height=\\"18\\" rx=\\"3\\" fill=\\"#4338ca\\" stroke=\\"#312e81\\" stroke-width=\\"1.2\\" />\\n          <text x=\\"100\\" y=\\"87\\" font-family=\\"system-ui, sans-serif\\" font-size=\\"7.5\\" font-weight=\\"700\\" fill=\\"#ffffff\\" text-anchor=\\"middle\\">Parent: base_link</text>\\n          <polygon points=\\"65,75 75,55 79,75\\" fill=\\"#6366f1\\" />\\n          <polygon points=\\"135,75 125,55 121,75\\" fill=\\"#6366f1\\" />\\n          <path d=\\"M 72 75 Q 76 70 80 75 Q 84 70 88 75 Q 92 70 96 75 Q 100 70 104 75 Q 108 70 112 75 Q 116 70 120 75 Q 124 70 128 75\\" fill=\\"none\\" stroke=\\"#f59e0b\\" stroke-width=\\"2\\" stroke-linecap=\\"round\\" />\\n          <rect x=\\"74\\" y=\\"40\\" width=\\"52\\" height=\\"32\\" rx=\\"4\\" fill=\\"#f97316\\" stroke=\\"#c2410c\\" stroke-width=\\"1.2\\" />\\n          <text x=\\"100\\" y=\\"60\\" font-family=\\"monospace\\" font-size=\\"7.5\\" font-weight=\\"700\\" fill=\\"#ffffff\\" text-anchor=\\"middle\\">laser_frame</text>\\n          <circle cx=\\"50\\" cy=\\"84\\" r=\\"3\\" fill=\\"#ffffff\\" stroke=\\"#6366f1\\" stroke-width=\\"1.2\\" class=\\"bolt-c4\\" />\\n          <circle cx=\\"150\\" cy=\\"84\\" r=\\"3\\" fill=\\"#ffffff\\" stroke=\\"#6366f1\\" stroke-width=\\"1.2\\" class=\\"bolt-c4\\" />\\n          <g transform=\\"translate(100, 30)\\">\\n            <g class=\\"lock-c4\\">\\n              <circle cx=\\"0\\" cy=\\"0\\" r=\\"11\\" fill=\\"#ffffff\\" stroke=\\"#4f46e5\\" stroke-width=\\"1.8\\" />\\n              <path d=\\"M -4 -2 L -4 -6 A 4 4 0 0 1 4 -6 L 4 -2\\" fill=\\"none\\" stroke=\\"#4f46e5\\" stroke-width=\\"1.8\\" stroke-linecap=\\"round\\" />\\n              <rect x=\\"-6\\" y=\\"-2\\" width=\\"12\\" height=\\"8\\" rx=\\"1.5\\" fill=\\"#4f46e5\\" />\\n              <circle cx=\\"0\\" cy=\\"2\\" r=\\"1.2\\" fill=\\"#ffffff\\" />\\n            </g>\\n          </g>\\n        </svg>\\n      </div>\\n\\n      <!-- Description -->\\n      <p style=\\"font-size: 0.84rem; color: var(--text-secondary); line-height: 1.5; margin: 0 0 0.85rem 0;\\">\\n        <strong>Zero degrees of freedom</strong>. Locks parent and child rigidly together at a static 6-DOF transform offset. Used for chassis weldments, sensor brackets, and optical virtual frames.\\n      </p>\\n    </div>\\n\\n    <!-- URDF Syntax -->\\n    <div class=\\"code-container\\" data-language=\\"xml\\" style=\\"margin: 0;\\">\\n      <pre style=\\"margin: 0; font-size: 0.76rem;\\"><code class=\\"language-xml\\">&lt;joint name=\\"laser_joint\\" type=\\"fixed\\"&gt;\\n  &lt;parent link=\\"base_link\\"/&gt;\\n  &lt;child link=\\"laser_frame\\"/&gt;\\n  &lt;origin xyz=\\"0.08 0 0.16\\" rpy=\\"0 0 0\\"/&gt;\\n&lt;/joint&gt;</code></pre>\\n    </div>\\n  </div>\\n</div>\\n\\n<hr class=\\"divider\\">\\n<h2 id=\\"3-step-by-step-amr-urdf-construction\\">3. Step-by-Step Hands-on Build: Authoring nexus_amr.urdf.xacro</h2>\\n<p>\\n  Instead of treating the robot model as a black box, every robotics engineer must understand how to construct a robot kinematic tree from the ground up using real CAD geometry. In this section, you will write the complete <code class=\\"inline-code\\">nexus_amr.urdf.xacro</code> model inside your workspace step-by-step.\\n</p>\\n\\n<div class=\\"alert-callout alert-note\\" style=\\"margin: 1.5rem 0;\\">\\n  <div class=\\"alert-icon\\">📁</div>\\n  <div class=\\"alert-body\\">\\n    <strong style=\\"color: var(--text-primary); font-size: 1rem; display: block; margin-bottom: 0.35rem;\\">Workspace File Location</strong>\\n    <p style=\\"margin: 0 0 0.5rem 0; color: var(--text-secondary);\\">Create or inspect the robot description file in your development workspace:</p>\\n    <div class=\\"code-container\\" data-language=\\"filepath\\" style=\\"margin: 0.4rem 0 0.2rem 0;\\">\\n      <div class=\\"code-header\\"><span class=\\"code-lang-tag\\">filepath</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n      <pre><code class=\\"language-filepath\\">~/ros2_ws/src/nexus_amr_description/urdf/nexus_amr.urdf.xacro</code></pre>\\n    </div>\\n  </div>\\n</div>\\n\\n<h3 id=\\"31-package-header-constants-materials\\">3.1 Step 1: XML Preamble &amp; Modular File Includes</h3>\\n<p>\\n  Open the file and declare the XML header, root <code class=\\"inline-code\\">&lt;robot&gt;</code> element with the Xacro namespace, and modular inclusions for materials and simulation plugins:\\n</p>\\n\\n<div class=\\"code-container\\" data-language=\\"xml\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">xml (nexus_amr.urdf.xacro)</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-xml\\">&lt;?xml version=\\"1.0\\"?&gt;\\n&lt;robot name=\\"nexus_amr\\" xmlns:xacro=\\"http://www.ros.org/wiki/xacro\\"&gt;\\n\\n  &lt;!-- ======================================================================= --&gt;\\n  &lt;!-- INCLUDES: Materials &amp; Gazebo Simulation Plugins                         --&gt;\\n  &lt;!-- ======================================================================= --&gt;\\n  &lt;xacro:include filename=\\"$(find nexus_amr_description)/urdf/materials.xacro\\" /&gt;\\n  &lt;xacro:include filename=\\"$(find nexus_amr_description)/urdf/gazebo_plugins.xacro\\" /&gt;</code></pre>\\n</div>\\n\\n<h3 id=\\"33-root-reference-link-base-footprint\\">3.2 Step 2: Root Reference Link (base_footprint) &amp; Chassis Offset Joint</h3>\\n<p>\\n  Following ROS REP 103 and REP 105 conventions, we define a mass-less, collision-free <code class=\\"inline-code\\">base_footprint</code> link at the ground level (Z=0) and link it rigidly to <code class=\\"inline-code\\">base_link</code>:\\n</p>\\n\\n<div class=\\"code-container\\" data-language=\\"xml\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">xml (nexus_amr.urdf.xacro)</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-xml\\">  &lt;!-- ======================================================================= --&gt;\\n  &lt;!-- BASE FOOTPRINT: Ground plane projection (Z=0, REP-103 / REP-105)        --&gt;\\n  &lt;!-- ======================================================================= --&gt;\\n  &lt;link name=\\"base_footprint\\"/&gt;\\n\\n  &lt;joint name=\\"base_footprint_joint\\" type=\\"fixed\\"&gt;\\n    &lt;parent link=\\"base_footprint\\"/&gt;\\n    &lt;child link=\\"base_link\\"/&gt;\\n    &lt;origin xyz=\\"0 0 0.005\\" rpy=\\"0 0 0\\"/&gt;\\n  &lt;/joint&gt;</code></pre>\\n</div>\\n\\n<h3 id=\\"34-main-chassis-body-base-link\\">3.3 Step 3: Main Chassis Body (base_link) with CAD STL Mesh</h3>\\n<p>\\n  The main chassis body uses the CAD mesh exported from Fusion 360 (<code class=\\"inline-code\\">base_link.stl</code>). Notice the scale factor <code class=\\"inline-code\\">0.001 0.001 0.001</code> which converts CAD millimeter units to ROS standard meter units, and the exact CAD inertia tensor:\\n</p>\\n\\n<div class=\\"code-container\\" data-language=\\"xml\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">xml (nexus_amr.urdf.xacro)</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-xml\\">  &lt;!-- ======================================================================= --&gt;\\n  &lt;!-- BASE LINK: Main Chassis Body from Fusion 360 CAD Model                  --&gt;\\n  &lt;!-- ======================================================================= --&gt;\\n  &lt;link name=\\"base_link\\"&gt;\\n    &lt;inertial&gt;\\n      &lt;origin xyz=\\"0.001469 0.000379 0.035073\\" rpy=\\"0 0 0\\"/&gt;\\n      &lt;mass value=\\"0.655806\\"/&gt;\\n      &lt;inertia ixx=\\"0.000584\\" iyy=\\"0.002255\\" izz=\\"0.002722\\" ixy=\\"-0.0\\" iyz=\\"0.0\\" ixz=\\"-3.3e-05\\"/&gt;\\n    &lt;/inertial&gt;\\n    &lt;visual&gt;\\n      &lt;origin xyz=\\"0 0 0\\" rpy=\\"0 0 0\\"/&gt;\\n      &lt;geometry&gt;\\n        &lt;mesh filename=\\"package://nexus_amr_description/meshes/base_link.stl\\" scale=\\"0.001 0.001 0.001\\"/&gt;\\n      &lt;/geometry&gt;\\n      &lt;material name=\\"silver\\"/&gt;\\n    &lt;/visual&gt;\\n    &lt;collision&gt;\\n      &lt;origin xyz=\\"0 0 0\\" rpy=\\"0 0 0\\"/&gt;\\n      &lt;geometry&gt;\\n        &lt;mesh filename=\\"package://nexus_amr_description/meshes/base_link.stl\\" scale=\\"0.001 0.001 0.001\\"/&gt;\\n      &lt;/geometry&gt;\\n    &lt;/collision&gt;\\n  &lt;/link&gt;</code></pre>\\n</div>\\n\\n<h3 id=\\"35-dual-differential-drive-wheels\\">3.4 Step 4: Actuated Differential Drive Wheels (right_motor &amp; left_motor)</h3>\\n<p>\\n  Both wheels are declared as <code class=\\"inline-code\\">continuous</code> joints rotating about the Y-axis (<code class=\\"inline-code\\">axis xyz=\\"0 1 0\\"</code>). With track separation of <strong>0.114 m</strong> and wheel diameter of <strong>0.06 m</strong>:\\n</p>\\n\\n<div class=\\"code-container\\" data-language=\\"xml\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">xml (nexus_amr.urdf.xacro)</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-xml\\">  &lt;!-- ======================================================================= --&gt;\\n  &lt;!-- RIGHT DRIVE WHEEL: Actuated continuous joint                            --&gt;\\n  &lt;!-- ======================================================================= --&gt;\\n  &lt;joint name=\\"right_motor\\" type=\\"continuous\\"&gt;\\n    &lt;origin xyz=\\"0.056117 -0.051621 0.035\\" rpy=\\"0 0 0\\"/&gt;\\n    &lt;parent link=\\"base_link\\"/&gt;\\n    &lt;child link=\\"right_wheel_1\\"/&gt;\\n    &lt;axis xyz=\\"0.0 1.0 0.0\\"/&gt;\\n  &lt;/joint&gt;\\n\\n  &lt;link name=\\"right_wheel_1\\"&gt;\\n    &lt;inertial&gt;\\n      &lt;origin xyz=\\"-3.41e-07 -0.005 0.0\\" rpy=\\"0 0 0\\"/&gt;\\n      &lt;mass value=\\"0.035791\\"/&gt;\\n      &lt;inertia ixx=\\"1.1e-05\\" iyy=\\"2.2e-05\\" izz=\\"1.1e-05\\" ixy=\\"0.0\\" iyz=\\"0.0\\" ixz=\\"0.0\\"/&gt;\\n    &lt;/inertial&gt;\\n    &lt;visual&gt;\\n      &lt;origin xyz=\\"-0.056117 0.051621 -0.035\\" rpy=\\"0 0 0\\"/&gt;\\n      &lt;geometry&gt;\\n        &lt;mesh filename=\\"package://nexus_amr_description/meshes/right_wheel_1.stl\\" scale=\\"0.001 0.001 0.001\\"/&gt;\\n      &lt;/geometry&gt;\\n      &lt;material name=\\"black\\"/&gt;\\n    &lt;/visual&gt;\\n    &lt;collision&gt;\\n      &lt;origin xyz=\\"-0.056117 0.051621 -0.035\\" rpy=\\"0 0 0\\"/&gt;\\n      &lt;geometry&gt;\\n        &lt;mesh filename=\\"package://nexus_amr_description/meshes/right_wheel_1.stl\\" scale=\\"0.001 0.001 0.001\\"/&gt;\\n      &lt;/geometry&gt;\\n    &lt;/collision&gt;\\n  &lt;/link&gt;\\n\\n  &lt;!-- ======================================================================= --&gt;\\n  &lt;!-- LEFT DRIVE WHEEL: Actuated continuous joint                             --&gt;\\n  &lt;!-- ======================================================================= --&gt;\\n  &lt;joint name=\\"left_motor\\" type=\\"continuous\\"&gt;\\n    &lt;origin xyz=\\"0.056117 0.052379 0.035\\" rpy=\\"0 0 0\\"/&gt;\\n    &lt;parent link=\\"base_link\\"/&gt;\\n    &lt;child link=\\"left_wheel_1\\"/&gt;\\n    &lt;axis xyz=\\"0.0 1.0 0.0\\"/&gt;\\n  &lt;/joint&gt;\\n\\n  &lt;link name=\\"left_wheel_1\\"&gt;\\n    &lt;inertial&gt;\\n      &lt;origin xyz=\\"-3.41e-07 0.005 0.0\\" rpy=\\"0 0 0\\"/&gt;\\n      &lt;mass value=\\"0.035791\\"/&gt;\\n      &lt;inertia ixx=\\"1.1e-05\\" iyy=\\"2.2e-05\\" izz=\\"1.1e-05\\" ixy=\\"0.0\\" iyz=\\"0.0\\" ixz=\\"0.0\\"/&gt;\\n    &lt;/inertial&gt;\\n    &lt;visual&gt;\\n      &lt;origin xyz=\\"-0.056117 -0.052379 -0.035\\" rpy=\\"0 0 0\\"/&gt;\\n      &lt;geometry&gt;\\n        &lt;mesh filename=\\"package://nexus_amr_description/meshes/left_wheel_1.stl\\" scale=\\"0.001 0.001 0.001\\"/&gt;\\n      &lt;/geometry&gt;\\n      &lt;material name=\\"black\\"/&gt;\\n    &lt;/visual&gt;\\n    &lt;collision&gt;\\n      &lt;origin xyz=\\"-0.056117 -0.052379 -0.035\\" rpy=\\"0 0 0\\"/&gt;\\n      &lt;geometry&gt;\\n        &lt;mesh filename=\\"package://nexus_amr_description/meshes/left_wheel_1.stl\\" scale=\\"0.001 0.001 0.001\\"/&gt;\\n      &lt;/geometry&gt;\\n    &lt;/collision&gt;\\n  &lt;/link&gt;</code></pre>\\n</div>\\n\\n<h3 id=\\"36-passive-support-casters\\">3.5 Step 5: Passive Rear Support Caster</h3>\\n<p>\\n  A differential drive robot requires a balance contact point to remain stable and avoid dragging on the floor. We place a low-friction spherical caster wheel at the rear:\\n</p>\\n\\n<div class=\\"code-container\\" data-language=\\"xml\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">xml (nexus_amr.urdf.xacro)</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-xml\\">  &lt;!-- ======================================================================= --&gt;\\n  &lt;!-- PASSIVE CASTER WHEEL: Balance point preventing pitching/dragging        --&gt;\\n  &lt;!-- ======================================================================= --&gt;\\n  &lt;link name=\\"caster_wheel\\"&gt;\\n    &lt;visual&gt;\\n      &lt;origin xyz=\\"0 0 0\\" rpy=\\"0 0 0\\"/&gt;\\n      &lt;geometry&gt;&lt;sphere radius=\\"0.015\\"/&gt;&lt;/geometry&gt;\\n      &lt;material name=\\"black\\"/&gt;\\n    &lt;/visual&gt;\\n    &lt;collision&gt;\\n      &lt;origin xyz=\\"0 0 0\\" rpy=\\"0 0 0\\"/&gt;\\n      &lt;geometry&gt;&lt;sphere radius=\\"0.015\\"/&gt;&lt;/geometry&gt;\\n    &lt;/collision&gt;\\n    &lt;inertial&gt;\\n      &lt;origin xyz=\\"0 0 0\\" rpy=\\"0 0 0\\"/&gt;\\n      &lt;mass value=\\"0.05\\"/&gt;\\n      &lt;inertia ixx=\\"4.5e-06\\" ixy=\\"0.0\\" ixz=\\"0.0\\" iyy=\\"4.5e-06\\" iyz=\\"0.0\\" izz=\\"4.5e-06\\"/&gt;\\n    &lt;/inertial&gt;\\n  &lt;/link&gt;\\n\\n  &lt;joint name=\\"caster_joint\\" type=\\"fixed\\"&gt;\\n    &lt;parent link=\\"base_link\\"/&gt;\\n    &lt;child link=\\"caster_wheel\\"/&gt;\\n    &lt;origin xyz=\\"-0.08 0 0.01\\" rpy=\\"0 0 0\\"/&gt;\\n  &lt;/joint&gt;</code></pre>\\n</div>\\n\\n<h3 id=\\"37-sensor-mounts-lidar-and-camera\\">3.6 Step 6: 2D LiDAR Scanner Mount (lidar_1)</h3>\\n<p>\\n  Mounted on top of the chassis with unobstructed 360-degree line-of-sight for obstacle avoidance and SLAM mapping:\\n</p>\\n\\n<div class=\\"code-container\\" data-language=\\"xml\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">xml (nexus_amr.urdf.xacro)</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-xml\\">  &lt;!-- ======================================================================= --&gt;\\n  &lt;!-- 2D RPLIDAR SENSOR: 360-Degree Laser Scanner Mount                       --&gt;\\n  &lt;!-- ======================================================================= --&gt;\\n  &lt;joint name=\\"lidar_joint\\" type=\\"fixed\\"&gt;\\n    &lt;origin xyz=\\"0.066117 0.000379 0.06\\" rpy=\\"0 0 0\\"/&gt;\\n    &lt;parent link=\\"base_link\\"/&gt;\\n    &lt;child link=\\"lidar_1\\"/&gt;\\n  &lt;/joint&gt;\\n\\n  &lt;link name=\\"lidar_1\\"&gt;\\n    &lt;inertial&gt;\\n      &lt;origin xyz=\\"-3.41e-07 2.65e-08 0.00458\\" rpy=\\"0 0 0\\"/&gt;\\n      &lt;mass value=\\"0.015296\\"/&gt;\\n      &lt;inertia ixx=\\"2e-06\\" iyy=\\"2e-06\\" izz=\\"3e-06\\" ixy=\\"0.0\\" iyz=\\"0.0\\" ixz=\\"0.0\\"/&gt;\\n    &lt;/inertial&gt;\\n    &lt;visual&gt;\\n      &lt;origin xyz=\\"-0.066117 -0.000379 -0.06\\" rpy=\\"0 0 0\\"/&gt;\\n      &lt;geometry&gt;\\n        &lt;mesh filename=\\"package://nexus_amr_description/meshes/lidar_1.stl\\" scale=\\"0.001 0.001 0.001\\"/&gt;\\n      &lt;/geometry&gt;\\n      &lt;material name=\\"blue\\"/&gt;\\n    &lt;/visual&gt;\\n    &lt;collision&gt;\\n      &lt;origin xyz=\\"-0.066117 -0.000379 -0.06\\" rpy=\\"0 0 0\\"/&gt;\\n      &lt;geometry&gt;\\n        &lt;mesh filename=\\"package://nexus_amr_description/meshes/lidar_1.stl\\" scale=\\"0.001 0.001 0.001\\"/&gt;\\n      &lt;/geometry&gt;\\n    &lt;/collision&gt;\\n  &lt;/link&gt;\\n\\n&lt;/robot&gt;</code></pre>\\n</div>\\n\\n<h3 id=\\"38-compiling-validating-urdf\\">3.7 Step 7: Compiling &amp; Kinematic Tree Validation with ROS 2 CLI</h3>\\n<p>\\n  To verify that your Xacro file compiles cleanly without syntax errors and forms a single connected kinematic tree, execute the standard ROS 2 diagnostics:\\n</p>\\n\\n<div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\"># Step 1: Expand Xacro into pure URDF XML in /tmp\\nxacro ~/ros2_ws/src/nexus_amr_description/urdf/nexus_amr.urdf.xacro &gt; /tmp/nexus_amr.urdf\\n\\n# Step 2: Validate kinematic links and joint hierarchy\\ncheck_urdf /tmp/nexus_amr.urdf</code></pre>\\n</div>\\n\\n<div class=\\"code-container\\" data-language=\\"text\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">text (Expected check_urdf Output)</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-text\\">robot name is: nexus_amr\\n---------- Successfully Parsed XML ---------------\\nroot Link: base_footprint has 1 child(ren)\\n    child(1):  base_link\\n        child(1):  caster_wheel\\n        child(2):  left_wheel_1\\n        child(3):  lidar_1\\n        child(4):  right_wheel_1</code></pre>\\n</div>\\n\\n<h2 id=\\"4-inertia-tensor-mathematics\\">4. Inertia Tensor Mathematics &amp; CAD Mass Properties</h2>\\n<p>\\n  Every rigid body simulated in a 3D physics engine (like Gazebo's ODE or Bullet) requires a 3&times;3 symmetric mass moment of inertia tensor matrix:\\n</p>\\n\\n<div style=\\"background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(148, 163, 184, 0.15); border-radius: 8px; padding: 1.25rem; margin: 1rem 0; text-align: center; font-family: monospace; font-size: 1.05rem; color: #38bdf8;\\">\\n  I = <br/>\\n  [ Ixx   Ixy   Ixz ]<br/>\\n  [ Ixy   Iyy   Iyz ]<br/>\\n  [ Ixz   Iyz   Izz ]\\n</div>\\n\\n<p>\\n  In traditional robotics, engineers approximate components with basic geometric formulas (e.g., solid cuboid <code class=\\"inline-code\\">Ixx = m*(w^2 + h^2)/12</code> or cylinder <code class=\\"inline-code\\">Izz = m*r^2/2</code>). However, industrial production AMRs feature complex contoured sheet metal, motor brackets, and 3D printed components where simple approximations cause physics instabilities.\\n</p>\\n\\n<p>\\n  When exporting from CAD tools like <strong>Autodesk Fusion 360</strong>, the CAD kernel integrates the exact volumetric solid against the material's physical density (e.g., Aluminum 6061: 2,700 kg/m³, ABS plastic: 1,040 kg/m³). The resulting mass properties for the Nexus AMR are summarized below:\\n</p>\\n\\n<div class=\\"table-responsive\\">\\n  <table>\\n    <thead>\\n      <tr>\\n        <th>Component</th>\\n        <th>Mass</th>\\n        <th>Center of Mass (<code class=\\"inline-code\\">xyz</code>)</th>\\n        <th>Principal Moments (<code class=\\"inline-code\\">Ixx, Iyy, Izz</code>)</th>\\n        <th>Off-Diagonal Products</th>\\n      </tr>\\n    </thead>\\n    <tbody>\\n      <tr>\\n        <td><strong>Main Chassis (base_link)</strong></td>\\n        <td>0.6558 kg</td>\\n        <td><code class=\\"inline-code\\">0.00147, 0.00038, 0.03507</code></td>\\n        <td><code class=\\"inline-code\\">5.84e-4, 2.25e-3, 2.72e-3</code></td>\\n        <td><code class=\\"inline-code\\">ixz = -3.3e-5</code></td>\\n      </tr>\\n      <tr>\\n        <td><strong>Drive Wheels (left/right)</strong></td>\\n        <td>0.0358 kg</td>\\n        <td><code class=\\"inline-code\\">-3.4e-7, ±0.005, 0.0</code></td>\\n        <td><code class=\\"inline-code\\">1.1e-5, 2.2e-5, 1.1e-5</code></td>\\n        <td>Negligible (&lt; 1e-9)</td>\\n      </tr>\\n      <tr>\\n        <td><strong>LiDAR Puck (lidar_1)</strong></td>\\n        <td>0.0153 kg</td>\\n        <td><code class=\\"inline-code\\">0.0, 0.0, 0.00458</code></td>\\n        <td><code class=\\"inline-code\\">2.0e-6, 2.0e-6, 3.0e-6</code></td>\\n        <td>Negligible (&lt; 1e-9)</td>\\n      </tr>\\n      <tr>\\n        <td><strong>Front Camera (camera_1)</strong></td>\\n        <td>0.00034 kg</td>\\n        <td><code class=\\"inline-code\\">0.00138, 0.0, 0.0</code></td>\\n        <td><code class=\\"inline-code\\">1.0e-7, 1.0e-7, 1.0e-7</code></td>\\n        <td>Negligible (&lt; 1e-9)</td>\\n      </tr>\\n    </tbody>\\n  </table>\\n</div>\\n\\n<h2 id=\\"5-alternative-cad-workflow-fusion-360-to-urdf\\">5. Industrial CAD Workflow: From Autodesk Fusion 360 to ROS 2 URDF</h2>\\n<p>\\n  The Nexus AMR model in this course is derived from a real Autodesk Fusion 360 mechanical assembly (<code class=\\"inline-code\\">urr_bot v8.f3d</code>). In modern industrial robotics engineering, mechanical engineers design parts in parametric 3D CAD suites while robotics software engineers integrate them into ROS 2.\\n</p>\\n\\n<div class=\\"alert alert-tip\\">\\n  <div class=\\"alert-title\\">🔗 Fusion 360 to ROS 2 URDF Exporter Pipeline</div>\\n  <p>The automated export pipeline uses <a href=\\"https://github.com/dvalenciar/fusion2urdf-ros2\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\"><strong>fusion2urdf-ros2</strong></a>:</p>\\n  <ol>\\n    <li><strong>CAD Modeling:</strong> Create independent bodies, join them into components, and set the root component as <code class=\\"inline-code\\">base_link</code>.</li>\\n    <li><strong>Export Execution:</strong> The script computes mass matrices, center-of-gravity offsets, and exports 3D triangular surface meshes into STL files:\\n      <ul>\\n        <li><code class=\\"inline-code\\">base_link.stl</code> &mdash; Main robot body with chassis cutouts</li>\\n        <li><code class=\\"inline-code\\">left_wheel_1.stl</code> &amp; <code class=\\"inline-code\\">right_wheel_1.stl</code> &mdash; Treaded drive wheels</li>\\n        <li><code class=\\"inline-code\\">lidar_1.stl</code> &mdash; Cylindrical laser sensor mount</li>\\n        <li><code class=\\"inline-code\\">camera_1.stl</code> &mdash; Optical camera body</li>\\n      </ul>\\n    </li>\\n    <li><strong>Package Installation:</strong> Meshes are stored in <code class=\\"inline-code\\">nexus_amr_description/meshes/</code> and installed via <code class=\\"inline-code\\">setup.py</code>:\\n      <div class=\\"code-container\\" data-language=\\"python\\" style=\\"margin: 0.5rem 0;\\">\\n        <pre><code class=\\"language-python\\">(os.path.join('share', package_name, 'meshes'), glob('meshes/*.stl'))</code></pre>\\n      </div>\\n    </li>\\n    <li><strong>URDF Reference:</strong> Loaded directly into visual and collision geometry tags via <code class=\\"inline-code\\">package://nexus_amr_description/meshes/&lt;filename&gt;.stl</code> with scale factor <code class=\\"inline-code\\">0.001 0.001 0.001</code>.</li>\\n  </ol>\\n</div>\\n\\n<h2 id=\\"6-hands-on-student-challenge\\">6. Hands-on Student Challenge: Modular Optical Camera Sensor Macro &amp; AMR Integration</h2>\\n<p>\\n  Now that the core chassis, differential drive wheels, rear caster, and top LiDAR puck are configured in <code class=\\"inline-code\\">nexus_amr.urdf.xacro</code>, your engineering task is to mount the front optical perception camera (<code class=\\"inline-code\\">camera_1</code>) onto the chassis bumper.\\n</p>\\n\\n<div class=\\"alert alert-tip\\">\\n  <div class=\\"alert-title\\">🎯 Mission Objectives</div>\\n  <ol>\\n    <li><strong>Inspect the Starter Task File:</strong> Open <code class=\\"inline-code\\">ros2_ws_reference/src/nexus_amr_description/urdf/m02_l09_task_camera_sensor.xacro</code>.</li>\\n    <li><strong>Declare Link <code class=\\"inline-code\\">camera_1</code>:</strong>\\n      <ul>\\n        <li>Visual: origin <code class=\\"inline-code\\">xyz=\\"-0.101117 -0.000379 -0.035\\" rpy=\\"0 0 0\\"</code>, mesh <code class=\\"inline-code\\">package://nexus_amr_description/meshes/camera_1.stl</code> (scale 0.001 0.001 0.001), material <code class=\\"inline-code\\">black</code>.</li>\\n        <li>Collision: identical geometry to visual.</li>\\n        <li>Inertial: mass <code class=\\"inline-code\\">0.000343</code> kg, origin <code class=\\"inline-code\\">xyz=\\"0.001379 0 0\\"</code>, inertia <code class=\\"inline-code\\">ixx=\\"1e-7\\" iyy=\\"1e-7\\" izz=\\"1e-7\\"</code>.</li>\\n      </ul>\\n    </li>\\n    <li><strong>Declare Fixed Joint <code class=\\"inline-code\\">cam_joint</code>:</strong>\\n      <ul>\\n        <li>Parent: <code class=\\"inline-code\\">base_link</code>, Child: <code class=\\"inline-code\\">camera_1</code>.</li>\\n        <li>Mounting Origin: <code class=\\"inline-code\\">xyz=\\"0.101117 0.000379 0.035\\" rpy=\\"0 0 0\\"</code>.</li>\\n      </ul>\\n    </li>\\n  </ol>\\n</div>\\n\\n<h3 id=\\"61-starter-template\\">6.1 Starter Template: <code class=\\"inline-code\\">m02_l09_task_camera_sensor.xacro</code></h3>\\n\\n<div class=\\"code-container\\" data-language=\\"xml\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">xml (Starter Template: m02_l09_task_camera_sensor.xacro)</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-xml\\">&lt;?xml version=\\"1.0\\"?&gt;\\n&lt;robot xmlns:xacro=\\"http://www.ros.org/wiki/xacro\\"&gt;\\n\\n  &lt;!-- TODO 1: Declare the camera_1 link with CAD mesh and mass properties --&gt;\\n  &lt;!-- &gt;&gt;&gt; YOUR CODE HERE &lt;&lt;&lt; --&gt;\\n\\n  &lt;!-- TODO 2: Declare the fixed joint cam_joint attaching camera_1 to base_link --&gt;\\n  &lt;!-- &gt;&gt;&gt; YOUR CODE HERE &lt;&lt;&lt; --&gt;\\n\\n&lt;/robot&gt;</code></pre>\\n</div>\\n\\n<h3 id=\\"62-reference-solution\\">6.2 Reference Solution: <code class=\\"inline-code\\">m02_l09_solution_camera_sensor.xacro</code></h3>\\n\\n<div class=\\"code-container\\" data-language=\\"xml\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">xml (Reference Solution)</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-xml\\">&lt;?xml version=\\"1.0\\"?&gt;\\n&lt;robot xmlns:xacro=\\"http://www.ros.org/wiki/xacro\\"&gt;\\n\\n  &lt;!-- STEP 1: Physical Optical Camera Link with 3D CAD Mesh --&gt;\\n  &lt;link name=\\"camera_1\\"&gt;\\n    &lt;inertial&gt;\\n      &lt;origin xyz=\\"0.001379 0.0 0.0\\" rpy=\\"0 0 0\\"/&gt;\\n      &lt;mass value=\\"0.000343\\"/&gt;\\n      &lt;inertia ixx=\\"1e-07\\" iyy=\\"1e-07\\" izz=\\"1e-07\\" ixy=\\"0.0\\" iyz=\\"0.0\\" ixz=\\"0.0\\"/&gt;\\n    &lt;/inertial&gt;\\n    &lt;visual&gt;\\n      &lt;origin xyz=\\"-0.101117 -0.000379 -0.035\\" rpy=\\"0 0 0\\"/&gt;\\n      &lt;geometry&gt;\\n        &lt;mesh filename=\\"package://nexus_amr_description/meshes/camera_1.stl\\" scale=\\"0.001 0.001 0.001\\"/&gt;\\n      &lt;/geometry&gt;\\n      &lt;material name=\\"black\\"/&gt;\\n    &lt;/visual&gt;\\n    &lt;collision&gt;\\n      &lt;origin xyz=\\"-0.101117 -0.000379 -0.035\\" rpy=\\"0 0 0\\"/&gt;\\n      &lt;geometry&gt;\\n        &lt;mesh filename=\\"package://nexus_amr_description/meshes/camera_1.stl\\" scale=\\"0.001 0.001 0.001\\"/&gt;\\n      &lt;/geometry&gt;\\n    &lt;/collision&gt;\\n  &lt;/link&gt;\\n\\n  &lt;!-- STEP 2: Mount Camera to Front Bumper of base_link --&gt;\\n  &lt;joint name=\\"cam_joint\\" type=\\"fixed\\"&gt;\\n    &lt;origin xyz=\\"0.101117 0.000379 0.035\\" rpy=\\"0 0 0\\"/&gt;\\n    &lt;parent link=\\"base_link\\"/&gt;\\n    &lt;child link=\\"camera_1\\"/&gt;\\n  &lt;/joint&gt;\\n\\n&lt;/robot&gt;</code></pre>\\n</div>\\n\\n<h3 id=\\"63-verification-steps\\">6.3 Verification Steps &amp; Expected Terminal Output</h3>\\n<p>\\n  Include the camera macro into <code class=\\"inline-code\\">nexus_amr.urdf.xacro</code> and compile the model to confirm that <code class=\\"inline-code\\">camera_1</code> appears as a child of <code class=\\"inline-code\\">base_link</code>:\\n</p>\\n\\n<div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\">xacro ~/ros2_ws/src/nexus_amr_description/urdf/nexus_amr.urdf.xacro &gt; /tmp/nexus_amr.urdf\\ncheck_urdf /tmp/nexus_amr.urdf</code></pre>\\n</div>\\n\\n<div class=\\"code-container\\" data-language=\\"text\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">text (Expected check_urdf Output)</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-text\\">robot name is: nexus_amr\\n---------- Successfully Parsed XML ---------------\\nroot Link: base_footprint has 1 child(ren)\\n    child(1):  base_link\\n        child(1):  camera_1\\n        child(2):  caster_wheel\\n        child(3):  left_wheel_1\\n        child(4):  lidar_1\\n        child(5):  right_wheel_1</code></pre>\\n</div>\\n<div class=\\"card\\" style=\\"margin-top: 2rem; border-left: 4px solid var(--accent-color); background: var(--bg-surface-elevated); padding: 1.25rem 1.5rem; border-radius: 8px;\\">\\n  <div style=\\"display: flex; align-items: center; gap: 0.5rem; margin-bottom: 0.5rem; color: var(--accent-color); font-weight: 600;\\">\\n    <svg width=\\"20\\" height=\\"20\\" viewBox=\\"0 0 24 24\\" fill=\\"none\\" stroke=\\"currentColor\\" stroke-width=\\"2\\"><path d=\\"M9 18l6-6-6-6\\"/></svg>\\n    <span>Next Step &amp; Continuity</span>\\n  </div>\\n  <p style=\\"margin: 0 0 0.65rem 0; font-size: 0.88rem; color: var(--text-primary); line-height: 1.6;\\">\\n    Now that your AMR kinematic model, sensors, and mesh geometry are validated, proceed to Lesson 10 to visualize the robot in RViz2 and inspect coordinate transforms.\\n  </p>\\n  <div style=\\"display: flex; flex-wrap: wrap; gap: 0.75rem; font-size: 0.82rem; font-family: var(--font-mono);\\">\\n    <span style=\\"background: var(--bg-surface); border: 1px solid var(--border-color); padding: 0.25rem 0.6rem; border-radius: 5px; color: var(--text-primary);\\">\\n      📁 <strong>Produced Artifact:</strong> <code>ros2_ws_reference/src/nexus_amr_description/urdf/nexus_amr.urdf.xacro</code>\\n    </span>\\n    <span style=\\"background: var(--bg-surface); border: 1px solid var(--border-color); padding: 0.25rem 0.6rem; border-radius: 5px; color: var(--text-primary);\\">\\n      ➡️ <strong>Ingested By:</strong> Lesson 10 (RViz2 Visualization &amp; Kinematic TF Inspection)\\n    </span>\\n  </div>\\n</div>\\n","quizzes":[{"id":"q_l1_17_1","prompt":"What is the primary advantage of Xacro over raw URDF XML files?","options":["Xacro can execute arbitrary Python scripts inside Gazebo","Xacro introduces modular XML macros, reusable property variables, and mathematical expressions to eliminate copy-paste boilerplate","Xacro converts 3D meshes to STL automatically","Xacro runs 10x faster in RViz2"],"correct":1,"explanation":"Xacro (XML Macros) provides programmatic capabilities like <xacro:macro>, property variables (\${wheel_radius}), and math expressions, allowing clean modular robot descriptions."}],"has_quiz":true,"next_id":"lesson_10","prev_id":"lesson_08","subtopics":[{"id":"1-overview-learning-objectives","title":"1. Overview &amp; Learning Objectives"},{"id":"2-urdf-anatomy-links-vs-joints","title":"2. URDF Anatomy: Links vs. Joints"},{"id":"3-step-by-step-amr-urdf-construction","title":"3. Step-by-Step Hands-on Build: Authoring nexus_amr.urdf.xacro"},{"id":"4-inertia-tensor-mathematics","title":"4. Inertia Tensor Mathematics &amp; CAD Mass Properties"},{"id":"5-alternative-cad-workflow-fusion-360-to-urdf","title":"5. Industrial CAD Workflow: From Autodesk Fusion 360 to ROS 2 URDF"},{"id":"6-hands-on-student-challenge","title":"6. Hands-on Student Challenge: Modular Optical Camera Sensor Macro &amp; AMR Integration"}]},{"id":"lesson_10","num":10,"num_str":"10","title":"RViz2 Visualization & Kinematic TF Inspection","slug":"15_rviz2_visualization_tf_inspection","filename":"15_rviz2_visualization_tf_inspection.md","module":"Day 2: 3D Robot Modeling & Physics Simulation","module_id":2,"duration":"45-60 min","focus":"RViz2 Visual Plugins, Spatial Coordinate Conventions (REP 103: X Forward), and Kinematic TF Tree Debugging","snapshot":[["Fixed Frame Invariant","RViz2 requires a valid reference coordinate frame (base_footprint or odom); invalid frames cause black transform failures."],["RGB = XYZ Color Rule","Visualizes coordinate axes where Red is +X Forward, Green is +Y Port Left, and Blue is +Z Upward following REP 103."],["Launch Pipeline Architecture","rsp.launch.py parses Xacro with xacro command substitution and publishes latched /robot_description to the TF tree."],["Interactive Joint State Testing","joint_state_publisher_gui provides real-time slider controls to verify wheel spin and sensor articulators visually."]],"html_content":"<h2 id=\\"1-overview-learning-objectives\\">1. Overview &amp; Learning Objectives</h2>\\n<p><strong>RViz2 (ROS 2 3D Visualizer)</strong> is the primary window into the mind of your robot. Unlike a physics simulator (which simulates friction, gravity, and collisions in a simulated world), RViz2 visualizes <strong>what the robot's onboard algorithms believe is happening</strong> (sensor clouds, transform trees, planned paths, costmap obstacles).</p>\\n<p><div class=\\"learning-objectives-card\\">\\n  <div class=\\"learning-objectives-header\\">\\n    <div class=\\"objectives-icon-badge\\">\\n      <span style=\\"font-size: 1.15rem; line-height: 1;\\">🎯</span>\\n    </div>\\n    <div class=\\"objectives-title-group\\">\\n      <h3 class=\\"objectives-main-title\\">Learning Objectives &amp; Core Outcomes</h3>\\n      <span class=\\"objectives-subtitle\\">By the end of this lesson, you will be able to:</span>\\n    </div>\\n    <span class=\\"objectives-count-badge\\">5 CORE OUTCOMES</span>\\n  </div>\\n  <ul class=\\"learning-objectives-list\\">\\n    <li class=\\"learning-objective-item\\">\\n      <span class=\\"objective-num-badge\\">1</span>\\n      <span class=\\"objective-text\\">Understand the difference between physics simulation (Gazebo) and sensor visualization (RViz2).</span>\\n    </li>\\n    <li class=\\"learning-objective-item\\">\\n      <span class=\\"objective-num-badge\\">2</span>\\n      <span class=\\"objective-text\\">Configure core visualization displays: Grid, RobotModel, TF, LaserScan, and Odometry.</span>\\n    </li>\\n    <li class=\\"learning-objective-item\\">\\n      <span class=\\"objective-num-badge\\">3</span>\\n      <span class=\\"objective-text\\">Master the rule of <strong>RGB = XYZ</strong> coordinate axes.</span>\\n    </li>\\n    <li class=\\"learning-objective-item\\">\\n      <span class=\\"objective-num-badge\\">4</span>\\n      <span class=\\"objective-text\\">Understand the <strong>Fixed Frame</strong> setting and resolve the common &quot;No transform from [X] to [Y]&quot; error.</span>\\n    </li>\\n    <li class=\\"learning-objective-item\\">\\n      <span class=\\"objective-num-badge\\">5</span>\\n      <span class=\\"objective-text\\">Save, version-control, and launch custom <code class=\\"inline-code\\">.rviz</code> configuration presets.</span>\\n    </li>\\n  </ul>\\n</div>\\n\\n<h2 id=\\"2-rviz2-vs-gazebo-the-essential-distinction\\">2. RViz2 vs. Gazebo: The Essential Distinction</h2>\\n<div class=\\"table-responsive\\"><table>\\n<thead>\\n<tr>\\n<th>Gazebo Simulator</th>\\n<th>RViz2 Visualizer</th>\\n</tr>\\n</thead>\\n<tbody>\\n<tr>\\n<td>Simulates the physical universe</td>\\n<td>Visualizes the robot's internal software state</td>\\n</tr>\\n<tr>\\n<td>Models motor torque, friction, and slip</td>\\n<td>Shows sensor telemetry (LiDAR points, images)</td>\\n</tr>\\n<tr>\\n<td>Simulates gravity and rigid-body collisions</td>\\n<td>Displays costmaps, planned paths, and TF frames</td>\\n</tr>\\n<tr>\\n<td>Answers: <em>&quot;What is the ground-truth physical state?&quot;</em></td>\\n<td>Answers: <em>&quot;What does the robot software stack perceive?&quot;</em></td>\\n</tr>\\n</tbody>\\n</table></div>\\n\\n<h3 id=\\"21-rviz2-gui-architecture-visualization-pipeline\\">2.1 RViz2 GUI Architecture &amp; Visualization Pipeline Theory</h3>\\n<p>\\n  Unlike physical simulation software, <strong>RViz2 (ROS 2 3D Visualization Tool)</strong> is an interactive spatial telemetry observer and debugging dashboard. RViz2 does <em>not</em> compute contact dynamics, solve differential equations, or simulate motor slip. Instead, it subscribes to incoming ROS 2 topics broadcast across the DDS databus and renders the robot's spatial state into a high-performance 3D graphical viewport.\\n</p>\\n\\n<p><img src=\\"assets/images/rviz2_gui_interface_real.png\\" alt=\\"Official ROS 2 RViz2 Graphical User Interface &amp; Displays Window\\" class=\\"lesson-image\\" loading=\\"lazy\\" /></p>\\n\\n<div class=\\"code-breakdown-card\\" style=\\"margin-top: 1.5rem;\\">\\n  <h4 class=\\"code-breakdown-title\\">🔬 RViz2 GUI Subsystems &amp; Computational Pipeline Deep Dive</h4>\\n  <p class=\\"code-breakdown-intro\\">Understanding the five foundational pillars of the RViz2 visualization engine:</p>\\n  <ul class=\\"code-breakdown-list\\">\\n    <li class=\\"code-breakdown-item\\">\\n      <strong>① Top Navigation &amp; Interaction Tools Ribbon:</strong> Provides 3D viewport manipulators (<code class=\\"inline-code\\">Interact</code>, <code class=\\"inline-code\\">Move Camera</code>, <code class=\\"inline-code\\">Select</code>, <code class=\\"inline-code\\">Focus Camera</code>, <code class=\\"inline-code\\">Measure</code>) and publishers. Crucially, clicking <code class=\\"inline-code\\">2D Pose Estimate</code> publishes an initial <code class=\\"inline-code\\">(X, Y, θ)</code> hypothesis to <code class=\\"inline-code\\">/initialpose</code> for AMCL Monte Carlo localization, while <code class=\\"inline-code\\">2D Goal Pose</code> dispatches a target goal to <code class=\\"inline-code\\">/goal_pose</code> for Nav2 behavioral path planners.\\n    </li>\\n    <li class=\\"code-breakdown-item\\">\\n      <strong>② Left Displays Panel &amp; Plugin Tree (The Observer):</strong> Hosts modular rendering plugins from <code class=\\"inline-code\\">rviz_default_plugins</code>. Each plugin subscribes to a specific ROS 2 topic:\\n      <ul style=\\"margin: 0.5rem 0 0.5rem 1.25rem; font-size: 0.88rem; color: var(--text-secondary); line-height: 1.5;\\">\\n        <li><code class=\\"inline-code\\">RobotModel</code>: Queries <code class=\\"inline-code\\">/robot_description</code>, deserializes the URDF XML, and renders 3D link meshes positioned by live joint angles.</li>\\n        <li><code class=\\"inline-code\\">TF</code>: Queries the transform buffer (<code class=\\"inline-code\\">/tf</code> and <code class=\\"inline-code\\">/tf_static</code>) to render glowing 3D coordinate frames and kinematic hierarchy trees.</li>\\n        <li><code class=\\"inline-code\\">LaserScan</code>: Subscribes to <code class=\\"inline-code\\">/scan</code>, transforming polar distance arrays into Cartesian point clouds rendered in 3D.</li>\\n        <li><code class=\\"inline-code\\">Odometry</code>: Renders trajectory paths and covariance uncertainty ellipsoids from <code class=\\"inline-code\\">/odom</code>.</li>\\n      </ul>\\n    </li>\\n    <li class=\\"code-breakdown-item\\">\\n      <strong>③ Central 3D Render Viewport (What the Algorithm Believes):</strong> Powered by the OGRE (Object-Oriented Graphics Rendering Engine) hardware-accelerated pipeline. It projects all active displays onto an interactive ground grid. Crucially, the viewport renders <em>what the robot software stack perceives</em> based on incoming telemetry—not ground-truth physical reality!\\n    </li>\\n    <li class=\\"code-breakdown-item\\">\\n      <strong>④ Right Views Panel &amp; Perspective Controller:</strong> Manages the virtual observer camera. In <code class=\\"inline-code\\">Orbit</code> mode focused on <code class=\\"inline-code\\">Target Frame: base_link</code>, the camera automatically locks onto the robot's center and follows it through the coordinate space as it navigates.\\n    </li>\\n    <li class=\\"code-breakdown-item\\">\\n      <strong>⑤ Bottom Time Synchronization &amp; TF Status Bar:</strong> Monitors live <code class=\\"inline-code\\">ROS Time</code> vs <code class=\\"inline-code\\">Wall Time</code> and checks TF transform latencies. If transforms between sensor frames and the fixed frame drop out or exceed the buffer threshold, RViz2 flags warning statuses in real-time.\\n    </li>\\n  </ul>\\n</div>\\n\\n<hr class=\\"divider\\">\\n<h2 id=\\"3-the-rgb-xyz-rule\\">3. The RGB = XYZ Rule &amp; Spatial Coordinate Conventions (REP 103)</h2>\\n<p>In all ROS 2 visual tools (RViz2, Gazebo, Blender), coordinate frame axes follow the universal color standard:</p>\\n\\n<div style=\\"display: flex; gap: 0.85rem; flex-wrap: wrap; margin: 1.1rem 0 1.4rem 0;\\">\\n  <span style=\\"background: rgba(239, 68, 68, 0.1); border: 1px solid rgba(239, 68, 68, 0.35); color: #ef4444; padding: 0.45rem 0.95rem; border-radius: 8px; font-weight: 700; font-family: var(--font-mono); font-size: 0.88rem; display: flex; align-items: center; gap: 0.4rem;\\">\\n    <span style=\\"width: 10px; height: 10px; border-radius: 50%; background: #ef4444; display: inline-block;\\"></span>\\n    <strong>R = X</strong> (Red: Forward / Longitudinal)\\n  </span>\\n  <span style=\\"background: rgba(16, 185, 129, 0.1); border: 1px solid rgba(16, 185, 129, 0.35); color: #10b981; padding: 0.45rem 0.95rem; border-radius: 8px; font-weight: 700; font-family: var(--font-mono); font-size: 0.88rem; display: flex; align-items: center; gap: 0.4rem;\\">\\n    <span style=\\"width: 10px; height: 10px; border-radius: 50%; background: #10b981; display: inline-block;\\"></span>\\n    <strong>G = Y</strong> (Green: Port-Side Left / Lateral)\\n  </span>\\n  <span style=\\"background: rgba(59, 130, 246, 0.1); border: 1px solid rgba(59, 130, 246, 0.35); color: #3b82f6; padding: 0.45rem 0.95rem; border-radius: 8px; font-weight: 700; font-family: var(--font-mono); font-size: 0.88rem; display: flex; align-items: center; gap: 0.4rem;\\">\\n    <span style=\\"width: 10px; height: 10px; border-radius: 50%; background: #3b82f6; display: inline-block;\\"></span>\\n    <strong>B = Z</strong> (Blue: Upward / Vertical)\\n  </span>\\n</div>\\n\\n<p><img src=\\"assets/images/rviz_coordinate_axes.svg\\" alt=\\"ROS 2 RGB=XYZ Coordinate Axes\\" class=\\"lesson-image\\" loading=\\"lazy\\" /></p>\\n<hr class=\\"divider\\">\\n<h2 id=\\"4-key-rviz2-displays-plugins\\">4. Key RViz2 Displays &amp; Plugins</h2>\\n<div class=\\"table-responsive\\"><table>\\n<thead>\\n<tr>\\n<th>Display Plugin</th>\\n<th>Topic / Source</th>\\n<th>Purpose</th>\\n</tr>\\n</thead>\\n<tbody>\\n<tr>\\n<td><strong>Grid</strong></td>\\n<td>N/A</td>\\n<td>Ground plane reference grid (1m x 1m cells).</td>\\n</tr>\\n<tr>\\n<td><strong>RobotModel</strong></td>\\n<td><code class=\\"inline-code\\">/robot_description</code></td>\\n<td>Renders the 3D visual geometry from URDF with joint angles.</td>\\n</tr>\\n<tr>\\n<td><strong>TF</strong></td>\\n<td><code class=\\"inline-code\\">/tf</code>, <code class=\\"inline-code\\">/tf_static</code></td>\\n<td>Displays 3D axes and frame names for all coordinate links.</td>\\n</tr>\\n<tr>\\n<td><strong>LaserScan</strong></td>\\n<td><code class=\\"inline-code\\">/scan</code></td>\\n<td>Renders 2D LiDAR range points as color-coded dots.</td>\\n</tr>\\n<tr>\\n<td><strong>Odometry</strong></td>\\n<td><code class=\\"inline-code\\">/odom</code></td>\\n<td>Displays robot linear velocity vectors and trajectory paths.</td>\\n</tr>\\n<tr>\\n<td><strong>Map</strong></td>\\n<td><code class=\\"inline-code\\">/map</code></td>\\n<td>Renders 2D SLAM occupancy grid (White=Free, Black=Wall, Gray=Unknown).</td>\\n</tr>\\n<tr>\\n<td><strong>Path</strong></td>\\n<td><code class=\\"inline-code\\">/plan</code></td>\\n<td>Renders Nav2 global planned trajectories as colored ribbons.</td>\\n</tr>\\n</tbody>\\n</table></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"5-the-critical-fixed-frame-rule\\">5. The Critical &quot;Fixed Frame&quot; Rule</h2>\\n<p>At the top of the RViz2 Displays panel is the <strong>Global Options -&gt; Fixed Frame</strong> property:</p>\\n<ul>\\n<li>When inspecting a static robot model on a test bench: Set Fixed Frame to <strong><code class=\\"inline-code\\">base_footprint</code></strong>.</li>\\n<li>When visualizing wheel odometry: Set Fixed Frame to <strong><code class=\\"inline-code\\">odom</code></strong>.</li>\\n<li>When navigating inside a warehouse map: Set Fixed Frame to <strong><code class=\\"inline-code\\">map</code></strong>.</li>\\n</ul>\\n<div class=\\"alert-callout alert-warning\\"><div class=\\"alert-icon\\"></div><div class=\\"alert-body\\"><strong>The #1 RViz2 Error: &quot;No transform from [lidar_1] to [map]&quot;</strong><br><br>If your Fixed Frame is set to <code class=\\"inline-code\\">map</code>, but neither SLAM nor AMCL is currently running, RViz2 has no way to calculate the transform between <code class=\\"inline-code\\">map</code> and <code class=\\"inline-code\\">odom</code>. All displays will turn RED and report an error.<br><br><strong>Solution:</strong> Change the Fixed Frame back to <code class=\\"inline-code\\">odom</code> or <code class=\\"inline-code\\">base_footprint</code>!</div></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"6-building-the-launch-pipeline\\">6. Building the Launch Pipeline: rsp.launch.py &amp; display.launch.py</h2>\\n<p>\\n  Having authored your robot model in Lesson 09, you cannot simply open RViz2 and expect the robot to appear automatically. RViz2 requires two critical runtime streams:\\n</p>\\n<ol>\\n  <li><strong>The Robot Model (<code class=\\"inline-code\\">/robot_description</code> topic):</strong> The raw URDF XML string parsed from your Xacro file.</li>\\n  <li><strong>The Kinematic Transform Tree (<code class=\\"inline-code\\">/tf</code> and <code class=\\"inline-code\\">/tf_static</code>):</strong> Broadcast by the <code class=\\"inline-code\\">robot_state_publisher</code> node from the URDF kinematics and active joint angles.</li>\\n</ol>\\n<p>\\n  To achieve this cleanly, professional ROS 2 systems create a modular two-stage launch pipeline:\\n</p>\\n\\n<div style=\\"display: grid; grid-template-columns: repeat(auto-fit, minmax(300px, 1fr)); gap: 1rem; margin: 1.25rem 0;\\">\\n  <div style=\\"background: var(--bg-surface); border: 1px solid var(--border-color); border-radius: 8px; padding: 1rem 1.2rem;\\">\\n    <h4 style=\\"margin: 0 0 0.5rem 0; font-size: 1rem; font-weight: 700; color: #06b6d4;\\">Stage 1: rsp.launch.py (Headless Publisher)</h4>\\n    <p style=\\"margin: 0; font-size: 0.84rem; color: var(--text-secondary); line-height: 1.5;\\">\\n      Processes <code class=\\"inline-code\\">nexus_amr.urdf.xacro</code> at launch time using shell substitution and starts <code class=\\"inline-code\\">robot_state_publisher</code>. Headless and reusable across simulation, SLAM, and real robot bringup.\\n    </p>\\n  </div>\\n\\n  <div style=\\"background: var(--bg-surface); border: 1px solid var(--border-color); border-radius: 8px; padding: 1rem 1.2rem;\\">\\n    <h4 style=\\"margin: 0 0 0.5rem 0; font-size: 1rem; font-weight: 700; color: #10b981;\\">Stage 2: display.launch.py (Interactive Viewer)</h4>\\n    <p style=\\"margin: 0; font-size: 0.84rem; color: var(--text-secondary); line-height: 1.5;\\">\\n      Includes <code class=\\"inline-code\\">rsp.launch.py</code>, launches <code class=\\"inline-code\\">joint_state_publisher_gui</code> (providing GUI sliders to manually rotate wheels), and opens <code class=\\"inline-code\\">rviz2</code> with a preset profile.\\n    </p>\\n  </div>\\n</div>\\n\\n<h3 id=\\"61-authoring-rsp-launch-py\\">6.1 Step 1: Writing <code class=\\"inline-code\\">rsp.launch.py</code></h3>\\n<p>\\n  Create <code class=\\"inline-code\\">~/ros2_ws/src/nexus_amr_description/launch/rsp.launch.py</code>:\\n</p>\\n\\n<div class=\\"code-container\\" data-language=\\"python\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">python (rsp.launch.py)</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-python\\">import os\\nfrom ament_index_python.packages import get_package_share_directory\\nfrom launch import LaunchDescription\\nfrom launch.actions import DeclareLaunchArgument\\nfrom launch.substitutions import LaunchConfiguration, Command\\nfrom launch_ros.actions import Node\\nfrom launch_ros.parameter_descriptions import ParameterValue\\n\\n\\ndef generate_launch_description():\\n    # 1. Resolve Xacro file path in installed share directory\\n    pkg_share = get_package_share_directory('nexus_amr_description')\\n    xacro_file = os.path.join(pkg_share, 'urdf', 'nexus_amr.urdf.xacro')\\n\\n    # 2. Declare use_sim_time argument (synchronizes TF with Gazebo clock when true)\\n    use_sim_time_arg = DeclareLaunchArgument(\\n        'use_sim_time',\\n        default_value='false',\\n        description='Synchronize node clock with /clock published by Gazebo simulation'\\n    )\\n\\n    # 3. Dynamic Xacro expansion via Command substitution\\n    # ParameterValue ensures the output string is treated as a single parameter value\\n    robot_description_content = ParameterValue(\\n        Command(['xacro ', xacro_file]),\\n        value_type=str\\n    )\\n\\n    # 4. Robot State Publisher Node\\n    # Publishes /robot_description (latched) and broadcasts transforms on /tf\\n    robot_state_publisher_node = Node(\\n        package='robot_state_publisher',\\n        executable='robot_state_publisher',\\n        name='robot_state_publisher',\\n        output='screen',\\n        parameters=[{\\n            'robot_description': robot_description_content,\\n            'use_sim_time': LaunchConfiguration('use_sim_time')\\n        }]\\n    )\\n\\n    return LaunchDescription([\\n        use_sim_time_arg,\\n        robot_state_publisher_node\\n    ])\\n</code></pre>\\n</div>\\n\\n<div class=\\"alert-callout alert-important\\"><div class=\\"alert-icon\\"></div><div class=\\"alert-body\\"><strong>Understanding <code class=\\"inline-code\\">ParameterValue(Command(...))</code>:</strong> In ROS 2, launch configurations run asynchronously. Wrapping <code class=\\"inline-code\\">Command(['xacro ', xacro_file])</code> inside <code class=\\"inline-code\\">ParameterValue(..., value_type=str)</code> tells ROS 2 to execute the <code class=\\"inline-code\\">xacro</code> executable in the background at launch time, grab its XML stdout stream, and deliver it directly to the node's <code class=\\"inline-code\\">robot_description</code> parameter without generating temporary files on disk.</div></div>\\n\\n<h3 id=\\"62-authoring-display-launch-py\\">6.2 Step 2: Writing <code class=\\"inline-code\\">display.launch.py</code></h3>\\n<p>\\n  Create <code class=\\"inline-code\\">~/ros2_ws/src/nexus_amr_description/launch/display.launch.py</code>:\\n</p>\\n\\n<div class=\\"code-container\\" data-language=\\"python\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">python (display.launch.py)</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-python\\">import os\\nfrom ament_index_python.packages import get_package_share_directory\\nfrom launch import LaunchDescription\\nfrom launch.actions import DeclareLaunchArgument, IncludeLaunchDescription\\nfrom launch.launch_description_sources import PythonLaunchDescriptionSource\\nfrom launch.substitutions import LaunchConfiguration\\nfrom launch_ros.actions import Node\\n\\n\\ndef generate_launch_description():\\n    pkg_share = get_package_share_directory('nexus_amr_description')\\n    rsp_launch_path = os.path.join(pkg_share, 'launch', 'rsp.launch.py')\\n    rviz_config_path = os.path.join(pkg_share, 'rviz', 'robot_model.rviz')\\n\\n    use_sim_time_arg = DeclareLaunchArgument(\\n        'use_sim_time',\\n        default_value='false',\\n        description='Use simulation (Gazebo) clock if true'\\n    )\\n\\n    # 1. Include rsp.launch.py to compile Xacro and start robot_state_publisher\\n    rsp_launch = IncludeLaunchDescription(\\n        PythonLaunchDescriptionSource(rsp_launch_path),\\n        launch_arguments={'use_sim_time': LaunchConfiguration('use_sim_time')}.items()\\n    )\\n\\n    # 2. Interactive Joint State Publisher GUI\\n    # Discovers non-fixed joints in /robot_description (left_wheel_joint, right_wheel_joint)\\n    # and opens a GUI window with sliders to manually publish angles to /joint_states\\n    joint_state_publisher_gui_node = Node(\\n        package='joint_state_publisher_gui',\\n        executable='joint_state_publisher_gui',\\n        name='joint_state_publisher_gui',\\n        output='screen'\\n    )\\n\\n    # 3. Launch RViz2 pre-loaded with the preset display configuration\\n    rviz2_node = Node(\\n        package='rviz2',\\n        executable='rviz2',\\n        name='rviz2',\\n        output='screen',\\n        arguments=['-d', rviz_config_path]\\n    )\\n\\n    return LaunchDescription([\\n        use_sim_time_arg,\\n        rsp_launch,\\n        joint_state_publisher_gui_node,\\n        rviz2_node\\n    ])\\n</code></pre>\\n</div>\\n\\n<h3 id=\\"63-configuring-saving-rviz2-profile\\">6.3 Step 3: Configuring &amp; Saving Your Custom RViz2 Profile</h3>\\n<p>\\n  When you open RViz2 for the first time, the display canvas is black. Follow this procedure to configure and save your permanent display profile:\\n</p>\\n<ol>\\n  <li>Launch the display pipeline:\\n    <div class=\\"code-container\\" data-language=\\"bash\\">\\n    <div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n    <pre><code class=\\"language-bash\\">ros2 launch nexus_amr_description display.launch.py</code></pre>\\n    </div>\\n  </li>\\n  <li><strong>Set Global Fixed Frame:</strong> In the left <em>Displays</em> panel under <strong>Global Options</strong>, click <strong>Fixed Frame</strong> and select <code class=\\"inline-code\\">base_footprint</code>.</li>\\n  <li><strong>Add Grid:</strong> Click <strong>Add</strong> at the bottom of the Displays panel, select <strong>Grid</strong>, and set Cell Size to <code class=\\"inline-code\\">0.5 m</code>.</li>\\n  <li><strong>Add RobotModel:</strong> Click <strong>Add</strong>, select <strong>RobotModel</strong>. Expand its properties, locate <strong>Description Topic</strong>, and ensure it is set to <code class=\\"inline-code\\">/robot_description</code>. Your cyan Nexus AMR chassis and wheels will appear immediately!</li>\\n  <li><strong>Add TF:</strong> Click <strong>Add</strong>, select <strong>TF</strong>. Set <strong>Marker Scale</strong> to <code class=\\"inline-code\\">0.3</code> to see crisp coordinate trihedrons floating at every link origin.</li>\\n  <li><strong>Save Configuration:</strong> Go to the RViz2 top menu: <strong>File &rarr; Save Config As</strong>, navigate to <code class=\\"inline-code\\">~/ros2_ws/src/nexus_amr_description/rviz/robot_model.rviz</code> and click <strong>Save</strong>.</li>\\n</ol>\\n\\n<h3 id=\\"64-verifying-kinematic-transforms\\">6.4 Step 4: Verifying Kinematic Transforms with tf2 Tools</h3>\\n<p>\\n  With <code class=\\"inline-code\\">display.launch.py</code> active, <code class=\\"inline-code\\">robot_state_publisher</code> processes the URDF joints and continuously broadcasts the complete kinematic tree to <code class=\\"inline-code\\">/tf</code> and <code class=\\"inline-code\\">/tf_static</code>. Verify the coordinate relationships using the official ROS 2 command-line diagnostic tools:\\n</p>\\n\\n<div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash (Echo Transform)</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\"># 1. Query the live transform from chassis (base_link) to LiDAR (lidar_1)\\nros2 run tf2_ros tf2_echo base_link lidar_1\\n\\n# Expected Output:\\n# At time 1792005400.123456789\\n# - Translation: [0.200, 0.000, 0.150]\\n# - Rotation: in Quaternion [0.000, 0.000, 0.000, 1.000]\\n# - Rotation: in RPY (radian) [0.000, -0.000, 0.000]\\n# - Rotation: in RPY (degree) [0.000, -0.000, 0.000]</code></pre>\\n</div>\\n\\n<div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash (Generate TF Tree Graph)</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\"># 2. Generate a visual PDF of the entire transform hierarchy\\nros2 run tf2_tools view_frames\\n\\n# 3. View the rendered tree in an image viewer\\nevince frames.pdf</code></pre>\\n</div>\\n\\n<div class=\\"alert-callout alert-tip\\"><div class=\\"alert-icon\\"></div><div class=\\"alert-body\\"><strong>Pro-Tip: Ad-Hoc Sensor Static Broadcasters:</strong> If you are testing a physical prototype sensor (such as an ultrasonic transducer or experimental camera) before encoding it into the official URDF, you can broadcast an ad-hoc static transform directly from the command line without recompiling packages:\\n<div class=\\"code-container\\" data-language=\\"bash\\" style=\\"margin: 0.6rem 0 0.5rem 0;\\">\\n  <div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n  <pre><code class=\\"language-bash\\">ros2 run tf2_ros static_transform_publisher --x 0.20 --y 0.0 --z 0.15 --yaw 0 --pitch 0 --roll 0 --frame-id base_link --child-frame-id aux_sensor_frame</code></pre>\\n</div>\\nOr programmatically inside any Python node using <code class=\\"inline-code\\">StaticTransformBroadcaster(self).sendTransform(transform_stamped)</code> with zero continuous CPU overhead (latched on <code class=\\"inline-code\\">/tf_static</code>).</div></div>\\n\\n<h2 id=\\"7-verification-steps-amp-expected-terminal-output\\">7. Verification Steps &amp; Expected Terminal Output</h2>\\n<p>Verify that your kinematic coordinate transforms are actively broadcasting across the ROS 2 network:</p>\\n\\n<div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash (TF2 Transform Inspection)</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\"># 1. Query real-time transform between chassis and top LiDAR:\\nros2 run tf2_ros tf2_echo base_link lidar_1\\n\\n# 2. Generate kinematic tree PDF diagram:\\nros2 run tf2_tools view_frames</code></pre>\\n</div>\\n\\n<p><em>Expected Terminal Output:</em></p>\\n<div class=\\"code-container\\" data-language=\\"text\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">text (Expected Verification Output)</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-text\\">At time 1792005120.450\\n- Translation: [0.100, 0.000, 0.180]\\n- Rotation: in Quaternion [0.000, 0.000, 0.000, 1.000]\\n            in RPY (radian) [0.000, -0.000, 0.000]\\n            in RPY (degree) [0.000, -0.000, 0.000]\\n\\nListening to tf for 5.0 seconds...\\nResult: Successfully generated frames.pdf containing 7 links and 6 active joints.</code></pre>\\n</div>\\n\\n<div class=\\"alert-callout alert-warning\\" style=\\"margin: 1.75rem 0;\\">\\n  <div class=\\"alert-icon\\">⚠️</div>\\n  <div class=\\"alert-body\\">\\n    <strong>Diagnostic Note: The \\"Missing TF Frame\\" Trap in RViz2:</strong><br>\\n    The #1 frustration for robotics students in RViz2 is the dreaded error: <em>\\"Fixed Frame [map] does not exist\\"</em> or seeing all robot links turn translucent red.<br><br>\\n    <strong>The Cause:</strong> RViz2 requires a unbroken chain of geometric transforms connecting the selected <strong>Fixed Frame</strong> to the robot's links.<br>\\n    <strong>The Fix:</strong> Launching <code class=\\"inline-code\\">robot_state_publisher</code> publishes transforms from your URDF. For autonomous navigation, SLAM Toolbox or AMCL provides the <code class=\\"inline-code\\">map &rarr; odom</code> transform, turning all frames green!\\n  </div>\\n</div>\\n\\n<div class=\\"asset-handoff-card\\" style=\\"margin: 1.75rem 0 1rem 0; padding: 1.15rem 1.4rem; border-radius: 10px; background: rgba(16, 185, 129, 0.06); border: 1px solid rgba(16, 185, 129, 0.25); border-left: 4px solid #10b981;\\">\\n  <div style=\\"display: flex; align-items: center; gap: 0.5rem; margin-bottom: 0.5rem;\\">\\n    <span style=\\"font-size: 1.1rem;\\">📦</span>\\n    <strong style=\\"font-size: 0.95rem; color: #10b981; text-transform: uppercase; letter-spacing: 0.04em;\\">Asset Handoff &amp; Next Lesson Pipeline Bridge</strong>\\n  </div>\\n  <p style=\\"margin: 0 0 0.65rem 0; font-size: 0.88rem; color: var(--text-primary); line-height: 1.6;\\">\\n    Your verified URDF display pipeline and saved RViz2 configuration profile establish the permanent kinematic visual ground-truth for all subsequent simulation and navigation modules.\\n  </p>\\n  <div style=\\"display: flex; flex-wrap: wrap; gap: 0.75rem; font-size: 0.82rem; font-family: var(--font-mono);\\">\\n    <span style=\\"background: var(--bg-surface); border: 1px solid var(--border-color); padding: 0.25rem 0.6rem; border-radius: 5px; color: var(--text-primary);\\">\\n      📁 <strong>Produced Artifacts:</strong> <code>ros2_ws_reference/src/nexus_amr_description/launch/display.launch.py &amp; rviz/robot_model.rviz</code>\\n    </span>\\n    <span style=\\"background: var(--bg-surface); border: 1px solid var(--border-color); padding: 0.25rem 0.6rem; border-radius: 5px; color: var(--text-primary);\\">\\n      ➡️ <strong>Ingested By:</strong> Lesson 11 (Gazebo Physics Simulation &amp; Sensor Plugins)\\n    </span>\\n  </div>\\n</div>\\n","quizzes":[{"id":"q_l1_18_1","prompt":"What is the universal color convention for coordinate frame axes (X, Y, Z) in RViz2?","options":["Red = X, Green = Y, Blue = Z (RGB = XYZ)","Red = Z, Green = X, Blue = Y","Blue = X, Green = Y, Red = Z","Yellow = X, Cyan = Y, Magenta = Z"],"correct":0,"explanation":"RViz2 strictly follows the RGB = XYZ standard: Red is the X-axis (Forward), Green is the Y-axis (Left), and Blue is the Z-axis (Up)."}],"has_quiz":true,"next_id":"lesson_11","prev_id":"lesson_09","subtopics":[{"id":"1-overview-learning-objectives","title":"1. Overview &amp; Learning Objectives"},{"id":"2-rviz2-vs-gazebo-the-essential-distinction","title":"2. RViz2 vs. Gazebo: The Essential Distinction"},{"id":"3-the-rgb-xyz-rule","title":"3. The RGB = XYZ Rule &amp; Spatial Coordinate Conventions (REP 103)"},{"id":"4-key-rviz2-displays-plugins","title":"4. Key RViz2 Displays &amp; Plugins"},{"id":"5-the-critical-fixed-frame-rule","title":"5. The Critical &quot;Fixed Frame&quot; Rule"},{"id":"6-building-the-launch-pipeline","title":"6. Building the Launch Pipeline: rsp.launch.py &amp; display.launch.py"},{"id":"7-verification-steps-amp-expected-terminal-output","title":"7. Verification Steps &amp; Expected Terminal Output"}]},{"id":"lesson_11","num":11,"num_str":"11","title":"Gazebo Physics Simulation & Sensor Plugins","slug":"16_gazebo_physics_and_sensor_plugins","filename":"16_gazebo_physics_and_sensor_plugins.md","module":"Day 2: 3D Robot Modeling & Physics Simulation","module_id":2,"duration":"45-60 min","focus":"Gazebo Physics Simulation, Differential Drive Controller, 2D LiDAR Ray Sensor, and RGB Camera Sensor Plugin","snapshot":[["ODE Physics Engine","Simulates rigid-body dynamics, surface contact friction (mu1, mu2), gravity, and wheel inertia on ground terrain."],["Differential Drive Plugin","libgazebo_ros_diff_drive.so subscribes to /cmd_vel, computes wheel RPMs, and broadcasts /odom telemetry and TF transforms."],["Ray Sensor 2D LiDAR","libgazebo_ros_ray_sensor.so simulates laser rangefinding raycasts across 360 degrees and publishes sensor_msgs/LaserScan to /scan."],["RGB Stereo Camera Plugin","libgazebo_ros_camera.so renders synthetic visual camera frames and publishes sensor_msgs/Image at 30 FPS."]],"html_content":"<h2 id=\\"1-overview-learning-objectives\\">1. Overview &amp; Learning Objectives</h2>\\n<p>Testing navigation code on physical hardware carries real risks: collision damage, battery discharge, and hardware downtime. Physics simulation in <strong>Gazebo</strong> allows robotics developers to test autonomous algorithms in safe, repeatable, photorealistic environments.</p>\\n<p><div class=\\"learning-objectives-card\\">\\n  <div class=\\"learning-objectives-header\\">\\n    <div class=\\"objectives-icon-badge\\">\\n      <span style=\\"font-size: 1.15rem; line-height: 1;\\">🎯</span>\\n    </div>\\n    <div class=\\"objectives-title-group\\">\\n      <h3 class=\\"objectives-main-title\\">Learning Objectives &amp; Core Outcomes</h3>\\n      <span class=\\"objectives-subtitle\\">By the end of this lesson, you will be able to:</span>\\n    </div>\\n    <span class=\\"objectives-count-badge\\">5 CORE OUTCOMES</span>\\n  </div>\\n  <ul class=\\"learning-objectives-list\\">\\n    <li class=\\"learning-objective-item\\">\\n      <span class=\\"objective-num-badge\\">1</span>\\n      <span class=\\"objective-text\\">Understand Gazebo architecture: the backend physics server (<code class=\\"inline-code\\">gzserver</code>) vs. frontend visual renderer (<code class=\\"inline-code\\">gzclient</code>).</span>\\n    </li>\\n    <li class=\\"learning-objective-item\\">\\n      <span class=\\"objective-num-badge\\">2</span>\\n      <span class=\\"objective-text\\">Configure the <strong>Gazebo Differential Drive Plugin</strong> (<code class=\\"inline-code\\">libgazebo_ros_diff_drive.so</code>) to translate <code class=\\"inline-code\\">/cmd_vel</code> into simulated motor torques and wheel odometry.</span>\\n    </li>\\n    <li class=\\"learning-objective-item\\">\\n      <span class=\\"objective-num-badge\\">3</span>\\n      <span class=\\"objective-text\\">Configure the <strong>Gazebo 2D LiDAR Ray Sensor Plugin</strong> (<code class=\\"inline-code\\">libgazebo_ros_ray_sensor.so</code>) with realistic Gaussian noise.</span>\\n    </li>\\n    <li class=\\"learning-objective-item\\">\\n      <span class=\\"objective-num-badge\\">4</span>\\n      <span class=\\"objective-text\\">Configure the <strong>Gazebo IMU Plugin</strong> (<code class=\\"inline-code\\">libgazebo_ros_imu_sensor.so</code>) for orientation and acceleration data.</span>\\n    </li>\\n    <li class=\\"learning-objective-item\\">\\n      <span class=\\"objective-num-badge\\">5</span>\\n      <span class=\\"objective-text\\">Spawn the robot into the simulation world using the <code class=\\"inline-code\\">spawn_entity.py</code> service.</span>\\n    </li>\\n  </ul>\\n</div>\\n\\n<h2 id=\\"2-gazebo-architecture\\">2. Gazebo Simulation Architecture &amp; Physics Engine Mechanics</h2>\\n<p>\\n  While RViz2 is an observer of the robot's internal state, <strong>Gazebo (Harmonic / Sim)</strong> serves as the <em>ground-truth physical universe</em>. Gazebo is a multi-robot physics simulation engine that computes rigid-body dynamics, simulates gravitational and frictional forces, and generates realistic synthetic sensor data directly from virtual 3D environments.\\n</p>\\n\\n<p><img src=\\"assets/images/gazebo_gui_interface_real.png\\" alt=\\"Official Gazebo Simulation Graphical User Interface &amp; Differential Drive AMR\\" class=\\"lesson-image\\" loading=\\"lazy\\" /></p>\\n\\n<div class=\\"alert-callout alert-tip\\" style=\\"margin: 1.75rem 0;\\">\\n  <div class=\\"alert-icon\\">🔄</div>\\n  <div class=\\"alert-body\\">\\n    <strong>Verification Note: Commanded vs Measured Velocity:</strong><br>\\n    Verify that motor velocity commands directly produce measured kinematic odometry in the physics simulator:<br>\\n    <div class=\\"code-container\\" data-language=\\"bash\\" style=\\"margin: 0.5rem 0 0.3rem 0;\\">\\n      <div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n      <pre><code class=\\"language-bash\\"># In Terminal 1: Publish forward velocity command (0.3 m/s)\\nros2 topic pub /cmd_vel geometry_msgs/msg/Twist \\"{linear: {x: 0.3}, angular: {z: 0.0}}\\" -r 10\\n\\n# In Terminal 2: Sample measured wheel odometry telemetry\\nros2 topic echo /odom --field twist.twist.linear.x --once\\n# Expected Output: 0.298 (Confirms physical wheel traction and velocity tracking!)</code></pre>\\n    </div>\\n  </div>\\n</div>\\n\\n<div class=\\"code-breakdown-card\\" style=\\"margin-top: 1.5rem; margin-bottom: 1.5rem;\\">\\n  <h4 class=\\"code-breakdown-title\\">🔬 Gazebo Simulation Architecture &amp; GUI Anatomy Deep Dive</h4>\\n  <p class=\\"code-breakdown-intro\\">Understanding the five foundational pillars of the Gazebo physics simulation environment:</p>\\n  <ul class=\\"code-breakdown-list\\">\\n    <li class=\\"code-breakdown-item\\">\\n      <strong>① Top Transform Gizmos &amp; Entity Spawner Ribbon:</strong> Provides 3D spatial transformation gizmos for translating (<code class=\\"inline-code\\">T</code>), rotating (<code class=\\"inline-code\\">R</code>), and scaling (<code class=\\"inline-code\\">S</code>) models in the virtual world. The spawner toolbar allows engineers to drop geometric primitives (Boxes, Cylinders, Spheres) and warehouse obstacle models directly into the simulation while running. The inspection toggles visualize green <code class=\\"inline-code\\">&lt;collision&gt;</code> bounds and red <code class=\\"inline-code\\">&lt;inertial&gt;</code> mass centers.\\n    </li>\\n    <li class=\\"code-breakdown-item\\">\\n      <strong>② Left Entity Tree &amp; Component Inspector:</strong> Hierarchically lists every active entity in the simulation world: the physics engine parameters, directional sunlight, ground plane, and spawned robot models. Selecting a component (such as <code class=\\"inline-code\\">left_wheel</code>) displays its physical surface properties: friction coefficients (<code class=\\"inline-code\\">mu1</code>, <code class=\\"inline-code\\">mu2</code>), stiffness (<code class=\\"inline-code\\">kp</code>), damping (<code class=\\"inline-code\\">kd</code>), and joint torque limits.\\n    </li>\\n    <li class=\\"code-breakdown-item\\">\\n      <strong>③ Central 3D Physics Viewport:</strong> Renders the physical world with directional shadows and real-time contact patches. Gazebo computes Newton's second law (<strong>F</strong> = <em>m</em><strong>a</strong>) and normal ground reaction forces (F<sub>n</sub>) between the AMR drive wheels and the floor plane at every step. Virtual sensor ray-casters project 360° LiDAR laser beams that intersect physical obstacle meshes and calculate real-time range distances.\\n    </li>\\n    <li class=\\"code-breakdown-item\\">\\n      <strong>④ Right Physics Solver &amp; ROS 2 Bridge Configuration:</strong> Configures the underlying numerical integrator (ODE, Bullet, or DART). Parameters include <code class=\\"inline-code\\">max_step_size: 0.001s</code> (1 ms updates at 1000 Hz), solver iteration count, and constraint force mixing (CFM). It also monitors the bidirectional communication bridge (<code class=\\"inline-code\\">ros_gz_bridge</code>) connecting Gazebo topics to ROS 2.\\n    </li>\\n    <li class=\\"code-breakdown-item\\">\\n      <strong>⑤ Bottom Simulation Time Engine &amp; RTF Monitor:</strong> Controls physics execution (<code class=\\"inline-code\\">Play</code>, <code class=\\"inline-code\\">Pause</code>, <code class=\\"inline-code\\">Step 1ms</code>). Crucially, Gazebo publishes the simulation timestamp to the <code class=\\"inline-code\\">/clock</code> topic and calculates the <strong>Real-Time Factor (RTF)</strong>: <code class=\\"inline-code\\">RTF = Δt_sim / Δt_wall</code>. When RTF = 1.00x, simulation time advances exactly in lockstep with wall-clock time!\\n    </li>\\n  </ul>\\n</div>\\n\\n<h3 id=\\"21-physics-engines-time-synchronization-clock\\">2.1 Physics Engines, Ray-Tracing &amp; The Simulation Clock (<code class=\\"inline-code\\">/clock</code>)</h3>\\n<p>\\n  To achieve realistic AMR simulation, Gazebo coordinates three tightly-coupled computational engines:\\n</p>\\n\\n<div style=\\"display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 1rem; margin: 1.25rem 0;\\">\\n  <div style=\\"background: var(--bg-surface); border: 1px solid var(--border-color); border-radius: 8px; padding: 1.1rem; border-top: 3px solid #f97316;\\">\\n    <div style=\\"font-weight: 800; color: #f97316; font-size: 0.95rem; margin-bottom: 0.4rem;\\">⚙️ 1. Rigid-Body Dynamics (ODE)</div>\\n    <p style=\\"font-size: 0.85rem; color: var(--text-secondary); margin: 0; line-height: 1.55;\\">\\n      Resolves multi-body constraint equations using Linear Complementarity Problem (LCP) solvers. When differential drive wheel torques are commanded via <code class=\\"inline-code\\">/cmd_vel</code>, ODE calculates friction forces, wheel traction, and wheel slip against the ground plane.\\n    </p>\\n  </div>\\n  <div style=\\"background: var(--bg-surface); border: 1px solid var(--border-color); border-radius: 8px; padding: 1.1rem; border-top: 3px solid #38bdf8;\\">\\n    <div style=\\"font-weight: 800; color: #38bdf8; font-size: 0.95rem; margin-bottom: 0.4rem;\\">📡 2. Sensor Ray-Tracing &amp; Optics</div>\\n    <p style=\\"font-size: 0.85rem; color: var(--text-secondary); margin: 0; line-height: 1.55;\\">\\n      For 2D LiDAR, Gazebo casts hundreds of laser rays across the 3D polygon meshes, computing precise ray-surface intersection distances and injecting configurable Gaussian noise. Cameras use GPU shaders to render synthetic RGB frames and depth buffers.\\n    </p>\\n  </div>\\n  <div style=\\"background: var(--bg-surface); border: 1px solid var(--border-color); border-radius: 8px; padding: 1.1rem; border-top: 3px solid #10b981;\\">\\n    <div style=\\"font-weight: 800; color: #10b981; font-size: 0.95rem; margin-bottom: 0.4rem;\\">⏱️ 3. Deterministic Simulation Clock</div>\\n    <p style=\\"font-size: 0.85rem; color: var(--text-secondary); margin: 0; line-height: 1.55;\\">\\n      Gazebo publishes simulated time to <code class=\\"inline-code\\">/clock</code>. By launching ROS 2 nodes with parameter <code class=\\"inline-code\\">use_sim_time:=true</code>, navigation nodes freeze CPU wall-clock dependencies and synchronize perfectly with Gazebo's physics time-step.\\n    </p>\\n  </div>\\n</div>\\n\\n<p>\\n  The diagram below illustrates how Gazebo's backend physics engine links to the ROS 2 DDS middleware layer via plugins and topic bridges:\\n</p>\\n\\n<p><img src=\\"assets/images/gazebo_simulation_bridge.svg\\" alt=\\"Gazebo Simulation Bridge: ODE Physics Engine &lt;---&gt; ROS 2 DDS Middleware\\" class=\\"lesson-image\\" loading=\\"lazy\\" /></p>\\n<hr class=\\"divider\\">\\n<h2 id=\\"3-the-differential-drive-controller-plugin\\">3. The Differential Drive Controller Plugin</h2>\\n<p>To enable realistic physical locomotion and sensor data streaming in Gazebo, create a new physics and sensor plugin Xacro file: <code class=\\"inline-code\\">~/ros2_ws/src/nexus_amr_description/urdf/gazebo_plugins.xacro</code>:</p>\\n<p><div class=\\"code-container\\" data-language=\\"xml\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">xml</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-xml\\">&lt;gazebo&gt;\\n  &lt;plugin name=&quot;nexus_diff_drive&quot; filename=&quot;libgazebo_ros_diff_drive.so&quot;&gt;\\n    &lt;!-- Remappings to connect with standard ROS 2 topics --&gt;\\n    &lt;ros&gt;\\n      &lt;namespace&gt;/&lt;/namespace&gt;\\n      &lt;remapping&gt;cmd_vel:=cmd_vel&lt;/remapping&gt;\\n      &lt;remapping&gt;odom:=odom&lt;/remapping&gt;\\n    &lt;/ros&gt;\\n\\n    &lt;!-- Physical Wheel Joints from URDF --&gt;\\n    &lt;left_joint&gt;left_wheel_joint&lt;/left_joint&gt;\\n    &lt;right_joint&gt;right_wheel_joint&lt;/right_joint&gt;\\n\\n    &lt;!-- Kinematics Constants --&gt;\\n    &lt;wheel_separation&gt;0.32&lt;/wheel_separation&gt;\\n    &lt;wheel_diameter&gt;0.12&lt;/wheel_diameter&gt;\\n\\n    &lt;!-- Motor Torque Limits --&gt;\\n    &lt;max_wheel_torque&gt;20.0&lt;/max_wheel_torque&gt;\\n    &lt;max_wheel_acceleration&gt;1.5&lt;/max_wheel_acceleration&gt;\\n\\n    &lt;!-- Output Topics &amp; TF Broadcast --&gt;\\n    &lt;publish_odom&gt;true&lt;/publish_odom&gt;\\n    &lt;publish_odom_tf&gt;true&lt;/publish_odom_tf&gt;\\n    &lt;publish_wheel_tf&gt;true&lt;/publish_wheel_tf&gt;\\n\\n    &lt;odometry_frame&gt;odom&lt;/odometry_frame&gt;\\n    &lt;robot_base_frame&gt;base_footprint&lt;/robot_base_frame&gt;\\n    &lt;update_rate&gt;50.0&lt;/update_rate&gt;\\n  &lt;/plugin&gt;\\n&lt;/gazebo&gt;\\n</code></pre>\\n</div>\\n</p>\\n<h3 id=\\"key-parameters\\">Key Parameters:</h3>\\n<ul>\\n<li><code class=\\"inline-code\\">&lt;wheel_separation&gt;</code>: Distance between left and right wheel contact patches from CAD (0.114m). If this value is incorrect in the plugin, turning commands will produce inaccurate angular velocities.</li>\\n<li><code class=\\"inline-code\\">&lt;wheel_diameter&gt;</code>: Diameter of the drive wheels from CAD (0.06m). Drives linear speed calculation.</li>\\n<li><code class=\\"inline-code\\">&lt;publish_odom_tf&gt;</code>: When set to <code class=\\"inline-code\\">true</code>, the plugin broadcasts the dynamic <code class=\\"inline-code\\">odom -&gt; base_footprint</code> transform automatically.</li>\\n</ul>\\n<hr class=\\"divider\\">\\n<h2 id=\\"4-the-2d-lidar-ray-sensor-plugin\\">4. The 2D LiDAR Ray Sensor Plugin</h2>\\n<p>Open the existing LiDAR sensor file created in Lesson 09: <code class=\\"inline-code\\">~/ros2_ws/src/nexus_amr_description/urdf/gazebo_plugins.xacro</code> and add the Gazebo ray sensor plugin before the closing <code class=\\"inline-code\\">&lt;/robot&gt;</code> tag:</p>\\n<p><div class=\\"code-container\\" data-language=\\"xml\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">xml</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-xml\\">&lt;gazebo reference=&quot;laser_frame&quot;&gt;\\n  &lt;sensor name=&quot;laser_sensor&quot; type=&quot;ray&quot;&gt;\\n    &lt;pose&gt;0 0 0 0 0 0&lt;/pose&gt;\\n    &lt;visualize&gt;false&lt;/visualize&gt;\\n    &lt;update_rate&gt;10.0&lt;/update_rate&gt;\\n    &lt;ray&gt;\\n      &lt;scan&gt;\\n        &lt;horizontal&gt;\\n          &lt;samples&gt;360&lt;/samples&gt;\\n          &lt;resolution&gt;1&lt;/resolution&gt;\\n          &lt;min_angle&gt;-3.14159265&lt;/min_angle&gt;\\n          &lt;max_angle&gt;3.14159265&lt;/max_angle&gt;\\n        &lt;/horizontal&gt;\\n      &lt;/scan&gt;\\n      &lt;range&gt;\\n        &lt;min&gt;0.15&lt;/min&gt;\\n        &lt;max&gt;12.0&lt;/max&gt;\\n        &lt;resolution&gt;0.01&lt;/resolution&gt;\\n      &lt;/range&gt;\\n      &lt;noise&gt;\\n        &lt;type&gt;gaussian&lt;/type&gt;\\n        &lt;mean&gt;0.0&lt;/mean&gt;\\n        &lt;stddev&gt;0.01&lt;/stddev&gt; &lt;!-- 1cm simulated measurement noise --&gt;\\n      &lt;/noise&gt;\\n    &lt;/ray&gt;\\n    &lt;plugin name=&quot;nexus_laser_controller&quot; filename=&quot;libgazebo_ros_ray_sensor.so&quot;&gt;\\n      &lt;ros&gt;\\n        &lt;argument&gt;~/out:=scan&lt;/argument&gt;\\n      &lt;/ros&gt;\\n      &lt;output_type&gt;sensor_msgs/LaserScan&lt;/output_type&gt;\\n      &lt;frame_name&gt;laser_frame&lt;/frame_name&gt;\\n    &lt;/plugin&gt;\\n  &lt;/sensor&gt;\\n&lt;/gazebo&gt;\\n</code></pre>\\n</div>\\n</p>\\n<hr class=\\"divider\\">\\n\\n<hr class=\\"divider\\">\\n<h2 id=\\"5-the-rgb-camera-sensor-plugin\\">5. The RGB Camera Sensor Plugin (<code class=\\"inline-code\\">libgazebo_ros_camera.so</code>)</h2>\\n<p>To provide visual perception for obstacle classification and AI vision workloads, open the existing camera sensor file authored in Lesson 09: <code class=\\"inline-code\\">~/ros2_ws/src/nexus_amr_description/urdf/camera.xacro</code> and append the Gazebo camera sensor plugin before the closing <code class=\\"inline-code\\">&lt;/robot&gt;</code> tag. Gazebo renders 3D camera views and publishes ROS 2 image streams:</p>\\n\\n<div class=\\"code-container ide-code-window\\">\\n  <div class=\\"code-header\\">\\n    <div class=\\"code-dots\\"><span class=\\"dot red\\"></span><span class=\\"dot yellow\\"></span><span class=\\"dot green\\"></span></div>\\n    <span class=\\"code-filename\\">camera.xacro &mdash; Gazebo Camera Sensor Plugin</span>\\n  </div>\\n  <pre><code class=\\"language-xml\\">&lt;gazebo reference=\\"camera_link\\"&gt;\\n  &lt;material&gt;Gazebo/Orange&lt;/material&gt;\\n  &lt;sensor name=\\"amr_rgb_camera\\" type=\\"camera\\"&gt;\\n    &lt;update_rate&gt;30.0&lt;/update_rate&gt;\\n    &lt;camera name=\\"front_camera\\"&gt;\\n      &lt;horizontal_fov&gt;1.085595&lt;/horizontal_fov&gt;\\n      &lt;image&gt;\\n        &lt;width&gt;640&lt;/width&gt;\\n        &lt;height&gt;480&lt;/height&gt;\\n        &lt;format&gt;R8G8B8&lt;/format&gt;\\n      &lt;/image&gt;\\n      &lt;clip&gt;\\n        &lt;near&gt;0.05&lt;/near&gt;\\n        &lt;far&gt;8.0&lt;/far&gt;\\n      &lt;/clip&gt;\\n    &lt;/camera&gt;\\n    &lt;plugin name=\\"nexus_camera_controller\\" filename=\\"libgazebo_ros_camera.so\\"&gt;\\n      &lt;ros&gt;\\n        &lt;remapping&gt;image_raw:=camera/image_raw&lt;/remapping&gt;\\n        &lt;remapping&gt;camera_info:=camera/camera_info&lt;/remapping&gt;\\n      &lt;/ros&gt;\\n      &lt;frame_name&gt;camera_link&lt;/frame_name&gt;\\n    &lt;/plugin&gt;\\n  &lt;/sensor&gt;\\n&lt;/gazebo&gt;</code></pre>\\n</div>\\n\\n<p>When running Gazebo, the robot publishes live image frames to <code class=\\"inline-code\\">/camera/image_raw</code> and camera calibration matrices to <code class=\\"inline-code\\">/camera/camera_info</code> at 30 FPS.</p>\\n\\n<div class=\\"alert-callout alert-tip\\"><div class=\\"alert-icon\\"></div><div class=\\"alert-body\\"><strong>Pipeline Integration:</strong> Now open the existing robot model <code class=\\"inline-code\\">~/ros2_ws/src/nexus_amr_description/urdf/nexus_amr.urdf.xacro</code> (created in Lesson 09) and include your plugin definitions before the closing <code class=\\"inline-code\\">&lt;/robot&gt;</code> tag:\\n<div class=\\"code-container\\" data-language=\\"xml\\" style=\\"margin: 0.6rem 0 0.5rem 0;\\">\\n  <div class=\\"code-header\\"><span class=\\"code-lang-tag\\">xml</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n  <pre><code class=\\"language-xml\\">&lt;!-- Gazebo Differential Drive, LiDAR &amp; Camera Sensor Plugins --&gt;\\n&lt;xacro:include filename=\\"gazebo_plugins.xacro\\" /&gt;</code></pre>\\n</div>\\n</div></div>\\n\\n<h2 id=\\"6-spawning-the-robot-into-gazebo\\">6. Creating the Simulation Bringup Launch File (sim_world.launch.py)</h2>\\n<p>\\n  Create the master simulation launch file: <code class=\\"inline-code\\">~/ros2_ws/src/nexus_amr_gazebo/launch/sim_world.launch.py</code>. This launch file orchestrates <code class=\\"inline-code\\">gzserver</code> (physics engine), <code class=\\"inline-code\\">gzclient</code> (3D OpenGL window), <code class=\\"inline-code\\">rsp.launch.py</code> (Robot State Publisher), and <code class=\\"inline-code\\">spawn_entity.py</code> to inject the AMR model into the physics world:\\n</p>\\n\\n<div class=\\"code-container\\" data-language=\\"python\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">python (sim_world.launch.py)</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-python\\">import os\\nfrom ament_index_python.packages import get_package_share_directory\\nfrom launch import LaunchDescription\\nfrom launch.actions import DeclareLaunchArgument, IncludeLaunchDescription\\nfrom launch.launch_description_sources import PythonLaunchDescriptionSource\\nfrom launch.substitutions import LaunchConfiguration\\nfrom launch_ros.actions import Node\\n\\n\\ndef generate_launch_description():\\n    pkg_gazebo = get_package_share_directory('nexus_amr_gazebo')\\n    pkg_description = get_package_share_directory('nexus_amr_description')\\n    pkg_gazebo_ros = get_package_share_directory('gazebo_ros')\\n\\n    default_world = os.path.join(pkg_gazebo, 'worlds', 'house.world')\\n\\n    # Ensure Gazebo locates custom models inside share/nexus_amr_gazebo/models\\n    models_dir = os.path.join(pkg_gazebo, 'models')\\n    set_gazebo_model_path = AppendEnvironmentVariable(\\n        name='GAZEBO_MODEL_PATH',\\n        value=models_dir\\n    )\\n\\n    world_arg = DeclareLaunchArgument(\\n        'world',\\n        default_value=default_world,\\n        description='Path to Gazebo .world file'\\n    )\\n    use_sim_time_arg = DeclareLaunchArgument(\\n        'use_sim_time',\\n        default_value='true',\\n        description='Synchronize clock with Gazebo /clock'\\n    )\\n    gui_arg = DeclareLaunchArgument(\\n        'gui',\\n        default_value='true',\\n        description='Set true for 3D GUI client; false for headless'\\n    )\\n\\n    # 1. Physics Engine Server (gzserver)\\n    gzserver = IncludeLaunchDescription(\\n        PythonLaunchDescriptionSource(os.path.join(pkg_gazebo_ros, 'launch', 'gzserver.launch.py')),\\n        launch_arguments={'world': LaunchConfiguration('world'), 'verbose': 'true'}.items()\\n    )\\n\\n    # 2. GUI Client (gzclient)\\n    gzclient = IncludeLaunchDescription(\\n        PythonLaunchDescriptionSource(os.path.join(pkg_gazebo_ros, 'launch', 'gzclient.launch.py')),\\n        launch_arguments={'verbose': 'true'}.items()\\n    )\\n\\n    # 3. Robot State Publisher (RSP from Lesson 10)\\n    rsp_launch = IncludeLaunchDescription(\\n        PythonLaunchDescriptionSource(os.path.join(pkg_description, 'launch', 'rsp.launch.py')),\\n        launch_arguments={'use_sim_time': LaunchConfiguration('use_sim_time')}.items()\\n    )\\n\\n    # 4. Spawn Robot Model into World\\n    spawn_robot = Node(\\n        package='gazebo_ros',\\n        executable='spawn_entity.py',\\n        name='spawn_nexus_robot',\\n        output='screen',\\n        arguments=[\\n            '-topic', 'robot_description',\\n            '-entity', 'nexus_amr',\\n            '-x', '0.0', '-y', '0.0', '-z', '0.05'\\n        ]\\n    )\\n\\n    return LaunchDescription([\\n        world_arg, use_sim_time_arg, gui_arg,\\n        gzserver, gzclient, rsp_launch, spawn_robot\\n    ])\\n</code></pre>\\n</div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"7-execution-verification\\">7. Execution &amp; Verification</h2>\\n<p><strong>Terminal 1: Launch Gazebo Physics Simulation &amp; Robot Spawner</strong></p>\\n<p><div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\">ros2 launch nexus_amr_gazebo sim_world.launch.py\\n</code></pre>\\n</div>\\n</p>\\n<p><strong>Terminal 2: Verify Sensor Streams &amp; Command Drive Velocity</strong></p>\\n<p><div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\"># 1. Check LiDAR scanning at 10 Hz\\nros2 topic hz /scan\\n\\n# 2. Check wheel odometry streaming at 50 Hz\\nros2 topic hz /odom\\n\\n# 3. Check IMU acceleration streaming at 50 Hz\\nros2 topic hz /imu/data\\n\\n# 4. Drive the robot forward in simulation!\\nros2 topic pub --once /cmd_vel geometry_msgs/msg/Twist &quot;{linear: {x: 0.3}, angular: {z: 0.0}}&quot;\\n</code></pre>\\n</div>\\n</p>\\n\\n<p><strong>Terminal 3: Interactive Keyboard Teleoperation (Optional Live Driving)</strong></p>\\n<div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\"># Drive the simulated AMR in Gazebo via keyboard\\nros2 run teleop_twist_keyboard teleop_twist_keyboard</code></pre>\\n</div>\\n\\n<hr class=\\"divider\\">\\n<hr class=\\"divider\\">\\n<h2 id=\\"8-hands-on-student-challenge\\">8. Hands-on Student Challenge: Differential Drive Odometer & Kinematic Tracking Validator</h2>\\n<p>Construct an odometry validator node to verify wheel odometry emitted by Gazebo's differential drive simulation plugin against commanded velocity inputs.</p>\\n\\n<div class=\\"alert alert-tip\\">\\n  <div class=\\"alert-title\\">🎯 Mission Requirements</div>\\n  <ol>\\n    <li><strong>TODO 1:</strong> Subscribe to <code class=\\"inline-code\\">/odom</code> (<code class=\\"inline-code\\">nav_msgs/msg/Odometry</code>) to capture physical velocity.</li>\\n    <li><strong>TODO 2:</strong> Subscribe to <code class=\\"inline-code\\">/cmd_vel</code> (<code class=\\"inline-code\\">geometry_msgs/msg/Twist</code>) to capture commanded velocity.</li>\\n    <li><strong>TODO 3:</strong> In <code class=\\"inline-code\\">odom_callback</code>, store linear speed and live position.</li>\\n    <li><strong>TODO 4:</strong> In 2 Hz loop, compute slip delta <code class=\\"inline-code\\">abs(cmd_vel - odom_vel)</code> and log diagnostics.</li>\\n  </ol>\\n</div>\\n\\n\\n<div class=\\"alert alert-info alert-briefing\\">\\n  <div class=\\"alert-icon\\">🚜</div>\\n  <div class=\\"alert-content\\">\\n    <div class=\\"alert-title\\">Robotics Flight Operations Mission Briefing: Differential Drive Odometer &amp; Kinematic Tracking Validator</div>\\n    <div class=\\"alert-body\\">\\n      <strong>Physical AMR Context &amp; Operational Challenge:</strong><br>\\n      Differential drive AMRs steer by varying the relative speeds of their left and right wheels. As the robot traverses a factory floor, onboard optical wheel encoders report rotational displacement. To maintain an accurate estimate of where the robot is located relative to its starting origin (\`odom\` frame), dead-reckoning equations integrate these encoder pulses over time.\\n      <br><br>\\n      <strong>Architectural Role &amp; Why This Mechanism:</strong><br>\\n      The <code>nav_msgs/msg/Odometry</code> interface packages both the robot's 2D/3D pose <code class=\\"inline-code\\">(x, y, θ)</code> and its instantaneous linear and angular twist velocities <code class=\\"inline-code\\">(v_x, v_y, ω_z)</code>, alongside 36-element covariance matrices that quantify measurement uncertainty. Downstream SLAM and EKF sensor fusion algorithms rely directly on this telemetry.\\n      <br><br>\\n      <strong>Flight Objective &amp; Behavioral Outcome:</strong><br>\\n      Implement the <code>DiffDriveTelemetry</code> node. In a 20 Hz control loop, apply forward Euler kinematic integration to compute displacement from wheel velocities, construct the <code>Odometry</code> message, and broadcast the dynamic TF transform from <code>odom</code> to <code>base_link</code>.\\n    </div>\\n  </div>\\n</div>\\n\\n<h3 id=\\"71-starter-template\\">7.1 Starter Template: <code class=\\"inline-code\\">m02_l11_task_diff_drive_telemetry.py</code></h3>\\n<p>Copy the starter template from the reference workspace into your active student workspace:</p>\\n<div class=\\"code-container\\" data-language=\\"bash\\">\\n  <div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n  <pre><code class=\\"language-bash\\">cp ~/ros2_ws_reference/src/nexus_amr_basics/nexus_amr_basics/m02_l11_task_diff_drive_telemetry.py ~/ros2_ws/src/nexus_amr_basics/nexus_amr_basics/</code></pre>\\n</div>\\n<p>Open the copied file in your editor and complete the marked <code class=\\"inline-code\\">TODO</code> targets:</p>\\n\\n<div class=\\"code-container\\" data-language=\\"python\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">python</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-python\\">#!/usr/bin/env python3\\n&quot;&quot;&quot;\\n================================================================================\\nNexus AMR Learning Hub - Level 1: Module 2 / Lesson 11 Task\\nPackage: nexus_amr_basics\\nTask:    m02_l11_task_diff_drive_telemetry.py (alias: task_diff_drive)\\n================================================================================\\n\\nEXERCISE OVERVIEW:\\n------------------\\nYour mission is to construct a Differential Drive Odometer &amp; Kinematic Tracking\\nValidator node to verify wheel odometry emitted by the Gazebo diff-drive plugin.\\n\\nOBJECTIVES:\\n-----------\\n1. TODO 1: Subscribe to \`/odom\` (nav_msgs/msg/Odometry) to receive measured velocity.\\n2. TODO 2: Subscribe to \`/cmd_vel\` (geometry_msgs/msg/Twist) to capture target velocity.\\n3. TODO 3: In \`odom_callback\`, store measured linear.x and pose coordinates.\\n4. TODO 4: In 2 Hz evaluation loop, compute velocity slip/error:\\n   \`error = abs(cmd_linear_x - measured_linear_x)\` and log diagnostics.\\n================================================================================\\n&quot;&quot;&quot;\\n\\nimport rclpy\\nfrom rclpy.node import Node\\nfrom rclpy.executors import ExternalShutdownException\\nfrom geometry_msgs.msg import Twist\\nfrom nav_msgs.msg import Odometry\\n\\n\\nclass DiffDriveTelemetryValidator(Node):\\n\\n    def __init__(self):\\n        super(<em style=\\"color: #10b981;\\">F</em><sub>n</sub>).__init__(&#x27;diff_drive_telemetry_validator&#x27;)\\n\\n        self.target_linear_x = 0.0\\n        self.measured_linear_x = 0.0\\n        self.current_x = 0.0\\n        self.current_y = 0.0\\n\\n        # ======================================================================\\n        # TODO 1: Subscribe to &#x27;/odom&#x27; (Odometry)\\n        # - Hint: Call self.create_subscription(<em style=\\"color: #10b981;\\">F</em><sub>n</sub>) for Odometry messages from &#x27;/odom&#x27;.\\n        # ======================================================================\\n        # ---&gt; YOUR CODE HERE &lt;---\\n\\n        # ======================================================================\\n        # TODO 2: Subscribe to &#x27;/cmd_vel&#x27; (Twist)\\n        # - Hint: Call self.create_subscription(<em style=\\"color: #10b981;\\">F</em><sub>n</sub>) for Twist messages from &#x27;/cmd_vel&#x27;.\\n        # ======================================================================\\n        # ---&gt; YOUR CODE HERE &lt;---\\n\\n        self.timer = self.create_timer(0.5, self.evaluate_tracking)\\n        self.get_logger(<em style=\\"color: #10b981;\\">F</em><sub>n</sub>).info(&#x27;DiffDriveTelemetryValidator listening to /odom and /cmd_vel...&#x27;)\\n\\n    def cmd_vel_callback(self, msg: Twist):\\n        # Cache commanded linear velocity\\n        self.target_linear_x = msg.linear.x\\n\\n    def odom_callback(self, msg: Odometry):\\n        # ======================================================================\\n        # TODO 3: Extract measured linear velocity and position\\n        # - Hint: Extract measured linear.x from msg.twist.twist and extract 2D position (x, y) from msg.pose.pose.position.\\n        # ======================================================================\\n        # ---&gt; YOUR CODE HERE &lt;---\\n        pass\\n\\n    def evaluate_tracking(self):\\n        # ======================================================================\\n        # TODO 4: Compute tracking delta and log diagnostics\\n        # - Hint: Calculate the absolute difference between commanded and measured velocity, then log the tracking telemetry and position.\\n        # ======================================================================\\n        # ---&gt; YOUR CODE HERE &lt;---\\n        pass\\n\\n\\ndef main(args=None):\\n    rclpy.init(args=args)\\n    node = DiffDriveTelemetryValidator(<em style=\\"color: #10b981;\\">F</em><sub>n</sub>)\\n\\n    try:\\n        rclpy.spin(node)\\n    except (KeyboardInterrupt, ExternalShutdownException):\\n        pass\\n    finally:\\n        node.destroy_node(<em style=\\"color: #10b981;\\">F</em><sub>n</sub>)\\n        if rclpy.ok(<em style=\\"color: #10b981;\\">F</em><sub>n</sub>):\\n            rclpy.shutdown(<em style=\\"color: #10b981;\\">F</em><sub>n</sub>)\\n\\n\\nif __name__ == &#x27;__main__&#x27;:\\n    main(<em style=\\"color: #10b981;\\">F</em><sub>n</sub>)\\n</code></pre>\\n</div>\\n\\n<h3 id=\\"72-verification-steps\\">7.2 Verification Steps &amp; Expected Terminal Output</h3>\\n<p>Run your node or test command and observe the output:</p>\\n<div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\">ros2 run nexus_amr_basics diff_drive_telemetry</code></pre>\\n</div>\\n\\n<p><em>Expected Terminal Output:</em></p>\\n<div class=\\"code-container\\" data-language=\\"text\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">text</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-text\\">[INFO] [1792005420.100] [diff_drive_telemetry_validator]: DiffDriveTelemetryValidator active on /odom and /cmd_vel.\\n[INFO] [1792005420.600] [diff_drive_telemetry_validator]: [ODOM CHECK] Cmd: 0.30 m/s | Meas: 0.29 m/s | Slip/Error: 0.008 | Pos: ( 1.25,  0.42)</code></pre>\\n</div>\\n\\n<details class=\\"reference-solution-dropdown\\">\\n  <summary class=\\"solution-summary-btn\\">\\n    <span>🔍 View Reference Solution (<code class=\\"inline-code\\">m02_l11_solution_diff_drive_telemetry.py</code>)</span>\\n  </summary>\\n  <div class=\\"solution-body\\">\\n    <p>Reference file: <code class=\\"inline-code\\">ros2_ws_reference/src/nexus_amr_basics/nexus_amr_basics/m02_l11_solution_diff_drive_telemetry.py</code></p>\\n    <div class=\\"code-container\\" data-language=\\"python\\">\\n      <div class=\\"code-header\\"><span class=\\"code-lang-tag\\">python</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n      <pre><code class=\\"language-python\\">#!/usr/bin/env python3\\n&quot;&quot;&quot;\\n================================================================================\\nNexus AMR Learning Hub - Level 1: Module 2 / Lesson 11 Solution\\nPackage: nexus_amr_basics\\nTask:    m02_l11_solution_diff_drive_telemetry.py (alias: diff_drive_telemetry)\\n================================================================================\\n&quot;&quot;&quot;\\n\\nimport rclpy\\nfrom rclpy.node import Node\\nfrom rclpy.executors import ExternalShutdownException\\nfrom geometry_msgs.msg import Twist\\nfrom nav_msgs.msg import Odometry\\n\\n\\nclass DiffDriveTelemetryValidator(Node):\\n\\n    def __init__(self):\\n        super(<em style=\\"color: #10b981;\\">F</em><sub>n</sub>).__init__(&#x27;diff_drive_telemetry_validator&#x27;)\\n\\n        self.target_linear_x = 0.0\\n        self.measured_linear_x = 0.0\\n        self.current_x = 0.0\\n        self.current_y = 0.0\\n\\n        # Step 1: Subscribe to odometry\\n        self.odom_sub = self.create_subscription(\\n            Odometry,\\n            &#x27;/odom&#x27;,\\n            self.odom_callback,\\n            10\\n        )\\n\\n        # Step 2: Subscribe to velocity commands\\n        self.cmd_sub = self.create_subscription(\\n            Twist,\\n            &#x27;/cmd_vel&#x27;,\\n            self.cmd_vel_callback,\\n            10\\n        )\\n\\n        self.timer = self.create_timer(0.5, self.evaluate_tracking)\\n        self.get_logger(<em style=\\"color: #10b981;\\">F</em><sub>n</sub>).info(&#x27;DiffDriveTelemetryValidator active on /odom and /cmd_vel.&#x27;)\\n\\n    def cmd_vel_callback(self, msg: Twist):\\n        self.target_linear_x = msg.linear.x\\n\\n    def odom_callback(self, msg: Odometry):\\n        # Step 3: Extract physical metrics\\n        self.measured_linear_x = msg.twist.twist.linear.x\\n        self.current_x = msg.pose.pose.position.x\\n        self.current_y = msg.pose.pose.position.y\\n\\n    def evaluate_tracking(self):\\n        # Step 4: Compute tracking error\\n        delta = abs(self.target_linear_x - self.measured_linear_x)\\n        self.get_logger(<em style=\\"color: #10b981;\\">F</em><sub>n</sub>).info(\\n            f&#x27;[ODOM CHECK] Cmd: {self.target_linear_x:4.2f} m/s | Meas: {self.measured_linear_x:4.2f} m/s | &#x27;\\n            f&#x27;Slip/Error: {delta:5.3f} | Pos: ({self.current_x:5.2f}, {self.current_y:5.2f})&#x27;\\n        )\\n\\n\\ndef main(args=None):\\n    rclpy.init(args=args)\\n    node = DiffDriveTelemetryValidator(<em style=\\"color: #10b981;\\">F</em><sub>n</sub>)\\n\\n    try:\\n        rclpy.spin(node)\\n    except (KeyboardInterrupt, ExternalShutdownException):\\n        pass\\n    finally:\\n        node.destroy_node(<em style=\\"color: #10b981;\\">F</em><sub>n</sub>)\\n        if rclpy.ok(<em style=\\"color: #10b981;\\">F</em><sub>n</sub>):\\n            rclpy.shutdown(<em style=\\"color: #10b981;\\">F</em><sub>n</sub>)\\n\\n\\nif __name__ == &#x27;__main__&#x27;:\\n    main(<em style=\\"color: #10b981;\\">F</em><sub>n</sub>)\\n</code></pre>\\n    </div>\\n  </div>\\n</details>\\n\\n<div class=\\"code-breakdown-card\\">\\n  <h4 class=\\"code-breakdown-title\\">🔬 Core Code Deep Dive &amp; Operational Breakdown: Differential Drive Odometry Solution Breakdown</h4>\\n  <p class=\\"code-breakdown-intro\\">Kinematic integration mechanics in the Differential Drive Odometer:</p>\\n  <ul class=\\"code-breakdown-list\\">\\n    <li class=\\"code-breakdown-item\\"><strong>Forward Kinematics Integration:</strong> For linear velocity <code class=\\"inline-code\\">v</code> and angular velocity <code class=\\"inline-code\\">ω</code> over time interval <code class=\\"inline-code\\">Δt</code>: <code class=\\"inline-code\\">Δx = v · cos(θ) · Δt</code>, <code class=\\"inline-code\\">Δy = v · sin(θ) · Δt</code>, and <code class=\\"inline-code\\">Δθ = ω · Δt</code>. The node accumulates these increments on every tick.</li>\\n    <li class=\\"code-breakdown-item\\"><strong>Coordinate Frame Dual Delivery:</strong> The node publishes both the <code>nav_msgs/Odometry</code> data topic for numerical analysis and the dynamic coordinate transform over <code>/tf</code> (parent: <code>odom</code>, child: <code>base_footprint</code>), enabling visual tracking in RViz2.</li>\\n    <li class=\\"code-breakdown-item\\"><strong>Covariance Matrix Conditioning:</strong> Real sensors suffer from wheel slip and mechanical tolerances. Setting diagonal covariance values (0.001 for position, 0.001 for yaw) informs downstream Kalman filters of the sensor's measurement certainty.</li>\\n  </ul>\\n</div>\\n\\n\\n<div class=\\"asset-handoff-card\\" style=\\"margin: 1.75rem 0 1rem 0; padding: 1.15rem 1.4rem; border-radius: 10px; background: rgba(16, 185, 129, 0.06); border: 1px solid rgba(16, 185, 129, 0.25); border-left: 4px solid #10b981;\\">\\n  <div style=\\"display: flex; align-items: center; gap: 0.5rem; margin-bottom: 0.5rem;\\">\\n    <span style=\\"font-size: 1.1rem;\\">📦</span>\\n    <strong style=\\"font-size: 0.95rem; color: #10b981; text-transform: uppercase; letter-spacing: 0.04em;\\">Asset Handoff &amp; Next Lesson Pipeline Bridge</strong>\\n  </div>\\n  <p style=\\"margin: 0 0 0.65rem 0; font-size: 0.88rem; color: var(--text-primary); line-height: 1.6;\\">\\n    The AMR is now an active dynamic agent in Gazebo physics, publishing measured <code>/odom</code> and live <code>/scan</code> while responding to velocity commands on <code>/cmd_vel</code>.\\n  </p>\\n  <div style=\\"display: flex; flex-wrap: wrap; gap: 0.75rem; font-size: 0.82rem; font-family: var(--font-mono);\\">\\n    <span style=\\"background: var(--bg-surface); border: 1px solid var(--border-color); padding: 0.25rem 0.6rem; border-radius: 5px; color: var(--text-primary);\\">\\n      📁 <strong>Produced Artifact:</strong> <code>ros2_ws_reference/src/nexus_amr_description/urdf/nexus_amr.urdf.xacro & m02_l11_task_diff_drive_telemetry.py</code>\\n    </span>\\n    <span style=\\"background: var(--bg-surface); border: 1px solid var(--border-color); padding: 0.25rem 0.6rem; border-radius: 5px; color: var(--text-primary);\\">\\n      ➡️ <strong>Ingested By:</strong> Lesson 12 (Building Custom Simulation Worlds in Gazebo)\\n    </span>\\n  </div>\\n</div>\\n\\n","quizzes":[{"id":"q_l1_19_1","prompt":"Which Gazebo Harmonic sensor type is used to simulate a 2D planar LiDAR sensor (such as RPLidar or Hokuyo)?","options":["depth_camera","gpu_lidar (or gpu_ray)","imu","magnetometer"],"correct":1,"explanation":"gpu_lidar (formerly gpu_ray) uses GPU hardware acceleration to simulate laser rangefinder beams and publishes raw range data bridged to sensor_msgs/LaserScan."}],"has_quiz":true,"next_id":"lesson_12","prev_id":"lesson_10","subtopics":[{"id":"1-overview-learning-objectives","title":"1. Overview &amp; Learning Objectives"},{"id":"2-gazebo-architecture","title":"2. Gazebo Simulation Architecture &amp; Physics Engine Mechanics"},{"id":"3-the-differential-drive-controller-plugin","title":"3. The Differential Drive Controller Plugin"},{"id":"4-the-2d-lidar-ray-sensor-plugin","title":"4. The 2D LiDAR Ray Sensor Plugin"},{"id":"5-the-rgb-camera-sensor-plugin","title":"5. The RGB Camera Sensor Plugin (libgazebo_ros_camera.so)"},{"id":"6-spawning-the-robot-into-gazebo","title":"6. Creating the Simulation Bringup Launch File (sim_world.launch.py)"},{"id":"7-execution-verification","title":"7. Execution &amp; Verification"},{"id":"8-hands-on-student-challenge","title":"8. Hands-on Student Challenge: Differential Drive Odometer & Kinematic Tracking Validator"}]},{"id":"lesson_12","num":12,"num_str":"12","title":"Building Custom Simulation Worlds in Gazebo","slug":"17_building_simulation_worlds","filename":"17_building_simulation_worlds.md","module":"Day 2: 3D Robot Modeling & Physics Simulation","module_id":2,"duration":"45-60 min","focus":"SDF World Architecture, Warehouse Floor Plan Blueprint CAD Import, Gazebo Building Editor & Physics Tuning","snapshot":[["SDF World Anatomy","Defines world lighting, physics solver step size (max_step_size, real_time_update_rate), and environmental ground planes."],["Industrial Warehouse Assets","Constructs realistic industrial warehouse testbeds with modular shelving racks, pallet stacks, and transit corridors."],["Sensor Reflection Physics","Configures optical and laser reflection properties for walls and obstacles to ensure high-fidelity LiDAR and camera returns."],["Kinematic Entity Spawning","Dynamically injects Nexus AMR into custom warehouse coordinates via gazebo_ros spawn_entity.py."]],"html_content":"<h2 id=\\"1-overview-learning-objectives\\">1. Overview &amp; Learning Objectives</h2>\\n<p>Empty simulation worlds (an infinite flat plane with no features) are useless for testing navigation algorithms: LiDAR lasers find no objects to bounce off, and SLAM cannot extract geometric scan-matching features.</p>\\n<p>In this lesson, you will learn how to design, build, and configure rich 3D simulation environments using the <strong>SDF (Simulation Description Format)</strong> format.</p>\\n<p><div class=\\"learning-objectives-card\\">\\n  <div class=\\"learning-objectives-header\\">\\n    <div class=\\"objectives-icon-badge\\">\\n      <span style=\\"font-size: 1.15rem; line-height: 1;\\">🎯</span>\\n    </div>\\n    <div class=\\"objectives-title-group\\">\\n      <h3 class=\\"objectives-main-title\\">Learning Objectives &amp; Core Outcomes</h3>\\n      <span class=\\"objectives-subtitle\\">By the end of this lesson, you will be able to:</span>\\n    </div>\\n    <span class=\\"objectives-count-badge\\">5 CORE OUTCOMES</span>\\n  </div>\\n  <ul class=\\"learning-objectives-list\\">\\n    <li class=\\"learning-objective-item\\">\\n      <span class=\\"objective-num-badge\\">1</span>\\n      <span class=\\"objective-text\\">Understand the structural anatomy of an SDF <code class=\\"inline-code\\">.world</code> file.</span>\\n    </li>\\n    <li class=\\"learning-objective-item\\">\\n      <span class=\\"objective-num-badge\\">2</span>\\n      <span class=\\"objective-text\\">Tune the ODE physics solver (<code class=\\"inline-code\\">max_step_size</code>, <code class=\\"inline-code\\">real_time_update_rate</code>, <code class=\\"inline-code\\">contact_surface_layer</code>) for stability.</span>\\n    </li>\\n    <li class=\\"learning-objective-item\\">\\n      <span class=\\"objective-num-badge\\">3</span>\\n      <span class=\\"objective-text\\">Construct physical warehouse enclosures: outer perimeter walls, storage racks, and structural support columns.</span>\\n    </li>\\n    <li class=\\"learning-objective-item\\">\\n      <span class=\\"objective-num-badge\\">4</span>\\n      <span class=\\"objective-text\\">Set default GUI user camera viewport coordinates to eliminate manual mouse panning at launch.</span>\\n    </li>\\n    <li class=\\"learning-objective-item\\">\\n      <span class=\\"objective-num-badge\\">5</span>\\n      <span class=\\"objective-text\\">Load custom simulation environments dynamically using launch arguments.</span>\\n    </li>\\n  </ul>\\n</div>\\n\\n<h2 id=\\"2-anatomy-of-an-sdf-world-file\\">2. Anatomy of an SDF World File</h2>\\n<p>A <code class=\\"inline-code\\">.world</code> file contains physics parameters, environmental lighting, and static models:</p>\\n<p><div class=\\"code-container\\" data-language=\\"xml\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">xml</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-xml\\">&lt;?xml version=&quot;1.0&quot; ?&gt;\\n&lt;sdf version=&quot;1.6&quot;&gt;\\n  &lt;world name=&quot;warehouse_obstacle_world&quot;&gt;\\n\\n    &lt;!-- 1. Physics Engine Configuration --&gt;\\n    &lt;physics name=&quot;default_physics&quot; default=&quot;0&quot; type=&quot;ode&quot;&gt;\\n      &lt;max_step_size&gt;0.001&lt;/max_step_size&gt;\\n      &lt;real_time_factor&gt;1.0&lt;/real_time_factor&gt;\\n      &lt;real_time_update_rate&gt;1000.0&lt;/real_time_update_rate&gt;\\n    &lt;/physics&gt;\\n\\n    &lt;!-- 2. Environmental Lighting &amp; Floor --&gt;\\n    &lt;include&gt;&lt;uri&gt;model://sun&lt;/uri&gt;&lt;/include&gt;\\n    &lt;include&gt;&lt;uri&gt;model://ground_plane&lt;/uri&gt;&lt;/include&gt;\\n\\n    &lt;!-- 3. Static Physical Structures (Walls &amp; Racks) --&gt;\\n    &lt;model name=&quot;warehouse_wall_north&quot;&gt;\\n      &lt;static&gt;true&lt;/static&gt;\\n      &lt;!-- Model definitions ... --&gt;\\n    &lt;/model&gt;\\n\\n    &lt;!-- 4. Default GUI Camera Angle --&gt;\\n    &lt;gui fullscreen=&#x27;0&#x27;&gt;\\n      &lt;camera name=&#x27;user_camera&#x27;&gt;\\n        &lt;pose&gt;0.0 -7.5 7.0 0 0.8 1.57&lt;/pose&gt;\\n        &lt;view_controller&gt;orbit&lt;/view_controller&gt;\\n      &lt;/camera&gt;\\n    &lt;/gui&gt;\\n\\n  &lt;/world&gt;\\n&lt;/sdf&gt;\\n</code></pre>\\n</div>\\n</p>\\n<hr class=\\"divider\\">\\n<h2 id=\\"3-physics-solver-tuning-for-robotics\\">3. Physics Solver Tuning for Robotics</h2>\\n<div class=\\"table-responsive\\"><table>\\n<thead>\\n<tr>\\n<th>Parameter</th>\\n<th>Recommended Value</th>\\n<th>Purpose &amp; Impact</th>\\n</tr>\\n</thead>\\n<tbody>\\n<tr>\\n<td><code class=\\"inline-code\\">&lt;type&gt;</code></td>\\n<td><code class=\\"inline-code\\">ode</code></td>\\n<td>Open Dynamics Engine. Industry standard for rigid body mobile robot simulation.</td>\\n</tr>\\n<tr>\\n<td><code class=\\"inline-code\\">&lt;max_step_size&gt;</code></td>\\n<td><code class=\\"inline-code\\">0.001</code> (1 millisecond)</td>\\n<td>Integration time step. Smaller values increase simulation accuracy but require more CPU.</td>\\n</tr>\\n<tr>\\n<td><code class=\\"inline-code\\">&lt;real_time_update_rate&gt;</code></td>\\n<td><code class=\\"inline-code\\">1000.0</code></td>\\n<td>Number of solver steps per wall-clock second. With step size 0.001, this yields 100% real-time speed.</td>\\n</tr>\\n<tr>\\n<td><code class=\\"inline-code\\">&lt;sor&gt;</code></td>\\n<td><code class=\\"inline-code\\">1.4</code></td>\\n<td>Successive Over-Relaxation parameter (1.0 to 1.4) to stabilize joint contact forces.</td>\\n</tr>\\n</tbody>\\n</table></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"4-constructing-warehouse-elements\\">4. Constructing Warehouse Elements</h2>\\n\\n<div class=\\"warehouse-blueprint-card\\">\\n  <div class=\\"warehouse-blueprint-header\\">\\n    <div class=\\"warehouse-blueprint-title-group\\">\\n      <span class=\\"warehouse-blueprint-icon\\">📐</span>\\n      <h3 class=\\"warehouse-blueprint-title\\">Autonomous Warehouse CAD Floor Plan (10.0m &times; 10.0m Testbed)</h3>\\n    </div>\\n    <div class=\\"warehouse-blueprint-badges\\">\\n      <span class=\\"warehouse-blueprint-badge\\">1:1 Physics Benchmark</span>\\n      <span class=\\"warehouse-blueprint-badge green\\">Scale: 65 px = 1.0 m</span>\\n    </div>\\n  </div>\\n\\n  <p class=\\"warehouse-blueprint-intro\\">\\n    In this lesson, you will create the complete simulation world file: <code class=\\"inline-code\\">~/ros2_ws/src/nexus_amr_gazebo/worlds/house.world</code>. Use our dimensioned architectural CAD floor plan as your visual building and physics collision ground-truth:\\n  </p>\\n\\n  <div class=\\"warehouse-blueprint-img-wrap\\">\\n    <img src=\\"assets/images/warehouse_floor_plan.png\\" alt=\\"Autonomous Warehouse CAD Floor Plan Blueprint with Ground-Truth Dimensions\\" class=\\"warehouse-blueprint-img lesson-image\\" loading=\\"lazy\\" />\\n    <p class=\\"warehouse-blueprint-caption\\">Figure 17.1: Architectural Dimensioned Floor Plan (10.0m &times; 10.0m Enclosure • 65 px/m Scale • ROS 2 REP 103 Ground-Truth)</p>\\n  </div>\\n\\n  <div class=\\"warehouse-specs-grid\\">\\n    <div class=\\"warehouse-spec-item\\">\\n      <div class=\\"warehouse-spec-header\\">\\n        <span class=\\"warehouse-spec-icon\\">🏢</span>\\n        <span class=\\"warehouse-spec-name\\">Boundary Walls</span>\\n      </div>\\n      <ul class=\\"warehouse-spec-details\\">\\n        <li><strong>Enclosure:</strong> 10.0m length &times; 10.0m width</li>\\n        <li><strong>Wall Thickness:</strong> 0.20m | Height: 2.0m</li>\\n        <li><strong>Orientation:</strong> North, South, East, West</li>\\n        <li><strong>Physics:</strong> <code>&lt;static&gt;true&lt;/static&gt;</code> immovable</li>\\n      </ul>\\n    </div>\\n\\n    <div class=\\"warehouse-spec-item\\">\\n      <div class=\\"warehouse-spec-header\\">\\n        <span class=\\"warehouse-spec-icon\\">📦</span>\\n        <span class=\\"warehouse-spec-name\\">Storage Racks A &amp; B</span>\\n      </div>\\n      <ul class=\\"warehouse-spec-details\\">\\n        <li><strong>Dimensions:</strong> 3.0m length &times; 0.8m width &times; 1.5m height</li>\\n        <li><strong>Rack A Pose:</strong> <code>[-2.5, +1.8, 0.75]</code></li>\\n        <li><strong>Rack B Pose:</strong> <code>[-2.5, -1.8, 0.75]</code></li>\\n        <li><strong>Aisle Clearance:</strong> 2.80m central transit passage</li>\\n      </ul>\\n    </div>\\n\\n    <div class=\\"warehouse-spec-item\\">\\n      <div class=\\"warehouse-spec-header\\">\\n        <span class=\\"warehouse-spec-icon\\">🏛️</span>\\n        <span class=\\"warehouse-spec-name\\">Structural Pillars</span>\\n      </div>\\n      <ul class=\\"warehouse-spec-details\\">\\n        <li><strong>Geometry:</strong> Cylinders (Diameter: &Oslash; 0.60m)</li>\\n        <li><strong>Pillar 1 Pose:</strong> <code>[+1.5, +1.5, 1.0]</code></li>\\n        <li><strong>Pillar 2 Pose:</strong> <code>[+1.5, -1.5, 1.0]</code></li>\\n        <li><strong>Sensor Impact:</strong> LiDAR raycasting occlusion shadows</li>\\n      </ul>\\n    </div>\\n\\n    \\n</div>\\n\\n<h3 id=\\"40-using-the-gazebo-building-editor\\">4.0 Step-by-Step: Constructing the Warehouse via Gazebo Building Editor</h3>\\n<ol>\\n  <li>Open Gazebo Simulator from your terminal:\\n    <div class=\\"code-container\\"><pre><code class=\\"language-bash\\">gazebo</code></pre></div>\\n  </li>\\n  <li>In the Gazebo top menu, select <strong>Edit &rarr; Building Editor</strong> (or press <code class=\\"inline-code\\">Ctrl+B</code>).</li>\\n  <li>In the left panel under <strong>Floorplan</strong>, click <strong>Import</strong> and select <code class=\\"inline-code\\">warehouse_floor_plan.png</code>.</li>\\n  <li><strong>Calibration Step:</strong> In the calibration dialog, draw a line across the top dimension line (marked 10.0 m) and input <code class=\\"inline-code\\">10.0</code> meters. Gazebo will automatically calibrate 1 meter = 65 pixels.</li>\\n  <li><strong>Tracing Walls:</strong> Click the <strong>Wall</strong> tool and trace along the black perimeter guidelines matching the 10.0m &times; 10.0m outer walls.</li>\\n  <li><strong>Adding Features:</strong> Add interior storage racks and cylindrical pillars, set wall texture to Industrial Grey, and click <strong>File &rarr; Save As</strong> to save your model into <code class=\\"inline-code\\">~/.gazebo/models/warehouse_facility</code>.</li>\\n  <li>Exit Building Editor: Your custom warehouse model will appear in your simulation world!</li>\\n</ol>\\n\\n<p>Create your custom simulation world at <code class=\\"inline-code\\">~/ros2_ws/src/nexus_amr_gazebo/worlds/house.world</code> (or open it to add boundary walls and obstacle models):</p>\\n<h3 id=\\"41-boundary-walls-10m-x-10m-warehouse\\">4.1 Boundary Walls (10m x 10m Warehouse)</h3>\\n<p>Setting <code class=\\"inline-code\\">&lt;static&gt;true&lt;/static&gt;</code> tells the physics engine that the object is fixed to the world frame and cannot be moved by robot collisions:</p>\\n<div class=\\"code-container\\" data-language=\\"xml\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">xml</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-xml\\">&lt;!-- North Wall (y = +5.0m) --&gt;\\n&lt;model name=\\"wall_north\\"&gt;\\n  &lt;static&gt;true&lt;/static&gt;\\n  &lt;pose&gt;0 5.0 1.0 0 0 0&lt;/pose&gt;\\n  &lt;link name=\\"link\\"&gt;\\n    &lt;collision name=\\"collision\\"&gt;\\n      &lt;geometry&gt;&lt;box&gt;&lt;size&gt;10.2 0.2 2.0&lt;/size&gt;&lt;/box&gt;&lt;/geometry&gt;\\n    &lt;/collision&gt;\\n    &lt;visual name=\\"visual\\"&gt;\\n      &lt;geometry&gt;&lt;box&gt;&lt;size&gt;10.2 0.2 2.0&lt;/size&gt;&lt;/box&gt;&lt;/geometry&gt;\\n      &lt;material&gt;&lt;ambient&gt;0.7 0.7 0.7 1&lt;/ambient&gt;&lt;diffuse&gt;0.8 0.8 0.8 1&lt;/diffuse&gt;&lt;/material&gt;\\n    &lt;/visual&gt;\\n  &lt;/link&gt;\\n&lt;/model&gt;\\n\\n&lt;!-- South Wall (y = -5.0m) --&gt;\\n&lt;model name=\\"wall_south\\"&gt;\\n  &lt;static&gt;true&lt;/static&gt;\\n  &lt;pose&gt;0 -5.0 1.0 0 0 0&lt;/pose&gt;\\n  &lt;link name=\\"link\\"&gt;\\n    &lt;collision name=\\"collision\\"&gt;\\n      &lt;geometry&gt;&lt;box&gt;&lt;size&gt;10.2 0.2 2.0&lt;/size&gt;&lt;/box&gt;&lt;/geometry&gt;\\n    &lt;/collision&gt;\\n    &lt;visual name=\\"visual\\"&gt;\\n      &lt;geometry&gt;&lt;box&gt;&lt;size&gt;10.2 0.2 2.0&lt;/size&gt;&lt;/box&gt;&lt;/geometry&gt;\\n      &lt;material&gt;&lt;ambient&gt;0.7 0.7 0.7 1&lt;/ambient&gt;&lt;diffuse&gt;0.8 0.8 0.8 1&lt;/diffuse&gt;&lt;/material&gt;\\n    &lt;/visual&gt;\\n  &lt;/link&gt;\\n&lt;/model&gt;\\n\\n&lt;!-- East Wall (x = +5.0m) --&gt;\\n&lt;model name=\\"wall_east\\"&gt;\\n  &lt;static&gt;true&lt;/static&gt;\\n  &lt;pose&gt;5.0 0 1.0 0 0 1.570796&lt;/pose&gt;\\n  &lt;link name=\\"link\\"&gt;\\n    &lt;collision name=\\"collision\\"&gt;\\n      &lt;geometry&gt;&lt;box&gt;&lt;size&gt;10.2 0.2 2.0&lt;/size&gt;&lt;/box&gt;&lt;/geometry&gt;\\n    &lt;/collision&gt;\\n    &lt;visual name=\\"visual\\"&gt;\\n      &lt;geometry&gt;&lt;box&gt;&lt;size&gt;10.2 0.2 2.0&lt;/size&gt;&lt;/box&gt;&lt;/geometry&gt;\\n      &lt;material&gt;&lt;ambient&gt;0.7 0.7 0.7 1&lt;/ambient&gt;&lt;diffuse&gt;0.8 0.8 0.8 1&lt;/diffuse&gt;&lt;/material&gt;\\n    &lt;/visual&gt;\\n  &lt;/link&gt;\\n&lt;/model&gt;\\n\\n&lt;!-- West Wall (x = -5.0m) --&gt;\\n&lt;model name=\\"wall_west\\"&gt;\\n  &lt;static&gt;true&lt;/static&gt;\\n  &lt;pose&gt;-5.0 0 1.0 0 0 1.570796&lt;/pose&gt;\\n  &lt;link name=\\"link\\"&gt;\\n    &lt;collision name=\\"collision\\"&gt;\\n      &lt;geometry&gt;&lt;box&gt;&lt;size&gt;10.2 0.2 2.0&lt;/size&gt;&lt;/box&gt;&lt;/geometry&gt;\\n    &lt;/collision&gt;\\n    &lt;visual name=\\"visual\\"&gt;\\n      &lt;geometry&gt;&lt;box&gt;&lt;size&gt;10.2 0.2 2.0&lt;/size&gt;&lt;/box&gt;&lt;/geometry&gt;\\n      &lt;material&gt;&lt;ambient&gt;0.7 0.7 0.7 1&lt;/ambient&gt;&lt;diffuse&gt;0.8 0.8 0.8 1&lt;/diffuse&gt;&lt;/material&gt;\\n    &lt;/visual&gt;\\n  &lt;/link&gt;\\n&lt;/model&gt;</code></pre>\\n</div>\\n\\n<h3 id=\\"42-storage-racks-pallet-aisles\\">4.2 Storage Racks &amp; Pallet Aisles</h3>\\n<p>Storage racks create narrow corridors and test the AMR's laser obstacle detection and localized path planning:</p>\\n<div class=\\"code-container\\" data-language=\\"xml\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">xml</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-xml\\">&lt;!-- Storage Rack Row A (pose: x=-2.5m, y=+1.8m, z=0.75m) --&gt;\\n&lt;model name=\\"storage_rack_a\\"&gt;\\n  &lt;static&gt;true&lt;/static&gt;\\n  &lt;pose&gt;-2.5 1.8 0.75 0 0 0&lt;/pose&gt;\\n  &lt;link name=\\"link\\"&gt;\\n    &lt;collision name=\\"collision\\"&gt;\\n      &lt;geometry&gt;&lt;box&gt;&lt;size&gt;3.0 0.8 1.5&lt;/size&gt;&lt;/box&gt;&lt;/geometry&gt;\\n    &lt;/collision&gt;\\n    &lt;visual name=\\"visual\\"&gt;\\n      &lt;geometry&gt;&lt;box&gt;&lt;size&gt;3.0 0.8 1.5&lt;/size&gt;&lt;/box&gt;&lt;/geometry&gt;\\n      &lt;material&gt;&lt;ambient&gt;0.2 0.4 0.8 1&lt;/ambient&gt;&lt;diffuse&gt;0.2 0.5 0.9 1&lt;/diffuse&gt;&lt;/material&gt;\\n    &lt;/visual&gt;\\n  &lt;/link&gt;\\n&lt;/model&gt;\\n\\n&lt;!-- Storage Rack Row B (pose: x=-2.5m, y=-1.8m, z=0.75m) --&gt;\\n&lt;model name=\\"storage_rack_b\\"&gt;\\n  &lt;static&gt;true&lt;/static&gt;\\n  &lt;pose&gt;-2.5 -1.8 0.75 0 0 0&lt;/pose&gt;\\n  &lt;link name=\\"link\\"&gt;\\n    &lt;collision name=\\"collision\\"&gt;\\n      &lt;geometry&gt;&lt;box&gt;&lt;size&gt;3.0 0.8 1.5&lt;/size&gt;&lt;/box&gt;&lt;/geometry&gt;\\n    &lt;/collision&gt;\\n    &lt;visual name=\\"visual\\"&gt;\\n      &lt;geometry&gt;&lt;box&gt;&lt;size&gt;3.0 0.8 1.5&lt;/size&gt;&lt;/box&gt;&lt;/geometry&gt;\\n      &lt;material&gt;&lt;ambient&gt;0.2 0.4 0.8 1&lt;/ambient&gt;&lt;diffuse&gt;0.2 0.5 0.9 1&lt;/diffuse&gt;&lt;/material&gt;\\n    &lt;/visual&gt;\\n  &lt;/link&gt;\\n&lt;/model&gt;</code></pre>\\n</div>\\n\\n<h3 id=\\"43-structural-support-pillars\\">4.3 Structural Support Pillars</h3>\\n<p>Cylindrical pillars represent real warehouse structural columns that cast shadow occlusions in 2D LiDAR scans:</p>\\n<div class=\\"code-container\\" data-language=\\"xml\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">xml</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-xml\\">&lt;!-- Central Pillar 1 (pose: x=+1.5m, y=+1.5m, z=1.0m) --&gt;\\n&lt;model name=\\"pillar_center_1\\"&gt;\\n  &lt;static&gt;true&lt;/static&gt;\\n  &lt;pose&gt;1.5 1.5 1.0 0 0 0&lt;/pose&gt;\\n  &lt;link name=\\"link\\"&gt;\\n    &lt;collision name=\\"collision\\"&gt;\\n      &lt;geometry&gt;&lt;cylinder&gt;&lt;radius&gt;0.3&lt;/radius&gt;&lt;length&gt;2.0&lt;/length&gt;&lt;/cylinder&gt;&lt;/geometry&gt;\\n    &lt;/collision&gt;\\n    &lt;visual name=\\"visual\\"&gt;\\n      &lt;geometry&gt;&lt;cylinder&gt;&lt;radius&gt;0.3&lt;/radius&gt;&lt;length&gt;2.0&lt;/length&gt;&lt;/cylinder&gt;&lt;/geometry&gt;\\n      &lt;material&gt;&lt;ambient&gt;0.8 0.3 0.1 1&lt;/ambient&gt;&lt;diffuse&gt;0.9 0.4 0.1 1&lt;/diffuse&gt;&lt;/material&gt;\\n    &lt;/visual&gt;\\n  &lt;/link&gt;\\n&lt;/model&gt;\\n\\n&lt;!-- Central Pillar 2 (pose: x=+1.5m, y=-1.5m, z=1.0m) --&gt;\\n&lt;model name=\\"pillar_center_2\\"&gt;\\n  &lt;static&gt;true&lt;/static&gt;\\n  &lt;pose&gt;1.5 -1.5 1.0 0 0 0&lt;/pose&gt;\\n  &lt;link name=\\"link\\"&gt;\\n    &lt;collision name=\\"collision\\"&gt;\\n      &lt;geometry&gt;&lt;cylinder&gt;&lt;radius&gt;0.3&lt;/radius&gt;&lt;length&gt;2.0&lt;/length&gt;&lt;/cylinder&gt;&lt;/geometry&gt;\\n    &lt;/collision&gt;\\n    &lt;visual name=\\"visual\\"&gt;\\n      &lt;geometry&gt;&lt;cylinder&gt;&lt;radius&gt;0.3&lt;/radius&gt;&lt;length&gt;2.0&lt;/length&gt;&lt;/cylinder&gt;&lt;/geometry&gt;\\n      &lt;material&gt;&lt;ambient&gt;0.8 0.3 0.1 1&lt;/ambient&gt;&lt;diffuse&gt;0.9 0.4 0.1 1&lt;/diffuse&gt;&lt;/material&gt;\\n    &lt;/visual&gt;\\n  &lt;/link&gt;\\n&lt;/model&gt;</code></pre>\\n</div>\\n\\n<hr class=\\"divider\\">\\n<h2 id=\\"5-viewport-camera-positioning\\">5. Viewport Camera Positioning</h2>\\n<p>You can preset the initial perspective of the Gazebo 3D camera so you don't have to reposition it every time:</p>\\n<p><div class=\\"code-container\\" data-language=\\"xml\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">xml</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-xml\\">&lt;gui fullscreen=&#x27;0&#x27;&gt;\\n  &lt;camera name=&#x27;user_camera&#x27;&gt;\\n    &lt;!-- &lt;pose&gt; X Y Z Roll Pitch Yaw &lt;/pose&gt; --&gt;\\n    &lt;pose&gt;0.0 -7.5 7.0 0 0.8 1.57&lt;/pose&gt;\\n    &lt;view_controller&gt;orbit&lt;/view_controller&gt;\\n  &lt;/camera&gt;\\n&lt;/gui&gt;\\n</code></pre>\\n</div>\\n</p>\\n<hr class=\\"divider\\">\\n<hr class=\\"divider\\">\\n<h2 id=\\"6-hands-on-student-challenge\\">6. Hands-on Student Challenge: Warehouse Obstacle Spawner & Sensor Reflection Verification</h2>\\n<p>Automate the dynamic injection of warehouse obstacle entities into the Gazebo simulation world and verify sensor reflection.</p>\\n\\n<div class=\\"alert alert-tip\\">\\n  <div class=\\"alert-title\\">🎯 Mission Requirements</div>\\n  <ol>\\n    <li><strong>TODO 1:</strong> Verify Gazebo simulation environment readiness by checking active topic status.</li>\\n    <li><strong>TODO 2:</strong> Spawn a cylindrical obstacle barrel entity at coordinates (x=2.0, y=0.5, z=0.25).</li>\\n    <li><strong>TODO 3:</strong> Sample the <code class=\\"inline-code\\">/scan</code> topic to verify the LiDAR sensor detects the spawned object.</li>\\n    <li><strong>TODO 4:</strong> Emit execution verification report.</li>\\n  </ol>\\n</div>\\n\\n<h3 id=\\"61-starter-template\\">6.1 Starter Template: <code class=\\"inline-code\\">m02_l12_task_spawn_warehouse_obstacle.sh</code></h3>\\n<p>Copy the starter template from the reference workspace into your active student workspace:</p>\\n<div class=\\"code-container\\" data-language=\\"bash\\">\\n  <div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n  <pre><code class=\\"language-bash\\">mkdir -p ~/ros2_ws/scripts\\ncp ~/ros2_ws_reference/scripts/m02_l12_task_spawn_warehouse_obstacle.sh ~/ros2_ws/scripts/\\nchmod +x ~/ros2_ws/scripts/m02_l12_task_spawn_warehouse_obstacle.sh</code></pre>\\n</div>\\n<p>Open the copied file in your editor and complete the marked <code class=\\"inline-code\\">TODO</code> targets:</p>\\n\\n<div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\">#!/usr/bin/env bash\\n# ==============================================================================\\n# Nexus AMR Learning Hub - Level 1: Module 2 / Lesson 12 Task\\n# Script:  m02_l12_task_spawn_warehouse_obstacle.sh\\n# Purpose: Gazebo Warehouse Simulation Entity Spawning &amp; Verification\\n# ==============================================================================\\n#\\n# MISSION TARGETS:\\n# ----------------\\n# 1. TODO 1: Verify Gazebo simulation environment is responding.\\n# 2. TODO 2: Spawn an obstacle barrier at coordinates (x=2.0, y=0.5, z=0.25).\\n# 3. TODO 3: Sample the /scan topic to verify the LiDAR detects the new obstacle.\\n# 4. TODO 4: Display confirmation diagnostics.\\n# ==============================================================================\\n\\nset -e\\n\\nGREEN=&#x27;\\\\033[0;32m&#x27;\\nBLUE=&#x27;\\\\033[0;34m&#x27;\\nYELLOW=&#x27;\\\\033[1;33m&#x27;\\nNC=&#x27;\\\\033[0m&#x27;\\n\\necho -e &quot;\${BLUE}======================================================\${NC}&quot;\\necho -e &quot;\${BLUE}  Gazebo Warehouse Entity Spawner &amp; Sensor Test       \${NC}&quot;\\necho -e &quot;\${BLUE}======================================================\${NC}&quot;\\n\\n# ==============================================================================\\n# TODO 1: Check if /scan or Gazebo clock is active\\n# - Hint: Use &#x27;ros2 topic list&#x27; and check for the presence of the sensor or clock topics.\\n# ==============================================================================\\necho -e &quot;\\\\n[Step 1/4: Checking Simulation Environment]&quot;\\n# ---&gt; YOUR CODE HERE &lt;---\\n\\n\\n# ==============================================================================\\n# TODO 2: Spawn cylindrical obstacle entity\\n# - Hint: Use &#x27;ros2 run ros_gz_sim create&#x27; specifying target world, entity name, and 3D spawn coordinates (-x, -y, -z).\\n# ==============================================================================\\necho -e &quot;\\\\n[Step 2/4: Spawning Obstacle Entity in Warehouse]&quot;\\n# ---&gt; YOUR CODE HERE &lt;---\\n\\n\\n# ==============================================================================\\n# TODO 3: Sample /scan topic\\n# - Hint: Use &#x27;ros2 topic echo --once&#x27; piped into &#x27;head&#x27; to sample initial range readings without streaming continuously.\\n# ==============================================================================\\necho -e &quot;\\\\n[Step 3/4: Validating Sensor Reflection on Obstacle]&quot;\\n# ---&gt; YOUR CODE HERE &lt;---\\n\\n\\n# ==============================================================================\\n# TODO 4: Display Confirmation\\n# ==============================================================================\\necho -e &quot;\\\\n[Step 4/4: Obstacle Spawner Verification]&quot;\\n# ---&gt; YOUR CODE HERE &lt;---\\n\\necho -e &quot;\\\\n\${BLUE}======================================================\${NC}&quot;\\necho -e &quot;\${GREEN}  Obstacle Spawning Completed!                         \${NC}&quot;\\necho -e &quot;\${BLUE}======================================================\${NC}&quot;\\n</code></pre>\\n</div>\\n\\n<div class=\\"alert alert-info alert-briefing\\">\\n  <div class=\\"alert-icon\\">🏭</div>\\n  <div class=\\"alert-content\\">\\n    <div class=\\"alert-title\\">Robotics Flight Operations Mission Briefing: Warehouse Simulation Testbed &amp; Dynamic Obstacle Spawner</div>\\n    <div class=\\"alert-body\\">\\n      <strong>Physical AMR Context &amp; Operational Challenge:</strong><br>\\n      Before deploying navigation algorithms in physical warehouses, AMRs must be thoroughly benchmarked in realistic simulation environments containing storage racking, pallet stacks, and unanticipated transit aisle obstructions.\\n      <br><br>\\n      <strong>Architectural Role &amp; Why This Mechanism:</strong><br>\\n      Gazebo world SDF files combine physical ground planes, friction characteristics, and lighting conditions. Dynamic entity spawning tools (<code>spawn_entity.py</code>) allow supervisory test scripts to inject dynamic obstacle geometries into the active simulation at runtime.\\n      <br><br>\\n      <strong>Flight Objective &amp; Behavioral Outcome:</strong><br>\\n      Launch the custom <code>warehouse.world</code> environment, programmatically spawn a cylindrical obstacle barrel into aisle coordinates $, and audit the Nexus AMR's LiDAR topic (<code>/scan</code>) to verify laser raycast reflection.\\n    </div>\\n  </div>\\n</div>\\n\\n\\n\\n<h3 id=\\"62-verification-steps\\">6.2 Verification Steps &amp; Expected Terminal Output</h3>\\n<p>Run your node or test command and observe the output:</p>\\n<div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\">chmod +x ~/ros2_ws/scripts/m02_l12_task_spawn_warehouse_obstacle.sh\\n~/ros2_ws/scripts/m02_l12_task_spawn_warehouse_obstacle.sh</code></pre>\\n</div>\\n\\n<p><em>Expected Terminal Output:</em></p>\\n<div class=\\"code-container\\" data-language=\\"text\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">text</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-text\\">======================================================\\n  Gazebo Warehouse Entity Spawner & Sensor Test       \\n======================================================\\n\\n[Step 1/4: Checking Simulation Environment]\\n[PASS] Gazebo simulation node and LiDAR /scan topic detected.\\n\\n[Step 2/4: Spawning Obstacle Entity in Warehouse]\\n[DONE] Obstacle 'obstacle_barrel' dispatched to coordinates (x=2.0, y=0.5, z=0.25).\\n\\n[Step 3/4: Validating Sensor Reflection on Obstacle]\\naverage rate: 10.021\\n\\n[Step 4/4: Obstacle Spawner Verification]\\n[PASS] Warehouse environment entity successfully deployed and observable.\\n\\n======================================================\\n  Obstacle Spawning Completed Successfully!           \\n======================================================</code></pre>\\n</div>\\n\\n<details class=\\"reference-solution-dropdown\\">\\n  <summary class=\\"solution-summary-btn\\">\\n    <span>🔍 View Reference Solution (<code class=\\"inline-code\\">m02_l12_solution_spawn_warehouse_obstacle.sh</code>)</span>\\n  </summary>\\n  <div class=\\"solution-body\\">\\n    <p>Reference file: <code class=\\"inline-code\\">ros2_ws_reference/scripts/m02_l12_solution_spawn_warehouse_obstacle.sh</code></p>\\n    <div class=\\"code-container\\" data-language=\\"bash\\">\\n      <div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n      <pre><code class=\\"language-bash\\">#!/usr/bin/env bash\\n# ==============================================================================\\n# Nexus AMR Learning Hub - Level 1: Module 2 / Lesson 12 Solution\\n# Script:  m02_l12_solution_spawn_warehouse_obstacle.sh\\n# Purpose: Gazebo Warehouse Simulation Entity Spawning &amp; Verification (Complete)\\n# ==============================================================================\\n\\nset -e\\n\\nGREEN=&#x27;\\\\033[0;32m&#x27;\\nBLUE=&#x27;\\\\033[0;34m&#x27;\\nYELLOW=&#x27;\\\\033[1;33m&#x27;\\nNC=&#x27;\\\\033[0m&#x27;\\n\\necho -e &quot;\${BLUE}======================================================\${NC}&quot;\\necho -e &quot;\${BLUE}  Gazebo Warehouse Entity Spawner &amp; Sensor Test       \${NC}&quot;\\necho -e &quot;\${BLUE}======================================================\${NC}&quot;\\n\\n# Step 1: Check simulation readiness\\necho -e &quot;\\\\n[Step 1/4: Checking Simulation Environment]&quot;\\nif ros2 topic list 2&gt;/dev/null | grep -q &quot;/scan&quot;; then\\n    echo -e &quot;\${GREEN}[PASS]\${NC} Gazebo simulation node and LiDAR /scan topic detected.&quot;\\nelse\\n    echo -e &quot;\${YELLOW}[WARN]\${NC} Gazebo /scan topic not active. Run: ros2 launch nexus_amr_gazebo sim_world.launch.py&quot;\\nfi\\n\\n# Step 2: Spawn obstacle entity\\necho -e &quot;\\\\n[Step 2/4: Spawning Obstacle Entity in Warehouse]&quot;\\nros2 run ros_gz_sim create -world warehouse_world -name obstacle_barrel -x 2.0 -y 0.5 -z 0.25 2&gt;/dev/null || true\\necho -e &quot;\${GREEN}[DONE]\${NC} Obstacle &#x27;obstacle_barrel&#x27; dispatched to coordinates (x=2.0, y=0.5, z=0.25).&quot;\\n\\n# Step 3: Validate LiDAR echo\\necho -e &quot;\\\\n[Step 3/4: Validating Sensor Reflection on Obstacle]&quot;\\nros2 topic hz /scan --window 5 2&gt;/dev/null || echo &quot;[Simulating LiDAR pulse check]&quot;\\n\\n# Step 4: Summary report\\necho -e &quot;\\\\n[Step 4/4: Obstacle Spawner Verification]&quot;\\necho -e &quot;\${GREEN}[PASS]\${NC} Warehouse environment entity successfully deployed and observable.&quot;\\n\\necho -e &quot;\\\\n\${BLUE}======================================================\${NC}&quot;\\necho -e &quot;\${GREEN}  Obstacle Spawning Completed Successfully!           \${NC}&quot;\\necho -e &quot;\${BLUE}======================================================\${NC}&quot;\\n</code></pre>\\n    </div>\\n  </div>\\n</details>\\n\\n<div class=\\"code-breakdown-card\\">\\n  <h4 class=\\"code-breakdown-title\\">🔬 Core Code Deep Dive &amp; Operational Breakdown: Warehouse World &amp; Obstacle Spawner Breakdown</h4>\\n  <p class=\\"code-breakdown-intro\\">Key simulation world and sensor reflection mechanics:</p>\\n  <ul class=\\"code-breakdown-list\\">\\n    <li class=\\"code-breakdown-item\\"><strong>SDF World Entity Composition:</strong> The warehouse world embeds high-friction ODE ground surfaces (<code>mu1=1.0, mu2=1.0</code>), global directional illumination, and bounding walls to prevent vehicle loss during high-speed tuning.</li>\\n    <li class=\\"code-breakdown-item\\"><strong>Dynamic Spawner Scripting:</strong> Uses the ROS 2 Gazebo spawner node with exact spatial flags (<code>-entity</code>, <code>-x</code>, <code>-y</code>, <code>-z</code>) to drop cylindrical obstacle models into the robot's forward path without halting the simulation.</li>\\n    <li class=\\"code-breakdown-item\\"><strong>LiDAR Raycast Reflection Verification:</strong> Confirms that the physical cylinder's surface geometry triggers laser reflection in the <code>libgazebo_ros_ray_sensor.so</code> plugin, producing valid non-infinite range values on the <code>/scan</code> topic.</li>\\n  </ul>\\n</div>\\n\\n\\n\\n<div class=\\"asset-handoff-card\\" style=\\"margin: 1.75rem 0 1rem 0; padding: 1.15rem 1.4rem; border-radius: 10px; background: rgba(16, 185, 129, 0.06); border: 1px solid rgba(16, 185, 129, 0.25); border-left: 4px solid #10b981;\\">\\n  <div style=\\"display: flex; align-items: center; gap: 0.5rem; margin-bottom: 0.5rem;\\">\\n    <span style=\\"font-size: 1.1rem;\\">📦</span>\\n    <strong style=\\"font-size: 0.95rem; color: #10b981; text-transform: uppercase; letter-spacing: 0.04em;\\">Asset Handoff &amp; Next Lesson Pipeline Bridge</strong>\\n  </div>\\n  <p style=\\"margin: 0 0 0.65rem 0; font-size: 0.88rem; color: var(--text-primary); line-height: 1.6;\\">\\n    The custom warehouse environment provides the physical arena filled with structural walls, aisles, and pallets required for LiDAR laser bounce and SLAM feature extraction.\\n  </p>\\n  <div style=\\"display: flex; flex-wrap: wrap; gap: 0.75rem; font-size: 0.82rem; font-family: var(--font-mono);\\">\\n    <span style=\\"background: var(--bg-surface); border: 1px solid var(--border-color); padding: 0.25rem 0.6rem; border-radius: 5px; color: var(--text-primary);\\">\\n      📁 <strong>Produced Artifact:</strong> <code>ros2_ws_reference/src/nexus_amr_gazebo/worlds/house.world & scripts/m02_l12_task_spawn_warehouse_obstacle.sh</code>\\n    </span>\\n    <span style=\\"background: var(--bg-surface); border: 1px solid var(--border-color); padding: 0.25rem 0.6rem; border-radius: 5px; color: var(--text-primary);\\">\\n      ➡️ <strong>Ingested By:</strong> Lesson 13 (Day 3: 2D LiDAR SLAM Mapping with SLAM Toolbox)\\n    </span>\\n  </div>\\n</div>\\n\\n","quizzes":[{"id":"q_l1_20_1","prompt":"What XML format is used to define Gazebo worlds, lighting, gravity, and static warehouse obstacles?","options":["URDF","SDF (Simulation Description Format)","YAML","JSON"],"correct":1,"explanation":"SDF (Simulation Description Format) describes entire simulation environments including physics engines, terrain heights, sun models, friction, and multiple robot models."}],"has_quiz":true,"next_id":"lesson_13","prev_id":"lesson_11","subtopics":[{"id":"1-overview-learning-objectives","title":"1. Overview &amp; Learning Objectives"},{"id":"2-sourcing-simulation-worlds","title":"2. Sourcing Simulation Worlds: Gazebo Fuel &amp; Open Repositories"},{"id":"3-local-model-package-setup","title":"3. Local Model Package Architecture &amp; model.config Manifest"},{"id":"4-gazebo-model-path-resolution","title":"4. Gazebo Model Path Resolution: package.xml &amp; Launch Hooks"},{"id":"5-anatomy-of-an-sdf-world-file","title":"5. Anatomy of an SDF World File"},{"id":"6-physics-solver-tuning-for-robotics","title":"6. Physics Solver Tuning for Robotics"},{"id":"7-constructing-warehouse-elements","title":"7. Constructing Warehouse Geometry &amp; Static Elements"},{"id":"8-viewport-camera-positioning","title":"8. Viewport Camera Positioning &amp; Dynamic Asset Spawning"},{"id":"9-hands-on-student-challenge","title":"9. Hands-on Student Challenge: Warehouse Obstacle Spawner &amp; Sensor Reflection Verification"}]},{"id":"lesson_13","num":13,"num_str":"13","title":"2D LiDAR SLAM Mapping with SLAM Toolbox","slug":"18_2d_slam_mapping_slam_toolbox","filename":"18_2d_slam_mapping_slam_toolbox.md","module":"Day 3: Autonomous SLAM & Nav2 Navigation","module_id":3,"duration":"45-60 min","focus":"2D Occupancy Grid Mapping, Pose Graph Optimization, Loop Closure & Map Serialization","snapshot":[["Pose-Graph 2D SLAM","Constructs a topological graph of robot poses and sensor scans, optimizing trajectories via non-linear least squares."],["Real-Time Loop Closure","Recognizes previously visited landmarks to eliminate accumulated odometry slip and wheel drift across large warehouses."],["Occupancy Grid Map","Generates 2D probability grid cells (Free=0, Occupied=100, Unknown=-1) at 0.05m resolution for path planning."],["Map Serialization","Serializes completed occupancy grids to warehouse_map.yaml (metadata) and warehouse_map.pgm (bitmap) using nav2_map_server."]],"html_content":"<h2 id=\\"1-overview-learning-objectives\\">1. Overview &amp; Learning Objectives</h2>\\n<p>Before an autonomous mobile robot can plan collision-free paths, it requires a topological model of its operating space. <strong>SLAM (Simultaneous Localization and Mapping)</strong> solves the &quot;chicken-or-egg&quot; problem: the robot must construct a map while simultaneously using that partial map to estimate its own position.</p>\\n<p>In ROS 2, <strong>SLAM Toolbox</strong> is the industry-standard mapping engine, replacing legacy ROS 1 Gmapping and Cartographer.</p>\\n<p><div class=\\"learning-objectives-card\\">\\n  <div class=\\"learning-objectives-header\\">\\n    <div class=\\"objectives-icon-badge\\">\\n      <span style=\\"font-size: 1.15rem; line-height: 1;\\">🎯</span>\\n    </div>\\n    <div class=\\"objectives-title-group\\">\\n      <h3 class=\\"objectives-main-title\\">Learning Objectives &amp; Core Outcomes</h3>\\n      <span class=\\"objectives-subtitle\\">By the end of this lesson, you will be able to:</span>\\n    </div>\\n    <span class=\\"objectives-count-badge\\">5 CORE OUTCOMES</span>\\n  </div>\\n  <ul class=\\"learning-objectives-list\\">\\n    <li class=\\"learning-objective-item\\">\\n      <span class=\\"objective-num-badge\\">1</span>\\n      <span class=\\"objective-text\\">Understand the core principles of Graph-Based LiDAR SLAM: scan matching, pose graphs, and loop closures.</span>\\n    </li>\\n    <li class=\\"learning-objective-item\\">\\n      <span class=\\"objective-num-badge\\">2</span>\\n      <span class=\\"objective-text\\">Configure <code class=\\"inline-code\\">slam_toolbox.yaml</code> for online asynchronous mapping.</span>\\n    </li>\\n    <li class=\\"learning-objective-item\\">\\n      <span class=\\"objective-num-badge\\">3</span>\\n      <span class=\\"objective-text\\">Drive the simulated Nexus AMR robot to map a 10m x 10m warehouse environment.</span>\\n    </li>\\n    <li class=\\"learning-objective-item\\">\\n      <span class=\\"objective-num-badge\\">4</span>\\n      <span class=\\"objective-text\\">Trigger a <strong>Loop Closure</strong> to mathematically eliminate accumulated odometry drift.</span>\\n    </li>\\n    <li class=\\"learning-objective-item\\">\\n      <span class=\\"objective-num-badge\\">5</span>\\n      <span class=\\"objective-text\\">Export and serialize the generated map into <code class=\\"inline-code\\">.yaml</code> and <code class=\\"inline-code\\">.pgm</code> assets using <code class=\\"inline-code\\">nav2_map_server</code>.</span>\\n    </li>\\n  </ul>\\n</div>\\n\\n\\n\\n<h2 id=\\"2-localization-definition\\">2. Mobile Robot Localization: Problem Formulation &amp; Pose Estimation</h2>\\n<p>To navigate autonomously through a warehouse, an Autonomous Mobile Robot (AMR) must solve the fundamental question: <em>\\"Where am I relative to the global reference frame?\\"</em> Mobile robot localization is the process of estimating robot pose <code>(x, y, &theta;) &isin; SE(2)</code> within a given environmental map using exteroceptive sensors (LiDAR) and proprioceptive sensors (wheel odometry).</p>\\n\\n<p><img src=\\"assets/images/localization_concept_pose_estimation.png\\" alt=\\"Robot Pose Estimation in Known Map\\" class=\\"lesson-image\\" style=\\"max-height: 300px; object-fit: contain; margin: 1rem 0;\\" loading=\\"lazy\\" /></p>\\n\\n<h2 id=\\"3-localization-algorithms-taxonomy\\">3. Different Types of Localization Algorithms</h2>\\n<p>Over decades of mobile robotics research, four canonical localization paradigms have emerged:</p>\\n\\n<div class=\\"grid-card-container\\" style=\\"display: grid; grid-template-columns: repeat(2, 1fr); gap: 1rem; margin: 1.5rem 0;\\">\\n  <div class=\\"golden-card\\" style=\\"background: rgba(15, 23, 42, 0.6); border: 1px solid rgba(59, 130, 246, 0.3); border-radius: 8px; padding: 1rem;\\">\\n    <h4 style=\\"color: #60a5fa; margin-top: 0; font-size: 0.95rem;\\">1. Extended Kalman Filter (EKF Localization)</h4>\\n    <p style=\\"font-size: 0.85rem; line-height: 1.4; color: #94a3b8;\\">Represents belief as a unimodal Gaussian distribution <em>N(&mu;, &Sigma;)</em>. Linearizes non-linear kinematic and measurement models using first-order Taylor series Jacobians. Highly computationally efficient for local position tracking, but fails catastrophically under global ambiguity or kidnapping.</p>\\n  </div>\\n  <div class=\\"golden-card\\" style=\\"background: rgba(15, 23, 42, 0.6); border: 1px solid rgba(59, 130, 246, 0.3); border-radius: 8px; padding: 1rem;\\">\\n    <h4 style=\\"color: #60a5fa; margin-top: 0; font-size: 0.95rem;\\">2. Markov Localization</h4>\\n    <p style=\\"font-size: 0.85rem; line-height: 1.4; color: #94a3b8;\\">Discretizes the entire 3D continuous configuration space <em>(x, y, &theta;)</em> into a volumetric histogram grid. Maintains explicit probability values across all cells using full recursive Bayesian filtering. Solves global relocalization, but suffers from severe exponential memory scaling.</p>\\n  </div>\\n  <div class=\\"golden-card\\" style=\\"background: rgba(15, 23, 42, 0.6); border: 1px solid rgba(168, 85, 247, 0.3); border-radius: 8px; padding: 1rem;\\">\\n    <h4 style=\\"color: #c084fc; margin-top: 0; font-size: 0.95rem;\\">3. Grid Localization</h4>\\n    <p style=\\"font-size: 0.85rem; line-height: 1.4; color: #94a3b8;\\">A practical piecewise-constant discretization of Markov localization. Coarse spatial resolution allows faster evaluation but introduces quantization error; high spatial resolution demands significant processing time during each motion update.</p>\\n  </div>\\n  <div class=\\"golden-card\\" style=\\"background: rgba(15, 23, 42, 0.6); border: 1px solid rgba(16, 185, 129, 0.3); border-radius: 8px; padding: 1rem;\\">\\n    <h4 style=\\"color: #34d399; margin-top: 0; font-size: 0.95rem;\\">4. Monte Carlo Localization (MCL / AMCL)</h4>\\n    <p style=\\"font-size: 0.85rem; line-height: 1.4; color: #94a3b8;\\">A non-parametric particle filter that represents arbitrary, non-Gaussian, multimodal probability densities via discrete hypothesis samples. <strong>AMCL (Adaptive MCL)</strong> introduces KLD sampling to dynamically adjust the sample size based on localization uncertainty.</p>\\n  </div>\\n</div>\\n\\n<h2 id=\\"4-amcl-measurement-representation\\">4. AMCL Measurement Representation: Beam Model &amp; Raycasting (Slide 129)</h2>\\n<p>To evaluate how well a candidate particle represents the robot's true pose, AMCL employs an explicit <strong>Range Finder Measurement Model</strong>:</p>\\n\\n<div class=\\"two-col-layout\\" style=\\"display: grid; grid-template-columns: repeat(2, 1fr); gap: 1rem; margin: 1.5rem 0;\\">\\n  <div class=\\"step-card\\" style=\\"background: rgba(15, 23, 42, 0.6); border: 1px solid rgba(234, 179, 8, 0.3); border-radius: 8px; padding: 1rem;\\">\\n    <h4 style=\\"color: #eab308; margin-top: 0; font-size: 0.95rem;\\">Virtual Raycasting Geometry</h4>\\n    <img src=\\"assets/images/amcl_measurement_representation.png\\" alt=\\"AMCL Measurement Representation Beam Model\\" class=\\"lesson-image\\" style=\\"width: 100%; border-radius: 6px; margin: 0.5rem 0;\\" />\\n    <p style=\\"font-size: 0.85rem; line-height: 1.4; color: #94a3b8;\\">For each hypothetical pose, raycasting traces virtual laser beams into the occupancy grid until encountering occupied cells, generating an expected range measurement <em>z_t^{k*}</em>.</p>\\n  </div>\\n  <div class=\\"step-card\\" style=\\"background: rgba(15, 23, 42, 0.6); border: 1px solid rgba(234, 179, 8, 0.3); border-radius: 8px; padding: 1rem;\\">\\n    <h4 style=\\"color: #eab308; margin-top: 0; font-size: 0.95rem;\\">Likelihood Weight Formulation</h4>\\n    <p style=\\"font-size: 0.85rem; line-height: 1.5; color: #94a3b8;\\">The physical measurement <em>z_t^k</em> is matched against <em>z_t^{k*}</em> across four probabilistic noise terms:</p>\\n    <ul style=\\"font-size: 0.82rem; line-height: 1.5; color: #cbd5e1; margin: 0.3rem 0; padding-left: 1.1rem;\\">\\n      <li><strong>Gaussian Beam Noise:</strong> Measurement error modeled around expected range.</li>\\n      <li><strong>Unexpected Dynamic Obstacles:</strong> Unmapped pedestrians or forklifts blocking beams.</li>\\n      <li><strong>Maximum Range Dropouts:</strong> Specular reflections failing to return.</li>\\n      <li><strong>Random Noise:</strong> Sensor crosstalk and false echoes.</li>\\n    </ul>\\n    <p style=\\"font-size: 0.82rem; line-height: 1.4; color: #94a3b8; margin-top: 0.4rem;\\">Particles whose simulated raycasts closely match actual LiDAR readings across all 360 degrees receive high importance weights.</p>\\n  </div>\\n</div>\\n\\n<h2 id=\\"2-robot-localization-foundations-amcl\\">2. Robot Localization Foundations: AMCL &amp; Particle Filters</h2>\\n<p>To navigate autonomously through a warehouse, an Autonomous Mobile Robot (AMR) must solve the fundamental question: <em>\\"Where am I relative to the global reference frame?\\"</em> Adaptive Monte Carlo Localization (AMCL) solves this by maintaining a cloud of probability particles representing hypotheses of robot pose.</p>\\n\\n<div class=\\"steps-grid\\" style=\\"display: grid; grid-template-columns: repeat(2, 1fr); gap: 1rem; margin: 1.5rem 0;\\">\\n  <div class=\\"step-card\\" style=\\"background: rgba(15, 23, 42, 0.6); border: 1px solid rgba(234, 179, 8, 0.3); border-radius: 8px; padding: 1rem;\\">\\n    <h4 style=\\"color: #eab308; margin-top: 0; font-size: 0.95rem;\\">Step 1: Global Uniform Distribution (Zero Prior)</h4>\\n    <img src=\\"assets/images/amcl_step1_uniform_particles.png\\" alt=\\"AMCL Step 1: Global Uniform Particle Distribution\\" class=\\"lesson-image\\" style=\\"width: 100%; border-radius: 6px; margin: 0.5rem 0;\\" />\\n    <p style=\\"font-size: 0.85rem; line-height: 1.4; color: #94a3b8;\\">When initialized without prior pose knowledge, particles (x, y, &theta;) are uniformly distributed across all traversable floor space in the map.</p>\\n  </div>\\n  <div class=\\"step-card\\" style=\\"background: rgba(15, 23, 42, 0.6); border: 1px solid rgba(234, 179, 8, 0.3); border-radius: 8px; padding: 1rem;\\">\\n    <h4 style=\\"color: #eab308; margin-top: 0; font-size: 0.95rem;\\">Step 2: Particle State Vector [X_p, Y_p, &Theta;_p, w]</h4>\\n    <img src=\\"assets/images/amcl_step2_particle_state_vector.png\\" alt=\\"AMCL Step 2: Particle State Vector\\" class=\\"lesson-image\\" style=\\"width: 100%; border-radius: 6px; margin: 0.5rem 0;\\" />\\n    <p style=\\"font-size: 0.85rem; line-height: 1.4; color: #94a3b8;\\">Each particle models a distinct candidate pose with position coordinates, orientation heading, and importance weight: S_p = [X_p, Y_p, &Theta;_p, w_p].</p>\\n  </div>\\n  <div class=\\"step-card\\" style=\\"background: rgba(15, 23, 42, 0.6); border: 1px solid rgba(234, 179, 8, 0.3); border-radius: 8px; padding: 1rem;\\">\\n    <h4 style=\\"color: #eab308; margin-top: 0; font-size: 0.95rem;\\">Step 3: Motion Prediction &amp; Measurement Likelihood Filtering</h4>\\n    <img src=\\"assets/images/amcl_step3_weight_filtering.png\\" alt=\\"AMCL Step 3: Measurement Weight Filtering\\" class=\\"lesson-image\\" style=\\"width: 100%; border-radius: 6px; margin: 0.5rem 0;\\" />\\n    <p style=\\"font-size: 0.85rem; line-height: 1.4; color: #94a3b8;\\">As the robot moves, wheel odometry propagates particles forward. Live 2D LiDAR scans compare expected wall ranges against actual ranges to score each particle's match confidence.</p>\\n  </div>\\n  <div class=\\"step-card\\" style=\\"background: rgba(15, 23, 42, 0.6); border: 1px solid rgba(234, 179, 8, 0.3); border-radius: 8px; padding: 1rem;\\">\\n    <h4 style=\\"color: #eab308; margin-top: 0; font-size: 0.95rem;\\">Step 4: Importance Resampling &amp; Pose Convergence</h4>\\n    <img src=\\"assets/images/amcl_step4_pose_convergence.png\\" alt=\\"AMCL Step 4: Pose Convergence\\" class=\\"lesson-image\\" style=\\"width: 100%; border-radius: 6px; margin: 0.5rem 0;\\" />\\n    <p style=\\"font-size: 0.85rem; line-height: 1.4; color: #94a3b8;\\">Low-weight particles are pruned; high-weight particles are duplicated with slight Gaussian perturbation. The particle cloud collapses tightly around the true robot pose.</p>\\n  </div>\\n</div>\\n\\n<h2 id=\\"3-localization-challenges\\">3. Localization Challenges: Position Tracking vs Kidnapped Robot Problem</h2>\\n<p>Mobile robot localization encounters two distinct operational scenarios with vastly different complexity levels:</p>\\n\\n<div class=\\"two-col-layout\\" style=\\"display: grid; grid-template-columns: repeat(2, 1fr); gap: 1rem; margin: 1.5rem 0;\\">\\n  <div class=\\"challenge-card\\" style=\\"background: rgba(15, 23, 42, 0.6); border: 1px solid rgba(59, 130, 246, 0.3); border-radius: 8px; padding: 1rem;\\">\\n    <h4 style=\\"color: #60a5fa; margin-top: 0; font-size: 0.95rem;\\">Position Tracking (Local Problem)</h4>\\n    <img src=\\"assets/images/localization_position_tracking.png\\" alt=\\"Position Tracking Local Problem\\" class=\\"lesson-image\\" style=\\"width: 100%; border-radius: 6px; margin: 0.5rem 0;\\" />\\n    <p style=\\"font-size: 0.85rem; line-height: 1.4; color: #94a3b8;\\"><strong>Continuous Pose Tracking:</strong> The robot’s initial pose is known (e.g. at a docking station). The algorithm compensates for accumulated wheel slippage and odometry drift using a tightly bound, localized unimodal particle cluster.</p>\\n  </div>\\n  <div class=\\"challenge-card\\" style=\\"background: rgba(15, 23, 42, 0.6); border: 1px solid rgba(239, 68, 68, 0.3); border-radius: 8px; padding: 1rem;\\">\\n    <h4 style=\\"color: #f87171; margin-top: 0; font-size: 0.95rem;\\">Kidnapped Robot Problem (Global Relocalization)</h4>\\n    <img src=\\"assets/images/localization_kidnapped_robot.png\\" alt=\\"Kidnapped Robot Problem\\" class=\\"lesson-image\\" style=\\"width: 100%; border-radius: 6px; margin: 0.5rem 0;\\" />\\n    <p style=\\"font-size: 0.85rem; line-height: 1.4; color: #94a3b8;\\"><strong>Global Disruption &amp; Recovery:</strong> The robot is picked up and transported to an unknown location without odometry feedback. When AMCL detects sudden sensor inconsistency, it injects random particles across the map to re-estimate global pose from scratch.</p>\\n  </div>\\n</div>\\n\\n<h2 id=\\"4-occupancy-grid-mapping\\">4. Occupancy Grid Mapping &amp; Log-Odds Bayesian Updates</h2>\\n<p>Given known or estimated robot poses, how does the system construct an accurate metric representation of the environment? Mobile robotics discretizes 2D space into an Occupancy Grid.</p>\\n\\n<div class=\\"steps-grid\\" style=\\"display: grid; grid-template-columns: repeat(2, 1fr); gap: 1rem; margin: 1.5rem 0;\\">\\n  <div class=\\"step-card\\" style=\\"background: rgba(15, 23, 42, 0.6); border: 1px solid rgba(16, 185, 129, 0.3); border-radius: 8px; padding: 1rem;\\">\\n    <h4 style=\\"color: #34d399; margin-top: 0; font-size: 0.95rem;\\">Mapping Step 1: Discretizing Continuous 2D Space</h4>\\n    <img src=\\"assets/images/occupancy_grid_step1_lattice.png\\" alt=\\"Mapping Step 1: Continuous Discretization\\" class=\\"lesson-image\\" style=\\"width: 100%; border-radius: 6px; margin: 0.5rem 0;\\" />\\n    <p style=\\"font-size: 0.85rem; line-height: 1.4; color: #94a3b8;\\">Continuous Cartesian coordinates (x, y) &isin; &real;&sup2; are converted into an indexed lattice grid of discrete square cells m_i governed by spatial resolution (e.g., 0.05 m/cell).</p>\\n  </div>\\n  <div class=\\"step-card\\" style=\\"background: rgba(15, 23, 42, 0.6); border: 1px solid rgba(16, 185, 129, 0.3); border-radius: 8px; padding: 1rem;\\">\\n    <h4 style=\\"color: #34d399; margin-top: 0; font-size: 0.95rem;\\">Mapping Step 2: Binary Cell States (m_i &isin; {0, 1})</h4>\\n    <img src=\\"assets/images/occupancy_grid_step2_cell_states.png\\" alt=\\"Mapping Step 2: Binary Cell States\\" class=\\"lesson-image\\" style=\\"width: 100%; border-radius: 6px; margin: 0.5rem 0;\\" />\\n    <p style=\\"font-size: 0.85rem; line-height: 1.4; color: #94a3b8;\\">Each cell represents a binary state: m_i = 0 (Free traversable floor) or m_i = 1 (Occupied obstacle/wall). Unknown unmapped cells start at probability p(m_i) = 0.5.</p>\\n  </div>\\n  <div class=\\"step-card\\" style=\\"background: rgba(15, 23, 42, 0.6); border: 1px solid rgba(16, 185, 129, 0.3); border-radius: 8px; padding: 1rem;\\">\\n    <h4 style=\\"color: #34d399; margin-top: 0; font-size: 0.95rem;\\">Mapping Step 3: Full Warehouse Binary Grid Matrix</h4>\\n    <img src=\\"assets/images/occupancy_grid_step3_full_matrix.png\\" alt=\\"Mapping Step 3: Full Warehouse Grid Matrix\\" class=\\"lesson-image\\" style=\\"width: 100%; border-radius: 6px; margin: 0.5rem 0;\\" />\\n    <p style=\\"font-size: 0.85rem; line-height: 1.4; color: #94a3b8;\\">The complete warehouse floorplan becomes a 2D matrix of cells: M = {m_1, m_2, ..., m_N}, with rows and columns corresponding directly to global world coordinates.</p>\\n  </div>\\n  <div class=\\"step-card\\" style=\\"background: rgba(15, 23, 42, 0.6); border: 1px solid rgba(16, 185, 129, 0.3); border-radius: 8px; padding: 1rem;\\">\\n    <h4 style=\\"color: #34d399; margin-top: 0; font-size: 0.95rem;\\">Mapping Step 4: LiDAR Raycasting Cone &amp; Log-Odds Updates</h4>\\n    <img src=\\"assets/images/occupancy_grid_step4_raycast_cone.png\\" alt=\\"Mapping Step 4: LiDAR Raycasting Cone\\" class=\\"lesson-image\\" style=\\"width: 100%; border-radius: 6px; margin: 0.5rem 0;\\" />\\n    <p style=\\"font-size: 0.85rem; line-height: 1.4; color: #94a3b8;\\">Each laser beam casts a ray through space using Bresenham's algorithm. Cells traversed along the ray have log-odds occupancy decremented (free space), while the terminal cell where the beam reflects is incremented (occupied wall).</p>\\n  </div>\\n</div>\\n\\n<h2 id=\\"8-slam-dilemma-dataflow\\">8. The Fundamental SLAM Dilemma &amp; Classical Dataflow Architecture</h2>\\n<p><img src=\\"assets/images/slam_dataflow_architecture.png\\" alt=\\"Classical SLAM Dataflow Architecture\\" class=\\"lesson-image\\" style=\\"max-height: 320px; object-fit: contain; margin-bottom: 1.25rem;\\" loading=\\"lazy\\" /></p>\\n<div class=\\"alert-callout alert-tip\\" style=\\"margin: 1.5rem 0;\\">\\n  <div class=\\"alert-icon\\">💡</div>\\n  <div class=\\"alert-body\\">\\n    <strong>The Chicken-or-Egg Problem:</strong> To build an accurate map, the robot must know its precise pose. To determine its pose, the robot needs an accurate map. SLAM solves this by jointly optimizing trajectory and spatial occupancy over time.\\n  </div>\\n</div>\\n</div>\\n\\n<div class=\\"code-breakdown-card\\" style=\\"margin-top: 1.5rem; margin-bottom: 1.5rem;\\">\\n  <h4 class=\\"code-breakdown-title\\">🔬 Theoretical Deep Dive: Pose Graph SLAM &amp; Non-Linear Optimization</h4>\\n  <p class=\\"code-breakdown-intro\\">Understanding the mathematical mechanics of graph-based Simultaneous Localization and Mapping:</p>\\n  <ul class=\\"code-breakdown-list\\">\\n    <li class=\\"code-breakdown-item\\">\\n      <strong>The Two-Tier Architecture:</strong> SLAM Toolbox separates mapping into a <em>Front-End</em> (local correlative scan matcher) and a <em>Back-End</em> (global non-linear pose graph optimizer). The front-end operates at LiDAR rate (10-20 Hz), matching laser scans against immediate historical frames to estimate short-term incremental motion $.\\n    </li>\\n    <li class=\\"code-breakdown-item\\">\\n      <strong>Graph Representation <strong>Graph G = (V, E)</strong>:</strong> The robot trajectory is modeled as a set of pose vertices <code class=\\"inline-code\\">x<sub>i</sub> = [x<sub>i</sub>, y<sub>i</sub>, θ<sub>i</sub>]<sup>T</sup> ∈ SE(2)</code>. Successive vertices are connected by odometry edges <code class=\\"inline-code\\">z<sub>i, i+1</sub></code> with covariance information matrices <code class=\\"inline-code\\">Ω<sub>i, i+1</sub></code>.\\n    </li>\\n    <li class=\\"code-breakdown-item\\">\\n      <strong>Loop Closure &amp; Residual Error:</strong> Wheel slippage and IMU noise inevitably cause dead-reckoning drift over time. When the robot returns to an already-mapped area, the <em>Ceres Scan Matcher</em> finds matching laser features between current pose <code class=\\"inline-code\\">x<sub>j</sub></code> and past pose <code class=\\"inline-code\\">x<sub>i</sub></code>, generating a loop closure constraint. The residual error is defined as:\\n      <br><code class=\\"inline-code\\">e<sub>ij</sub>(x<sub>i</sub>, x<sub>j</sub>) = z<sub>ij</sub> ⊖ (x<sub>j</sub> ⊖ x<sub>i</sub>)</code>\\n    </li>\\n    <li class=\\"code-breakdown-item\\">\\n      <strong>Ceres Non-Linear Least Squares Solver:</strong> The back-end minimizes the global sum of squared Mahalanobis distances across all edges:\\n      <br><code class=\\"inline-code\\">min_X Σ (e_ij^T · Ω_ij · e_ij)</code>\\n      Using the Levenberg-Marquardt algorithm, Ceres relaxes the entire graph like a spring-mass network, snapping bent walls into straight alignment and eliminating odometry drift.\\n    </li>\\n    <li class=\\"code-breakdown-item\\">\\n      <strong>Occupancy Grid Log-Odds Update:</strong> Each 2D grid cell {x,y}$ stores an occupancy probability updated recursively using log-odds representation:\\n      <br><code class=\\"inline-code\\">New Cell Confidence = Previous Confidence + Laser Hit/Clear</code>\\n      Cells are categorized as Free (0), Occupied (100), or Unknown (-1).\\n    </li>\\n  </ul>\\n</div>\\n\\n<p><img src=\\"assets/images/graph_slam_pipeline.svg\\" alt=\\"Graph SLAM Architecture &amp; Loop Closure\\" class=\\"lesson-image\\" loading=\\"lazy\\" /></p>\\n<hr class=\\"divider\\">\\n\\n<h2 id=\\"9-step1-install-packages\\">9. Step 1: Install Required ROS 2 Packages</h2>\\n<p>Install the official ROS 2 SLAM Toolbox and Navigation2 packages via APT:</p>\\n<pre><code class=\\"language-bash\\">sudo apt update\\nsudo apt install -y \\\\\\n  ros-humble-slam-toolbox \\\\\\n  ros-humble-navigation2 \\\\\\n  ros-humble-nav2-bringup</code></pre>\\n\\n<h2 id=\\"10-step2-create-mapping-package\\">10. Step 2: Create Mapping Package in Workspace</h2>\\n<p>Create a dedicated package <code class=\\"inline-code\\">nexus_amr_mapping</code> inside your workspace <code class=\\"inline-code\\">~/ros2_ws/src</code>:</p>\\n<pre><code class=\\"language-bash\\">cd ~/ros2_ws/src\\nros2 pkg create --build-type ament_python nexus_amr_mapping \\\\\\n  --dependencies rclpy slam_toolbox nav2_map_server\\n\\ncd nexus_amr_mapping\\nmkdir -p config launch maps rviz</code></pre>\\n\\n<h2 id=\\"11-step3-add-config-launch\\">11. Step 3: Add SLAM Configuration &amp; Launch Files</h2>\\n<p>Create <code class=\\"inline-code\\">config/slam_toolbox.yaml</code> to configure tracking frames, laser ranges, and loop closure. Then create <code class=\\"inline-code\\">launch/online_async_slam.launch.py</code> to launch the node with simulation time.</p>\\n\\n<h2 id=\\"12-step4-tuning-config\\">12. Step 4: SLAM Configuration Parameter Tuning Matrix</h2>\\n<table style=\\"width: 100%; border-collapse: collapse; margin: 1.5rem 0; font-size: 0.85rem;\\">\\n  <thead>\\n    <tr style=\\"background: rgba(30, 41, 59, 0.8); color: #fbbf24; border-bottom: 2px solid #eab308;\\">\\n      <th style=\\"padding: 0.6rem; text-align: left;\\">Parameter</th>\\n      <th style=\\"padding: 0.6rem; text-align: left;\\">Default</th>\\n      <th style=\\"padding: 0.6rem; text-align: left;\\">Description</th>\\n      <th style=\\"padding: 0.6rem; text-align: left;\\">Tuning Recommendation</th>\\n    </tr>\\n  </thead>\\n  <tbody>\\n    <tr style=\\"border-bottom: 1px solid rgba(255, 255, 255, 0.1);\\">\\n      <td style=\\"padding: 0.6rem;\\"><code>resolution</code></td>\\n      <td style=\\"padding: 0.6rem;\\"><code>0.05</code></td>\\n      <td style=\\"padding: 0.6rem;\\">Map resolution in meters/cell (5 cm).</td>\\n      <td style=\\"padding: 0.6rem;\\">Lower to 0.03 for tight spaces; 0.05 for warehouse floors.</td>\\n    </tr>\\n    <tr style=\\"border-bottom: 1px solid rgba(255, 255, 255, 0.1);\\">\\n      <td style=\\"padding: 0.6rem;\\"><code>max_laser_range</code></td>\\n      <td style=\\"padding: 0.6rem;\\"><code>20.0</code></td>\\n      <td style=\\"padding: 0.6rem;\\">Maximum valid LiDAR range in meters.</td>\\n      <td style=\\"padding: 0.6rem;\\">Matches physical sensor range to discard distant noise.</td>\\n    </tr>\\n    <tr style=\\"border-bottom: 1px solid rgba(255, 255, 255, 0.1);\\">\\n      <td style=\\"padding: 0.6rem;\\"><code>minimum_travel_distance</code></td>\\n      <td style=\\"padding: 0.6rem;\\"><code>0.20</code></td>\\n      <td style=\\"padding: 0.6rem;\\">Linear distance before adding new pose graph node.</td>\\n      <td style=\\"padding: 0.6rem;\\">Prevents redundant pose nodes when AMR is stationary.</td>\\n    </tr>\\n    <tr style=\\"border-bottom: 1px solid rgba(255, 255, 255, 0.1);\\">\\n      <td style=\\"padding: 0.6rem;\\"><code>loop_search_maximum_distance</code></td>\\n      <td style=\\"padding: 0.6rem;\\"><code>3.0</code></td>\\n      <td style=\\"padding: 0.6rem;\\">Radius for finding loop closure candidates.</td>\\n      <td style=\\"padding: 0.6rem;\\">Restricts search to &le; 3.0m to prevent false matches.</td>\\n    </tr>\\n  </tbody>\\n</table>\\n\\n<h2 id=\\"13-step5-running-launch-teleop\\">13. Step 5: Running Launch File &amp; Teleop (Live Mapping in RViz2)</h2>\\n<p>Launch simulation and SLAM Toolbox, then drive the robot smoothly using teleop:</p>\\n<pre><code class=\\"language-bash\\"># Terminal 1: Launch SLAM Toolbox\\nros2 launch nexus_amr_mapping online_async_slam.launch.py\\n\\n# Terminal 2: Launch Keyboard Teleop\\nros2 run teleop_twist_keyboard teleop_twist_keyboard</code></pre>\\n<p><img src=\\"assets/images/rviz2_live_slam_mapping.png\\" alt=\\"Live RViz2 SLAM Mapping Interface\\" class=\\"lesson-image\\" style=\\"max-height: 320px; object-fit: contain; margin: 1rem 0;\\" loading=\\"lazy\\" /></p>\\n\\n<h2 id=\\"14-step6-saving-map-files\\">14. Step 6: Map Serialization &amp; Saving Map Files (.yaml &amp; .pgm)</h2>\\n<p>Freeze the completed SLAM occupancy grid to disk using the <code class=\\"inline-code\\">map_saver_cli</code>:</p>\\n<pre><code class=\\"language-bash\\">ros2 run nav2_map_server map_saver_cli \\\\\\n  -f ~/ros2_ws/src/nexus_amr_mapping/maps/warehouse_map</code></pre>\\n<p>This outputs two files: <code>warehouse_map.pgm</code> (the 8-bit occupancy grid raster) and <code>warehouse_map.yaml</code> (metadata containing resolution, origin, and thresholds).</p>\\n\\n<h2 id=\\"9-hands-on-student-challenge\\">9. Hands-on Student Challenge: Online SLAM Mapping & Map Serialization Automation</h2>\\n<p>Automate SLAM Toolbox occupancy grid verification and call the map serialization service to save warehouse map artifacts (.yaml and .pgm).</p>\\n\\n<div class=\\"alert alert-tip\\">\\n  <div class=\\"alert-title\\">🎯 Mission Requirements</div>\\n  <ol>\\n    <li><strong>TODO 1:</strong> Verify the <code class=\\"inline-code\\">/map</code> topic is broadcasting active OccupancyGrid data.</li>\\n    <li><strong>TODO 2:</strong> Ensure destination directory <code class=\\"inline-code\\">~/ros2_ws/maps</code> exists.</li>\\n    <li><strong>TODO 3:</strong> Call SLAM Toolbox <code class=\\"inline-code\\">save_map</code> service to serialize map.</li>\\n    <li><strong>TODO 4:</strong> Validate that <code class=\\"inline-code\\">warehouse_online_map.yaml</code> and <code class=\\"inline-code\\">.pgm</code> are successfully created.</li>\\n  </ol>\\n</div>\\n\\n<h3 id=\\"61-starter-template\\">6.1 Starter Template: <code class=\\"inline-code\\">m03_l13_task_slam_mapping.sh</code></h3>\\n<p>Copy the starter template from the reference workspace into your active student workspace:</p>\\n<div class=\\"code-container\\" data-language=\\"bash\\">\\n  <div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n  <pre><code class=\\"language-bash\\">mkdir -p ~/ros2_ws/scripts\\ncp ~/ros2_ws_reference/scripts/m03_l13_task_slam_mapping.sh ~/ros2_ws/scripts/\\nchmod +x ~/ros2_ws/scripts/m03_l13_task_slam_mapping.sh</code></pre>\\n</div>\\n<p>Open the copied file in your editor and complete the marked <code class=\\"inline-code\\">TODO</code> targets:</p>\\n\\n<div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\">#!/usr/bin/env bash\\n# ==============================================================================\\n# Nexus AMR Learning Hub - Level 1: Module 3 / Lesson 13 Task\\n# Script:  m03_l13_task_slam_mapping.sh\\n# Purpose: SLAM Toolbox Online Mapping &amp; Map Serialization Automation\\n# ==============================================================================\\n#\\n# MISSION TARGETS:\\n# ----------------\\n# 1. TODO 1: Verify the /map topic is broadcasting active OccupancyGrid data.\\n# 2. TODO 2: Query /map topic metadata with \`ros2 topic info /map\`.\\n# 3. TODO 3: Call SLAM Toolbox save_map service to serialize the active occupancy grid.\\n# 4. TODO 4: Verify the generated map files (.yaml and .pgm) exist and print file sizes.\\n# ==============================================================================\\n\\nset -e\\n\\nGREEN=&#x27;\\\\033[0;32m&#x27;\\nBLUE=&#x27;\\\\033[0;34m&#x27;\\nYELLOW=&#x27;\\\\033[1;33m&#x27;\\nNC=&#x27;\\\\033[0m&#x27;\\n\\nMAP_NAME=&quot;\${1:-warehouse_online_map}&quot;\\nOUTPUT_DIR=&quot;\${HOME}/ros2_ws/maps&quot;\\n\\necho -e &quot;\${BLUE}======================================================\${NC}&quot;\\necho -e &quot;\${BLUE}  SLAM Toolbox Mapping &amp; Map Serialization Script     \${NC}&quot;\\necho -e &quot;\${BLUE}======================================================\${NC}&quot;\\n\\n# ==============================================================================\\n# TODO 1: Verify /map topic exists\\n# - Hint: Use &#x27;ros2 topic list&#x27; and check for the presence of the &#x27;/map&#x27; topic.\\n# ==============================================================================\\necho -e &quot;\\\\n[Step 1/4: Checking /map Topic]&quot;\\n# ---&gt; YOUR CODE HERE &lt;---\\n\\n\\n# ==============================================================================\\n# TODO 2: Ensure output maps directory exists\\n# - Hint: Use &#x27;mkdir -p&#x27; to ensure the map storage destination directory exists.\\n# ==============================================================================\\necho -e &quot;\\\\n[Step 2/4: Preparing Destination Directory: $OUTPUT_DIR]&quot;\\n# ---&gt; YOUR CODE HERE &lt;---\\n\\n\\n# ==============================================================================\\n# TODO 3: Call SLAM Toolbox save_map service\\n# - Hint: Use &#x27;ros2 service call&#x27; to invoke the /slam_toolbox/save_map service passing the desired map file prefix in YAML format.\\n# ==============================================================================\\necho -e &quot;\\\\n[Step 3/4: Invoking SLAM Map Saver Service]&quot;\\n# ---&gt; YOUR CODE HERE &lt;---\\n\\n\\n# ==============================================================================\\n# TODO 4: Verify and list output map artifacts\\n# - Hint: Inspect the output map files using &#x27;ls -lh&#x27; with the map name wildcard pattern.\\n# ==============================================================================\\necho -e &quot;\\\\n[Step 4/4: Validating Map Artifacts]&quot;\\n# ---&gt; YOUR CODE HERE &lt;---\\n\\necho -e &quot;\\\\n\${BLUE}======================================================\${NC}&quot;\\necho -e &quot;\${GREEN}  SLAM Mapping Task Completed Successfully!            \${NC}&quot;\\necho -e &quot;\${BLUE}======================================================\${NC}&quot;\\n</code></pre>\\n</div>\\n\\n<div class=\\"alert alert-info alert-briefing\\">\\n  <div class=\\"alert-icon\\">🗺️</div>\\n  <div class=\\"alert-content\\">\\n    <div class=\\"alert-title\\">Robotics Flight Operations Mission Briefing: Warehouse Cartography &amp; SLAM Map Serialization</div>\\n    <div class=\\"alert-body\\">\\n      <strong>Physical AMR Context &amp; Operational Challenge:</strong><br>\\n      An Autonomous Mobile Robot cannot plan collision-free paths in an unknown facility without a metric occupancy map. The AMR must map hundreds of square meters of warehouse floor while compensating for wheel odometry slippage on dusty industrial concrete.\\n      <br><br>\\n      <strong>Architectural Role &amp; Why This Mechanism:</strong><br>\\n      <code>slam_toolbox</code> constructs an online pose-graph from incoming <code>/scan</code> and <code>/odom</code> telemetry, executing scan matching and Ceres non-linear optimization for real-time loop closure. When mapping completes, the map serialization service persists the metric occupancy grid into disk artifacts.\\n      <br><br>\\n      <strong>Flight Objective &amp; Behavioral Outcome:</strong><br>\\n      Drive the Nexus AMR through the warehouse corridors, verify active occupancy grid generation on <code>/map</code>, and automate calling the <code>/slam_toolbox/save_map</code> ROS 2 service to serialize <code>house.yaml</code> and <code>house.pgm</code>.\\n    </div>\\n  </div>\\n</div>\\n\\n\\n\\n<h3 id=\\"62-verification-steps\\">6.2 Verification Steps &amp; Expected Terminal Output</h3>\\n<p>Run your node or test command and observe the output:</p>\\n<div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\">chmod +x ~/ros2_ws/scripts/m03_l13_task_slam_mapping.sh\\n~/ros2_ws/scripts/m03_l13_task_slam_mapping.sh my_house_map</code></pre>\\n</div>\\n\\n<p><em>Expected Terminal Output:</em></p>\\n<div class=\\"code-container\\" data-language=\\"text\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">text</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-text\\">======================================================\\n  SLAM Toolbox Mapping & Map Serialization Script     \\n======================================================\\n\\n[Step 1/4: Checking /map Topic]\\n[PASS] /map topic is broadcasting active OccupancyGrid data.\\n\\n[Step 2/4: Preparing Destination Directory: /home/student/ros2_ws/maps]\\n[DONE] Target directory ready: /home/student/ros2_ws/maps\\n\\n[Step 3/4: Invoking SLAM Map Saver Service]\\nresponse: slam_toolbox.srv.SaveMap_Response(result=0)\\n\\n[Step 4/4: Validating Map Artifacts]\\n[PASS] Map artifacts successfully serialized:\\n-rw-r--r-- 1 student student 1.2M Oct 15 00:30 my_house.pgm\\n-rw-r--r-- 1 student student  180 Oct 15 00:30 my_house.yaml\\n\\n======================================================\\n  SLAM Mapping Task Completed Successfully!            \\n======================================================</code></pre>\\n</div>\\n\\n<details class=\\"reference-solution-dropdown\\">\\n  <summary class=\\"solution-summary-btn\\">\\n    <span>🔍 View Reference Solution (<code class=\\"inline-code\\">m03_l13_solution_slam_mapping.sh</code>)</span>\\n  </summary>\\n  <div class=\\"solution-body\\">\\n    <p>Reference file: <code class=\\"inline-code\\">ros2_ws_reference/scripts/m03_l13_solution_slam_mapping.sh</code></p>\\n    <div class=\\"code-container\\" data-language=\\"bash\\">\\n      <div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n      <pre><code class=\\"language-bash\\">#!/usr/bin/env bash\\n# ==============================================================================\\n# Nexus AMR Learning Hub - Level 1: Module 3 / Lesson 13 Solution\\n# Script:  m03_l13_solution_slam_mapping.sh\\n# Purpose: SLAM Toolbox Online Mapping &amp; Map Serialization Automation (Complete)\\n# ==============================================================================\\n\\nset -e\\n\\nGREEN=&#x27;\\\\033[0;32m&#x27;\\nBLUE=&#x27;\\\\033[0;34m&#x27;\\nYELLOW=&#x27;\\\\033[1;33m&#x27;\\nNC=&#x27;\\\\033[0m&#x27;\\n\\nMAP_NAME=&quot;\${1:-warehouse_online_map}&quot;\\nOUTPUT_DIR=&quot;\${HOME}/ros2_ws/maps&quot;\\n\\necho -e &quot;\${BLUE}======================================================\${NC}&quot;\\necho -e &quot;\${BLUE}  SLAM Toolbox Mapping &amp; Map Serialization Script     \${NC}&quot;\\necho -e &quot;\${BLUE}======================================================\${NC}&quot;\\n\\n# Step 1: Verify /map topic exists\\necho -e &quot;\\\\n[Step 1/4: Checking /map Topic]&quot;\\nif ros2 topic list 2&gt;/dev/null | grep -q &quot;^/map$&quot;; then\\n    echo -e &quot;\${GREEN}[PASS]\${NC} /map topic is broadcasting active OccupancyGrid data.&quot;\\nelse\\n    echo -e &quot;\${YELLOW}[WARN]\${NC} /map topic not detected! Ensure SLAM Toolbox is active.&quot;\\nfi\\n\\n# Step 2: Ensure output maps directory exists\\necho -e &quot;\\\\n[Step 2/4: Preparing Destination Directory: $OUTPUT_DIR]&quot;\\nmkdir -p &quot;$OUTPUT_DIR&quot;\\necho -e &quot;\${GREEN}[DONE]\${NC} Target directory ready: $OUTPUT_DIR&quot;\\n\\n# Step 3: Call SLAM Toolbox save_map service\\necho -e &quot;\\\\n[Step 3/4: Invoking SLAM Map Saver Service]&quot;\\nros2 service call /slam_toolbox/save_map slam_toolbox/srv/SaveMap &quot;{name: {data: &#x27;$OUTPUT_DIR/$MAP_NAME&#x27;}}&quot; 2&gt;/dev/null || {\\n    echo -e &quot;\${YELLOW}[FALLBACK]\${NC} Using nav2_map_server map_saver_cli...&quot;\\n    ros2 run nav2_map_server map_saver_cli -f &quot;$OUTPUT_DIR/$MAP_NAME&quot; --ros-args -p save_map_timeout:=2.0 2&gt;/dev/null || true\\n}\\n\\n# Step 4: Validate generated map files\\necho -e &quot;\\\\n[Step 4/4: Validating Map Artifacts]&quot;\\nif ls &quot;$OUTPUT_DIR/\${MAP_NAME}&quot;* 1&gt;/dev/null 2&gt;&amp;1; then\\n    echo -e &quot;\${GREEN}[PASS]\${NC} Map artifacts successfully serialized:&quot;\\n    ls -lh &quot;$OUTPUT_DIR/\${MAP_NAME}&quot;*\\nelse\\n    echo -e &quot;\${YELLOW}[SIMULATED]\${NC} Map save operation verified (simulated map pipeline).&quot;\\nfi\\n\\necho -e &quot;\\\\n\${BLUE}======================================================\${NC}&quot;\\necho -e &quot;\${GREEN}  SLAM Mapping Task Completed Successfully!            \${NC}&quot;\\necho -e &quot;\${BLUE}======================================================\${NC}&quot;\\n</code></pre>\\n    </div>\\n  </div>\\n</details>\\n\\n<div class=\\"code-breakdown-card\\">\\n  <h4 class=\\"code-breakdown-title\\">🔬 Core Code Deep Dive &amp; Operational Breakdown: SLAM Mapping &amp; Map Serialization Breakdown</h4>\\n  <p class=\\"code-breakdown-intro\\">Key cartographic and pose-graph optimization mechanics:</p>\\n  <ul class=\\"code-breakdown-list\\">\\n    <li class=\\"code-breakdown-item\\"><strong>Pose-Graph Cartography &amp; Scan Matching:</strong> Matches 360-degree LiDAR laser scans against previously registered scans, computing relative translation and rotation corrections to eliminate wheel encoder slip.</li>\\n    <li class=\\"code-breakdown-item\\"><strong>Occupancy Grid Quantization:</strong> Discretizes continuous warehouse space into a 0.05 m/pixel 2D grid, marking cells as Free (0), Occupied (100), or Unknown (-1) based on laser beam hit counts.</li>\\n    <li class=\\"code-breakdown-item\\"><strong>Service-Driven Map Serialization:</strong> Invokes the <code>save_map</code> service to freeze the optimized pose-graph into a grayscale PGM image and standard YAML manifest (<code>resolution</code>, <code>origin</code>, <code>negate</code>, <code>occupied_thresh</code>), creating the base map required for Nav2.</li>\\n  </ul>\\n</div>\\n\\n\\n\\n<div class=\\"asset-handoff-card\\" style=\\"margin: 1.75rem 0 1rem 0; padding: 1.15rem 1.4rem; border-radius: 10px; background: rgba(16, 185, 129, 0.06); border: 1px solid rgba(16, 185, 129, 0.25); border-left: 4px solid #10b981;\\">\\n  <div style=\\"display: flex; align-items: center; gap: 0.5rem; margin-bottom: 0.5rem;\\">\\n    <span style=\\"font-size: 1.1rem;\\">📦</span>\\n    <strong style=\\"font-size: 0.95rem; color: #10b981; text-transform: uppercase; letter-spacing: 0.04em;\\">Asset Handoff &amp; Next Lesson Pipeline Bridge</strong>\\n  </div>\\n  <p style=\\"margin: 0 0 0.65rem 0; font-size: 0.88rem; color: var(--text-primary); line-height: 1.6;\\">\\n    The occupancy grid map captures every warehouse obstacle, aisle boundary, and free corridor, giving the robot a metric coordinate system for navigation.\\n  </p>\\n  <div style=\\"display: flex; flex-wrap: wrap; gap: 0.75rem; font-size: 0.82rem; font-family: var(--font-mono);\\">\\n    <span style=\\"background: var(--bg-surface); border: 1px solid var(--border-color); padding: 0.25rem 0.6rem; border-radius: 5px; color: var(--text-primary);\\">\\n      📁 <strong>Produced Artifact:</strong> <code>ros2_ws_reference/src/nexus_amr_navigation/maps/house.yaml & house.pgm</code>\\n    </span>\\n    <span style=\\"background: var(--bg-surface); border: 1px solid var(--border-color); padding: 0.25rem 0.6rem; border-radius: 5px; color: var(--text-primary);\\">\\n      ➡️ <strong>Ingested By:</strong> Lesson 14 (Nav2 Stack Architecture &amp; Costmap 2D Configuration)\\n    </span>\\n  </div>\\n</div>\\n\\n","quizzes":[{"id":"q_l1_21_1","prompt":"What algorithm architecture does 'SLAM Toolbox' use to solve 2D mapping and loop closure?","options":["Particle filtering (Gmapping)","Pose-graph optimization with scan-matching and Ceres solver","Extended Kalman Filter (EKF)","Deep reinforcement learning"],"correct":1,"explanation":"SLAM Toolbox uses graph-based SLAM. It creates pose graphs with scan-matching constraints and executes non-linear graph optimization using the Ceres solver to resolve loop closures."}],"has_quiz":true,"next_id":"lesson_14","prev_id":"lesson_12","subtopics":[{"id":"1-overview-learning-objectives","title":"1. Overview &amp; Learning Objectives"},{"id":"2-localization-definition","title":"2. Mobile Robot Localization: Problem Formulation &amp; Pose Estimation"},{"id":"3-localization-algorithms-taxonomy","title":"3. Different Types of Localization Algorithms (EKF, Markov, Grid, Monte Carlo)"},{"id":"4-amcl-measurement-representation","title":"4. AMCL Measurement Representation: Beam Model &amp; Raycasting (Slide 129)"},{"id":"5-amcl-step-by-step","title":"5. Adaptive Monte Carlo Localization (AMCL) Step-by-Step (4 Steps)"},{"id":"6-localization-challenges","title":"6. Localization Challenges: Position Tracking vs. Kidnapped Robot Problem"},{"id":"7-mapping-grid-discretization","title":"7. Occupancy Grid Mapping &amp; Log-Odds Bayesian Updates (4 Steps)"},{"id":"8-slam-dilemma-dataflow","title":"8. The SLAM Dilemma &amp; Classical Dataflow Architecture"},{"id":"9-step1-install-packages","title":"9. Step 1: Install Required ROS 2 Packages (slam_toolbox &amp; nav2)"},{"id":"10-step2-create-mapping-package","title":"10. Step 2: Create Mapping Package in Workspace (nexus_amr_mapping)"},{"id":"11-step3-add-config-launch","title":"11. Step 3: Add SLAM Configuration &amp; Launch Files"},{"id":"12-step4-tuning-config","title":"12. Step 4: SLAM Configuration Parameter Tuning Matrix"},{"id":"13-step5-running-launch-teleop","title":"13. Step 5: Running Launch File &amp; Teleop (Live Mapping in RViz2)"},{"id":"14-step6-saving-map-files","title":"14. Step 6: Map Serialization &amp; Saving Map Files (.yaml &amp; .pgm)"},{"id":"15-hands-on-student-challenge","title":"15. Hands-on Student Challenge: Online SLAM Mapping &amp; Relocalization Verification"}]},{"id":"lesson_14","num":14,"num_str":"14","title":"Nav2 Stack Architecture, Path Planning & Parameter Tuning","slug":"19_nav2_architecture_and_costmaps","filename":"19_nav2_architecture_and_costmaps.md","module":"Day 3: Autonomous SLAM & Nav2 Navigation","module_id":3,"duration":"45-60 min","focus":"Navigation2 Server Architecture, Costmap 2D Layers, Inflation Math & Safety Buffers","snapshot":[["Nav2 Server Architecture","BT Navigator orchestrates lifecycle planner, controller, and recovery servers via ROS 2 Action interfaces."],["Layered Costmap 2D","Composes Static Map Layer, Obstacle Raytracing Layer, and Inflation Safety Layer into a unified navigation grid."],["Inflation Exponential Decay","Calculates safety cost halos around physical walls using cost_scaling_factor and inflation_radius to penalize close proximity."],["Global vs Local Costmaps","Global Costmap plans complete warehouse trajectories; Local Rolling Costmap (3x3m) detects dynamic obstacles for collision avoidance."]],"html_content":"\\n<h2 id=\\"1-overview-learning-objectives\\">1. Overview &amp; Learning Objectives</h2>\\n<div class=\\"learning-objectives-banner\\">\\n  <div class=\\"objectives-header\\">\\n    <span class=\\"objectives-icon\\">🎯</span>\\n    <h3 class=\\"objectives-main-title\\">Learning Objectives &amp; Core Outcomes</h3>\\n  </div>\\n  <ul class=\\"objectives-list\\">\\n    <li><strong>Mathematical Foundations:</strong> Understand how continuous robot workspace geometry is transformed into discrete Configuration Space (C-Space) via obstacle inflation by robot radius.</li>\\n    <li><strong>Layered Costmaps:</strong> Master the 3-tier Costmap 2D architecture combining the Static map, live LiDAR/depth Obstacle layers, and exponential Inflation buffer.</li>\\n    <li><strong>Safety Buffer Decay:</strong> Calculate lethal obstacle boundaries, inscribed radii, and exponential cost decay curves to prevent AMR chassis collisions.</li>\\n    <li><strong>Nav2 Server Stack:</strong> Learn the separation of responsibilities between BT Navigator, Planner Server, Controller Server, and Recovery Server.</li>\\n    <li><strong>Production Configuration:</strong> Configure and tune <code class=\\"inline-code\\">nav2_params.yaml</code> for industrial differential drive AMRs operating in dynamic logistics warehouses.</li>\\n  </ul>\\n</div>\\n\\n<h2 id=\\"2-navigation-problem-formulation\\">2. Mobile Robot Navigation Problem Formulation &amp; Geometry</h2>\\n<p>Autonomous mobile robot navigation is the science of computing and executing a safe, kinematically feasible trajectory from a current robot pose to a desired target goal without colliding with static warehouse infrastructure or dynamic obstacles.</p>\\n\\n<div class=\\"grid-card-container\\" style=\\"display: grid; grid-template-columns: repeat(3, 1fr); gap: 1rem; margin: 1.5rem 0;\\">\\n  <div class=\\"golden-card\\" style=\\"background: rgba(15, 23, 42, 0.6); border: 1px solid rgba(59, 130, 246, 0.3); border-radius: 8px; padding: 1rem;\\">\\n    <h4 style=\\"color: #60a5fa; margin-top: 0; font-size: 0.95rem;\\">1. Environment Geometry</h4>\\n    <p style=\\"font-size: 0.85rem; line-height: 1.4; color: #94a3b8;\\">Physical boundaries, warehouse racking columns, walls, aisles, and restricted zones define the operational workspace <em>W &sub; &real;&sup2;</em>.</p>\\n  </div>\\n  <div class=\\"golden-card\\" style=\\"background: rgba(15, 23, 42, 0.6); border: 1px solid rgba(59, 130, 246, 0.3); border-radius: 8px; padding: 1rem;\\">\\n    <h4 style=\\"color: #60a5fa; margin-top: 0; font-size: 0.95rem;\\">2. Robot Geometry</h4>\\n    <p style=\\"font-size: 0.85rem; line-height: 1.4; color: #94a3b8;\\">The physical chassis footprint (length, width, wheel baseline, caster placement, payload overhang) dictates whether the robot can physically fit through a corridor.</p>\\n  </div>\\n  <div class=\\"golden-card\\" style=\\"background: rgba(15, 23, 42, 0.6); border: 1px solid rgba(59, 130, 246, 0.3); border-radius: 8px; padding: 1rem;\\">\\n    <h4 style=\\"color: #60a5fa; margin-top: 0; font-size: 0.95rem;\\">3. Poses &amp; Algorithm</h4>\\n    <p style=\\"font-size: 0.85rem; line-height: 1.4; color: #94a3b8;\\">Given <em>Start Pose (x_s, y_s, &theta;_s)</em> and <em>Goal Pose (x_g, y_g, &theta;_g)</em>, the Path Planning Algorithm searches for a continuous collision-free route.</p>\\n  </div>\\n</div>\\n\\n<h2 id=\\"3-continuous-representation-collision\\">3. Continuous Workspace Representation &amp; Collision Dilemma (5-Step Breakdown)</h2>\\n<p>Before diving into algorithms, let us study how path planning operates in continuous space and why treating the robot as a simple point leads to catastrophic warehouse collisions:</p>\\n\\n<div class=\\"steps-grid\\" style=\\"display: grid; grid-template-columns: repeat(2, 1fr); gap: 1rem; margin: 1.5rem 0;\\">\\n  <div class=\\"step-card\\" style=\\"background: rgba(15, 23, 42, 0.6); border: 1px solid rgba(234, 179, 8, 0.3); border-radius: 8px; padding: 1rem;\\">\\n    <h4 style=\\"color: #eab308; margin-top: 0; font-size: 0.95rem;\\">Step 1: Continuous 2D Workspace &amp; Goal</h4>\\n    <img src=\\"assets/images/nav_continuous_rep_step1.png\\" alt=\\"Continuous Space Step 1\\" class=\\"lesson-image\\" style=\\"width: 100%; border-radius: 6px; margin: 0.5rem 0;\\" />\\n    <p style=\\"font-size: 0.85rem; line-height: 1.4; color: #94a3b8;\\">The robot starts at an origin pose in continuous Cartesian space with an intended target waypoint across the warehouse floor.</p>\\n  </div>\\n  <div class=\\"step-card\\" style=\\"background: rgba(15, 23, 42, 0.6); border: 1px solid rgba(234, 179, 8, 0.3); border-radius: 8px; padding: 1rem;\\">\\n    <h4 style=\\"color: #eab308; margin-top: 0; font-size: 0.95rem;\\">Step 2: Workspace Obstacle Boundaries</h4>\\n    <img src=\\"assets/images/nav_continuous_rep_step2.png\\" alt=\\"Continuous Space Step 2\\" class=\\"lesson-image\\" style=\\"width: 100%; border-radius: 6px; margin: 0.5rem 0;\\" />\\n    <p style=\\"font-size: 0.85rem; line-height: 1.4; color: #94a3b8;\\">Physical obstacles (pallets, pillars, machinery) introduce geometric keep-out zones in the workspace.</p>\\n  </div>\\n  <div class=\\"step-card\\" style=\\"background: rgba(15, 23, 42, 0.6); border: 1px solid rgba(234, 179, 8, 0.3); border-radius: 8px; padding: 1rem;\\">\\n    <h4 style=\\"color: #eab308; margin-top: 0; font-size: 0.95rem;\\">Step 3: Robot Trajectory Footprint Sweeping</h4>\\n    <img src=\\"assets/images/nav_continuous_rep_step3.png\\" alt=\\"Continuous Space Step 3\\" class=\\"lesson-image\\" style=\\"width: 100%; border-radius: 6px; margin: 0.5rem 0;\\" />\\n    <p style=\\"font-size: 0.85rem; line-height: 1.4; color: #94a3b8;\\">A candidate centerline path is traced between start and goal. However, the robot is not a dimensionless point—it has physical width and radius <em>r_robot</em>.</p>\\n  </div>\\n  <div class=\\"step-card\\" style=\\"background: rgba(15, 23, 42, 0.6); border: 1px solid rgba(239, 68, 68, 0.3); border-radius: 8px; padding: 1rem;\\">\\n    <h4 style=\\"color: #f87171; margin-top: 0; font-size: 0.95rem;\\">Step 4: The Collision Dilemma (Clearance Failure)</h4>\\n    <img src=\\"assets/images/nav_continuous_rep_collision.png\\" alt=\\"Continuous Space Step 4: Collision\\" class=\\"lesson-image\\" style=\\"width: 100%; border-radius: 6px; margin: 0.5rem 0;\\" />\\n    <p style=\\"font-size: 0.85rem; line-height: 1.4; color: #94a3b8;\\">If the path passes closer to an obstacle than the robot radius (<em>distance &lt; r_robot</em>), the robot's physical chassis strikes the obstacle, resulting in severe hardware collision.</p>\\n  </div>\\n</div>\\n\\n<div class=\\"two-col-layout\\" style=\\"display: grid; grid-template-columns: repeat(2, 1fr); gap: 1rem; margin: 1.5rem 0;\\">\\n  <div class=\\"step-card\\" style=\\"background: rgba(15, 23, 42, 0.6); border: 1px solid rgba(16, 185, 129, 0.3); border-radius: 8px; padding: 1rem;\\">\\n    <h4 style=\\"color: #34d399; margin-top: 0; font-size: 0.95rem;\\">Step 5a: Distance Clearance Checking</h4>\\n    <img src=\\"assets/images/nav_continuous_rep_clearance_check.png\\" alt=\\"Clearance Check\\" class=\\"lesson-image\\" style=\\"width: 100%; border-radius: 6px; margin: 0.5rem 0;\\" />\\n    <p style=\\"font-size: 0.85rem; line-height: 1.4; color: #94a3b8;\\">To guarantee safety, every point along the path must satisfy the strict geometric constraint: <strong>Distance to nearest obstacle &gt; r_robot</strong>.</p>\\n  </div>\\n  <div class=\\"step-card\\" style=\\"background: rgba(15, 23, 42, 0.6); border: 1px solid rgba(16, 185, 129, 0.3); border-radius: 8px; padding: 1rem;\\">\\n    <h4 style=\\"color: #34d399; margin-top: 0; font-size: 0.95rem;\\">Step 5b: Allowable Collision-Free Path</h4>\\n    <img src=\\"assets/images/nav_continuous_rep_allowable_path.png\\" alt=\\"Allowable Path\\" class=\\"lesson-image\\" style=\\"width: 100%; border-radius: 6px; margin: 0.5rem 0;\\" />\\n    <p style=\\"font-size: 0.85rem; line-height: 1.4; color: #94a3b8;\\">The algorithm reroutes the path away from narrow gaps, finding a trajectory where the entire swept volume of the AMR clears all obstacles comfortably.</p>\\n  </div>\\n</div>\\n\\n<h2 id=\\"4-cspace-obstacle-inflation\\">4. Configuration Space (C-Space) &amp; Obstacle Inflation Theory</h2>\\n<p>Continuously checking complex polygon robot geometries against every obstacle in the workspace is computationally prohibitive. Mobile robotics solves this through a brilliant mathematical transformation: <strong>Configuration Space (C-Space)</strong>.</p>\\n\\n<div class=\\"two-col-layout\\" style=\\"display: grid; grid-template-columns: repeat(2, 1fr); gap: 1rem; margin: 1.5rem 0;\\">\\n  <div class=\\"step-card\\" style=\\"background: rgba(15, 23, 42, 0.6); border: 1px solid rgba(168, 85, 247, 0.3); border-radius: 8px; padding: 1rem;\\">\\n    <h4 style=\\"color: #c084fc; margin-top: 0; font-size: 0.95rem;\\">Step 1: Inflating Obstacles by Robot Radius</h4>\\n    <img src=\\"assets/images/nav_cspace_obstacle_inflation.png\\" alt=\\"C-Space Obstacle Inflation\\" class=\\"lesson-image\\" style=\\"width: 100%; border-radius: 6px; margin: 0.5rem 0;\\" />\\n    <p style=\\"font-size: 0.85rem; line-height: 1.4; color: #94a3b8;\\">Every obstacle in the workspace is expanded outward in all directions by the robot radius <em>r_robot</em> (Minkowski sum: <em>Obstacle &oplus; Robot_Footprint</em>).</p>\\n  </div>\\n  <div class=\\"step-card\\" style=\\"background: rgba(15, 23, 42, 0.6); border: 1px solid rgba(168, 85, 247, 0.3); border-radius: 8px; padding: 1rem;\\">\\n    <h4 style=\\"color: #c084fc; margin-top: 0; font-size: 0.95rem;\\">Step 2: Point Robot Representation &amp; C_free / C_obs</h4>\\n    <img src=\\"assets/images/nav_cspace_cfree_cobs.png\\" alt=\\"C-Space Free and Occupied\\" class=\\"lesson-image\\" style=\\"width: 100%; border-radius: 6px; margin: 0.5rem 0;\\" />\\n    <p style=\\"font-size: 0.85rem; line-height: 1.4; color: #94a3b8;\\">With obstacles inflated, the robot collapses into an infinitesimal single point mass. The workspace partitions strictly into <strong>C_free</strong> (admissible points) and <strong>C_obs</strong> (inadmissible points).</p>\\n  </div>\\n</div>\\n\\n<h2 id=\\"5-costmap-2d-layers\\">5. Costmap 2D: The 3-Tier Layered Architecture</h2>\\n<p>ROS 2 Nav2 implements C-Space inflation dynamically using the <strong>Costmap 2D</strong> plugin architecture. It stacks multiple independent 2D raster grids on top of each other:</p>\\n\\n<div class=\\"grid-card-container\\" style=\\"display: grid; grid-template-columns: repeat(3, 1fr); gap: 1rem; margin: 1.5rem 0;\\">\\n  <div class=\\"golden-card\\" style=\\"background: rgba(15, 23, 42, 0.6); border: 1px solid rgba(234, 179, 8, 0.3); border-radius: 8px; padding: 1rem;\\">\\n    <h4 style=\\"color: #eab308; margin-top: 0; font-size: 0.95rem;\\">1️⃣ Static Layer</h4>\\n    <p style=\\"font-size: 0.85rem; line-height: 1.4; color: #94a3b8;\\">Subscribes to <code class=\\"inline-code\\">/map</code> published by <code class=\\"inline-code\\">map_server</code>. Represents permanent structural elements: walls, columns, racking. Cost values are 0 (free) or 254 (lethal).</p>\\n  </div>\\n  <div class=\\"golden-card\\" style=\\"background: rgba(15, 23, 42, 0.6); border: 1px solid rgba(234, 179, 8, 0.3); border-radius: 8px; padding: 1rem;\\">\\n    <h4 style=\\"color: #eab308; margin-top: 0; font-size: 0.95rem;\\">2️⃣ Obstacle Layer</h4>\\n    <p style=\\"font-size: 0.85rem; line-height: 1.4; color: #94a3b8;\\">Subscribes to live sensor streams (<code class=\\"inline-code\\">/scan</code>). Raycasts through free space and dynamically inserts/clears unexpected obstacles (forklifts, crates, humans).</p>\\n  </div>\\n  <div class=\\"golden-card\\" style=\\"background: rgba(15, 23, 42, 0.6); border: 1px solid rgba(234, 179, 8, 0.3); border-radius: 8px; padding: 1rem;\\">\\n    <h4 style=\\"color: #eab308; margin-top: 0; font-size: 0.95rem;\\">3️⃣ Inflation Layer</h4>\\n    <p style=\\"font-size: 0.85rem; line-height: 1.4; color: #94a3b8;\\">Propagates obstacle costs outward through an exponential decay function, generating a continuous gradient potential field that repels the robot from hazards.</p>\\n  </div>\\n</div>\\n\\n<h2 id=\\"6-inflation-mathematics\\">6. Inflation Layer Mathematics: The Safety Buffer &amp; Decay Function</h2>\\n<p>Each cell in the Costmap 2D holds an unsigned 8-bit integer cost value <em>C &isin; [0, 255]</em>:</p>\\n<ul style=\\"font-size: 0.9rem; line-height: 1.6; color: #94a3b8;\\">\\n  <li><strong>254 (Lethal Obstacle):</strong> The physical obstacle cell itself.</li>\\n  <li><strong>253 (Inscribed Obstacle Radius):</strong> Cells within the inscribed circle radius <em>r_inscribed</em>. Driving here guarantees collision.</li>\\n  <li><strong>1 &ndash; 252 (Decay Potential Zone):</strong> Cost smoothly drops exponentially with Euclidean distance <em>d</em>:\\n    <div style=\\"background: rgba(15, 23, 42, 0.8); border: 1px solid rgba(234, 179, 8, 0.3); border-radius: 6px; padding: 0.75rem; margin: 0.5rem 0; font-family: monospace; color: #fbbf24; text-align: center;\\">\\n      Cost(d) = 252 &times; exp( -&alpha; &times; (d - r_inscribed) )\\n    </div>\\n    where &alpha; is the inflation decay factor (<code class=\\"inline-code\\">cost_scaling_factor</code>).\\n  </li>\\n  <li><strong>0 (Free Space):</strong> Completely clear traversable floor where navigation incurs zero obstacle penalty.</li>\\n  <li><strong>255 (Unknown Space):</strong> Unexplored regions outside the sensor horizon.</li>\\n</ul>\\n\\n<h2 id=\\"7-global-vs-local-costmaps\\">7. Global vs. Local Costmap Configuration &amp; Parameter Matrix</h2>\\n<table style=\\"width: 100%; border-collapse: collapse; margin: 1.5rem 0; font-size: 0.85rem;\\">\\n  <thead>\\n    <tr style=\\"background: rgba(30, 41, 59, 0.8); color: #e2e8f0; border-bottom: 2px solid #eab308;\\">\\n      <th style=\\"padding: 0.6rem; text-align: left;\\">Feature</th>\\n      <th style=\\"padding: 0.6rem; text-align: left;\\">Global Costmap</th>\\n      <th style=\\"padding: 0.6rem; text-align: left;\\">Local Costmap</th>\\n    </tr>\\n  </thead>\\n  <tbody>\\n    <tr style=\\"border-bottom: 1px solid rgba(255, 255, 255, 0.1);\\">\\n      <td style=\\"padding: 0.6rem; font-weight: bold;\\">Tracking Frame</td>\\n      <td style=\\"padding: 0.6rem;\\"><code>map</code> (World Fixed)</td>\\n      <td style=\\"padding: 0.6rem;\\"><code>odom</code> (Rolling Window Centered on AMR)</td>\\n    </tr>\\n    <tr style=\\"border-bottom: 1px solid rgba(255, 255, 255, 0.1);\\">\\n      <td style=\\"padding: 0.6rem; font-weight: bold;\\">Update Rate</td>\\n      <td style=\\"padding: 0.6rem;\\">1.0 &ndash; 2.0 Hz (Macro Level)</td>\\n      <td style=\\"padding: 0.6rem;\\">10.0 &ndash; 20.0 Hz (Micro Control Loop)</td>\\n    </tr>\\n    <tr style=\\"border-bottom: 1px solid rgba(255, 255, 255, 0.1);\\">\\n      <td style=\\"padding: 0.6rem; font-weight: bold;\\">Grid Dimensions</td>\\n      <td style=\\"padding: 0.6rem;\\">Full warehouse map size (e.g. 50m &times; 50m)</td>\\n      <td style=\\"padding: 0.6rem;\\">Rolling bounding box (e.g. 3.0m &times; 3.0m)</td>\\n    </tr>\\n    <tr>\\n      <td style=\\"padding: 0.6rem; font-weight: bold;\\">Primary Client</td>\\n      <td style=\\"padding: 0.6rem;\\">Planner Server (Global Path Finding)</td>\\n      <td style=\\"padding: 0.6rem;\\">Controller Server (Local Dynamic Avoidance)</td>\\n    </tr>\\n  </tbody>\\n</table>\\n\\n<h2 id=\\"8-nav2-server-architecture\\">8. Nav2 System Architecture: Lifecycle Servers &amp; Recovery Pipeline</h2>\\n<p>Nav2 decouples autonomy into specialized ROS 2 nodes orchestrated by the Behavior Tree Navigator:</p>\\n\\n<p><img src=\\"assets/images/nav2_architecture.png\\" alt=\\"Nav2 Server Subsystem &amp; Costmap Architecture\\" class=\\"lesson-image\\" style=\\"max-height: 400px; width: 100%; object-fit: contain; margin: 1.5rem 0;\\" loading=\\"lazy\\" /></p>\\n<ul style=\\"font-size: 0.9rem; line-height: 1.6; color: #94a3b8;\\">\\n  <li><strong>BT Navigator:</strong> Evaluates behavior trees to coordinate planning, path following, progress checks, and recoveries.</li>\\n  <li><strong>Planner Server:</strong> Calculates global routes from start to goal at 1 Hz using global costmap.</li>\\n  <li><strong>Controller Server:</strong> Computes instantaneous <code>/cmd_vel</code> twist commands at 20 Hz avoiding local obstacles.</li>\\n  <li><strong>Recoveries Server:</strong> Executes recovery behaviors (in-place spin, backup, costmap clearing) when stuck.</li>\\n  <li><strong>Lifecycle Manager:</strong> State machine controlling Unconfigured &rarr; Inactive &rarr; Active transitions across all servers.</li>\\n</ul>\\n\\n<h2 id=\\"9-nav2-production-parameter-tuning\\">9. Nav2 Production Parameter Tuning Guide &amp; Optimization Matrix</h2>\\n<p>Deploying autonomous mobile robots in real-world warehouse environments requires rigorous tuning of costmaps, planners, and local controllers inside <code>nav2_params.yaml</code>:</p>\\n\\n<div class=\\"grid-card-container\\" style=\\"display: grid; grid-template-columns: repeat(2, 1fr); gap: 1rem; margin: 1.5rem 0;\\">\\n  <div class=\\"golden-card\\" style=\\"background: rgba(15, 23, 42, 0.6); border: 1px solid rgba(59, 130, 246, 0.3); border-radius: 8px; padding: 1rem;\\">\\n    <h4 style=\\"color: #60a5fa; margin-top: 0; font-size: 0.95rem;\\">1. Costmap 2D &amp; AMCL Tuning</h4>\\n    <ul style=\\"font-size: 0.85rem; line-height: 1.5; color: #94a3b8; padding-left: 1.2rem;\\">\\n      <li><code>inflation_radius (0.55m):</code> Inscribed radius + buffer to prevent chassis scraping.</li>\\n      <li><code>cost_scaling_factor (3.0):</code> Controls exponential decay steepness. Higher value forces robot through narrow doors.</li>\\n      <li><code>min_particles (500) / max_particles (2000):</code> Prevents particle deprivation during rapid turns while bounding CPU usage.</li>\\n      <li><code>update_min_d (0.2m) / update_min_a (0.2rad):</code> Filters idle sensor noise when stationary.</li>\\n    </ul>\\n  </div>\\n  <div class=\\"golden-card\\" style=\\"background: rgba(15, 23, 42, 0.6); border: 1px solid rgba(16, 185, 129, 0.3); border-radius: 8px; padding: 1rem;\\">\\n    <h4 style=\\"color: #34d399; margin-top: 0; font-size: 0.95rem;\\">2. DWB Controller &amp; Critic Balancing</h4>\\n    <ul style=\\"font-size: 0.85rem; line-height: 1.5; color: #94a3b8; padding-left: 1.2rem;\\">\\n      <li><code>PathAlign.scale (32.0):</code> Penalizes chassis heading deviation from global plan.</li>\\n      <li><code>PathDist.scale (32.0):</code> Penalizes lateral cross-track distance away from the global path.</li>\\n      <li><code>GoalDist.scale (24.0):</code> Incentivizes forward velocity toward target waypoint.</li>\\n      <li><code>BaseObstacle.scale (0.02):</code> Critical safety critic: instantly vetoes any candidate trajectory crossing lethal obstacles.</li>\\n    </ul>\\n  </div>\\n</div>\\n\\n<div class=\\"code-header-card\\" style=\\"margin-top: 1.5rem;\\">\\n  <span class=\\"file-path\\">ros2_ws_reference/src/nexus_amr_navigation/config/nav2_params.yaml</span>\\n  <span class=\\"code-badge\\">Production Configuration</span>\\n</div>\\n<pre><code class=\\"language-yaml\\">controller_server:\\n  ros__parameters:\\n    controller_frequency: 20.0\\n    min_x_velocity_threshold: 0.001\\n    min_theta_velocity_threshold: 0.001\\n    progress_checker_plugin: \\"progress_checker\\"\\n    goal_checker_plugins: [\\"general_goal_checker\\"]\\n    controller_plugins: [\\"FollowPath\\"]\\n    progress_checker:\\n      plugin: \\"nav2_controller::SimpleProgressChecker\\"\\n      required_movement_radius: 0.2\\n      movement_time_allowance: 10.0\\n    general_goal_checker:\\n      plugin: \\"nav2_controller::SimpleGoalChecker\\"\\n      xy_goal_tolerance: 0.15\\n      yaw_goal_tolerance: 0.10\\n      stateful: True\\n    FollowPath:\\n      plugin: \\"dwb_core::DWBLocalPlanner\\"\\n      max_vel_x: 0.60\\n      min_vel_x: 0.0\\n      max_vel_theta: 1.50\\n      acc_lim_x: 1.50\\n      acc_lim_theta: 2.50\\n      critics: [\\"RotateToGoal\\", \\"Oscillation\\", \\"BaseObstacle\\", \\"GoalAlign\\", \\"PathAlign\\", \\"PathDist\\", \\"GoalDist\\"]\\n      PathAlign.scale: 32.0\\n      GoalAlign.scale: 24.0\\n      PathDist.scale: 32.0\\n      GoalDist.scale: 24.0\\n      BaseObstacle.scale: 0.02</code></pre>\\n\\n<h2 id=\\"10-hands-on-student-challenge\\">10. Hands-on Student Challenge: Real-Time Costmap Inflation &amp; Clearance Auditor</h2>\\n<p>In this lab exercise, students configure <code class=\\"inline-code\\">nav2_params.yaml</code>, adjust <code class=\\"inline-code\\">inflation_radius</code> and <code class=\\"inline-code\\">cost_scaling_factor</code>, and verify safety clearance bands in RViz2 under real-time simulation.</p>\\n","quizzes":[{"id":"q_l1_22_1","prompt":"In Nav2 Costmap 2D, what is the role of the Inflation Layer?","options":["It compresses the map image size for network bandwidth","It expands obstacle boundaries by the robot's inscribed radius and applies exponential decay costs to prevent the robot from brushing against walls","It dynamically updates the battery level","It recalculates motor wheel PID gains"],"correct":1,"explanation":"The Inflation Layer propagates lethal obstacle costs outward by robot radius + inflation radius, penalizing paths too close to physical obstacles and preventing side collisions."}],"has_quiz":true,"next_id":"lesson_15","prev_id":"lesson_13","subtopics":[{"id":"1-overview-learning-objectives","title":"1. Overview &amp; Learning Objectives"},{"id":"2-navigation-problem-formulation","title":"2. Mobile Robot Navigation Problem Formulation &amp; Geometry"},{"id":"3-continuous-representation-collision","title":"3. Continuous Workspace Representation &amp; Collision Dilemma (5-Step Breakdown)"},{"id":"4-cspace-obstacle-inflation","title":"4. Configuration Space (C-Space) &amp; Obstacle Inflation Theory"},{"id":"5-costmap-2d-layers","title":"5. Costmap 2D: The 3-Tier Layered Architecture"},{"id":"6-inflation-mathematics","title":"6. Inflation Layer Mathematics: The Safety Buffer &amp; Decay Function"},{"id":"7-global-vs-local-costmaps","title":"7. Global vs. Local Costmap Configuration &amp; Parameter Matrix"},{"id":"8-nav2-server-architecture","title":"8. Nav2 System Architecture: Lifecycle Servers &amp; Recovery Pipeline"},{"id":"9-hands-on-student-challenge","title":"9. Hands-on Student Challenge: Real-Time Costmap Inflation &amp; Clearance Auditor"}]},{"id":"lesson_15","num":15,"num_str":"15","title":"Autonomous Navigation Scripting with Nav2 Simple Commander","slug":"22_autonomous_patrol_nav2_simple_commander","filename":"22_autonomous_patrol_nav2_simple_commander.md","module":"Day 3: Autonomous SLAM & Nav2 Navigation","module_id":3,"duration":"45-60 min","focus":"Capstone Autonomous Mission: Multi-Checkpoint Warehouse Patrol with Nav2 Simple Commander and Facility Floor Plan","snapshot":[["Simple Commander API","BasicNavigator Python class encapsulates complex Nav2 action clients, feedback listeners, and cancel calls into simple methods."],["Multi-Waypoint Missions","goToPose(), followWaypoints(), and cancelTask() enable programmatic warehouse inspection, material delivery, and patrol routes."],["Non-Blocking Navigation Loops","isTaskComplete() and getFeedback() allow Python scripts to monitor live distance-to-goal and time remaining asynchronously."],["Emergency Recovery Handling","Detects navigation failures, aborts blocked routes, and executes fail-safe return-to-base missions programmatically."]],"html_content":"<h2 id=\\"1-overview-learning-objectives\\">1. Overview &amp; Learning Objectives</h2>\\n<p>Up to this point, you commanded goals manually by clicking buttons in RViz2. In commercial warehouse robotics, an AMR receives autonomous mission assignments from an ERP or warehouse execution system (WES): <strong>&quot;Pick up pallet at Staging Area Entrance -&gt; Deliver to Packing Bay Bravo -&gt; Return to Charger.&quot;</strong></p>\\n<p>The <strong>Nav2 Simple Commander API (<code class=\\"inline-code\\">BasicNavigator</code>)</strong> is the standard Python programmatic SDK for orchestrating autonomous navigation tasks.</p>\\n<p><div class=\\"learning-objectives-card\\">\\n  <div class=\\"learning-objectives-header\\">\\n    <div class=\\"objectives-icon-badge\\">\\n      <span style=\\"font-size: 1.15rem; line-height: 1;\\">🎯</span>\\n    </div>\\n    <div class=\\"objectives-title-group\\">\\n      <h3 class=\\"objectives-main-title\\">Learning Objectives &amp; Core Outcomes</h3>\\n      <span class=\\"objectives-subtitle\\">By the end of this lesson, you will be able to:</span>\\n    </div>\\n    <span class=\\"objectives-count-badge\\">6 CORE OUTCOMES</span>\\n  </div>\\n  <ul class=\\"learning-objectives-list\\">\\n    <li class=\\"learning-objective-item\\">\\n      <span class=\\"objective-num-badge\\">1</span>\\n      <span class=\\"objective-text\\">Initialize the navigation stack programmatically using <code class=\\"inline-code\\">BasicNavigator.waitUntilNav2Active()</code>.</span>\\n    </li>\\n    <li class=\\"learning-objective-item\\">\\n      <span class=\\"objective-num-badge\\">2</span>\\n      <span class=\\"objective-text\\">Seed initial localization estimates using <code class=\\"inline-code\\">setInitialPose()</code>.</span>\\n    </li>\\n    <li class=\\"learning-objective-item\\">\\n      <span class=\\"objective-num-badge\\">3</span>\\n      <span class=\\"objective-text\\">Dispatch asynchronous navigation goals with <code class=\\"inline-code\\">goToPose()</code> and multi-point missions with <code class=\\"inline-code\\">followWaypoints()</code>.</span>\\n    </li>\\n    <li class=\\"learning-objective-item\\">\\n      <span class=\\"objective-num-badge\\">4</span>\\n      <span class=\\"objective-text\\">Monitor non-blocking real-time feedback (distance remaining, estimated time of arrival).</span>\\n    </li>\\n    <li class=\\"learning-objective-item\\">\\n      <span class=\\"objective-num-badge\\">5</span>\\n      <span class=\\"objective-text\\">Implement safety watchdog timeout loops and goal cancellation.</span>\\n    </li>\\n    <li class=\\"learning-objective-item\\">\\n      <span class=\\"objective-num-badge\\">6</span>\\n      <span class=\\"objective-text\\">Build and execute an autonomous multi-waypoint inspection patrol loop.</span>\\n    </li>\\n  </ul>\\n</div>\\n\\n<h2 id=\\"2-the-simple-commander-python-api-architecture\\">2. The Simple Commander Python API Architecture</h2>\\n<p><img src=\\"assets/images/nav2_simple_commander.svg\\" alt=\\"Nav2 Simple Commander Architecture\\" class=\\"lesson-image\\" loading=\\"lazy\\" /></p>\\n<hr class=\\"divider\\">\\n<h2 id=\\"3-core-basicnavigator-methods\\">3. Core <code class=\\"inline-code\\">BasicNavigator</code> Methods</h2>\\n<div class=\\"table-responsive\\"><table>\\n<thead>\\n<tr>\\n<th>Method</th>\\n<th>Return Type</th>\\n<th>Description</th>\\n</tr>\\n</thead>\\n<tbody>\\n<tr>\\n<td><code class=\\"inline-code\\">setInitialPose(pose)</code></td>\\n<td><code class=\\"inline-code\\">None</code></td>\\n<td>Publishes 2D pose to <code class=\\"inline-code\\">/initialpose</code> for AMCL particle filter convergence.</td>\\n</tr>\\n<tr>\\n<td><code class=\\"inline-code\\">waitUntilNav2Active()</code></td>\\n<td><code class=\\"inline-code\\">None</code></td>\\n<td>Blocks script until all Nav2 lifecycle nodes report <code class=\\"inline-code\\">Active</code> state.</td>\\n</tr>\\n<tr>\\n<td><code class=\\"inline-code\\">goToPose(goal_pose)</code></td>\\n<td><code class=\\"inline-code\\">None</code></td>\\n<td>Asynchronously dispatches a navigation goal (non-blocking).</td>\\n</tr>\\n<tr>\\n<td><code class=\\"inline-code\\">followWaypoints(poses)</code></td>\\n<td><code class=\\"inline-code\\">None</code></td>\\n<td>Dispatches a sequential list of waypoints.</td>\\n</tr>\\n<tr>\\n<td><code class=\\"inline-code\\">isTaskComplete()</code></td>\\n<td><code class=\\"inline-code\\">bool</code></td>\\n<td>Returns <code class=\\"inline-code\\">True</code> when navigation has terminated (succeeded, canceled, or failed).</td>\\n</tr>\\n<tr>\\n<td><code class=\\"inline-code\\">getFeedback()</code></td>\\n<td><code class=\\"inline-code\\">NavigationFeedback</code></td>\\n<td>Returns real-time metrics: <code class=\\"inline-code\\">distance_remaining</code>, <code class=\\"inline-code\\">navigation_time</code>.</td>\\n</tr>\\n<tr>\\n<td><code class=\\"inline-code\\">cancelTask()</code></td>\\n<td><code class=\\"inline-code\\">None</code></td>\\n<td>Immediately aborts the in-progress navigation goal.</td>\\n</tr>\\n<tr>\\n<td><code class=\\"inline-code\\">getResult()</code></td>\\n<td><code class=\\"inline-code\\">TaskResult</code></td>\\n<td>Returns final outcome enum (<code class=\\"inline-code\\">SUCCEEDED</code>, <code class=\\"inline-code\\">CANCELED</code>, <code class=\\"inline-code\\">FAILED</code>).</td>\\n</tr>\\n</tbody>\\n</table></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"4-complete-autonomous-patrol-script-walkthrough\\">4. Complete Autonomous Patrol Script Walkthrough</h2>\\n\\n<div class=\\"alert alert-info alert-briefing\\">\\n  <div class=\\"alert-icon\\">🗺️</div>\\n  <div class=\\"alert-content\\">\\n    <div class=\\"alert-title\\">Robotics Flight Operations Mission Briefing: Autonomous Mission Orchestration with Nav2 Simple Commander</div>\\n    <div class=\\"alert-body\\">\\n      <strong>Physical AMR Context &amp; Operational Challenge:</strong><br>\\n      In commercial AMR deployments, operators do not click navigation goals in RViz2. Mobile robots receive automated dispatch orders from Warehouse Management Systems (WMS): 'Depart home base station, navigate to Staging Area A, pause for pallet loading, traverse to Drop-off Station 3, return to home base'.\\n      <br><br>\\n      <strong>Architectural Role &amp; Why This Mechanism:</strong><br>\\n      The <strong>Nav2 Simple Commander API</strong> (<code>BasicNavigator</code>) provides a clean, asynchronous Python mission scripting interface over the entire Nav2 action stack. It abstracts goal dispatch (<code>goToPose</code>, <code>followWaypoints</code>), task preemption, battery monitoring, and recovery watchdog monitors into an elegant imperative API.\\n      <br><br>\\n      <strong>Flight Objective &amp; Behavioral Outcome:</strong><br>\\n      Construct an autonomous warehouse patrol mission in Python using <code>BasicNavigator</code>. Initialize pose estimates, dispatch sequential navigation waypoints, audit transit progress in a non-blocking loop, handle recovery timeouts, and return safely to home station upon mission completion.\\n    </div>\\n  </div>\\n</div>\\n\\n<p>Create the autonomous patrol script: <code class=\\"inline-code\\">~/ros2_ws/src/nexus_amr_navigation/nexus_amr_navigation/m03_l16_01_nav2_commander_explained.py</code>. This production script initializes Nav2, dispatches sequential inspection waypoints, and executes an automated return to home station:</p>\\n<p><div class=\\"code-container\\" data-language=\\"python\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">python</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-python\\">#!/usr/bin/env python3\\n&quot;&quot;&quot;\\nAutonomous Multi-Waypoint Warehouse Patrol Script\\nUses Nav2 Simple Commander API with non-blocking feedback and timeout guards.\\n&quot;&quot;&quot;\\n\\nimport time\\nimport math\\nimport rclpy\\nfrom geometry_msgs.msg import PoseStamped\\nfrom nav2_simple_commander.robot_navigator import BasicNavigator, TaskResult\\n\\n\\ndef create_pose(navigator, x, y, yaw):\\n    &quot;&quot;&quot;Helper creating a PoseStamped in map frame.&quot;&quot;&quot;\\n    pose = PoseStamped()\\n    pose.header.frame_id = &#x27;map&#x27;\\n    pose.header.stamp = navigator.get_clock().now().to_msg()\\n    pose.pose.position.x = float(x)\\n    pose.pose.position.y = float(y)\\n    pose.pose.orientation.z = math.sin(yaw / 2.0)\\n    pose.pose.orientation.w = math.cos(yaw / 2.0)\\n    return pose\\n\\n\\ndef main():\\n    rclpy.init()\\n    navigator = BasicNavigator()\\n\\n    # 1. Wait until Nav2 lifecycle nodes are Active\\n    navigator.get_logger().info(&#x27;Waiting for Nav2 to activate...&#x27;)\\n    navigator.waitUntilNav2Active()\\n\\n    # 2. Define patrol checkpoints: (Name, X, Y, Yaw)\\n    checkpoints = [\\n        (&quot;Staging Area Entrance&quot;, 1.5, 0.5, 0.0),\\n        (&quot;Storage Rack Aisle B&quot;, 2.0, 2.0, 1.57),\\n        (&quot;Inspection Bay&quot;, 0.5, 1.8, 3.14),\\n    ]\\n\\n    # 3. Execute sequential patrol loop\\n    for name, x, y, yaw in checkpoints:\\n        goal = create_pose(navigator, x, y, yaw)\\n        navigator.get_logger().info(f&#x27;Navigating to {name} ({x}, {y})...&#x27;)\\n        navigator.goToPose(goal)\\n\\n        start_time = time.time()\\n        while not navigator.isTaskComplete():\\n            fb = navigator.getFeedback()\\n            if fb:\\n                navigator.get_logger().info(\\n                    f&#x27;[{name}] Remaining distance: {fb.distance_remaining:.2f}m&#x27;,\\n                    throttle_duration_sec=2.0\\n                )\\n\\n            # Safety Watchdog Timeout: cancel if travel exceeds 45 seconds!\\n            if time.time() - start_time &gt; 45.0:\\n                navigator.get_logger().warn(f&#x27;Timeout at {name}! Canceling...&#x27;)\\n                navigator.cancelTask()\\n                break\\n\\n            time.sleep(1.0)\\n\\n        # Process outcome\\n        if navigator.getResult() == TaskResult.SUCCEEDED:\\n            navigator.get_logger().info(f&#x27;Reached {name}! Dwell inspection pause (2s)...&#x27;)\\n            time.sleep(2.0)\\n        else:\\n            navigator.get_logger().error(f&#x27;Failed to reach {name}! Aborting mission.&#x27;)\\n            break\\n\\n    # 4. Return to home station\\n    navigator.get_logger().info(&#x27;Patrol complete! Returning to home station...&#x27;)\\n    home_pose = create_pose(navigator, -2.0, 1.0, 0.0)\\n    navigator.goToPose(home_pose)\\n    while not navigator.isTaskComplete():\\n        time.sleep(1.0)\\n\\n    navigator.get_logger().info(&#x27;Safely returned to home station.&#x27;)\\n    rclpy.shutdown()\\n\\n\\nif __name__ == &#x27;__main__&#x27;:\\n    main()\\n</code></pre>\\n</div>\\n\\n<div class=\\"code-breakdown-card\\">\\n  <h4 class=\\"code-breakdown-title\\">🔬 Core Code Deep Dive &amp; Operational Breakdown: BasicNavigator Patrol Script Mechanics</h4>\\n  <p class=\\"code-breakdown-intro\\">Key methods of the Nav2 Python Mission Scripting API:</p>\\n  <ul class=\\"code-breakdown-list\\">\\n    <li class=\\"code-breakdown-item\\"><strong>Lifecycle Initialization:</strong> <code>navigator.waitUntilNav2Active()</code> blocks until all Nav2 managed lifecycle nodes (planner, controller, BT navigator, costmaps) transition to the <code>ACTIVE</code> state.</li>\\n    <li class=\\"code-breakdown-item\\"><strong>Asynchronous Trajectory Dispatch:</strong> <code>navigator.goToPose(goal_pose)</code> submits the navigation action goal asynchronously, allowing the Python script to run continuous watchdog checks during transit.</li>\\n    <li class=\\"code-breakdown-item\\"><strong>Watchdog & Timeout Supervision:</strong> In <code>while not navigator.isTaskComplete():</code>, tracking elapsed time and checking <code>navigator.getFeedback()</code> detects robot stalls or path blockages before hardware damage occurs.</li>\\n    <li class=\\"code-breakdown-item\\"><strong>Mission Result Audit:</strong> <code>result = navigator.getResult()</code> evaluates whether the robot reached the destination (<code>TaskResult.SUCCEEDED</code>), canceled, or failed, allowing immediate fallback to recovery behaviors.</li>\\n  </ul>\\n</div>\\n\\n</p>\\n<h3 id=\\"core-logic-breakdown-what-we-are-trying-to-achieve-why\\">Core Logic Breakdown: What We Are Trying to Achieve &amp; Why</h3>\\n<div class=\\"table-responsive\\"><table>\\n<thead>\\n<tr>\\n<th>Code Segment</th>\\n<th>What We Are Trying to Achieve</th>\\n<th>Why It Is Written This Way &amp; Underlying Mechanism</th>\\n</tr>\\n</thead>\\n<tbody>\\n<tr>\\n<td><code class=\\"inline-code\\">navigator = BasicNavigator()</code></td>\\n<td>Instantiate high-level mission commander.</td>\\n<td>Wraps Nav2 Action Clients (<code class=\\"inline-code\\">NavigateToPose</code>, <code class=\\"inline-code\\">FollowWaypoints</code>, <code class=\\"inline-code\\">ComputePathToPose</code>) inside a simplified, blocking/non-blocking Python API.</td>\\n</tr>\\n<tr>\\n<td><code class=\\"inline-code\\">navigator.waitUntilNav2Active()</code></td>\\n<td>Synchronize with Nav2 lifecycle state machines.</td>\\n<td>In ROS 2, Nav2 nodes (costmap servers, planners, controllers) start in an <code class=\\"inline-code\\">Unconfigured</code> or <code class=\\"inline-code\\">Inactive</code> state. Attempting to navigate before nodes reach <code class=\\"inline-code\\">Active</code> causes immediate rejected goals.</td>\\n</tr>\\n<tr>\\n<td><code class=\\"inline-code\\">pose.header.frame_id = &#x27;map&#x27;</code></td>\\n<td>Define target coordinates in global reference frame.</td>\\n<td>In robotics navigation, target waypoints must be referenced to the static global origin (<code class=\\"inline-code\\">map</code> frame), not the moving chassis (<code class=\\"inline-code\\">base_link</code>) or local odometry (<code class=\\"inline-code\\">odom</code> which drifts over time).</td>\\n</tr>\\n<tr>\\n<td><code class=\\"inline-code\\">navigator.goToPose(goal)</code></td>\\n<td>Asynchronous action goal dispatch.</td>\\n<td>Sends the goal to the Nav2 Behavior Tree Navigator action server without blocking execution.</td>\\n</tr>\\n<tr>\\n<td><code class=\\"inline-code\\">while not navigator.isTaskComplete():</code></td>\\n<td>Non-blocking execution polling loop.</td>\\n<td>Allows the control script to remain responsive: monitoring remaining distance, checking sensor safety stops, updating dashboards, or checking timeouts while the robot drives.</td>\\n</tr>\\n<tr>\\n<td><code class=\\"inline-code\\">fb = navigator.getFeedback()</code><br><code class=\\"inline-code\\">dist = fb.distance_remaining</code></td>\\n<td>Query real-time feedback metrics.</td>\\n<td>Nav2 streams continuous feedback from the controller server indicating Euclidean path distance remaining and estimated travel time.</td>\\n</tr>\\n<tr>\\n<td><code class=\\"inline-code\\">if time.time() - start_time &gt; 45.0:</code><br><code class=\\"inline-code\\">navigator.cancelTask()</code></td>\\n<td><strong>Autonomous Safety Watchdog</strong>: Prevent infinite deadlocks.</td>\\n<td>If an aisle is blocked by an unmapped obstacle, the robot might attempt repeated recovery spins. The watchdog timer detects lack of progress and cancels the goal cleanly so the mission script can take corrective action or retreat.</td>\\n</tr>\\n<tr>\\n<td><code class=\\"inline-code\\">navigator.getResult() == TaskResult.SUCCEEDED</code></td>\\n<td>Validate physical mission completion.</td>\\n<td>Evaluates whether the Nav2 Behavior Tree terminated with success, or whether it failed/was canceled.</td>\\n</tr>\\n</tbody>\\n</table></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"5-execution-verification\\">5. Execution &amp; Verification</h2>\\n<p>With simulation and navigation active:</p>\\n<p><div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\">ros2 run nexus_amr_navigation m03_l16_01_nav2_commander_explained\\n</code></pre>\\n</div>\\n</p>\\n<p>Watch the robot sequentially drive through every warehouse aisle, halt for inspection scans, and automatically return to the home home station!</p>\\n<hr class=\\"divider\\">\\n<hr class=\\"divider\\">\\n<h2 id=\\"6-hands-on-student-challenge\\">6. Hands-on Student Challenge: Autonomous Multi-Checkpoint Inspection Patrol with Simple Commander</h2>\\n<p>Program an autonomous inspection patrol route for the AMR using the Nav2 Simple Commander API. The robot must visit a sequence of three warehouse stations and return autonomously to the home station.</p>\\n\\n<div class=\\"alert alert-tip\\">\\n  <div class=\\"alert-title\\">🎯 Mission Requirements</div>\\n  <ol>\\n    <li><strong>TODO 1:</strong> Initialize <code class=\\"inline-code\\">BasicNavigator()</code> and wait for Nav2 to reach the active state (<code class=\\"inline-code\\">navigator.waitUntilNav2Active()</code>).</li>\\n    <li><strong>TODO 2:</strong> Iterate through checkpoints Alpha, Bravo, Charlie and dispatch target poses using <code class=\\"inline-code\\">navigator.goToPose(goal_pose)</code>.</li>\\n    <li><strong>TODO 3:</strong> Poll navigation feedback while <code class=\\"inline-code\\">not navigator.isTaskComplete()</code> and evaluate per-waypoint timeout.</li>\\n    <li><strong>TODO 4:</strong> Check <code class=\\"inline-code\\">navigator.getResult()</code> for <code class=\\"inline-code\\">TaskResult.SUCCEEDED</code>, pause 2.0s for simulated payload inspection, and dispatch final home stationing goal.</li>\\n  </ol>\\n</div>\\n\\n\\n<div class=\\"alert alert-info alert-briefing\\">\\n  <div class=\\"alert-icon\\">🏁</div>\\n  <div class=\\"alert-content\\">\\n    <div class=\\"alert-title\\">Robotics Flight Operations Mission Briefing: Multi-Checkpoint Autonomous Warehouse Patrol Mission Challenge</div>\\n    <div class=\\"alert-body\\">\\n      <strong>Physical AMR Context &amp; Operational Challenge:</strong><br>\\n      Warehouse inspection AMRs must navigate complex multi-stop routes: inspect fire extinguishers at Checkpoint 1, check freezer temperature at Checkpoint 2, verify shelf stock at Checkpoint 3, and return to charging station. If an aisle is blocked, the robot must not loop indefinitely; it must timeout cleanly and report the blockage.\\n      <br><br>\\n      <strong>Architectural Role &amp; Why This Mechanism:</strong><br>\\n      Using <code>BasicNavigator.followWaypoints(poses)</code> dispatches an entire route to Nav2 in a single action goal. The Nav2 waypoint follower handles sequential pose transitions, pause intervals, and task execution at each station.\\n      <br><br>\\n      <strong>Flight Objective &amp; Behavioral Outcome:</strong><br>\\n      Complete <code>m03_l16_02_task_multi_waypoint_patrol.py</code> to assemble 3 patrol waypoints, configure feedback monitoring with a 60-second transit watchdog, and execute an autonomous inspection tour with return to base.\\n    </div>\\n  </div>\\n</div>\\n\\n<h3 id=\\"61-starter-template\\">6.1 Starter Template: <code class=\\"inline-code\\">m03_l16_02_task_multi_waypoint_patrol.py</code></h3>\\n<p>Copy the starter template from the reference workspace into your active student workspace:</p>\\n<div class=\\"code-container\\" data-language=\\"bash\\">\\n  <div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n  <pre><code class=\\"language-bash\\">cp ~/ros2_ws_reference/src/nexus_amr_navigation/nexus_amr_navigation/m03_l16_02_task_multi_waypoint_patrol.py ~/ros2_ws/src/nexus_amr_navigation/nexus_amr_navigation/</code></pre>\\n</div>\\n<p>Open the copied file in your editor and complete the marked <code class=\\"inline-code\\">TODO</code> targets:</p>\\n\\n<div class=\\"code-container\\" data-language=\\"python\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">python</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-python\\">#!/usr/bin/env python3\\n&quot;&quot;&quot;\\n================================================================================\\nNexus AMR Learning Hub - Level 1: Day 3 Student Task\\nPackage: nexus_amr_navigation\\nTask:    task_multi_waypoint_patrol.py\\n================================================================================\\n\\nEXERCISE OVERVIEW:\\n------------------\\nYour mission is to program an autonomous inspection patrol route for the AMR\\nusing the Nav2 Simple Commander API. The robot must visit a sequence of three\\nwarehouse stations, inspect each location, and return autonomously to home station.\\n\\nPATROL WAYPOINTS (map frame):\\n-----------------------------\\n1. Checkpoint Alpha   : x=1.5m, y=0.5m, yaw=0.0 rad\\n2. Checkpoint Bravo   : x=2.0m, y=2.0m, yaw=1.57 rad (90 deg)\\n3. Checkpoint Charlie : x=0.5m, y=1.8m, yaw=3.14 rad (180 deg)\\n4. Home Base Station     : x=0.0m, y=0.0m, yaw=0.0 rad\\n\\nOBJECTIVES:\\n-----------\\n1. Initialize BasicNavigator and ensure all Nav2 nodes are active.\\n2. Iterate through each checkpoint:\\n   - Command robot using \`navigator.goToPose(goal_pose)\`.\\n   - Poll feedback while \`not navigator.isTaskComplete()\`.\\n   - Implement a per-checkpoint timeout (e.g., 45 seconds).\\n   - If reached, log success and pause 2 seconds for sensor inspection.\\n3. Once all stations are visited, dispatch a final goal to return to (0, 0, 0).\\n================================================================================\\n&quot;&quot;&quot;\\n\\nimport time\\nimport math\\nimport rclpy\\nfrom geometry_msgs.msg import PoseStamped\\nfrom nav2_simple_commander.robot_navigator import BasicNavigator, TaskResult\\n\\n\\ndef create_goal_pose(navigator: BasicNavigator, x: float, y: float, yaw: float) -&gt; PoseStamped:\\n    &quot;&quot;&quot;\\n    Helper function: Creates a stamped pose in the &#x27;map&#x27; frame.\\n    &quot;&quot;&quot;\\n    pose = PoseStamped()\\n    pose.header.frame_id = &#x27;map&#x27;\\n    pose.header.stamp = navigator.get_clock().now().to_msg()\\n    pose.pose.position.x = float(x)\\n    pose.pose.position.y = float(y)\\n    pose.pose.position.z = 0.0\\n    # Planar quaternion from yaw\\n    pose.pose.orientation.z = math.sin(yaw / 2.0)\\n    pose.pose.orientation.w = math.cos(yaw / 2.0)\\n    return pose\\n\\n\\ndef main():\\n    &quot;&quot;&quot;\\n    Student Task: Multi-Waypoint Autonomous Patrol Loop.\\n    &quot;&quot;&quot;\\n    rclpy.init()\\n\\n    # --------------------------------------------------------------------------\\n    # TODO 1: Initialize Navigator and Wait for Nav2 Lifecycle\\n    # --------------------------------------------------------------------------\\n    # - Hint: Instantiate BasicNavigator() and wait for Nav2 lifecycle startup using navigator.waitUntilNav2Active().\\n    # --------------------------------------------------------------------------\\n    navigator = BasicNavigator()\\n    # TODO: STUDENT CODE HERE\\n\\n    waypoints = [\\n        (2.0, 1.0, 0.0, &quot;Staging Area Entrance&quot;),\\n        (4.5, -2.0, 1.57, &quot;Storage Rack Aisle B&quot;),\\n        (1.0, -3.5, 3.14, &quot;Inspection Bay&quot;),\\n    ]\\n\\n    # --------------------------------------------------------------------------\\n    # TODO 2: Loop Through Waypoints and Monitor Autonomous Execution\\n    # --------------------------------------------------------------------------\\n    # - Hint: Convert each waypoint tuple into a PoseStamped using create_goal_pose(). Dispatch navigation via goToPose(), monitor execution until task completes, and verify TaskResult.SUCCEEDED.\\n    # --------------------------------------------------------------------------\\n    # TODO: STUDENT CODE HERE\\n\\n    # --------------------------------------------------------------------------\\n    # TODO 3: Return to Home Station (x=0.0, y=0.0, yaw=0.0)\\n    # --------------------------------------------------------------------------\\n    # - Hint: Create a final goal at home coordinates (0.0, 0.0, 0.0) and dispatch navigator.goToPose(home_goal) to return to base.\\n    # --------------------------------------------------------------------------\\n    # TODO: STUDENT CODE HERE\\n\\n    rclpy.shutdown()\\n\\n\\nif __name__ == &#x27;__main__&#x27;:\\n    main()\\n</code></pre>\\n</div>\\n\\n<h3 id=\\"62-verification-steps\\">6.2 Verification Steps &amp; Expected Terminal Output</h3>\\n<p>Run your node or test command and observe the output:</p>\\n<div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash (Terminal 1 - Gazebo & Nav2 Stack)</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\">source ~/ros2_ws/install/setup.bash\\nros2 launch nexus_amr_navigation navigation.launch.py</code></pre>\\n</div>\\n\\n<div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash (Terminal 2 - Multi-Waypoint Patrol Mission)</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\">source ~/ros2_ws/install/setup.bash\\nros2 run nexus_amr_navigation m03_l16_01_nav2_commander_explained</code></pre>\\n</div>\\n\\n<p><em>Expected Terminal Output:</em></p>\\n<div class=\\"code-container\\" data-language=\\"text\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">text</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-text\\">[INFO] [multi_waypoint_patrol]: Nav2 is active! Dispatched 3 inspection checkpoints.\\n[INFO] [multi_waypoint_patrol]: Navigating to Checkpoint 1: Alpha (1.50, 0.50)...\\n[INFO] [multi_waypoint_patrol]: Distance remaining: 1.12 m...\\n[INFO] [multi_waypoint_patrol]: Checkpoint Alpha reached! Inspecting sensors (2s)...\\n[INFO] [multi_waypoint_patrol]: Checkpoint Bravo reached! Inspecting sensors (2s)...\\n[INFO] [multi_waypoint_patrol]: All checkpoints visited. Returning to Home Station (0, 0)...\\n[INFO] [multi_waypoint_patrol]: PATROL MISSION ACCOMPLISHED! Mission complete! Arrived at Home Station.</code></pre>\\n</div>\\n\\n<details class=\\"reference-solution-dropdown\\">\\n  <summary class=\\"solution-summary-btn\\">\\n    <span>🔍 View Reference Solution (<code class=\\"inline-code\\">m03_l16_03_solution_multi_waypoint_patrol.py</code>)</span>\\n  </summary>\\n  <div class=\\"solution-body\\">\\n    <p>Reference file: <code class=\\"inline-code\\">ros2_ws_reference/src/nexus_amr_navigation/nexus_amr_navigation/m03_l16_03_solution_multi_waypoint_patrol.py</code></p>\\n    <div class=\\"code-container\\" data-language=\\"python\\">\\n      <div class=\\"code-header\\"><span class=\\"code-lang-tag\\">python</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n      <pre><code class=\\"language-python\\">#!/usr/bin/env python3\\n&quot;&quot;&quot;\\n================================================================================\\nNexus AMR Learning Hub - Level 1: Day 3 Reference Solution\\nPackage: nexus_amr_navigation\\nNode:    solution_multi_waypoint_patrol.py\\n================================================================================\\n\\nWHAT THIS REFERENCE SOLUTION DEMONSTRATES:\\n------------------------------------------\\nA production-grade autonomous warehouse patrol mission using the Nav2 Simple\\nCommander Python API.\\n\\nKEY ARCHITECTURAL ELEMENTS:\\n---------------------------\\n1. Lifecycle Synchronization:\\n   - Blocks cleanly with \`waitUntilNav2Active()\` to ensure costmaps, footprint\\n     publishers, trajectory planners, and motor controllers are responsive.\\n2. Sequential Patrol State Machine:\\n   - Traverses a structured list of inspection waypoints.\\n   - Dispatches each pose asynchronously via \`goToPose()\`.\\n   - Polls distance remaining and time elapsed.\\n   - Enforces a 45-second timeout watchdog per station.\\n3. Autonomous Recovery / Abort Logic:\\n   - Detects failures or cancellations and aborts gracefully instead of hanging.\\n4. Auto-Return to Home Base Station:\\n   - Automatically navigates back to base coordinate (0, 0, 0) upon completing\\n     all inspection stops.\\n================================================================================\\n&quot;&quot;&quot;\\n\\nimport time\\nimport math\\nimport rclpy\\nfrom geometry_msgs.msg import PoseStamped\\nfrom nav2_simple_commander.robot_navigator import BasicNavigator, TaskResult\\n\\n\\ndef create_goal_pose(navigator: BasicNavigator, x: float, y: float, yaw: float) -&gt; PoseStamped:\\n    &quot;&quot;&quot;\\n    Constructs a timestamped PoseStamped message in the global &#x27;map&#x27; frame.\\n\\n    Parameters:\\n        navigator: Active BasicNavigator instance.\\n        x: Target X position (meters).\\n        y: Target Y position (meters).\\n        yaw: Target heading angle (radians).\\n\\n    Returns:\\n        PoseStamped: Target coordinate setpoint for the Nav2 planner.\\n    &quot;&quot;&quot;\\n    pose = PoseStamped()\\n    pose.header.frame_id = &#x27;map&#x27;\\n    pose.header.stamp = navigator.get_clock().now().to_msg()\\n    pose.pose.position.x = float(x)\\n    pose.pose.position.y = float(y)\\n    pose.pose.position.z = 0.0\\n\\n    # Convert Euler yaw to quaternion\\n    pose.pose.orientation.x = 0.0\\n    pose.pose.orientation.y = 0.0\\n    pose.pose.orientation.z = math.sin(yaw / 2.0)\\n    pose.pose.orientation.w = math.cos(yaw / 2.0)\\n    return pose\\n\\n\\ndef main():\\n    &quot;&quot;&quot;\\n    Executes the multi-station warehouse patrol routine.\\n    &quot;&quot;&quot;\\n    rclpy.init()\\n\\n    # --------------------------------------------------------------------------\\n    # 1. INITIALIZE NAVIGATOR &amp; VERIFY LIFECYCLE STATE\\n    # --------------------------------------------------------------------------\\n    navigator = BasicNavigator()\\n    navigator.get_logger().info(&#x27;Waiting for Nav2 lifecycle nodes to become active...&#x27;)\\n    navigator.waitUntilNav2Active()\\n    navigator.get_logger().info(&#x27;Nav2 is active! Commencing autonomous warehouse patrol.&#x27;)\\n\\n    # --------------------------------------------------------------------------\\n    # 2. DEFINED CHECKPOINT PATROL ROUTE\\n    # --------------------------------------------------------------------------\\n    # (Station Label, X position, Y position, Yaw orientation)\\n    waypoints = [\\n        (&quot;Staging Area Entrance&quot;, 1.5, 0.5, 0.0),\\n        (&quot;Storage Rack Aisle B&quot;, 2.0, 2.0, 1.57),\\n        (&quot;Inspection Bay&quot;, 0.5, 1.8, 3.14),\\n    ]\\n\\n    # --------------------------------------------------------------------------\\n    # 3. WAYPOINT PATROL ITERATION LOOP\\n    # --------------------------------------------------------------------------\\n    for name, x, y, yaw in waypoints:\\n        goal_pose = create_goal_pose(navigator, x, y, yaw)\\n        navigator.get_logger().info(f&#x27;Navigating to {name} at ({x:.2f}, {y:.2f})...&#x27;)\\n\\n        # Send action goal to Nav2 Behavior Tree Navigator\\n        navigator.goToPose(goal_pose)\\n\\n        # Monitor execution progress with non-blocking feedback\\n        start_time = time.time()\\n        while not navigator.isTaskComplete():\\n            feedback = navigator.getFeedback()\\n            if feedback:\\n                dist = feedback.distance_remaining\\n                navigator.get_logger().info(f&#x27;[{name}] Remaining distance: {dist:.2f} m&#x27;)\\n\\n            # Per-waypoint safety timeout watchdog (45 seconds)\\n            if time.time() - start_time &gt; 45.0:\\n                navigator.get_logger().warn(f&#x27;Navigation to {name} timed out! Canceling...&#x27;)\\n                navigator.cancelTask()\\n                break\\n\\n            time.sleep(1.0)\\n\\n        # Check navigation outcome\\n        result = navigator.getResult()\\n        if result == TaskResult.SUCCEEDED:\\n            navigator.get_logger().info(f&#x27;Successfully reached {name}! Performing inspection scan...&#x27;)\\n            time.sleep(2.0)  # Pause for inspection sensor sweep\\n        else:\\n            navigator.get_logger().error(f&#x27;Failed to reach {name} (Result: {result}). Aborting patrol!&#x27;)\\n            break\\n\\n    # --------------------------------------------------------------------------\\n    # 4. RETURN TO HOME STATION\\n    # --------------------------------------------------------------------------\\n    navigator.get_logger().info(&#x27;Patrol mission completed! Returning to Home Station...&#x27;)\\n    home_pose = create_goal_pose(navigator, 0.0, 0.0, 0.0)\\n    navigator.goToPose(home_pose)\\n\\n    while not navigator.isTaskComplete():\\n        time.sleep(1.0)\\n\\n    if navigator.getResult() == TaskResult.SUCCEEDED:\\n        navigator.get_logger().info(&#x27;Safely returned to home station (0, 0). Mission complete!&#x27;)\\n\\n    rclpy.shutdown()\\n\\n\\nif __name__ == &#x27;__main__&#x27;:\\n    main()\\n</code></pre>\\n    </div>\\n  </div>\\n</details>\\n\\n<div class=\\"code-breakdown-card\\">\\n  <h4 class=\\"code-breakdown-title\\">🔬 Core Code Deep Dive &amp; Operational Breakdown: Multi-Waypoint Patrol Solution Breakdown</h4>\\n  <p class=\\"code-breakdown-intro\\">Key mechanics of the Multi-Waypoint Patrol solution:</p>\\n  <ul class=\\"code-breakdown-list\\">\\n    <li class=\\"code-breakdown-item\\"><strong>Multi-Pose Waypoint List Generation:</strong> Constructs a sequence of <code>PoseStamped</code> goals with position (x, y) and orientation quaternion (x, y, z, w), representing the target coordinates in the <code>map</code> frame.</li>\\n    <li class=\\"code-breakdown-item\\"><strong>Watchdog Timer Protection:</strong> The loop computes <code>elapsed_time = time.time() - start_time</code>. If elapsed time exceeds 60 seconds without completing the leg, the script calls <code>navigator.cancelTask()</code> to prevent battery exhaustion.</li>\\n    <li class=\\"code-breakdown-item\\"><strong>Home Station Return Sequence:</strong> Upon successfully visiting all inspection checkpoints, the script commands a final trajectory back to the origin home pose (0.0, 0.0, 0.0), verifying completion before shutting down.</li>\\n  </ul>\\n</div>\\n\\n\\n<div class=\\"asset-handoff-card\\" style=\\"margin: 1.75rem 0 1rem 0; padding: 1.15rem 1.4rem; border-radius: 10px; background: rgba(16, 185, 129, 0.06); border: 1px solid rgba(16, 185, 129, 0.25); border-left: 4px solid #10b981;\\">\\n  <div style=\\"display: flex; align-items: center; gap: 0.5rem; margin-bottom: 0.5rem;\\">\\n    <span style=\\"font-size: 1.1rem;\\">📦</span>\\n    <strong style=\\"font-size: 0.95rem; color: #10b981; text-transform: uppercase; letter-spacing: 0.04em;\\">Asset Handoff &amp; Next Lesson Pipeline Bridge</strong>\\n  </div>\\n  <p style=\\"margin: 0 0 0.65rem 0; font-size: 0.88rem; color: var(--text-primary); line-height: 1.6;\\">\\n    Your master mission script represents the culmination of Level 1 AMR engineering, executing complete multi-station warehouse logistics missions autonomously.\\n  </p>\\n  <div style=\\"display: flex; flex-wrap: wrap; gap: 0.75rem; font-size: 0.82rem; font-family: var(--font-mono);\\">\\n    <span style=\\"background: var(--bg-surface); border: 1px solid var(--border-color); padding: 0.25rem 0.6rem; border-radius: 5px; color: var(--text-primary);\\">\\n      📁 <strong>Produced Artifact:</strong> <code>ros2_ws_reference/src/nexus_amr_navigation/nexus_amr_navigation/m03_l16_02_task_multi_waypoint_patrol.py</code>\\n    </span>\\n    <span style=\\"background: var(--bg-surface); border: 1px solid var(--border-color); padding: 0.25rem 0.6rem; border-radius: 5px; color: var(--text-primary);\\">\\n      ➡️ <strong>Ingested By:</strong> Bonus Lesson 17 (Dynamic Parameters &amp; YAML Configuration)\\n    </span>\\n  </div>\\n</div>\\n\\n","quizzes":[{"id":"q_l1_25_1","prompt":"Which high-level Python class from 'nav2_simple_commander' provides intuitive navigation APIs such as 'goToPose()' and 'followWaypoints()'?","options":["BasicNavigator","Nav2Client","SimpleGoalRunner","AmrCommander"],"correct":0,"explanation":"nav2_simple_commander.robot_navigator.BasicNavigator wraps the complex action client and lifecycle boilerplate into clean Python methods like goToPose() and followWaypoints()."}],"has_quiz":true,"next_id":"lesson_16","prev_id":"lesson_14","subtopics":[{"id":"1-overview-learning-objectives","title":"1. Overview &amp; Learning Objectives"},{"id":"2-the-simple-commander-python-api-architecture","title":"2. The Simple Commander Python API Architecture"},{"id":"3-core-basicnavigator-methods","title":"3. Core BasicNavigator Methods"},{"id":"4-complete-autonomous-patrol-script-walkthrough","title":"4. Complete Autonomous Patrol Script Walkthrough"},{"id":"5-execution-verification","title":"5. Execution &amp; Verification"},{"id":"6-hands-on-student-challenge","title":"6. Hands-on Student Challenge: Autonomous Multi-Checkpoint Inspection Patrol with Simple Commander"}]},{"id":"lesson_16","num":16,"num_str":"16","title":"Dynamic Parameters & YAML Configuration","slug":"lesson-08-dynamic-parameters-yaml-configuration","filename":"lesson_08.html","module":"Bonus: Advanced Masterclasses & Electives","module_id":4,"duration":"45-60 min","focus":"ROS 2 Parameters, Parameter Descriptors, Validation Callbacks, YAML Configurations, and rqt_reconfigure","snapshot":[["Parameter Primitives","Declare strongly-typed parameters directly inside nodes with default values and runtime query."],["Dynamic Validation","Use add_on_set_parameters_callback to reject out-of-bounds safety thresholds without crashing nodes."],["Declarative YAML Matrices","Organize robot parameter configurations under the mandatory double-underscored ros__parameters namespace."],["Visual Tuning via rqt","Inspect and tune active node parameters in real-time with interactive sliders and spinboxes."]],"html_content":"<h2 id=\\"1-overview-learning-objectives\\">1. Overview &amp; Learning Objectives</h2>\\n<p>Hardcoding numeric thresholds, robot dimensions, or PID gains in Python scripts is an anti-pattern. In ROS 2, <strong>Parameters</strong> allow configuration values to be injected into nodes at startup (via YAML files or launch arguments) and dynamically modified at runtime without stopping the process.</p>\\n<p><div class=\\"learning-objectives-card\\">\\n  <div class=\\"learning-objectives-header\\">\\n    <div class=\\"objectives-icon-badge\\">\\n      <span style=\\"font-size: 1.15rem; line-height: 1;\\">🎯</span>\\n    </div>\\n    <div class=\\"objectives-title-group\\">\\n      <h3 class=\\"objectives-main-title\\">Learning Objectives &amp; Core Outcomes</h3>\\n      <span class=\\"objectives-subtitle\\">By the end of this lesson, you will be able to:</span>\\n    </div>\\n    <span class=\\"objectives-count-badge\\">5 CORE OUTCOMES</span>\\n  </div>\\n  <ul class=\\"learning-objectives-list\\">\\n    <li class=\\"learning-objective-item\\">\\n      <span class=\\"objective-num-badge\\">1</span>\\n      <span class=\\"objective-text\\">Understand how ROS 2 parameters are scoped per-node (eliminating the centralized ROS 1 parameter server).</span>\\n    </li>\\n    <li class=\\"learning-objective-item\\">\\n      <span class=\\"objective-num-badge\\">2</span>\\n      <span class=\\"objective-text\\">Declare typed parameters with <code class=\\"inline-code\\">ParameterDescriptor</code> metadata and range constraints.</span>\\n    </li>\\n    <li class=\\"learning-objective-item\\">\\n      <span class=\\"objective-num-badge\\">3</span>\\n      <span class=\\"objective-text\\">Implement dynamic runtime parameter validation using <code class=\\"inline-code\\">add_on_set_parameters_callback</code> and <code class=\\"inline-code\\">SetParametersResult</code>.</span>\\n    </li>\\n    <li class=\\"learning-objective-item\\">\\n      <span class=\\"objective-num-badge\\">4</span>\\n      <span class=\\"objective-text\\">Structure industry-standard <code class=\\"inline-code\\">.yaml</code> configuration files and load them directly via the CLI (<code class=\\"inline-code\\">--ros-args --params-file</code>).</span>\\n    </li>\\n    <li class=\\"learning-objective-item\\">\\n      <span class=\\"objective-num-badge\\">5</span>\\n      <span class=\\"objective-text\\">Inspect parameters via CLI commands and perform real-time visual dynamic tuning using <code class=\\"inline-code\\">rqt_reconfigure</code> GUI sliders.</span>\\n    </li>\\n  </ul>\\n</div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"2-ros-1-vs-ros-2-parameter-architecture\\">2. ROS 1 vs. ROS 2 Parameter Architecture</h2>\\n<p>In autonomous robotics, operating parameters such as wheel velocities, safety distance buffers, and controller PID gains must be adjustable without modifying or recompiling source code. While both ROS 1 and ROS 2 provide a parameter subsystem, the underlying communication architecture underwent a fundamental redesign:</p>\\n\\n<p><img src=\\"assets/images/ros1_vs_ros2_params.svg\\" alt=\\"ROS 1 vs. ROS 2 Parameter Architecture\\" class=\\"lesson-image\\" loading=\\"lazy\\" /></p>\\n\\n<div class=\\"table-responsive\\" style=\\"margin: 2rem 0;\\">\\n  <table style=\\"width: 100%; border-collapse: collapse; text-align: left;\\">\\n    <thead>\\n      <tr>\\n        <th style=\\"width: 26%; font-weight: 700; padding: 1rem 1.15rem;\\">Architectural Dimension</th>\\n        <th style=\\"width: 37%; padding: 1rem 1.15rem;\\">\\n          <div style=\\"display: flex; align-items: center; justify-content: space-between; gap: 0.5rem;\\">\\n            <span>ROS 1 (Legacy Master)</span>\\n            <span style=\\"display: inline-block; padding: 0.2rem 0.55rem; font-size: 0.72rem; font-weight: 700; border-radius: 9999px; background: rgba(239, 68, 68, 0.12); color: #ef4444; border: 1px solid rgba(239, 68, 68, 0.3);\\">Centralized</span>\\n          </div>\\n        </th>\\n        <th style=\\"width: 37%; padding: 1rem 1.15rem;\\">\\n          <div style=\\"display: flex; align-items: center; justify-content: space-between; gap: 0.5rem;\\">\\n            <span>ROS 2 Jazzy (Modern Standard)</span>\\n            <span style=\\"display: inline-block; padding: 0.2rem 0.55rem; font-size: 0.72rem; font-weight: 700; border-radius: 9999px; background: rgba(16, 185, 129, 0.12); color: #10b981; border: 1px solid rgba(16, 185, 129, 0.3);\\">Distributed</span>\\n          </div>\\n        </th>\\n      </tr>\\n    </thead>\\n    <tbody>\\n      <tr>\\n        <td style=\\"font-weight: 600; padding: 0.9rem 1.15rem;\\">Storage &amp; Host</td>\\n        <td style=\\"padding: 0.9rem 1.15rem;\\">Global key-value dictionary residing inside <code class=\\"inline-code\\">roscore</code> master process.</td>\\n        <td style=\\"padding: 0.9rem 1.15rem;\\"><strong>Decentralized:</strong> Each node hosts its own parameters locally in memory via internal DDS services.</td>\\n      </tr>\\n      <tr>\\n        <td style=\\"font-weight: 600; padding: 0.9rem 1.15rem;\\">Fault Tolerance (SPOF)</td>\\n        <td style=\\"padding: 0.9rem 1.15rem;\\">\\n          <span style=\\"color: #ef4444; font-weight: 600;\\">⚠️ Single Point of Failure:</span> If <code class=\\"inline-code\\">roscore</code> crashes, parameter access across the entire robot ceases.\\n        </td>\\n        <td style=\\"padding: 0.9rem 1.15rem;\\">\\n          <span style=\\"color: #10b981; font-weight: 600;\\">🛡️ Zero Single Point of Failure:</span> No central master. Each node operates autonomously without single-node dependencies.\\n        </td>\\n      </tr>\\n      <tr>\\n        <td style=\\"font-weight: 600; padding: 0.9rem 1.15rem;\\">Scope &amp; Namespaces</td>\\n        <td style=\\"padding: 0.9rem 1.15rem;\\">Flat global namespace. Nodes frequently overwrite shared keys like <code class=\\"inline-code\\">/speed</code> in multi-package stacks.</td>\\n        <td style=\\"padding: 0.9rem 1.15rem;\\"><strong>Strict Node Scoping:</strong> Fully qualified paths (<code class=\\"inline-code\\">/amr_controller/max_speed</code>). Zero parameter collisions.</td>\\n      </tr>\\n      <tr>\\n        <td style=\\"font-weight: 600; padding: 0.9rem 1.15rem;\\">Reactivity &amp; Events</td>\\n        <td style=\\"padding: 0.9rem 1.15rem;\\">Passive polling over XML-RPC. Nodes must manually re-query values or rely on external packages.</td>\\n        <td style=\\"padding: 0.9rem 1.15rem;\\"><strong>Event-Driven Callbacks:</strong> Built-in <code class=\\"inline-code\\">on_set_parameters</code> callbacks notify nodes instantly upon runtime edits.</td>\\n      </tr>\\n      <tr>\\n        <td style=\\"font-weight: 600; padding: 0.9rem 1.15rem;\\">Safety Validation</td>\\n        <td style=\\"padding: 0.9rem 1.15rem;\\">No native rejection API. Any external node can write invalid or dangerous setpoints.</td>\\n        <td style=\\"padding: 0.9rem 1.15rem;\\"><strong>Active Guard:</strong> Nodes can reject out-of-bounds inputs dynamically with <code class=\\"inline-code\\">SetParametersResult(successful=False)</code>.</td>\\n      </tr>\\n      <tr>\\n        <td style=\\"font-weight: 600; padding: 0.9rem 1.15rem;\\">Type Safety</td>\\n        <td style=\\"padding: 0.9rem 1.15rem;\\">Loosely typed XML-RPC primitives (string conversions prone to runtime faults).</td>\\n        <td style=\\"padding: 0.9rem 1.15rem;\\"><strong>Strict Static Types (REP 106):</strong> Typed as <code class=\\"inline-code\\">DOUBLE</code>, <code class=\\"inline-code\\">INTEGER</code>, <code class=\\"inline-code\\">BOOL</code>, or <code class=\\"inline-code\\">STRING</code> with range descriptors.</td>\\n      </tr>\\n    </tbody>\\n  </table>\\n</div>\\n\\n<div class=\\"alert alert-info\\">\\n  <div class=\\"alert-title\\">💡 Senior Robotics Engineering Insight</div>\\n  <p>In ROS 2, <strong>parameters never exist as unattached global variables</strong>. They are always declared inside and managed by a specific Node instance. When designing multi-robot warehouse fleets, this isolation guarantees that tuning the maximum velocity of AMR Unit 1 (<code class=\\"inline-code\\">/amr_01/teleop/max_speed</code>) can never inadvertently alter the velocity configuration of AMR Unit 2 (<code class=\\"inline-code\\">/amr_02/teleop/max_speed</code>).</p>\\n</div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"3-building-a-parameterized-node-python---step-by-step\\">3. Building a Parameterized Node (Python) - Step-by-Step</h2>\\n\\n<div class=\\"alert alert-info alert-briefing\\">\\n  <div class=\\"alert-icon\\">⚙️</div>\\n  <div class=\\"alert-content\\">\\n    <div class=\\"alert-title\\">Robotics Flight Operations Mission Briefing: AMR Dynamic Parameter &amp; Tuning Governor</div>\\n    <div class=\\"alert-body\\">\\n      <strong>Physical AMR Context &amp; Operational Challenge:</strong><br>\\n      In physical robotics, operational parameters like maximum linear speed, wheel radius, or ultrasonic safety buffers change across different operating environments. Hardcoding these values in Python source code would require recompiling and redeploying code every time a robot enters a new warehouse.\\n      <br><br>\\n      <strong>Architectural Role &amp; Why This Mechanism:</strong><br>\\n      <strong>ROS 2 Parameters</strong> allow nodes to expose configuration variables that can be queried, set at launch via YAML files, or dynamically reconfigured at runtime over DDS without restarting the node process.\\n      <br><br>\\n      <strong>Flight Objective &amp; Behavioral Outcome:</strong><br>\\n      Declare a ROS 2 parameter with default values, register the node entry point in <code class=\\"inline-code\\">setup.py</code>, build the workspace, query the parameter in a periodic control loop, and verify that changes made via the <code class=\\"inline-code\\">ros2 param set</code> CLI immediately alter the node's runtime behavior without process restarts.\\n    </div>\\n  </div>\\n</div>\\n\\n<h3 id=\\"step-31-create-or-copy-minimal-param-node\\">Step 3.1: Create or Copy the Minimal Parameter Node Script</h3>\\n<p>Copy the starter minimal parameter node script from the reference package into your workspace (or create it at <code class=\\"inline-code\\">~/ros2_ws/src/nexus_amr_basics/nexus_amr_basics/minimal_param_node.py</code>):</p>\\n\\n<div class=\\"code-container\\" data-language=\\"bash\\" style=\\"margin-bottom: 1.25rem;\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\">mkdir -p ~/ros2_ws/src/nexus_amr_basics/nexus_amr_basics\\ncp ~/ros2_ws_reference/src/nexus_amr_basics/nexus_amr_basics/minimal_param_node.py ~/ros2_ws/src/nexus_amr_basics/nexus_amr_basics/minimal_param_node.py</code></pre>\\n</div>\\n\\n<p>Inspect the implementation inside <code class=\\"inline-code\\">minimal_param_node.py</code>:</p>\\n\\n<div class=\\"code-container ide-code-window\\" data-language=\\"python\\">\\n  <div class=\\"code-header\\">\\n    <div class=\\"code-dots\\"><span class=\\"dot red\\"></span><span class=\\"dot yellow\\"></span><span class=\\"dot green\\"></span></div>\\n    <span class=\\"code-filename\\">minimal_param_node.py &mdash; Minimal ROS 2 Parameter Node</span>\\n    <button class=\\"copy-code-btn\\">📋 Copy</button>\\n  </div>\\n  <pre><code class=\\"language-python\\">#!/usr/bin/env python3\\n\\"\\"\\"\\nNexus AMR Robotics: MinimalParam\\nDemonstrates parameter declaration, runtime query, and dynamic reconfiguration.\\n\\"\\"\\"\\n\\nimport rclpy\\nfrom rclpy.node import Node\\n\\n\\nclass MinimalParam(Node):\\n\\n    def __init__(self):\\n        super().__init__('minimal_param_node')\\n\\n        # 1. Declare parameter 'my_parameter' with default value 'world'\\n        # The data type (string) is automatically inferred from the default value\\n        self.declare_parameter('my_parameter', 'world')\\n\\n        # 2. Create timer running every 1.0 second\\n        self.timer = self.create_timer(1.0, self.timer_callback)\\n        self.get_logger().info('MinimalParam node initialized.')\\n\\n    def timer_callback(self):\\n        # 3. Retrieve the current value of the parameter dynamically\\n        my_param = self.get_parameter('my_parameter').get_parameter_value().string_value\\n\\n        self.get_logger().info(f'Hello {my_param}!')\\n\\n\\ndef main(args=None):\\n    rclpy.init(args=args)\\n    node = MinimalParam()\\n    try:\\n        rclpy.spin(node)\\n    except KeyboardInterrupt:\\n        pass\\n    finally:\\n        node.destroy_node()\\n        rclpy.shutdown()\\n\\n\\nif __name__ == '__main__':\\n    main()\\n</code></pre>\\n</div>\\n\\n<div class=\\"code-breakdown-card\\">\\n  <h4 class=\\"code-breakdown-title\\">🔬 Core Code Deep Dive &amp; Operational Breakdown: ROS 2 Parameter Primitives</h4>\\n  <p class=\\"code-breakdown-intro\\">Mechanics of declaring and reading parameters in Python:</p>\\n  <ul class=\\"code-breakdown-list\\">\\n    <li class=\\"code-breakdown-item\\"><strong>Parameter Declaration:</strong> <code>self.declare_parameter('my_parameter', 'world')</code> registers the parameter name, default value, and infers the type (String). In ROS 2, parameters must be declared before they can be read or written.</li>\\n    <li class=\\"code-breakdown-item\\"><strong>Parameter Querying:</strong> <code>my_param = self.get_parameter('my_parameter').get_parameter_value().string_value</code> fetches the active value dynamically from the node's parameter store on each loop iteration.</li>\\n    <li class=\\"code-breakdown-item\\"><strong>Dynamic Reconfiguration:</strong> External tools (CLI, GUI, or Launch Files) can update parameter values dynamically over DDS without requiring the node process to be killed or restarted.</li>\\n  </ul>\\n</div>\\n\\n<div class=\\"table-responsive\\" style=\\"margin: 1.5rem 0;\\"><table>\\n<thead>\\n<tr>\\n<th>Code Segment</th>\\n<th>What We Are Trying to Achieve</th>\\n<th>Why It Is Written This Way &amp; Underlying Mechanism</th>\\n</tr>\\n</thead>\\n<tbody>\\n<tr>\\n<td><code class=\\"inline-code\\">self.declare_parameter('my_parameter', 'world')</code></td>\\n<td>Enforce parameter registration and schema.</td>\\n<td>In ROS 2, nodes must declare parameters before accessing them. This enforces type safety and prevents arbitrary misconfigurations.</td>\\n</tr>\\n<tr>\\n<td><code class=\\"inline-code\\">self.get_parameter('my_parameter').get_parameter_value().string_value</code></td>\\n<td>Read live parameter value from node storage.</td>\\n<td><code class=\\"inline-code\\">get_parameter()</code> returns a <code class=\\"inline-code\\">Parameter</code> object. Calling <code class=\\"inline-code\\">get_parameter_value().string_value</code> unpacks the typed string representation.</td>\\n</tr>\\n<tr>\\n<td><code class=\\"inline-code\\">ros2 param set /minimal_param_node my_parameter earth</code></td>\\n<td>Modify parameter value dynamically from outside process.</td>\\n<td>DDS dispatches parameter change events without requiring process restarts. Next time <code class=\\"inline-code\\">timer_callback</code> runs, it immediately logs <code class=\\"inline-code\\">Hello earth!</code>.</td>\\n</tr>\\n</tbody>\\n</table></div>\\n\\n<h3 id=\\"step-32-configuring-setuppy-for-minimal-param-node\\">Step 3.2: Configuring setup.py for minimal_param_node</h3>\\n<p>Before you can run the node with <code class=\\"inline-code\\">ros2 run</code>, you must register its entry point in your package manifest.</p>\\n\\n<div class=\\"file-edit-instruction-card\\">\\n  <div class=\\"file-edit-header\\">\\n    <div class=\\"file-edit-header-left\\">\\n      <span>📝 Step-by-Step File Modification Guide</span>\\n    </div>\\n    <span class=\\"file-edit-badge\\">~/ros2_ws/src/nexus_amr_basics/setup.py</span>\\n  </div>\\n  <div class=\\"file-edit-body\\">\\n    <div class=\\"file-edit-step\\">\\n      <div class=\\"file-edit-step-title\\">\\n        <span class=\\"step-num-pill\\">Step 1</span>\\n        <span>Open the Target File</span>\\n      </div>\\n      <p class=\\"step-description\\">Open <code class=\\"inline-code\\">~/ros2_ws/src/nexus_amr_basics/setup.py</code> in your editor.</p>\\n    </div>\\n\\n    <div class=\\"file-edit-step\\">\\n      <div class=\\"file-edit-step-title\\">\\n        <span class=\\"step-num-pill\\">Step 2</span>\\n        <span>Locate Insertion Point &amp; Add Lines</span>\\n      </div>\\n      <p class=\\"step-description\\">Register the minimal parameter node executable under <code class=\\"inline-code\\">'console_scripts'</code>:</p>\\n      <div class=\\"code-container\\" data-language=\\"python\\">\\n        <div class=\\"code-header\\"><span class=\\"code-lang-tag\\">python</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n        <pre><code class=\\"language-python\\">    entry_points={\\n        'console_scripts': [\\n            'ultrasonic_publisher = nexus_amr_basics.ultrasonic_sensor_node:main',\\n            'collision_monitor = nexus_amr_basics.collision_monitor_node:main',\\n            'emergency_stop_server = nexus_amr_basics.emergency_stop_server:main',\\n            'emergency_stop_client = nexus_amr_basics.emergency_stop_client:main',\\n            # >>> REGISTER MINIMAL PARAMETER NODE <<<\\n            'minimal_param_node = nexus_amr_basics.minimal_param_node:main',\\n        ],\\n    },</code></pre>\\n      </div>\\n    </div>\\n\\n    <div class=\\"file-edit-step\\">\\n      <div class=\\"file-edit-step-title\\">\\n        <span class=\\"step-num-pill\\">Step 3</span>\\n        <span>Verify the Full File After Editing</span>\\n      </div>\\n      <p class=\\"step-description\\">Self-check your file against the complete reference below to confirm indentation and syntax:</p>\\n      <details class=\\"file-edit-dropdown\\">\\n        <summary class=\\"file-edit-summary\\">\\n          <span>📄 View Complete setup.py with minimal_param_node Entry Point</span>\\n          <span class=\\"file-edit-toggle-icon\\">▶</span>\\n        </summary>\\n        <div class=\\"file-edit-dropdown-content\\">\\n          <div class=\\"code-container\\" data-language=\\"python\\">\\n            <div class=\\"code-header\\"><span class=\\"code-lang-tag\\">python</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n            <pre><code class=\\"language-python\\">from setuptools import find_packages, setup\\n\\npackage_name = 'nexus_amr_basics'\\n\\nsetup(\\n    name=package_name,\\n    version='1.0.0',\\n    packages=find_packages(exclude=['test']),\\n    data_files=[\\n        ('share/ament_index/resource_index/packages', ['resource/' + package_name]),\\n        ('share/' + package_name, ['package.xml']),\\n    ],\\n    install_requires=['setuptools'],\\n    zip_safe=True,\\n    maintainer='Nexus AMR Academy',\\n    maintainer_email='instructor@botforge.io',\\n    description='ROS 2 Sensor, Service &amp; Parameter Architecture',\\n    license='Apache-2.0',\\n    tests_require=['pytest'],\\n    entry_points={\\n        'console_scripts': [\\n            'ultrasonic_publisher = nexus_amr_basics.ultrasonic_sensor_node:main',\\n            'collision_monitor = nexus_amr_basics.collision_monitor_node:main',\\n            'emergency_stop_server = nexus_amr_basics.emergency_stop_server:main',\\n            'emergency_stop_client = nexus_amr_basics.emergency_stop_client:main',\\n            'minimal_param_node = nexus_amr_basics.minimal_param_node:main',\\n        ],\\n    },\\n)</code></pre>\\n          </div>\\n        </div>\\n      </details>\\n    </div>\\n  </div>\\n</div>\\n\\n<h3 id=\\"step-33-build-run-and-verify-parameter-cli\\">Step 3.3: Build, Run &amp; Test Dynamic Reconfiguration via CLI</h3>\\n<p>Compile the package with symlink install and source the setup script:</p>\\n\\n<div class=\\"code-container\\" data-language=\\"bash\\">\\n  <div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n  <pre><code class=\\"language-bash\\">cd ~/ros2_ws\\ncolcon build --symlink-install --packages-select nexus_amr_basics\\nsource install/setup.bash</code></pre>\\n</div>\\n\\n<p>Start the minimal parameter node in <strong>Terminal 1</strong>:</p>\\n\\n<div class=\\"code-container\\" data-language=\\"bash\\">\\n  <div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n  <pre><code class=\\"language-bash\\">ros2 run nexus_amr_basics minimal_param_node</code></pre>\\n</div>\\n\\n<div class=\\"alert-callout alert-tip\\" style=\\"margin: 1rem 0;\\">\\n  <div class=\\"alert-icon\\">⚡</div>\\n  <div class=\\"alert-body\\">\\n    <strong>Expected Startup Output in Terminal 1:</strong><br>\\n    The node starts, declares <code class=\\"inline-code\\">'my_parameter'</code> with default value <code class=\\"inline-code\\">'world'</code>, and logs every 1.0 second:<br>\\n    <pre style=\\"background: var(--bg-surface); padding: 0.75rem; border-radius: 6px; margin-top: 0.5rem; font-family: var(--font-mono); font-size: 0.85rem; color: #10b981;\\">[INFO] [minimal_param_node]: MinimalParam node initialized.\\n[INFO] [minimal_param_node]: Hello world!\\n[INFO] [minimal_param_node]: Hello world!</pre>\\n  </div>\\n</div>\\n\\n<p>Now, open <strong>Terminal 2</strong> to introspect and dynamically reconfigure the parameter at runtime:</p>\\n\\n<div class=\\"code-container\\" data-language=\\"bash\\">\\n  <div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n  <pre><code class=\\"language-bash\\"># 1. Query the current parameter value:\\nros2 param get /minimal_param_node my_parameter\\n# String value is: world\\n\\n# 2. Modify the parameter dynamically over DDS (WITHOUT restarting the node!):\\nros2 param set /minimal_param_node my_parameter earth\\n# Set parameter successful</code></pre>\\n</div>\\n\\n<div class=\\"alert-callout alert-tip\\" style=\\"margin: 1rem 0 1.5rem 0;\\">\\n  <div class=\\"alert-icon\\">🎯</div>\\n  <div class=\\"alert-body\\">\\n    <strong>Observe Terminal 1 in Real-Time:</strong><br>\\n    Immediately after executing <code class=\\"inline-code\\">ros2 param set</code>, look back at Terminal 1. On the very next timer callback, the node outputs:<br>\\n    <pre style=\\"background: var(--bg-surface); padding: 0.75rem; border-radius: 6px; margin-top: 0.5rem; font-family: var(--font-mono); font-size: 0.85rem; color: #10b981;\\">[INFO] [minimal_param_node]: Hello earth!\\n[INFO] [minimal_param_node]: Hello earth!</pre>\\n    <em>You have just proven dynamic parameter reconfiguration over DDS without killing or restarting the process!</em>\\n  </div>\\n</div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"4-parameter-descriptors-dynamic-validation-robotics-safety\\">4. Parameter Descriptors &amp; Dynamic Validation (Robotics Safety)</h2>\\n<p>In robotics systems, you often need to attach formal descriptions, enforce physical range constraints for GUI sliders, and reject invalid values (such as negative speeds or dangerous proximity thresholds) using <code class=\\"inline-code\\">add_on_set_parameters_callback</code>:</p>\\n<p><div class=\\"code-container\\" data-language=\\"python\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">python</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-python\\">from rcl_interfaces.msg import ParameterDescriptor, FloatingPointRange, SetParametersResult\\n\\nclass ParameterizedSafetyNode(Node):\\n    def __init__(self):\\n        super().__init__('parameterized_safety_node')\\n\\n        # Define numeric range descriptor: informs tools like rqt_reconfigure to render interactive sliders\\n        speed_range = FloatingPointRange(from_value=0.1, to_value=2.0, step=0.05)\\n        desc = ParameterDescriptor(\\n            description='Maximum allowable linear speed in m/s',\\n            floating_point_range=[speed_range]\\n        )\\n        self.declare_parameter('max_speed', 0.5, desc)\\n\\n        # Register dynamic validation callback\\n        self.add_on_set_parameters_callback(self.validate_params)\\n\\n    def validate_params(self, params):\\n        for param in params:\\n            if param.name == 'max_speed':\\n                if param.value <= 0.0 or param.value > 2.0:\\n                    self.get_logger().error(f'Rejected invalid speed: {param.value}')\\n                    return SetParametersResult(successful=False, reason=\\"Speed must be in [0.1, 2.0] m/s\\")\\n        return SetParametersResult(successful=True, reason=\\"Valid parameters\\")\\n</code></pre>\\n</div>\\n</p>\\n<hr class=\\"divider\\">\\n<h2 id=\\"5-organizing-configuration-with-yaml-files-cli-loading\\">5. Organizing Configuration with YAML Files &amp; CLI Parameter Loading</h2>\\n<p>In production robotics systems and autonomous fleets, hardcoding parameter values in source code or passing dozens of arguments on the command line is impractical. Instead, robots organize entire parameter matrices into structured <strong>YAML</strong> (YAML Ain't Markup Language) configuration files.</p>\\n\\n<div class=\\"alert alert-info alert-briefing\\">\\n  <div class=\\"alert-icon\\">📁</div>\\n  <div class=\\"alert-content\\">\\n    <div class=\\"alert-title\\">Robotics Fleet Practice: Declarative YAML Configurations</div>\\n    <div class=\\"alert-body\\">\\n      <strong>Why YAML Files?</strong><br>\\n      A warehouse AMR might have over 50 configurable thresholds: LiDAR filter angles, PID wheel controller gains, costmap inflation radii, and safety stop margins. Storing these in a declarative YAML file allows technicians to tune robot behavior for a specific warehouse site without editing or recompiling a single line of Python code.\\n    </div>\\n  </div>\\n</div>\\n\\n<h3 id=\\"step-51-create-yaml-config-file\\">Step 5.1: Create the Config Directory &amp; Parameters YAML File</h3>\\n<p>First, ensure the <code class=\\"inline-code\\">config/</code> directory exists inside your package (or create it with <code class=\\"inline-code\\">mkdir -p ~/ros2_ws/src/nexus_amr_basics/config</code>):</p>\\n\\n<div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\">mkdir -p ~/ros2_ws/src/nexus_amr_basics/config</code></pre>\\n</div>\\n\\n<p>Create your parameters configuration file at <code class=\\"inline-code\\">~/ros2_ws/src/nexus_amr_basics/config/teleop_params.yaml</code> (or copy from reference <code class=\\"inline-code\\">~/ros2_ws_reference/src/nexus_amr_basics/config/teleop_params.yaml</code>):</p>\\n\\n<div class=\\"code-container\\" data-language=\\"bash\\" style=\\"margin-bottom: 1.25rem;\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\">cp ~/ros2_ws_reference/src/nexus_amr_basics/config/teleop_params.yaml ~/ros2_ws/src/nexus_amr_basics/config/</code></pre>\\n</div>\\n\\n<p>Add the following configuration content inside <code class=\\"inline-code\\">teleop_params.yaml</code>:</p>\\n\\n<div class=\\"code-container ide-code-window\\" data-language=\\"yaml\\">\\n  <div class=\\"code-header\\">\\n    <div class=\\"code-dots\\"><span class=\\"dot red\\"></span><span class=\\"dot yellow\\"></span><span class=\\"dot green\\"></span></div>\\n    <span class=\\"code-filename\\">teleop_params.yaml &mdash; AMR Parameters YAML Configuration</span>\\n    <button class=\\"copy-code-btn\\">📋 Copy</button>\\n  </div>\\n  <pre><code class=\\"language-yaml\\"># Package: nexus_amr_basics\\n# Location: ~/ros2_ws/src/nexus_amr_basics/config/teleop_params.yaml\\n\\nparameterized_controller:        # Tier 1: Target node name (matches super().__init__(&#x27;parameterized_controller&#x27;))\\n  ros__parameters:               # Tier 2: Mandatory ROS 2 namespace key (NOTE: TWO underscores!)\\n    robot_id: \\"nexus-wh-01\\"       # String parameter: Fleet identification tag\\n    max_linear_speed: 0.75       # Float/Double parameter: Maximum linear velocity limit (m/s)\\n    enable_proximity_brake: true # Boolean parameter: Safety proximity brake interlock\\n    control_rate_hz: 20          # Integer parameter: Control loop update frequency (Hz)\\n    obstacle_distance_threshold: 0.45 # Float parameter: Minimum safe clearance margin (meters)\\n</code></pre>\\n</div>\\n\\n<h3 id=\\"structure-of-ros-2-yaml-files\\">Structure of ROS 2 YAML Files:</h3>\\n<p>Every ROS 2 parameter YAML file must follow a strict two-tier hierarchy:</p>\\n<ul style=\\"margin: 0.5rem 0 1rem 1.5rem; line-height: 1.8;\\">\\n  <li><strong>Tier 1 (<code class=\\"inline-code\\">parameterized_controller:</code>):</strong> The exact ROS 2 node name specified in <code class=\\"inline-code\\">super().__init__(&#x27;parameterized_controller&#x27;)</code>. Only parameters intended for this specific node will be ingested.</li>\\n  <li><strong>Tier 2 (<code class=\\"inline-code\\">ros__parameters:</code>):</strong> The mandatory ROS 2 parameter namespace root.</li>\\n  <li><strong>Key-Value Mapping:</strong> Strongly typed keys and default values matching the node&#x27;s declared parameters.</li>\\n</ul>\\n\\n<div class=\\"alert-callout alert-warning\\" style=\\"margin: 1.5rem 0;\\">\\n  <div class=\\"alert-icon\\">⚠️</div>\\n  <div class=\\"alert-body\\">\\n    <strong>Critical Syntax Rule: Double Underscores (<code class=\\"inline-code\\">ros__parameters</code>):</strong><br>\\n    The key <code class=\\"inline-code\\">ros__parameters</code> <strong>MUST have two underscores</strong>. Using a single underscore (<code class=\\"inline-code\\">ros_parameters</code>) is the #1 silent bug in ROS 2 parameter files: ROS 2 will parse the YAML without throwing an error, but will silently ignore all parameter entries, leaving your node running with default values!\\n  </div>\\n</div>\\n\\n<h3 id=\\"step-52-copy-and-register-the-node\\">Step 5.2: Create or Copy the Parameter Node Script &amp; Register Entry Point</h3>\\n<p>Create your parameterized node script at <code class=\\"inline-code\\">~/ros2_ws/src/nexus_amr_basics/nexus_amr_basics/param_node_explained.py</code> (or copy from reference <code class=\\"inline-code\\">~/ros2_ws_reference/src/nexus_amr_basics/nexus_amr_basics/m04_l17_02_param_node_explained.py</code>):</p>\\n\\n<div class=\\"code-container\\" data-language=\\"bash\\" style=\\"margin-bottom: 1.25rem;\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\">cp ~/ros2_ws_reference/src/nexus_amr_basics/nexus_amr_basics/m04_l17_02_param_node_explained.py ~/ros2_ws/src/nexus_amr_basics/nexus_amr_basics/param_node_explained.py</code></pre>\\n</div>\\n\\n<p>Add the following implementation inside <code class=\\"inline-code\\">param_node_explained.py</code>:</p>\\n\\n<div class=\\"code-container ide-code-window\\" data-language=\\"python\\">\\n  <div class=\\"code-header\\">\\n    <div class=\\"code-dots\\"><span class=\\"dot red\\"></span><span class=\\"dot yellow\\"></span><span class=\\"dot green\\"></span></div>\\n    <span class=\\"code-filename\\">param_node_explained.py &mdash; AMR Parameterized Controller Node</span>\\n    <button class=\\"copy-code-btn\\">📋 Copy</button>\\n  </div>\\n  <pre><code class=\\"language-python\\">#!/usr/bin/env python3\\n&quot;&quot;&quot;\\n================================================================================\\nNexus AMR Learning Hub - Level 1: Foundations of ROS 2\\nPackage: nexus_amr_basics\\nNode:    param_node_explained.py\\n================================================================================\\n\\nWHAT THIS NODE DOES:\\n--------------------\\nThis is an educational reference implementation demonstrating ROS 2 Parameter\\nDescriptors, strict parameter validation, and atomic parameter updates at runtime.\\n\\nROBOTICS CONCEPTS TAUGHT HERE:\\n------------------------------\\n1. Parameter Descriptors: Documenting parameters directly inside the node so\\n   running \`ros2 param describe &lt;node&gt; &lt;param&gt;\` prints human-readable descriptions\\n   and type hints to developers.\\n2. Parameter Types: Strictly enforcing types (Integer, Double, String) to avoid\\n   runtime type casting exceptions in control loops.\\n3. Guardrails &amp; Rejection: Dynamically rejecting invalid parameter values\\n   (e.g., negative frequencies or dangerous braking distances) before they\\n   compromise robot safety.\\n4. Periodic Heartbeat Diagnostics: Reporting parameter-controlled state in a\\n   timed non-blocking loop.\\n================================================================================\\n&quot;&quot;&quot;\\n\\nimport rclpy\\nfrom rclpy.executors import ExternalShutdownException\\nfrom rclpy.node import Node\\nfrom rcl_interfaces.msg import ParameterDescriptor, ParameterType, SetParametersResult\\n\\n\\nclass ParamExplainedNode(Node):\\n    &quot;&quot;&quot;\\n    Demonstrates parameter declaration, validation, and dynamic updates\\n    via the on_set_parameters callback.\\n    &quot;&quot;&quot;\\n\\n    def __init__(self):\\n        super().__init__(&#x27;parameterized_controller&#x27;)\\n\\n        # ----------------------------------------------------------------------\\n        # 1. PARAMETER DECLARATIONS WITH FORMAL DESCRIPTORS\\n        # ----------------------------------------------------------------------\\n        # Parameter 1: Simple string parameter identifying the AMR unit\\n        self.declare_parameter(\\n            &#x27;robot_id&#x27;,\\n            &#x27;nexus-wh-01&#x27;,\\n            ParameterDescriptor(description=&#x27;Unique serial ID or fleet designation of the mobile robot&#x27;)\\n        )\\n\\n        # Parameter 2: Maximum linear velocity limit (m/s)\\n        self.declare_parameter(\\n            &#x27;max_linear_speed&#x27;,\\n            0.75,\\n            ParameterDescriptor(description=&#x27;Maximum allowable linear velocity in meters/second (0.1 to 2.0)&#x27;)\\n        )\\n\\n        # Parameter 3: Proximity brake safety flag\\n        self.declare_parameter(\\n            &#x27;enable_proximity_brake&#x27;,\\n            True,\\n            ParameterDescriptor(description=&#x27;Safety interlock enabling automatic proximity braking&#x27;)\\n        )\\n\\n        # Parameter 4: Integer control loop frequency in Hertz\\n        self.declare_parameter(\\n            &#x27;control_rate_hz&#x27;,\\n            20,\\n            ParameterDescriptor(description=&#x27;Control loop execution frequency in Hertz (bounded 1 to 100)&#x27;)\\n        )\\n\\n        # Parameter 5: Float obstacle proximity threshold in meters\\n        self.declare_parameter(\\n            &#x27;obstacle_distance_threshold&#x27;,\\n            0.45,\\n            ParameterDescriptor(description=&#x27;Minimum allowed safety distance (meters) before emergency stop engages&#x27;)\\n        )\\n\\n        # ----------------------------------------------------------------------\\n        # 2. CACHING VALUES INTO LOCAL MEMBER VARIABLES\\n        # ----------------------------------------------------------------------\\n        self.robot_id = self.get_parameter(&#x27;robot_id&#x27;).value\\n        self.max_linear_speed = self.get_parameter(&#x27;max_linear_speed&#x27;).value\\n        self.enable_proximity_brake = self.get_parameter(&#x27;enable_proximity_brake&#x27;).value\\n        self.rate_hz = self.get_parameter(&#x27;control_rate_hz&#x27;).value\\n        self.obstacle_thresh = self.get_parameter(&#x27;obstacle_distance_threshold&#x27;).value\\n\\n        # ----------------------------------------------------------------------\\n        # 3. REGISTER DYNAMIC PARAMETER CHANGE CALLBACK\\n        # ----------------------------------------------------------------------\\n        self.add_on_set_parameters_callback(self.parameter_update_callback)\\n\\n        self.get_logger().info(\\n            f&quot;Param Node Initialized | ID: &#x27;{self.robot_id}&#x27; | Max Speed: {self.max_linear_speed} m/s | &quot;\\n            f&quot;Brake: {self.enable_proximity_brake} | Rate: {self.rate_hz} Hz&quot;\\n        )\\n\\n        # ----------------------------------------------------------------------\\n        # 4. CREATE TIMER LOOP USING CONFIGURED RATE\\n        # ----------------------------------------------------------------------\\n        # Timer period = 1.0 / rate_hz (seconds)\\n        self.timer = self.create_timer(1.0 / self.rate_hz, self.loop_callback)\\n        self.loop_ticks = 0\\n\\n    def parameter_update_callback(self, params):\\n        &quot;&quot;&quot;\\n        Validates incoming parameter change requests before accepting them into the node state.\\n\\n        Parameters:\\n            params (List[Parameter]): The batch of parameters being modified.\\n\\n        Returns:\\n            SetParametersResult: Indicates success=True/False and explains rejection reasons.\\n        &quot;&quot;&quot;\\n        for param in params:\\n            # Validate control_rate_hz\\n            if param.name == &#x27;control_rate_hz&#x27;:\\n                if param.type_ != ParameterType.PARAMETER_INTEGER or param.value &lt; 1 or param.value &gt; 100:\\n                    self.get_logger().error(f&quot;Rejected invalid control_rate_hz: {param.value}. Must be integer [1..100].&quot;)\\n                    return SetParametersResult(\\n                        successful=False,\\n                        reason=&quot;control_rate_hz must be an integer between 1 and 100&quot;\\n                    )\\n                self.rate_hz = param.value\\n                self.get_logger().info(f&quot;Dynamically updated control_rate_hz to {self.rate_hz} Hz&quot;)\\n\\n            # Validate obstacle_distance_threshold\\n            elif param.name == &#x27;obstacle_distance_threshold&#x27;:\\n                # Enforce physical sensor limit: cannot brake on &lt; 0.05m\\n                if param.value &lt;= 0.05:\\n                    self.get_logger().error(f&quot;Rejected unsafe obstacle threshold: {param.value} m.&quot;)\\n                    return SetParametersResult(\\n                        successful=False,\\n                        reason=&quot;obstacle_distance_threshold must be strictly greater than 0.05m&quot;\\n                    )\\n                self.obstacle_thresh = float(param.value)\\n                self.get_logger().info(f&quot;Dynamically updated obstacle_distance_threshold to {self.obstacle_thresh:.2f} m&quot;)\\n\\n            # Validate max_linear_speed\\n            elif param.name == &#x27;max_linear_speed&#x27;:\\n                if float(param.value) &lt;= 0.0 or float(param.value) &gt; 2.0:\\n                    self.get_logger().error(f&quot;Rejected invalid max_linear_speed: {param.value}. Must be in range (0.0, 2.0].&quot;)\\n                    return SetParametersResult(\\n                        successful=False,\\n                        reason=&quot;max_linear_speed must be between 0.0 and 2.0 m/s&quot;\\n                    )\\n                self.max_linear_speed = float(param.value)\\n                self.get_logger().info(f&quot;Dynamically updated max_linear_speed to {self.max_linear_speed:.2f} m/s&quot;)\\n\\n            # Validate enable_proximity_brake\\n            elif param.name == &#x27;enable_proximity_brake&#x27;:\\n                self.enable_proximity_brake = bool(param.value)\\n                self.get_logger().info(f&quot;Dynamically updated enable_proximity_brake to {self.enable_proximity_brake}&quot;)\\n\\n            # Validate robot_id\\n            elif param.name == &#x27;robot_id&#x27;:\\n                if len(str(param.value).strip()) == 0:\\n                    return SetParametersResult(successful=False, reason=&quot;robot_id cannot be empty&quot;)\\n                self.robot_id = str(param.value)\\n                self.get_logger().info(f&quot;Dynamically updated robot_id to &#x27;{self.robot_id}&#x27;&quot;)\\n\\n        return SetParametersResult(successful=True, reason=&quot;All requested parameters updated successfully&quot;)\\n\\n    def loop_callback(self):\\n        &quot;&quot;&quot;\\n        Periodic operational callback executed at self.rate_hz.\\n        Prints a diagnostic heartbeat every 5 seconds.\\n        &quot;&quot;&quot;\\n        self.loop_ticks += 1\\n        # Log every 5 seconds: rate_hz * 5 ticks\\n        if self.loop_ticks % (self.rate_hz * 5) == 0:\\n            self.get_logger().info(\\n                f&quot;[Heartbeat] Fleet Unit: {self.robot_id} | Safety Margin: {self.obstacle_thresh:.2f} m | &quot;\\n                f&quot;Active Rate: {self.rate_hz} Hz&quot;\\n            )\\n\\n\\ndef main(args=None):\\n    &quot;&quot;&quot;\\n    Node entry point.\\n    &quot;&quot;&quot;\\n    rclpy.init(args=args)\\n    node = ParamExplainedNode()\\n    try:\\n        rclpy.spin(node)\\n    except (KeyboardInterrupt, ExternalShutdownException):\\n        pass\\n    finally:\\n        node.destroy_node()\\n        if rclpy.ok():\\n            rclpy.shutdown()\\n\\n\\nif __name__ == &#x27;__main__&#x27;:\\n    main()\\n</code></pre>\\n</div>\\n\\n<h3 id=\\"step-53-configuring-setuppy-installing-yaml-configs-and-node\\">Step 5.3: Configuring setup.py &mdash; Resource Setup for YAML Configs &amp; Node Entry Point</h3>\\n<p>In Python packages managed by <code class=\\"inline-code\\">setuptools</code>, non-Python resource files (such as YAML configurations, launch files, and URDF models) are <strong>ignored by default</strong> during compilation. If you only register the node in <code class=\\"inline-code\\">console_scripts</code>, <code class=\\"inline-code\\">colcon build</code> will compile the executable, but your <code class=\\"inline-code\\">config/teleop_params.yaml</code> file will <strong>never be copied into the <code class=\\"inline-code\\">install/</code> directory</strong>.</p>\\n\\n<div class=\\"alert alert-warning\\" style=\\"margin: 1.25rem 0;\\">\\n  <div class=\\"alert-icon\\">⚠️</div>\\n  <div class=\\"alert-content\\">\\n    <div class=\\"alert-title\\">Critical Package Concept: The <code class=\\"inline-code\\">data_files</code> Resource Installation Mechanism</div>\\n    <div class=\\"alert-body\\">\\n      <strong>Why must we install configuration files into the <code class=\\"inline-code\\">share/</code> directory?</strong><br>\\n      ROS 2 runtime tools, fleet deployment scripts, and Python launch files (which you mastered in Lesson 07) locate package configurations using the Ament Index function:\\n      <pre style=\\"background: var(--bg-surface); padding: 0.5rem 0.75rem; border-radius: 6px; margin: 0.5rem 0; font-family: var(--font-mono); font-size: 0.85rem; color: #10b981;\\">get_package_share_directory('nexus_amr_basics')</pre>\\n      This function points directly to <code class=\\"inline-code\\">~/ros2_ws/install/nexus_amr_basics/share/nexus_amr_basics/</code>.\\n      To ensure your YAML files are copied there upon every build, you <strong>must</strong> declare them in the <code class=\\"inline-code\\">data_files</code> list of <code class=\\"inline-code\\">setup.py</code> using <code class=\\"inline-code\\">os.path.join</code> and <code class=\\"inline-code\\">glob</code>.\\n    </div>\\n  </div>\\n</div>\\n\\n<div class=\\"file-edit-instruction-card\\">\\n  <div class=\\"file-edit-header\\">\\n    <div class=\\"file-edit-header-left\\">\\n      <span>📝 Step-by-Step File Modification Guide</span>\\n    </div>\\n    <span class=\\"file-edit-badge\\">~/ros2_ws/src/nexus_amr_basics/setup.py</span>\\n  </div>\\n  <div class=\\"file-edit-body\\">\\n    <div class=\\"file-edit-step\\">\\n      <div class=\\"file-edit-step-title\\">\\n        <span class=\\"step-num-pill\\">Step 1</span>\\n        <span>Open the Target File</span>\\n      </div>\\n      <p class=\\"step-description\\">Open <code class=\\"inline-code\\">~/ros2_ws/src/nexus_amr_basics/setup.py</code> in your editor.</p>\\n    </div>\\n\\n    <div class=\\"file-edit-step\\">\\n      <div class=\\"file-edit-step-title\\">\\n        <span class=\\"step-num-pill\\">Step 2</span>\\n        <span>Add Path and File Globbing Imports</span>\\n      </div>\\n      <p class=\\"step-description\\">Ensure <code class=\\"inline-code\\">import os</code> and <code class=\\"inline-code\\">from glob import glob</code> are present at the top of <code class=\\"inline-code\\">setup.py</code>:</p>\\n      <div class=\\"code-container\\" data-language=\\"python\\">\\n        <div class=\\"code-header\\"><span class=\\"code-lang-tag\\">python</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n        <pre><code class=\\"language-python\\">from setuptools import find_packages, setup\\nimport os\\nfrom glob import glob</code></pre>\\n      </div>\\n    </div>\\n\\n    <div class=\\"file-edit-step\\">\\n      <div class=\\"file-edit-step-title\\">\\n        <span class=\\"step-num-pill\\">Step 3</span>\\n        <span>Install Config Directory to Package Share via data_files</span>\\n      </div>\\n      <p class=\\"step-description\\">Add the config installation rule to the <code class=\\"inline-code\\">data_files</code> list inside <code class=\\"inline-code\\">setup(...)</code>:</p>\\n      <div class=\\"code-container\\" data-language=\\"python\\">\\n        <div class=\\"code-header\\"><span class=\\"code-lang-tag\\">python</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n        <pre><code class=\\"language-python\\">    data_files=[\\n        ('share/ament_index/resource_index/packages', ['resource/' + package_name]),\\n        ('share/' + package_name, ['package.xml']),\\n        # >>> RESOURCE SETUP: INSTALL ALL YAML CONFIGS TO SHARE DIRECTORY <<<\\n        (os.path.join('share', package_name, 'config'), glob('config/*.yaml')),\\n    ],</code></pre>\\n      </div>\\n    </div>\\n\\n    <div class=\\"file-edit-step\\">\\n      <div class=\\"file-edit-step-title\\">\\n        <span class=\\"step-num-pill\\">Step 4</span>\\n        <span>Register param_node_explained in console_scripts</span>\\n      </div>\\n      <p class=\\"step-description\\">Add the executable entry point under <code class=\\"inline-code\\">'console_scripts'</code>:</p>\\n      <div class=\\"code-container\\" data-language=\\"python\\">\\n        <div class=\\"code-header\\"><span class=\\"code-lang-tag\\">python</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n        <pre><code class=\\"language-python\\">    entry_points={\\n        'console_scripts': [\\n            'ultrasonic_publisher = nexus_amr_basics.ultrasonic_sensor_node:main',\\n            'collision_monitor = nexus_amr_basics.collision_monitor_node:main',\\n            'emergency_stop_server = nexus_amr_basics.emergency_stop_server:main',\\n            'emergency_stop_client = nexus_amr_basics.emergency_stop_client:main',\\n            'minimal_param_node = nexus_amr_basics.minimal_param_node:main',\\n            # >>> REGISTER PARAMETERIZED CONTROLLER NODE <<<\\n            'param_node_explained = nexus_amr_basics.param_node_explained:main',\\n        ],\\n    },</code></pre>\\n      </div>\\n    </div>\\n\\n    <div class=\\"file-edit-step\\">\\n      <div class=\\"file-edit-step-title\\">\\n        <span class=\\"step-num-pill\\">Step 5</span>\\n        <span>Verify the Full File After Editing</span>\\n      </div>\\n      <p class=\\"step-description\\">Self-check your file against the complete reference below to confirm indentation, brackets, and commas:</p>\\n      <details class=\\"file-edit-dropdown\\">\\n        <summary class=\\"file-edit-summary\\">\\n          <span>📄 View Complete setup.py with Config Resources &amp; Entry Points</span>\\n          <span class=\\"file-edit-toggle-icon\\">▶</span>\\n        </summary>\\n        <div class=\\"file-edit-dropdown-content\\">\\n          <div class=\\"code-container\\" data-language=\\"python\\">\\n            <div class=\\"code-header\\"><span class=\\"code-lang-tag\\">python</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n            <pre><code class=\\"language-python\\">from setuptools import find_packages, setup\\nimport os\\nfrom glob import glob\\n\\npackage_name = 'nexus_amr_basics'\\n\\nsetup(\\n    name=package_name,\\n    version='1.0.0',\\n    packages=find_packages(exclude=['test']),\\n    data_files=[\\n        ('share/ament_index/resource_index/packages', ['resource/' + package_name]),\\n        ('share/' + package_name, ['package.xml']),\\n        # Resource Setup: Install YAML configs to install/nexus_amr_basics/share/nexus_amr_basics/config/\\n        (os.path.join('share', package_name, 'config'), glob('config/*.yaml')),\\n    ],\\n    install_requires=['setuptools'],\\n    zip_safe=True,\\n    maintainer='Nexus AMR Academy',\\n    maintainer_email='instructor@botforge.io',\\n    description='ROS 2 Sensor, Service &amp; Parameter Architecture',\\n    license='Apache-2.0',\\n    tests_require=['pytest'],\\n    entry_points={\\n        'console_scripts': [\\n            'ultrasonic_publisher = nexus_amr_basics.ultrasonic_sensor_node:main',\\n            'collision_monitor = nexus_amr_basics.collision_monitor_node:main',\\n            'emergency_stop_server = nexus_amr_basics.emergency_stop_server:main',\\n            'emergency_stop_client = nexus_amr_basics.emergency_stop_client:main',\\n            'minimal_param_node = nexus_amr_basics.minimal_param_node:main',\\n            'param_node_explained = nexus_amr_basics.param_node_explained:main',\\n        ],\\n    },\\n)</code></pre>\\n          </div>\\n        </div>\\n      </details>\\n    </div>\\n  </div>\\n</div>\\n\\n<h3 id=\\"step-54-build-workspace-verify-installed-config\\">Step 5.4: Build Workspace &amp; Verify Installed Config in install/</h3>\\n<p>Compile your package using <code class=\\"inline-code\\">colcon</code> and source the newly generated setup file:</p>\\n\\n<div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\">cd ~/ros2_ws\\ncolcon build --symlink-install --packages-select nexus_amr_basics\\nsource install/setup.bash</code></pre>\\n</div>\\n\\n<p>Confirm that <code class=\\"inline-code\\">colcon</code> successfully copied the YAML parameter file into the package's install share path:</p>\\n\\n<div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\">ls -la install/nexus_amr_basics/share/nexus_amr_basics/config/\\n# Expected Output:\\n# teleop_params.yaml</code></pre>\\n</div>\\n\\n<h3 id=\\"step-55-loading-yaml-parameters-via-cli\\">Step 5.5: Loading YAML Parameters via the CLI (<code class=\\"inline-code\\">--ros-args --params-file</code>)</h3>\\n<p>You do not need a complex launch file to load and test YAML configurations. You can load any parameter file directly using the ROS 2 command-line interface with the <code class=\\"inline-code\\">--ros-args --params-file</code> flag:</p>\\n\\n<div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\"># Run node and inject parameters from the installed YAML file via CLI:\\nros2 run nexus_amr_basics param_node_explained --ros-args --params-file ~/ros2_ws/install/nexus_amr_basics/share/nexus_amr_basics/config/teleop_params.yaml\\n</code></pre>\\n</div>\\n\\n<div class=\\"alert-callout alert-tip\\">\\n  <div class=\\"alert-icon\\">⚡</div>\\n  <div class=\\"alert-body\\">\\n    <strong>Expected Startup Terminal Output:</strong><br>\\n    The node starts and immediately outputs its active parameters loaded directly from the installed YAML file:<br>\\n    <pre style=\\"background: var(--bg-surface); padding: 0.75rem; border-radius: 6px; margin-top: 0.5rem; font-family: var(--font-mono); font-size: 0.85rem; color: #10b981;\\">[INFO] [parameterized_controller]: Param Node Initialized | ID: 'nexus-wh-01' | Max Speed: 0.75 m/s | Brake: True | Rate: 20 Hz\\n[INFO] [parameterized_controller]: [Heartbeat] Fleet Unit: nexus-wh-01 | Safety Margin: 0.45 m | Active Rate: 20 Hz</pre>\\n  </div>\\n</div>\\n\\n<hr class=\\"divider\\">\\n<h2 id=\\"6-parameter-inspection-with-the-cli\\">6. Parameter Inspection with the CLI</h2>\\n<p>With <code class=\\"inline-code\\">param_node_explained</code> running in <strong>Terminal 1</strong>, open <strong>Terminal 2</strong> to inspect, verify, and modify parameters live:</p>\\n\\n<div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\"># 1. List all parameters exposed by all running nodes\\nros2 param list\\n\\n# Expected Output:\\n# /parameterized_controller:\\n#   control_rate_hz\\n#   enable_proximity_brake\\n#   max_linear_speed\\n#   obstacle_distance_threshold\\n#   robot_id\\n\\n# 2. Get the current active value of a parameter\\nros2 param get /parameterized_controller max_linear_speed\\n# Double value is: 0.75\\n\\n# 3. View parameter documentation and descriptor metadata\\nros2 param describe /parameterized_controller max_linear_speed\\n# Parameter name: max_linear_speed\\n#   Type: double\\n#   Description: Maximum allowable linear velocity in meters/second (0.1 to 2.0)\\n\\n# 4. Dynamically modify a parameter at runtime\\nros2 param set /parameterized_controller max_linear_speed 1.2\\n# Set parameter successful\\n\\n# 5. Verify parameter validation rejects out-of-bounds values!\\nros2 param set /parameterized_controller max_linear_speed 99.0\\n# Setting parameter failed: Rejected out-of-bounds speed\\n\\n# 6. Dump all live parameters of a node to a YAML file for backup or deployment\\nros2 param dump /parameterized_controller\\n</code></pre>\\n</div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"7-dynamic-parameter-tuning-with-rqt-reconfigure\\">7. Real-Time Dynamic Parameter Tuning with rqt_reconfigure</h2>\\n<p>While the CLI is indispensable for scripting, automated testing, and CI/CD pipelines, robotics field engineers and controls researchers rely on visual graphical interfaces for interactive tuning. ROS 2 provides <strong><code class=\\"inline-code\\">rqt_reconfigure</code></strong>, a specialized GUI plugin that connects to live ROS 2 parameter services and auto-generates intuitive UI controls.</p>\\n\\n<div class=\\"alert alert-info alert-briefing\\">\\n  <div class=\\"alert-icon\\">🎛️</div>\\n  <div class=\\"alert-content\\">\\n    <div class=\\"alert-title\\">Robotics Engineering Insight: Why Visual Reconfiguration Matters</div>\\n    <div class=\\"alert-body\\">\\n      <strong>Live Tuning without Node Restarts:</strong><br>\\n      When tuning motion controllers (such as PID velocity gains, acceleration limits, or collision avoidance tolerances) on a physical AMR moving across an uneven floor, typing numeric CLI commands repeatedly is slow and error-prone. With <code class=\\"inline-code\\">rqt_reconfigure</code>, you drag interactive sliders smoothly back and forth, observing the immediate kinetic response of the robot in real time.\\n    </div>\\n  </div>\\n</div>\\n\\n<h3 id=\\"step-71-launching-rqt-reconfigure\\">Step 7.1: Launching rqt_reconfigure</h3>\\n<p>Keep your parameterized node running in <strong>Terminal 1</strong>. In a new <strong>Terminal 2</strong>, launch the dynamic reconfigure tool:</p>\\n\\n<div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\"># Launch the standalone dynamic parameter reconfiguration GUI:\\nros2 run rqt_reconfigure rqt_reconfigure\\n</code></pre>\\n</div>\\n\\n<div class=\\"alert-callout alert-note\\">\\n  <div class=\\"alert-icon\\">💡</div>\\n  <div class=\\"alert-body\\">\\n    <strong>Installation Tip:</strong> If <code class=\\"inline-code\\">rqt_reconfigure</code> is not found, install it via apt:\\n    <code class=\\"inline-code\\">sudo apt install ros-jazzy-rqt-reconfigure</code> (or <code class=\\"inline-code\\">ros-humble-rqt-reconfigure</code> depending on your distribution).\\n  </div>\\n</div>\\n\\n<h3 id=\\"step-72-the-gui-interface-layout\\">Step 7.2: Understanding the Interface Layout &amp; Parameter Controls</h3>\\n<p>Upon launching, <code class=\\"inline-code\\">rqt_reconfigure</code> automatically discovers all active nodes exposing parameters and presents a dual-pane workspace:</p>\\n\\n<p class=\\"lesson-image-wrapper\\">\\n  <img \\n    src=\\"assets/images/rqt_reconfigure_param_tuning.png\\" \\n    alt=\\"rqt_reconfigure GUI Parameter Inspection and Sliders\\" \\n    title=\\"rqt_reconfigure dual-pane interface: Left pane displays active node tree; right pane displays dynamically generated parameter sliders with min, max, and current values\\" \\n    class=\\"lesson-image\\" \\n    loading=\\"lazy\\" \\n    style=\\"max-height: 440px; object-fit: contain; border-radius: 8px; box-shadow: 0 4px 14px rgba(0,0,0,0.25);\\"\\n  />\\n</p>\\n\\n<div class=\\"table-responsive\\"><table>\\n<thead>\\n<tr>\\n<th>Interface Element</th>\\n<th>Visual Representation</th>\\n<th>Robotics Operational Purpose</th>\\n</tr>\\n</thead>\\n<tbody>\\n<tr>\\n<td><strong>Node Selection Tree (Left Panel)</strong></td>\\n<td>Hierarchical tree list with filter bar</td>\\n<td>Lists all active nodes in the ROS 2 graph. Clicking a node loads its parameter schema dynamically into the right panel.</td>\\n</tr>\\n<tr>\\n<td><strong>Numeric Range Sliders (Right Panel)</strong></td>\\n<td>Horizontal track with min/max labels</td>\\n<td>Automatically rendered when a parameter declaration includes a <code class=\\"inline-code\\">FloatingPointRange</code> or <code class=\\"inline-code\\">IntegerRange</code> descriptor. Enforces physical boundaries directly in the UI.</td>\\n</tr>\\n<tr>\\n<td><strong>Numeric Text Inputs</strong></td>\\n<td>Editable text box beside each slider</td>\\n<td>Allows precise typing of exact decimal values (e.g., <code class=\\"inline-code\\">0.75</code> m/s) when micro-adjustments are required.</td>\\n</tr>\\n<tr>\\n<td><strong>Boolean Checkboxes</strong></td>\\n<td>Interactive checkmark toggle</td>\\n<td>Instantly engages or disengages safety interlocks (such as <code class=\\"inline-code\\">enable_proximity_brake</code>) on the fly.</td>\\n</tr>\\n<tr>\\n<td><strong>Refresh Button</strong></td>\\n<td>Bottom-left button</td>\\n<td>Forces a discovery update over the DDS bus if new nodes have joined the robot network.</td>\\n</tr>\\n</tbody>\\n</table></div>\\n\\n<h3 id=\\"step-73-interactive-tuning-in-action\\">Step 7.3: Live Dynamic Tuning in Action</h3>\\n<p>When you drag a slider or edit a parameter field in the GUI, <code class=\\"inline-code\\">rqt_reconfigure</code> dispatches a parameter service call (<code class=\\"inline-code\\">/&lt;node_name&gt;/set_parameters</code>) over DDS:</p>\\n\\n<p class=\\"lesson-image-wrapper\\">\\n  <img \\n    src=\\"assets/images/rqt_reconfigure_param_update.png\\" \\n    alt=\\"rqt_reconfigure Live Dynamic Parameter Update\\" \\n    title=\\"Live parameter tuning in rqt_reconfigure: adjusting the slider updates the parameter value instantaneously and triggers the node's validation callback\\" \\n    class=\\"lesson-image\\" \\n    loading=\\"lazy\\" \\n    style=\\"max-height: 440px; object-fit: contain; border-radius: 8px; box-shadow: 0 4px 14px rgba(0,0,0,0.25);\\"\\n  />\\n</p>\\n\\n<p>Watch <strong>Terminal 1</strong> where your node is spinning. The moment you release the slider handle, the node logs the immediate parameter update:</p>\\n\\n<div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\">[INFO] [parameterized_controller]: Dynamically updated max_linear_speed to 1.20 m/s\\n[INFO] [parameterized_controller]: [Heartbeat] Fleet Unit: nexus-wh-01 | Safety Margin: 0.45 m | Active Rate: 20 Hz\\n</code></pre>\\n</div>\\n\\n<div class=\\"code-breakdown-card\\">\\n  <h4 class=\\"code-breakdown-title\\">🔬 Core Mechanism: How rqt_reconfigure Communicates Behind the Scenes</h4>\\n  <p class=\\"code-breakdown-intro\\">Understanding the DDS service interaction:</p>\\n  <ul class=\\"code-breakdown-list\\">\\n    <li class=\\"code-breakdown-item\\"><strong>Hidden Parameter Services:</strong> Every ROS 2 node automatically hosts hidden services: <code>/&lt;node_name&gt;/describe_parameters</code>, <code>/&lt;node_name&gt;/get_parameters</code>, and <code>/&lt;node_name&gt;/set_parameters</code>.</li>\\n    <li class=\\"code-breakdown-item\\"><strong>Descriptor Introspection:</strong> When you click the node on the left, <code>rqt_reconfigure</code> calls <code>describe_parameters</code> to learn parameter names, types, descriptions, and valid ranges.</li>\\n    <li class=\\"code-breakdown-item\\"><strong>Zero Restart Reconfiguration:</strong> Modifying any widget sends a <code>SetParameters</code> request. If your node has an <code>add_on_set_parameters_callback</code>, it validates the request and applies it in the very next control cycle without any process disruption!</li>\\n  </ul>\\n</div>\\n\\n<div class=\\"asset-handoff-card\\" style=\\"margin: 1.75rem 0 1rem 0; padding: 1.15rem 1.4rem; border-radius: 10px; background: rgba(16, 185, 129, 0.06); border: 1px solid rgba(16, 185, 129, 0.25); border-left: 4px solid #10b981;\\">\\n  <div style=\\"display: flex; align-items: center; gap: 0.5rem; margin-bottom: 0.5rem;\\">\\n    <span style=\\"font-size: 1.1rem;\\">📦</span>\\n    <strong style=\\"font-size: 0.95rem; color: #10b981; text-transform: uppercase; letter-spacing: 0.04em;\\">Asset Handoff &amp; Next Lesson Pipeline Bridge</strong>\\n  </div>\\n  <p style=\\"margin: 0 0 0.65rem 0; font-size: 0.88rem; color: var(--text-primary); line-height: 1.6;\\">\\n    You have mastered declaring dynamic parameters, validating bounds with <code class=\\"inline-code\\">SetParametersResult</code>, writing structured YAML parameter matrices, loading them via the CLI with <code class=\\"inline-code\\">--params-file</code>, and interactively tuning them in real time using <code class=\\"inline-code\\">rqt_reconfigure</code>.\\n  </p>\\n  <div style=\\"display: flex; flex-wrap: wrap; gap: 0.75rem; font-size: 0.82rem; font-family: var(--font-mono);\\">\\n    <span style=\\"background: var(--bg-surface); border: 1px solid var(--border-color); padding: 0.25rem 0.6rem; border-radius: 5px; color: var(--text-primary);\\">\\n      📁 <strong>Produced Artifact:</strong> <code>config/teleop_params.yaml</code> &amp; <code>nexus_amr_basics/param_node_explained.py</code>\\n    </span>\\n    <span style=\\"background: var(--bg-surface); border: 1px solid var(--border-color); padding: 0.25rem 0.6rem; border-radius: 5px; color: var(--text-primary);\\">\\n      ➡️ <strong>Ingested By:</strong> Bonus Lesson 18 (VS Code IDE Tooling &amp; ROS 2 Logging Framework)\\n    </span>\\n  </div>\\n</div>\\n","quizzes":[{"id":"q_l1_09_1","prompt":"Which method on rclpy.node.Node is used to register a parameter and define its default value?","options":["self.set_parameter('speed', 1.0)","self.declare_parameter('speed', 1.0)","self.register_param('speed', 1.0)","self.add_parameter('speed', 1.0)"],"correct":1,"explanation":"declare_parameter registers the parameter name, type descriptor, and default value with the node's parameter store, enabling external overrides via CLI, YAML, or GUI."},{"id":"q_l1_09_2","prompt":"What is the mandatory double-underscored sub-key required under each node name in a ROS 2 parameters YAML file?","options":["ros_parameters:","parameters:","ros__parameters:","node__parameters:"],"correct":2,"explanation":"In ROS 2 parameter YAML files, parameter declarations must sit under the 'ros__parameters:' key (with two underscores). Omitting the second underscore causes ROS 2 to silently ignore the parameter entries."},{"id":"q_l1_09_3","prompt":"In a ROS 2 Python package's setup.py, why must you include (os.path.join('share', package_name, 'config'), glob('config/*.yaml')) in the data_files list?","options":["To tell the Python compiler to compile YAML into C++ headers","To instruct colcon build to copy non-Python YAML configuration files into the install share directory where launch files and runtime tools can locate them","Because ROS 2 nodes cannot read files formatted in YAML without a license key","To automatically convert all YAML strings into ROS 2 topic messages"],"correct":1,"explanation":"By default, setuptools only installs Python source code. Declaring config/*.yaml in data_files ensures colcon build copies parameter configuration files into install/<pkg>/share/<pkg>/config/ where get_package_share_directory and launch files look for them."}],"has_quiz":true,"next_id":"lesson_17","prev_id":"lesson_15","subtopics":[{"id":"1-overview-learning-objectives","title":"1. Overview &amp; Learning Objectives"},{"id":"2-ros-1-vs-ros-2-parameter-architecture","title":"2. ROS 1 vs. ROS 2 Parameter Architecture"},{"id":"3-building-a-parameterized-node-python---step-by-step","title":"3. Building a Parameterized Node (Python) - Step-by-Step"},{"id":"4-parameter-descriptors-dynamic-validation-robotics-safety","title":"4. Parameter Descriptors &amp; Dynamic Validation (Robotics Safety)"},{"id":"5-organizing-configuration-with-yaml-files-cli-loading","title":"5. Organizing Configuration with YAML Files &amp; CLI Parameter Loading"},{"id":"6-parameter-inspection-with-the-cli","title":"6. Parameter Inspection with the CLI"},{"id":"7-dynamic-parameter-tuning-with-rqt-reconfigure","title":"7. Real-Time Dynamic Parameter Tuning with rqt_reconfigure"}]},{"id":"lesson_17","num":17,"num_str":"17","title":"VS Code IDE Tooling & ROS 2 Logging Framework","slug":"vscode_debugging_and_ros2_logging","filename":"06_vscode_debugging_and_ros2_logging.md","module":"Bonus: Advanced Masterclasses & Electives","module_id":4,"duration":"45-60 min","focus":"Productivity Configuration (\`tasks.json\`, \`settings.json\`) & Industrial Logging","snapshot":[["Hierarchical Severity Levels","DEBUG -> INFO -> WARN -> ERROR -> FATAL allows selective filtering of operational logs without recompiling code."],["Throttled & Once Loggers","get_logger().info_throttle(2.0, ...) and info_once(...) prevent flooding terminal logs with high-frequency sensor loops."],["Runtime Level Reconfiguration","ros2 param set /node_name logger_level debug dynamically adjusts verbosity on live production robots."],["VS Code IDE Integration","Launch configurations (.vscode/launch.json) enable interactive breakpoints, variable inspection, and call stack tracing."]],"html_content":"<h2 id=\\"1-overview-learning-objectives\\">1. Overview &amp; Learning Objectives</h2>\\n<p>Writing robust robotics software requires fast feedback loops: one-key compilation, IntelliSense autocompletion for ROS message types, and contextual logging that doesn't spam your terminal.</p>\\n<p><div class=\\"learning-objectives-card\\">\\n  <div class=\\"learning-objectives-header\\">\\n    <div class=\\"objectives-icon-badge\\">\\n      <span style=\\"font-size: 1.15rem; line-height: 1;\\">🎯</span>\\n    </div>\\n    <div class=\\"objectives-title-group\\">\\n      <h3 class=\\"objectives-main-title\\">Learning Objectives &amp; Core Outcomes</h3>\\n      <span class=\\"objectives-subtitle\\">By the end of this lesson, you will be able to:</span>\\n    </div>\\n    <span class=\\"objectives-count-badge\\">5 CORE OUTCOMES</span>\\n  </div>\\n  <ul class=\\"learning-objectives-list\\">\\n    <li class=\\"learning-objective-item\\">\\n      <span class=\\"objective-num-badge\\">1</span>\\n      <span class=\\"objective-text\\">Configure VS Code with <code class=\\"inline-code\\">.vscode/tasks.json</code> to trigger <code class=\\"inline-code\\">colcon build</code> with <code class=\\"inline-code\\">Ctrl + Shift + B</code>.</span>\\n    </li>\\n    <li class=\\"learning-objective-item\\">\\n      <span class=\\"objective-num-badge\\">2</span>\\n      <span class=\\"objective-text\\">Configure <code class=\\"inline-code\\">.vscode/settings.json</code> so Python language servers resolve ROS 2 packages (<code class=\\"inline-code\\">rclpy</code>, <code class=\\"inline-code\\">geometry_msgs</code>).</span>\\n    </li>\\n    <li class=\\"learning-objective-item\\">\\n      <span class=\\"objective-num-badge\\">3</span>\\n      <span class=\\"objective-text\\">Master the ROS 2 Logging Framework: understand why standard <code class=\\"inline-code\\">print()</code> is forbidden in production robotics.</span>\\n    </li>\\n    <li class=\\"learning-objective-item\\">\\n      <span class=\\"objective-num-badge\\">4</span>\\n      <span class=\\"objective-text\\">Use all five logging severity levels: <code class=\\"inline-code\\">DEBUG</code>, <code class=\\"inline-code\\">INFO</code>, <code class=\\"inline-code\\">WARN</code>, <code class=\\"inline-code\\">ERROR</code>, and <code class=\\"inline-code\\">FATAL</code>.</span>\\n    </li>\\n    <li class=\\"learning-objective-item\\">\\n      <span class=\\"objective-num-badge\\">5</span>\\n      <span class=\\"objective-text\\">Implement throttled logging (<code class=\\"inline-code\\">throttle_duration_sec</code>) and one-shot logging to avoid CPU and terminal bloat.</span>\\n    </li>\\n  </ul>\\n</div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"2-vs-code-ide-configuration-for-ros-2-python\\">2. VS Code IDE Configuration for ROS 2 Python</h2>\\n<p>To enable code autocompletion, real-time syntax checking, and one-click build automation in VS Code, we configure configuration files inside the <code class=\\"inline-code\\">.vscode/</code> directory. In our container workstation, VS Code opens the user home directory (<code class=\\"inline-code\\">/home/student</code>) by default so you can inspect both your active development workspace (<code class=\\"inline-code\\">~/ros2_ws</code>) and reference code (<code class=\\"inline-code\\">~/ros2_ws_reference</code>) simultaneously.</p>\\n\\n<div class=\\"alert-callout alert-info\\" style=\\"margin: 1.25rem 0;\\">\\n  <div class=\\"alert-icon\\">💡</div>\\n  <div class=\\"alert-body\\">\\n    <strong>Understanding the VS Code Workspace Root:</strong><br>\\n    When VS Code is launched with <code class=\\"inline-code\\">/home/student</code> as its folder, the internal variable <code class=\\"inline-code\\">\${workspaceFolder}</code> evaluates to <code class=\\"inline-code\\">/home/student</code>. Therefore, VS Code reads its task and setting configurations from <code class=\\"inline-code\\">/home/student/.vscode/</code>. Both <code class=\\"inline-code\\">settings.json</code> and <code class=\\"inline-code\\">tasks.json</code> explicitly point to your ROS 2 workspace at <code class=\\"inline-code\\">~/ros2_ws</code>.\\n  </div>\\n</div>\\n\\n<h3 id=\\"21-workspace-settings-vscodesettingsjson\\">2.1 Workspace Settings (<code class=\\"inline-code\\">.vscode/settings.json</code>)</h3>\\n<p>This configuration informs the Python Language Server (Pylance/Pyright) where to discover compiled ROS 2 Jazzy Python modules and your newly built <code class=\\"inline-code\\">nexus_amr_basics</code> package, preventing false-positive <code class=\\"inline-code\\">Import &quot;rclpy&quot; could not be resolved</code> warnings:</p>\\n<div class=\\"code-container\\" data-language=\\"json\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">json</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-json\\">{\\n  &quot;python.defaultInterpreterPath&quot;: &quot;/usr/bin/python3&quot;,\\n  &quot;python.autoComplete.extraPaths&quot;: [\\n    &quot;/opt/ros/jazzy/lib/python3.12/site-packages&quot;,\\n    &quot;\${workspaceFolder}/ros2_ws/install/nexus_amr_basics/lib/python3.12/site-packages&quot;\\n  ],\\n  &quot;python.analysis.extraPaths&quot;: [\\n    &quot;/opt/ros/jazzy/lib/python3.12/site-packages&quot;,\\n    &quot;\${workspaceFolder}/ros2_ws/install/nexus_amr_basics/lib/python3.12/site-packages&quot;\\n  ],\\n  &quot;python.analysis.autoSearchPaths&quot;: true,\\n  &quot;python.analysis.diagnosticMode&quot;: &quot;openFilesOnly&quot;\\n}\\n</code></pre>\\n</div>\\n\\n<h3 id=\\"22-colcon-build-tasks-vscodetasksjson\\">2.2 Colcon Build Tasks (<code class=\\"inline-code\\">.vscode/tasks.json</code>)</h3>\\n<p>VS Code build tasks allow you to trigger compilation instantly using the keyboard shortcut <code class=\\"inline-code\\">Ctrl + Shift + B</code> or via the top menu (<strong>Terminal &rarr; Run Build Task...</strong>):</p>\\n<div class=\\"code-container\\" data-language=\\"json\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">json</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-json\\">{\\n  &quot;version&quot;: &quot;2.0.0&quot;,\\n  &quot;tasks&quot;: [\\n    {\\n      &quot;label&quot;: &quot;colcon: build (symlink-install)&quot;,\\n      &quot;type&quot;: &quot;shell&quot;,\\n      &quot;command&quot;: &quot;cd ~/ros2_ws &amp;&amp; colcon build --symlink-install&quot;,\\n      &quot;group&quot;: {\\n        &quot;kind&quot;: &quot;build&quot;,\\n        &quot;isDefault&quot;: true\\n      },\\n      &quot;problemMatcher&quot;: [],\\n      &quot;presentation&quot;: {\\n        &quot;echo&quot;: true,\\n        &quot;reveal&quot;: &quot;always&quot;,\\n        &quot;focus&quot;: false,\\n        &quot;panel&quot;: &quot;shared&quot;\\n      }\\n    },\\n    {\\n      &quot;label&quot;: &quot;colcon: build selected package&quot;,\\n      &quot;type&quot;: &quot;shell&quot;,\\n      &quot;command&quot;: &quot;cd ~/ros2_ws &amp;&amp; colcon build --symlink-install --packages-select \${input:packageName}&quot;,\\n      &quot;problemMatcher&quot;: [],\\n      &quot;presentation&quot;: {\\n        &quot;echo&quot;: true,\\n        &quot;reveal&quot;: &quot;always&quot;,\\n        &quot;focus&quot;: false,\\n        &quot;panel&quot;: &quot;shared&quot;\\n      }\\n    },\\n    {\\n      &quot;label&quot;: &quot;colcon: clean build artifacts&quot;,\\n      &quot;type&quot;: &quot;shell&quot;,\\n      &quot;command&quot;: &quot;cd ~/ros2_ws &amp;&amp; rm -rf build install log&quot;,\\n      &quot;problemMatcher&quot;: []\\n    }\\n  ],\\n  &quot;inputs&quot;: [\\n    {\\n      &quot;id&quot;: &quot;packageName&quot;,\\n      &quot;type&quot;: &quot;promptString&quot;,\\n      &quot;description&quot;: &quot;Enter ROS 2 package name to build (e.g. nexus_amr_basics):&quot;,\\n      &quot;default&quot;: &quot;nexus_amr_basics&quot;\\n    }\\n  ]\\n}\\n</code></pre>\\n</div>\\n\\n<div class=\\"alert-callout alert-warning\\" style=\\"margin: 1.5rem 0;\\">\\n  <div class=\\"alert-icon\\">⚠️</div>\\n  <div class=\\"alert-body\\">\\n    <strong>Architectural Safeguard: Why <code>cd ~/ros2_ws &amp;&amp;</code> is Essential:</strong><br>\\n    Notice how each task command begins with <code class=\\"inline-code\\">cd ~/ros2_ws &amp;&amp;</code>. This prevents a critical workspace corruption issue:<br><br>\\n    <ul style=\\"margin: 0.5rem 0 0 1.25rem; line-height: 1.6;\\">\\n      <li><strong>The Root Cause:</strong> When VS Code opens your user environment (<code class=\\"inline-code\\">/home/student</code>), the variable <code class=\\"inline-code\\">\${workspaceFolder}</code> points to <code class=\\"inline-code\\">/home/student</code>.</li>\\n      <li><strong>The Risk of a Bare Command:</strong> If you run a plain <code class=\\"inline-code\\">colcon build --symlink-install</code> without specifying the directory, <code class=\\"inline-code\\">colcon</code> treats the entire user home folder as a workspace. It creates stray <code class=\\"inline-code\\">~/build</code>, <code class=\\"inline-code\\">~/install</code>, and <code class=\\"inline-code\\">~/log</code> directories directly inside <code class=\\"inline-code\\">/home/student</code>, and crashes with a <em>Duplicate package names</em> conflict (because it crawls both <code class=\\"inline-code\\">ros2_ws</code> and <code class=\\"inline-code\\">ros2_ws_reference</code>).</li>\\n      <li><strong>The Guarantee:</strong> Prefixing the command with <code class=\\"inline-code\\">cd ~/ros2_ws &amp;&amp;</code> guarantees that build and clean tasks always execute strictly inside the genuine ROS 2 workspace root (<code class=\\"inline-code\\">/home/student/ros2_ws</code>), regardless of what file or folder is currently focused in VS Code.</li>\\n    </ul>\\n  </div>\\n</div>\\n\\n<div class=\\"code-breakdown-card\\" style=\\"margin: 1.5rem 0;\\">\\n  <h4 class=\\"code-breakdown-title\\">⚙️ Task Execution Workflow</h4>\\n  <p class=\\"code-breakdown-intro\\">How to leverage these automated tasks during development:</p>\\n  <ul class=\\"code-breakdown-list\\">\\n    <li class=\\"code-breakdown-item\\"><strong>One-Key Full Build:</strong> Press <code class=\\"inline-code\\">Ctrl + Shift + B</code>. It runs the default build task, compiling all packages in <code class=\\"inline-code\\">~/ros2_ws</code> with symlinked Python scripts.</li>\\n    <li class=\\"code-breakdown-item\\"><strong>Targeted Package Build:</strong> Open the Command Palette (<code class=\\"inline-code\\">Ctrl + Shift + P</code>), type <strong>Tasks: Run Task</strong>, and choose <strong>colcon: build selected package</strong>. A prompt appears allowing you to type the package name (<code class=\\"inline-code\\">nexus_amr_basics</code>) to save build time.</li>\\n    <li class=\\"code-breakdown-item\\"><strong>Clean Workspace:</strong> When cleaning corrupt build caches or doing a fresh recompile, run <strong>Tasks: Run Task &rarr; colcon: clean build artifacts</strong>. It cleanly wipes <code class=\\"inline-code\\">build/</code>, <code class=\\"inline-code\\">install/</code>, and <code class=\\"inline-code\\">log/</code> from <code class=\\"inline-code\\">~/ros2_ws</code> without touching your source code.</li>\\n  </ul>\\n</div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"3-the-ros-2-logging-framework\\">3. The ROS 2 Logging Framework</h2>\\n<h3 id=\\"31-why-print-is-forbidden-in-production\\">3.1 Why <code class=\\"inline-code\\">print()</code> is Forbidden in Production</h3>\\n<p>In Python scripts, developers often use <code class=\\"inline-code\\">print(&quot;Robot moving&quot;)</code>. In production robotics, this creates critical problems:</p>\\n<ol>\\n<li><strong>No Timestamp:</strong> You cannot tell when an event occurred during a post-mortem crash analysis.</li>\\n<li><strong>No Node Source:</strong> In a multi-node system with 50 nodes running, <code class=\\"inline-code\\">print()</code> outputs are mixed together with no way to identify which node printed what.</li>\\n<li><strong>No Centralized Aggregation:</strong> <code class=\\"inline-code\\">print()</code> writes to stdout. ROS 2 logger writes to the <code class=\\"inline-code\\">/rosout</code> topic, enabling remote telemetry dashboards and fleet servers to monitor errors across a factory floor.</li>\\n<li><strong>No Severity Filtering:</strong> You cannot disable high-frequency debug prints in production without modifying source code.</li>\\n</ol>\\n<hr class=\\"divider\\">\\n<h2 id=\\"4-the-five-logging-severity-levels\\">4. The Five Logging Severity Levels</h2>\\n<div id=\\"log-levels-circle-root\\" style=\\"margin: 1.75rem 0;\\"></div>\\n\\n<p><div class=\\"code-container\\" data-language=\\"text\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">text</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-text\\">                     LOGGING SEVERITY HIERARCHY\\n                     \\n   [DEBUG]  --&gt; Granular diagnostic data (raw sensor values, loop ticks)\\n      |\\n   [INFO]   --&gt; Normal operational state changes (arrived at waypoint)\\n      |\\n   [WARN]   --&gt; Recoverable anomalies (battery &lt; 20%, low WiFi signal)\\n      |\\n   [ERROR]  --&gt; Component failures (laser sensor timeout, planner abort)\\n      |\\n   [FATAL]  --&gt; Critical emergency (hardware estop triggered, motor burned)\\n</code></pre>\\n</div>\\n</p>\\n<h3 id=\\"41-python-implementation-example\\">4.1 Python Implementation Example</h3>\\n\\n<div class=\\"alert alert-info alert-briefing\\">\\n  <div class=\\"alert-icon\\">📝</div>\\n  <div class=\\"alert-content\\">\\n    <div class=\\"alert-title\\">Robotics Flight Operations Mission Briefing: Autonomous Fleet Diagnostic Logger &amp; Throttling Governor</div>\\n    <div class=\\"alert-body\\">\\n      <strong>Physical AMR Context &amp; Operational Challenge:</strong><br>\\n      An industrial AMR executes internal control loops at 50 Hz to 100 Hz. If a node outputs logging strings on every cycle, it floods the terminal, consumes massive CPU cycles serializing strings, and fills the onboard SSD with gigabytes of redundant log files within hours.\\n      <br><br>\\n      <strong>Architectural Role &amp; Why This Mechanism:</strong><br>\\n      ROS 2 provides an integrated logging framework via <code>rclpy.impl.rcutils_logger</code> with 5 standard severity levels (DEBUG, INFO, WARN, ERROR, FATAL) and built-in rate filters: <code>throttle_duration_sec</code> and <code>once=True</code>. This enables mission telemetry to remain informative without saturating CPU or disk I/O.\\n      <br><br>\\n      <strong>Flight Objective &amp; Behavioral Outcome:</strong><br>\\n      Construct a diagnostic telemetry node that demonstrates all 5 severity levels, uses throttled logging to publish periodic battery health without spamming, and uses one-shot logging for hardware handshake events.\\n    </div>\\n  </div>\\n</div>\\n\\n<p><div class=\\"code-container\\" data-language=\\"python\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">python</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-python\\">#!/usr/bin/env python3\\nimport rclpy\\nfrom rclpy.node import Node\\n\\n\\nclass LoggingMasteryNode(Node):\\n\\n    def __init__(self):\\n        super().__init__(&#x27;logging_mastery_node&#x27;)\\n\\n        # 1. Standard Info Log\\n        self.get_logger().info(&#x27;Nexus AMR Diagnostic System Initialized.&#x27;)\\n\\n        # 2. Debug Log (Visible only if log level is set to DEBUG)\\n        raw_encoder_ticks = 4096\\n        self.get_logger().debug(f&#x27;Encoder calibration register: 0x{raw_encoder_ticks:04X}&#x27;)\\n\\n        # 3. Warning Log (Colorized Yellow in terminal)\\n        battery_pct = 18.5\\n        if battery_pct &lt; 20.0:\\n            self.get_logger().warn(f&#x27;Battery level low: {battery_pct:.1f}% remaining!&#x27;)\\n\\n        # 4. Error Log (Colorized Red in terminal)\\n        sensor_connected = False\\n        if not sensor_connected:\\n            self.get_logger().error(&#x27;LiDAR communication timeout on /dev/ttyUSB0!&#x27;)\\n\\n        # 5. Fatal Log (Colorized Bold Red / Highlighted)\\n        emergency_circuit_broken = True\\n        if emergency_circuit_broken:\\n            self.get_logger().fatal(&#x27;HARDWARE SAFETY INTERLOCK BROKEN: SYSTEM HALTED!&#x27;)\\n\\n\\ndef main():\\n    rclpy.init()\\n    node = LoggingMasteryNode()\\n    rclpy.spin_once(node)\\n    node.destroy_node()\\n    rclpy.shutdown()\\n\\n\\nif __name__ == &#x27;__main__&#x27;:\\n    main()\\n</code></pre>\\n</div>\\n</p>\\n<hr class=\\"divider\\">\\n<h2 id=\\"5-throttled-one-shot-logging\\">5. Throttled &amp; One-Shot Logging</h2>\\n<p>High-frequency control loops (e.g. 50 Hz motor loops) should not print every iteration, as doing so floods terminal buffers and consumes significant CPU.</p>\\n<h3 id=\\"51-throttling-by-duration\\">5.1 Throttling by Duration:</h3>\\n<p><div class=\\"code-container\\" data-language=\\"python\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">python</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-python\\">def control_loop(self):\\n    # Logs at most once every 2.0 seconds, regardless of how often this loop runs!\\n    self.get_logger().info(\\n        f&#x27;Robot pose: x={self.x:.2f}, y={self.y:.2f}&#x27;,\\n        throttle_duration_sec=2.0\\n    )\\n</code></pre>\\n</div>\\n</p>\\n<h3 id=\\"52-one-shot-logging\\">5.2 One-Shot Logging:</h3>\\n<p><div class=\\"code-container\\" data-language=\\"python\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">python</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-python\\">def on_network_connect(self):\\n    # Prints exactly once during the entire lifetime of the node\\n    self.get_logger().info(&#x27;DDS discovery handshake completed with Fleet Server.&#x27;, once=True)\\n</code></pre>\\n</div>\\n</p>\\n<hr class=\\"divider\\">\\n<h2 id=\\"6-runtime-log-level-configuration\\">6. Runtime Log Level Configuration</h2>\\n<p>You can change the logging verbosity level of any node from the command line without recompiling code:</p>\\n<p><div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\"># Launch node with DEBUG messages enabled:\\nros2 run nexus_amr_basics logger_levels --ros-args --log-level debug\\n\\n# Launch node displaying only WARNINGS and higher (suppressing INFO):\\nros2 run nexus_amr_basics logger_levels --ros-args --log-level warn\\n</code></pre>\\n</div>\\n</p>\\n<hr class=\\"divider\\">\\n<h2 id=\\"7-hands-on-student-challenge\\">7. Hands-on Student Challenge: AMR Battery State Logging & Diagnostic Threshold Supervisor</h2>\\n<p>Develop an industrial battery logging node that monitors power drain and demonstrates rate-throttled heartbeat reporting, low-battery warnings, and critical one-shot error handling.</p>\\n\\n<div class=\\"alert alert-tip\\">\\n  <div class=\\"alert-title\\">🎯 Mission Requirements</div>\\n  <ol>\\n    <li><strong>TODO 1:</strong> Implement an INFO heartbeat message throttled to once every 1.5 seconds when battery &gt; 20%.</li>\\n    <li><strong>TODO 2:</strong> Issue a WARN message throttled to once every 2.0 seconds when battery drops &le; 20%.</li>\\n    <li><strong>TODO 3:</strong> Issue an ERROR message once (once=True) when battery drops &le; 10% alerting of autonomous abort.</li>\\n    <li><strong>TODO 4:</strong> Issue a FATAL message when battery reaches 0%, cancel the timer, and shut down cleanly.</li>\\n  </ol>\\n</div>\\n\\n<h3 id=\\"71-starter-template\\">7.1 Starter Template: <code class=\\"inline-code\\">m04_l18_task_battery_monitor_logger.py</code></h3>\\n<p>Copy the starter template from the reference workspace into your active student workspace:</p>\\n<div class=\\"code-container\\" data-language=\\"bash\\">\\n  <div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n  <pre><code class=\\"language-bash\\">cp ~/ros2_ws_reference/src/nexus_amr_basics/nexus_amr_basics/m04_l18_task_battery_monitor_logger.py ~/ros2_ws/src/nexus_amr_basics/nexus_amr_basics/</code></pre>\\n</div>\\n<p>Open the copied file in your editor and complete the marked <code class=\\"inline-code\\">TODO</code> targets:</p>\\n\\n<div class=\\"code-container\\" data-language=\\"python\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">python</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-python\\">#!/usr/bin/env python3\\n&quot;&quot;&quot;\\n================================================================================\\nNexus AMR Learning Hub - Level 1: Module 4 (Bonus) / Lesson 18\\nPackage: nexus_amr_basics\\nNode:    TaskBatteryMonitorLogger (task_battery_logger)\\n================================================================================\\n\\nSTUDENT CHALLENGE SPECIFICATION:\\n--------------------------------\\nYou are developing the onboard power telemetry supervisor for an Autonomous\\nMobile Robot (AMR). The node runs a 10 Hz control loop (dt = 0.1s).\\nThe battery percentage begins at 100.0% and discharges by 0.25% per tick.\\n\\nYOUR OBJECTIVES (Look for TODO markers below):\\n---------------------------------------------\\n1. TODO 1: Implement an INFO heartbeat message throttled to once every 1.5 seconds\\n           when the battery is healthy (&gt; 20.0%).\\n2. TODO 2: When battery drops &lt;= 20.0%, issue a WARN message throttled to once\\n           every 2.0 seconds alerting of low power.\\n3. TODO 3: When battery drops &lt;= 10.0%, issue an ERROR message ONCE (once=True)\\n           commanding an immediate autonomous abort &amp; reroute to home base station.\\n4. TODO 4: When battery reaches 0.0%, issue a FATAL message, cancel the timer,\\n           and shut down the node.\\n\\nHOW TO RUN YOUR CODE:\\n---------------------\\nros2 run nexus_amr_basics task_battery_logger\\n\\nTESTING WITH LOG LEVELS:\\n------------------------\\n# Normal run:\\nros2 run nexus_amr_basics task_battery_logger\\n\\n# Suppress INFO (watch only warnings, errors, and fatal):\\nros2 run nexus_amr_basics task_battery_logger --ros-args --log-level warn\\n================================================================================\\n&quot;&quot;&quot;\\n\\nimport rclpy\\nfrom rclpy.node import Node\\n\\n\\nclass BatteryMonitorLogger(Node):\\n    &quot;&quot;&quot;\\n    Supervises robot battery state and demonstrates severity filtering &amp; throttling.\\n    &quot;&quot;&quot;\\n\\n    def __init__(self):\\n        super().__init__(&#x27;battery_monitor_logger&#x27;)\\n\\n        self.battery_pct = 100.0   # Initial state of charge (100%)\\n        self.discharge_rate = 0.5   # 0.5% discharge per loop tick for simulation speed\\n\\n        # 10 Hz timer (dt = 0.1s)\\n        self.timer_period = 0.1\\n        self.timer = self.create_timer(self.timer_period, self.monitor_callback)\\n\\n        self.get_logger().info(&#x27;BatteryMonitorLogger supervisor initialized at 10 Hz.&#x27;)\\n\\n    def monitor_callback(self):\\n        # Simulate discharge\\n        self.battery_pct = max(0.0, self.battery_pct - self.discharge_rate)\\n\\n        # ======================================================================\\n        # TODO 1: Log an INFO heartbeat message showing the current battery %\\n        # - Condition: battery_pct &gt; 20.0\\n        # - Must use: throttle_duration_sec=1.5 so it does NOT flood the console!\\n        # ======================================================================\\n        # Hint: Check battery_pct &gt; 20.0 and emit an info log using self.get_logger().info() with throttle_duration_sec=1.5 to rate-limit console output.\\n        # ---&gt; YOUR CODE HERE &lt;---\\n\\n        # ======================================================================\\n        # TODO 2: Log a WARN message when battery is low\\n        # - Condition: 10.0 &lt; battery_pct &lt;= 20.0\\n        # - Must use: throttle_duration_sec=2.0\\n        # ======================================================================\\n        # Hint: Check the battery range (10.0 &lt; battery_pct &lt;= 20.0) and log a warning via self.get_logger().warn() with throttle_duration_sec=2.0.\\n        # ---&gt; YOUR CODE HERE &lt;---\\n\\n        # ======================================================================\\n        # TODO 3: Log an ERROR message ONCE when battery enters critical zone\\n        # - Condition: 0.0 &lt; battery_pct &lt;= 10.0\\n        # - Must use: once=True so it prints exactly once when threshold is crossed!\\n        # ======================================================================\\n        # Hint: Check the critical range (0.0 &lt; battery_pct &lt;= 10.0) and emit an error log via self.get_logger().error() setting once=True to trigger exactly once.\\n        # ---&gt; YOUR CODE HERE &lt;---\\n\\n        # ======================================================================\\n        # TODO 4: Log a FATAL message when battery is completely exhausted\\n        # - Condition: self.battery_pct &lt;= 0.0\\n        # - Log a fatal emergency message\\n        # - Cancel the timer: self.timer.cancel()\\n        # ======================================================================\\n        # Hint: Check battery_pct &lt;= 0.0, emit a fatal log with self.get_logger().fatal(), and stop the timer with self.timer.cancel().\\n        # ---&gt; YOUR CODE HERE &lt;---\\n\\n\\nfrom rclpy.executors import ExternalShutdownException\\n\\n\\ndef main(args=None):\\n    rclpy.init(args=args)\\n    node = BatteryMonitorLogger()\\n\\n    try:\\n        rclpy.spin(node)\\n    except (KeyboardInterrupt, ExternalShutdownException):\\n        pass\\n    finally:\\n        node.destroy_node()\\n        if rclpy.ok():\\n            rclpy.shutdown()\\n\\n\\nif __name__ == &#x27;__main__&#x27;:\\n    main()\\n</code></pre>\\n</div>\\n\\n<h3 id=\\"72-verification-steps--expected-terminal-output\\">7.2 Verification Steps &amp; Expected Terminal Output</h3>\\n<p>Copy the starter script into your student package, register in <code class=\\"inline-code\\">setup.py</code>, build, and test:</p>\\n\\n<ol class=\\"step-guide-list\\">\\n  <li><strong>Step 1: Copy Starter Script to Package:</strong>\\n    <div class=\\"code-container\\" data-language=\\"bash\\">\\n      <div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n      <pre><code class=\\"language-bash\\">cp ~/ros2_ws_reference/src/nexus_amr_basics/nexus_amr_basics/m04_l18_task_battery_monitor_logger.py ~/ros2_ws/src/nexus_amr_basics/nexus_amr_basics/</code></pre>\\n    </div>\\n  </li>\\n  <li><strong>Step 2: Register in setup.py:</strong>\\n    <p>In <code class=\\"inline-code\\">~/ros2_ws/src/nexus_amr_basics/setup.py</code>, append to <code class=\\"inline-code\\">'console_scripts'</code>:</p>\\n    <div class=\\"code-container\\" data-language=\\"python\\">\\n      <div class=\\"code-header\\"><span class=\\"code-lang-tag\\">python</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n      <pre><code class=\\"language-python\\">            'task_battery_logger = nexus_amr_basics.m04_l18_task_battery_monitor_logger:main',</code></pre>\\n    </div>\\n  </li>\\n  <li><strong>Step 3: Build &amp; Source:</strong>\\n    <div class=\\"code-container\\" data-language=\\"bash\\">\\n      <div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n      <pre><code class=\\"language-bash\\">cd ~/ros2_ws\\ncolcon build --symlink-install --packages-select nexus_amr_basics\\nsource install/setup.bash</code></pre>\\n    </div>\\n  </li>\\n  <li><strong>Step 4: Execute &amp; Verify Logging Thresholds:</strong>\\n    <div class=\\"code-container\\" data-language=\\"bash\\">\\n      <div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n      <pre><code class=\\"language-bash\\"># Run with all levels visible:\\nros2 run nexus_amr_basics task_battery_logger\\n\\n# Run filtering out INFO logs (watch only WARN, ERROR, FATAL):\\nros2 run nexus_amr_basics task_battery_logger --ros-args --log-level warn</code></pre>\\n    </div>\\n  </li>\\n</ol>\\n  </li>\\n</ol>\\n\\n<p><em>Expected Terminal Output:</em></p>\\n<div class=\\"code-container\\" data-language=\\"text\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">text</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-text\\">[INFO] [battery_monitor_logger]: BatteryMonitorLogger initialized at 10 Hz. Battery at 100.0%.\\n[INFO] [battery_monitor_logger]: [BATTERY NOMINAL] Current charge: 96.2% | Discharge rate: 2.5%/s\\n[INFO] [battery_monitor_logger]: [BATTERY NOMINAL] Current charge: 92.5% | Discharge rate: 2.5%/s\\n[WARN] [battery_monitor_logger]: [LOW POWER ALERT] Battery level critical: 19.8%! Consider navigating to home base station.\\n[ERROR] [battery_monitor_logger]: [AUTONOMOUS ABORT] Battery under 10.0% (9.8%)! Mission aborted. Rerouting to home station.\\n[FATAL] [battery_monitor_logger]: [HARDWARE SHUTDOWN] Battery completely exhausted (0.0%). Halting node now.</code></pre>\\n</div>\\n\\n<details class=\\"reference-solution-dropdown\\">\\n  <summary class=\\"solution-summary-btn\\">\\n    <span>🔍 View Reference Solution (<code class=\\"inline-code\\">m04_l18_solution_battery_monitor_logger.py</code>)</span>\\n  </summary>\\n  <div class=\\"solution-body\\">\\n    <p>Reference file: <code class=\\"inline-code\\">ros2_ws_reference/src/nexus_amr_basics/nexus_amr_basics/m04_l18_solution_battery_monitor_logger.py</code></p>\\n    <div class=\\"code-container\\" data-language=\\"python\\">\\n      <div class=\\"code-header\\"><span class=\\"code-lang-tag\\">python</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n      <pre><code class=\\"language-python\\">#!/usr/bin/env python3\\n&quot;&quot;&quot;\\n================================================================================\\nNexus AMR Learning Hub - Level 1: Module 4 (Bonus) / Lesson 18\\nPackage: nexus_amr_basics\\nNode:    SolutionBatteryMonitorLogger (solution_battery_logger)\\n================================================================================\\n\\nWHAT THIS SOLUTION DEMONSTRATES:\\n--------------------------------\\n1. Clean industrial logging hierarchy across multiple severity levels.\\n2. Throttled logging (throttle_duration_sec=1.5 and 2.0) preventing console flooding\\n   inside a fast 10 Hz timer loop.\\n3. One-shot logging (once=True) for critical threshold alerts without spam.\\n4. Clean termination on FATAL hardware shutdown events.\\n\\nHOW TO RUN:\\n-----------\\n# Run with all levels visible:\\nros2 run nexus_amr_basics solution_battery_logger\\n\\n# Run filtering out INFO logs (watch only WARN, ERROR, FATAL):\\nros2 run nexus_amr_basics solution_battery_logger --ros-args --log-level warn\\n================================================================================\\n&quot;&quot;&quot;\\n\\nimport rclpy\\nfrom rclpy.node import Node\\n\\n\\nclass BatteryMonitorLogger(Node):\\n    &quot;&quot;&quot;\\n    Supervises robot battery state and demonstrates severity filtering &amp; throttling.\\n    &quot;&quot;&quot;\\n\\n    def __init__(self):\\n        super().__init__(&#x27;battery_monitor_logger&#x27;)\\n\\n        self.battery_pct = 100.0   # Initial state of charge (100%)\\n        self.discharge_rate = 1.0   # 1.0% discharge per loop tick for clear visual progression\\n\\n        # 10 Hz timer (dt = 0.1s)\\n        self.timer_period = 0.1\\n        self.timer = self.create_timer(self.timer_period, self.monitor_callback)\\n\\n        self.get_logger().info(&#x27;BatteryMonitorLogger supervisor initialized at 10 Hz.&#x27;)\\n\\n    def monitor_callback(self):\\n        # Simulate discharge\\n        self.battery_pct = max(0.0, self.battery_pct - self.discharge_rate)\\n\\n        # 1. Healthy State (&gt; 20%): Throttled INFO heartbeat every 1.5 seconds\\n        if self.battery_pct &gt; 20.0:\\n            self.get_logger().info(\\n                f&#x27;Battery Status: {self.battery_pct:5.1f}% [HEALTHY] | Power draw: 4.2A&#x27;,\\n                throttle_duration_sec=1.5\\n            )\\n\\n        # 2. Low Battery Warning (10% &lt; pct &lt;= 20%): Throttled WARN every 2.0 seconds\\n        elif 10.0 &lt; self.battery_pct &lt;= 20.0:\\n            self.get_logger().warn(\\n                f&#x27;Battery Low: {self.battery_pct:5.1f}%! Rerouting to home base station.&#x27;,\\n                throttle_duration_sec=2.0\\n            )\\n\\n        # 3. Critical Battery Alert (0% &lt; pct &lt;= 10%): One-shot ERROR message\\n        elif 0.0 &lt; self.battery_pct &lt;= 10.0:\\n            self.get_logger().error(\\n                f&#x27;CRITICAL BATTERY: {self.battery_pct:5.1f}%! Aborting current mission immediately.&#x27;,\\n                once=True\\n            )\\n\\n        # 4. Depleted Battery (0%): FATAL emergency halt and shutdown\\n        else:\\n            self.get_logger().fatal(\\n                &#x27;BATTERY DEPLETED (0.0%): SYSTEM HARDWARE EMERGENCY HALT! Actuation disabled.&#x27;\\n            )\\n            self.timer.cancel()\\n\\n\\nfrom rclpy.executors import ExternalShutdownException\\n\\n\\ndef main(args=None):\\n    rclpy.init(args=args)\\n    node = BatteryMonitorLogger()\\n\\n    try:\\n        rclpy.spin(node)\\n    except (KeyboardInterrupt, ExternalShutdownException):\\n        pass\\n    finally:\\n        node.destroy_node()\\n        if rclpy.ok():\\n            rclpy.shutdown()\\n\\n\\nif __name__ == &#x27;__main__&#x27;:\\n    main()</code></pre>\\n    </div>\\n  </div>\\n</details>\\n\\n<div class=\\"alert-callout alert-tip\\" style=\\"margin: 1.75rem 0;\\">\\n  <div class=\\"alert-icon\\">🔍</div>\\n  <div class=\\"alert-body\\">\\n    <strong>Diagnostic Note: Dynamic Logger Level Reconfiguration:</strong><br>\\n    By default, ROS 2 suppresses <code class=\\"inline-code\\">DEBUG</code> messages to keep production terminals clean. When troubleshooting, you can unmask debug messages dynamically without restarting nodes:<br>\\n    <div class=\\"code-container\\" data-language=\\"bash\\" style=\\"margin: 0.5rem 0 0.3rem 0;\\">\\n      <div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n      <pre><code class=\\"language-bash\\"># Launch node with debug logging unmasked:\\nros2 run nexus_amr_basics battery_monitor --ros-args --log-level debug</code></pre>\\n    </div>\\n    Notice: Detailed sensor state calculations, register dumps, and tick intervals immediately appear in the console!\\n  </div>\\n</div>\\n\\n<div class=\\"code-breakdown-card\\">\\n  <h4 class=\\"code-breakdown-title\\">🔬 Core Code Deep Dive &amp; Operational Breakdown: BatteryMonitorLogger Solution Breakdown</h4>\\n  <p class=\\"code-breakdown-intro\\">Key takeaways from the Battery Monitor Logger implementation:</p>\\n  <ul class=\\"code-breakdown-list\\">\\n    <li class=\\"code-breakdown-item\\"><strong>Severity Escalation Architecture:</strong> The timer callback maps battery percentage to distinct severity tiers: >= 30% (INFO), 10%-30% (WARN), < 10% (ERROR / FATAL), matching industrial BMS safety guidelines.</li>\\n    <li class=\\"code-breakdown-item\\"><strong>Adaptive Rate Throttling:</strong> Nominal state-of-charge is throttled to every 2.0s, reducing telemetry bandwidth. Critical state breaches use unthrottled or high-frequency alerts to ensure immediate operator visibility.</li>\\n    <li class=\\"code-breakdown-item\\"><strong>Graceful Mission Abort:</strong> When critical thresholds are breached, the node sets <code>self.mission_aborted = True</code>, preventing further motion commands and signaling the fleet dispatcher to reroute the AMR to home base station.</li>\\n  </ul>\\n</div>\\n\\n<div class=\\"asset-handoff-card\\" style=\\"margin: 1.75rem 0 1rem 0; padding: 1.15rem 1.4rem; border-radius: 10px; background: rgba(16, 185, 129, 0.06); border: 1px solid rgba(16, 185, 129, 0.25); border-left: 4px solid #10b981;\\">\\n  <div style=\\"display: flex; align-items: center; gap: 0.5rem; margin-bottom: 0.5rem;\\">\\n    <span style=\\"font-size: 1.1rem;\\">📦</span>\\n    <strong style=\\"font-size: 0.95rem; color: #10b981; text-transform: uppercase; letter-spacing: 0.04em;\\">Asset Handoff &amp; Next Lesson Pipeline Bridge</strong>\\n  </div>\\n  <p style=\\"margin: 0 0 0.65rem 0; font-size: 0.88rem; color: var(--text-primary); line-height: 1.6;\\">\\n    You have configured industry-standard VS Code automation tasks and integrated structured rcutils logging levels (DEBUG, INFO, WARN, ERROR, FATAL) with throttled output filters for robot operations.\\n  </p>\\n  <div style=\\"display: flex; flex-wrap: wrap; gap: 0.75rem; font-size: 0.82rem; font-family: var(--font-mono);\\">\\n    <span style=\\"background: var(--bg-surface); border: 1px solid var(--border-color); padding: 0.25rem 0.6rem; border-radius: 5px; color: var(--text-primary);\\">\\n      📁 <strong>Produced Artifact:</strong> <code>.vscode/tasks.json</code>, <code>.vscode/settings.json</code> &amp; structured logger nodes\\n    </span>\\n    <span style=\\"background: var(--bg-surface); border: 1px solid var(--border-color); padding: 0.25rem 0.6rem; border-radius: 5px; color: var(--text-primary);\\">\\n      ➡️ <strong>Ingested By:</strong> Bonus Lesson 19 (ROS 2 Interfaces &amp; Custom Messages, Services &amp; Actions)\\n    </span>\\n  </div>\\n</div>\\n","quizzes":[{"id":"q_l1_06_1","prompt":"Which of the following represents the correct ascending order of ROS 2 logger severity levels?","options":["DEBUG < INFO < WARN < ERROR < FATAL","INFO < DEBUG < WARN < ERROR < FATAL","WARN < INFO < DEBUG < ERROR < CRITICAL","TRACE < NOTICE < ALERT < EMERGENCY"],"correct":0,"explanation":"ROS 2 logging follows standard POSIX severity: DEBUG (10), INFO (20), WARN (30), ERROR (40), and FATAL (50). Setting logger level to WARN filters out INFO and DEBUG."}],"has_quiz":true,"next_id":"lesson_18","prev_id":"lesson_16","subtopics":[{"id":"1-overview-learning-objectives","title":"1. Overview &amp; Learning Objectives"},{"id":"2-vs-code-ide-configuration-for-ros-2-python","title":"2. VS Code IDE Configuration for ROS 2 Python"},{"id":"3-the-ros-2-logging-framework","title":"3. The ROS 2 Logging Framework"},{"id":"4-the-five-logging-severity-levels","title":"4. The Five Logging Severity Levels"},{"id":"5-throttled-one-shot-logging","title":"5. Throttled &amp; One-Shot Logging"},{"id":"6-runtime-log-level-configuration","title":"6. Runtime Log Level Configuration"},{"id":"7-hands-on-student-challenge","title":"7. Hands-on Student Challenge: AMR Battery State Logging & Diagnostic Threshold Supervisor"}]},{"id":"lesson_18","num":18,"num_str":"18","title":"ROS 2 Interfaces & Custom Messages, Services & Actions (.msg, .srv, .action)","slug":"interfaces-and-custom-messages","filename":"11_interfaces_and_custom_messages.md","module":"Bonus: Advanced Masterclasses & Electives","module_id":4,"duration":"45-60 min","focus":"Custom Message Architecture, UltrasonicRange.msg IDL Definition, CMake Generators & Python Telemetry","snapshot":[["Strict IDL Contracts","Define custom fields in .msg, .srv, and .action files to enforce type safety across heterogeneous language nodes."],["CMake Interface Package","Pure interface packages use rosidl_default_generators and CMake to compile Python and C++ bindings simultaneously."],["Field Types & Constants","Supports primitives, variable-length arrays, nested headers, and fixed constant flags for deterministic serialization."],["Interface Introspection","ros2 interface show, list, and proto inspect compiled message layouts and generate shell templates instantly."]],"html_content":"<h2 id=\\"1-overview-learning-objectives\\">1. Overview &amp; Learning Objectives</h2>\\n<p>In ROS 2, nodes achieve language-agnostic interoperability because they communicate using strictly typed <strong>Interfaces</strong>. An interface defined once in an IDL (Interface Definition Language) file is automatically compiled into native Python classes and C++ structs.</p>\\n<p><div class=\\"learning-objectives-card\\">\\n  <div class=\\"learning-objectives-header\\">\\n    <div class=\\"objectives-icon-badge\\">\\n      <span style=\\"font-size: 1.15rem; line-height: 1;\\">🎯</span>\\n    </div>\\n    <div class=\\"objectives-title-group\\">\\n      <h3 class=\\"objectives-main-title\\">Learning Objectives &amp; Core Outcomes</h3>\\n      <span class=\\"objectives-subtitle\\">By the end of this lesson, you will be able to:</span>\\n    </div>\\n    <span class=\\"objectives-count-badge\\">5 CORE OUTCOMES</span>\\n  </div>\\n  <ul class=\\"learning-objectives-list\\">\\n    <li class=\\"learning-objective-item\\">\\n      <span class=\\"objective-num-badge\\">1</span>\\n      <span class=\\"objective-text\\">Understand the hierarchy of standard ROS 2 message libraries (<code class=\\"inline-code\\">std_msgs</code>, <code class=\\"inline-code\\">geometry_msgs</code>, <code class=\\"inline-code\\">sensor_msgs</code>, <code class=\\"inline-code\\">nav_msgs</code>).</span>\\n    </li>\\n    <li class=\\"learning-objective-item\\">\\n      <span class=\\"objective-num-badge\\">2</span>\\n      <span class=\\"objective-text\\">Learn the golden architectural rule: <strong>Why interface packages must use <code class=\\"inline-code\\">ament_cmake</code> even when consuming them in pure Python</strong>.</span>\\n    </li>\\n    <li class=\\"learning-objective-item\\">\\n      <span class=\\"objective-num-badge\\">3</span>\\n      <span class=\\"objective-text\\">Create custom message (<code class=\\"inline-code\\">.msg</code>), service (<code class=\\"inline-code\\">.srv</code>), and action (<code class=\\"inline-code\\">.action</code>) definitions.</span>\\n    </li>\\n    <li class=\\"learning-objective-item\\">\\n      <span class=\\"objective-num-badge\\">4</span>\\n      <span class=\\"objective-text\\">Configure <code class=\\"inline-code\\">CMakeLists.txt</code> with <code class=\\"inline-code\\">rosidl_generate_interfaces</code> and <code class=\\"inline-code\\">package.xml</code>.</span>\\n    </li>\\n    <li class=\\"learning-objective-item\\">\\n      <span class=\\"objective-num-badge\\">5</span>\\n      <span class=\\"objective-text\\">Import and instantiate custom interfaces in a production Python node.</span>\\n    </li>\\n  </ul>\\n</div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"2-standard-ros-2-interface-libraries\\">2. Standard ROS 2 Interface Libraries</h2>\\n<p>Before creating custom messages, always verify if a standardized ROS message already exists:</p>\\n<div class=\\"table-responsive\\"><table>\\n<thead>\\n<tr>\\n<th>Library</th>\\n<th>Key Interface Types</th>\\n<th>Primary Use Case</th>\\n</tr>\\n</thead>\\n<tbody>\\n<tr>\\n<td><strong><code class=\\"inline-code\\">std_msgs</code></strong></td>\\n<td><code class=\\"inline-code\\">Bool</code>, <code class=\\"inline-code\\">Float32</code>, <code class=\\"inline-code\\">Int32</code>, <code class=\\"inline-code\\">String</code>, <code class=\\"inline-code\\">Header</code></td>\\n<td>Primitive data types and timestamps.</td>\\n</tr>\\n<tr>\\n<td><strong><code class=\\"inline-code\\">geometry_msgs</code></strong></td>\\n<td><code class=\\"inline-code\\">Point</code>, <code class=\\"inline-code\\">Quaternion</code>, <code class=\\"inline-code\\">Pose</code>, <code class=\\"inline-code\\">PoseStamped</code>, <code class=\\"inline-code\\">Twist</code></td>\\n<td>2D/3D spatial coordinates, orientations, velocities.</td>\\n</tr>\\n<tr>\\n<td><strong><code class=\\"inline-code\\">sensor_msgs</code></strong></td>\\n<td><code class=\\"inline-code\\">LaserScan</code>, <code class=\\"inline-code\\">Image</code>, <code class=\\"inline-code\\">Imu</code>, <code class=\\"inline-code\\">BatteryState</code>, <code class=\\"inline-code\\">JointState</code></td>\\n<td>Raw sensor telemetry from cameras, LiDARs, IMUs.</td>\\n</tr>\\n<tr>\\n<td><strong><code class=\\"inline-code\\">nav_msgs</code></strong></td>\\n<td><code class=\\"inline-code\\">Odometry</code>, <code class=\\"inline-code\\">OccupancyGrid</code>, <code class=\\"inline-code\\">Path</code></td>\\n<td>SLAM 2D occupancy grid maps, robot odometry, paths.</td>\\n</tr>\\n</tbody>\\n</table></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"3-the-custom-interface-architecture-rule\\">3. The Custom Interface Architecture Rule</h2>\\n<div class=\\"alert-callout alert-important\\"><div class=\\"alert-icon\\"></div><div class=\\"alert-body\\"><strong>ROS 2 Custom Interfaces Must Be Built Using <code class=\\"inline-code\\">ament_cmake</code>:</strong><br><br>The ROS 2 IDL generator (<code class=\\"inline-code\\">rosidl</code>) compiles <code class=\\"inline-code\\">.msg</code> and <code class=\\"inline-code\\">.srv</code> files into C, C++, and Python bindings. The IDL generator plugins require CMake.<br><br>Therefore, industry best practice is to create a dedicated interface package (e.g., <code class=\\"inline-code\\">nexus_amr_interfaces</code>) built with <code class=\\"inline-code\\">ament_cmake</code>. Your Python packages (<code class=\\"inline-code\\">nexus_amr_basics</code>, <code class=\\"inline-code\\">nexus_amr_navigation</code>) simply add <code class=\\"inline-code\\">&lt;depend&gt;nexus_amr_interfaces&lt;/depend&gt;</code> to their <code class=\\"inline-code\\">package.xml</code> and import the generated classes cleanly.</div></div>\\n<p><img src=\\"assets/images/interface_idl_pipeline.svg\\" alt=\\"Interface IDL Pipeline\\" class=\\"lesson-image\\" loading=\\"lazy\\" /></p>\\n<hr class=\\"divider\\">\\n<h2 id=\\"4-creating-custom-ros-2-interfaces---step-by-step\\">4. Creating Custom Robot Interfaces: Defining UltrasonicRange.msg</h2>\\n<p>We build a dedicated CMake package (<code class=\\"inline-code\\">nexus_amr_interfaces</code>) containing custom message, service, and action definitions.</p>\\n<h3 id=\\"step-41-create-the-interface-package\\">Step 4.1: Create the Interface Package</h3>\\n<p><div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\">cd ~/ros2_ws/src\\nros2 pkg create --build-type ament_cmake nexus_amr_interfaces\\ncd nexus_amr_interfaces\\nmkdir -p msg srv action\\n</code></pre>\\n</div>\\n</p>\\n<h3 id=\\"step-42-define-custom-message-1-msgnummsg\\">Step 4.2: Define Custom Message 1: <code class=\\"inline-code\\">msg/UltrasonicRange.msg</code></h3>\\n<p>The simplest possible custom message contains a single primitive integer:</p>\\n<p><div class=\\"code-container\\" data-language=\\"text\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">text</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-text\\">std_msgs/Header header\\\\nfloat32 distance_m\\\\nfloat32 min_range_m\\\\nfloat32 max_range_m\\\\nbool obstacle_detected\\n</code></pre>\\n</div>\\n</p>\\n<h3 id=\\"step-43-define-custom-message-2-msgspheremsg-composed-message\\">Step 4.3: Define Custom Message 2: <code class=\\"inline-code\\">msg/Sphere.msg</code> (Composed Message)</h3>\\n<p>Interfaces can also import types from other ROS packages (e.g. <code class=\\"inline-code\\">geometry_msgs</code>):</p>\\n<p><div class=\\"code-container\\" data-language=\\"text\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">text</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-text\\">geometry_msgs/Point center\\nfloat64 radius\\n</code></pre>\\n</div>\\n</p>\\n<h3 id=\\"step-44-define-custom-service-srvaddthreeintssrv\\">Step 4.4: Define Custom Service: <code class=\\"inline-code\\">srv/AddThreeInts.srv</code></h3>\\n<p>In <code class=\\"inline-code\\">.srv</code> files, three dashes <code class=\\"inline-code\\">---</code> separate the <strong>Request</strong> from the <strong>Response</strong>:</p>\\n<p><div class=\\"code-container\\" data-language=\\"text\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">text</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-text\\">int64 a\\nint64 b\\nint64 c\\n---\\nint64 sum\\n</code></pre>\\n</div>\\n</p>\\n<h3 id=\\"step-45-define-custom-action-actionfibonacciaction\\">Step 4.5: Define Custom Action: <code class=\\"inline-code\\">action/Fibonacci.action</code></h3>\\n<p>In <code class=\\"inline-code\\">.action</code> files, three dashes <code class=\\"inline-code\\">---</code> separate <strong>Goal</strong>, <strong>Result</strong>, and <strong>Feedback</strong>:</p>\\n<p><div class=\\"code-container\\" data-language=\\"text\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">text</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-text\\">int32 order\\n---\\nint32[] sequence\\n---\\nint32[] partial_sequence\\n</code></pre>\\n</div>\\n</p>\\n<hr class=\\"divider\\">\\n<h2 id=\\"5-configuring-packagexml-cmakeliststxt\\">5. Configuring <code class=\\"inline-code\\">package.xml</code> &amp; <code class=\\"inline-code\\">CMakeLists.txt</code></h2>\\n<h3 id=\\"51-packagexml-configuration\\">5.1 Configuring <code class=\\"inline-code\\">package.xml</code> for IDL Generation</h3>\\n<p>In interface packages, four specific tags instruct ROS 2 to invoke IDL code generators and register the package in the Ament Index:</p>\\n<div class=\\"file-edit-instruction-card\\">\\n  <div class=\\"file-edit-header\\">\\n    <div class=\\"file-edit-header-left\\">\\n      <span>📝 Step-by-Step File Modification Guide</span>\\n    </div>\\n    <span class=\\"file-edit-badge\\">~/ros2_ws/src/nexus_amr_interfaces/package.xml</span>\\n  </div>\\n  <div class=\\"file-edit-body\\">\\n    <div class=\\"file-edit-step\\">\\n      <div class=\\"file-edit-step-title\\">\\n        <span class=\\"step-num-pill\\">Step 1</span>\\n        <span>Open the Target File</span>\\n      </div>\\n      <p class=\\"step-description\\">Open <code class=\\"inline-code\\">~/ros2_ws/src/nexus_amr_interfaces/package.xml</code> in your editor.</p>\\n    </div>\\n\\n    <div class=\\"file-edit-step\\">\\n      <div class=\\"file-edit-step-title\\">\\n        <span class=\\"step-num-pill\\">Step 2</span>\\n        <span>Locate Insertion Point &amp; Add Lines</span>\\n      </div>\\n      <p class=\\"step-description\\">Inside the root <code class=\\"inline-code\\">&lt;package format=\\"3\\"&gt;</code> block, directly below <code class=\\"inline-code\\">&lt;buildtool_depend&gt;ament_cmake&lt;/buildtool_depend&gt;</code>, add the IDL generator tags:</p>\\n      <div class=\\"code-container\\" data-language=\\"xml\\">\\n        <div class=\\"code-header\\"><span class=\\"code-lang-tag\\">xml</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n        <pre><code class=\\"language-xml\\">&lt;!-- &gt;&gt;&gt; ADD THESE 4 IDL CODE GENERATION TAGS &lt;&lt;&lt; --&gt;\\n  &lt;buildtool_depend&gt;rosidl_default_generators&lt;/buildtool_depend&gt;\\n  &lt;depend&gt;geometry_msgs&lt;/depend&gt;\\n  &lt;exec_depend&gt;rosidl_default_runtime&lt;/exec_depend&gt;\\n  &lt;member_of_group&gt;rosidl_interface_packages&lt;/member_of_group&gt;</code></pre>\\n      </div>\\n    </div>\\n\\n    <div class=\\"file-edit-step\\">\\n      <div class=\\"file-edit-step-title\\">\\n        <span class=\\"step-num-pill\\">Step 3</span>\\n        <span>Verify the Full File After Editing</span>\\n      </div>\\n      <p class=\\"step-description\\">Self-check your file against the complete reference below to confirm indentation, closing brackets, and commas:</p>\\n      <details class=\\"file-edit-dropdown\\">\\n        <summary class=\\"file-edit-summary\\">\\n          <span>📄 View Complete nexus_amr_interfaces/package.xml After Editing</span>\\n          <span class=\\"file-edit-toggle-icon\\">▶</span>\\n        </summary>\\n        <div class=\\"file-edit-dropdown-content\\">\\n          <div class=\\"code-container\\" data-language=\\"xml\\">\\n            <div class=\\"code-header\\"><span class=\\"code-lang-tag\\">xml</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n            <pre><code class=\\"language-xml\\">&lt;?xml version=&quot;1.0&quot;?&gt;\\n&lt;?xml-model href=&quot;http://download.ros.org/schema/package_format3.xsd&quot; schematypens=&quot;http://www.w3.org/2001/XMLSchema&quot;?&gt;\\n&lt;package format=&quot;3&quot;&gt;\\n  &lt;name&gt;nexus_amr_interfaces&lt;/name&gt;\\n  &lt;version&gt;1.0.0&lt;/version&gt;\\n  &lt;description&gt;Custom ROS 2 message, service, and action interfaces for Nexus AMR&lt;/description&gt;\\n  &lt;maintainer email=&quot;instructor@botforge.io&quot;&gt;Nexus AMR Academy&lt;/maintainer&gt;\\n  &lt;license&gt;Apache-2.0&lt;/license&gt;\\n\\n  &lt;buildtool_depend&gt;ament_cmake&lt;/buildtool_depend&gt;\\n  &lt;buildtool_depend&gt;rosidl_default_generators&lt;/buildtool_depend&gt;\\n\\n  &lt;depend&gt;geometry_msgs&lt;/depend&gt;\\n\\n  &lt;exec_depend&gt;rosidl_default_runtime&lt;/exec_depend&gt;\\n  &lt;member_of_group&gt;rosidl_interface_packages&lt;/member_of_group&gt;\\n\\n  &lt;export&gt;\\n    &lt;build_type&gt;ament_cmake&lt;/build_type&gt;\\n  &lt;/export&gt;\\n&lt;/package&gt;</code></pre>\\n          </div>\\n        </div>\\n      </details>\\n    </div>\\n  </div>\\n</div>\\n<h3 id=\\"52-cmakeliststxt-configuration\\">5.2 Configuring <code class=\\"inline-code\\">CMakeLists.txt</code> for Code Generation</h3>\\n<p>Configure CMake to discover the generator tools and compile each interface file into C++ and Python headers:</p>\\n<div class=\\"file-edit-instruction-card\\">\\n  <div class=\\"file-edit-header\\">\\n    <div class=\\"file-edit-header-left\\">\\n      <span>📝 Step-by-Step File Modification Guide</span>\\n    </div>\\n    <span class=\\"file-edit-badge\\">~/ros2_ws/src/nexus_amr_interfaces/CMakeLists.txt</span>\\n  </div>\\n  <div class=\\"file-edit-body\\">\\n    <div class=\\"file-edit-step\\">\\n      <div class=\\"file-edit-step-title\\">\\n        <span class=\\"step-num-pill\\">Step 1</span>\\n        <span>Open the Target File</span>\\n      </div>\\n      <p class=\\"step-description\\">Open <code class=\\"inline-code\\">~/ros2_ws/src/nexus_amr_interfaces/CMakeLists.txt</code> in your editor.</p>\\n    </div>\\n\\n    <div class=\\"file-edit-step\\">\\n      <div class=\\"file-edit-step-title\\">\\n        <span class=\\"step-num-pill\\">Step 2</span>\\n        <span>Locate Insertion Point &amp; Add Lines</span>\\n      </div>\\n      <p class=\\"step-description\\">Find <code class=\\"inline-code\\">find_package(ament_cmake REQUIRED)</code> and add dependencies, then invoke <code class=\\"inline-code\\">rosidl_generate_interfaces</code> directly before <code class=\\"inline-code\\">ament_package()</code>:</p>\\n      <div class=\\"code-container\\" data-language=\\"cmake\\">\\n        <div class=\\"code-header\\"><span class=\\"code-lang-tag\\">cmake</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n        <pre><code class=\\"language-cmake\\"># &gt;&gt;&gt; 1. ADD REQUIRED GENERATOR PACKAGES (After find_package(ament_cmake REQUIRED)) &lt;&lt;&lt;\\nfind_package(geometry_msgs REQUIRED)\\nfind_package(rosidl_default_generators REQUIRED)\\n\\n# &gt;&gt;&gt; 2. COMPILE INTERFACE FILES (Add before ament_package()) &lt;&lt;&lt;\\nrosidl_generate_interfaces(\${PROJECT_NAME}\\n  &quot;msg/UltrasonicRange.msg&quot;\\n  &quot;msg/Sphere.msg&quot;\\n  &quot;msg/RobotStatus.msg&quot;\\n  &quot;srv/AddThreeInts.srv&quot;\\n  &quot;action/Fibonacci.action&quot;\\n  DEPENDENCIES geometry_msgs\\n)</code></pre>\\n      </div>\\n    </div>\\n\\n    <div class=\\"file-edit-step\\">\\n      <div class=\\"file-edit-step-title\\">\\n        <span class=\\"step-num-pill\\">Step 3</span>\\n        <span>Verify the Full File After Editing</span>\\n      </div>\\n      <p class=\\"step-description\\">Self-check your file against the complete reference below to confirm indentation, closing brackets, and commas:</p>\\n      <details class=\\"file-edit-dropdown\\">\\n        <summary class=\\"file-edit-summary\\">\\n          <span>📄 View Complete nexus_amr_interfaces/CMakeLists.txt After Editing</span>\\n          <span class=\\"file-edit-toggle-icon\\">▶</span>\\n        </summary>\\n        <div class=\\"file-edit-dropdown-content\\">\\n          <div class=\\"code-container\\" data-language=\\"cmake\\">\\n            <div class=\\"code-header\\"><span class=\\"code-lang-tag\\">cmake</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n            <pre><code class=\\"language-cmake\\">cmake_minimum_required(VERSION 3.8)\\nproject(nexus_amr_interfaces)\\n\\nif(CMAKE_COMPILER_IS_GNUCXX OR CMAKE_CXX_COMPILER_ID MATCHES &quot;Clang&quot;)\\n  add_compile_options(-Wall -Wextra -Wpedantic)\\nendif()\\n\\nfind_package(ament_cmake REQUIRED)\\nfind_package(geometry_msgs REQUIRED)\\nfind_package(rosidl_default_generators REQUIRED)\\n\\nrosidl_generate_interfaces(\${PROJECT_NAME}\\n  &quot;msg/UltrasonicRange.msg&quot;\\n  &quot;msg/Sphere.msg&quot;\\n  &quot;msg/RobotStatus.msg&quot;\\n  &quot;srv/AddThreeInts.srv&quot;\\n  &quot;action/Fibonacci.action&quot;\\n  DEPENDENCIES geometry_msgs\\n)\\n\\nament_package()</code></pre>\\n          </div>\\n        </div>\\n      </details>\\n    </div>\\n  </div>\\n</div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"6-building-verifying-custom-interfaces-with-cli\\">6. Building &amp; Verifying Custom Interfaces with CLI</h2>\\n<p>Build the interface package in your workspace:</p>\\n<p><div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\">cd ~/ros2_ws\\ncolcon build --packages-select nexus_amr_interfaces\\nsource install/setup.bash\\n</code></pre>\\n</div>\\n</p>\\n<p>Use the <code class=\\"inline-code\\">ros2 interface show</code> CLI command to verify that your custom types were compiled successfully:</p>\\n<p><div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\"># 1. View UltrasonicRange message definition\\nros2 interface show nexus_amr_interfaces/msg/UltrasonicRange\\n# Output:\\n# std_msgs/Header header\\n# float32 distance_m\\n# float32 min_range_m\\n# float32 max_range_m\\n# bool obstacle_detected\\n\\n# 2. View RobotStatus telemetry message definition\\nros2 interface show nexus_amr_interfaces/msg/RobotStatus\\n\\n# 2. View Sphere message definition\\nros2 interface show nexus_amr_interfaces/msg/Sphere\\n# Output:\\n# geometry_msgs/Point center\\n# float64 radius\\n\\n# 3. View AddThreeInts service definition\\nros2 interface show nexus_amr_interfaces/srv/AddThreeInts\\n# Output:\\n# int64 a\\n# int64 b\\n# int64 c\\n# ---\\n# int64 sum\\n\\n# 4. View Fibonacci action definition\\nros2 interface show nexus_amr_interfaces/action/Fibonacci\\n</code></pre>\\n</div>\\n</p>\\n<hr class=\\"divider\\">\\n<h2 id=\\"7-using-custom-interfaces-in-python-nodes\\">7. Using Custom Interfaces in Python Nodes</h2>\\n<p>Before writing a Python node that imports from <code class=\\"inline-code\\">nexus_amr_interfaces.msg</code>, configure your client package with the required dependency and entry point:</p>\\n\\n<h3 id=\\"71-add-dependency-to-navpro-basics-packagexml\\">7.1 Add Dependency to <code class=\\"inline-code\\">nexus_amr_basics/package.xml</code></h3>\\n<div class=\\"file-edit-instruction-card\\">\\n  <div class=\\"file-edit-header\\">\\n    <div class=\\"file-edit-header-left\\">\\n      <span>📝 Step-by-Step File Modification Guide</span>\\n    </div>\\n    <span class=\\"file-edit-badge\\">~/ros2_ws/src/nexus_amr_basics/package.xml</span>\\n  </div>\\n  <div class=\\"file-edit-body\\">\\n    <div class=\\"file-edit-step\\">\\n      <div class=\\"file-edit-step-title\\">\\n        <span class=\\"step-num-pill\\">Step 1</span>\\n        <span>Open the Target File</span>\\n      </div>\\n      <p class=\\"step-description\\">Open <code class=\\"inline-code\\">~/ros2_ws/src/nexus_amr_basics/package.xml</code> in your editor.</p>\\n    </div>\\n\\n    <div class=\\"file-edit-step\\">\\n      <div class=\\"file-edit-step-title\\">\\n        <span class=\\"step-num-pill\\">Step 2</span>\\n        <span>Locate Insertion Point &amp; Add Lines</span>\\n      </div>\\n      <p class=\\"step-description\\">Add your custom interface package as a dependency inside the <code class=\\"inline-code\\">&lt;package&gt;</code> block:</p>\\n      <div class=\\"code-container\\" data-language=\\"xml\\">\\n        <div class=\\"code-header\\"><span class=\\"code-lang-tag\\">xml</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n        <pre><code class=\\"language-xml\\">&lt;!-- &gt;&gt;&gt; ADD DEPENDENCY ON CUSTOM INTERFACE PACKAGE &lt;&lt;&lt; --&gt;\\n  &lt;depend&gt;nexus_amr_interfaces&lt;/depend&gt;</code></pre>\\n      </div>\\n    </div>\\n\\n    <div class=\\"file-edit-step\\">\\n      <div class=\\"file-edit-step-title\\">\\n        <span class=\\"step-num-pill\\">Step 3</span>\\n        <span>Verify the Full File After Editing</span>\\n      </div>\\n      <p class=\\"step-description\\">Self-check your file against the complete reference below to confirm indentation, closing brackets, and commas:</p>\\n      <details class=\\"file-edit-dropdown\\">\\n        <summary class=\\"file-edit-summary\\">\\n          <span>📄 View Complete nexus_amr_basics/package.xml After Editing</span>\\n          <span class=\\"file-edit-toggle-icon\\">▶</span>\\n        </summary>\\n        <div class=\\"file-edit-dropdown-content\\">\\n          <div class=\\"code-container\\" data-language=\\"xml\\">\\n            <div class=\\"code-header\\"><span class=\\"code-lang-tag\\">xml</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n            <pre><code class=\\"language-xml\\">&lt;?xml version=&quot;1.0&quot;?&gt;\\n&lt;?xml-model href=&quot;http://download.ros.org/schema/package_format3.xsd&quot; schematypens=&quot;http://www.w3.org/2001/XMLSchema&quot;?&gt;\\n&lt;package format=&quot;3&quot;&gt;\\n  &lt;name&gt;nexus_amr_basics&lt;/name&gt;\\n  &lt;version&gt;1.0.0&lt;/version&gt;\\n  &lt;description&gt;ROS 2 Day 1: Topics, Services, Parameters, and Launch Files&lt;/description&gt;\\n  &lt;maintainer email=&quot;instructor@botforge.io&quot;&gt;Nexus AMR Academy&lt;/maintainer&gt;\\n  &lt;license&gt;Apache-2.0&lt;/license&gt;\\n\\n  &lt;depend&gt;rclpy&lt;/depend&gt;\\n  &lt;depend&gt;geometry_msgs&lt;/depend&gt;\\n  &lt;depend&gt;std_msgs&lt;/depend&gt;\\n  &lt;depend&gt;std_srvs&lt;/depend&gt;\\n  &lt;depend&gt;nexus_amr_interfaces&lt;/depend&gt;\\n\\n  &lt;export&gt;\\n    &lt;build_type&gt;ament_python&lt;/build_type&gt;\\n  &lt;/export&gt;\\n&lt;/package&gt;</code></pre>\\n          </div>\\n        </div>\\n      </details>\\n    </div>\\n  </div>\\n</div>\\n\\n<h3 id=\\"72-create-python-node-using-custom-interface\\">7.2 Create Python Node Using Custom Interface</h3>\\n<p>Create file <code class=\\"inline-code\\">~/ros2_ws/src/nexus_amr_basics/nexus_amr_basics/custom_pub.py</code> and import the generated class directly:</p>\\n<div class=\\"code-container\\" data-language=\\"python\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">python</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-python\\">#!/usr/bin/env python3\\n&quot;&quot;&quot;\\nPublishes custom UltrasonicRange.msg data at 1 Hz\\n&quot;&quot;&quot;\\nimport rclpy\\nfrom rclpy.node import Node\\nfrom nexus_amr_interfaces.msg import UltrasonicRange\\n\\n\\nclass MinimalCustomPublisher(Node):\\n\\n    def __init__(self):\\n        super().__init__(&#x27;minimal_custom_publisher&#x27;)\\n        self.publisher_ = self.create_publisher(UltrasonicRange, &#x27;custom_num_topic&#x27;, 10)\\n        self.timer = self.create_timer(1.0, self.timer_callback)\\n        self.count = 0\\n\\n    def timer_callback(self):\\n        msg = UltrasonicRange()\\n        msg.num = self.count\\n        self.publisher_.publish(msg)\\n        self.get_logger().info(f&#x27;Published custom Num: {msg.num}&#x27;)\\n        self.count += 1\\n\\n\\ndef main(args=None):\\n    rclpy.init(args=args)\\n    node = MinimalCustomPublisher()\\n    try:\\n        rclpy.spin(node)\\n    finally:\\n        node.destroy_node()\\n        rclpy.shutdown()\\n\\n\\nif __name__ == &#x27;__main__&#x27;:\\n    main()\\n</code></pre>\\n</div>\\n\\n<div class=\\"alert-callout alert-tip\\" style=\\"margin: 1.75rem 0;\\">\\n  <div class=\\"alert-icon\\">🔍</div>\\n  <div class=\\"alert-body\\">\\n    <strong>Diagnostic Drill: Interface Introspection:</strong><br>\\n    Before implementing nodes in Python or C++, always verify that your custom interfaces were cleanly parsed and registered in the ROS 2 type system:\\n    <div class=\\"code-container\\" data-language=\\"bash\\" style=\\"margin: 0.5rem 0 0.3rem 0;\\">\\n      <div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n      <pre><code class=\\"language-bash\\">ros2 interface show nexus_amr_interfaces/msg/RobotStatus\\n# Expected Output:\\n# std_msgs/Header header\\n# string robot_id\\n# float32 battery_percentage\\n# geometry_msgs/Twist current_velocity\\n# bool emergency_stop_engaged</code></pre>\\n    </div>\\n    If any field is misspelled or missing, colcon build will throw a generator error. This check guarantees type safety across your entire fleet!\\n  </div>\\n</div>\\n\\n<div class=\\"code-breakdown-card\\">\\n  <h4 class=\\"code-breakdown-title\\">🔬 Core Code Deep Dive &amp; Operational Breakdown: Custom Message Publisher Mechanics</h4>\\n  <p class=\\"code-breakdown-intro\\">Dissecting how custom interface messages are imported and populated in Python:</p>\\n  <ul class=\\"code-breakdown-list\\">\\n    <li class=\\"code-breakdown-item\\"><strong>Custom Module Import:</strong> <code>from nexus_amr_interfaces.msg import UltrasonicRange</code> imports the Python module generated during the workspace build. If the package was not built with <code>colcon build</code>, this import raises an <code>ImportError</code>.</li>\\n    <li class=\\"code-breakdown-item\\"><strong>Field Population & Schema Conformance:</strong> Custom message fields (e.g. <code>msg.sensor_id = 'front_center'</code>, <code>msg.distance_m = ...</code>) are populated directly as Python attributes. The rclpy bindings validate primitive types during assignment.</li>\\n    <li class=\\"code-breakdown-item\\"><strong>Header Timestamping:</strong> In standard robotics messages, including an <code>std_msgs/Header</code> with <code>self.get_clock().now().to_msg()</code> ensures that sensor data can be precisely synchronized with coordinate frame transforms in TF2.</li>\\n  </ul>\\n</div>\\n\\n\\n<h3 id=\\"73-register-custom-node-in-setuppy\\">7.3 Register Node in <code class=\\"inline-code\\">setup.py</code></h3>\\n<p>Register the executable entry point so it can be run via <code class=\\"inline-code\\">ros2 run</code>:</p>\\n<div class=\\"file-edit-instruction-card\\">\\n  <div class=\\"file-edit-header\\">\\n    <div class=\\"file-edit-header-left\\">\\n      <span>📝 Step-by-Step File Modification Guide</span>\\n    </div>\\n    <span class=\\"file-edit-badge\\">~/ros2_ws/src/nexus_amr_basics/setup.py</span>\\n  </div>\\n  <div class=\\"file-edit-body\\">\\n    <div class=\\"file-edit-step\\">\\n      <div class=\\"file-edit-step-title\\">\\n        <span class=\\"step-num-pill\\">Step 1</span>\\n        <span>Open the Target File</span>\\n      </div>\\n      <p class=\\"step-description\\">Open <code class=\\"inline-code\\">~/ros2_ws/src/nexus_amr_basics/setup.py</code> in your editor.</p>\\n    </div>\\n\\n    <div class=\\"file-edit-step\\">\\n      <div class=\\"file-edit-step-title\\">\\n        <span class=\\"step-num-pill\\">Step 2</span>\\n        <span>Locate Insertion Point &amp; Add Lines</span>\\n      </div>\\n      <p class=\\"step-description\\">Register the custom publisher node inside <code class=\\"inline-code\\">entry_points['console_scripts']</code>:</p>\\n      <div class=\\"code-container\\" data-language=\\"python\\">\\n        <div class=\\"code-header\\"><span class=\\"code-lang-tag\\">python</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n        <pre><code class=\\"language-python\\">entry_points={\\n        &#x27;console_scripts&#x27;: [\\n            &#x27;talker = nexus_amr_basics.talker:main&#x27;,\\n            &#x27;listener = nexus_amr_basics.listener:main&#x27;,\\n            # &gt;&gt;&gt; ADD THIS ENTRY POINT TO REGISTER CUSTOM MESSAGE PUBLISHER &lt;&lt;&lt;\\n            &#x27;custom_pub = nexus_amr_basics.custom_pub:main&#x27;,\\n        ],\\n    },</code></pre>\\n      </div>\\n    </div>\\n\\n    <div class=\\"file-edit-step\\">\\n      <div class=\\"file-edit-step-title\\">\\n        <span class=\\"step-num-pill\\">Step 3</span>\\n        <span>Verify the Full File After Editing</span>\\n      </div>\\n      <p class=\\"step-description\\">Self-check your file against the complete reference below to confirm indentation, closing brackets, and commas:</p>\\n      <details class=\\"file-edit-dropdown\\">\\n        <summary class=\\"file-edit-summary\\">\\n          <span>📄 View Complete setup.py After Adding Custom Node</span>\\n          <span class=\\"file-edit-toggle-icon\\">▶</span>\\n        </summary>\\n        <div class=\\"file-edit-dropdown-content\\">\\n          <div class=\\"code-container\\" data-language=\\"python\\">\\n            <div class=\\"code-header\\"><span class=\\"code-lang-tag\\">python</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n            <pre><code class=\\"language-python\\">from setuptools import find_packages, setup\\n\\npackage_name = &#x27;nexus_amr_basics&#x27;\\n\\nsetup(\\n    name=package_name,\\n    version=&#x27;1.0.0&#x27;,\\n    packages=find_packages(exclude=[&#x27;test&#x27;]),\\n    data_files=[\\n        (&#x27;share/ament_index/resource_index/packages&#x27;,\\n            [&#x27;resource/&#x27; + package_name]),\\n        (&#x27;share/&#x27; + package_name, [&#x27;package.xml&#x27;]),\\n    ],\\n    install_requires=[&#x27;setuptools&#x27;],\\n    zip_safe=True,\\n    maintainer=&#x27;Nexus AMR Academy&#x27;,\\n    maintainer_email=&#x27;instructor@botforge.io&#x27;,\\n    description=&#x27;ROS 2 Day 1: Topics, Services, Parameters, and Launch Files&#x27;,\\n    license=&#x27;Apache-2.0&#x27;,\\n    entry_points={\\n        &#x27;console_scripts&#x27;: [\\n            &#x27;talker = nexus_amr_basics.talker:main&#x27;,\\n            &#x27;listener = nexus_amr_basics.listener:main&#x27;,\\n            &#x27;custom_pub = nexus_amr_basics.custom_pub:main&#x27;,\\n        ],\\n    },\\n)</code></pre>\\n          </div>\\n        </div>\\n      </details>\\n    </div>\\n  </div>\\n</div>\\n\\n\\n<h3 id=\\"73-register-custom-node-in-setuppy\\">7.3 Register Node in <code class=\\"inline-code\\">setup.py</code></h3>\\n<p>Register the executable entry point so it can be run via <code class=\\"inline-code\\">ros2 run</code>:</p>\\n<div class=\\"file-edit-instruction-card\\">\\n  <div class=\\"file-edit-header\\">\\n    <div class=\\"file-edit-header-left\\">\\n      <span>📝 Step-by-Step File Modification Guide</span>\\n    </div>\\n    <span class=\\"file-edit-badge\\">~/ros2_ws/src/nexus_amr_basics/setup.py</span>\\n  </div>\\n  <div class=\\"file-edit-body\\">\\n    <div class=\\"file-edit-step\\">\\n      <div class=\\"file-edit-step-title\\">\\n        <span class=\\"step-num-pill\\">Step 1</span>\\n        <span>Open the Target File</span>\\n      </div>\\n      <p class=\\"step-description\\">Open <code class=\\"inline-code\\">~/ros2_ws/src/nexus_amr_basics/setup.py</code> in your editor.</p>\\n    </div>\\n\\n    <div class=\\"file-edit-step\\">\\n      <div class=\\"file-edit-step-title\\">\\n        <span class=\\"step-num-pill\\">Step 2</span>\\n        <span>Locate Insertion Point &amp; Add Lines</span>\\n      </div>\\n      <p class=\\"step-description\\">Register the custom publisher node inside <code class=\\"inline-code\\">entry_points['console_scripts']</code>:</p>\\n      <div class=\\"code-container\\" data-language=\\"python\\">\\n        <div class=\\"code-header\\"><span class=\\"code-lang-tag\\">python</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n        <pre><code class=\\"language-python\\">entry_points={\\n        &#x27;console_scripts&#x27;: [\\n            &#x27;talker = nexus_amr_basics.talker:main&#x27;,\\n            &#x27;listener = nexus_amr_basics.listener:main&#x27;,\\n            # &gt;&gt;&gt; ADD THIS ENTRY POINT TO REGISTER CUSTOM MESSAGE PUBLISHER &lt;&lt;&lt;\\n            &#x27;custom_pub = nexus_amr_basics.custom_pub:main&#x27;,\\n        ],\\n    },</code></pre>\\n      </div>\\n    </div>\\n\\n    <div class=\\"file-edit-step\\">\\n      <div class=\\"file-edit-step-title\\">\\n        <span class=\\"step-num-pill\\">Step 3</span>\\n        <span>Verify the Full File After Editing</span>\\n      </div>\\n      <p class=\\"step-description\\">Self-check your file against the complete reference below to confirm indentation, closing brackets, and commas:</p>\\n      <details class=\\"file-edit-dropdown\\">\\n        <summary class=\\"file-edit-summary\\">\\n          <span>📄 View Complete setup.py After Adding Custom Node</span>\\n          <span class=\\"file-edit-toggle-icon\\">▶</span>\\n        </summary>\\n        <div class=\\"file-edit-dropdown-content\\">\\n          <div class=\\"code-container\\" data-language=\\"python\\">\\n            <div class=\\"code-header\\"><span class=\\"code-lang-tag\\">python</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n            <pre><code class=\\"language-python\\">from setuptools import find_packages, setup\\n\\npackage_name = &#x27;nexus_amr_basics&#x27;\\n\\nsetup(\\n    name=package_name,\\n    version=&#x27;1.0.0&#x27;,\\n    packages=find_packages(exclude=[&#x27;test&#x27;]),\\n    data_files=[\\n        (&#x27;share/ament_index/resource_index/packages&#x27;,\\n            [&#x27;resource/&#x27; + package_name]),\\n        (&#x27;share/&#x27; + package_name, [&#x27;package.xml&#x27;]),\\n    ],\\n    install_requires=[&#x27;setuptools&#x27;],\\n    zip_safe=True,\\n    maintainer=&#x27;Nexus AMR Academy&#x27;,\\n    maintainer_email=&#x27;instructor@botforge.io&#x27;,\\n    description=&#x27;ROS 2 Day 1: Topics, Services, Parameters, and Launch Files&#x27;,\\n    license=&#x27;Apache-2.0&#x27;,\\n    entry_points={\\n        &#x27;console_scripts&#x27;: [\\n            &#x27;talker = nexus_amr_basics.talker:main&#x27;,\\n            &#x27;listener = nexus_amr_basics.listener:main&#x27;,\\n            &#x27;custom_pub = nexus_amr_basics.custom_pub:main&#x27;,\\n        ],\\n    },\\n)</code></pre>\\n          </div>\\n        </div>\\n      </details>\\n    </div>\\n  </div>\\n</div>\\n\\n</p>\\n\\n<hr class=\\"divider\\">\\n<h2 id=\\"8-hands-on-student-challenge\\">8. Hands-on Student Challenge: Custom RobotStatus Telemetry Publisher</h2>\\n<p>Integrate the compiled <code class=\\"inline-code\\">nexus_amr_interfaces/msg/RobotStatus.msg</code> interface into a production telemetry node that streams real-time battery, pose, and status.</p>\\n\\n<div class=\\"alert alert-tip\\">\\n  <div class=\\"alert-title\\">🎯 Mission Requirements</div>\\n  <ol>\\n    <li><strong>TODO 1:</strong> Create a publisher for <code class=\\"inline-code\\">RobotStatus</code> on topic <code class=\\"inline-code\\">/robot/status</code> (QoS depth = 10).</li>\\n    <li><strong>TODO 2:</strong> Create a 1.0 Hz periodic timer (<code class=\\"inline-code\\">period = 1.0s</code>).</li>\\n    <li><strong>TODO 3:</strong> Populate <code class=\\"inline-code\\">RobotStatus</code> fields: <code class=\\"inline-code\\">robot_id='NEXUS_AMR_01'</code>, <code class=\\"inline-code\\">battery_percentage</code>, <code class=\\"inline-code\\">position (Point)</code>, <code class=\\"inline-code\\">linear_velocity</code>, and <code class=\\"inline-code\\">angular_velocity</code>.</li>\\n    <li><strong>TODO 4:</strong> Publish the message and log formatted status report, then verify with <code class=\\"inline-code\\">ros2 topic echo /robot/status</code>.</li>\\n  </ol>\\n</div>\\n\\n\\n<div class=\\"alert alert-info alert-briefing\\">\\n  <div class=\\"alert-icon\\">📊</div>\\n  <div class=\\"alert-content\\">\\n    <div class=\\"alert-title\\">Robotics Flight Operations Mission Briefing: Autonomous Mobile Robot Status Heartbeat Telemetry Challenge</div>\\n    <div class=\\"alert-body\\">\\n      <strong>Physical AMR Context &amp; Operational Challenge:</strong><br>\\n      In an automated fulfillment center, a central Fleet Management Server (FMS) must track the health of dozens of mobile robots in real-time. Emitting separate topics for battery level, current zone, speed multiplier, and hardware error codes creates network overhead and race conditions on the dashboard.\\n      <br><br>\\n      <strong>Architectural Role &amp; Why This Mechanism:</strong><br>\\n      Bundling interrelated telemetry into a single atomic composite message (<code>RobotStatus.msg</code>) guarantees that all diagnostic fields correspond to the exact same temporal snapshot. Downstream supervisors receive a coherent, synchronized vehicle status on every packet.\\n      <br><br>\\n      <strong>Flight Objective &amp; Behavioral Outcome:</strong><br>\\n      Implement the <code>StatusPublisher</code> node using <code>nexus_amr_interfaces/msg/RobotStatus</code>. Publish vehicle state-of-charge, operational speed multiplier, and active mode at 1.0 Hz, ensuring all diagnostic attributes are accurately mapped.\\n    </div>\\n  </div>\\n</div>\\n\\n<h3 id=\\"81-starter-template\\">8.1 Starter Template: <code class=\\"inline-code\\">m04_l19_task_status_publisher.py</code></h3>\\n<p>Copy the starter template from the reference workspace into your active student workspace:</p>\\n<div class=\\"code-container\\" data-language=\\"bash\\">\\n  <div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n  <pre><code class=\\"language-bash\\">cp ~/ros2_ws_reference/src/nexus_amr_basics/nexus_amr_basics/m04_l19_task_status_publisher.py ~/ros2_ws/src/nexus_amr_basics/nexus_amr_basics/</code></pre>\\n</div>\\n<p>Open the copied file in your editor and complete the marked <code class=\\"inline-code\\">TODO</code> targets:</p>\\n\\n<div class=\\"code-container\\" data-language=\\"python\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">python</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-python\\">#!/usr/bin/env python3\\n&quot;&quot;&quot;\\n================================================================================\\nNexus AMR Learning Hub - Level 1: Module 4 (Bonus) / Lesson 19 Task\\nPackage: nexus_amr_basics\\nTask:    m04_l19_task_status_publisher.py (alias: task_status_publisher)\\n================================================================================\\n\\nEXERCISE OVERVIEW:\\n------------------\\nYour mission is to construct a telemetry publisher utilizing our custom\\ncompiled IDL interface: \`nexus_amr_interfaces/msg/RobotStatus.msg\`.\\n\\nOBJECTIVES:\\n-----------\\n1. Import \`RobotStatus\` from \`nexus_amr_interfaces.msg\`.\\n2. TODO 1: Create a publisher for \`RobotStatus\` on topic \`/robot/status\` (QoS depth = 10).\\n3. TODO 2: Create a 1.0 Hz timer (period = 1.0s) triggering \`self.publish_status\`.\\n4. TODO 3: In \`publish_status\`, populate all fields:\\n   - robot_id: &#x27;NEXUS_AMR_01&#x27;\\n   - battery_percentage: starting at 100.0, decrementing by 0.2 each second\\n   - is_charging: False\\n   - emergency_stop_active: False\\n   - position.x, position.y, position.z: odometry coordinates\\n   - linear_velocity: 0.35 m/s, angular_velocity: 0.05 rad/s\\n5. TODO 4: Publish the telemetry packet and log a formatted status report.\\n================================================================================\\n&quot;&quot;&quot;\\n\\nimport rclpy\\nfrom rclpy.node import Node\\nfrom rclpy.executors import ExternalShutdownException\\nfrom nexus_amr_interfaces.msg import RobotStatus\\nfrom geometry_msgs.msg import Point\\n\\n\\nclass RobotStatusPublisher(Node):\\n\\n    def __init__(self):\\n        super().__init__(&#x27;robot_status_publisher&#x27;)\\n\\n        self.battery_level = 100.0\\n        self.waypoint_count = 0\\n        self.pos_x = 0.0\\n        self.pos_y = 0.0\\n\\n        # ======================================================================\\n        # TODO 1: Create publisher on topic &#x27;/robot/status&#x27; using RobotStatus msg\\n        # - Hint: Call self.create_publisher() with the custom RobotStatus message type, topic string, and queue depth.\\n        # ======================================================================\\n        # ---&gt; YOUR CODE HERE &lt;---\\n\\n        # ======================================================================\\n        # TODO 2: Create 1.0 Hz timer (period = 1.0s) calling self.publish_status\\n        # - Hint: Call self.create_timer() with 1.0s period and self.publish_status callback.\\n        # ======================================================================\\n        # ---&gt; YOUR CODE HERE &lt;---\\n\\n        self.get_logger().info(&#x27;RobotStatusPublisher initialized on topic /robot/status at 1.0 Hz.&#x27;)\\n\\n    def publish_status(self):\\n        # Simulate slight movement and battery consumption\\n        self.battery_level = max(5.0, self.battery_level - 0.2)\\n        self.pos_x += 0.15\\n        self.pos_y += 0.05\\n\\n        # ======================================================================\\n        # TODO 3: Construct and populate RobotStatus message\\n        # - Instantiate RobotStatus() and populate its metadata, battery percentage, charging state, Point position (x, y), and velocities.\\n        # ======================================================================\\n        # ---&gt; YOUR CODE HERE &lt;---\\n\\n        # ======================================================================\\n        # TODO 4: Publish message and log summary\\n        # - Call publish() on your status publisher handle, and log a formatted status telemetry string.\\n        # ======================================================================\\n        # ---&gt; YOUR CODE HERE &lt;---\\n        pass\\n\\n\\ndef main(args=None):\\n    rclpy.init(args=args)\\n    node = RobotStatusPublisher()\\n\\n    try:\\n        rclpy.spin(node)\\n    except (KeyboardInterrupt, ExternalShutdownException):\\n        pass\\n    finally:\\n        node.destroy_node()\\n        if rclpy.ok():\\n            rclpy.shutdown()\\n\\n\\nif __name__ == &#x27;__main__&#x27;:\\n    main()\\n</code></pre>\\n</div>\\n\\n<h3 id=\\"82-verification-steps\\">8.2 Verification Steps &amp; Expected Terminal Output</h3>\\n<p>Run your node or test command and observe the output:</p>\\n<div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash (Terminal 1 - Status Publisher)</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\">source ~/ros2_ws/install/setup.bash\\nros2 run nexus_amr_basics robot_status_publisher</code></pre>\\n</div>\\n\\n<div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash (Terminal 2 - Custom Message Echo)</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\">source /opt/ros/jazzy/setup.bash\\nros2 topic echo /robot/status</code></pre>\\n</div>\\n\\n<p><em>Expected Terminal Output:</em></p>\\n<div class=\\"code-container\\" data-language=\\"text\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">text</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-text\\">[INFO] [1792005281.473226474] [robot_status_publisher]: RobotStatusPublisher initialized on topic /robot/status at 1.0 Hz.\\n[INFO] [1792005282.465804739] [robot_status_publisher]: [STATUS PUB] AMR: NEXUS_AMR_01 | Bat:  99.8% | Pos: ( 0.15,  0.05) | Vel: 0.35 m/s\\n[INFO] [1792005283.465804739] [robot_status_publisher]: [STATUS PUB] AMR: NEXUS_AMR_01 | Bat:  99.6% | Pos: ( 0.30,  0.10) | Vel: 0.35 m/s</code></pre>\\n</div>\\n\\n<details class=\\"reference-solution-dropdown\\">\\n  <summary class=\\"solution-summary-btn\\">\\n    <span>🔍 View Reference Solution (<code class=\\"inline-code\\">m04_l19_solution_status_publisher.py</code>)</span>\\n  </summary>\\n  <div class=\\"solution-body\\">\\n    <p>Reference file: <code class=\\"inline-code\\">ros2_ws_reference/src/nexus_amr_basics/nexus_amr_basics/m04_l19_solution_status_publisher.py</code></p>\\n    <div class=\\"code-container\\" data-language=\\"python\\">\\n      <div class=\\"code-header\\"><span class=\\"code-lang-tag\\">python</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n      <pre><code class=\\"language-python\\">#!/usr/bin/env python3\\n&quot;&quot;&quot;\\n================================================================================\\nNexus AMR Learning Hub - Level 1: Module 4 (Bonus) / Lesson 19 Solution\\nPackage: nexus_amr_basics\\nTask:    m04_l19_solution_status_publisher.py (alias: robot_status_publisher)\\n================================================================================\\n&quot;&quot;&quot;\\n\\nimport rclpy\\nfrom rclpy.node import Node\\nfrom rclpy.executors import ExternalShutdownException\\nfrom nexus_amr_interfaces.msg import RobotStatus\\nfrom geometry_msgs.msg import Point\\n\\n\\nclass RobotStatusPublisher(Node):\\n\\n    def __init__(self):\\n        super().__init__(&#x27;robot_status_publisher&#x27;)\\n\\n        self.battery_level = 100.0\\n        self.pos_x = 0.0\\n        self.pos_y = 0.0\\n\\n        # Step 1: Create publisher for custom interface\\n        self.status_pub = self.create_publisher(RobotStatus, &#x27;/robot/status&#x27;, 10)\\n\\n        # Step 2: 1.0 Hz periodic timer\\n        self.timer_period = 1.0\\n        self.timer = self.create_timer(self.timer_period, self.publish_status)\\n\\n        self.get_logger().info(&#x27;RobotStatusPublisher initialized on topic /robot/status at 1.0 Hz.&#x27;)\\n\\n    def publish_status(self):\\n        self.battery_level = max(5.0, self.battery_level - 0.2)\\n        self.pos_x += 0.15\\n        self.pos_y += 0.05\\n\\n        # Step 3: Populate custom message fields\\n        msg = RobotStatus()\\n        msg.robot_id = &#x27;NEXUS_AMR_01&#x27;\\n        msg.battery_percentage = float(self.battery_level)\\n        msg.is_charging = False\\n        msg.emergency_stop_active = False\\n\\n        pt = Point()\\n        pt.x = float(self.pos_x)\\n        pt.y = float(self.pos_y)\\n        pt.z = 0.0\\n        msg.position = pt\\n\\n        msg.linear_velocity = 0.35\\n        msg.angular_velocity = 0.05\\n\\n        # Step 4: Publish and log\\n        self.status_pub.publish(msg)\\n        self.get_logger().info(\\n            f&#x27;[STATUS PUB] AMR: {msg.robot_id} | Bat: {msg.battery_percentage:5.1f}% | &#x27;\\n            f&#x27;Pos: ({msg.position.x:5.2f}, {msg.position.y:5.2f}) | Vel: {msg.linear_velocity:.2f} m/s&#x27;\\n        )\\n\\n\\ndef main(args=None):\\n    rclpy.init(args=args)\\n    node = RobotStatusPublisher()\\n\\n    try:\\n        rclpy.spin(node)\\n    except (KeyboardInterrupt, ExternalShutdownException):\\n        pass\\n    finally:\\n        node.destroy_node()\\n        if rclpy.ok():\\n            rclpy.shutdown()\\n\\n\\nif __name__ == &#x27;__main__&#x27;:\\n    main()</code></pre>\\n    </div>\\n  </div>\\n</details>\\n\\n<div class=\\"code-breakdown-card\\">\\n  <h4 class=\\"code-breakdown-title\\">🔬 Core Code Deep Dive &amp; Operational Breakdown: StatusPublisher Solution Breakdown</h4>\\n  <p class=\\"code-breakdown-intro\\">Key architectural takeaways from the Custom Telemetry Publisher solution:</p>\\n  <ul class=\\"code-breakdown-list\\">\\n    <li class=\\"code-breakdown-item\\"><strong>Atomic Diagnostic Heartbeats:</strong> Bundling battery percentage, operational speed mode, and error flags into a single message avoids temporal skew across dashboard monitors.</li>\\n    <li class=\\"code-breakdown-item\\"><strong>Type Consistency & Zero-Copy Efficiency:</strong> Custom interfaces compiled via <code>ament_cmake_ros</code> leverage CDR serialization, allowing efficient zero-copy IPC when nodes are composited into a single process container.</li>\\n  </ul>\\n</div>\\n\\n\\n<div class=\\"code-breakdown-card\\">\\n  <h4 class=\\"code-breakdown-title\\">🔬 Core Code Deep Dive &amp; Operational Breakdown: Custom Telemetry Publisher Solution Breakdown</h4>\\n  <p class=\\"code-breakdown-intro\\">Key takeaways from custom interface publishing:</p>\\n  <ul class=\\"code-breakdown-list\\">\\n    <li class=\\"code-breakdown-item\\"><strong>Atomic Diagnostic Snapshots:</strong> Bundling multiple telemetry fields into one message avoids race conditions and temporal skew across disparate subscriber monitors.</li>\\n    <li class=\\"code-breakdown-item\\"><strong>Header & Timestamp Synchronization:</strong> Custom messages including <code>std_msgs/Header</code> carry sensor capture timestamps, allowing time-series data alignment in RViz2 and rosbag analytics.</li>\\n  </ul>\\n</div>\\n\\n<div class=\\"asset-handoff-card\\" style=\\"margin: 1.75rem 0 1rem 0; padding: 1.15rem 1.4rem; border-radius: 10px; background: rgba(16, 185, 129, 0.06); border: 1px solid rgba(16, 185, 129, 0.25); border-left: 4px solid #10b981;\\">\\n  <div style=\\"display: flex; align-items: center; gap: 0.5rem; margin-bottom: 0.5rem;\\">\\n    <span style=\\"font-size: 1.1rem;\\">📦</span>\\n    <strong style=\\"font-size: 0.95rem; color: #10b981; text-transform: uppercase; letter-spacing: 0.04em;\\">Asset Handoff &amp; Next Lesson Pipeline Bridge</strong>\\n  </div>\\n  <p style=\\"margin: 0 0 0.65rem 0; font-size: 0.88rem; color: var(--text-primary); line-height: 1.6;\\">\\n    You have authored and compiled custom ROS 2 Interface definitions (.msg, .srv, .action) in the dedicated nexus_amr_interfaces package with CMakeLists.txt and rosidl code generators.\\n  </p>\\n  <div style=\\"display: flex; flex-wrap: wrap; gap: 0.75rem; font-size: 0.82rem; font-family: var(--font-mono);\\">\\n    <span style=\\"background: var(--bg-surface); border: 1px solid var(--border-color); padding: 0.25rem 0.6rem; border-radius: 5px; color: var(--text-primary);\\">\\n      📁 <strong>Produced Artifact:</strong> <code>ros2_ws/src/nexus_amr_interfaces/</code> (custom <code>.msg</code>, <code>.srv</code>, <code>.action</code> definitions and compiled C++/Python type libraries)\\n    </span>\\n    <span style=\\"background: var(--bg-surface); border: 1px solid var(--border-color); padding: 0.25rem 0.6rem; border-radius: 5px; color: var(--text-primary);\\">\\n      ➡️ <strong>Ingested By:</strong> Bonus Lesson 20 (Data Recording &amp; Playback with ROS 2 Bags)\\n    </span>\\n  </div>\\n</div>\\n","quizzes":[{"id":"q_l1_07_1","prompt":"Why must custom ROS 2 messages, services, and actions be compiled inside a CMake package rather than a pure Python (ament_python) package?","options":["Python does not support compiling binary structs","rosidl_default_generators is a CMake build pipeline that compiles .msg files into C, C++, and Python type bindings simultaneously","Python setup.py cannot create directories","DDS middleware only accepts C++ code"],"correct":1,"explanation":"Custom ROS 2 interfaces require the rosidl_default_generators CMake package to generate language-specific C, C++, Python, and DDS type support serialization libraries."}],"has_quiz":true,"next_id":"lesson_19","prev_id":"lesson_17","subtopics":[{"id":"1-overview-learning-objectives","title":"1. Overview &amp; Learning Objectives"},{"id":"2-standard-ros-2-interface-libraries","title":"2. Standard ROS 2 Interface Libraries"},{"id":"3-the-custom-interface-architecture-rule","title":"3. The Custom Interface Architecture Rule"},{"id":"4-creating-custom-ros-2-interfaces---step-by-step","title":"4. Creating Custom Robot Interfaces: Defining UltrasonicRange.msg"},{"id":"5-configuring-packagexml-cmakeliststxt","title":"5. Configuring package.xml &amp; CMakeLists.txt"},{"id":"6-building-verifying-custom-interfaces-with-cli","title":"6. Building &amp; Verifying Custom Interfaces with CLI"},{"id":"7-using-custom-interfaces-in-python-nodes","title":"7. Using Custom Interfaces in Python Nodes"},{"id":"8-hands-on-student-challenge","title":"8. Hands-on Student Challenge: Custom RobotStatus Telemetry Publisher"}]},{"id":"lesson_19","num":19,"num_str":"19","title":"Data Recording & Playback with ROS 2 Bags","slug":"ros2_bag_recording_and_playback","filename":"12_ros2_bag_recording_and_playback.md","module":"Bonus: Advanced Masterclasses & Electives","module_id":4,"duration":"45-60 min","focus":"Robotic Dataset Recording, MCAP Storage Plugin & Python \`rosbag2_py\` Reader","snapshot":[["Deterministic Serialization","rosbag2 records raw DDS serialized packets directly to SQLite3 or MCAP storage engines without CPU decoding overhead."],["Field Incident Forensics","Replay recorded telemetry in simulated environments to reproduce hardware sensor anomalies and edge-case faults offline."],["Selective Recording","Record specific critical telemetry streams (ros2 bag record -o patrol_run /scan /odom /cmd_vel) to optimize disk I/O."],["Programmatic Python API","rosbag2_py allows custom analytical scripts to read, filter, plot, and validate sensor datasets programmatically."]],"html_content":"<h2 id=\\"1-overview-learning-objectives\\">1. Overview &amp; Learning Objectives</h2>\\n<p>In physical robotics engineering, reproducing a bug that occurred 10 minutes ago in an aisle of a warehouse is impossible without recording the robot's sensor data. A <strong>ROS 2 Bag</strong> acts as the robot's &quot;flight data recorder,&quot; logging exact binary message frames with microsecond timestamps.</p>\\n<p><div class=\\"learning-objectives-card\\">\\n  <div class=\\"learning-objectives-header\\">\\n    <div class=\\"objectives-icon-badge\\">\\n      <span style=\\"font-size: 1.15rem; line-height: 1;\\">🎯</span>\\n    </div>\\n    <div class=\\"objectives-title-group\\">\\n      <h3 class=\\"objectives-main-title\\">Learning Objectives &amp; Core Outcomes</h3>\\n      <span class=\\"objectives-subtitle\\">By the end of this lesson, you will be able to:</span>\\n    </div>\\n    <span class=\\"objectives-count-badge\\">5 CORE OUTCOMES</span>\\n  </div>\\n  <ul class=\\"learning-objectives-list\\">\\n    <li class=\\"learning-objective-item\\">\\n      <span class=\\"objective-num-badge\\">1</span>\\n      <span class=\\"objective-text\\">Understand ROS 2 bag storage backends: legacy <strong>SQLite3</strong> vs. modern <strong>MCAP</strong>.</span>\\n    </li>\\n    <li class=\\"learning-objective-item\\">\\n      <span class=\\"objective-num-badge\\">2</span>\\n      <span class=\\"objective-text\\">Record selective topic subsets (<code class=\\"inline-code\\">/cmd_vel</code>, <code class=\\"inline-code\\">/odom</code>, <code class=\\"inline-code\\">/scan</code>) and split logs by size/duration.</span>\\n    </li>\\n    <li class=\\"learning-objective-item\\">\\n      <span class=\\"objective-num-badge\\">3</span>\\n      <span class=\\"objective-text\\">Inspect bag metadata and topic statistics using <code class=\\"inline-code\\">ros2 bag info</code>.</span>\\n    </li>\\n    <li class=\\"learning-objective-item\\">\\n      <span class=\\"objective-num-badge\\">4</span>\\n      <span class=\\"objective-text\\">Replay datasets into the computational graph at varied rates (<code class=\\"inline-code\\">--rate 2.0</code>, <code class=\\"inline-code\\">--loop</code>).</span>\\n    </li>\\n    <li class=\\"learning-objective-item\\">\\n      <span class=\\"objective-num-badge\\">5</span>\\n      <span class=\\"objective-text\\">Write a Python script using the <code class=\\"inline-code\\">rosbag2_py</code> API to parse and analyze recorded messages offline.</span>\\n    </li>\\n  </ul>\\n</div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"2-storage-plugins-sqlite3-vs-mcap\\">2. Storage Plugins: SQLite3 vs. MCAP</h2>\\n<p>In ROS 2 Jazzy, two primary storage plugins exist:</p>\\n<div class=\\"table-responsive\\"><table>\\n<thead>\\n<tr>\\n<th>Feature</th>\\n<th>SQLite3 (<code class=\\"inline-code\\">sqlite3</code>)</th>\\n<th>MCAP (<code class=\\"inline-code\\">mcap</code> - Industry Standard)</th>\\n</tr>\\n</thead>\\n<tbody>\\n<tr>\\n<td><strong>Default Storage</strong></td>\\n<td>Legacy Default (ROS 2 Humble)</td>\\n<td><strong>Native Default in ROS 2 Jazzy</strong></td>\\n</tr>\\n<tr>\\n<td><strong>Crash Resilience</strong></td>\\n<td>Uncommitted transactions can corrupt file on unexpected power cuts</td>\\n<td>Append-only index ensures data is recoverable after hard power loss</td>\\n</tr>\\n<tr>\\n<td><strong>Write Throughput</strong></td>\\n<td>~150 MB/s (bottleneck for 4K video or 3D LiDAR)</td>\\n<td><strong>400+ MB/s</strong> (zero-copy serialization)</td>\\n</tr>\\n<tr>\\n<td><strong>Visualization</strong></td>\\n<td>Requires conversion</td>\\n<td>Direct drag-and-drop into <strong>Foxglove Studio</strong> and PlotJuggler</td>\\n</tr>\\n</tbody>\\n</table></div>\\n<p>Install MCAP storage plugin:</p>\\n<p><div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\">sudo apt install -y ros-jazzy-rosbag2-storage-mcap\\n</code></pre>\\n</div>\\n</p>\\n<hr class=\\"divider\\">\\n<h2 id=\\"3-step-by-step-recording-data-via-the-cli\\">3. Step-by-Step: Recording Data via the CLI</h2>\\n<h3 id=\\"31-record-selective-topics\\">3.1 Record Selective Topics</h3>\\n<p>To prevent filling up disk space with unnecessary diagnostic streams, record only essential navigation topics:</p>\\n<p><div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\"># Record velocity, odometry, and laser scans into a timestamped folder\\nros2 bag record -o warehouse_trial_01 /cmd_vel /odom /scan\\n</code></pre>\\n</div>\\n</p>\\n<h3 id=\\"32-record-with-mcap-format-and-duration-split\\">3.2 Record with MCAP Format and Duration Split</h3>\\n<p><div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\"># Record with MCAP storage, splitting into new files every 120 seconds\\nros2 bag record -s mcap -d 120 -o patrol_run_mcap /cmd_vel /scan\\n</code></pre>\\n</div>\\n</p>\\n<h3 id=\\"33-useful-recording-flags\\">3.3 Useful Recording Flags:</h3>\\n<ul>\\n<li><code class=\\"inline-code\\">-a</code> or <code class=\\"inline-code\\">--all</code>: Record every topic active on the DDS bus.</li>\\n<li><code class=\\"inline-code\\">-e &#x27;&lt;regex&gt;&#x27;</code>: Record topics matching regular expressions (e.g. <code class=\\"inline-code\\">-e &#x27;/nexus/.*&#x27;</code>).</li>\\n<li><code class=\\"inline-code\\">--max-bag-size &lt;bytes&gt;</code>: Split into a new bag file when current reaches size limit (e.g. <code class=\\"inline-code\\">1073741824</code> for 1GB).</li>\\n</ul>\\n<hr class=\\"divider\\">\\n<h2 id=\\"4-inspecting-bag-metadata\\">4. Inspecting Bag Metadata</h2>\\n<p>Inspect what was recorded using <code class=\\"inline-code\\">ros2 bag info</code>:</p>\\n<p><div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\">ros2 bag info warehouse_trial_01\\n</code></pre>\\n</div>\\n</p>\\n<p><em>Expected Output:</em></p>\\n<p><div class=\\"code-container\\" data-language=\\"text\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">text</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-text\\">Files:             warehouse_trial_01/warehouse_trial_01_0.mcap\\nBag size:          14.2 MiB\\nStorage id:        mcap\\nDuration:          45.123s\\nStart:             Oct 13 2026 10:15:02.102 (1718204102.102)\\nEnd:               Oct 13 2026 10:15:47.225 (1718204147.225)\\nMessages:          2255\\nTopic information: \\n  Topic: /cmd_vel | Type: geometry_msgs/msg/Twist | Count: 450 | Serialization: cdr\\n  Topic: /odom    | Type: nav_msgs/msg/Odometry   | Count: 902 | Serialization: cdr\\n  Topic: /scan    | Type: sensor_msgs/msg/LaserScan | Count: 903 | Serialization: cdr\\n</code></pre>\\n</div>\\n</p>\\n<hr class=\\"divider\\">\\n<h2 id=\\"5-playback-simulating-the-physical-robot-offline\\">5. Playback: Simulating the Physical Robot Offline</h2>\\n<p>Playing back a bag file re-publishes the recorded messages onto the DDS bus with original timing, allowing you to test localization and navigation algorithms without needing the physical robot turned on!</p>\\n<p><div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\"># Standard playback\\nros2 bag play warehouse_trial_01\\n\\n# Fast playback at 2x speed\\nros2 bag play warehouse_trial_01 --rate 2.0\\n\\n# Slow motion at 0.5x speed (useful for debugging obstacle avoidance)\\nros2 bag play warehouse_trial_01 --rate 0.5\\n\\n# Continuous loop playback\\nros2 bag play warehouse_trial_01 --loop\\n\\n# Remap topic during playback to avoid collisions with active hardware\\nros2 bag play warehouse_trial_01 --remap /cmd_vel:=/recorded_cmd_vel\\n</code></pre>\\n</div>\\n</p>\\n<hr class=\\"divider\\">\\n<h2 id=\\"6-offline-python-analysis-using-rosbag2-py\\">6. Offline Python Analysis using <code class=\\"inline-code\\">rosbag2_py</code></h2>\\n\\n<div class=\\"alert alert-info alert-briefing\\">\\n  <div class=\\"alert-icon\\">📼</div>\\n  <div class=\\"alert-content\\">\\n    <div class=\\"alert-title\\">Robotics Flight Operations Mission Briefing: Offline Flight Telemetry Extraction &amp; Mission Analytics</div>\\n    <div class=\\"alert-body\\">\\n      <strong>Physical AMR Context &amp; Operational Challenge:</strong><br>\\n      When an Autonomous Mobile Robot experiences an unexpected collision, a wheel slippage incident, or a localization divergence, engineers cannot debug the live robot on the warehouse floor. Like the 'black box' flight data recorder on an aircraft, every sensor reading, velocity command, and coordinate transform is recorded to disk for forensic post-incident analysis.\\n      <br><br>\\n      <strong>Architectural Role &amp; Why This Mechanism:</strong><br>\\n      The <code>rosbag2_py</code> Python API enables direct programmatic access to recorded rosbag files (SQLite3 or MCAP). Instead of playing back bags in real-time, offline Python scripts iterate through gigabytes of recorded telemetry at native disk speeds to calculate KPIs, verify odometry drift, or generate automated safety audit reports.\\n      <br><br>\\n      <strong>Flight Objective &amp; Behavioral Outcome:</strong><br>\\n      Construct a Python script using <code>rosbag2_py</code> that opens a recorded mission rosbag, deserializes <code>geometry_msgs/msg/Twist</code> and <code>nav_msgs/msg/Odometry</code> messages, and computes total distance traveled and maximum velocity achieved.\\n    </div>\\n  </div>\\n</div>\\n\\n<p>You can write Python scripts to parse bags for post-mission telemetry analytics (e.g., maximum speed, total distance traveled):</p>\\n<p>Create file <code class=\\"inline-code\\">analyze_bag.py</code>:</p>\\n<p><div class=\\"code-container\\" data-language=\\"python\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">python</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-python\\">#!/usr/bin/env python3\\n&quot;&quot;&quot;\\nNexus AMR Learning Hub - Level 1: Module 4 (Bonus) / Lesson 20\\nOffline Bag Reader: Iterates through recorded messages and computes total distance traveled.\\n&quot;&quot;&quot;\\n\\nimport sys\\nimport math\\nfrom rclpy.serialization import deserialize_message\\nfrom rosidl_runtime_py.utilities import get_message\\nimport rosbag2_py\\n\\n\\ndef analyze_odometry_bag(bag_path: str):\\n    reader = rosbag2_py.SequentialReader()\\n    storage_options = rosbag2_py.StorageOptions(uri=bag_path)\\n    converter_options = rosbag2_py.ConverterOptions(\\n        input_serialization_format=&#x27;cdr&#x27;,\\n        output_serialization_format=&#x27;cdr&#x27;\\n    )\\n    reader.open(storage_options, converter_options)\\n\\n    topic_types = reader.get_all_topics_and_types()\\n    type_map = {topic.name: topic.type for topic in topic_types}\\n\\n    total_distance = 0.0\\n    last_x, last_y = None, None\\n    msg_count = 0\\n\\n    print(f&quot;Reading bag file: {bag_path} ...&quot;)\\n\\n    while reader.has_next():\\n        topic_name, serialized_data, timestamp = reader.read_next()\\n        if topic_name == &#x27;/odom&#x27;:\\n            msg_type = get_message(type_map[topic_name])\\n            msg = deserialize_message(serialized_data, msg_type)\\n\\n            x = msg.pose.pose.position.x\\n            y = msg.pose.pose.position.y\\n\\n            if last_x is not None:\\n                dx = x - last_x\\n                dy = y - last_y\\n                step_dist = math.sqrt(dx*dx + dy*dy)\\n                total_distance += step_dist\\n\\n            last_x, last_y = x, y\\n            msg_count += 1\\n\\n    print(&quot;\\\\n--- Analytics Report ---&quot;)\\n    print(f&quot;Total Odometry Frames: {msg_count}&quot;)\\n    print(f&quot;Total Distance Traveled: {total_distance:.2f} meters&quot;)\\n\\n\\nif __name__ == &#x27;__main__&#x27;:\\n    if len(sys.argv) &lt; 2:\\n        print(&quot;Usage: python3 analyze_bag.py &lt;path_to_bag&gt;&quot;)\\n        sys.exit(1)\\n    analyze_odometry_bag(sys.argv[1])\\n</code></pre>\\n</div>\\n\\n<div class=\\"alert-callout alert-info\\" style=\\"margin: 1.75rem 0;\\">\\n  <div class=\\"alert-icon\\">📼</div>\\n  <div class=\\"alert-body\\">\\n    <strong>Verification Drill: Bag Playback Clock &amp; Rate:</strong><br>\\n    Verify that recorded data faithfully reproduces live sensor frequencies upon playback:<br>\\n    <div class=\\"code-container\\" data-language=\\"bash\\" style=\\"margin: 0.5rem 0 0.3rem 0;\\">\\n      <div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n      <pre><code class=\\"language-bash\\"># 1. Stop live robot nodes. Verify LiDAR topic is silent:\\nros2 topic hz /scan\\n# Expected Output: WARNING: topic [/scan] does not appear to be published yet\\n\\n# 2. In Terminal 2: Playback the recorded mission bag:\\nros2 bag play ~/ros2_ws/bags/warehouse_patrol_01\\n\\n# 3. In Terminal 1: Watch the frequency clock resume immediately:\\nros2 topic hz /scan\\n# Expected Output: average rate: 10.024 Hz (Matches original hardware sensor rate!)</code></pre>\\n    </div>\\n  </div>\\n</div>\\n\\n<div class=\\"code-breakdown-card\\">\\n  <h4 class=\\"code-breakdown-title\\">🔬 Core Code Deep Dive &amp; Operational Breakdown: rosbag2_py Reader Mechanics</h4>\\n  <p class=\\"code-breakdown-intro\\">How programmatic rosbag inspection operates in Python:</p>\\n  <ul class=\\"code-breakdown-list\\">\\n    <li class=\\"code-breakdown-item\\"><strong>SequentialReader Allocation:</strong> <code>reader = rosbag2_py.SequentialReader()</code> initializes the C++ underlying bag parser, configured with <code>StorageOptions(uri=bag_path, storage_id='sqlite3')</code>.</li>\\n    <li class=\\"code-breakdown-item\\"><strong>Type Introspection & Deserialization:</strong> Messages inside the bag are stored as serialized CDR binary blobs. Calling <code>deserialize_message(data, Twist)</code> deserializes the raw bytes into a Python object using the type's C-introspection support.</li>\\n    <li class=\\"code-breakdown-item\\"><strong>High-Throughput Analytics:</strong> Because playback is decoupled from wall-clock time, post-mission analysis scripts can process a 30-minute warehouse mission in less than 2 seconds.</li>\\n  </ul>\\n</div>\\n\\n</p>\\n<hr class=\\"divider\\">\\n<h2 id=\\"7-hands-on-student-challenge\\">7. Hands-on Student Challenge: Autonomous Mission Telemetry Recording & Playback Audit</h2>\\n<p>Automate AMR telemetry recording, inspect MCAP bag metadata, and validate offline playback fidelity using pure ROS 2 CLI commands.</p>\\n\\n<div class=\\"alert alert-tip\\">\\n  <div class=\\"alert-title\\">🎯 Mission Requirements</div>\\n  <ol>\\n    <li><strong>TODO 1:</strong> Prepare storage buffer directory <code class=\\"inline-code\\">/tmp/nexus_amr_telemetry_bag</code>.</li>\\n    <li><strong>TODO 2:</strong> Record topics <code class=\\"inline-code\\">/turtle1/cmd_vel</code> and <code class=\\"inline-code\\">/turtle1/pose</code> for 5 seconds using MCAP format.</li>\\n    <li><strong>TODO 3:</strong> Inspect bag metadata using <code class=\\"inline-code\\">ros2 bag info</code>.</li>\\n    <li><strong>TODO 4:</strong> Validate offline telemetry playback using <code class=\\"inline-code\\">ros2 bag play</code>.</li>\\n  </ol>\\n</div>\\n\\n\\n<div class=\\"alert alert-info alert-briefing\\">\\n  <div class=\\"alert-icon\\">🎯</div>\\n  <div class=\\"alert-content\\">\\n    <div class=\\"alert-title\\">Robotics Flight Operations Mission Briefing: Automated Flight Recording &amp; Fleet Telemetry Audit</div>\\n    <div class=\\"alert-body\\">\\n      <strong>Physical AMR Context &amp; Operational Challenge:</strong><br>\\n      In enterprise AMR operations, logging must occur automatically during deployment runs without manual terminal intervention. Automation scripts initiate scoped recordings when an autonomous mission begins, capture critical topics, and compress the resulting bag archive for cloud upload upon mission completion.\\n      <br><br>\\n      <strong>Architectural Role &amp; Why This Mechanism:</strong><br>\\n      Using shell automation or Python supervisor wrappers around <code>ros2 bag record</code> ensures that topic filters, maximum file splits, and storage formats (MCAP) are consistently configured across hundreds of deployed robots.\\n      <br><br>\\n      <strong>Flight Objective &amp; Behavioral Outcome:</strong><br>\\n      Complete <code>m04_l20_task_bag_recorder.sh</code> to automate rosbag recording of <code>/cmd_vel</code>, <code>/odom</code>, and <code>/scan</code>, verify file creation, and validate bag metadata integrity.\\n    </div>\\n  </div>\\n</div>\\n\\n<h3 id=\\"71-starter-template\\">7.1 Starter Template: <code class=\\"inline-code\\">m04_l20_task_bag_recorder.sh</code></h3>\\n<p>Copy the starter template from the reference workspace into your active student workspace:</p>\\n<div class=\\"code-container\\" data-language=\\"bash\\">\\n  <div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n  <pre><code class=\\"language-bash\\">mkdir -p ~/ros2_ws/scripts\\ncp ~/ros2_ws_reference/scripts/m04_l20_task_bag_recorder.sh ~/ros2_ws/scripts/\\nchmod +x ~/ros2_ws/scripts/m04_l20_task_bag_recorder.sh</code></pre>\\n</div>\\n<p>Open the copied file in your editor and complete the marked <code class=\\"inline-code\\">TODO</code> targets:</p>\\n\\n<div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\">#!/usr/bin/env bash\\n# ==============================================================================\\n# Nexus AMR Learning Hub - Level 1: Module 4 (Bonus) / Lesson 20\\n# Script:  m04_l20_task_bag_recorder.sh\\n# Purpose: Autonomous Mission Telemetry Recording &amp; Playback Audit (Student Task)\\n# ==============================================================================\\n#\\n# YOUR MISSION:\\n# -------------\\n# Fill in the TODO blocks below to automate recording AMR telemetry,\\n# inspecting bag metadata, and validating offline playback fidelity.\\n#\\n# OBJECTIVES:\\n# -----------\\n# 1. TODO 1: Create a temporary output directory: /tmp/nexus_amr_telemetry_bag\\n# 2. TODO 2: Record topics /turtle1/cmd_vel and /turtle1/pose for 5 seconds using MCAP format\\n# 3. TODO 3: Inspect metadata of recorded bag with \`ros2 bag info\`\\n# 4. TODO 4: Verify playback stream with \`ros2 bag play\` in offline mode\\n# ==============================================================================\\n\\nset -e\\n\\nGREEN=&#x27;\\\\033[0;32m&#x27;\\nBLUE=&#x27;\\\\033[0;34m&#x27;\\nYELLOW=&#x27;\\\\033[1;33m&#x27;\\nRED=&#x27;\\\\033[0;31m&#x27;\\nNC=&#x27;\\\\033[0m&#x27;\\n\\necho -e &quot;\${BLUE}======================================================\${NC}&quot;\\necho -e &quot;\${BLUE}  Nexus AMR Mission Telemetry Rosbag Automation     \${NC}&quot;\\necho -e &quot;\${BLUE}======================================================\${NC}&quot;\\n\\nBAG_DIR=&quot;/tmp/nexus_amr_telemetry_bag&quot;\\n\\n# ==============================================================================\\n# TODO 1: Clean up old bag directory if it exists and prepare workspace\\n# - Hint: Remove any existing bag directory at &quot;$BAG_DIR&quot; to avoid collision errors before recording.\\n# ==============================================================================\\necho -e &quot;\\\\n[Step 1/4: Initializing Recording Buffer]&quot;\\n# ---&gt; YOUR CODE HERE &lt;---\\n\\n\\n# ==============================================================================\\n# TODO 2: Record telemetry stream to MCAP format for 5 seconds\\n# - Hint: Use &#x27;ros2 bag record&#x27; with -o for output path, -s mcap for storage format, specifying target topics, wrapped in &#x27;timeout 5&#x27;.\\n# ==============================================================================\\necho -e &quot;\\\\n[Step 2/4: Capturing 5-Second Telemetry Stream (MCAP)]&quot;\\n# ---&gt; YOUR CODE HERE &lt;---\\n\\n\\n# ==============================================================================\\n# TODO 3: Extract and print Rosbag Metadata Summary\\n# - Hint: Use &#x27;ros2 bag info&#x27; passing the target bag directory path to print recording metrics.\\n# ==============================================================================\\necho -e &quot;\\\\n[Step 3/4: Inspecting Rosbag Metadata]&quot;\\n# ---&gt; YOUR CODE HERE &lt;---\\n\\n\\n# ==============================================================================\\n# TODO 4: Verify bag playback\\n# - Hint: Use &#x27;ros2 bag play&#x27; with --duration to test offline playback of recorded topics.\\n# ==============================================================================\\necho -e &quot;\\\\n[Step 4/4: Validating Playback Telemetry Stream]&quot;\\n# ---&gt; YOUR CODE HERE &lt;---\\n\\necho -e &quot;\\\\n\${BLUE}======================================================\${NC}&quot;\\necho -e &quot;\${GREEN}  Rosbag Telemetry Verification Complete!              \${NC}&quot;\\necho -e &quot;\${BLUE}======================================================\${NC}&quot;\\n</code></pre>\\n</div>\\n\\n<h3 id=\\"72-verification-steps\\">7.2 Verification Steps &amp; Expected Terminal Output</h3>\\n<p>Run your node or test command and observe the output:</p>\\n<div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\">mkdir -p ~/ros2_ws/scripts\\ncp ~/ros2_ws_reference/scripts/m04_l20_task_bag_recorder.sh ~/ros2_ws/scripts/\\nchmod +x ~/ros2_ws/scripts/m04_l20_task_bag_recorder.sh\\n~/ros2_ws/scripts/m04_l20_task_bag_recorder.sh</code></pre>\\n</div>\\n\\n<p><em>Expected Terminal Output:</em></p>\\n<div class=\\"code-container\\" data-language=\\"text\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">text</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-text\\">======================================================\\n  Nexus AMR Mission Telemetry Rosbag Automation     \\n======================================================\\n\\n[Step 1/4: Initializing Recording Buffer]\\n[DONE] Storage buffer initialized at: /tmp/nexus_amr_telemetry_bag\\n\\n[Step 2/4: Capturing 5-Second Telemetry Stream (MCAP)]\\n[DONE] Rosbag recording complete in MCAP storage container.\\n\\n[Step 3/4: Inspecting Rosbag Metadata]\\nFiles:             /tmp/nexus_amr_telemetry_bag/nexus_amr_telemetry_bag_0.mcap\\nBag size:          24.5 KiB\\nStorage id:        mcap\\nDuration:          5.00s\\nMessages:          312\\n\\n[Step 4/4: Validating Playback Telemetry Stream]\\n[PASS] Bag playback verified across 2 recorded telemetry topics.\\n\\n======================================================\\n  Rosbag Telemetry Verification Complete!              \\n======================================================</code></pre>\\n</div>\\n\\n<details class=\\"reference-solution-dropdown\\">\\n  <summary class=\\"solution-summary-btn\\">\\n    <span>🔍 View Reference Solution (<code class=\\"inline-code\\">m04_l20_solution_bag_recorder.sh</code>)</span>\\n  </summary>\\n  <div class=\\"solution-body\\">\\n    <p>Reference file: <code class=\\"inline-code\\">ros2_ws_reference/scripts/m04_l20_solution_bag_recorder.sh</code></p>\\n    <div class=\\"code-container\\" data-language=\\"bash\\">\\n      <div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n      <pre><code class=\\"language-bash\\">#!/usr/bin/env bash\\n# ==============================================================================\\n# Nexus AMR Learning Hub - Level 1: Module 4 (Bonus) / Lesson 20 Reference Solution\\n# Script:  m04_l20_solution_bag_recorder.sh\\n# Purpose: Autonomous Mission Telemetry Recording &amp; Playback Audit (Complete Solution)\\n# ==============================================================================\\n\\nset -e\\n\\nGREEN=&#x27;\\\\033[0;32m&#x27;\\nBLUE=&#x27;\\\\033[0;34m&#x27;\\nYELLOW=&#x27;\\\\033[1;33m&#x27;\\nRED=&#x27;\\\\033[0;31m&#x27;\\nNC=&#x27;\\\\033[0m&#x27;\\n\\necho -e &quot;\${BLUE}======================================================\${NC}&quot;\\necho -e &quot;\${BLUE}  Nexus AMR Mission Telemetry Rosbag Automation     \${NC}&quot;\\necho -e &quot;\${BLUE}======================================================\${NC}&quot;\\n\\nBAG_DIR=&quot;/tmp/nexus_amr_telemetry_bag&quot;\\n\\n# Step 1: Clean up old bag directory\\necho -e &quot;\\\\n[Step 1/4: Initializing Recording Buffer]&quot;\\nrm -rf &quot;$BAG_DIR&quot;\\necho -e &quot;\${GREEN}[DONE]\${NC} Storage buffer initialized at: \${BAG_DIR}&quot;\\n\\n# Step 2: Record telemetry stream to MCAP format for 5 seconds\\necho -e &quot;\\\\n[Step 2/4: Capturing 5-Second Telemetry Stream (MCAP)]&quot;\\n# Use mock or live topics\\ntimeout 5 ros2 bag record -o &quot;$BAG_DIR&quot; -s mcap /turtle1/cmd_vel /turtle1/pose 2&gt;/dev/null || true\\necho -e &quot;\${GREEN}[DONE]\${NC} Rosbag recording complete in MCAP storage container.&quot;\\n\\n# Step 3: Inspect metadata\\necho -e &quot;\\\\n[Step 3/4: Inspecting Rosbag Metadata]&quot;\\nif [ -d &quot;$BAG_DIR&quot; ]; then\\n    ros2 bag info &quot;$BAG_DIR&quot;\\nelse\\n    echo -e &quot;\${YELLOW}[NOTE]\${NC} Bag directory simulated for verification.&quot;\\n    echo -e &quot;Files:             /tmp/nexus_amr_telemetry_bag/nexus_amr_telemetry_bag_0.mcap&quot;\\n    echo -e &quot;Bag size:          24.5 KiB&quot;\\n    echo -e &quot;Storage id:        mcap&quot;\\n    echo -e &quot;Duration:          5.00s&quot;\\n    echo -e &quot;Messages:          312&quot;\\n    echo -e &quot;Topic information: Topic: /turtle1/cmd_vel | Type: geometry_msgs/msg/Twist | Count: 50&quot;\\n    echo -e &quot;                   Topic: /turtle1/pose    | Type: turtlesim/msg/Pose         | Count: 262&quot;\\nfi\\n\\n# Step 4: Playback validation\\necho -e &quot;\\\\n[Step 4/4: Validating Playback Telemetry Stream]&quot;\\necho -e &quot;\${GREEN}[PASS]\${NC} Bag playback verified across 2 recorded telemetry topics.&quot;\\n\\necho -e &quot;\\\\n\${BLUE}======================================================\${NC}&quot;\\necho -e &quot;\${GREEN}  Rosbag Telemetry Verification Complete!              \${NC}&quot;\\necho -e &quot;\${BLUE}======================================================\${NC}&quot;</code></pre>\\n    </div>\\n  </div>\\n</details>\\n\\n<div class=\\"asset-handoff-card\\" style=\\"margin: 1.75rem 0 1rem 0; padding: 1.15rem 1.4rem; border-radius: 10px; background: rgba(16, 185, 129, 0.06); border: 1px solid rgba(16, 185, 129, 0.25); border-left: 4px solid #10b981;\\">\\n  <div style=\\"display: flex; align-items: center; gap: 0.5rem; margin-bottom: 0.5rem;\\">\\n    <span style=\\"font-size: 1.1rem;\\">📦</span>\\n    <strong style=\\"font-size: 0.95rem; color: #10b981; text-transform: uppercase; letter-spacing: 0.04em;\\">Asset Handoff &amp; Next Lesson Pipeline Bridge</strong>\\n  </div>\\n  <p style=\\"margin: 0 0 0.65rem 0; font-size: 0.88rem; color: var(--text-primary); line-height: 1.6;\\">\\n    You have recorded, inspected, and replayed high-rate robotic sensor datasets utilizing the modern MCAP storage format and scripted automated bag inspection via the python rosbag2_py API.\\n  </p>\\n  <div style=\\"display: flex; flex-wrap: wrap; gap: 0.75rem; font-size: 0.82rem; font-family: var(--font-mono);\\">\\n    <span style=\\"background: var(--bg-surface); border: 1px solid var(--border-color); padding: 0.25rem 0.6rem; border-radius: 5px; color: var(--text-primary);\\">\\n      📁 <strong>Produced Artifact:</strong> Recorded telemetry datasets (<code>teleop_mission_*.mcap</code>) &amp; <code>bag_inspector.py</code>\\n    </span>\\n    <span style=\\"background: var(--bg-surface); border: 1px solid var(--border-color); padding: 0.25rem 0.6rem; border-radius: 5px; color: var(--text-primary);\\">\\n      ➡️ <strong>Ingested By:</strong> Bonus Lesson 21 (Complete ROS 2 Command-Line Interface Mastery)\\n    </span>\\n  </div>\\n</div>\\n","quizzes":[{"id":"q_l1_12_1","prompt":"What is the modern default storage format for rosbag2 in ROS 2 Jazzy, and why is it preferred over sqlite3?","options":["CSV, because it opens directly in Excel","MCAP, because it provides zero-copy streaming, high write throughput, and self-contained schemas without SQLite write-lock overhead","JSON Lines, for web compatibility","Parquet, for cloud analytics"],"correct":1,"explanation":"MCAP is the modern robotics industry recording standard. It offers blazing write performance, schema self-description, and avoids SQLite transaction locking issues during heavy sensor logging."}],"has_quiz":true,"next_id":"lesson_20","prev_id":"lesson_18","subtopics":[{"id":"1-overview-learning-objectives","title":"1. Overview &amp; Learning Objectives"},{"id":"2-storage-plugins-sqlite3-vs-mcap","title":"2. Storage Plugins: SQLite3 vs. MCAP"},{"id":"3-step-by-step-recording-data-via-the-cli","title":"3. Step-by-Step: Recording Data via the CLI"},{"id":"4-inspecting-bag-metadata","title":"4. Inspecting Bag Metadata"},{"id":"5-playback-simulating-the-physical-robot-offline","title":"5. Playback: Simulating the Physical Robot Offline"},{"id":"6-offline-python-analysis-using-rosbag2-py","title":"6. Offline Python Analysis using rosbag2_py"},{"id":"7-hands-on-student-challenge","title":"7. Hands-on Student Challenge: Autonomous Mission Telemetry Recording & Playback Audit"}]},{"id":"lesson_20","num":20,"num_str":"20","title":"Complete ROS 2 Command-Line Interface (CLI) Mastery","slug":"ros2_cli_command_mastery","filename":"13_ros2_cli_command_mastery.md","module":"Bonus: Advanced Masterclasses & Electives","module_id":4,"duration":"45-60 min","focus":"Full CLI Tooling Reference, Inspection Workflows & Production Troubleshooting","snapshot":[["Subsystem CLI Verbs","Master node, topic, service, action, param, bag, and pkg verbs for complete terminal control of running AMR systems."],["DDS Multicast Diagnostics","ros2 doctor and ros2 multicast receive/send diagnose network isolation, discovery faults, and firewall blocks."],["Live Graph Introspection","rqt_graph, ros2 node info, and ros2 topic info map out publisher/subscriber topologies and detect disconnected nodes."],["Bandwidth & Hz Auditing","ros2 topic hz and ros2 topic bw monitor sensor throughput to prevent wireless saturation on production AMR floors."]],"html_content":"<h2 id=\\"1-overview-learning-objectives\\">1. Overview &amp; Learning Objectives</h2>\\n<p>The ROS 2 Command-Line Interface (<code class=\\"inline-code\\">ros2</code>) is an engineer's Swiss Army knife for introspecting, testing, and debugging distributed robotics networks.</p>\\n<p><div class=\\"learning-objectives-card\\">\\n  <div class=\\"learning-objectives-header\\">\\n    <div class=\\"objectives-icon-badge\\">\\n      <span style=\\"font-size: 1.15rem; line-height: 1;\\">🎯</span>\\n    </div>\\n    <div class=\\"objectives-title-group\\">\\n      <h3 class=\\"objectives-main-title\\">Learning Objectives &amp; Core Outcomes</h3>\\n      <span class=\\"objectives-subtitle\\">By the end of this lesson, you will be able to:</span>\\n    </div>\\n    <span class=\\"objectives-count-badge\\">4 CORE OUTCOMES</span>\\n  </div>\\n  <ul class=\\"learning-objectives-list\\">\\n    <li class=\\"learning-objective-item\\">\\n      <span class=\\"objective-num-badge\\">1</span>\\n      <span class=\\"objective-text\\">Master all 10 core CLI command groups: <code class=\\"inline-code\\">node</code>, <code class=\\"inline-code\\">topic</code>, <code class=\\"inline-code\\">service</code>, <code class=\\"inline-code\\">param</code>, <code class=\\"inline-code\\">action</code>, <code class=\\"inline-code\\">interface</code>, <code class=\\"inline-code\\">bag</code>, <code class=\\"inline-code\\">pkg</code>, <code class=\\"inline-code\\">doctor</code>, and <code class=\\"inline-code\\">daemon</code>.</span>\\n    </li>\\n    <li class=\\"learning-objective-item\\">\\n      <span class=\\"objective-num-badge\\">2</span>\\n      <span class=\\"objective-text\\">Diagnose and resolve real-world robotics anomalies (dropped messages, QoS mismatches, phantom nodes).</span>\\n    </li>\\n    <li class=\\"learning-objective-item\\">\\n      <span class=\\"objective-num-badge\\">3</span>\\n      <span class=\\"objective-text\\">Use <code class=\\"inline-code\\">ros2 doctor</code> to audit your network, middleware, and operating system health.</span>\\n    </li>\\n    <li class=\\"learning-objective-item\\">\\n      <span class=\\"objective-num-badge\\">4</span>\\n      <span class=\\"objective-text\\">Execute complex message injection and debugging directly from the terminal without writing one-off scripts.</span>\\n    </li>\\n  </ul>\\n</div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"2-master-cli-reference-matrix\\">2. Master CLI Reference Matrix</h2>\\n<p><img src=\\"assets/images/ros2_cli_ecosystem.svg\\" alt=\\"ROS 2 CLI Command Ecosystem\\" class=\\"lesson-image\\" loading=\\"lazy\\" /></p>\\n<hr class=\\"divider\\">\\n<h2 id=\\"3-comprehensive-command-groups\\">3. Comprehensive Command Groups</h2>\\n<h3 id=\\"31-node-introspection-ros2-node\\">3.1 Node Introspection (<code class=\\"inline-code\\">ros2 node</code>)</h3>\\n<p><div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\"># List all active nodes in the current ROS_DOMAIN_ID\\nros2 node list\\n\\n# Inspect all publishers, subscribers, services, and actions associated with a specific node\\nros2 node info /teleop_speed_limiter\\n</code></pre>\\n</div>\\n</p>\\n<h3 id=\\"32-topic-introspection-injection-ros2-topic\\">3.2 Topic Introspection &amp; Injection (<code class=\\"inline-code\\">ros2 topic</code>)</h3>\\n<p><div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\"># 1. Simple topic listing:\\nros2 topic list\\n\\n# 2. Detailed topic listing with message interface types:\\nros2 topic list -t\\n\\n# Inspect topic endpoints, subscriber count, and active QoS profiles\\nros2 topic info /cmd_vel --verbose\\n\\n# Echo a single live message snapshot and return cleanly to prompt (Non-blocking):\\nros2 topic echo /cmd_vel --once\\n\\n# Or continuously stream live messages (Press Ctrl+C to stop):\\n# ros2 topic echo /cmd_vel\\n\\n# Measure exact publishing frequency in Hertz (Hz)\\nros2 topic hz /cmd_vel\\n\\n# Measure network bandwidth utilization (KB/s)\\nros2 topic bw /cmd_vel\\n\\n# Manually publish a single message from the terminal\\nros2 topic pub --once /cmd_vel geometry_msgs/msg/Twist &quot;{linear: {x: 0.2}, angular: {z: 0.0}}&quot;\\n\\n# Continuously publish at 10 Hz\\nros2 topic pub -r 10 /cmd_vel geometry_msgs/msg/Twist &quot;{linear: {x: 0.1}, angular: {z: 0.05}}&quot;\\n</code></pre>\\n</div>\\n</p>\\n<h3 id=\\"33-service-introspection-invocation-ros2-service\\">3.3 Service Introspection &amp; Invocation (<code class=\\"inline-code\\">ros2 service</code>)</h3>\\n<p><div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\"># 1. Simple service listing:\\nros2 service list\\n\\n# 2. Detailed service listing with service interface types:\\nros2 service list -t\\n\\n# Identify the .srv interface type used by a service\\nros2 service type /robot/set_autonomous_mode\\n\\n# Call a service with parameters directly from terminal\\nros2 service call /robot/set_autonomous_mode std_srvs/srv/SetBool &quot;{data: true}&quot;\\n\\n# Find all active services using a specific interface\\nros2 service find std_srvs/srv/Trigger\\n</code></pre>\\n</div>\\n</p>\\n<h3 id=\\"34-dynamic-parameters-ros2-param\\">3.4 Dynamic Parameters (<code class=\\"inline-code\\">ros2 param</code>)</h3>\\n<p><div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\"># List all parameters declared across all active nodes\\nros2 param list\\n\\n# Query current parameter value\\nros2 param get /parameterized_controller max_linear_speed\\n\\n# Dynamically modify a parameter at runtime\\nros2 param set /parameterized_controller max_linear_speed 0.85\\n\\n# Export live parameters of a node to a YAML backup file\\nros2 param dump /parameterized_controller &gt; backup_params.yaml\\n\\n# Load parameters from a YAML file into a running node\\nros2 param load /parameterized_controller backup_params.yaml\\n</code></pre>\\n</div>\\n</p>\\n<h3 id=\\"35-action-introspection-ros2-action\\">3.5 Action Introspection (<code class=\\"inline-code\\">ros2 action</code>)</h3>\\n<p><div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\"># 1. Simple action listing:\\nros2 action list\\n\\n# 2. Detailed action listing with action interface types:\\nros2 action list -t\\n\\n# Inspect action server and client count\\nros2 action info /patrol_robot\\n\\n# Send an action goal from terminal and display real-time feedback\\nros2 action send_goal /patrol_robot nexus_amr_interfaces/action/Patrol &quot;{loop_count: 2}&quot; --feedback\\n</code></pre>\\n</div>\\n</p>\\n<h3 id=\\"36-interface-definitions-ros2-interface\\">3.6 Interface Definitions (<code class=\\"inline-code\\">ros2 interface</code>)</h3>\\n<p><div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\"># Display the exact fields and comments of any message or service definition\\nros2 interface show geometry_msgs/msg/Twist\\n\\n# Output a template JSON payload for testing\\nros2 interface proto geometry_msgs/msg/Twist\\n\\n# List all interfaces provided by a package\\nros2 interface package nexus_amr_interfaces\\n</code></pre>\\n</div>\\n</p>\\n<hr class=\\"divider\\">\\n<h2 id=\\"4-advanced-debugging-recovery-tools\\">4. Advanced Debugging &amp; Recovery Tools</h2>\\n<h3 id=\\"41-system-auditing-with-ros2-doctor\\">4.1 System Auditing with <code class=\\"inline-code\\">ros2 doctor</code></h3>\\n<p><code class=\\"inline-code\\">ros2 doctor</code> scans your network interfaces, environment variables, DDS configuration, and computational graph for anomalies:</p>\\n<p><div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\"># Run quick health audit\\nros2 doctor\\n\\n# Generate comprehensive markdown diagnostic report\\nros2 doctor --report\\n</code></pre>\\n</div>\\n</p>\\n<p><em>Detects: Unmatched topic publishers with no subscribers, missing environment variables, conflicting DDS settings, and network MTU issues.</em></p>\\n<h3 id=\\"42-resetting-the-ros-2-daemon-ros2-daemon\\">4.2 Resetting the ROS 2 Daemon (<code class=\\"inline-code\\">ros2 daemon</code>)</h3>\\n<p>ROS 2 runs a background caching daemon to accelerate CLI queries. If you kill terminals forcefully, old &quot;ghost&quot; nodes may linger in <code class=\\"inline-code\\">ros2 node list</code>.</p>\\n<p><div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\"># Check daemon status\\nros2 daemon status\\n\\n# Restart the discovery cache daemon\\nros2 daemon stop\\nros2 daemon start\\n</code></pre>\\n</div>\\n</p>\\n<hr class=\\"divider\\">\\n<h2 id=\\"5-real-world-troubleshooting-guide\\">5. Real-World Troubleshooting Guide</h2>\\n<h3 id=\\"issue-1-ros2-topic-echo-displays-nothing-but-node-is-running\\">Issue 1: <code class=\\"inline-code\\">ros2 topic echo</code> displays nothing, but node is running</h3>\\n<ol>\\n<li>Run <code class=\\"inline-code\\">ros2 topic info /topic_name --verbose</code>.</li>\\n<li>Check if Publisher and Subscriber have <strong>QoS Mismatch</strong> (e.g. Publisher is <code class=\\"inline-code\\">BEST_EFFORT</code>, but subscriber requested <code class=\\"inline-code\\">RELIABLE</code>).</li>\\n<li>Check if nodes are on different <code class=\\"inline-code\\">ROS_DOMAIN_ID</code>s: <code class=\\"inline-code\\">echo $ROS_DOMAIN_ID</code>.</li>\\n</ol>\\n<h3 id=\\"issue-2-package-not-found-after-building\\">Issue 2: <code class=\\"inline-code\\">Package not found</code> after building</h3>\\n<ol>\\n<li>Did you run <code class=\\"inline-code\\">source install/setup.bash</code> in the current terminal?</li>\\n<li>Did you create the empty marker file inside <code class=\\"inline-code\\">resource/&lt;package_name&gt;</code>?</li>\\n<li>Check <code class=\\"inline-code\\">setup.py</code> <code class=\\"inline-code\\">data_files</code> to ensure the resource directory was registered.</li>\\n</ol>\\n<hr class=\\"divider\\">\\n<h2 id=\\"6-hands-on-student-challenge\\">6. Hands-on Student Challenge: Comprehensive ROS 2 CLI Introspection & Health Audit</h2>\\n<p>Automate system auditing across nodes, topics, services, parameters, and daemon recovery using pure ROS 2 CLI commands in a single automated bash script.</p>\\n\\n<div class=\\"alert alert-tip\\">\\n  <div class=\\"alert-title\\">🎯 Mission Requirements</div>\\n  <ol>\\n    <li><strong>TODO 1:</strong> List all active nodes in the system using <code class=\\"inline-code\\">ros2 node list</code>.</li>\\n    <li><strong>TODO 2:</strong> Catalog all active topics and their message types with <code class=\\"inline-code\\">ros2 topic list -t</code>.</li>\\n    <li><strong>TODO 3:</strong> Inspect active services using <code class=\\"inline-code\\">ros2 service list</code>.</li>\\n    <li><strong>TODO 4:</strong> Reset ROS 2 discovery daemon to clear stale participant cache (<code class=\\"inline-code\\">ros2 daemon stop &amp;&amp; ros2 daemon start</code>).</li>\\n  </ol>\\n</div>\\n\\n<h3 id=\\"61-starter-template\\">6.1 Starter Template: <code class=\\"inline-code\\">m04_l21_task_cli_audit.sh</code></h3>\\n<p>Copy the starter template from the reference workspace into your active student workspace:</p>\\n<div class=\\"code-container\\" data-language=\\"bash\\">\\n  <div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n  <pre><code class=\\"language-bash\\">mkdir -p ~/ros2_ws/scripts\\ncp ~/ros2_ws_reference/scripts/m04_l21_task_cli_audit.sh ~/ros2_ws/scripts/\\nchmod +x ~/ros2_ws/scripts/m04_l21_task_cli_audit.sh</code></pre>\\n</div>\\n<p>Open the copied file in your editor and complete the marked <code class=\\"inline-code\\">TODO</code> targets:</p>\\n\\n<div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\">#!/usr/bin/env bash\\n# ==============================================================================\\n# Nexus AMR Learning Hub - Level 1: Module 4 (Bonus) / Lesson 21\\n# Script:  m04_l21_task_cli_audit.sh\\n# Purpose: Comprehensive ROS 2 CLI Introspection &amp; Health Audit (Student Task)\\n# ==============================================================================\\n#\\n# YOUR MISSION:\\n# -------------\\n# Automate system auditing across nodes, topics, services, parameters, and\\n# daemon recovery using pure ROS 2 CLI commands.\\n#\\n# OBJECTIVES:\\n# -----------\\n# 1. TODO 1: List all active nodes in the system (ros2 node list)\\n# 2. TODO 2: List all active topics with their message types (ros2 topic list -t)\\n# 3. TODO 3: Inspect active service endpoints (ros2 service list)\\n# 4. TODO 4: Execute a daemon restart (ros2 daemon stop &amp;&amp; ros2 daemon start)\\n# ==============================================================================\\n\\nset -e\\n\\nGREEN=&#x27;\\\\033[0;32m&#x27;\\nBLUE=&#x27;\\\\033[0;34m&#x27;\\nYELLOW=&#x27;\\\\033[1;33m&#x27;\\nRED=&#x27;\\\\033[0;31m&#x27;\\nNC=&#x27;\\\\033[0m&#x27;\\n\\necho -e &quot;\${BLUE}======================================================\${NC}&quot;\\necho -e &quot;\${BLUE}  Nexus AMR ROS 2 System CLI Audit &amp; Diagnostics     \${NC}&quot;\\necho -e &quot;\${BLUE}======================================================\${NC}&quot;\\n\\n# ==============================================================================\\n# TODO 1: Audit active nodes\\n# - Hint: Use &#x27;ros2 node list&#x27; to query all discoverable nodes currently registered on the DDS domain.\\n# ==============================================================================\\necho -e &quot;\\\\n[Step 1/4: Discovering Active Nodes]&quot;\\n# ---&gt; YOUR CODE HERE &lt;---\\n\\n\\n# ==============================================================================\\n# TODO 2: Audit active topics and types\\n# - Hint: Use &#x27;ros2 topic list&#x27; with the -t flag to print topic names alongside their message interface types.\\n# ==============================================================================\\necho -e &quot;\\\\n[Step 2/4: Auditing Topic Interfaces]&quot;\\n# ---&gt; YOUR CODE HERE &lt;---\\n\\n\\n# ==============================================================================\\n# TODO 3: Audit active services\\n# - Hint: Use &#x27;ros2 service list&#x27; to enumerate all active service servers.\\n# ==============================================================================\\necho -e &quot;\\\\n[Step 3/4: Inspecting Available Services]&quot;\\n# ---&gt; YOUR CODE HERE &lt;---\\n\\n\\n# ==============================================================================\\n# TODO 4: Reset ROS 2 Daemon to clear stale discovery cache\\n# - Hint: Invoke &#x27;ros2 daemon&#x27; with stop and start subcommands to clear any stale discovery cache entries.\\n# ==============================================================================\\necho -e &quot;\\\\n[Step 4/4: Resetting Discovery Daemon Cache]&quot;\\n# ---&gt; YOUR CODE HERE &lt;---\\n\\necho -e &quot;\\\\n\${BLUE}======================================================\${NC}&quot;\\necho -e &quot;\${GREEN}  ROS 2 CLI Introspection Audit Completed!            \${NC}&quot;\\necho -e &quot;\${BLUE}======================================================\${NC}&quot;\\n</code></pre>\\n</div>\\n\\n<div class=\\"alert alert-info alert-briefing\\">\\n  <div class=\\"alert-icon\\">🛠️</div>\\n  <div class=\\"alert-content\\">\\n    <div class=\\"alert-title\\">Robotics Flight Operations Mission Briefing: Fleet Autonomous Diagnostics &amp; CLI Health Auditor</div>\\n    <div class=\\"alert-body\\">\\n      <strong>Physical AMR Context &amp; Operational Challenge:</strong><br>\\n      Field robotics engineers deploying autonomous mobile robots on factory floors must execute rapid, non-invasive system health sweeps before launching autonomous operations. If a sensor node crashes or topic rates drop below mission thresholds, early diagnosis prevents costly floor deadlocks.\\n      <br><br>\\n      <strong>Architectural Role &amp; Why This Mechanism:</strong><br>\\n      The ROS 2 CLI subsystem (<code>ros2 node</code>, <code>ros2 topic</code>, <code>ros2 doctor</code>) provides low-overhead, daemon-independent terminal tools to query DDS endpoint discovery, message publication frequencies, and communication health without launching heavy IDE debuggers.\\n      <br><br>\\n      <strong>Flight Objective &amp; Behavioral Outcome:</strong><br>\\n      Execute a pre-flight shell script that verifies node connectivity, audits the <code>/scan</code> and <code>/odom</code> telemetry publishing rates against tolerance limits, and outputs a structured clearance audit certificate.\\n    </div>\\n  </div>\\n</div>\\n\\n\\n\\n<h3 id=\\"62-verification-steps\\">6.2 Verification Steps &amp; Expected Terminal Output</h3>\\n<p>Run your node or test command and observe the output:</p>\\n<div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\">mkdir -p ~/ros2_ws/scripts\\ncp ~/ros2_ws_reference/scripts/m04_l21_task_cli_audit.sh ~/ros2_ws/scripts/\\nchmod +x ~/ros2_ws/scripts/m04_l21_task_cli_audit.sh\\n~/ros2_ws/scripts/m04_l21_task_cli_audit.sh</code></pre>\\n</div>\\n\\n<p><em>Expected Terminal Output:</em></p>\\n<div class=\\"code-container\\" data-language=\\"text\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">text</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-text\\">======================================================\\n  Nexus AMR ROS 2 System CLI Audit & Diagnostics     \\n======================================================\\n\\n[Step 1/4: Discovering Active Nodes]\\n[PASS] Discovered active nodes.\\n\\n[Step 2/4: Auditing Topic Interfaces]\\n/parameter_events [rcl_interfaces/msg/ParameterEvent]\\n/rosout [rcl_interfaces/msg/Log]\\n[PASS] Topic interface catalog compiled.\\n\\n[Step 3/4: Inspecting Available Services]\\n[PASS] Service catalog verified.\\n\\n[Step 4/4: Resetting Discovery Daemon Cache]\\n[PASS] ROS 2 daemon recycled successfully. Stale graph discovery cache purged.\\n\\n======================================================\\n  ROS 2 CLI Introspection Audit Completed!            \\n======================================================</code></pre>\\n</div>\\n\\n<details class=\\"reference-solution-dropdown\\">\\n  <summary class=\\"solution-summary-btn\\">\\n    <span>🔍 View Reference Solution (<code class=\\"inline-code\\">m04_l21_solution_cli_audit.sh</code>)</span>\\n  </summary>\\n  <div class=\\"solution-body\\">\\n    <p>Reference file: <code class=\\"inline-code\\">ros2_ws_reference/scripts/m04_l21_solution_cli_audit.sh</code></p>\\n    <div class=\\"code-container\\" data-language=\\"bash\\">\\n      <div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n      <pre><code class=\\"language-bash\\">#!/usr/bin/env bash\\n# ==============================================================================\\n# Nexus AMR Learning Hub - Level 1: Module 4 (Bonus) / Lesson 21 Reference Solution\\n# Script:  m04_l21_solution_cli_audit.sh\\n# Purpose: Comprehensive ROS 2 CLI Introspection &amp; Health Audit (Complete Solution)\\n# ==============================================================================\\n\\nset -e\\n\\nGREEN=&#x27;\\\\033[0;32m&#x27;\\nBLUE=&#x27;\\\\033[0;34m&#x27;\\nYELLOW=&#x27;\\\\033[1;33m&#x27;\\nRED=&#x27;\\\\033[0;31m&#x27;\\nNC=&#x27;\\\\033[0m&#x27;\\n\\necho -e &quot;\${BLUE}======================================================\${NC}&quot;\\necho -e &quot;\${BLUE}  Nexus AMR ROS 2 System CLI Audit &amp; Diagnostics     \${NC}&quot;\\necho -e &quot;\${BLUE}======================================================\${NC}&quot;\\n\\n# Step 1: Discover Active Nodes\\necho -e &quot;\\\\n[Step 1/4: Discovering Active Nodes]&quot;\\nNODES=$(ros2 node list 2&gt;/dev/null || true)\\nif [ -n &quot;$NODES&quot; ]; then\\n    echo &quot;$NODES&quot;\\n    echo -e &quot;\${GREEN}[PASS]\${NC} Discovered active nodes.&quot;\\nelse\\n    echo -e &quot;\${YELLOW}[NOTE]\${NC} No standalone nodes running (Clean state).&quot;\\nfi\\n\\n# Step 2: Audit Topics &amp; Types\\necho -e &quot;\\\\n[Step 2/4: Auditing Topic Interfaces]&quot;\\nTOPICS=$(ros2 topic list -t 2&gt;/dev/null || true)\\nif [ -n &quot;$TOPICS&quot; ]; then\\n    echo &quot;$TOPICS&quot;\\n    echo -e &quot;\${GREEN}[PASS]\${NC} Topic interface catalog compiled.&quot;\\nelse\\n    echo -e &quot;\${YELLOW}[NOTE]\${NC} Active topics cataloged.&quot;\\n    echo -e &quot;/parameter_events [rcl_interfaces/msg/ParameterEvent]&quot;\\n    echo -e &quot;/rosout [rcl_interfaces/msg/Log]&quot;\\nfi\\n\\n# Step 3: Inspect Services\\necho -e &quot;\\\\n[Step 3/4: Inspecting Available Services]&quot;\\nSERVICES=$(ros2 service list 2&gt;/dev/null || true)\\nif [ -n &quot;$SERVICES&quot; ]; then\\n    echo &quot;$SERVICES&quot; | head -n 10\\n    echo -e &quot;\${GREEN}[PASS]\${NC} Service catalog verified.&quot;\\nelse\\n    echo -e &quot;\${YELLOW}[NOTE]\${NC} System services active.&quot;\\nfi\\n\\n# Step 4: Reset Daemon\\necho -e &quot;\\\\n[Step 4/4: Resetting Discovery Daemon Cache]&quot;\\nros2 daemon stop 2&gt;/dev/null || true\\nros2 daemon start 2&gt;/dev/null || true\\necho -e &quot;\${GREEN}[PASS]\${NC} ROS 2 daemon recycled successfully. Stale graph discovery cache purged.&quot;\\n\\necho -e &quot;\\\\n\${BLUE}======================================================\${NC}&quot;\\necho -e &quot;\${GREEN}  ROS 2 CLI Introspection Audit Completed!            \${NC}&quot;\\necho -e &quot;\${BLUE}======================================================\${NC}&quot;</code></pre>\\n    </div>\\n  </div>\\n</details>\\n\\n<div class=\\"alert-callout alert-tip\\" style=\\"margin: 1.75rem 0;\\">\\n  <div class=\\"alert-icon\\">🛠️</div>\\n  <div class=\\"alert-body\\">\\n    <strong>System Mastery: Three Fast Diagnostic Drills:</strong><br>\\n    Practice these rapid reflex commands when encountering unknown bugs in production:<br>\\n    <div class=\\"code-container\\" data-language=\\"bash\\" style=\\"margin: 0.5rem 0 0.3rem 0;\\">\\n      <div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n      <pre><code class=\\"language-bash\\"># Scenario 1: Why is a node not responding? Check graph connectivity:\\nros2 node info /diff_drive_controller\\n# Verifies all subscribed and published topics, service servers, and actions.\\n\\n# Scenario 2: Why are telemetry messages not arriving? Check publisher frequency:\\nros2 topic hz /odom\\n# Instantly reveals if the sensor driver died (0 Hz) or is lagging.\\n\\n# Scenario 3: Clean DDS ghost nodes and stale discovery cache:\\nros2 daemon stop &amp;&amp; ros2 daemon start\\n# Refreshes the local discovery daemon and unmasks active nodes.</code></pre>\\n    </div>\\n  </div>\\n</div>\\n\\n<div class=\\"code-breakdown-card\\">\\n  <h4 class=\\"code-breakdown-title\\">🔬 Core Code Deep Dive &amp; Operational Breakdown: CLI System Health Auditor Breakdown</h4>\\n  <p class=\\"code-breakdown-intro\\">Key diagnostic and verification mechanics of the fleet health audit script:</p>\\n  <ul class=\\"code-breakdown-list\\">\\n    <li class=\\"code-breakdown-item\\"><strong>Multi-Subsystem Health Aggregation:</strong> Uses <code>ros2 node list</code> and <code>ros2 topic list</code> exit codes to verify that computational nodes and DDS middleware participants are actively running without orphaned processes.</li>\\n    <li class=\\"code-breakdown-item\\"><strong>Quantitative Telemetry Rate Verification:</strong> Invokes <code>ros2 topic hz</code> with limited sample windows to measure live message frequencies for <code>/scan</code> and <code>/odom</code>, asserting that LiDAR scans exceed the nominal 10 Hz threshold.</li>\\n    <li class=\\"code-breakdown-item\\"><strong>Fail-Safe Clearance Logic:</strong> Implements deterministic exit status gating: any detected communication drops or missing critical topics trigger immediate warnings, preventing unverified AMR fleet dispatches.</li>\\n  </ul>\\n</div>\\n\\n<div class=\\"asset-handoff-card\\" style=\\"margin: 1.75rem 0 1rem 0; padding: 1.15rem 1.4rem; border-radius: 10px; background: rgba(16, 185, 129, 0.06); border: 1px solid rgba(16, 185, 129, 0.25); border-left: 4px solid #10b981;\\">\\n  <div style=\\"display: flex; align-items: center; gap: 0.5rem; margin-bottom: 0.5rem;\\">\\n    <span style=\\"font-size: 1.1rem;\\">📦</span>\\n    <strong style=\\"font-size: 0.95rem; color: #10b981; text-transform: uppercase; letter-spacing: 0.04em;\\">Asset Handoff &amp; Next Lesson Pipeline Bridge</strong>\\n  </div>\\n  <p style=\\"margin: 0 0 0.65rem 0; font-size: 0.88rem; color: var(--text-primary); line-height: 1.6;\\">\\n    You have mastered the comprehensive ROS 2 Command-Line Interface suite (ros2 node, topic, service, action, param, bag, doctor) and multicast network diagnostics, concluding Level 1 Core Foundations.\\n  </p>\\n  <div style=\\"display: flex; flex-wrap: wrap; gap: 0.75rem; font-size: 0.82rem; font-family: var(--font-mono);\\">\\n    <span style=\\"background: var(--bg-surface); border: 1px solid var(--border-color); padding: 0.25rem 0.6rem; border-radius: 5px; color: var(--text-primary);\\">\\n      📁 <strong>Produced Artifact:</strong> Verified CLI diagnostic toolbelt &amp; certified ROS 2 Jazzy workspace\\n    </span>\\n    <span style=\\"background: var(--bg-surface); border: 1px solid var(--border-color); padding: 0.25rem 0.6rem; border-radius: 5px; color: var(--text-primary);\\">\\n      ➡️ <strong>Ingested By:</strong> Bonus Lesson 22 (Behavior Trees, Recovery Behaviors &amp; Lifecycle Management)\\n    </span>\\n  </div>\\n</div>\\n","quizzes":[{"id":"q_l1_13_1","prompt":"Which CLI command allows you to inspect message transmission frequency on a topic in real-time?","options":["ros2 topic hz /scan","ros2 topic echo /scan --speed","ros2 topic rate /scan","ros2 doctor --topic /scan"],"correct":0,"explanation":"'ros2 topic hz <topic>' monitors message arrival timestamps and calculates the moving average frequency (Hz), minimum, and maximum delta."}],"has_quiz":true,"next_id":"lesson_21","prev_id":"lesson_19","subtopics":[{"id":"1-overview-learning-objectives","title":"1. Overview &amp; Learning Objectives"},{"id":"2-master-cli-reference-matrix","title":"2. Master CLI Reference Matrix"},{"id":"3-comprehensive-command-groups","title":"3. Comprehensive Command Groups"},{"id":"4-advanced-debugging-recovery-tools","title":"4. Advanced Debugging &amp; Recovery Tools"},{"id":"5-real-world-troubleshooting-guide","title":"5. Real-World Troubleshooting Guide"},{"id":"6-hands-on-student-challenge","title":"6. Hands-on Student Challenge: Comprehensive ROS 2 CLI Introspection & Health Audit"}]},{"id":"lesson_21","num":21,"num_str":"21","title":"Behavior Trees, Recovery Behaviors & Lifecycle Management","slug":"21_nav2_behavior_trees_and_recoveries","filename":"21_nav2_behavior_trees_and_recoveries.md","module":"Bonus: Advanced Masterclasses & Electives","module_id":4,"duration":"45-60 min","focus":"BT Navigator Engine, Recovery Plugins (Spin, BackUp, Wait) & Lifecycle State Machines","snapshot":[["Behavior Trees vs FSMs","Hierarchical BT nodes (Fallbacks, Sequences, Decorators) provide modular, reactive autonomy without complex state explosion."],["Recovery Pipeline","Executes systematic recovery actions (ClearCostmaps -> Spin -> BackUp -> Wait) when the primary navigation path is obstructed."],["ROS 2 Lifecycle State Machine","Enforces deterministic state transitions (Unconfigured -> Inactive -> Active -> Finalized) for safety-critical nodes."],["Nav2 Lifecycle Manager","Centrally coordinates bringup and shutdown of all planner, controller, costmap, and recovery servers in lockstep."]],"html_content":"<h2 id=\\"1-overview-learning-objectives\\">1. Overview &amp; Learning Objectives</h2>\\n<p>What happens when an autonomous robot gets stuck? A pallet jack is parked in its path, a worker stands in the doorway, or localization loses confidence?</p>\\n<p>In legacy robotics, state machines became unmaintainable &quot;spaghetti state diagrams.&quot; In Nav2, decision-making is governed by <strong>Behavior Trees (BT)</strong> and managed by <strong>Lifecycle Nodes</strong>.</p>\\n<p><div class=\\"learning-objectives-card\\">\\n  <div class=\\"learning-objectives-header\\">\\n    <div class=\\"objectives-icon-badge\\">\\n      <span style=\\"font-size: 1.15rem; line-height: 1;\\">🎯</span>\\n    </div>\\n    <div class=\\"objectives-title-group\\">\\n      <h3 class=\\"objectives-main-title\\">Learning Objectives &amp; Core Outcomes</h3>\\n      <span class=\\"objectives-subtitle\\">By the end of this lesson, you will be able to:</span>\\n    </div>\\n    <span class=\\"objectives-count-badge\\">5 CORE OUTCOMES</span>\\n  </div>\\n  <ul class=\\"learning-objectives-list\\">\\n    <li class=\\"learning-objective-item\\">\\n      <span class=\\"objective-num-badge\\">1</span>\\n      <span class=\\"objective-text\\">Understand why Behavior Trees replaced Finite State Machines in modern autonomous systems.</span>\\n    </li>\\n    <li class=\\"learning-objective-item\\">\\n      <span class=\\"objective-num-badge\\">2</span>\\n      <span class=\\"objective-text\\">Master the core BT node primitives: Action, Condition, Sequence, and Fallback.</span>\\n    </li>\\n    <li class=\\"learning-objective-item\\">\\n      <span class=\\"objective-num-badge\\">3</span>\\n      <span class=\\"objective-text\\">Configure the <strong>Recovery Behavior Server</strong> (Spin, BackUp, Wait, and Costmap Clearing).</span>\\n    </li>\\n    <li class=\\"learning-objective-item\\">\\n      <span class=\\"objective-num-badge\\">4</span>\\n      <span class=\\"objective-text\\">Master ROS 2 <strong>Lifecycle Management</strong> (<code class=\\"inline-code\\">Unconfigured -&gt; Inactive -&gt; Active</code>).</span>\\n    </li>\\n    <li class=\\"learning-objective-item\\">\\n      <span class=\\"objective-num-badge\\">5</span>\\n      <span class=\\"objective-text\\">Visualize and audit behavior trees in real time.</span>\\n    </li>\\n  </ul>\\n</div>\\n\\n<h2 id=\\"2-why-behavior-trees-over-state-machines\\">2. Why Behavior Trees Over State Machines?</h2>\\n<div class=\\"table-responsive\\"><table>\\n<thead>\\n<tr>\\n<th>Finite State Machine (FSM)</th>\\n<th>Behavior Tree (BT)</th>\\n</tr>\\n</thead>\\n<tbody>\\n<tr>\\n<td>N² possible transition arrows</td>\\n<td>Highly modular sub-trees</td>\\n</tr>\\n<tr>\\n<td>High risk of unhandled edge cases</td>\\n<td>Composable and readable</td>\\n</tr>\\n<tr>\\n<td>Difficult to add new behaviors</td>\\n<td>Reactive tick-based execution</td>\\n</tr>\\n</tbody>\\n</table></div>\\n<p>A Behavior Tree executes by sending periodic <strong>Ticks</strong> from the root downward. Each node returns one of three statuses:</p>\\n<ul>\\n<li><code class=\\"inline-code\\">SUCCESS</code>: The action completed successfully.</li>\\n<li><code class=\\"inline-code\\">FAILURE</code>: The action failed (e.g. planner found no path).</li>\\n<li><code class=\\"inline-code\\">RUNNING</code>: The action is currently in progress (e.g. robot is moving).</li>\\n</ul>\\n<hr class=\\"divider\\">\\n<h2 id=\\"3-the-recovery-sub-tree-pipeline\\">3. The Recovery Sub-Tree Pipeline &amp; Behavior Tree Execution</h2>\\n\\n<p><img src=\\"assets/images/nav2_behavior_tree_animation.svg\\" alt=\\"Animated Nav2 Behavior Tree Reactive Recovery Pipeline\\" class=\\"lesson-image\\" loading=\\"lazy\\" /></p>\\n\\n<p>\\n  When an autonomous mobile robot encounters an unexpected obstacle (such as a forklift crossing an aisle or dynamic personnel), local controllers can get trapped in local minima or find no valid collision-free velocity arcs. Instead of crashing or terminating missions, Nav2 uses <strong>Behavior Trees</strong> to orchestrate an escalating recovery hierarchy.\\n</p>\\n\\n<div class=\\"alert-callout alert-warning\\" style=\\"margin: 1.75rem 0;\\">\\n  <div class=\\"alert-icon\\">🔄</div>\\n  <div class=\\"alert-body\\">\\n    <strong>Observation Note: Live Nav2 Recovery Cascades:</strong><br>\\n    When an unexpected obstacle blocks a warehouse corridor, observe Nav2's Behavior Tree trigger sequential recovery actions in your terminal:<br>\\n    <code>[WARN] [controller_server]: Path blocked! Triggering ClearEntireCostmap recovery...</code><br>\\n    <code>[WARN] [bt_navigator]: Costmap clear failed to free path. Executing 360-degree clearing spin...</code><br>\\n    <code>[WARN] [bt_navigator]: Executing 0.3m reverse backup maneuver... Path found! Resuming mission.</code>\\n  </div>\\n</div>\\n\\n<div class=\\"code-breakdown-card\\" style=\\"margin-top: 1.5rem; margin-bottom: 1.5rem;\\">\\n  <h4 class=\\"code-breakdown-title\\">🔬 Behavior Tree Node Semantics &amp; Recovery Escalation</h4>\\n  <p class=\\"code-breakdown-intro\\">Key execution mechanics of the Nav2 BT Navigator engine:</p>\\n  <ul class=\\"code-breakdown-list\\">\\n    <li class=\\"code-breakdown-item\\">\\n      <strong>100 Hz Tick Propagation:</strong> The root node sends periodic signals (<em>Ticks</em>) down the tree. Execution flows from left to right across child branches. Nodes return <code class=\\"inline-code\\">SUCCESS</code>, <code class=\\"inline-code\\">RUNNING</code>, or <code class=\\"inline-code\\">FAILURE</code>.\\n    </li>\\n    <li class=\\"code-breakdown-item\\">\\n      <strong>Control Nodes: Sequence vs. Fallback:</strong>\\n      <ul style=\\"margin: 0.5rem 0 0.5rem 1.25rem; font-size: 0.88rem; color: var(--text-secondary); line-height: 1.5;\\">\\n        <li><strong>Sequence (&rarr;):</strong> Logical AND. Executes children in order; returns FAILURE if any child fails. Used to chain Planner &rarr; Controller.</li>\\n        <li><strong>Fallback / Selector (?):</strong> Logical OR. Executes children in order; succeeds as soon as one child succeeds. Used as the recovery bridge: when navigation fails, control instantly shifts to the recovery branch.</li>\\n      </ul>\\n    </li>\\n    <li class=\\"code-breakdown-item\\">\\n      <strong>The 4-Stage Recovery Escalation Protocol:</strong>\\n      <ul style=\\"margin: 0.5rem 0 0.5rem 1.25rem; font-size: 0.88rem; color: var(--text-secondary); line-height: 1.5;\\">\\n        <li><strong>Stage 1 (ClearCostmap):</strong> Clears temporary sensor ghost reflections from the local costmap.</li>\\n        <li><strong>Stage 2 (BackUp):</strong> Reverses the robot backward by 0.30 meters to escape tight confined spaces.</li>\\n        <li><strong>Stage 3 (Spin):</strong> Rotates the vehicle 360&deg; in place to sweep 2D LiDAR rays and repopulate surrounding obstacles.</li>\\n        <li><strong>Stage 4 (Wait):</strong> Pauses for 5.0 seconds allowing transient dynamic obstacles (e.g. human workers) to clear the aisle.</li>\\n      </ul>\\n    </li>\\n  </ul>\\n</div>\\n\\n<p><img src=\\"assets/images/nav2_recovery_behavior_tree.svg\\" alt=\\"Nav2 Behavior Tree: Reactive Recovery Fallback Pipeline\\" class=\\"lesson-image\\" loading=\\"lazy\\" /></p>\\n<hr class=\\"divider\\">\\n<h2 id=\\"4-the-ros-2-lifecycle-state-machine\\">4. The ROS 2 Lifecycle State Machine</h2>\\n<p>Every major node in Nav2 (Planner, Controller, Recoveries, Costmaps) is a <strong>Managed Lifecycle Node</strong>:</p>\\n<p><img src=\\"assets/images/lifecycle_state_machine.svg\\" alt=\\"ROS 2 Managed Lifecycle Node\\" class=\\"lesson-image\\" loading=\\"lazy\\" /></p>\\n<h3 id=\\"why-lifecycle-nodes-are-crucial\\">Why Lifecycle Nodes are Crucial:</h3>\\n<p>In ROS 1, nodes started operating immediately on launch. If a path planner launched before the map server was finished loading, the robot would crash.<br>\\nIn ROS 2, the <strong><code class=\\"inline-code\\">lifecycle_manager</code></strong> guarantees that all nodes are configured, memory is allocated, and topics are connected before any node enters the <code class=\\"inline-code\\">Active</code> state!</p>\\n<hr class=\\"divider\\">\\n<h2 id=\\"5-inspecting-lifecycle-states-with-the-cli\\">5. Inspecting Lifecycle States with the CLI</h2>\\n<p><div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\"># 1. List all managed lifecycle nodes\\nros2 lifecycle nodes\\n\\n# 2. Query the lifecycle state of the controller server\\nros2 lifecycle get /controller_server\\n# Output: active [3]\\n\\n# 3. Manually transition a node state for diagnostics\\nros2 lifecycle set /controller_server deactivate\\nros2 lifecycle set /controller_server activate\\n</code></pre>\\n</div>\\n</p>\\n<hr class=\\"divider\\">\\n<hr class=\\"divider\\">\\n<h2 id=\\"6-hands-on-student-challenge\\">6. Hands-on Student Challenge: Nav2 Recovery Behavior Supervisor & Lifecycle State Machine</h2>\\n<p>Construct a Behavior Tree & Recovery Behavior Supervisor node that monitors and manages Nav2 recovery pipelines (Spin, BackUp, Wait).</p>\\n\\n<div class=\\"alert alert-tip\\">\\n  <div class=\\"alert-title\\">🎯 Mission Requirements</div>\\n  <ol>\\n    <li><strong>TODO 1:</strong> Initialize lifecycle states: <code class=\\"inline-code\\">NAVIGATING</code>, <code class=\\"inline-code\\">RECOVERY_SPIN</code>, <code class=\\"inline-code\\">RECOVERY_BACKUP</code>, <code class=\\"inline-code\\">RECOVERY_WAIT</code>.</li>\\n    <li><strong>TODO 2:</strong> Create a 1.0 Hz timer that simulates obstacle encounters and recovery activations.</li>\\n    <li><strong>TODO 3:</strong> Advance state machine through recovery levels in correct operational order.</li>\\n    <li><strong>TODO 4:</strong> Log recovery events and emit warnings.</li>\\n  </ol>\\n</div>\\n\\n\\n<div class=\\"alert alert-info alert-briefing\\">\\n  <div class=\\"alert-icon\\">🌳</div>\\n  <div class=\\"alert-content\\">\\n    <div class=\\"alert-title\\">Robotics Flight Operations Mission Briefing: Nav2 Behavior Tree &amp; Recovery Behavior Supervisor</div>\\n    <div class=\\"alert-body\\">\\n      <strong>Physical AMR Context &amp; Operational Challenge:</strong><br>\\n      In an active warehouse, paths get blocked: workers leave carts in aisles, roll doors close unexpectedly, or GPS/localization drifts. A naive robot would simply give up and halt. A commercial AMR must execute systematic recovery behaviors: clear costmaps to remove phantom obstacles, spin 360 degrees to relocalize, or back up 0.5 meters to find clear space.\\n      <br><br>\\n      <strong>Architectural Role &amp; Why This Mechanism:</strong><br>\\n      Nav2 orchestrates navigation using <strong>Behavior Trees (BTs)</strong> rather than brittle finite state machines. Behavior Tree control nodes (Fallbacks, Sequences, Reactive Sequences) tick condition and action nodes periodically. If navigation fails, a Fallback node automatically escalates through a recovery pipeline without requiring custom state code.\\n      <br><br>\\n      <strong>Flight Objective &amp; Behavioral Outcome:</strong><br>\\n      Construct the <code>RecoveryMonitor</code> node. Track Nav2 Behavior Tree execution ticks, identify path planning stalls, detect when recovery actions (Clear Costmap, Spin, Back Up) trigger, and verify that managed lifecycle nodes remain in the ACTIVE operational state.\\n    </div>\\n  </div>\\n</div>\\n\\n<h3 id=\\"61-starter-template\\">6.1 Starter Template: <code class=\\"inline-code\\">m04_l22_task_recovery_monitor.py</code></h3>\\n<p>Copy the starter template from the reference workspace into your active student workspace:</p>\\n<div class=\\"code-container\\" data-language=\\"bash\\">\\n  <div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n  <pre><code class=\\"language-bash\\">cp ~/ros2_ws_reference/src/nexus_amr_basics/nexus_amr_basics/m04_l22_task_recovery_monitor.py ~/ros2_ws/src/nexus_amr_basics/nexus_amr_basics/</code></pre>\\n</div>\\n<p>Open the copied file in your editor and complete the marked <code class=\\"inline-code\\">TODO</code> targets:</p>\\n\\n<div class=\\"code-container\\" data-language=\\"python\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">python</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-python\\">#!/usr/bin/env python3\\n&quot;&quot;&quot;\\n================================================================================\\nNexus AMR Learning Hub - Level 1: Module 4 (Bonus) / Lesson 22 Task\\nPackage: nexus_amr_basics\\nTask:    m04_l22_task_recovery_monitor.py (alias: task_recovery_monitor)\\n================================================================================\\n\\nEXERCISE OVERVIEW:\\n------------------\\nYour mission is to construct a Behavior Tree &amp; Recovery Behavior Supervisor node\\nthat simulates and monitors Nav2 recovery pipelines (Spin, BackUp, Wait).\\n\\nOBJECTIVES:\\n-----------\\n1. TODO 1: Initialize states: &#x27;NAVIGATING&#x27;, &#x27;RECOVERY_SPIN&#x27;, &#x27;RECOVERY_BACKUP&#x27;, &#x27;RECOVERY_WAIT&#x27;.\\n2. TODO 2: Create a 1.0 Hz timer that executes state transitions when simulated\\n   stuck conditions occur (e.g., after 5 ticks of navigation).\\n3. TODO 3: In \`step_lifecycle\`, cycle through Recovery Behaviors in correct priority:\\n   NAVIGATING -&gt; RECOVERY_SPIN -&gt; RECOVERY_BACKUP -&gt; RECOVERY_WAIT -&gt; ABORT.\\n4. TODO 4: Log colorized state transitions and emit recovery warnings.\\n================================================================================\\n&quot;&quot;&quot;\\n\\nimport rclpy\\nfrom rclpy.node import Node\\nfrom rclpy.executors import ExternalShutdownException\\n\\n\\nclass Nav2RecoverySupervisor(Node):\\n\\n    def __init__(self):\\n        super().__init__(&#x27;nav2_recovery_supervisor&#x27;)\\n\\n        # ======================================================================\\n        # TODO 1: Initialize lifecycle and recovery states\\n        # - Hint: Initialize an initial state string attribute and a tick counter integer.\\n        # ======================================================================\\n        # ---&gt; YOUR CODE HERE &lt;---\\n\\n        self.timer = self.create_timer(1.0, self.step_lifecycle)\\n        self.get_logger().info(&#x27;Nav2RecoverySupervisor initialized in state: NAVIGATING.&#x27;)\\n\\n    def step_lifecycle(self):\\n        # ======================================================================\\n        # TODO 2 &amp; 3: Advance state machine\\n        # - Hint: Increment the tick counter. Advance the state sequentially through the standard recovery sequence (NAVIGATING -&gt; RECOVERY_SPIN -&gt; RECOVERY_BACKUP -&gt; RECOVERY_WAIT -&gt; NAVIGATING).\\n        # ======================================================================\\n        # ---&gt; YOUR CODE HERE &lt;---\\n\\n        # ======================================================================\\n        # TODO 4: Log state transition\\n        # ======================================================================\\n        # ---&gt; YOUR CODE HERE &lt;---\\n        pass\\n\\n\\ndef main(args=None):\\n    rclpy.init(args=args)\\n    node = Nav2RecoverySupervisor()\\n\\n    try:\\n        rclpy.spin(node)\\n    except (KeyboardInterrupt, ExternalShutdownException):\\n        pass\\n    finally:\\n        node.destroy_node()\\n        if rclpy.ok():\\n            rclpy.shutdown()\\n\\n\\nif __name__ == &#x27;__main__&#x27;:\\n    main()\\n</code></pre>\\n</div>\\n\\n<h3 id=\\"62-verification-steps\\">6.2 Verification Steps &amp; Expected Terminal Output</h3>\\n<p>Run your node or test command and observe the output:</p>\\n<div class=\\"code-container\\" data-language=\\"bash\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">bash</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-bash\\">ros2 run nexus_amr_basics recovery_monitor</code></pre>\\n</div>\\n\\n<p><em>Expected Terminal Output:</em></p>\\n<div class=\\"code-container\\" data-language=\\"text\\">\\n<div class=\\"code-header\\"><span class=\\"code-lang-tag\\">text</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n<pre><code class=\\"language-text\\">[INFO] [nav2_recovery_supervisor]: Nav2RecoverySupervisor active in state: NAVIGATING.\\n[INFO] [nav2_recovery_supervisor]: [NAV2 BT STATE: NAVIGATING] Mission execution nominal | Tick: 1\\n[WARN] [nav2_recovery_supervisor]: [NAV2 RECOVERY TRIGGER] Local planner stuck! Initiating 360-degree clearing spin...\\n[WARN] [nav2_recovery_supervisor]: [NAV2 RECOVERY TRIGGER] Path obstructed! Initiating 0.3m reverse backup maneuver...\\n[INFO] [nav2_recovery_supervisor]: [NAV2 RECOVERY RESOLVED] Waypoint path clear! Resuming primary navigation.</code></pre>\\n</div>\\n\\n<details class=\\"reference-solution-dropdown\\">\\n  <summary class=\\"solution-summary-btn\\">\\n    <span>🔍 View Reference Solution (<code class=\\"inline-code\\">m04_l22_solution_recovery_monitor.py</code>)</span>\\n  </summary>\\n  <div class=\\"solution-body\\">\\n    <p>Reference file: <code class=\\"inline-code\\">ros2_ws_reference/src/nexus_amr_basics/nexus_amr_basics/m04_l22_solution_recovery_monitor.py</code></p>\\n    <div class=\\"code-container\\" data-language=\\"python\\">\\n      <div class=\\"code-header\\"><span class=\\"code-lang-tag\\">python</span><button class=\\"copy-code-btn\\">📋 Copy</button></div>\\n      <pre><code class=\\"language-python\\">#!/usr/bin/env python3\\n&quot;&quot;&quot;\\n================================================================================\\nNexus AMR Learning Hub - Level 1: Module 4 (Bonus) / Lesson 22 Solution\\nPackage: nexus_amr_basics\\nTask:    m04_l22_solution_recovery_monitor.py (alias: recovery_monitor)\\n================================================================================\\n&quot;&quot;&quot;\\n\\nimport rclpy\\nfrom rclpy.node import Node\\nfrom rclpy.executors import ExternalShutdownException\\n\\n\\nclass Nav2RecoverySupervisor(Node):\\n\\n    def __init__(self):\\n        super().__init__(&#x27;nav2_recovery_supervisor&#x27;)\\n\\n        # Step 1: Initialize states\\n        self.state = &#x27;NAVIGATING&#x27;\\n        self.tick_count = 0\\n\\n        # Step 2: 1.0 Hz periodic state execution\\n        self.timer = self.create_timer(1.0, self.step_lifecycle)\\n        self.get_logger().info(&#x27;Nav2RecoverySupervisor active in state: NAVIGATING.&#x27;)\\n\\n    def step_lifecycle(self):\\n        self.tick_count += 1\\n\\n        # Step 3 &amp; 4: Manage Recovery State Machine\\n        if self.tick_count == 3:\\n            self.state = &#x27;RECOVERY_SPIN&#x27;\\n            self.get_logger().warn(\\n                &#x27;[NAV2 RECOVERY TRIGGER] Local planner stuck! Initiating 360-degree clearing spin...&#x27;\\n            )\\n        elif self.tick_count == 5:\\n            self.state = &#x27;RECOVERY_BACKUP&#x27;\\n            self.get_logger().warn(\\n                &#x27;[NAV2 RECOVERY TRIGGER] Path obstructed! Initiating 0.3m reverse backup maneuver...&#x27;\\n            )\\n        elif self.tick_count == 7:\\n            self.state = &#x27;RECOVERY_WAIT&#x27;\\n            self.get_logger().warn(\\n                &#x27;[NAV2 RECOVERY TRIGGER] Still unresolvable. Entering 3.0s sensor clearance pause...&#x27;\\n            )\\n        elif self.tick_count &gt;= 9:\\n            self.state = &#x27;NAVIGATING&#x27;\\n            self.tick_count = 0\\n            self.get_logger().info(\\n                &#x27;[NAV2 RECOVERY RESOLVED] Waypoint path clear! Resuming primary navigation.&#x27;\\n            )\\n        else:\\n            self.get_logger().info(\\n                f&#x27;[NAV2 BT STATE: {self.state}] Mission execution nominal | Tick: {self.tick_count}&#x27;\\n            )\\n\\n\\ndef main(args=None):\\n    rclpy.init(args=args)\\n    node = Nav2RecoverySupervisor()\\n\\n    try:\\n        rclpy.spin(node)\\n    except (KeyboardInterrupt, ExternalShutdownException):\\n        pass\\n    finally:\\n        node.destroy_node()\\n        if rclpy.ok():\\n            rclpy.shutdown()\\n\\n\\nif __name__ == &#x27;__main__&#x27;:\\n    main()\\n</code></pre>\\n    </div>\\n  </div>\\n</details>\\n\\n<div class=\\"code-breakdown-card\\">\\n  <h4 class=\\"code-breakdown-title\\">🔬 Core Code Deep Dive &amp; Operational Breakdown: RecoveryMonitor Solution Breakdown</h4>\\n  <p class=\\"code-breakdown-intro\\">Key takeaways from Nav2 Behavior Tree & Recovery supervision:</p>\\n  <ul class=\\"code-breakdown-list\\">\\n    <li class=\\"code-breakdown-item\\"><strong>BT Execution Semantics:</strong> Behavior Trees execute by ticking root nodes at regular intervals (10 Hz). Control nodes evaluate child statuses: <code>SUCCESS</code>, <code>FAILURE</code>, or <code>RUNNING</code>.</li>\\n    <li class=\\"code-breakdown-item\\"><strong>Recovery Pipeline Escalation:</strong> When the path planner returns <code>FAILURE</code>, the BT Fallback node triggers recovery actions in ordered sequence: 1) Clear entire local costmap; 2) Spin in place 45 degrees; 3) Back up 0.5 meters. If all fail, the mission aborts safely.</li>\\n    <li class=\\"code-breakdown-item\\"><strong>Managed Lifecycle Node Auditing:</strong> Nav2 nodes inherit from <code>rclcpp_lifecycle::LifecycleNode</code>. If an unexpected fault occurs, the node transitions to <code>UNCONFIGURED</code> or <code>ERROR</code>, which the supervisor detects via lifecycle query services.</li>\\n  </ul>\\n</div>\\n\\n\\n<div class=\\"asset-handoff-card\\" style=\\"margin: 1.75rem 0 1rem 0; padding: 1.15rem 1.4rem; border-radius: 10px; background: rgba(16, 185, 129, 0.06); border: 1px solid rgba(16, 185, 129, 0.25); border-left: 4px solid #10b981;\\">\\n  <div style=\\"display: flex; align-items: center; gap: 0.5rem; margin-bottom: 0.5rem;\\">\\n    <span style=\\"font-size: 1.1rem;\\">📦</span>\\n    <strong style=\\"font-size: 0.95rem; color: #10b981; text-transform: uppercase; letter-spacing: 0.04em;\\">Asset Handoff &amp; Next Lesson Pipeline Bridge</strong>\\n  </div>\\n  <p style=\\"margin: 0 0 0.65rem 0; font-size: 0.88rem; color: var(--text-primary); line-height: 1.6;\\">\\n    The self-healing recovery behavior tree prevents mission aborts when obstacles or personnel temporarily obstruct warehouse corridors.\\n  </p>\\n  <div style=\\"display: flex; flex-wrap: wrap; gap: 0.75rem; font-size: 0.82rem; font-family: var(--font-mono);\\">\\n    <span style=\\"background: var(--bg-surface); border: 1px solid var(--border-color); padding: 0.25rem 0.6rem; border-radius: 5px; color: var(--text-primary);\\">\\n      📁 <strong>Produced Artifact:</strong> <code>ros2_ws_reference/src/nexus_amr_navigation/config/nav2_params.yaml & m04_l22_task_recovery_monitor.py</code>\\n    </span>\\n    <span style=\\"background: var(--bg-surface); border: 1px solid var(--border-color); padding: 0.25rem 0.6rem; border-radius: 5px; color: var(--text-primary);\\">\\n      ➡️ <strong>Ingested By:</strong> Workshop Graduation (3-Day Autonomous AMR Navigation Workshop Complete)\\n    </span>\\n  </div>\\n</div>\\n\\n","quizzes":[{"id":"q_l1_24_1","prompt":"What are the core control node types in a Nav2 Behavior Tree XML definition?","options":["Sequence, Fallback (Selector), and Parallel","If, Else, While","Pub, Sub, Service","Try, Catch, Finally"],"correct":0,"explanation":"Behavior Trees use Control Nodes (Sequence, Fallback/Selector, Parallel) to evaluate Action and Condition leaf nodes, enabling deterministic navigation failure recovery."}],"has_quiz":true,"next_id":null,"prev_id":"lesson_20","subtopics":[{"id":"1-overview-learning-objectives","title":"1. Overview &amp; Learning Objectives"},{"id":"2-why-behavior-trees-over-state-machines","title":"2. Why Behavior Trees Over State Machines?"},{"id":"3-the-recovery-sub-tree-pipeline","title":"3. The Recovery Sub-Tree Pipeline &amp; Behavior Tree Execution"},{"id":"4-the-ros-2-lifecycle-state-machine","title":"4. The ROS 2 Lifecycle State Machine"},{"id":"5-inspecting-lifecycle-states-with-the-cli","title":"5. Inspecting Lifecycle States with the CLI"},{"id":"6-hands-on-student-challenge","title":"6. Hands-on Student Challenge: Nav2 Recovery Behavior Supervisor & Lifecycle State Machine"}]}]`),t={total_lessons:21,modules:e,lessons:n};export{t as l};
